        E("dsh-comfyui-1", "dsh-comfyui", "让 DeepSeek Harness 的 Agent 直接驱动本地或远程 ComfyUI：comfyui_run / comfyui_object_info / comfyui_workflow 工具生成与编辑图像、视频，附带工作流库（图工作流提取：按分量 / 主流程 / 整体）、加载区分辨率自动匹", "image", 159, "vision"),
        E("ark-plan-api", "ark-plan-api", "在 DSH 原生模型选择器中注册方舟 Agent Plan、Coding Plan 与后付费模型路由。", "ai", 149, "model"),
