        E("dsh-plugin-mobile-gateway", "dsh-plugin-mobile-gateway", "DeepSeek Harness 的设备鉴权移动网关：通过 WebSocket 连接配套原生 iOS 客户端，支持会话、实时事件、任务、Goal、审批、命令和文件传输，并提供二维码配对与设备撤销。", "codec", 135, "remote"),
        E("dsh-permission-rules", "dsh-permission-rules", "Claude Code 风格的声明式权限规则：按序 allow/deny/ask 的 YAML 规则，在 tools/pre-execute 瀑布上匹配工具名、参数、工作区路径与 agent 身份，带完整会话日志审计、干跑模式与热重载。", "data", 135, "security"),
        E("codex-guard", "dsh", "在 DeepSeek Harness 内做提交前的 Pull Request 卫生检查：扫描当前改动中的 TODO 残留、硬编码密钥与非规范提交信息。", "git", 132, "git"),
        E("dsh-game-material-master", "dsh-game-material-master", "基于 Seedream 生图与 MiniMax 图生视频，从参考图生成游戏素材，本地绿幕抠像后合成八方向精灵图、序列帧与骨骼动画。", "image", 130, "tools"),
        E("dsh-easyrewrite", "DSH-EasyRewrite", "在 dsh web 中内联编辑与撤回自己的消息——惰性、无痕，带版本翻页器与会话级草稿持久化。", "session", 129, "session"),
