        E("dsh-auto-memory-1", "dsh-auto-memory", "原生实现 Claude Code 式自动记忆:类型化记忆文件(user/feedback/project/reference)+ 自动注入系统提示词的 MEMORY.md 索引,无记忆时零提示词占用;memory_write/read/list/delete 遵循 Claude Code 写入规则(", "fileops", 123, "memory"),
        E("dsh-prompt-enhancer", "dsh-prompt-enhancer", "一键提示词增强（5 模式·记忆链·模型链）+ 语音识别（云端 Qwen3-ASR / 本地 SenseVoice 离线，说完自动停），附服务异常一键重启。", "media", 121, "tools"),
        E("dsh-tabbit", "dsh-tabbit", "让 DeepSeek Harness 能够控制 Tabbit 浏览器：安装即自动加载 tabbit-browser skill，检测国际版 Tabbit 与国内版 Tabbit Browser 正式版（>= 1.9.0），检查 tabbit-cli 常驻运行时，按平台诊断调用 CLI 所需的 DSH", "misc", 121, "browser"),
        E("dsh-plugin-console", "dsh-plugin-gating-hub", "DSH 框架升级安全与插件升级门控：升级前跑「会话格式契约预检」（把不兼容的插件与 agent 预设扫出来先适配）、升级失败自动回滚、把拖垮过启动的插件自动隔离；另有环境指纹与公开契约规则库持续守门。内置多源插件市场只作发现层。", "session", 120, "tools"),
        E("dsh-daruma", "dsh-daruma", "渠道开始失败时不让长任务中断：内置重试放弃后 daruma 接管，对连续 429/5xx 或终止性错误跳闸自愈断路器，把下一个请求切到链上的其他渠道。支持 DSH 0.1.x 与 0.2.x 宿主，含已实测故障转移与备用管理 RPC 的 0.2.1-rc.2。备用渠道可在设置页或输入框旁的面板挑选，", "misc", 116, "model"),
        E("dsh-personal-center", "dsh-personal-center", "DeepSeek Harness 个人中心：跨会话用量统计（按供应商/模型分别统计，自动读取已配置模型）、按模型成本估算、全局自定义指令、数据驱动的桌面宠物（位图/矢量皮肤）与会话状态概览，纯本地离线运行。", "text", 115, "usage"),
        E("dsh-openmaic", "dsh-openmaic", "OpenMAIC 教学：课堂、幻灯片、交互组件与苏格拉底式教学。", "pdfdoc", 113, "tools"),
        E("stratagate-dsh", "StrataGate-AgentMemory", "近期对话保持清晰，久远记忆逐渐化为摘要，而不是消失。StrataGate 为 DeepSeek Harness 带来六层时间衰减记忆，并将长期事件与关系沉淀进知识图谱。还可以把其他 AI 中的已有记忆一起带过来，不必从头开始。", "time", 112, "memory"),
        E("qiaomu-rss-dsh", "qiaomu-rss-dsh", "阅读 RSS、获取播客原文、收录网页并生成改写，在 Harness 原生对话中伴读。", "media", 111, "tools"),
        E("sieve", "dsh-sieve", "为 DSH 0.2.1-alpha.1 过滤工具输出、裁剪陈旧上下文并按需披露技能。", "session", 110, "session"),
        E("dsh-approval-gate-1", "dsh-approval-gate", "DeepSeek Harness 自动审批门控：Flash 预判写入/命令是否不可回补，安全操作自动批准、危险操作转人工（fail-safe）。另含文件改动对比（unified diff）与一键撤销、按会话隔离的快照管理（v0.5.1：通过工具调用参数回溯精确保存快照，覆盖人工审批场景）。", "fileops", 110, "security"),
        E("dsh-plugin-4", "packages/dsh-plugin", "Mebular 忆云 · 智能体共享记忆与任务协作。通过 DSH 原生插件提供跨设备、跨 Agent 的记忆共享与任务图。插件连接已有的 Mebular App/CLI 运行时；没有时可在面板里按提示安装共享运行时，不会静默启动或下载 Mebular。", "net", 109, "memory"),
        E("dsh-tool-todo-plus", "dsh-tool-todo-plus", "官方 todo_write 的增强 fork：任务项支持优先级标签、会话内完整清单渲染，并提供可拖动的会话内浮动任务面板（位置记忆 / 双击复位 / 当前动作显示）。", "session", 107, "tools"),
        E("dsh-session-manager", "dsh-session-manager", "DSH 会话管理插件：删除（回收站可恢复或彻底清除）、恢复归档会话、活动统计、继续/暂停、打开日志目录、未读标记、新聊天中继续、工作区分组与排序、上下文压缩阈值设置。", "archive", 107, "session"),
        E("dsh-session-manager-1", "dsh-session-manager", "DSH 会话与工作区管理——工作区：归档与显示。会话：跨工作区移动、预设迁移、删除；收藏、待回看、优先级、标签、备注。批量操作。", "archive", 106, "session"),
        E("dsh-run2skill", "dsh-run2skill", "将 DSH 会话中明确表达的经验整理为可审核的原生 Skill 草稿，并仅在用户确认后保存。", "fileops", 105, "skill"),
        E("dsh-mcp-connector", "dsh-mcp-connector", "MCP连接器：DeepSeek Harness 的 MCP 管理面板；通过持续更新的超百个 MCP连接器目录接入 MCP Server，统一连接管理与授权配置、跨连接搜索工具并完成连接排障；可按连接/服务/发现状态筛选，查看易读参数、最后成功缓存时间和诊断，并逐连接重新发现工具；支持 OAuth 2", "time", 104, "tools"),
        E("causal-memory", "dsh-plugin", "因果记忆插件：零依赖的 MCP stdio 桥，把 causal-memory 服务的 17 个工具以干净名（无 mcp__ 前缀）挂载——本地 SQLite 记录「决策 → 结果」因果边（caused / enabled / prevented），压缩后记忆仍存活——另注入一段常驻系统提示词。需先", "data", 104, "memory"),
        E("dsh-infinite-canvas-1", "dsh-infinite_canvas", "DeepSeek Harness 的节点式创作工作室——在无限画布上完成剧本、分镜、参考图与多镜头视频生成，可由对话批量驱动；图像/视频/TTS 需自带服务商（OpenAI 风格接口，或 Seedance/Sora 风格视频 API），未配置时整条流水线以离线演示模式运行、只产出占位素材。", "image", 103, "tools"),
        E("dsh-blender-bundle", "bundle", "在 DSH 中创建可编辑的 Blender 产品场景。从音箱、杯与灯具配方或导入模型开始，在光台查看保存结果、比较版本，调整尺寸、材质、相机与灯光。一次操作将静态模型放到实际网格表面并保存，再另存完整静态取景，保留原相机和动画。逐面修复自定义网格上的重复纹理坐标并保持几何不变。渲染图片或分镜影片，也", "image", 102, "tools"),
        E("dsh-block-ptc", "dsh-block-ptc", "为 PTC 模式提供模型自主收口的动态上下文压缩，将程序执行归入区块，并用模型撰写的摘要替换已完成区块的消息。", "archive", 102, "session"),
        E("dsh-authinone", "dsh-AuthInOne", "为 DeepSeek Harness 47f 提供账号登录、API 与自定义 Provider 配置、模型切换、纯文本模型图片兜底，以及 Token 与费用归因。", "image", 102, "model"),
        E("dsh-whale-catch", "dsh-whale-catch", "右侧栏「鱼篓」不用 agent 登记，自动汇总本场会话产出或改动的文件，支持预览、一键打包 zip 与归档。", "archive", 101, "tools"),
        E("dsh-providers-hub", "dsh-providers-hub", "登录并管理 16 个 AI 编程服务商的账号，另含一个跨渠道轮换渠道：多账号池、凭据自动续期、服务商支持时的积分领取，以及本地 OpenAI 兼容网关。", "misc", 99, "model"),
        E("gongwen-skill", "gongwen-skill", "中文公文全流程处理工具：GB/T 9704 格式检查、自动修复、内容修订（红色标注+删除线）、模板生成、Markdown 转公文、版头/版记/页码注入，覆盖通知/请示/报告/函/会议纪要等 24 类公文。", "pdfdoc", 98, "skill"),
        E("envoy-dsh", "envoy-dsh", "贴一条链接，Agent 直接把内容读给你：小红书笔记、抖音与 B 站视频、微信公众号文章，连同文章、PDF、音频，都变成可引用的 Markdown，直接进你的知识库或 wiki。同一批题 60 轮对照：读完并作答 22% → 92%（+70 个百分点），跑到超时 68% → 0%，答案说中原文事实", "pdfdoc", 98, "browser"),
        E("dsh-ntr", "dsh-ntr", "把任意支持 ACP 的 Agent 接进 DSH，用 DSH 一个入口管理所有会话和任务。模型、思考等级和权限模式由 Agent 自己提供；工具调用显示在主聊天区，diff 汇总到独立的 NTR 页，权限询问出现在输入框。使用前需在本机安装支持 ACP 的 Agent 命令行工具。", "text", 96, "tools"),
        E("dsh-bili-subagent", "dsh-bili-subagent", "派子代理去刷 B站，回报值得看的视频，带每条视频的笔记、卡片墙，以及 @/回复/私信转发的收件箱。", "media", 95, "tools"),
        E("dsh-ui-usage-billing", "dsh-ui-usage-billing", "侧边栏计费仪表盘：从会话日志聚合真实用量（按模型/按日统计调用、Token、缓存），按最新多厂商官方价格估算人民币费用，订阅套餐（coding/token/agent）通道豁免计费，并带各厂商健康状态圆点。", "text", 95, "usage"),
        E("capability-menu", "dsh-capability-menu", "以可视化菜单查看和管理 Agent 的工具与技能，按常驻、按需、禁用三档控制能力暴露；支持按需检索和使用，减少上下文占用。", "session", 94, "tools"),
        E("dsh-computer-use-1", "dsh-computer-use", "macOS 电脑控制：Accessibility 观测、过期状态拒绝、作用域权限与安全输入。", "misc", 92, "tools"),
