        E("dsh-imagegen-video", "dsh-imagegen-video", "面向 DSH Web GUI 的 AI 生图与生视频插件：文生图/图生图按渠道配置模型目录，并按模型族适配请求协议（gpt-image、Grok Imagine、Nano Banana、Seedream、GLM-Image、Qwen-Image、MiniMax image-01、DALL-E 3），", "media", 70, "vision"),
        E("dsh-plugin-save-token", "dsh-plugin-save-token", "可逆的上下文瘦身插件：均匀 JSON 数组走 TOON 式无损表格化重编码，管道表按行号抽样保留窗口，90 秒内字节级相同的工具输出跨轮去重；每次替换都要通过双重门（压缩后 ≤72% 字节且估算 token 严格下降），原文落盘并以 `[save-token #id]` 标记，可用 `save_to", "codec", 68, "memory"),
        E("dsh-qoder-connect-1", "dsh-qoder-connect", "通过个人访问令牌将 Qoder（国内版与国际版）接入 DSH，两版各自独立的凭证与模型目录，支持多令牌切换、侧栏额度卡、按模型开关、上下文窗口偏好与每日自动签到。", "fileops", 67, "model"),
        E("dsh-deepread", "dsh-deepread", "五种模式精读图书与文章（快速/深度/知识地图/费曼/全书），输出观点—证据—数据报告、四档置信度、Mermaid/XMind 思维导图，支持批量对比、预算预检与后台任务进度透明，可导出 MD/MM/HTML。", "misc", 66, "tools"),
        E("dsh-plugin-rea", "dsh-plugin-rea", "第三方适配插件：把上游 REA（逆向一切，github.com/morluto/rea）的 MCP 服务接入 DeepSeek Harness，提供 mcp__rea__* 工具。2.x 自带供给：把 Node、REA CLI、JDK、Ghidra 装到 <DSH_HOME>/plugins/rea", "misc", 66, "tools"),
        E("dsh-computer-use", "dsh-computer-use", "跨平台 Computer Use 插件：虚拟鼠标真人操作（screen_observe / computer_click / type / key / scroll / drag 共 11 个工具），AX 语义树零视觉成本 + GLM-4V-Flash 免费视觉兜底，安全护栏（快照 TTL / 应用", "misc", 65, "tools"),
        E("dsh-fund-research", "dsh-fund-research", "中国公募基金确定性研究报告：采集天天基金/东方财富公开数据，纯函数计算业绩拆解、持仓穿透、风格归因与经理画像，输出带逐数字可溯源快照附录的版本化报告。", "misc", 65, "tools"),
        E("dsh-better-reasoning-effort", "dsh-better-reasoning-effort", "为第三方供应商模型按模型配置思考强度与输入模态：知识库与原始 /models 端点取证融合建议并标注置信度，在官方「模型」页卡片内直接编辑。", "ai", 65, "model"),
        E("dsh-biodsh", "dsh-biodsh", "生信智能体预设，含 17 个 BioDSH 分析技能（单细胞、bulk RNA-seq、生存分析、回归、方差分析）、可用 skill_library 工具检索的 2000+ 技能库、按消息自动选技能和按时间/步数的收敛护栏。", "archive", 65, "skill"),
        E("dsh-web-startup-auth", "dsh-web-startup-auth", "替换 dsh web 启动器以允许绑定 0.0.0.0，并以账号密码登录为门槛：签名会话 cookie、/api 路由保护、设置面板认证标签页，以及轮换签名密钥使全部会话失效的重置 CLI。", "text", 65, "security"),
        E("vram-switcher", "vram-switcher", "面向本地 AI 陪伴的 AstrBot/DSH 原生显存协调：LLM、IndexTTS、ComfyUI 轮流用卡，不加代理。", "net", 64, "tools"),
        E("dsh-suite", "plugin-session-export", "把 append-only 会话日志导出为按轨迹来源分组的可读 Markdown 或 HTML。", "pdfdoc", 64, "session"),
        E("tinytitan", "dsh-tinytitan", "把本机 TinyTitan 模型服务接入 Harness：按已安装模型刷新 llm-pi-ai 路由，并挂载一个不做思考的压缩后端。", "archive", 64, "model"),
        E("dsh-plugin-guide", "dsh-plugin-guide", "DSH 插件开发知识库，作为按需加载的 agent 技能随 bundle 安装：官方约束、任务工作流、API 参考与社区踩坑，写插件时让 DSH 自己查。", "ai", 64, "skill"),
        E("unity-plugin", "unity-plugin", "通过官方 unity CLI 在 DSH 中操作 Unity 编辑器：实时场景命令、编辑器内 C# 求值、运行时命令发现，均复用常驻的 unity shell 会话；另有原始 CLI 通道用于建工程、跑测试与构建。同时挂载 Unity 官方技能集，以及插件自带的 Unity 工作流与 Asset S", "session", 63, "tools"),
        E("agent-context-editor", "deepseek-harness", "Agent Context Editor 是一个可以手动排除、编辑和选择性压缩 AI 对话上下文的跨 Agent 插件，同时支持搜索、筛选、选择、隐藏、恢复和撤销对话内容，并保留原始 Session。", "archive", 63, "session"),
        E("dsh-chinese-traditional-wisdom-skill", "dsh-chinese-traditional-wisdom-skill", "完整中华传统智慧（玄枢 / XuanShu）技能包，封装为 DeepSeek Harness Cordis 插件：八字、紫微斗数、六爻、梅花易数、奇门遁甲、大六壬、太乙、五运六气、中医体质与风水推算，内置本地确定性引擎与可视化 Dashboard。", "misc", 62, "skill"),
        E("dsh-codegraph", "codegraph", "DSH Web GUI 的 Codegraph 集成：设置 → 插件 中的「Codegraph」卡片提供索引状态、符号搜索、callers/callees/impact 查看与一键 sync/index；托管 codegraph MCP 服务器，并向 system prompt 注入 Codegra", "search", 61, "tools"),
        E("dsh-docker", "docker", "DSH Web GUI 的 Docker 容器面板：本机或 SSH 主机上的容器列表（可选含已停止）、docker inspect 详情、日志、stats 快照、镜像列表与一次性 exec——默认只读（启停删与 exec 均需显式开启权限），可经 tty 插件在面板底部就地打开容器终端。", "devops", 61, "tools"),
        E("dsh-loglens", "loglens", "DSH Web GUI 的日志查询卡片（Elasticsearch / OpenSearch）：一个查询面——按来源方言给查询串与可点例子、字段名补全、筛选芯片、可点柱缩放时间窗的时间分布、把分组的桶点成筛选、带级别染色与堆栈续行标记的结果列表（可选列、可翻页）；Docker 容器日志作为采集来源复", "data", 61, "tools"),
        E("dsh-mcp", "mcp", "DSH Web GUI 的 MCP 服务器配置卡片：增删改查与启用/停用 MCP 服务器（stdio 本地子进程 / streamable-http 远程两种传输），env / headers 值支持 js: 前缀表达式，带状态徽标，保存即热生效。", "sysinfo", 61, "tools"),
        E("dsh-rss", "rss", "DSH 的 RSS/新闻聚合插件：内置渠道库 + awesome-rsshub-routes 精选订阅源目录 + 自定义源（保存时真实抓取校验），每天自动汇总成「今日值得读」Markdown 并注入 systemPrompt；带 Web 设置卡片与侧边栏阅读弹窗。", "pdfdoc", 61, "tools"),
        E("dsh-search", "search", "DSH Web GUI 的全局搜索插件：侧边栏全局搜索框全文搜索历史会话（走 sessionQuery 全文索引，未启用时降级为逐会话扫描）与设置面板，关键词高亮，点击直达会话或对应设置卡片。", "search", 61, "session"),
        E("dsh-workbuddy-trae-qoder-connect", "dsh-workbuddy-trae-qoder-connect", "一个 DSH 插件把 WorkBuddy（个人多账号、企业版与国际版 WorkBuddy AI）、Qoder CN、Trae CN 的模型聚合进同一个模型选择器，共用一套对话历史，支持积分倍率、逐模型思考档位、国际版上游声明的最大上下文窗口，并在渠道有签到活动时自动领取。", "session", 61, "model"),
        E("multivibe", "dsh-multivibe", "把 DSH 接到 MultiVibe 网关，并可查看可用模型与连接状态。", "ai", 61, "model"),
        E("dsh-quant", "dsh-quant", "面向 DeepSeek Harness 的量化研发工具箱，59 个工具覆盖行情、指标、因子评价、滚动样本外机器学习验证、风险（VaR/CVaR/回撤/Beta 与 Kupiec POF）、期权、债券、FICC 和基金模拟，并提供端到端 PDAT→PET 研究管线。", "misc", 60, "tools"),
        E("workbuddy-to-dsh", "dsh-plugin", "把本机的本地 OpenAI 兼容桥注册成 dsh 原生模型 provider：复用这台机器桌面端已登录的模型，管理桥与其本地控制台进程，并附带 5 个工具、/workbuddy 命令与 9 个标签页的设置面板。需同机已安装并登录该桌面端；桥只监听 127.0.0.1。", "sysinfo", 60, "model"),
        E("dsh-web-search-free-1", "dsh-web-search-free", "把默认的 Web 搜索与抓取通道替换为 Tavily、Exa、Brave 等八个免费搜索引擎，按可配置的顺序依次 fallback。在设置卡片中填写各引擎 Key，并可开关 web_fetch 工具。", "net", 59, "tools"),
        E("dsh-im-gateway", "dsh-im-gateway", "DeepSeek Harness 聚合 IM 网关：通过微信、飞书、Telegram、Discord、QQ、WhatsApp 等 20+ 聊天平台驱动 agent，支持统一会话、远程审批和交互提问。默认放行所有能给机器人发消息的人，需要限制请配置 allowedUserIds。", "session", 59, "remote"),
        E("dsh-zotero", "dsh-zotero", "面向 Agent 研究工作流的 Zotero 插件：搜索文献、查看元数据与笔记、提取与问题相关的证据段落、打开原文 PDF、生成引用与参考文献表。", "pdfdoc", 58, "tools"),
        E("dsh-qa-skills", "qa-skills", "软件测试全流程技能包：10 个技能覆盖需求分析、测试策略、用例编写与审查、E2E（Playwright）与 API 自动化、探索式测试、回归范围与 Bug 分析，共享知识库提供格式规范、风险模型与 Schema 校验脚本。", "data", 58, "skill"),
        E("dsh-token-pet", "dsh-token-pet", "DSH 悬浮桌面用量小宠物：用 12 个正式状态动作反馈请求、工具、上下文压缩、归档和提示词增强，展示实时上下文占用、跨会话终身用量账本、服务商/模型统计、小时趋势与近 7/30 日视图；支持深色/浅色主题切换；可选成本估算（默认关闭）与可视化价格表、月预算告警；客户端皮肤 ZIP 导入；JSON/", "data", 58, "usage"),
        E("dsh-drawai", "dsh-drawai", "DSH 侧边栏的可编辑画布，加两个模型工具（diagram_read、diagram_apply），直接读写工作区、载体是原生 .drawio 文件：无损写回让画布读不懂的单元逐字节保留，文件指纹 revision 支撑起对并发编辑的乐观锁。", "fileops", 57, "tools"),
        E("dsh-mech-workbench", "dsh-mech-workbench", "工科与数学题解工作台：九个工具覆盖读题、求解、出图与校核，另附四个随包技能。需要带 numpy 与 Pillow 的 Python。读图、图形校核与公式排版依赖你已配置密钥的视觉模型提供商，图片会发给它；未配置密钥时这些功能报失败，其余工具照常可用。", "pdfdoc", 57, "tools"),
        E("dsh-scholar", "dsh-scholar", "学术助手插件。", "misc", 57, "tools"),
        E("dsh-thinking-effort", "dsh-thinking-effort", "为 DSH 自定义模型配置思考档位和子 agent 默认思考强度。", "ai", 57, "model"),
        E("dsh-aginxbrowser", "dsh-aginxbrowser", "给 DSH agent 的网页访问层：把 JS 渲染或受保护的页面抓成干净 markdown，聚合搜索 14 个引擎，并提供有状态交互会话（点击、输入、滚动、eval、截图），引擎可托管可自部署（Rust 单二进制）。每个会话带直播页 URL，人能实时围观 agent 浏览并用鼠标接管。", "pdfdoc", 56, "browser"),
        E("dsh-confirm-gate", "dsh-confirm-gate", "按轮统计持久化操作，按总数逐级升级：先提醒，再给明确的停止指令，最后请求确认。每次调用都现读会话的沙箱模式，在 read-only 与 workspace-write 下保持沉默。", "text", 55, "security"),
        E("sofagent", "cordis-plugin-sofagent-audit", "面向 AI 编程 agent 的提交时审计 harness——28 条 git diff 规则（密钥泄漏、越界改动、提示注入）、HMAC 签名审计链、快照回滚、完整 MCP 工具面的 MCP server；dsh plugin add 即装。", "git", 55, "security"),
        E("dsh-remote-web", "dsh-remote-web", "手机浏览器远程控制 dsh web，人在哪都能用（免公网 IP）：官方托管中继 4G 即用，也可自建 relay；一条命令安装电脑端 bridge 与设置页「远程控制」面板（云端 / 自建 / 微信机器人三个 tab、账号登录、bridge 启停、反馈）；隧道数据面端到端加密（E2EE：手机↔电脑端", "codec", 54, "remote"),
        E("dsh-data-quality", "dsh-data-quality", "DeepSeek Harness 的数据质量检查：数据画像、清洗与验证流水线，产出结构化报告。", "text", 53, "tools"),
        E("dsh-message-edit", "dsh-message-edit", "基于分支的消息编辑、reroll、重试与版本时间线。", "git", 53, "session"),
        E("dsh-recall-plugin", "dsh-recall-plugin", "消息撤回：在用户消息旁加「撤回」按钮，把对话历史（官方会话 fork）与项目文件（逐消息影子 git 快照）一并回退到该消息发送之前，带差异预览确认面板。", "git", 53, "session"),
        E("dsh-in-hand", "dsh-in-hand", "掌上 DSH（dsh-in-hand）：DeepSeek Harness 的手机端，不用装 App（PWA）。公网与局域网两个入口可随时切换；在手机上读会话、子代理、目标轮次、工作流、后台任务与待审批，和任意会话实时对话（流式回复、工具调用进度、随时停止、切换会话与模型），消息可排队并「立即发送」，", "net", 53, "remote"),
        E("dsh-browser-control", "dsh-browser-control", "通过本地 WebSocket 桥接让 DSH 操控你的真实 Chrome：标签页管理、导航、DOM 快照、页面 JS 求值、点击输入、截图、等待与弹窗处理，默认关闭需在设置中开启。", "image", 53, "browser"),
        E("dsh-douyin-browser-local", "dsh-douyin-agent", "在专用浏览器中按每日时段和额度观看抖音，共享本地人格与兴趣，提供原生设置、自检、用量和观看日报。回复与分享限定所选好友和群聊，群聊仅在被 @ 或叫到设定昵称时回复；公开评论需单独开启。", "ai", 52, "browser"),
