        E("dsh-sessions-insight", "sessions-insight", "按工作目录浏览 Claude Code、DSH 和 Codex 会话日志，查看每轮上下文构成、token 用量、压缩点和费用估算。", "archive", 51, "usage"),
        E("dsh-full-remote", "dsh-full-remote", "远程访问 DeepSeek Harness 且服务端 API 完整：转发时改写 Host/Origin，恢复其他方案必定 403 的 settings.* / credentials.* / host.listDirectory。令牌门、按设备会话、可选首访审批。", "session", 51, "remote"),
        E("dsh-to-figma", "DSH-to-Figma", "让 DSH 用自然语言读取、创建和修改 Figma 设计，支持批量调整图层、组件与变量、截图及素材导出。本地模式不消耗官方 Figma MCP 调用额度。", "image", 50, "tools"),
