        E("dsh-plugin-session-delete", "dsh-plugin-session-delete", "在 Web UI 与桌面客户端中删除 DSH 会话：头部危险按钮 + 会话行菜单项，风险确认弹窗，宿主端点与 agent 工具同步清理会话日志、投影缓存与工作区记账。", "session", 50, "session"),
