        E("dsh-krouter", "DSH-KRouter", "把本地 Obsidian 库当作 Agent 知识库，并用只读 DSH 工具把状态、偏好、纠错、记忆、项目、搜索与建议路由到对应页面。", "search", 48, "memory"),
        E("dsh-knit", "dsh-knit", "把会话工作区里已有的 Markdown 文档、源码、图片与视频列进 DSH 侧边栏，按与当前对话的相关性排序。默认的词法模式用最近几条消息在本地与标题、摘要、正文做带 IDF 加权的匹配（BM25）—— 不调用模型、没有网络出口，内容不出本机。列表来自工作区扫描，而不是「最近打开记录」，所以重启 D", "pdfdoc", 48, "docs"),
        E("dsh-remote-ssh", "dsh-remote-ssh", "类 VSCode Remote-SSH 的 DSH 插件：SSH 连接超算/服务器，内置文件页签直读远程文件、终端页签自动 SSH，远程工作区配单往返合并读与结果缓存，含 12 个会话感知的 remote_ssh_* 模型工具。", "fileops", 48, "remote"),
        E("dsh-ssh-ops", "dsh-ssh-ops", "DSH SSH 运维终端：在主对话中直接指挥已连接的服务器（ssh_connect/ssh_exec/ssh_read/ssh_write/ssh_disconnect），右侧保留可交互的 xterm.js 终端。", "session", 48, "remote"),
        E("dsh-wechat", "dsh-wechat", "将微信私聊消息桥接到 DSH，支持文本、图片、文件、音视频的双向传输，用 slash 命令管理会话、工作区、模型、权限等等，目标是在微信端还原 DSH 的原生体验。", "image", 48, "remote"),
        E("dsh-plugin-writing-guard", "dsh-plugin-writing-guard", "论文写作守卫（中英双语）：去掉 AI 式防御性写作，润色时守住科学证据（数字/引用/主张强度/零结果/scope），并按目标期刊校准写作风格（Journal Profile + Journal Fit）。纯本地正则/统计，零网络零 LLM；提供 writing_rules / writing_aud", "fileops", 46, "tools"),
        E("godot-bridge", "godot-bridge", "DSH↔Godot 引擎运行时控制桥：通过游戏内置 TCP 交互服务器启动并操控运行中的 Godot 4.x——16 个工具（约 130 条运行时命令、场景/UI 检查、GDScript eval、输入模拟、截图、headless 静态操作、项目编辑、导出、脚本编译检查、引擎路径设置），替代 god", "image", 46, "tools"),
        E("dsh-session-workbench", "dsh-session-workbench", "会话工作台：全文搜索历史会话、一键 @引用 召回最多 3 个，并管理会话视图标签栏（显示/隐藏 + 拖拽排序）。", "text", 46, "session"),
        E("dsh-remote-1", "dsh-remote", "为 DeepSeek Harness Web UI 提供安全远程访问：登录门禁、MFA/TOTP、签名会话 Cookie、可选的 admin/user/guest 角色、浏览器内工作区选择和按允许目录限制的远程文件预览。", "fileops", 45, "security"),
        E("dsh-session-delete-11", "dsh-session-delete", "真正删除会话：回收站可还原、归档清理、设置页批量删除。", "archive", 44, "session"),
