        E("dsh-literature", "dsh-literature", "DSH 内置文献库（可选导出到 Zotero）：通过 Unpaywall/arXiv/自定义 URL 模板获取全文 PDF，Crossref 候选式宽松搜索，APA/GB-T 7714/MLA/Chicago 引用生成，侧窗 PDF 阅读器（高亮与笔记），以及注入当前对话的 AI 问答/翻译。", "pdfdoc", 8, "tools"),
        E("dsh-oauth-mcp-client", "dsh-oauth-mcp-client", "面向 Streamable HTTP 服务的 OAuth 2.1 MCP 客户端：在设置页添加连接，通过浏览器登录（PKCE + 动态客户端注册），其工具随即注册进 DSH；令牌存于凭据服务，连接写入 profile。", "fileops", 8, "tools"),
        E("dsh-plugin-chart", "dsh-plugin-chart", "增强 DeepSeek Harness 数据可视化能力，根据用户输入自动选择图表类型并生成图片，支持趋势、比较、占比、关系和流程等可视化场景。", "image", 8, "tools"),
        E("dsh-proxy", "dsh-proxy", "DeepSeek Harness 网络代理设置页：配置全局 HTTP(S) 代理及免代理主机，或为单个 LLM 提供商单独指定代理或直连；保存即生效，无需重启。", "net", 8, "tools"),
        E("dsh-proxy-pro", "dsh-proxy-pro", "把模型请求、web 抓取/搜索与衍生工具统一路由到 Windows 系统代理或自定义地址——幂等内核（读操作不重组分发器）、头部一键开关、按 URL 路由诊断与 NTLM 认证提示。", "net", 8, "tools"),
        E("dsh-ptc-cordis-preset", "dsh-ptc-cordis-preset", "为 DeepSeek Harness 提供的 Agent 预设：在 PTC 编码模式之上叠加自引用 Cordis 工具集（动态插件、运行时检视）与预设编写技能；物化文件带逐文件 sha256 标记，用户改过的预设升级与卸载时都不会被覆盖。", "codec", 8, "tools"),
        E("dsh-rea-agents", "dsh-rea-agents", "为 DeepSeek Harness 固定版本的 REA：把 rea-agents 安装到当前配置档的一个确切版本，从该副本启动其 MCP 服务，只有按下「更新」才升级。", "ai", 8, "tools"),
        E("dsh-sql", "dsh-sql", "数据库工具：sql_list/query/exec/schema/stats/health，SQLite/MySQL/PostgreSQL 三引擎，词法级只读保护、行数钳制、CSV/JSON 查询输出与写审批门。", "data", 8, "tools"),
        E("dsh-subagent-codex", "dsh-subagent-codex", "新增 subagent_codex 工具，把任务委派给本机 OpenAI Codex CLI 在独立外部进程中执行，与主对话完全隔离。", "sysinfo", 8, "tools"),
        E("dsh-delete-turn", "dsh-delete-turn", "DSH 消息删除插件：按条删除用户消息、按步骤删除思考与工具调用、按整条回复删除助手回答，经官方 surface-replace 契约从模型上下文移除并从可见转录隐藏，原始 append-only 日志不改写。", "session", 8, "session"),
        E("dsh-message-ops", "dsh-message-ops", "DSH 会话消息级回滚、单条删除与重放式恢复；操作以 append-only surface replace 实现，带确认提示和运行中会话保护。需 Node.js 23.5+。", "session", 8, "session"),
        E("dsh-plugin-session-import", "dsh-plugin-session-import", "把 claude-code / codex / reasonix / zcode 的聊天历史导入为 dsh 会话：工作区绑定、工具调用保留、超长会话保护、zcode 压缩还原。", "archive", 8, "session"),
        E("dsh-resume", "dsh-resume", "导入本地编程 Agent 的会话历史，在 DSH 中继续工作。", "session", 8, "session"),
        E("dsh-session-bridge-1", "dsh-session-bridge", "会话桥：让当前 agent 直接用提示词驱动其它真实的 DSH 会话——跨工作区创建主会话、向任意会话发消息或注入 steering、等待并逐段读取回复（含思维链）、恢复离线会话、按名称或 id 跨工作区查找会话；还能用后台看门狗监控并调度主任务（卡住催办、偏离纠偏、卡死终止），一键归档会话。", "archive", 8, "session"),
        E("dsh-session-cleaner", "dsh-session-cleaner", "在 DSH Web GUI 设置页管理对话记录：可删除整个会话（归档并物理删除日志），或按用户消息分组浏览并删除单条消息（删除用户消息会级联删除其引发的助手与工具消息）。运行中与当前会话受保护。", "archive", 8, "session"),
        E("dsh-session-fork", "dsh-session-fork", "Git 式会话分支，模拟真实程序员协作的并行开发：根分支充当秘书维持调度，子分支持有各自上下文并行工作，任务完成后仅以压缩摘要 squash/rebase 合并回来；提供 /branch 命令、分支页签、send_message_by_branch 跨分支消息，并附一份把会话分支绑定到 git wo", "git", 8, "session"),
        E("dsh-session-mgr", "dsh-session-mgr", "在 DeepSeek Harness 网页界面中跨工作区移动、归档、恢复、可携式备份/导出与导入会话。", "archive", 8, "session"),
        E("dsh-structured", "dsh-structured", "让 DSH 每条实质回复默认结构化：无标签标题卡 + 表格/清单/步骤；按会话开关，style.md 可覆盖。", "data", 8, "session"),
        E("dsh-webchatlike", "dsh-webchatlike", "更贴近 deepseek 网页版/App 的聊天体验：原位编辑提问、重新生成回复、每条消息带 <i/N> 版本翻页器（树状版本模型，跨对话保持稳定）。", "session", 8, "session"),
        E("dsh-ccswitch", "dsh-ccswitch", "将 CC Switch 中的 provider 和模型接入 DeepSeek Harness，并支持 provider 筛选和模型名称搜索。", "search", 8, "model"),
        E("dsh-chinese-mode", "dsh-chinese-mode", "全局中文模式：输入框旁的紧凑胶囊开关，开启后向任意预设（完整 persona 除外）的系统提示注入语言要求；回复、思考、工具区域可分别切换中英文，并兼容锚定预设。", "misc", 8, "model"),
        E("dsh-clinebot", "dsh-clinebot", "DeepSeek Harness 的 ClineBot/ClinePass 集成：专属设置页、实时配额仪表板、界面内密钥保存、精选与自定义模型选择，以及 /cline 命令。", "ai", 8, "model"),
        E("dsh-deepseek-web-free", "dsh-deepseek-web-free", "把你已登录的 chat.deepseek.com 账号当作额外模型接入 DSH，同时把 DeepSeek 网页端直接嵌进 DSH 窗口：右侧栏标签页，以及一颗可拖动、可拉伸的鲸鱼悬浮球窗口（位置与尺寸跨重启记忆，拖球时窗口跟随）。登录只需一次且双向同步——在设置页或面板内登录/退出都会同步到另一边，", "session", 8, "model"),
        E("dsh-hyperworkbuddy", "dsh-hyperworkbuddy", "将本机登录的 WorkBuddy 多账号接入 DSH，国内版与国际版分开管理。支持账号故障自动切换、一键刷新模型目录与积分、国内版每日签到，以及可开关的 OpenAI 兼容端点。", "fileops", 8, "model"),
        E("dsh-llm-codex", "dsh-llm-codex", "ChatGPT Codex 订阅聊天：官方 OAuth 登录，Sol/Terra/Luna 目录含 Fast 行，实时额度，以及可选的搜索与 view_image 工具。", "fileops", 8, "model"),
        E("dsh-llm-proxy", "dsh-llm-proxy", "按模型给 LLM 请求分流代理：勾选的模型走代理（Clash 等），其余直连；传输错误、429、5xx 自动重试，设置页实时生效。", "net", 8, "model"),
        E("dsh-model-pro", "dsh-model-pro", "llm-pi-ai 模型提供商的生命周期管理 UI：提供商的新建/编辑/删除与启停（自定义请求头、AES-GCM 加密密钥）；卸载时安全还原滞留提供商，远端模型发现与批量写入，五种策略的智能路由，并集/交集组合提供商，逐模型连通性测试与请求观测。", "codec", 8, "model"),
        E("dsh-opencode-go-model-list", "dsh-opencode-go-model-list", "让 DSH 自带的 opencode-go 供应商跟随 opencode Go 套餐的实时模型列表，opencode 上架新模型后无需改配置即可使用。", "codec", 8, "model"),
        E("dsh-router-codebuddy", "dsh-router-codebuddy", "dsh-router 的 CodeBuddy 供应商插件。单账号负责轮询式 OAuth 登录与令牌刷新，选号、冷却与签到交由 dsh-router 核心处理。", "misc", 8, "model"),
        E("dsh-subagent-model-router", "DSH-Subagent-Model-Router", "借助别名、能力标签和使用说明，将每项委派任务自动智能路由到最合适的已配置模型——常规工作更快、更省，复杂任务则交给更强的专用模型。可通过 Web 设置页或引导流程组建模型团队，让多个专家并行工作并可靠汇总结果；所选模型会显示在子代理视图中，并以内联标签无缝融入 Better Sidebar 的 Ta", "net", 8, "model"),
        E("dsh-think-ultra", "dsh-think-ultra", "将每个请求固定到原生 max effort 档位，并提供按模型与模式隔离的推理深度面板：0-20 能力滑块、独立的迅流（Velocity）/极境（Apex）配置档与离线推理工具箱。以混淆构建交付，允许商用，禁止逆向。", "ai", 8, "model"),
        E("dsh-memory-connect", "dsh-memory-connect", "跨会话记忆插件（v0.6.1，npm 包 @asherliner/dsh-memory-connect）：自动提取、SQLite FTS5 索引、RRF 语义召回（每轮注入系统提示词）、定时维护、LLM 智能合并（自动接入 ctx.llm）、上下文爆炸防护、全局身份 Soul（~/.dsh/soul", "data", 8, "memory"),
        E("dsh-memory-manager", "dsh-memory-manager", "ZCode 风格持久化项目记忆：设置内完整管理页、索引式注入与 agent 记忆工具。", "session", 8, "memory"),
        E("nowledge-mem-deepseek-harness", "nowledge-mem-deepseek-harness", "给所有 AI 工具和 Agent 共用的一层记忆：注入 Context Bundle、提示时检索、MCP 工具与回合结束 DSH 线程捕获。", "session", 8, "memory"),
        E("dsh-math-modeling-skills-gatecraft", "dsh-math-modeling-skills-Gatecraft-", "面向 DeepSeek Harness 的门控式数学建模 skill 套件：五阶段流水线、阶段门、国奖写作范式、灵敏度分析、统计诊断与竞赛预设。", "text", 8, "skill"),
        E("dsh-wuyun-liuqi", "dsh-wuyun-liuqi", "完整 wuyun-liuqi（五运六气）中医运气学技能包，封装为 DeepSeek Harness 插件：年度与客气推算、临床辨证、病机推演。", "misc", 8, "skill"),
        E("mattpocock-skills-dsh-zh", "mattpocock-skills-dsh-zh", "Matt Pocock 25 个技能正文全译中文（技术术语保留英文并附注释）。", "misc", 8, "skill"),
        E("sumsec-skills", "SumSec-Skills", "多平台 Agent Skills 集合，作为 DeepSeek Harness profile bundle 挂载，提供中文写作、Git、插件开发、Taste 与语义边界检测等 Skill。", "git", 8, "skill"),
        E("dsh-appshots", "dsh-appshots", "给 DSH Desktop 用的窗口截图，支持 macOS 和 Windows：macOS 按两边 Command、Windows 按两边 Ctrl（或点输入框旁相机）捕获当前前台窗口并附加到会话，同时把 VoiceOver 风格的辅助功能树注入为隐藏上下文。", "image", 8, "vision"),
        E("dsh-free-vision", "dsh-free-vision", "免费视觉插件：纯文本模型看图 / OCR / UI / 报错分析，优先免费模型（千问 Qwen3-VL-Flash、豆包、DeepSeek-OCR），设置界面可配置。", "image", 8, "vision"),
        E("dsh-highres-vision", "dsh-highres-vision", "为 DeepSeek Harness 原生视觉模型 deepseek-v4-flash-vision-exp 提供高清识图：将图片准入上限提升至 32 MiB / 8192 px / 600 张，并新增 highres_read 工具，将大图切为整图与 800x800 分块后经宿主 read_ima", "image", 8, "vision"),
        E("dsh-hos-scrcpy", "dsh-hos-scrcpy", "在 DSH 网页中用 AI 操控鸿蒙手机：实时 H.264 投屏、触控与系统按键、hilog 日志，并让模型读屏、定位 UI 控件，再执行点击/长按/按键/输入。", "ai", 8, "vision"),
        E("dsh-tool-vision-1", "dsh-tool-vision", "通过 inspect_image 工具将本地图片或 HTTP(S) 图片链接发送至配置的 OpenAI 兼容视觉端点，并将文字结果带回对话。", "image", 8, "vision"),
        E("dsh-video-storyboard-hp", "dsh-video-storyboard-hp", "SAOS-3624/dsh-video-storyboard 的高性能分支，与上游二选一、不能同装。把视频压成可寻址的宫格分镜（编号、每格时间戳与台词、音频包络）；需要 Node 20+、PATH 上的 ffmpeg/ffprobe，文件无字幕轨时还需配置 ASR 端点。", "git", 8, "vision"),
        E("dsh-vision-web", "dsh-vision", "纯文本 DeepSeek 的识图插件：默认走豆包 Web（零成本、免 API key，经 Windows CDP 桥接驱动已登录 Chrome），另有反重力额度（flash/pro）与 Gemini 降级通道；档位自动升级、视觉证据记忆与会话压缩恢复、内容哈希缓存、双语客户端面板。", "codec", 8, "vision"),
        E("dsh-markdown-typora", "dsh-markdown-typora", "DSH 右侧栏的 Typora 式 Markdown 编辑器：公式与 Mermaid 即时渲染，点图片右侧直接在下一行继续写，Ctrl/Cmd+S 版本守卫保存（不受会话工作区限制），选中文段带绝对路径插入对话。", "pdfdoc", 8, "docs"),
        E("dsh-paperlab", "paperlab", "Overleaf 式 LaTeX 论文工作台：在渲染后的 PDF 上选中任意文字批注，由 dsh agent 改写源文件、编译验证并提交 git 修订。", "git", 8, "docs"),
        E("dsh-fast-mode", "dsh-fast-mode", "DeepSeek Harness 自己的 fast mode：同一个模型、同样的思考强度，只花更少的输出 token，全程提示词侧。默认只开「精简输出」（late 模式，第 4 步后生效），其余开关默认关、可单独打开；工具输出很长时再开「截短工具输出」那个。本机实测、非榜单成绩：输出偏长的 30 对", "ai", 8, "usage"),
        E("dsh-opencodego-usage", "dsh-opencodego-usage", "OpenCodeGo 剩余额度监视器：输入框右下角呼吸指示灯（按剩余额度绿/黄/红），液态玻璃面板显示滚动/周/月用量窗口与重置时间，每 30 秒自动刷新，API Key 自动读取 DSH 凭据。", "codec", 8, "usage"),
        E("dsh-peak-block", "dsh-peak-block", "北京时间工作日高峰时段拦截发往官方 provider 的请求，默认 09:00-12:00、14:00-18:00，可切到配置的中转目标或直接阻止并提示，非高峰正常走官方。", "time", 8, "usage"),
        E("dsh-quota-badge", "DSH-Balance-display", "侧边栏底部实时显示 DeepSeek 账户余额徽章：数字滚轮动画、多币种支持、余额趋势图、按 Key 用量统计（含安装前历史回填），并支持 GitHub 版本自动检查。", "text", 8, "usage"),
        E("dsh-spend", "dsh-spend", "DSH Web 用量与费用统计插件：右下角悬浮窗，按模型/按天/按会话多维聚合与预计花费。", "text", 8, "usage"),
        E("dsh-token-stats", "dsh-token-stats", "DeepSeek Harness 的 Token 用量统计：近 7 天/30 天按模型的柱状图、饼图，外加近一年每日活跃热力图。", "text", 8, "usage"),
        E("dsh-devices", "dsh-devices", "去中心化多设备舰队：mDNS 同网发现、密钥配对、SSH 跨网直连指挥。", "net", 8, "remote"),
        E("dsh-gateway", "dsh-gateway", "为 DSH Web 界面提供 HTTPS + 登录保护的远程访问网关：局域网内其它设备可安全访问，配置端口映射后可从互联网访问。默认 fail-closed（仅本机监听、无内置账号，配置后才能登录），配置与安全说明见 README。", "net", 8, "remote"),
        E("dsh-lan-gateway", "dsh-lan-gateway", "把 DSH Web GUI 发布到局域网/公网，dsh 仍只绑定回环。除显式开启局域网免密外，所有来源均须登录换取 HMAC 会话 Cookie。提供自签名或自定义 TLS、用于明文 HTTP 代理的 secureCookies 覆盖项，以及让局域网纯 HTTP 来源正常打开工作区的 UUID sh", "net", 8, "remote"),
        E("dsh-lanmode", "dsh-lanmode", "为 DeepSeek Harness 网页 UI 提供局域网与反向代理访问：在非 localhost 页面返回设置服务，补齐浏览器在纯 HTTP 下限制的 Web API，并可自行开启监听端口。", "net", 8, "remote"),
        E("dsh-plugin-mobile-link", "mobile-link", "DSH Mobile 的电脑侧连接器：连上可自建的公网 WSS 中转，手机在 4G/5G 下即可访问这台电脑上的 DSH 会话，电脑不需要公网 IP 也不用组网；中转只做鉴权与转发。", "session", 8, "remote"),
        E("dsh-ssh-tunnel", "dsh-ssh-tunnel", "多机 SSH 工作台：把远程服务器收进主机库、按项目授权，在右侧栏里开交互式终端或双栏 SFTP；模型用 SSHManager 工具远程执行命令、上传下载文件，密钥不进模型上下文。", "net", 8, "remote"),
        E("dsh-approval-llm", "dsh-approval-llm", "基于模型的权限审批：由独立审查模型自动应答 approval 权限请求。", "ai", 8, "security"),
        E("dsh-approval-mode", "dsh-approval-mode", "在权限下拉框旁增加「审批模式」开关：默认审批保留逐次确认，绕过审批自动放行所有工具调用，同时保持 Workspace Write 权限。", "misc", 8, "security"),
        E("dsh-riskproof", "dsh-riskproof", "DSH 实时安全浮标，随工具调用更新防护状态，点击查看调用统计、风险来源链和拦截结果，支持只读任务约束及工具元数据变化检测。", "text", 8, "security"),
        E("dsh-workspace-write-plus", "dsh-workspace-write-plus", "增加工作区修改++权限档，文件工具仍锁在工作区，可用通配符放行 Git Bash 等程序以跳过 Windows 进程沙箱。", "git", 8, "security"),
        E("browser-mcp", "browser-mcp", "通过本地 MCP server 驱动你真实的 Chrome：可搜索 Google/Bing/搜狗、读取任意页面（含 JS 渲染与登录后内容）、在后台窗口自动化点击/滚动/输入/按键/选择，并为知乎、小红书、抖音、Bilibili、X、Reddit 提供平台级搜索/详情/评论/下载；评论断点续抓、下载", "net", 8, "browser"),
        E("dsh-browser-control-1", "dsh-browser-control", "基于 Playwright MCP 的 AI 浏览器控制：驱动真实可见的 Chrome（导航/点击/输入/快照，约 80 个 browser_* 工具），并在 GUI 内嵌实时截图面板，每次操作后自动刷新。", "image", 8, "browser"),
        E("dsh-explorer", "dsh-explorer", "Git 优先的文件树侧栏：VS Code 风格层级线、M/A/U/D/R git 状态装饰、HEAD 与工作区对照预览、媒体预览、拖拽引用（文件/文件夹/选中代码带行号）—— 纯插件。", "git", 8, "git"),
        E("3chatai-deepseek-harness-plugin", "3chatai-deepseek-harness-plugin", "通过 OAuth 将 DeepSeek Harness 接入 3Chat，查询客户与会话、读取沟通上下文、确认后发送消息并跟踪批次进度。", "session", 7, "tools"),
        E("deepseek-harness-plugins-1", "archive/mcwiki-search", "查询中文 Minecraft Wiki（MediaWiki API），把搜索结果与页面全文完整转换为 AI 可直接阅读的干净文本——搜索、引言、全文 Markdown、随机条目；模板、引用、图片、跨语言链接等噪声在插件内部全部清洗完毕。已归档并冻结在固定版本：作者不再为它适配新版 DSH。", "pdfdoc", 7, "tools"),
        E("dsh-bili-watch", "dsh-bili-watch", "把 B 站视频解析成模型可消费的结构化内容：元数据、评论、弹幕、字幕、本地 ASR 转写、抽帧 OCR。本地跑不上传、字幕诱饵检测（可疑时抽帧核对）、二次读瞬时、输出 manifest + 摘要。抽帧 OCR 需 ffmpeg；本地 ASR/OCR 需 Python 3.10+ 虚拟环境（Windo", "image", 7, "tools"),
        E("dsh-compressor", "dsh-compressor", "Headroom 的精简移植，在不影响模型上下文缓存以及 Agent 性能的情况下，压缩工具的输出，至多减少 20% 的上下文。", "archive", 7, "tools"),
        E("dsh-db-tool", "dsh-db-tool", "DeepSeek Harness 社区插件：在对话中直接管理多数据库（MySQL、PostgreSQL、GaussDB、MongoDB、Redis、Oracle、达梦、SQLite），支持项目级 ro/rw 授权、侧边栏管理面板、结构浏览与数据预览，危险操作需确认后执行。", "data", 7, "tools"),
        E("dsh-figma-mcp", "dsh-figma-mcp", "DSH 的 Figma MCP 一键连接插件。", "misc", 7, "tools"),
        E("dsh-grafana", "dsh-grafana", "对话式 Grafana 运维：跨多个命名源站查看实时大盘数据，再通过审批与版本校验安全、可审阅地修改大盘。", "session", 7, "tools"),
        E("dsh-laya", "dsh-laya", "把 Laya 的有类型决策（`noul` 是/否、`choice`、`score`）接成一等 Cordis 服务（`ctx.laya`）与两个模型可见工具 `laya_ask`、`laya_plan`。插件自身不安装也不下载任何东西：它是你自己启动的 `laya-mcp serve` 边车的客户端，", "net", 7, "tools"),
        E("dsh-macos-computer-use", "dsh", "DeepSeek Harness 的 macOS computer use：基于无障碍树的稳定 ref 定位、后台输入、Unicode 输入、菜单与应用、set-of-mark 截图、本地 OCR 与动作校验——11 个工具桥接 macos-cu CLI。", "image", 7, "tools"),
        E("dsh-mcp-lazy", "dsh-mcp-lazy", "MCP 懒加载路由：自动发现可接管的 MCP，冷态只在工具目录里留一个共享路由，某轮需要哪个服务器才展开它的工具 Schema、轮次结束再收起，让装了很多 MCP 不再每次请求都吃上下文。命名异常、重名或状态不确定的 MCP 不接管；出现任何不确定即恢复原工具可见性，执行、权限与进程生命周期仍归原", "data", 7, "tools"),
        E("dsh-mysql", "dsh-mysql", "DeepSeek Harness 的 MySQL 连接插件：在设置页配置多套连接（每连接可配表白名单与写权限），输入栏一键切换当前会话的连接，并为所有 Agent 预设提供 mysql_query / mysql_tables / mysql_execute 工具。", "data", 7, "tools"),
        E("dsh-native", "packages/dsh-rust-exec", "Windows 上的常驻 Rust 伴生进程，把散落的 shell 调用收进一个暖 worker：11 个工具（10 个 rust_* 工具外加 native_help 入口；5 个常驻、6 个按需激活）覆盖命令执行、带 sha256 校验的文件读写、代码索引与搜索、会话日志投影与资源采样，由带通道", "codec", 7, "tools"),
        E("dsh-proxy-1", "dsh-proxy", "在直连、手动 HTTP(S)/SOCKS5 代理和环境/系统代理模式间热切换 DSH 进程内 fetch 流量，支持免代理规则，并可为之后启动的子进程导出代理环境变量。", "net", 7, "tools"),
        E("dsh-rustxng", "dsh-rustxng", "用自托管的 RustXNG 元搜索引擎接管内置 web_search，按需下载并启动该二进制、空闲超时后停止；可选的抓取层还能解码仅在 <meta> 中声明编码的页面。", "codec", 7, "tools"),
        E("dsh-skillport", "dsh-skillport", "把已有的 Agent Skills（SKILL.md）技能库带进 DSH：扫描 Claude/Codex/Cursor/Gemini 技能目录、注入渐进式索引，按需加载技能正文。", "fileops", 7, "tools"),
        E("dsh-sw-cad", "dsh-sw-cad", "注册两个 MCP 服务器，在 Windows 上通过 COM 驱动本机安装的 AutoCAD 与 SolidWorks，另附两个按需技能。仅 Windows，需要 Python 3.11+；首次加载时自动安装钉死版本的上游服务器，并且只给真正装了的 CAD 应用注册对应的那一行。两者都只广告两个元工", "devops", 7, "tools"),
        E("dsh-tool-web-enhanced-profile", "profile", "为原生 web_search 与 web_fetch 提供可切换的后端，每个会话可在输入框菜单或 /setup-search、/setup-fetch 中选择：搜索支持 DeepSeek、Exa、Firecrawl、Tavily、Tinyfish、OpenAlex、Semantic Scholar", "fileops", 7, "tools"),
        E("dsh-webgis", "DSH-WebGIS", "DSH Web UI 的对话式 GIS：支持本地文件与 PostGIS 查询、交互式地图与空间分析。", "fileops", 7, "tools"),
        E("hermes-dsh-bridge", "hermes-dsh-bridge", "内嵌 MCP server，让外部 Agent（Hermes、Claude Code 等）通过 StreamableHTTP 驱动 DeepSeek Harness：同步/异步任务执行、三档文件沙箱、Web 审批桥、会话管理与搜索、路径隔离的文件工具。", "fileops", 7, "tools"),
        E("lume-dsh-plugin", "Lume", "DSH Desktop 人设与记忆插件：从聊天记录、小说、剧本或设定文档蒸馏角色；支持长期与临时记忆、风格学习、认可语料、人设切换纠偏、记忆星图和角色卡导入导出。任务侧仅保留轻量工作纪律，不再注入计划、台账或动态提醒。", "session", 7, "tools"),
        E("dsh-archived-sessions-1", "dsh-archived-sessions", "归档会话管理：浏览已归档会话，支持恢复（取消归档）与清空。", "archive", 7, "session"),
        E("dsh-context-mode", "dsh-context-mode", "为 DeepSeek Harness 适配 Context Mode：进程内 ctx_* 工具（沙箱代码执行与 FTS5 知识库），并注入上下文窗口路由指引。", "sysinfo", 7, "session"),
        E("dsh-cross-session-approval", "dsh-cross-session-approval", "DeepSeek Harness 的跨会话派活与协同：新建顶层任务会话并投递任务，用 base62 会话别名读取或干预，并通过审批桥批准子会话的沙箱提权——命中破坏性删除一律强制拒绝。", "session", 7, "session"),
        E("dsh-daily-chat", "dsh-daily-chat", "把 DSH Web 侧边栏的「新会话」拆成两种模式：「日常聊天」在专属工作区里用插件自己安装到 harness home 的 `daily` 预设开一个只有人格、网页检索/抓取、提问和上下文压缩的轻量会话（没有文件、Shell、计划模式和子代理），侧边栏只列这些日常会话；「开始工作」保持原有编码 A", "codec", 7, "session"),
        E("dsh-file-claim", "dsh-file-claim", "同一工作区并行多会话的文件认领与写入保护（claim/release、心跳 stale 接管、pending 三路合并）。", "fileops", 7, "session"),
        E("dsh-prompt-easymanager", "dsh-prompt-easymanager", "可以自行选择在全局范围或单独会话中增加个人提示词、修改系统提示词来工作，各会话互不影响。", "session", 7, "session"),
        E("dsh-search-index", "dsh-search-index", "自带独立索引的侧边栏会话搜索（不再复用 DSH 官方全文索引）：一处入口在标题与内容检索间切换，结果按会话聚合，附最强命中片段与 用户/回复/工具 类型标签；水位驱动增量同步、按归档集合清理已归档会话，整理走影子索引不阻塞在用索引。", "archive", 7, "session"),
        E("dsh-session-cleaner-1", "dsh-session-cleaner", "在侧栏会话菜单中加入「删除」，把会话——带子代理时连同整棵后代树——搬进回收站（目录在磁盘上整体 rename 迁走，原子操作，不做复制），并提供侧栏回收站面板：标题与正文搜索、工作区筛选、排序、查看对话记录、恢复与彻底删除。删除时同时摘掉工作区槽位、置顶与归档标记以及投影缓存行，恢复时把会话放回侧", "archive", 7, "session"),
        E("dsh-session-link", "dsh-session-link", "复制、打开 `dsh://` 会话深链，或将其粘贴到另一对话中，注入被引用会话的受限只读快照。", "session", 7, "session"),
        E("dsh-session-prefix", "dsh-session-prefix", "基于 Jev 决策模型或 Agent 工具为会话自动分类，并将任务阶段直观展示为标题前缀 Emoji（进行中 🚧、阻塞 ⏸️、待验收 👀、已完成 ✅、规划 💡、排障 🐛）。支持生命周期状态自愈、可选 Jev 决策推断（需配置 Jev API Key）、Agent 自主标记与可视化设置面板。", "session", 7, "session"),
        E("dsh-team-link", "dsh-team-link", "会话深链、全量会话导出（markdown/JSON）、带配对的跨会话消息投递，以及团队 roster / 换届 / 恢复工具。", "pdfdoc", 7, "session"),
        E("dsh-claude-cli", "dsh-claude-cli", "LLM 供应商：把本机已安装的 Claude Code CLI 作为模型后端，请求走已订阅的 Claude 账号，无需按量计费的 API key；原生工具调用经 MCP 桥接。", "ai", 7, "model"),
        E("dsh-codex-harness", "dsh-codex-harness", "在 DSH 中提供精简的 Codex 编码模式：使用精简的 codex 提示词与原生 Codex 风格工具，并用少量提示词约束抑制 GPT 的过度解释；提示词可自行编辑调整。", "codec", 7, "model"),
        E("dsh-connect-sensenova-token-plan", "dsh-connect-sensenova-token-plan", "一键接入商汤 Token Plan的语言、生图模型到 DSH（默认关），自动填入图片识别与思考强度；限频时自动退避重试，不会误判为额度耗尽；登录商汤控制台后，可查看用量胶囊、积分池、每模型消耗。也支持扫码登录小浣熊，接入其模型，查看模型消耗倍率，使用联网搜索。", "image", 7, "model"),
        E("dsh-gemini-pool", "dsh-gemini-pool", "多账号 Google Gemini 提供商：按剩余额度挑选账号，遇 429 指数退避切换，后台探活已禁用账号，附中英双语设置页。", "misc", 7, "model"),
        E("dsh-kimi-tide", "dsh-kimi-tide", "逐步模型路由器：以命名预设与带图/关键词组有序规则为每一步在全部已挂载模型间选路，附图像转述协作流、图像护栏、多 plan 配额面板与逐步决策可观测。", "image", 7, "model"),
        E("dsh-model-extension", "dsh-model-extension", "模型+ 设置页:按模型声明推理挡位、输入模态与兼容参数(走官方 settings 管线保存),支持 models.dev 元数据预填与 API 密钥管理。", "ai", 7, "model"),
        E("dsh-oauth-adapter", "dsh-oauth-adapter", "为 DSH Web 提供 OAuth 账号页面，目前支持 OpenAI Codex、GitHub Copilot、Anthropic、Kimi For Coding、OpenRouter 与 xAI。", "misc", 7, "model"),
        E("dsh-opencode-free", "dsh-opencode-free", "在 DeepSeek Harness 中使用免费的 OpenCode Zen 模型：默认匿名，可选填 Zen key；模型表在运行时从 Zen 官方列表读取，匿名请求会按免费档校验做适配，并有带日期的实测记录。", "codec", 7, "model"),
        E("dsh-router-traework", "dsh-router-traework", "dsh-router 的 TRAE SOLO 供应商插件，移植自 traework2api。提供 traework 供应商这一免费 SOLO 聊天通道，并向 dsh-router 核心上报单账号状态。", "misc", 7, "model"),
        E("dsh-wtq-pool", "dsh-wtq-pool", "把本机 WorkBuddy、Trae、Qoder 的桌面登录接进 DeepSeek Harness，每家一个 OpenAI 兼容的本地端点，带账号池、限流自动换号与设置面板。", "misc", 7, "model"),
        E("dsh-zcode-cli-proxy", "dsh-zcode-cli-proxy", "把 ZCode CLI（客户端自带 agent）接入 DeepSeek Harness 的模型反代：常驻 app-server 会话 + Start Plan 账户注入 + 每请求 OAuth 鉴权，直接消耗 ZCode Start Plan / Coding Plan 额度，真流式、图片输入、会话", "image", 7, "model"),
        E("dsh-biomemory", "dsh-biomemory", "为 DeepSeek Harness 打造的生物仿生记忆系统：以单一 SQLite 库为唯一事实来源（node:sqlite，WAL），Markdown 树仅作只读镜像；含 memory 工具、会话启动时的冻结快照注入、分级审批门、按需把当前会话抽取成记忆、近重复合并、归档与取代生命周期、记忆代谢（", "pdfdoc", 7, "memory"),
        E("dsh-memory-system", "dsh-memory-system", "面向 DeepSeek Harness 的本地优先持久记忆：在 pre-step 注入有预算上限的热记忆，使用精确匹配与中文二元 BM25 召回冷层，提供六个 Agent 工具，并以审批门禁、租约锁、恢复回执和只读治理与轨迹复盘候选保护写入。", "session", 7, "memory"),
        E("dsh-tiddlywiki", "dsh-tiddlywiki", "把 TiddlyWiki 5 变成 DSH 的持久知识库：十个 tiddlywiki_* 智能体工具（带过滤的检索、读写/批量/改名/删除、最近、标签，以及 git 同步与冲突解决），GUI 中央栏经同源代理内嵌完整 TiddlyWiki 编辑器，右侧栏知识库 Tab，会话级汇总本会话读写过的笔记，", "git", 7, "memory"),
        E("dsh-unified-agent-memory", "unified-agent-memory", "多 Agent 共享一个 Obsidian vault：零依赖 Python core（检索/晋升/裁决/遗忘）+ vault 模板 + dsh 插件（memory_search/show/submit/status）。", "search", 7, "memory"),
        E("dsh-adhd-copilot", "dsh-adhd-copilot", "ADHD 行为辅导技能：任务拆解、事项过载管理、启动仪式与失败重启。", "misc", 7, "skill"),
        E("dsh-echocat-skill-panel", "dsh-echocat-skill-panel", "每轮对话报告本轮调用了哪些 skill（模型自动加载、用户输入 /name，或一个都没用），并管理本机 skill 目录：粘贴仓库、文件夹、SKILL.md 或 zip 地址即可安装，中文显示名写入该 skill 的 meta.yaml，删除时保留备份。", "git", 7, "skill"),
        E("dsh-rigorquant", "dsh-rigorquant", "RigorQuant 预设与技能包：面向实证与计算数学（经济学、金融、组合）的无人值守隔离多智能体研究，内置四重实现前校验与 jacobian/Lean 升级通道。", "ai", 7, "skill"),
        E("dsh-trip-planner-cn", "better-trip-planner", "把境内旅行规划技能注册进 DSH 技能目录：逐小时每日时间线、12306 与携程/去哪儿预订深链、离线 KML 与七套 HTML 主题。需 PATH 上有 Python 3.9+（内置脚本仅依赖标准库）。", "time", 7, "skill"),
        E("no-ai-style", "no-ai-style", "学术与专业写作润色技能，输入框三选一：检查——只检查并给建议；询问能否提交时补充结论，不改原文。润色——改善表达，保留原意、事实和引用。起草——根据现有材料起草，不补充材料外的事实。", "git", 7, "skill"),
        E("tripo-dsh", "plugin", "通过 shell 驱动 tripo-cli 的 Tripo 3D 生成 Skill：文生 3D、图生 3D、绑骨与走跑动画、减面与 LOD 链，导出 GLB/FBX/OBJ/STL/USDZ/3MF，支持国内站与海外站账号的无头设备码登录；npm 包名 `tripo-dsh`。", "misc", 7, "skill"),
        E("deepseek-harness-plugins-2", "vision-bridge", "让纯文本模型也能看图：消息中出现图片占位符时模型调用 vision_describe 工具，插件把本轮图片引用与提问一起转交给多模态视觉模型识别，主模型失败时自动用备用模型重试。配置在设置页完成并通过官方 settings API 持久化到 settings.yaml，热重载不丢。", "image", 7, "vision"),
        E("dsh-omni-workstation", "dsh-omni-workstation", "面向 DSH 的全模态工作站：analyze_image 走有序多卡片 VLM 故障转移链；六个视觉工具箱工具（局部放大、色调采样、像素比对、OCR、元素检测、内联展示）共用同一套图片来源解析；generate_image 支持 OpenAI/DashScope/ComfyUI 协议；多卡片异步 g", "image", 7, "vision"),
        E("docs-mode", "docs-mode", "面向 DeepSeek Harness 的技术文档撰写 Agent 模式：模板驱动写作与自学习模板库、技术文档去 AI 味，以及文档质量保障工具集（量化体检、多文档口径一致性校验、图/表编号重排、版本同步检查、Word/PDF 导出与界面截图自动化）。", "pdfdoc", 7, "docs"),
        E("dsh-code-server-app", "dsh-code-server-app", "将code-server（VSCode网页版）打包安装到dsh内的插件，快速实现专业的文件编辑。", "archive", 7, "docs"),
        E("dsh-pdf-translator", "dsh-pdf-translator", "DeepSeek Harness 的 Windows PDF 翻译插件：由视觉模型识别并翻译正文、表格、图表和公式，输出中文 PDF 与 LaTeX 源码压缩包。需要自备支持图片输入的 OpenAI 兼容 API。", "pdfdoc", 7, "docs"),
