        E("dsh-balance-float", "dsh-balance-float", "Web UI 右上角悬浮窗：实时显示 DeepSeek 余额，支持手动刷新与一键优雅退出（Y/N 快捷键确认）。", "misc", 7, "usage"),
        E("dsh-balance-widget-1", "dsh-balance-widget", "DSH Web GUI 的余额与成本小部件：侧边栏底部卡片显示账户余额、剩余比例条与今日花费；点击展开四层级成本明细（最近提问 / 本会话 / 今日·本项目 / 今日·全部），带名词解释与一键充值入口。零依赖，兼容 Node 24。", "session", 7, "usage"),
        E("dsh-desktop-statusbar", "dsh-desktop-statusbar", "把 DSH 桌面端对话区底部的统计行换成可配置状态栏：10 个字段可选可排序，按 DeepSeek 官方峰谷口径实时估算费用，支持自定义模型单价、CNY / USD 计价切换与账户余额显示。", "data", 7, "usage"),
        E("dsh-llm-key-rotation", "dsh-llm-key-rotation", "在配额、速率限制或身份验证失败后轮换已配置的 LLM API 密钥。", "ai", 7, "usage"),
        E("dsh-quota-1", "dsh-quota", "右下角「会员额度」悬浮球与面板，聚合各 AI 平台套餐额度（Kimi Code、DeepSeek、智谱 Coding Plan、BigModel、通义千问、超算、TokenRouter、SupaWriter），API key 自动同步自 DSH 凭证域，彩色进度条展示用量。", "ai", 7, "usage"),
        E("dsh-token-saver-1", "dsh-token-saver", "为 DeepSeek Harness 设计的 token 节省插件：不损失任务效果。默认 conservative 档对工具结果做无损头尾裁剪与 grep 折叠；balanced 档在压力阈值委托 dsh-compaction-basic；aggressive 档以 LLM-summary 引擎子类", "ai", 7, "usage"),
        E("dsh-token-viewer", "dsh-token-viewer", "dsh 网页端 CC Switch 风格 Token 消耗统计：按请求的用量日志、真实消耗 Hero、按请求提交时间分桶的趋势图、按模型峰谷牌价计费、项目/模型统计与账户余额。", "git", 7, "usage"),
        E("model-usage-plugin", "model-usage-plugin", "按模型统计 token 消耗并估算费用，同时显示 DeepSeek 账户余额，展示于设置面板「模型消耗」页签。", "text", 7, "usage"),
        E("dsh-plugin-mesh", "dsh-plugin-mesh", "通过 UDP 组播或端口扫描发现局域网内的其他 DSH 实例，在侧栏面板中列出它们以及各自上报的能力，并可经局域网或自动下载的用户态 Tailscale 节点在两台机器之间双向派发任务。", "net", 7, "remote"),
        E("dsh-qq-onebot", "dsh-qq", "把 QQ 接进 DeepSeek Harness：私聊群聊、本地语音转文字、看图，以及十个互动工具（戳一戳、贴表情、点赞、发图、发文件、撤回等）。需要本机另跑一个 OneBot 11 实现（如 NapCat）。", "media", 7, "remote"),
        E("dsh-remote-development", "dsh-remote-development", "基于 SSH 的远程开发：把注册机器上的目录选为会话工作区后，文件、shell、bash 与搜索工具即改在远程主机上执行——agent 用与本地相同的工具在那里工作，不新增任何面向模型的工具。", "fileops", 7, "remote"),
        E("dsh-remote-tunnel", "dsh-remote-tunnel", "远程主机隧道管理器：把 dsh web 跑在远程 Linux 服务器上（systemd 守护、免 root），本地经自动重连的 SSH 隧道访问；远程端口自动分配并在服务器登记留档，支持多人共用与 audit 审查。", "net", 7, "remote"),
        E("dsh-ssh-workspace-1", "dsh-ssh-workspace", "通过SSH方式，将远程主机的文件夹当成DSH的工作区，可以在本地DSH控制远程主机工作目录，不需要手动同步、不需要挂载驱动、不需要装任何第三方文件系统", "fileops", 7, "remote"),
        E("dsh-webgate", "dsh-webgate", "Web GUI 远程访问：局域网二维码直连、cloudflared 快速隧道、frp 自有服务器反代，内置登录门户，并放行设置接口。", "codec", 7, "remote"),
        E("harness-relay-mcp", "deepseek-harness-relay-mcp", "在 Web profile 中安装适配层，检测并写入 MCP 配置，供 Codex、Cursor 或 Claude Code 拉起 dsh --profile codex.", "fileops", 7, "remote"),
