        E("dsh-ai-dataset-inspector", "ai-dataset-inspector", "AI数据集质量巡检工具，自动检测数据集中的标注一致性、类别分布偏差与数据泄露风险。", "misc", 6, "tools"),
        E("dsh-city-data-classifier", "city-data-classifier", "城市数据AI分类插件 — 基于GB/T 47949自动推荐数据分类，支持结构化/半结构化/非结构化", "misc", 6, "tools"),
