        E("dsh-data-asset-inventory-scan", "data-asset-inventory-scan", "数据资产盘点扫描插件 — 深度元数据扫描 + 资产三条件初筛（权属线索标注），输出资产清单", "misc", 6, "tools"),
        E("dsh-data-asset-orchestration", "data-asset-orchestration", "数据资产编排引擎，把套件内工具串成预置流水线（脱敏→清洗→盘点→封装、鉴证、AI数据集体检、政务巡检、可流通性评估），支持增量与定时处理", "time", 6, "tools"),
        E("dsh-data-asset-quality-score", "data-asset-quality-score", "依据 GB/T 36344-2018 国家标准，从规范性、完整性等六个维度对数据质量进行量化评分，为企业数据资产入表提供可审计的底稿。", "misc", 6, "tools"),
        E("dsh-data-asset-registration-helper", "data-asset-registration-helper", "数据资产登记助手：做禁用场景与权属纠纷预检，按数据类型和地区匹配登记机构，并给出含三审标准与七步流程的登记清单。", "misc", 6, "tools"),
