        E("dsh-data-lineage", "data-lineage", "数据血缘追踪工具，梳理数据从产生到流转的全链路，满足数据产权登记中的来源合法性审查要求。", "misc", 6, "tools"),
        E("dsh-data-masking", "data-masking", "基于国家标准的自动化数据脱敏工具，自动识别身份证、手机号等敏感字段，支持完全匿名化与假名化分级策略，生成合规审计日志。", "data", 6, "tools"),
