        E("dsh-data-visualization", "data-visualization", "数据可视化插件 — 生成自包含HTML报告，支持五种图表(bar/comparison/pie/radar/flowchart)与两列布局", "misc", 6, "tools"),
        E("dsh-disk-guard", "dsh-disk-guard", "把 DSH 的下载、产物、缓存与临时文件重定向到用户指定目录（自动挑剩余空间最大的非 C 盘），向每个会话注入路径纪律提示词，并自带 disk_guard 工具做状态查看与清理——防止 C 盘被撑爆。", "net", 6, "tools"),
        E("dsh-edit-approval", "dsh-edit-approval", "每次 edit 与 bash 调用前都会询问：编辑前展示红绿行级 diff，命令前展示描述与命令面板——同意一次或拒绝，两个 gate 各带独立总开关（Settings → General）。", "text", 6, "tools"),
        E("dsh-fin-aml-checker", "fin-aml-checker", "金融反洗钱合规检查插件，自动检测大额与可疑交易阈值、豁免规则与时效性，输出可审计的反洗钱合规报告，覆盖银行、保险、证券多业态。", "misc", 6, "tools"),
        E("dsh-generate-registration-docs", "generate-registration-docs", "登记文档生成插件 - 生成三份登记材料：数据描述、来源合法性声明与产权归属说明（三权分置）。", "misc", 6, "tools"),
        E("dsh-geo-data-quality-inspector", "geo-data-quality-inspector", "地理空间数据质量检查插件，检测高程精度、拓扑一致性与坐标系统合规性，输出加权质量评分报告，满足GB/T 24356-2023国家标准。", "misc", 6, "tools"),
