        E("dsh-matlab-mcp", "dsh-matlab-mcp", "把 MathWorks MATLAB/Simulink MCP 服务器注册进 dsh profile，让会话获得 mcp__matlab__* 工具，用于运行 MATLAB 代码以及读取、编辑与测试 Simulink 模型。", "fileops", 6, "tools"),
