        E("dsh-office-com", "dsh-office-com", "COM 驱动真实 Microsoft Office 实例的 DeepSeek Harness 插件：经 OfficeMCP 操作运行中的 Excel/Word——VBA 宏、透视表、活公式重算、文档深度排版；含会计场景（复式记账分录 + 借贷平衡校验、SUMIF 科目总账）。", "pdfdoc", 6, "tools"),
        E("dsh-plugin-academic-writing", "dsh-plugin-academic-writing", "为 DSH agent 提供学术写作工具包：论文大纲、标题与摘要骨架、GB/T 7714 / APA / MLA 引文格式化、措辞质检与投稿前清单。", "ai", 6, "tools"),
        E("dsh-plugin-autoevo", "dsh-plugin-autoevo", "AutoEvo v1.0.0 为 DSH Agent 提供 Search-first 能力工作流：优先复用本地工具或审查精确来源插件后再安装；可在受管源码中改造或新建能力；回执区分 installed、loaded、activated、verified，版本工具支持回滚、领养与上游更新。", "search", 6, "tools"),
        E("dsh-plugin-finance-data", "dsh-plugin-finance-data", "为 DSH agent 提供金融数据工具包：数字与货币格式化（含中文万/亿单位）、收益与年化计算、估值与盈利比率、现值/终值、风险指标与数据质量清单。", "ai", 6, "tools"),
        E("dsh-plugin-proxy", "dsh-plugin-proxy", "DeepSeek Harness 全局代理插件：通过 Windows 系统代理或自定义地址统一代理模型请求与工具流量，主界面常驻开关，且 Agent 在对话中实时感知代理状态。", "net", 6, "tools"),
        E("dsh-prompt-polish", "dsh-prompt-polish", "输入框 ✨ 一键润色按钮：参考 WorkBuddy 润色（humanizer-zh）规则改写提示词与草稿（去除 AI 写作痕迹、调整句式节奏，按指令/提问/普通文本分类处理），默认使用免费的智谱 GLM-4.5-Flash，也支持任意 OpenAI 兼容 API，断网时回退到本地规则引擎。", "ai", 6, "tools"),
        E("dsh-registration-precheck", "registration-precheck", "登记预检插件 — 按国家数据产权登记规则做四项检查（国家安全、来源合规、权属纠纷、材料真实性承诺），并输出《登记预检报告》。", "misc", 6, "tools"),
        E("dsh-research", "dsh-research", "提供本地 PDF 阅读、持久论文库、可追溯证据记录，以及跨论文比较与综合工具。", "pdfdoc", 6, "tools"),
        E("dsh-research-data-provenance", "research-data-provenance", "科研数据溯源审计插件，审计血缘完整性、可复现性与FAIR原则合规性，输出溯源审计报告，支撑科研诚信与开放科学。", "search", 6, "tools"),
        E("dsh-rss-1", "dsh-rss", "RSS/Atom 订阅九工具（管理/校验/抓取解析/跨订阅搜索/增量抓取/OPML 导入导出/健康自检），游标增量抓取，订阅持久化到 settings。面板内置 3 步首次使用引导，看一次后不再出现。", "net", 6, "tools"),
        E("dsh-smart-dl", "dsh-smart-download", "DSH 多线程下载插件，内置 aria2：先探测目标是否支持 Range，再按文件大小选择 aria2（4 或 8 连接）或回退 curl 单线程下载。", "net", 6, "tools"),
        E("dsh-subagent-control", "dsh-subagent-control", "三个工具，让任意智能体（包括团队成员）能列出、追问并中止自己派出的子代理。", "net", 6, "tools"),
        E("dsh-tool-disclosure", "tool-disclosure", "渐进式工具披露：被延后的工具组在每次请求中只占目录里的一行，模型用 tool_search 加载后才拿到完整 schema；设置页为每个组提供一个开关，各组开销按当前工具注册表实测。", "data", 6, "tools"),
        E("dsh-web-search-multi", "dsh-web-search-multi", "为原生 web_search 工具提供可选的 SearXNG、Brave、Tavily、Gemini 搜索溯源或 Wikipedia 后端，支持 Web 设置且不进行隐式回退。", "search", 6, "tools"),
        E("gov-config-zj", "gov-config-zj", "浙江省政务数据巡检配置包 — 含浙政办/浙委改等浙江省地方政策依据与标准词表，提供配置加载与校验运行时", "misc", 6, "tools"),
        E("rotifer", "rotifer", "Rotifer 协议的技能包加 Rotifer MCP 服务，以 DSH 自带的技能提供器与 MCP 客户端实例的形式挂载：搜索 Gene、按 Arena 排名比较、在本地项目里安装或回滚 Gene，并创建和运行本地 Agent。MCP 服务锁定版本，只开放 evolve 工具集，不含发布与登录。", "search", 6, "tools"),
        E("context-assembler-dsh", "context-assembler-DSH", "DeepSeek Harness 上下文汇编插件：话题块上下文汇编、水位压力话题切割、工具轮压缩/改写、reality 召回注入与 handoff 规划。", "archive", 6, "session"),
        E("deepseek-web-import", "deepseek-web-import", "从设置页把 chat.deepseek.com 网页端对话导入为 DeepSeek Harness 会话，导入后可在其中继续对话。", "session", 6, "session"),
        E("dsh-agent-message", "dsh-agent-message", "DeepSeek Harness 跨会话 Agent 通信：支持会话发现、离线投递、投递回执与发送方会话导航。", "session", 6, "session"),
        E("dsh-annotation", "dsh-annotation", "选中正文、Diff 或文件文字后批注并随消息发送，回复按批注逐条对照并支持定位；引用与批注共用宿主的选中文字工具栏。", "fileops", 6, "session"),
        E("dsh-archive-manager-1", "dsh-archive-manager", "归档会话管理器：按工作区分组查看已归档的会话，支持恢复（取消归档）与打开会话转录目录。", "archive", 6, "session"),
        E("dsh-archive-manager-2", "dsh-archive-manager", "DSH Web UI 的归档会话管理器：重新打开已归档会话并继续对话、取消归档恢复原位、彻底删除会话，支持分组浏览、消息搜索与原生视图同步。", "archive", 6, "session"),
        E("dsh-codexlike-projectless", "dsh-codexlike-projectless", "提供类似 Codex 的无项目草稿、各项目草稿切换及首次发送时按日期和主题创建目录的功能；支持 Windows DSH Desktop 0.2.1-rc.2，无需归档补丁或外部安装器。", "archive", 6, "session"),
        E("dsh-companion", "dsh-companion", "四模块会话伴侣：对话智能导出（Markdown/PDF/JSON/PNG 长图、隐私脱敏、批量 ZIP）、上下文交接摘要（模板保存与导入继承）、API 成本优化（官方动态计价、峰谷调度、日/月双档预算、模型路由）、全局对话检索与对话内搜索（Ctrl+F、CSS Custom Highlight AP", "pdfdoc", 6, "session"),
        E("dsh-find-session", "dsh-find-session", "在当前对话或所有会话里按关键词查找，命中可高亮、可跳转。", "session", 6, "session"),
        E("dsh-off-peak-message", "dsh-offpeak-send", "谷时发送调度器：开启谷时模式后输入框消息排队至 DeepSeek 谷时窗口（半价）自动注入会话并得到回复。原生外观输入条、快捷键（Enter 入队 / ⌘+Enter 立即发送 / Esc 退出）、按会话记忆的开关，重启不丢。", "session", 6, "session"),
        E("dsh-retrace", "dsh-retrace", "撤回/编辑重发/重新生成，加上单会话版本化：每次回退的时间线、产物回退（git 优先、快照兜底）、分叉图、会话谱系，以及实时看门狗（并发写入第一时间快照日志）。编辑前自动停止运行中的 agent（官方 cancel/whenIdle），回退不会损坏持久化日志、也不会破坏 /compact。", "git", 6, "session"),
        E("dsh-rollback", "dsh-rollback", "TRAE 式「回退到本轮对话发起前」插件：按轮次建立检查点（10 轮滑动窗口），同时回滚工作区文件与原位截断模型上下文，保持同一 session id。回退只能由人发起：/rollback 命令或每轮的 Web 回退按钮（被中断的轮次也可用），弹窗逐条列出受影响文件及其动作（恢复/找回/删除/跳过）", "fileops", 6, "session"),
        E("dsh-session-categories", "dsh-session-categories", "为 Web 侧边栏添加按 Workspace 隔离的分类树，支持嵌套分类、拖拽归类会话、在分类中新建会话，以及删除分类时归档其中的会话。", "archive", 6, "session"),
        E("dsh-session-delete-12", "dsh-session-delete", "给 DSH 会话加上回收站。增加删除会话、多选批量删除会话功能，删除的会话会被移至回收站。回收站内的会话可恢复，也可彻底删除；彻底删除就是永久删除，之后不可恢复，也不会自动过期。回收站内可以查看会话正文，方便区分会话。", "session", 6, "session"),
        E("dsh-session-explorer", "dsh-session-explorer", "DSH 会话消息级全文检索浏览器：FTS5 trigram 索引按消息检索（用户/助手/系统注入/工具四类，可按类型筛选），fork/续接会话结果自动去重，只读上下文预览自动滚动定位焦点消息，一键跳转真实会话；支持增量/全量重建索引与健康检查；界面中英双语跟随 Host locale 服务。", "text", 6, "session"),
        E("dsh-session-flow", "dsh-session-flow", "跨会话档案柜：总览工作台、折叠时间线、子代理血缘、全文检索、双模式摘要、ZIP 导出、实时跟踪。会话流标签页嵌入原生会话页：轮次悬浮条、详情并入右栏（实时模式，切换会话可钉住原会话直播）、会话重命名（对齐官方即时同步）、结论摘要行、健康监控与常驻头部胶囊（空闲 / 活跃 / 工具执行 / 疑似卡死四", "archive", 6, "session"),
        E("dsh-session-guard", "dsh-session-guard", "高峰自动会话门：周末模式 + 高峰自动暂停（全局）+ 会话级冻结/恢复 + 后端自动重试；错峰自动续跑。", "session", 6, "session"),
        E("dsh-theone", "dsh-theone", "所有事在一个对话框（主聊天）里聊：每条消息自动分到所属话题，每个话题在后台有独立的会话和上下文；已有的 DSH 旧会话也会自动整理、分类成话题。", "fileops", 6, "session"),
        E("dsh-codebuddy", "dsh-codebuddy", "非官方 provider 插件：把腾讯 CodeBuddy 开放平台的模型接入 DeepSeek Harness，支持自动探测模型，并在设置页填写 API 密钥。", "ai", 6, "model"),
        E("dsh-codex-connect-plus", "dsh-codex-connect-plus", "为 DSH 添加基于 ChatGPT/Codex OAuth 的 Codex 模型及 gpt-image-2 文生图和编辑能力，无需 OpenAI Platform API Key。", "ai", 6, "model"),
        E("dsh-commandcode", "dsh-commandcode", "Command Code for DSH｜订阅接入：通过 llm-pi-ai 供应商配置接入 Go / GOAT / Pro / Max 订阅，支持模型同步预览、收藏与隐藏、逐模型推理预设、主动调用诊断、用量提醒、配置导入导出和联网搜索。", "search", 6, "model"),
        E("dsh-gen-limit", "gen-limit", "按提供方/模型限制并发生成，并附带设置卡片：限定同时进行流式生成的会话数，在流式调用与子代理派生两处强制执行；超出上限的扇出会进入 FIFO 队列等待，而不是直接失败。", "net", 6, "model"),
        E("dsh-grok-kit", "dsh-grok-kit", "面向符合资格的 X Subscription、SuperGrok 或 X Premium 账号的非官方 Grok 集成：共用 Grok CLI OAuth 登录，支持对话及可选的主循环网页/X 搜索；实验性的图片生成、图生图编辑和视频生成均默认关闭，需主动开启。", "image", 6, "model"),
        E("dsh-http-proxy", "dsh-http-proxy", "把 globalThis.fetch 包一层，按目标域名让 DeepSeek Harness 的模型 API 请求走 HTTP/SOCKS 代理、其它请求保持直连，全程不改 Harness 源码。", "net", 6, "model"),
        E("dsh-llm-codex-app-server", "dsh-plugin-codex", "使用本地 Codex 登录的 Codex App Server 模型提供方，支持会话复用、Harness 工具桥接、原生动作轨迹和生成图片持久化。", "image", 6, "model"),
        E("dsh-llm-newapi", "dsh-llm-newapi", "NewAPI（OpenAI 兼容网关）模型接入：注册 `newapi` 路由，仅发现聊天类模型，自动从 models.dev 获取模型参数（上下文窗口、思考强度等）并填充，并在 Web 设置页配置 base URL 与 API Key。", "session", 6, "model"),
        E("dsh-model-sync", "dsh-model-sync", "自动从服务商同步 API Key 提供方的模型列表，无需手动维护。", "ai", 6, "model"),
        E("dsh-model-tidy", "dsh-model-tidy", "DSH 模型整理：整理并精简模型列表——隐藏任意模型、给模型和渠道改备注名（保留厂商计费倍率）、用箭头调整模型与渠道排序；支持搜索、渠道级批量开关、返回顶部与一键恢复。只改显示，不重写任何渠道配置。", "fileops", 6, "model"),
        E("dsh-opencode-go-plus", "dsh-opencode-go-plus", "把 OpenCode Go 订阅模型接入 DeepSeek Harness：每隔几分钟重新解析网关实时目录，内置表里没有的模型按同族自动适配，支持流式输出、工具调用、图片输入与订阅额度显示。这是 dsh-opencode-go 的维护分支：与上游包争用 llm-opencode-go 设置命名空间时", "git", 6, "model"),
        E("dsh-opencode-models", "dsh-opencode-models", "在 settings.yaml 中管理 OpenCode Zen 免费档与 Go 档模型——实时拉取 opencode.ai 的最新模型列表，按路由对比已配置与线上差异，通过四个 agent 工具和设置页分区增删模型条目。", "codec", 6, "model"),
        E("dsh-opendesign-go", "dsh-opendesign-go", "OpenDesign Go 模型提供方：以 Chat Completions 协议接入 12 个订阅模型，从本机 OpenDesign 客户端读取真实的 5 小时 / 7 天额度，支持每模型参数与开关、多账号失败切换。", "ai", 6, "model"),
        E("dsh-openrouter-providers", "dsh-openrouter-providers", "配置 OpenRouter 请求使用的提供商列表与量化位数上限，注入 provider.only/order（allow_fallbacks）与 provider.quantizations 路由参数。", "misc", 6, "model"),
        E("dsh-plugin-local-model", "dsh-plugin-local-model", "DeepSeek Harness 本地模型插件：在设置里管理 GGUF 模型，首条对话自动拉起 llama.cpp，空闲 5 分钟自动卸载释放显存。", "session", 6, "model"),
        E("dsh-plugin-model-capability", "dsh-plugin-model-capability", "DSH 网页端模型能力管理插件：控制推理档位、上下文与输出上限、输入模态及网关兼容预设，双语界面。", "session", 6, "model"),
        E("dsh-plugin-subhub", "dsh-plugin-subhub", "用第三方订阅账户在 DeepSeek Harness 中使用订阅覆盖的模型：文字对话、图片理解、图片生成与图片编辑，可用模型与推理等级随账户自动同步；当前支持 OpenAI / ChatGPT 订阅，更多订阅服务规划中。", "image", 6, "model"),
        E("dsh-set-model", "dsh-set-model", "为 DSH 提供动态模型切换与思考深度调节：set_model / list_models 两个 Agent 工具让模型按任务难度自主切换 provider、model 与 reasoningEffort（思考深度），强制附带切换理由，带 Provider 白名单与上下文窗口 Token 水位护栏，", "session", 6, "model"),
        E("dsh-think-level", "think-level", "按提供方与模型保存思考等级：推理强度不再只属于设置它的那次会话，还会应用到 dsh 从不询问的子代理。会话内的手动选择依然优先，没有配置的模型保持提供方默认值。", "net", 6, "model"),
        E("dsh-tier-router", "dsh-tier-router", "双档模型路由：强档负责规划/咨询/评审、弱档负责实现；含计划模式自动路由、高危操作守卫、失败自动升级与子代理分层。", "net", 6, "model"),
        E("dsh-workbuddy", "dsh-workbuddy", "把 WorkBuddy 国内版和国际版的免费/付费模型接进 DSH —— 无需下载 WorkBuddy 桌面端。", "net", 6, "model"),
        E("dsh-brainagent", "dsh-brainagent", "受大脑启发的认知插件:情景、语义、程序与情绪记忆,带强化学习信号;目标栈支持时间触发器,好奇心驱动的自主网络研究与主动提议。", "time", 6, "memory"),
        E("dsh-context-imports", "dsh-context-imports", "把 AGENTS.md 里 @路径 引用的文件读出来，在会话启动时注入模型上下文；带字节预算、压缩后重新注入和六语言设置卡片。v0.3.x 会展开 DSH 已加载的所有指令文件里的引用，包括会话中途自动带进来的项目 AGENTS.md（需 DSH 0.2.0+）；DSH 0.1.7 请用 0.2.x", "archive", 6, "memory"),
        E("dsh-ecolink-adapter", "adapter", "跨端记忆的 DSH 适配器：支持 DSM 短标签自动捕获入池、记忆注入与写回、网页完整回答保存、DSH 侧栏浏览与手动注入、指定条目读取、通用/非通用分类及事务化记忆压缩；配合需另行加载的 extension/ 目录下 Chrome/Edge 扩展，以及适配器可自动启动的本地 @zoria-lind", "archive", 6, "memory"),
        E("dsh-eli-mode", "packages/eli-mode", "知识库驱动的 Agent 预设：wiki 长期记忆、网页知识库、管理页、可选界面润色。", "session", 6, "memory"),
        E("dsh-longterm-memory", "dsh-longterm-memory", "为 DSH 提供本地 Markdown 长期记忆：Obsidian 兼容仓库、侧边栏管理页、四个记忆工具，以及按预算的每回合召回。", "git", 6, "memory"),
        E("dsh-mem-weave", "dsh-mem-weave", "忆织 MemWeave（dsh-mem-weave）—— 把记忆编织进人格（记忆 × 人格一体 DSH 插件）：分层记忆与人格编辑，每轮注入有固定上限，记忆按层遗忘与整理，候选与冲突需人工确认，写入可在 24 小时内撤销，另有约定与纪念日提醒，全部数据存在本机 SQLite 文件里。", "data", 6, "memory"),
        E("dsh-memory", "dsh-memory", "分层 Claude Code 式记忆：用户级+项目级双作用域（项目记忆随 git 团队共享），MEMORY.md 索引会话启动自动注入，上下文护栏，纯文件零依赖。", "git", 6, "memory"),
        E("dsh-memory-10", "dsh-memory", "跨会话明文记忆：确定性 BM25 关键词召回（无向量嵌入），memory_save/list/search/confirm/forget 五个工具 + 人工确认闸门，global/project 两层 JSON 存储（project 随 git 分享）。", "git", 6, "memory"),
        E("dsh-memory-semantic", "dsh-memory-semantic", "meow-memory 的只读语义检索增强层：为本机记忆条目与对话轮次建 bge-m3 向量索引，提供记忆图谱与逐字原文召回，绝不回写记忆库；需与 meow-memory 搭配使用。", "session", 6, "memory"),
        E("dsh-memory-vault", "dsh-memory", "跨会话记忆库：remember / recall / forget 工具、每轮提示注入与设置页条目浏览。", "session", 6, "memory"),
        E("dsh-notion-connector", "dsh-notion-connector", "配置一次 Notion Integration Token，Agent 即可搜索、读取、查询、创建、更新、追加 Notion 页面与数据库内容，并提供 Web 设置页。", "search", 6, "memory"),
        E("dsh-plugin-2", "dsh-plugin", "将 Memory Lake 作为 dsh 的持久记忆层：基于 memorylake CLI 的 memory_search、memory_remember、memory_forget 三个工具，会话状态行，以及引导安装/诊断 skills，与 Claude Code、Codex 插件共享同一 ~/.", "search", 6, "memory"),
        E("dsh-plugin-memory-3", "dsh-plugin-memory", "五层持久记忆系统：相关性注入、LLM 自动提取、画像轮替与六个 agent 工具。", "session", 6, "memory"),
        E("dsh-prompt-errornotes-desk", "dsh-prompt-ErrorNotes-desk", "把 agent 自报的错误收进分类经验库，并每轮回注系统提示词（每条草稿都先经用户确认或修改）；同时在对话标题栏提供两个面板，用于编辑跨对话全局提示词与本次对话提示词。", "session", 6, "memory"),
        E("dsh-simple-wiki-memory", "dsh-simple-wiki-memory", "超级简化版 llm-wiki 记忆插件：一个索引文档（自动加载）+ 每个主题一个 md 文件（需要时才读）——不会把所有东西塞进上下文烧 token。简单轻量，安装卸载无压力，想怎么改就怎么改。", "pdfdoc", 6, "memory"),
        E("dsh-yogacara", "dsh-yogacara", "以唯识心所与种子藏记录 agent 的状态，并以第一人称倾向写回提示词。", "ai", 6, "memory"),
        E("deep-structural-analysis-skill", "deep-structural-analysis-skill", "多视角深层结构分析技能：16 透镜 4 类别、10 个结构工具，先攻击默认立场，产出置信度校准、事实绑定的分层结论。", "misc", 6, "skill"),
        E("dsh-amphoreus", "dsh-amphoreus", "把 δ-me13（翁法罗斯）的 13 张黄金裔角色技能卡变成席位工作区：逐席配色与壁纸、首轮自动注入技能卡、对话表情、每席记忆便签与预设、Alt+数字切席，以及用于派发与移交的总览画布；技能套件本身从可配置的本地目录读取，不随插件打包。", "archive", 6, "skill"),
        E("dsh-cloudq", "cloudq-for-dsh", "腾讯云智能顾问集成：CloudQ 对话模式，附用量、灵感、制品与架构图面板。", "session", 6, "skill"),
        E("dsh-ppt-master-wrapper", "dsh-ppt-master-wrapper", "把上游 ppt-master 演示文稿技能集封装为可安装的 DeepSeek Harness 插件：逐字节 vendor 技能树，提供 ppt_master_info / ppt_master_check_env / ppt_master_setup_deps 三个生命周期工具、可选的 venv 解", "pdfdoc", 6, "skill"),
