        E("dsh-rate-limiter", "dsh-rate-limiter", "按 provider 令牌桶主动限速，超限请求在发出前延迟排队而非失败，避免触发上游 429。", "misc", 5, "usage"),
        E("dsh-session-cost", "dsh-session-cost", "对话底部的会话费用状态栏：按模型逐条计价估算 Token 费用（CNY），并实时显示 DeepSeek 账户余额（官方余额接口）。", "session", 5, "usage"),
        E("dsh-timeband", "dsh-timeband", "在 DSH 桌面端头像旁显示 DeepSeek API 峰谷时段、切换倒计时与迷你时间轴，点击查看北京时间 24 小时时间轴；节假日日历从 holiday-cn 自动更新，可选在峰时段开始前 5 分钟提醒。", "time", 5, "usage"),
        E("chicheng-gate", "chicheng-gate", "DSH Web 插件：局域网/远程访问控制、frpc 内网穿透、面板密码门禁与手机端 UI 适配。", "devops", 5, "remote"),
        E("dsh-a2a", "dsh-a2a", "为 dsh agent 提供 A2A 协议服务，支持 JSON-RPC 任务、SSE 流式输出、取消任务和 agent card。", "data", 5, "remote"),
        E("dsh-alpha", "dsh-alpha", "DSH 的多机多 Agent 编排与控制平台：发现各设备上的 Agent 与工作区，按机器、仓库、能力和负载将任务路由到本地或远程 Agent Runtime，统一回传进度、审批与结果，并在断线后恢复持久任务。", "git", 5, "remote"),
        E("dsh-auth-tunnel", "dsh-auth-tunnel", "通过快速或命名 Cloudflare Tunnel 为 DSH Web GUI 提供密码保护的公网访问，并代理 HTTP/WebSocket 流量、改用应用内目录选择器。", "net", 5, "remote"),
        E("dsh-channel-wechat", "dsh-channel-wechat", "把微信（腾讯 iLink / ClawBot）接入 DeepSeek Harness 的通道插件：扫码登录，双向收发文本、图片与文件，微信内可用 /cwd、/skills 等命令，审批卡与提问卡在聊天里回答；回复侧会切分超长正文、对限流退避重试，而不是直接丢弃。默认只放行扫码登录的那个微信号，其他人", "image", 5, "remote"),
        E("dsh-links", "dsh-links", "Android 配套桥接：局域网扫码配对（可吊销的设备 Token 与 TLS 指纹）、手机连接与设备管理面板，以及向配对原生 App 提供会话、实时事件与审批的 HTTPS 接入代理。", "net", 5, "remote"),
        E("dsh-mini-remote", "dsh-mini-remote", "给 DeepSeek Harness 用的极简手机遥控器：手机页面上只有你发出的指令和 AI 最后的结论，工具调用、文件读写、子 Agent 调度与思考过程全部留在电脑上；可通过内网、Tailscale 或 Cloudflare 隧道连接，每条路径各配二维码、链接和密码。", "codec", 5, "remote"),
        E("dsh-plugin-remote-access", "dsh-plugin-remote-access", "只把本机 DSH 网页界面开放给指定的一个网段（默认 Tailscale 100.64.0.0/10），不绑 0.0.0.0：网段外的对端一律拒绝，进入方式可选带票网址或 4–12 位数字/字母访问密码；远程页面可强制手机布局而不动本机界面，官方「通用设置」里的外观 / 字号大小 / 工作步骤展示", "misc", 5, "remote"),
        E("dsh-web-service", "dsh-webapi", "让任何会说 HTTP 的东西驱动 DSH：47 条路由（REST + SSE），覆盖工作区、会话（创建/提示、SSE 实时生成、历史、统计、任务清单、中止、问答）、模型与全局默认模型、提供方、Agent Preset、设置命名空间、技能与工作区文件（含分片续传上传），另有 OpenAI 兼容的 /c", "fileops", 5, "remote"),
        E("dsh-wx-bridge", "dsh-wx-bridge", "手机微信驱动本机 DSH：自建 iLink 桥 + 常驻 ACP 原生会话（上下文归 DSH、可 resume），手机会话自动登记进桌面工作区；支持图片识别、直接发文件（Excel/Word/PDF，由会话里的 agent 自行解析）与语音转写。审批可在微信里应答（编号卡片，ask/allow/re", "pdfdoc", 5, "remote"),
        E("dsh-agent-approval", "dsh-agent-approval", "由独立审批子代理裁决每次沙箱提权，可配置审批模型并带审计记录。", "net", 5, "security"),
        E("dsh-guardian-1", "dsh-guardian", "Agent 安全护栏：拦截并审计所有工具调用，命中敏感操作就要求人工确认。", "ai", 5, "security"),
        E("dsh-policy", "dsh-policy", "根据可配置的允许、拒绝和审批规则控制 dsh 工具调用，包括对 shell 命令的匹配。", "misc", 5, "security"),
        E("chrome-faithful", "dsh-plugin-chrome-faithful", "按精确 Profile 名控制你真实已登录的 Chrome 浏览器：MCP 服务器 + MV3 扩展 + 认证本地桥接，提供标签页、定位器、文件注入、媒体导出与持久滚动采集，不使用调试 Profile 或远程调试端口。", "net", 5, "browser"),
        E("dsh-browser-3", "packages/browser/bridge-browser", "侧栏 Chrome/Firefox 扩展，让 DSH 直接操控你当前所在的标签页：页面以带编号的结构化文本交给模型，点击、输入与导航都要你批准后才执行。在上游基础上补了视口截图、在新窗口打开网址、滚动页面内的滚动容器（聊天记录、侧栏列表、弹窗正文等）、输入区的权限模式/模型/斜杠命令控件，以及默认关", "image", 5, "browser"),
        E("dsh-chrome-bridge", "plugin", "操作你已经登录的 Chrome：模型在你真实的标签页里点击、打字、填表、读网页、截图、下载文件，同源 iframe 里的内容也能读能点。支持 macOS、Windows、Linux；需要 Chrome 116+ 与 Node 18+。走 native messaging 与 chrome.debug", "image", 5, "browser"),
        E("dsh-deepseek-search", "dsh-deepseek-search", "在 ctx.web 接缝上注册 DeepSeek Search / Fetch API 的搜索与抓取 provider，用 DeepSeek 的 Search / Fetch JSON API 替换 web_search 与 web_fetch 两个后端；支持可配置的重试与退避、下次调用即生效的实时", "data", 5, "browser"),
