        E("dsh-opencli-1", "dsh-opencli", "登录态真实浏览器自动化:170+ 站点结构化命令一步到位（需安装 OpenCLI CLI：npm i -g @jackwener/opencli，及其 BrowserBridge 浏览器扩展）;执行真实性判定(失败说真话)、站点知识卡+健康度、watch 监控、轨迹回放、带出处报告导出;写命令带审批", "sysinfo", 5, "browser"),
        E("dsh-plugin-tavily", "dsh-plugin-tavily", "基于 Tavily 的网页搜索提供方：替换内置 web_search 的后端，并提供 API Key、结果数量与时间窗口的设置卡片。", "time", 5, "browser"),
        E("dsh-tool-control-chrome", "dsh-tool-control-chrome", "通过 MV3 扩展和本地 loopback Bridge 驱动用户已登录的真实 Chrome/Edge Profile、标签页与 Cookie，为 DSH 提供 browser_* 工具、Skill 和 /chrome 命令。", "fileops", 5, "browser"),
        E("dsh-video-downloader", "dsh-video-downloader", "检测并下载 B站/YouTube/抖音/小红书视频媒体，带清晰度与格式分析。", "media", 5, "browser"),
        E("dsh-web-fetch-moli", "dsh-web-fetch-moli", "基于超轻量 Rust 无头浏览器 Moli 的 web_fetch 提供方：专为微前端与复杂 SPA 渲染设计，内存占用仅约 60MB。", "sysinfo", 5, "browser"),
        E("dsh-git-forge", "dsh-git-forge", "项目级 Git 凭据：forge 账号（GitHub、Gitea、GitLab、Bitbucket 或自定义域名）在右侧栏「Git 凭据」标签页里管理并可按项目授权，再由生成的凭据 helper 交给 agent 走 HTTPS 推送，token 不进对话；未授权 host 的推送会被拦截器直接拒绝", "git", 5, "git"),
        E("dsh-git-graph-1", "dsh-git-graph", "DSH Web 原生右侧栏的只读 Git Graph，支持提交历史、分支与标签、文件 Diff、两提交比较和完整历史原文。", "git", 5, "git"),
