        E("dsh-undo-plugin", "dsh-undo", "对话与工作区撤销：通过 /undo 节点轴、会话头部按钮或消息下方图标回滚到任意已发送 prompt 之前；插件私有 Shadow Git 快照恢复文件，被回滚回合不会进入模型上下文，误操作还能“撤回回滚”。附带归档会话管理与工具卡片分类配色。", "git", 4, "session"),
        E("dsh-vision-hub", "bridge-preview", "图片桥接内联预览:对话中 \\[图片: 路径] 标记渲染后自动显示图片,长指令不留在对话里。", "image", 4, "session"),
        E("obsidian-dsh-acp", "obsidian-dsh-acp", "在 Obsidian Agent Client（及其他 ACP 客户端）里驱动 DeepSeek Harness 的 ACP 适配器：会话 list / resume / fork / delete、按会话切换模型、一句话摘要预览、导入外部 ACP 会话，并可把 Obsidian 侧会话拉进 dsh", "session", 4, "session"),
        E("shl-session-history", "shl-session-history", "会话历史迷你滑轨：对话区左侧垂直居中的短横线，每条横线代表一条真实用户请求，悬停预览请求内容，点击跳转到对应轮次。", "session", 4, "session"),
        E("dsh-agy-provider", "dsh-agy-provider", "将本机已登录的 AGY CLI 接入 DSH 作为模型 Provider：支持 Gemini/Claude 模型发现、独立推理强度、DSH-owned 工具、受限上下文与工具结果管理、Windows 安全流式传输；如遇问题，请在 GitHub 提交 Issue：https://github.com/", "git", 4, "model"),
        E("dsh-anthropic-membership", "dsh-anthropic-membership", "用 Claude Pro/Max 会员登录 DeepSeek Harness（无需 API key），将 Anthropic 请求图片长边压到 2000px，精简 /compact 摘要请求，并显示 5 小时/每周套餐用量百分比与 DSH 消息数。", "image", 4, "model"),
        E("dsh-bundle-antigravity-host", "dsh-antigravity-acp", "把 Google 官方 Antigravity ACP agent 接入 DeepSeek Harness 作为模型提供商，工具执行与审批仍由 DSH 负责，附按模型切换的额度药丸和设置页；需 Node 22.19+ 并登录 Antigravity 账号。", "ai", 4, "model"),
        E("dsh-codebuddy-link", "dsh-codebuddy-link", "通过 ACP 将腾讯 CodeBuddy CLI 接入 DeepSeek Harness，支持 CLI 原生工具执行、多账户管理和 codebuddy_ask 独立问答。", "misc", 4, "model"),
        E("dsh-codex-shim", "dsh-codex-shim", "为选定的模型路由模拟 Codex 环境，以提升 GPT 系列模型的工具调用成功率。", "ai", 4, "model"),
        E("dsh-connect-doubao", "dsh-connect-doubao", "复用本机豆包桌面客户端已有的登录态，作为 DeepSeek Harness 的模型 provider，并提供 5 小时限额与周额度的只读额度概览。仅 Windows x64：凭据解密依赖 DPAPI。", "codec", 4, "model"),
        E("dsh-glm-mode", "dsh-glm-mode", "为 zhipuai/glm-5.3-flash 调优的「GLM 模式」Agent 预设：PTC 程序化工具调用、思考死循环守卫与工具空转守卫双层防护（源自活体事故复盘）、GLM 专属自动压缩（75%/22%）。", "archive", 4, "model"),
        E("dsh-llm-opencode-go-1", "dsh-llm-opencode-go", "DSH 的 OpenCode Go 订阅聊天：按模型选择 Completions、Responses 或 Anthropic 协议，支持模型发现、上下文、视觉与思考元数据、effort 默认值和用量仪表。", "codec", 4, "model"),
        E("dsh-llm-qwen-local", "dsh-llm-qwen-local", "面向 vLLM OpenAI 兼容端点上本地部署的 Qwen 模型的 LLM 适配器插件,支持按模型多模态开关、完全可配置的推理档位,以及可在前端编辑部署配置的 Web 设置页。", "ai", 4, "model"),
        E("dsh-model-capabilities", "dsh-model-capabilities", "在设置里新增「模型能力」一页，为每个模型声明思考档位与视觉能力。", "ai", 4, "model"),
        E("dsh-model-capability", "dsh-model-capabilities", "为 DeepSeek Harness Web UI 的自定义模型设置添加输入模态选择器。", "ai", 4, "model"),
        E("dsh-model-router-2", "dsh-model-router", "维护一个模型池，把每个 agent 步骤路由到池内模型并设置其思考等级——全部在输入栏点选配置，不需要写 JSON。路由面板接管输入栏的模型位置，同一个控件里既有本会话的模型与思考等级，也有路由自身的设置。三种授权范围（模型 / 思考 / 全部）：手动选择只在所属范围内生效；「思考」范围下路由只作用", "data", 4, "model"),
        E("dsh-model-router-3", "dsh-model-router", "DSH 关键词路由与隔离生图插件：确定性关键词路由、白名单模型切换与隔离的 image_gen 生图通道。", "ai", 4, "model"),
        E("dsh-model-think-level", "dsh-model-think-level", "在官方「模型」页为第三方模型补上思考等级、图片输入与生图；一个供应商可配多把密钥，按模型分流、失败自动换密钥重试，并可配置按路由的请求头、查看余额。", "image", 4, "model"),
        E("dsh-multi-agent-gateway", "dsh-multi-agent-gateway", "把六个 AI 编程平台接进 DSH——OpenCode、Qoder、Qoder CN、TRAE、WorkBuddy 与国际版——每个平台在原生模型选择器里各自成组；在一个设置页里统一管理账号，平台有签到接口就每日签到、可查积分余额，账号被限流时自动改用同平台其它账号。平台声明了积分倍率的模型会标注倍", "codec", 4, "model"),
        E("dsh-ollama-cloud", "dsh-ollama-cloud", "Ollama Cloud 供应商：安装即配好聊天路由，按 Ollama 模型自身元数据公布每个模型的思维链档位（供 composer 的推理强度选择），模型清单可由端点自动刷新（/api/tags 与 /api/show，并带离线缓存），在 Models 页与侧栏显示账号额度并提供 API Key", "ai", 4, "model"),
        E("dsh-opencode-zen-plugin", "dsh-opencode-zen-plugin", "为 DeepSeek Harness 接入 OpenCode Console (Zen) 模型：在「设置 → 插件」填入 Console API Key 后即可选用 Console 的对话模型，模型目录自动同步，每个模型按官方文档路由到对应端点，免费 *-free 模型默认不列出（它们只能在 Ope", "codec", 4, "model"),
        E("dsh-provider-rate-limit", "dsh-provider-rate-limit", "按供应商与模型粒度限速 LLM 请求，预约式令牌桶支持排队或拒绝两种模式，附带网关身份规则（改写 User-Agent、注入自定义请求头）。", "ai", 4, "model"),
        E("dsh-qwen38-ninfer-compaction-fix", "dsh-qwen38-compaction-fix", "针对 NInfer 托管的 qwen3.8-27b 网关的压缩修复：在 dsh 上下文压缩与会话标题调用中关闭思考，避免 xhigh 推理耗尽全部输出预算；同一思路适用于其他启动方式，本包仅面向 NInfer。", "archive", 4, "model"),
        E("dsh-sensenova-pool", "dsh-sensenova-pool", "把商汤日日新（SenseNova）模型接入 dsh，并提供按 Key 轮换的 Key 池：粘贴任意多把 API Key，请求在多把 Key 之间轮转；遇 429 限流立即换下一把 Key 重试，每把 Key 独立指数退避冷却；本地 RPM 预限流从源头避开限流，池子耗尽时回报 503 与 Retry", "ai", 4, "model"),
        E("dsh-zcode-startplan", "dsh-zcode-startplan", "把 ZCode 赠送的免费 plan 接进模型选择器：多账号池轮换、按账号的限流与额度展示、bigmodel/zai 双渠道设备登录。", "ai", 4, "model"),
        E("dsh-adaptive-context", "dsh-adaptive-context", "带治理的长期记忆：只追加证据账本、写入闸门、7 级权威声明与取代链，pre-step 按领域配额预算注入。", "session", 4, "memory"),
        E("dsh-agentmemory", "dsh-agentmemory", "DSH ↔ agentmemory 会话记忆桥：把会话生命周期镜像到本地 agentmemory 守护进程（REST），提供 memory_recall / memory_remember 工具，并通过 agent/pre-step 按会话注入记忆上下文窗口。", "sysinfo", 4, "memory"),
        E("dsh-full-life-memory", "dsh-full-life-memory", "记忆插件：上下文放不下时把旧轮次蒸馏成 Token 线索并从历史中切除，需要时用线索重建记忆。", "session", 4, "memory"),
        E("dsh-lite-memory", "dsh-lite-memory", "让东坡肉滚出系统提示：记忆不常驻，命中只给标题，正文读了才进上下文，项目规范还能自己长。", "session", 4, "memory"),
        E("dsh-mnemosyne-2", "dsh-mnemosyne", "Mnemosyne 记忆插件 for DeepSeek Harness：提供 remember / recall / forget / stats / sleep 工具、内嵌技能、Settings 面板和可选的自动记忆功能。", "session", 4, "memory"),
        E("dsh-puzzle-mode", "dsh-puzzle-mode", "把项目决策落成纯 markdown 而不是留在聊天记录里：一份主文档加若干模块文档，每条都带 文件:行 出处。AI 主动提问把悬而未决变成已定；五维健康性（任务复杂度 / 可拓展性 / 维护系数 / 代码质量 / 可复用性）由文档证据算出，显示在输入框模型选择器旁边的小按钮上。一个会话可同时绑多个项", "pdfdoc", 4, "memory"),
        E("dsh-recall", "dsh-recall", "对话历史回忆：字面/模糊/语义三层检索全部历史会话的原始文本，完全本地离线——AI 再也不会忘记你说的话。一条命令安装（自带 `dsh.bundle.patch`），语义推理跑在 worker 线程。", "session", 4, "memory"),
        E("dsh-suzu-memory", "dsh-suzu-memory", "为 DeepSeek Harness 提供会话独立的长期记忆、记忆管理、人设设置和压缩提示词。", "archive", 4, "memory"),
        E("dsh-tool-user-memory", "dsh-tool-user-memory", "面向 DSH 的本地 Markdown 用户与项目记忆：置顶偏好、关键词检索、软失效、历史归档，以及带预览、备份与回滚的 JSON 迁移。", "pdfdoc", 4, "memory"),
        E("mosaic-memory-compress", "mosaic-memory-compress", "为 DeepSeek Harness 提供基于自然遗忘曲线的就地对话压缩：近期对话逐字保留、中期结构化脱水（零 LLM 成本）、久远对话折叠为有界摘要对——有限记忆预算上的无限对话。", "archive", 4, "memory"),
        E("veyra", "Veyra", "面向编程代理的工程智能——为 DeepSeek Harness 提供持久化、证据感知、项目隔离的工程记忆，以及统一的混合搜索（记忆 + RAG 文档）。", "net", 4, "memory"),
        E("dsh-douyin-oem-touliu-report", "dsh-douyin-oem-touliu-report", "抖音本地推 OEM 广告日报/周报自动生成（作者：Kirin）：一次 Edge 登录后自动采集三大数据源（来客客资、计划级投放明细、视频分析），计算指标并生成 A4 排版 docx 报告，支持自由选择定时运行时间和邮件通知。", "pdfdoc", 4, "skill"),
        E("dsh-fix-duplicate-loader-id", "dsh-fix-duplicate-loader-id", "检测并修复 dsh 启动的 \"duplicate loader entry id\" 崩溃：扫描 profile 各 bundle 的重复 loader row，转换为 id-targeted patch，附带零依赖 CLI（检测/预览/修复/复检）。", "archive", 4, "skill"),
        E("dsh-goal", "dsh-goal", "DeepSeek Harness 的目标模式与自主执行插件：顶部吸附横幅在每轮对话中保持当前目标可见，同时 Agent 自主推进完成目标。", "session", 4, "skill"),
        E("dsh-skill-evolution", "dsh-skill-evolution", "观察 agent 执行轨迹，在每个成功回合结束时按信号触发 LLM 评审，把值得复用的工作流结晶为已注册技能，并随后续运行持续改进。", "ai", 4, "skill"),
        E("dsh-skill-manager-4", "dsh-skill-manager", "DeepSeek Harness 技能生命周期管理：技能库（纯技能池）、工作区启用白名单、会话勾选三层模型；Web 设置面板与对话页内嵌视图，支持技能文件浏览/编辑、zip 与文件夹批量导入、引擎实际加载校验。", "archive", 4, "skill"),
        E("dsh-skill-market", "dsh-skill-market", "浏览、搜索并安装公开的 SkillHub 技能库,启用、停用、更新或卸载都不必离开 Harness。分类按钮带该分类的上游总数;详情抽屉提供文件树、版本历史、权限、第三方安全扫描结论与上游指标等页签。装好的技能会作为一个普通本地技能写入 harness 的技能根目录,而「停用」是把它的目录移出该根目", "fileops", 4, "skill"),
        E("dsh-skillopt", "dsh-skillopt", "为 DeepSeek Harness agent 提供夜间自我进化：离线复盘过往会话，在你的 API 预算内重放高频任务，并把学到的技能凝练成经得起门禁验证的技能。把 microsoft/SkillOpt 的 SkillOpt-Sleep 引擎带进 dsh，作为原生工具加内置技能——无需模型训练。需", "session", 4, "skill"),
        E("dsh-skills-manager", "dsh-skills-manager-plugin", "根据提示词自动激活已安装的 Skill，应用 Skill 声明的生命周期 Hook 与工具策略，并通过设置页或 skill_manager 工具管理 GitHub 托管的 Skill。", "ai", 4, "skill"),
        E("dsh-skills-nexus", "dsh-skills-nexus", "通用 skill 适配器，将含 SKILL.md 的 GitHub 仓库克隆并 symlink 到官方 skills 根目录，注册为 DSH skill。", "git", 4, "skill"),
        E("dsh-video-pipeline", "dsh-video-pipeline", "把一条短视频生产流水线的 19 个 skill（1 总入口 + 1 编排 + 17 原子）内置进 agent 技能目录：中文配音读音校正、文生图与文生视频、图片运镜、成片合成、封面、成片核验、数据复盘、四平台发布。本包只提供 skill 与脚本，不安装任何工具：要真跑通流水线，还得本机装好 ffmp", "image", 4, "skill"),
        E("stata-ai-skill", "dsh-plugin", "在 DeepSeek Harness 中运行 Stata：Stata AI Skill 原生服务随 DSH 自动启动（内置 macOS/Windows 多平台二进制），无需手动配置即可跑回归、do 文件与计量工作流。", "fileops", 4, "skill"),
        E("dsh-comfyui-image", "dsh-comfyui-image", "通过本地 ComfyUI 的 HTTP 接口把工作流排到用户自己的 GPU 上，由 Agent 直接生图：Z-Image-Turbo 适合快速草稿，Qwen-Image-2.1 适合成图与图中文字排版。 注册 comfyui_generate、comfyui_status 两个工具和一个涵盖模型选择", "ai", 4, "vision"),
        E("dsh-draw-router", "dsh-draw-router", "DeepSeek Harness 统一绘图路由器：自动识别任意 OpenAI 兼容接口的绘图模型，提供 draw_image 和 draw_list_sources 工具，支持商汤、阶跃、Agnes、千问、Flux、SD、Imagen 等。", "ai", 4, "vision"),
        E("dsh-image-pathify", "dsh-image-pathify", "让纯文本模型也能处理聊天贴图，提供原生视觉体验，支持批量看图，走内置 OpenAI 兼容识图工具 analyze_image；具备视觉能力的模型不受影响。", "ai", 4, "vision"),
        E("dsh-image-viewer", "dsh-image-viewer", "增强 DSH 原生图片查看体验，支持指针中心缩放、拖动、画廊、下载、键盘操作和图片区域备注。", "image", 4, "vision"),
        E("dsh-plugin-deepseek-vision", "plugins/dsh-plugin-deepseek-vision", "面向纯文本 DeepSeek 的视觉 MCP + DSH 插件：analyze_image / analyze_clipboard / compare_images / vision_status 四个工具、可视化配置页、默认免费 GLM-4.6V-Flash、结果缓存与限流容错，Key 不入日志。", "devops", 4, "vision"),
        E("dsh-video-vision", "dsh-video-vision", "五个工具，把视频当成原料而不是节目来读。video_outline 把整片映射成文字、一张图都不画：4-60 个等分窗口，每行给切点数量、语音占比、强度条和标签，再给出值得先看的窗口以及下一步的精确 start/end —— 零图像 token。video_probe 不解码画面就给元数据和阅读计划", "image", 4, "vision"),
        E("dsh-vision-bridge-2", "dsh-vision-bridge", "将会话图片转交可配置视觉服务，并向符合条件的 DeepSeek Harness 模型路由返回纯文本分析。", "image", 4, "vision"),
        E("dsh-vision-hub-2", "tool-vision", "增强版视觉工具箱:14 个像素级视觉工具(看图问答/定位/检测/裁剪/像素比对/OCR/长截图OCR/矢量化/取色/抠图/截图/展示/落盘/网页截图),单一 OpenAI 兼容端点驱动,桥接标记极简、规则下沉系统提示,带内容安全识别与限流自动重试。", "image", 4, "vision"),
        E("free-vision-skill", "free-vision-skill", "基于 macOS Vision Framework 的全本地识图插件：`ocr_image`（文字提取，表格结构+坐标）与 `view_image`（场景/人脸/二维码）；web 输入框可直接粘贴多张图片，图片永不离开你的 Mac。", "image", 4, "vision"),
        E("phone-eye", "phone-eye", "让 AI 助手看见并操作真实安卓手机：phone_look（视觉+UI 树融合判读）、点击/滑动/输入、截图——经 adb，适用于任何 MCP 客户端。", "image", 4, "vision"),
        E("visual-review", "visual-review", "在 DSH Web 聊天界面内联渲染粘贴/上传的图片，并让纯文本模型“看见”图片：visual_review 工具优先调用任意 OpenAI 兼容多模态 API，未配置时回退本机 Qwen3-VL。", "image", 4, "vision"),
        E("dsh-attachment-formats", "dsh-attachment-formats", "DeepSeek Harness Web 插件——PDF 文字层与扫描件 OCR、Office 文档转 Markdown、TIFF/epub 与长文档索引卡。", "pdfdoc", 4, "docs"),
        E("dsh-cowork", "dsh", "doc_read/doc_write：以有界、单元格寻址的方式读写 xlsx / pdf / docx / pptx / ipynb，另附 MCP 服务器与 CLI。", "pdfdoc", 4, "docs"),
        E("dsh-data-insight-1", "dsh-data-insight", "把原始数据（CSV / 粘贴表格 / SQL 结果 / DuckDB）转成带业务结论、指标与图表的结构化 Markdown 报告。", "pdfdoc", 4, "docs"),
        E("dsh-ima", "dsh-ima", "在 DSH 侧边栏浏览腾讯 ima 的知识库与文件，内置常见格式预览，并让 agent 用 5 个工具按名称或正文检索、读取库内资料。", "fileops", 4, "docs"),
        E("dsh-mermaid-image-preview", "dsh-mermaid-image-preview", "当 DSH Web 中的消息包含 Mermaid 语法时，通过本地渲染以图像形式预览 Mermaid Diagrams，并允许接入外部渲染服务器。", "image", 4, "docs"),
        E("dsh-openspec", "dsh-openspec", "在 Web UI 会话标题栏打开当前项目的 openspec/ 目录，浏览、预览、编辑并保存其中的文件，自动跟随会话工作区。", "fileops", 4, "docs"),
        E("dsh-overleaf-1", "dsh-overleaf", "把 Overleaf 站点（公有云或自托管实例）经同源反向代理嵌入会话页标签，支持 Cookie 或弹窗登录、选区引用、光标处插入、编译日志驱动的修复、文档大纲跳转与 .bib / .tex 双向同步。", "pdfdoc", 4, "docs"),
        E("dsh-plugin-dev-kb", "dsh-plugin-dev-kb", "以 dsh-plugin-dev-kb 技能内置 DeepSeek Harness 官方文档离线镜像：站点中英 168 页 + 仓库补充文档 52 篇，带主题导航与全文检索，编写插件时随时查阅。", "git", 4, "docs"),
        E("dsh-tool-markdown", "dsh-tool-markdown", "HTML↔Markdown 转换、GFM 表格规范化、目录生成。", "pdfdoc", 4, "docs"),
        E("dsh-calculator", "dsh-calculator", "右侧面板展示 DeepSeek API 费用（当前会话 + 全部会话累计）与账户余额，内置官方计价与峰谷计价支持。", "session", 4, "usage"),
        E("dsh-deepseek-billing-1", "dsh-deepseek-billing", "侧边栏底部 DeepSeek 账户余额显示与会话费用估算卡片。", "session", 4, "usage"),
        E("dsh-deepseek-quota-bar", "dsh-deepseek-quota-bar", "可拖动透明余额卡片：余额/月初额度血条、今日/本月用量（配置平台 token 后为官方精确数据）、当前对话费用。", "session", 4, "usage"),
        E("dsh-discipline-guard", "dsh-discipline-guard", "DSH Agent 纪律卫士：在 harness 边界强制四道闸门（循环熔断、Token 成本熔断、路由切换警示、计划审批卡），模型无法用文字绕过；🛡 芯片一键解除，daily 档对有缓存路由零打扰，把无缓存失控从每回合数百万 token 封顶到约 50 万。", "ai", 4, "usage"),
        E("dsh-ibka-balance", "dsh-ibka-balance", "输入框下方常驻余额卡片：实时显示 DeepSeek API 账户余额，每 5 分钟自动刷新，支持手动刷新，余额过低自动变色提醒。", "misc", 4, "usage"),
        E("dsh-token-billing", "dsh-token-billing", "DSH Web 实时 token 计费插件：官网人民币价直接计费、高峰/错峰自动切换、价格实时跟随官网、可视化自定义模型价格、多币种兜底。", "ai", 4, "usage"),
        E("dsh-token-pulse", "dsh-token-pulse", "DSH 设置内的本地 Token 用量热图：GitHub 风格周/月/季度/年视图、每日小时级展开、模型与供应商 Top 5，历史持久化，删除会话不丢数据。零联网、零计费。", "session", 4, "usage"),
        E("dsh-token-usage-stats", "dsh-token-usage-stats", "仿 DeepSeek 官方 Token 统计，跨会话 Token 消耗、请求次数与峰谷分时费用统计看板。", "text", 4, "usage"),
        E("dsh-tokenrhythm-bill", "dsh-tokenrhythm-bill", "基元律动费用中心：账户余额与限时额度、按分类筛选的模型价格卡（含折扣价）、服务状态与平台密钥管理，支持平台账号或 Cookie 登录，凭据存本机 host。", "ai", 4, "usage"),
        E("dsh-tps-ttft", "dsh-tps-ttft", "为 DeepSeek Harness 提供每轮 TPS/TTFT 统计：模型耗时、工具耗时、首 token 延迟、输出速度。", "text", 4, "usage"),
        E("dsh-workspace", "dsh-workspace", "侧边栏用量面板：DeepSeek 余额与今日费用、项目文件浏览、Git 变更与历史、内置终端，以及 Harness 一键更新。", "git", 4, "usage"),
        E("dsh-astrbot-ingress", "dsh-astrbot-ingress", "把本机 DeepSeek Harness agent 接到 AstrBot，从 QQ 等 IM 渠道驱动它：用 /dsh 派活、引用或 @ 机器人续聊、在聊天里回答审批与 ask_user_question（与 DSH 网页并行），结果、内联图片与文件卡片发回。含会话 / 工作区 / 模型 / 权限", "image", 4, "remote"),
        E("dsh-lan-guard", "dsh-lan-guard", "把官方 DSH Web UI 安全地开放到局域网：不改动 DSH 自身的回环绑定，另开一个带密码门禁、自签 HTTPS 与可逐个吊销的设备配对的反向代理端口，并提供手机扫码入口。", "net", 4, "remote"),
        E("dsh-on-imessage", "dsh-on-imessage", "在 iPhone 信息里直接和本机 DeepSeek Harness（dsh）对话：切换工作区/会话、开新会话、原生信息气泡回复，无需额外 App、服务器或云服务。", "session", 4, "remote"),
        E("dsh-plugin-wechat-bridge", "dsh-plugin-wechat-bridge", "把微信私聊桥接进 DSH agent 会话并流式回传回复，支持热插拔与设置页签。", "session", 4, "remote"),
        E("dsh-qq-bot", "dsh-qq-bot", "把 DeepSeek Harness 接到 QQ。支持 OneBot 11/12、Satori、Milky 与 QQ 官方机器人接口，群聊和私聊各有一条独立会话；内置九个工具：群管理、聊天记录与图片理解、联网搜索、网页抓取、图片反搜、生图等，另有按间隔自主接话的主动发言（判断与发言可分用两个模型）。", "image", 4, "remote"),
        E("dsh-qqbot-bridge", "dsh-qqbot-bridge", "通过 QQ（官方 Bot API v2，仅单聊）远程控制 DeepSeek Harness 会话与工作区：列出/切换工作区、新建会话、压缩历史、切换模型，支持流式输出、Markdown 与审批转发。未做按用户门禁——任何能给该机器人发消息的人都能控制这些会话，消耗你的模型额度与文件权限。", "pdfdoc", 4, "remote"),
        E("dsh-qqbridge", "dsh-qqbridge", "通过 SSH 把 qq-bridge 引擎部署到远程主机并接入 DeepSeek Harness：环境体检、不把密钥写进仓库的配置生成、桥接主进程与每日归档/当天同步/看门狗三个定时器的 systemd 单元，以及体检、生成配置、部署、看状态四个工具。另带 lite 回复模式（直连 DeepSeek", "git", 4, "remote"),
        E("dsh-remote-agent", "dsh-remote-agent", "把另一台电脑变成你的远程 Agent 同事：副机本地跑自己的 DSH 与完整 Agent 循环，所以链路断开时任务照常继续、模型凭证也永不离开那台机器。主机用 8 个 remote_* 工具派活，只收回 handoff 摘要与产物清单，成品按需拉取——中间产物留在副机。配对码接入，direct 或", "ai", 4, "remote"),
        E("dsh-remote-local-plugin", "packages/local-plugin", "把 SSH 主机上的工作区接入 DSH：远程工作区、镜像会话、终端与文件访问、审批和原生 DSH 界面。需 DSH Desktop 0.2.1-rc.2，远端主机为 Linux 或 macOS。", "fileops", 4, "remote"),
        E("dsh-swarmdrop", "dsh-swarmdrop", "在 agent 和你自己的手机之间开一条设备通道：agent 把刚产出的文件发过去，手机传回来的东西可以在输入框里 @ 引用。底层经 SwarmDrop CLI 走端到端加密的 P2P，不需要账号，也不需要公网 IP；节点状态、已配对设备与扫码配对都在侧边栏面板里。", "codec", 4, "remote"),
        E("plugin", "plugin", "在手机上审批工具调用、看流式输出、回答问题；载荷级端到端加密，中继可自托管。", "codec", 4, "remote"),
        E("dsh-perm-gate", "dsh-perm-gate", "已追加 cc-safety-net 风格的机械安全网规则，同时支持无模型、有模型辅助方式的安全审查，模式为自动审查、机械直通等。P0–P4 确定性优先权限门控，含 Permissive 档位、学习沉淀与审批历史 UI；凭据/受保护路径硬拒绝，内部只读工具自动放行。", "fileops", 4, "security"),
        E("dsh-permissions", "dsh-permissions", "Claude Code 风格权限规则引擎：hard/deny/ask/allow 四级规则（hard 高于全访问、不可豁免）、workspace 作用域、通配符路径保护、可视化草稿式编辑器，规则持久化于 settings.yaml。", "data", 4, "security"),
        E("dsh-plugin-security-review", "dsh-plugin-security-review", "DSH 插件安全审查与运行时守卫：安装前静态审查（反混淆解码、供应链检测）、Web 一键审查/安装/卸载，以及可选的运行时工具调用拦截。", "codec", 4, "security"),
        E("dsh-plugin-vetting", "dsh-plugin-vetting", "为了您的电脑安全，装插件前先体检：静态扫描恶意模式（外传/凭据/混淆/持久化）与高权限误用，覆盖传递依赖与官方包哈希基线（防供应链篡改），可选插件工具调用闸。", "codec", 4, "security"),
        E("dsh-verification-receipt", "dsh-verification-receipt", "把每轮工具计数与粗粒度验证信号写入本地 JSONL，不保存提示词、工具参数或结果正文。", "data", 4, "security"),
        E("sandbox-micro", "sandbox-micro", "microsandbox 沙箱支持。", "misc", 4, "security"),
        E("deepseek-harness-zhipu-plan-tools", "deepseek-harness-zhipu_plan_tools", "智谱（GLM Coding Plan）三件套以原生 provider 与工具接入：内置 web_search / web_fetch 后端切换为智谱联网搜索与网页 Markdown 读取，可选注册 github_search_doc / github_get_repo_structure / git", "pdfdoc", 4, "browser"),
        E("dsh-browser-2", "dsh-browser", "让 agent 在一台真实 Chrome 或 Edge 里干活，侧栏同步镜像，你能看着，也能随时接手：每个对话一台独立的浏览器进程，各自的 profile 与 CDP 端口，登录态不会在对话之间串。它驱动机器上已有的 Chrome 或 Edge，不下载浏览器，不需要配套应用或扩展；侧栏镜像开着时，另", "net", 4, "browser"),
        E("dsh-browser-use-1", "dsh-browser-use", "为 DeepSeek Harness 提供真实浏览器操作能力：网页浏览与信息提取、表单填写、多标签页协作和多步骤任务执行；支持增量 DOM、会话隔离、截图、操作结果检查与证据归档回读。", "image", 4, "browser"),
        E("dsh-cloak-browser", "dsh-cloak-browser", "基于 CloakBrowser 的原生浏览器工具：按 Agent 隔离会话，提供有界快照、ref 交互、截图与安全路由。", "image", 4, "browser"),
        E("dsh-exa-mcp", "dsh-exa-mcp", "通过内置的 @deepseek-ai/dsh-mcp-client 桥接接入托管的 Exa 搜索 MCP 端点（mcp.exa.ai）：web_search_exa 与 web_fetch_exa 工具，免费额度匿名可用，设置 EXA_API_KEY 可解锁更高限额。", "search", 4, "browser"),
        E("dsh-native-browser", "dsh-native-browser", "DSH 浏览器插件（Browser）：以 Codex 浏览器操作为体验参考，直接使用已登录的 Chrome 浏览器，平滑虚拟鼠标，支持页面读取、填表、截图与控制交还；安装后从侧栏「浏览器」完成配置。需要 macOS + Google Chrome（125+），并一次性以解压加载方式安装随包的 MV3", "image", 4, "browser"),
        E("dsh-search-enhance", "dsh-search-enhance", "提供 Grok-compatible 网页搜索、保留来源分页、Context7 与 Exa 文档检索、有界网页提取、站点映射、离线研究计划和只读诊断。", "search", 4, "browser"),
        E("dsh-web-fetch-fakeip", "dsh-web-fetch-fakeip", "ctx.web 的 fake-ip 感知抓取后端，接管官方 http provider id：当某主机名的每一条 DNS 应答都是代理 fake-ip 段（默认 198.18.0.0/15）内的占位地址时予以接受，从而在 mihomo/Clash TUN 模式下无需关闭 fake-ip、也无需设置代", "net", 4, "browser"),
        E("dsh-web-search-ollama", "dsh-web-search-ollama", "让 DSH 的 web_search 工具走 Ollama 联网搜索 API，复用 OLLAMA_API_KEY，无需 DeepSeek 官方 Key。", "search", 4, "browser"),
        E("dsh-git-change-1", "dsh-git-change", "输入框工具行的 git 状态角标：模型选择器左侧一枚 14px 分支图标，悬停显示分支名、变更文件数与增删行数。统计含未跟踪文件；非 git 工作区不显示。", "git", 4, "git"),
        E("dsh-git-plugins", "bundle", "DeepSeek Harness 的 Git 与源码管理插件套件：本地 git 操作，外加 GitHub、GitLab、Bitbucket、Azure DevOps 与 Gitea 适配器，并带自演进记忆。", "git", 4, "git"),
        E("dsh-git-status", "dsh-git-status", "专精于 Git 分支与状态处理：Web 右缘 Git 状态浮窗，commit DAG 泳道图、未提交改动与 stash、行内 diff，右键分支/tag 切换、合并、重命名、删除、新建，一键拉取全部远程。", "git", 4, "git"),
        E("astro-ph-researcher", "astro-ph-researcher", "面向天文的 DSH/Codex 研究工作台：NADC 术语、参考文献库、写作、评分、作者确认、推荐书籍、FITS/XML 格式与分析引导。", "data", 3, "tools"),
        E("cli-doctor", "cli-doctor", "DSH 侧栏的只读 CLI 工具链体检面板：按生态列出 Homebrew、npm 全局、pip、 Rust/Bun/uv 与自更新类 CLI 的本机版本，标出哪些有可用更新，并展示已安装包 的依赖影响。只报不升，不会改动本机任何工具。DSH 插件在 npm 上以 `dsh-cli-doctor` 发", "misc", 3, "tools"),
        E("codegraph", "codegraph", "面向 agent 的本地代码知识图谱：把代码库（Python/JS/TS/Go/Java/Rust）解析进 SQLite 索引，回答调用者、被调用者、依赖、反向依赖、影响面与全文检索问题。", "data", 3, "tools"),
        E("dsh-aigc-radar", "dsh-aigc-radar", "检索 AIGC Radar 精选 GitHub AI 项目库（500 Stars 准入、中英双语标签、星标增长快照），经其 MCP 端点调用并以原生结果卡片展示；agent/pre-step 监听器在 agent 动手写代码前主动建议复用检查。", "archive", 3, "tools"),
        E("dsh-apple-mode", "dsh-apple-mode", "DSH 的 Xcode AI 集成：26 个 Xcode MCP 工具（mcpbridge）+ Apple 平台技能 + Xcode Intelligence 风格 persona（agent preset 或全局 bundle）。", "ai", 3, "tools"),
        E("dsh-ark-wiki", "dsh-ark-wiki", "查询 PRTS Wiki 的《明日方舟》干员、物品、关卡、剧情与泰拉大典世界观条目，并基于剧情卡司统计与卡池历史预测未实装角色、异格与卡池排期。", "text", 3, "tools"),
        E("dsh-astock-research", "dsh-astock-research", "A股个股研究：搜股票、查任意区间公告、财报卡、估值画像与交易信号科普（约 5000 只、2011 年至今，公共只读数据服务），另有一个跳转外部交易推演产品的链接工具。", "misc", 3, "tools"),
        E("dsh-bayes-predict", "dsh-bayes-predict", "贝叶斯个股预测插件：多指标信号融合的上涨概率估计、趋势状态识别与持仓风险度量（A 股 + 美股）。", "misc", 3, "tools"),
        E("dsh-bili-interactor", "dsh-bili-interactor", "替你在 B 站上真的动手：搜视频、点赞、投币、发弹幕、发评论、回别人的评论，别人回了还能接着聊。会读视频的 B 站 AI 字幕（没有字幕时可本地转写），所以评论说的是视频里真正讲了什么；挑该回谁之前也会先看一遍视频内容。它不抄别人的句子，而是总结「怎么说话才像真人」的规律，跑得越多 AI 味越淡。会", "media", 3, "tools"),
        E("dsh-capability-toggle-plugin", "dsh-capability-toggle-plugin", "在 DSH WebUI 中为技能、MCP 服务器、工具、提示词注入、审批升权和安全守卫提供会话、项目与全局三级控制，并在当前 agent 作用域内强制执行。", "session", 3, "tools"),
        E("dsh-cos", "dsh-cos", "提供 COS 云存储浏览与传输、工作区产物上传、临时链接，以及同时保留本地副本和云端对象身份的会话附件，并提供腾讯云 COS、数据万象和 MetaInsight 的 Agent 工具。", "session", 3, "tools"),
        E("dsh-data-cleaning-agent", "dsh-data-cleaning-agent", "数据清洗补全智能体：面向 Excel/CSV/JSON 企业名单，提供数据清洗、表格清洗、清洗补全、去重、企业数据补全与字段补全，支持企查查 MCP 和结果导出。", "data", 3, "tools"),
        E("dsh-devtoolbox", "dsh-devtoolbox", "DSH 本地工具箱：侧边栏独立页面内置 35 个纯本地小工具（文本、编码、哈希、提取、转换、速查表），另有 /toolbox 命令与配置驱动的 agent 工具注册。", "codec", 3, "tools"),
        E("dsh-docker-2", "dsh-docker", "Docker 工具：ps/images/logs/inspect/exec/manage/health 七工具，JSON 输出、DSH_DOCKER_PATH 环境变量、exec 审批门、零运行时依赖。", "data", 3, "tools"),
        E("dsh-electro-lab", "dsh-electro-lab", "DSH 电气电子计算插件：所有计算都通过专用工具完成，基于 SI 基本单位的自描述复数值对象；附带隔离的计算智能体预设与记录面板，每次求解落盘存档。", "ai", 3, "tools"),
        E("dsh-exam-countdown", "dsh-exam-countdown", "查询 64 场中国考试（高考/考研/四六级/CPA/法考…）的规则日期（第二个周六、第一个周日）与倒计时。", "time", 3, "tools"),
        E("dsh-fhl-image-plugin", "DSH-FHL-Image-Plugin", "为 DeepSeek Harness 提供 FHL Images 生图与多参考图编辑，含三个 Agent 工具、最多十个 API Key Worker 的池，以及聊天内配置 Key。", "ai", 3, "tools"),
        E("dsh-figma-to-lottie", "dsh-figma-to-lottie", "将 SVG 路径与关键帧参数编译成自包含的 Lottie JSON 动画文件。", "image", 3, "tools"),
        E("dsh-find-ideas", "dsh-find-ideas", "GitHub 项目检索与解析工具：一句话输入开发想法，agent 在 GitHub 搜索相关项目，按相关性与 star 加权排序后返回一张结构化的卡片（包括各项目的更新时间、相关性分数、star数、加权后得分、使用的开发语言、一句话简介）。选择几个仓库后，它还能直接读取这些项目的 README、依赖", "git", 3, "tools"),
        E("dsh-freecad", "dsh-freecad", "通过 FreeCAD 读写 STEP 模型、量取几何尺寸（距离、角度、直径），并生成带孔表的第一角法二维加工图，可导出 SVG、DXF、PDF、PNG。", "pdfdoc", 3, "tools"),
        E("dsh-go-sensei", "dsh-go-sensei", "围棋复盘教练：解析 SGF 棋谱，用自带 KataGo 引擎补算胜率与目差，在对话里逐手讲解问题手，并把讲解写回 SGF 副本；Web 面板用棋盘展示问题手、AI 首选与变化图。", "session", 3, "tools"),
        E("dsh-gpt-image", "dsh-gpt-image", "游戏素材生产流水线：出图、生视频与音频，把一段视频变成连贯的精灵动画，派生配色变体，适配引擎配置，装进项目并核对代码是否真的引用了。视频转精灵动画需 ffmpeg；出图/生视频需自备图像/视频 API Key（Agnes AI / OpenAI / fal）。", "image", 3, "tools"),
        E("dsh-grok-xsearch", "dsh-grok-xsearch", "为 DeepSeek Harness 增加用于 X/Twitter 搜索的 x_search 工具，通过独立的 SuperGrok OAuth 账号鉴权，不占用会话所用提供方的配额。", "search", 3, "tools"),
        E("dsh-ieee-weekly", "ieee-weekly", "按关键词盯 IEEE 期刊 Early Access：Crossref 抓新收录，逐篇交给大模型研判，生成 Markdown 周报并发到邮箱。", "pdfdoc", 3, "tools"),
        E("dsh-jenkins", "dsh-jenkins", "管理多台 Jenkins 服务器，支持从设置页、模型工具或工作区级「执行 Jenkins Job」入口触发构建，宿主 + 浏览器双端、界面中英双语。", "ai", 3, "tools"),
        E("dsh-live-canvas", "dsh-live-canvas", "在隔离的 iframe 沙箱中实时渲染 Agent 生成的 HTML、React (JSX/TSX)、Vue、SVG、Mermaid 和 Markdown，支持 SSE 热重载，并提供 DOM 点击检查器、并排视觉对比、响应式设备矩阵和一键 Vite ZIP 导出。", "pdfdoc", 3, "tools"),
        E("dsh-local-search", "dsh-local-search", "本机文件搜索与文档全文搜索（全文检索）：文件名走 Everything（es.exe），磁盘上的 PDF / DOCX / XLSX / PPTX / EPUB 正文走 Anytxt，五个只读工具；两个引擎需另装，仅支持 Windows。", "pdfdoc", 3, "tools"),
        E("dsh-logtimeline", "dsh-logtimeline", "用中文自然语言时间描述查询本地日志（如「昨天下午」「3小时前」）——精确时间范围、匹配行、级别统计，完全离线。", "time", 3, "tools"),
        E("dsh-mcp-bridge", "dsh-mcp-bridge", "零依赖 MCP 客户端桥接，连接 stdio 与 HTTP MCP server，把其工具注册为 mcp_<server>_<tool> 供 agent 调用。", "ai", 3, "tools"),
        E("dsh-mcp-manager-4", "dsh-mcp-manager", "管理 MCP 服务器，按需加载并筛选工具以减少上下文占用。", "session", 3, "tools"),
        E("dsh-mcp-matlab", "dsh-mcp-matlab", "将本地 MATLAB MCP server 桥接进 DSH，提供 mcp__matlab__* 工具：执行 MATLAB 代码、运行 .m 脚本与测试、查看已安装工具箱。需要自备 MATLAB 与 MathWorks 官方 MATLAB MCP Server 可执行文件，且安装后需填一次路径——只装", "fileops", 3, "tools"),
        E("dsh-mcp-tools", "dsh-mcp-tools", "DeepSeek Harness 的 MCP 工具管理器：在设置里添加 streamable-http/stdio 服务器、Postman 式请求头、连通性测试，并按工具开关——停用的工具不会进入模型。", "ai", 3, "tools"),
        E("dsh-mcptoon", "dsh-mcptoon", "把 mcptoon 作为一条 stdio MCP 服务接入，让 agent 通过 mcptoon 的压缩视图发现已配置 MCP server 的工具，而非每轮支付完整 JSON schema。附带 doctor CLI：校验 mcptoon 可执行文件能否解析，不能时打印精确的 command/ar", "data", 3, "tools"),
        E("dsh-net-tools", "dsh-net-tools", "让沙箱里的 agent 通过你的本地代理联网：net_fetch 抓取网页，net_proxy_status 查看代理状态。", "net", 3, "tools"),
        E("dsh-nonead-ursim", "dsh-nonead-ursim", "让 DSH 用自然语言直接控制 Universal Robots（UR）协作机械臂的插件——默认是一台离线、运动学级的仿真机械臂，真机通道在显式开启前始终关闭。需本机 Python 并 pip install -r requirements.txt（numpy、paramiko）。由拓德科技（Non", "misc", 3, "tools"),
        E("dsh-omv", "dsh-omv", "面向 DeepSeek Harness 的证据优先漏洞研究工作台：原生审计视图、29 个 OMV 工具、Evidence.v1 Finding、可复现 Run、Campaign 工作流和隔离 PoC 证据。", "misc", 3, "tools"),
        E("dsh-packer", "dsh-packer", "为 DeepSeek Harness 打造的 Agent 配置打包器：把本地 Agent 资产（Skills/会话/Profile/全局设置/记忆）打包成 zip，用于迁移或分享；带隐私安全扫描、差异恢复、包管理与设置 UI；记忆以只读 Markdown 镜像入包，不含运行时数据库。", "pdfdoc", 3, "tools"),
        E("dsh-patch-edit-plus", "dsh-patch-edit-plus", "补丁风格文件编辑：单个 apply_patch 工具，接受 git/unified diff（默认）与 Codex apply_patch 语法（可选开启），在完整只读校验后全量原子应用；删除与移动走沙箱感知路径，并提供 dry-run 模式。", "fileops", 3, "tools"),
        E("dsh-pixmart", "dsh-pixmart", "DSH 电商商品图生成：24 个提示词模块覆盖主图、详情图与广告图，支持参考图风格复刻、批量生成，以及作品库实时预览。", "ai", 3, "tools"),
        E("dsh-plugin-7", "dsh-plugin", "通过 PicGo 已有配置（PicGo Cloud、GitHub、S3、腾讯云 COS、七牛，或任意已安装的上传插件）把本地图片和文件上传到图床，提供 `picgo_upload` 工具与 `/picgo` 命令。", "image", 3, "tools"),
        E("dsh-plugin-cats", "dsh-plugin-cats", "为 AI 代理从公开 API 获取随机猫咪冷知识与猫图。", "net", 3, "tools"),
