        E("dsh-plugin-midscene", "dsh-plugin-midscene", "基于 Midscene 的 AI UI 自动化——android_ui 与 web_ui 工具，通过 ctx.midscene seam 在真实 Android 设备或已运行的 Chrome 上完成点击、输入、查询与断言。", "misc", 3, "tools"),
        E("dsh-plugin-muapi", "dsh-plugin-muapi", "MuApi 媒体生成工具：muapi_generate 工具通过一个 x-api-key 提交并轮询 MuApi 100 多个图片、视频、音频与 3D 模型的生成任务。", "git", 3, "tools"),
        E("dsh-plugin-nlbi", "dsh-plugin-nlbi", "自然语言查询 + 商业智能报表：Text2SQL、图表、报表收藏、Schema/数据面板与侧栏工作台，基于 DSH 的 MySQL 连接层。", "data", 3, "tools"),
        E("dsh-polymarket-knowhow", "dsh-polymarket-knowhow", "面向 DeepSeek Harness 与 Claude Code 的 Polymarket 工具包：Gamma/CLOB/Data-API 行情工具（DSH 内 31 个模型工具，MCP 只暴露只读子集）、需显式开启的带鉴权交易工具、WebSocket 推流服务，以及内置的 Polymarket", "ai", 3, "tools"),
        E("dsh-proxy-routing", "dsh-proxy-routing", "按每次执行为 Agent fetch、LLM provider 与 shell 命令路由 HTTP/SOCKS5 代理；支持 settings 热更新、审批门禁和凭据安全状态。", "net", 3, "tools"),
        E("dsh-rea-mcp", "dsh-rea-mcp", "纯配置型 DeepSeek Harness 插件，用本体自带的 MCP 客户端桥，经 stdio 连接 morluto/rea，让 agent 从应用行为一路逆向到底层原生二进制。", "ai", 3, "tools"),
        E("dsh-remote-ssh-ops", "dsh-remote-ssh-ops", "DSH SSH 远程运维：通过 SSH 或一次性配对码的 remote-hostd 连接服务器，执行命令、管理后台任务、读写远程文件并审阅变更（host_pair/host_bash/host_jobs/host_read_file/host_write_file/host_review_chang", "fileops", 3, "tools"),
        E("dsh-router-ext-rtk", "dsh-router-ext-rtk", "dsh-router 的 RTK(Rust Token Killer)扩展插件：把每次 bash 工具调用经 `rtk rewrite` 改写，让 agent 读到压缩后的命令输出；rtk 缺失或无等价改写时原样执行。", "archive", 3, "tools"),
        E("dsh-select-quote", "dsh-select-quote", "为 DSH 增加划词批注、引用、划词翻译、侧边子代理提问，链接用默认浏览器打开。选中的原文连同评论随下一条消息交给模型，正文保留高亮与序号角标、可跳回原文；菜单可划词浮出或从右键打开，翻译可单独指定模型。", "net", 3, "tools"),
        E("dsh-session-audit", "dsh-session-audit", "会话执行分析：步骤、工具调用、失败、重复动作、token 用量与验证信号，输出 text/Markdown/JSON 报告。", "pdfdoc", 3, "tools"),
        E("dsh-shared-terminal", "dsh-shared-terminal", "共享交互式终端：AI terminal 单工具与官方侧栏 xterm 共用 Session shell，用户可输入并查看当前屏幕。", "misc", 3, "tools"),
        E("dsh-shell-select", "dsh-shell-select", "Windows shell 接管：把默认 pwsh 工具替换为可配置多客户端 shell 工具（git bash/WSL/cmd/pwsh、自定义路径），deny 黑名单与失败自动回退官方链。", "git", 3, "tools"),
        E("dsh-study-coach", "dsh-study-coach", "DSH 的学习教练：把一门课拆成知识地图（大类 / 模块 / 最小单元），逐单元记六档掌握度，按资料索引排每日任务，带错题本与记忆卡，并自带一个网页面板。", "session", 3, "tools"),
        E("dsh-tool-diff", "dsh-tool-diff", "文本/JSON/CSV/Markdown 结构化比较与 unified diff。", "pdfdoc", 3, "tools"),
        E("dsh-tool-drawer", "dsh-tool-drawer", "把重工具组从每一轮请求里收起来，并且能按会话/按角色裁剪工具面：角色键来自宿主自己的会话 label、subagent 标记或 preset，编排器的子代理各看各的组白名单。另有按名前缀自动分组、让 AI 分一次没归组的工具、调用被收工具时自动放回，以及每个会话实际可见性的 health 快照。", "net", 3, "tools"),
        E("dsh-tool-gate-1", "dsh-tool-gate", "全局层工具白名单延迟加载：白名单内工具全量注入，其余交宿主按需加载链以 tool_search 检索激活，设置卡可视配置。", "search", 3, "tools"),
        E("dsh-tool-json", "dsh-tool-json", "JMESPath 子集 JSON 查询。", "data", 3, "tools"),
