        E("dsh-tool-schema", "dsh-tool-schema", "JSON Schema 验证：validate/paths/explain/normalize。", "data", 3, "tools"),
        E("dsh-tool-time", "dsh-tool-time", "严格 ISO 8601 解析、IANA 时区转换、UTC 日历运算。", "time", 3, "tools"),
        E("dsh-tracescope", "dsh-tracescope", "DSH 右侧栏插件：对比两个 git 提交，根据影响面生成手测清单，支持失败备注、截图、任务附件，以及向云效 / GitHub / GitLab / Webhook 提交缺陷。", "git", 3, "tools"),
        E("dsh-trajectory-governance", "dsh-trajectory-governance", "Agent 轨迹治理与异常诊断：把平铺会话日志重建为多分支轨迹树，识别循环死锁/无效重试/目标漂移，带成本归因的告警与一键中断/断点分支（官方 API），独立 GUI Tab。", "git", 3, "tools"),
        E("dsh-ugreen-nas", "dsh-ugreen-nas", "绿联 NAS（UGOS Pro）连接器：通过访问令牌调用 OpenCLI，59 个工具覆盖全部 70 项令牌权限——文件、存储、任务指标、Docker、下载、应用管理、控制面板与全局搜索，按令牌实际授予自动增减。", "net", 3, "tools"),
        E("dsh-units", "dsh-units", "单位换算工具箱：覆盖 20 个类别——长度、质量、温度、面积、体积（含美制烹饪单位）、速度、时长、数据大小（十进制 MB 与二进制 MiB）、数据传输速率（Mbps 与 MB/s）、加速度（含 g-force）、照度（lux 与英尺烛光）、压强、能量、角度、频率、功率（含三种马力定义）、力、扭矩、排", "sysinfo", 3, "tools"),
        E("dsh-wait-subagent", "dsh-wait-subagent", "为 DeepSeek Harness 提供后台子代理的主动等待：注册 wait_subagent 模型工具，阻塞等待指定的后台 continuable（可续会话）子代理收尾（settlement），返回停止原因与收尾消息——可选超时、成员资格门控拒绝未知 id、事件驱动零轮询。补齐 run_in_b", "net", 3, "tools"),
        E("dsh-web-search", "dsh-web-search", "免密钥网页搜索：一个 web_tools 入口、八个 action，覆盖多查询、日期窗口、包、论文、仓库、平台、正文读取、引用研究、缓存检索与引擎健康；融合八个引擎，并提供给其他 Agent 使用的 stdio MCP server。", "git", 3, "tools"),
        E("dsh-webfetch", "dsh-webfetch", "纯文本 agent 的网页阅读工具。五个只读工具：web_fetch（把任意 URL 渲染成干净的 Markdown 或纯文本）、web_links（清单页内链接）、web_feed（RSS 2.0 / Atom 条目解析）、web_headers（不下正文即取 HTTP 状态、响应头与重定向链，H", "pdfdoc", 3, "tools"),
        E("dsh-wind-aifin", "dsh-wind-aifin", "将 Wind 七个金融 MCP 域和 Wind Alice 接入 DSH，并仅在宿主凭证边界内解析 WIND_API_KEY。", "misc", 3, "tools"),
        E("knowlp-rag", "knowlp-rag", "Markdown 笔记的双知识图谱 RAG，带半衰期记忆衰减：前置依赖 + 相似关联双图（P/S-Agent 遍历）、段落级匹配、ngram/embedding 混合检索、显式权重反馈闭环——原生 Cordis 插件，npm 包 @eqman00003/knowlp-rag。", "pdfdoc", 3, "tools"),
        E("lightroom-py", "lightroom-py", "通过 lightroom-py MCP 服务器把 Adobe Lightroom Classic 接入为 dsh 原生工具：读取目录、应用 develop 设置与预设、导出 JPEG/TIFF/PSD/DNG、写入星级/色标/关键词/IPTC——15 个工具，直接驱动本机安装的 Lightroom", "image", 3, "tools"),
        E("orca-dsh-launcher", "orca-dsh-launcher", "DeepSeek Harness 的 Windows 桌面伴侣：更新检查、服务器启停、系统托盘、图形控制台与一键安装。", "devops", 3, "tools"),
        E("pack-agent", "pack-agent", "把 .pack.json/.pack.zip 投影到 .agent-pack/modpacks/，按工作区白名单暴露 skill。", "data", 3, "tools"),
        E("qcc-dsh-mcp-legal-oauth", "qcc-mcp-legal-oauth", "一键 OAuth（PKCE）授权接入企查查法律产品——法律数据 MCP 服务（法规检索、案例检索）：动态注册客户端、token 自动刷新、动态配置 mcp-client 条目，一次授权覆盖法规与案例服务。", "ai", 3, "tools"),
        E("sqlx-dsh", "sqlx-dsh", "OtterMind SQLX 数据库工具：列出已保存的数据源、查看或测试连接、执行 SQL、打开本地结果页，缺少 sqlx CLI 时首次调用自动安装。", "data", 3, "tools"),
        E("dsh-archive-manager-5", "dsh-archive-manager", "DeepSeek Harness 会话归档管理：分组归档面板，支持恢复与删除。", "archive", 3, "session"),
        E("dsh-autocompact", "dsh-autocompact", "为 DeepSeek Harness 按模型设置更早的自动压缩阈值：/autocompact 以精确 provider/model 为键写入仅本会话生效的覆盖值（off 回退后端默认、default 清除覆盖），设置页「自动压缩」管理所有会话继承的持久化逐模型阈值，输入框状态条目显示当前读数。", "archive", 3, "session"),
        E("dsh-btw-plugin", "dsh-btw-plugin", "Codex 风格 /btw 指令：在继承主会话上下文的子代理中回答附带问题，答案展示在界面里、不写入主会话历史。", "net", 3, "session"),
        E("dsh-chat", "dsh-chat", "面向 DSH 会话的群聊室：支持明确 @ 提及、冷会话唤醒投递，并可通过 dsh-weave 跨主机通信。", "session", 3, "session"),
        E("dsh-codex-history", "dsh-codex-history", "在 DSH 里说一句话就能装上，随后它会读取 ~/.codex/sessions 里的本地 Codex CLI/桌面版聊天记录并在 DeepSeek Harness 里直接使用：输入框下方的面板可列出会话、按关键词与起止日期筛选并一键导入；codex_history 工具让 agent 列出、读取、", "time", 3, "session"),
        E("dsh-compaction-policy", "dsh-compaction-policy", "让 DeepSeek Harness 不再过早压缩对话（把早期内容总结掉）。默认行为下，上下文窗口不大的模型（十几万 token 那种）常常在半满出头就开始压缩；装上它之后，压缩会等你设定的比例（默认 80%）到了才发生，并且可以按 provider/model 分别设置。它只改“什么时候压缩”，一", "archive", 3, "session"),
        E("dsh-concise", "dsh-concise", "DeepSeek Harness 一键 Concise 输出风格开关：结果先行、少废话，工作深浅不变。每轮最终回答开头自动附「摘要」精华卡（划选即复制），按会话独立生效，headless/CLI 同样生效，支持 /concise 命令、style.md 自定义风格与本地 API。摘要卡内的链接与文件", "fileops", 3, "session"),
        E("dsh-context-fold", "dsh-context-fold", "把超长工具结果折叠为落盘副本并保留 head/tail 标记，为 compaction 摘要建立可检索账本，并按项目作用域抽取跨会话记忆；被折叠的内容可通过一次工具调用原样取回。", "session", 3, "session"),
        E("dsh-context-manager", "dsh-context-manager", "预览会话上下文，按对话分组选择保留、摘要或省略，确认后通过 Harness 会话服务持久化压缩结果。", "archive", 3, "session"),
        E("dsh-date-wrapper", "dsh-date-wrapper", "将 DSH 时间上下文从约 280 字符压缩到 46 字符，向运行期快照注入紧凑日期行，无运行时依赖。", "archive", 3, "session"),
        E("dsh-delete-sessions-1", "dsh-session-delete", "在侧栏会话菜单的「归档会话」下方新增红色「删除会话」项，配自定义确认对话框，实现真正的会话删除——停止会话进行中的工作、摘除工作区/归档/置顶记账、删除投影缓存与日志目录，然后广播移除事件让该行立即消失，而不是只能归档。会话删除会把对话从磁盘彻底移除且无法恢复；删除会话与会话删除是同一种操作的两种叫", "archive", 3, "session"),
        E("dsh-favorites", "dsh-favorites", "会话收藏夹：把任意会话收藏进浏览器收藏夹式的管理面板——左侧会话行一键收藏/星标，主面板支持文件夹分门别类、备注、自定义显示名、一键继续会话、Fork 新会话、会话基本统计，外加一张清晰展示会话派生关系的 fork 关系图。", "fileops", 3, "session"),
        E("dsh-incognito", "dsh-incognito", "无痕会话：独立临时子 Agent（独立 preset 不继承父会话、全量工具集），浮窗可拖动，关闭即焚毁、磁盘零痕迹。", "sysinfo", 3, "session"),
        E("dsh-message-recall", "dsh-message-recall", "给会话里的每条消息加上「撤回 / 删除 / 删除此处及之后」悬浮按钮：以 append-only 墓碑让内容同时从模型上下文与对话界面消失，带空内容兜底，旧删除不会打回严格校验的 provider。已实测支持 DSH 2.0 桌面版。", "session", 3, "session"),
        E("dsh-message-rewind", "dsh-message-rewind", "给自己的消息气泡加「编辑 / 删除」：编辑会截断其后的轮次并重发新内容，删除会移除这条消息及其后的轮次；两者都可选择同时回滚被移除轮次记录到的文件改动（文件之后又被改过则拒绝回滚）。侧边栏始终只保留一条会话。", "fileops", 3, "session"),
        E("dsh-move-to-workspace", "dsh-move-to-workspace", "从侧边栏菜单把已有的 DeepSeek Harness 会话移动到其他工作区：会话记录与标题一并带过去，可在同一对话框里登记新的工作区文件夹，原会话归档且可恢复。", "archive", 3, "session"),
        E("dsh-msg-rewind", "dsh-msg-rewind", "对话回退：/undo 回退一轮，/rewind 回退到历史消息，悬浮用户气泡可可视化撤回。", "session", 3, "session"),
        E("dsh-plugin-message-edit", "dsh-plugin-message-edit", "面向 DSH 桌面端的消息与附件编辑，支持原地保存、分支重生成和版本时间线。", "git", 3, "session"),
        E("dsh-rewind-plugin", "dsh-rewind-plugin", "撤回已发送的消息：会话日志只追加、不删除任何东西，被撤回的回合退出模型上下文并从对话界面消失、原文回到输入框，被这些回合改动的文件留在隔离区里——设置里独立一页，可查看可清理。", "fileops", 3, "session"),
        E("dsh-scratch-workspace", "dsh-scratch-workspace", "一键创建一次性临时工作区（独立文件夹、独立工作区与会话），在侧边栏统一管理，用完把文件夹移入系统废纸篓。", "fileops", 3, "session"),
        E("dsh-session-archive", "dsh-session-archive", "DeepSeek Harness 已归档会话管理面板：按工作区目录分组、按标题实时搜索、只读预览用户问题、一键恢复，或二次确认后删除。", "archive", 3, "session"),
        E("dsh-session-deck", "dsh-session-deck", "在 DSH 侧栏添加 Activity 和 Favorites 视图，跨工作区查看运行中、等待回复、未读、最近及原生置顶会话，并保留原生工作区树。仅适配 DSH 0.2.1-rc.2。", "session", 3, "session"),
        E("dsh-session-delete-1", "dsh-session-delete", "用于彻底删除 DeepSeek Harness 会话，并同步清理 .dsh/sessions 目录下相关文件的插件。", "fileops", 3, "session"),
        E("dsh-session-delete-7", "dsh-session-delete", "在侧栏会话行的「…」菜单里永久删除单个会话;也可从侧栏标题旁的「⋯」菜单进入批量删除:在列表里勾选会话(运行中的不能删),再在确认弹窗里一次删掉 —— 会话日志、工作区归属、宿主内存实例、客户端列表行一并清理。同一个「⋯」菜单还收着会话搜索与视图选项;另可清理日志已不存在的残留行,用户消息与 AI", "sysinfo", 3, "session"),
        E("dsh-session-doctor", "dsh-session-doctor", "会话医生：列出会话（含 agent 运行状态）、读取会话记录、诊断卡死的 agent、解卡（cancel + keepInbox 保留排队消息）、向其他会话发送消息。", "session", 3, "session"),
        E("dsh-session-export", "dsh-session-export", "把当前会话导出为可移植、带 schema 版本的 Markdown 与 JSON 文件，提供 `session_export` 工具与斜杠命令两种入口，文件名跨平台安全。", "pdfdoc", 3, "session"),
        E("dsh-session-export-2", "dsh-session-export", "会话导出为 Markdown/JSON，便于复盘、重放与单会话成本汇总。", "pdfdoc", 3, "session"),
        E("dsh-session-find", "dsh-session-find", "会话内 Ctrl+F 全文查找（读会话 store 而非 DOM）：命中按来源分类（你/助手/思考/工具调用/工具输出/系统）、按轮次分组、同文合并，可切「只搜正文 / 搜全部内容」，支持正则/大小写/全词，全量高亮，并能把结果复制或导出为 Markdown。", "pdfdoc", 3, "session"),
        E("dsh-session-hotkeys", "dsh-session-hotkeys", "Web 会话热键插件：像切浏览器标签页一样用键盘管理会话——Alt+1-9 顺序切换、固定槽位、上/下一个、新建/归档/重命名、Alt+M 键盘切换模型与备用发送、Esc 焦点交接，Alt+W 关闭/恢复 dsh-split-screen 工作区；键位可在面板录制重绑，Windows/macOS 双", "archive", 3, "session"),
        E("dsh-session-manager-4", "dsh-session-manager", "会话管理：超期会话自动归档（阈值可配），归档面板支持取消归档，删除移入系统回收站可还原。", "archive", 3, "session"),
        E("dsh-session-multiselect", "dsh-session-multiselect", "为 DSH 对话加入可搜索、按工作区分组的多选面板，支持 Shift 范围选择与 Ctrl/Cmd 追加选择，然后批量删除、归档或置顶。", "archive", 3, "session"),
        E("dsh-session-progress", "dsh-session-progress", "不用再翻日志，也能随时知道 DeepSeek Harness 的会话做到哪一步了：agent 维护一份实时嵌套清单——从整个阶段到单个步骤——每一项都带权重，所以输入框下方 dock 行的进度环与百分比胶囊始终反映真实进度。悬停可看当前活动，或打开原生右侧边栏的 Session Progress 标", "session", 3, "session"),
        E("dsh-session-robustness", "dsh-session-robustness", "官方 llm-retry（n/5）耗尽后，对超时/传输/限流/5xx/SSE 断流等瞬时失败在同一打开 step 上继续重试直到成功、取消或暂停；认证失败、额度耗尽和用户停止不会重试。", "ai", 3, "session"),
        E("dsh-sessionflow", "dsh-sessionflow", "在 DeepSeek Harness 里跨编码 Agent 继续工作：六个 sessionflow_* 工具查询 sessionFlow 构建的本地会话索引，找回过去的工作、看清当前项目做到哪了，并把目标、涉及文件与未完成事项交给下一个 Agent。需要另行安装独立的 sessionFlow 核心（", "codec", 3, "session"),
        E("dsh-task-control", "dsh-task-control", "DeepSeek Harness 任务控制：卡死的下载与工具调用一键急停与强制终止、下载进度、卡死识别、pwsh 运行状态检测，以及追加条件/暂停/恢复（恢复指令隐形注入，不打扰聊天）。", "net", 3, "session"),
        E("dsh-task-notice-board", "dsh-task-notice-board", "面向 DSH Web 的任务级 Workspace 到 Task 到 Session 协作控制台，提供 Session 看板、归档对话查看，以及在关联 Session 之间共享的有界长期记忆。", "archive", 3, "session"),
        E("dsh-threads-1", "dsh-threads", "针对一句话提问，不打断主对话：在 Web 对话中选中一段文字发表评论，会话自己的模型在旁边的小线程里作答，主对话不受影响。回复者可以读取会话、工作目录，开启后也可联网，但不做任何修改。被评论的段落保持高亮，徽标提示未读回复；需要 Agent 动手时，「发送到对话」把线程交给它。", "fileops", 3, "session"),
        E("dsh-treecom", "dsh-treecom", "DeepSeek Harness 的可平移会话树：在侧栏查看任意一轮、回到该分支，并从任意一轮分叉；连续轮次会折叠成一个节点。", "git", 3, "session"),
        E("dsh-unarchive", "dsh-unarchive", "列出已归档会话、预览内容、恢复到原工作区，并提供可选的归档二次确认。", "archive", 3, "session"),
        E("huahua-dsh-record-replay", "huahua-dsh-record-replay", "功能完整的 DSH 录制回放插件（huahua 出品，Windows 实测可用）：会话时间线回放、回放包导出/导入、复刻会话重新执行、录屏自动生成可安装技能。基于 kangshifu1/dsh-record-replay 做 4 处 Windows/rc.5 适配（见 README 衍生声明）。", "time", 3, "session"),
        E("claude-in-dsh", "claude-in-dsh", "把一个 dsh web 会话交给本机 Claude Code CLI 驱动：输入框内的引擎选择器（DSH | Claude Code）按会话切换，模型座换成 Claude 的模型与 reasoning effort，访问模式换成 Claude 权限档；权限请求、AskUserQuestion、Exi", "session", 3, "model"),
        E("dsh-agy-cli", "dsh-agy-cli", "Windows 专用的 Google Antigravity CLI 模型提供方，接续自 Darkings/dsh-agy-provider（包名 dsh-agy-cli，请勿与原版同装）。从 Windows 凭据管理器读取 Antigravity 令牌并只发往 Google Cloud Code", "ai", 3, "model"),
        E("dsh-ark-coding-provider", "dsh-ark-coding-provider", "非官方火山方舟 Coding Plan 模型接入插件：注册 `ark-coding` 路由，12 个模型的容量事实逐项实测，多账户自动轮换，内置钉版 arkcli 拉官方模型目录与真实套餐额度，含设置向导与侧边栏用量卡片。", "fileops", 3, "model"),
        E("dsh-auto-driving", "dsh-auto-driving", "DeepSeek Harness 模型故障自动回退与轮次保活：请求在产出任何可见内容前因模型错误失败时，沿所选供应商分组的模型（再到下一个供应商）逐个切换直到流式成功；瞬态失败按指数退避自动重试并有活性看门狗防假死，整轮任务失败后自动发送模板化「继续」唤醒续跑；可选全自动模式自动应答权限审批、确认提", "ai", 3, "model"),
        E("dsh-claude-driver", "dsh-claude-driver", "让会话主模型跑在本机 Claude Code 订阅上：经官方 Claude Agent SDK 接管 claude-code provider 的 llm/stream 路由，支持 token 级流式、会话 resume 续接，并把 DSH 工具经 MCP 桥接进去以保留 DSH 的沙箱与审批。", "session", 3, "model"),
        E("dsh-cliproxyapi-pro", "dsh-cliproxyapi-pro", "在 DeepSeek Harness（DSH）中接入 CLIProxyAPI（CPA），支持多账户、模型筛选、原生协议直连、额度查询、生图生视频，选好配置后自动出现在模型选择器中。", "media", 3, "model"),
        E("dsh-connect-opencode", "dsh-connect-opencode", "把本机 opencode serve 目录里的全部免费模型（覆盖所有 provider，含你自定义的 provider）接入 DeepSeek Harness 模型选择器，并禁用 OpenCode 原生工具，执行权留在 DSH。", "codec", 3, "model"),
        E("dsh-connect-workbuddy-models", "dsh-connect-workbuddy-models", "把本机所有登录过的 WorkBuddy 账号聚合成一个模型池，带手动与自动签到、积分与到期监控、模型倍率，并可在输入框下方切换账号、查看剩余总积分。", "sysinfo", 3, "model"),
        E("dsh-everything-oauth", "dsh-everything-oauth", "把本机 Codex / Grok / Claude / OpenCode / CC Switch 登录态导入 DSH，在设置里自选来源并启用模型。", "codec", 3, "model"),
        E("dsh-llm-acp", "dsh-llm-acp", "通过 ACP（Agent Client Protocol）将任意外部 agent 作为 LLM 提供方接入——支持 Claude Code、Codex、Gemini CLI、Devin 等，内置注册表浏览与服务管理界面，支持惰性认证、模型动态发现与热切换。", "ai", 3, "model"),
        E("dsh-llm-commandcode", "dsh-llm-commandcode", "DSH 的 Command Code Provider API 聊天：Host 持有 API key，支持模型发现、effort 默认值、可选零数据保留请求头、额度仪表，以及按模型选择 OpenAI 或 Anthropic 协议。", "ai", 3, "model"),
        E("dsh-llm-error-retry", "dsh-llm-error-retry", "大模型请求重试插件：命中配置的 HTTP 状态码、机器码或 provider 返回字段=值时，按该条规则独立配置的时长休眠后自动重新请求，让订阅套餐的限额、限流报错（429 / insufficient_quota）不打断运行。", "data", 3, "model"),
        E("dsh-llm-hub", "dsh-llm-hub", "补上官方 pi-ai 适配器在模型页缺的那半：网关可达性与延迟探测、一键拉取网关模型目录并勾选写回配置、DeepSeek 余额与各家配额就地常驻、每个 provider 实际接入的协议与地址；模型下拉只列当前真能用的分组 —— key 失效、余额耗尽、配额用尽都会被摘掉，修好后自动恢复。", "fileops", 3, "model"),
        E("dsh-llm-longcat", "dsh-llm-longcat", "LongCat-2.0 模型适配器：100 万上下文、二元思考模式、工具调用，基于 OpenAI 兼容接口的流式输出。", "session", 3, "model"),
        E("dsh-llm-opencode-go-live", "dsh-llm-opencode-go-live", "为 DSH 提供 OpenCode Go 模型来源：从 Models.dev 读取 opencode-go 目录，在独立的 opencode-go-live 路由上提供，内置 opencode-go 路由保持原样。目录快照缓存在 DSH home 下，刷新失败时沿用上一次成功的目录；插件自带 Mod", "codec", 3, "model"),
        E("dsh-llm-pi-gateway", "dsh-llm-pi-gateway", "LLM 网关会话粘性路由：把会话 sessionId 注入发往 NewApi 类网关的每个请求，供网关做请求亲和以提升 prompt cache 命中，装上即接管官方 pi-ai 路由，卸载即还原。", "session", 3, "model"),
        E("dsh-loomy-connect", "dsh-loomy-connect", "把讯飞 Loomy 桌面端内置的模型注册为 DSH 的 `loomy` 供应商，读取该应用的本地登录态而不使用 API Key。是 gdrpzym/dsh-loomy-connect 适配 DSH 0.2.1 的派生版本，新增逐模型启用/禁用开关。需本机安装并登录讯飞 Loomy 桌面端；与 gdr", "ai", 3, "model"),
        E("dsh-model", "dsh-model", "为 dsh 和其他软件提供一个带鉴权的 OpenAI 兼容地址（基于 CLIProxyAPI）：汇集 WorkBuddy、OpenCode Zen、本机 Ollama / LM Studio，以及 Codex、Kimi 等 CLI 订阅；在 dsh 页面上登录，不用装各家 CLI；挑选的模型按来源分", "codec", 3, "model"),
        E("dsh-model-fold", "dsh-model-fold", "把 DSH 模型选择器按来源（provider）分组：菜单只列来源与其模型数，悬停来源即在右侧滑出该来源的模型子面板（默认）；切换为面板模式后改为单击来源滑出，或改为在列表内就地展开，双击来源标题即可在 悬浮 -> 面板 -> 列表 三者间循环切换；当前使用的模型一眼可见。纯 DOM 增强、零侵入—", "ai", 3, "model"),
        E("dsh-model-gateway", "dsh-model-gateway", "把 DeepSeek Harness 里已配置好的模型通过 OpenAI 兼容网关中转出去，其他本地项目 用标准 OpenAI 客户端即可调用。多个供应商候选共享一个具名分组，支持顺序、均衡、 随机三种调度；上游在产出任何内容前失败时自动切换下一候选，客户端无感，被限流的 请求按供应商指示的退避时间", "time", 3, "model"),
        E("dsh-model-prompt-injector", "dsh-model-prompt-injector", "DSH 按模型注入系统提示词：为本地已配置的模型把自定义提示词追加到系统提示词末尾，支持 provider/model 精确匹配与 provider/* 服务商级通配（两者按序叠加）。设置页自动列出每个已配置服务商及其模型，逐行编辑、即时生效；规则持久化保存、重启不丢；对主会话、subagent 与", "session", 3, "model"),
        E("dsh-model-settings", "dsh-model-settings", "DeepSeek Harness 模型设置面板：设置新会话的默认模型，并为子代理与 goal 回合分别配置 provider、模型和推理强度，保存后热更新。", "net", 3, "model"),
        E("dsh-model-sync-1", "dsh-model-sync", "把各提供方线上模型列表写进 DSH 设置，输入框圆环显示当前会话模型的 5 小时/7 天窗口或按量剩余余额。", "session", 3, "model"),
        E("dsh-models-dev-reasoning", "dsh-models-dev-reasoning", "为未配置的第三方 DeepSeek Harness 模型添加 models.dev 推理级别支持。", "ai", 3, "model"),
        E("dsh-models-radar", "dsh-models-radar", "在设置页展示 CodexRadar 模型能力评测，并在输入框旁显示当前会话所选模型的 DeepSWE 分数。", "session", 3, "model"),
        E("dsh-multi-model-orchestrator", "dsh-multi-model-orchestrator", "多模型主脑编排器：主模型将复杂任务拆解，按各模型优劣分派给 GLM / Kimi / Qwen 子代理执行，并按模型统计 token 用量。", "net", 3, "model"),
        E("dsh-opencode-bridge", "dsh-opencode-bridge", "在 DSH 中使用 OpenCode 免费模型，支持模型列表动态刷新与可选的代理出口轮换，并提供默认拒绝不安全转换的工具桥与离线、按 Agent 作用域的兼容性审计。", "codec", 3, "model"),
        E("dsh-opencode-connect", "dsh-opencode-connect", "把本机已安装的 OpenCode CLI 免费模型接入 DSH：自动拉起或复用本地 opencode serve，读取实时模型目录并每五分钟刷新，再通过仅绑定回环、校验 Host 与 Origin 的 shim 把会话事件流转换为 OpenAI 兼容 SSE。", "codec", 3, "model"),
        E("dsh-openrouter-free-models", "dsh-openrouter-free-models", "自动筛选 OpenRouter 免费模型，实测真实速度与上下文大小，并按速度从快到慢写入 DeepSeek Harness 模型列表，模型名中带上速度与上下文，同时在设置中新增「免费模型」配置页。", "session", 3, "model"),
        E("dsh-plugin-weaknet-adaptor", "dsh-plugin-weaknet-adaptor", "弱网适配器：模型流式请求的长退避透明重试（上限 10 分钟）、本地响应重放缓存、心跳自动重连、降级模式 token 节流，并提供中英双语设置页。", "ai", 3, "model"),
        E("dsh-polyglot", "dsh-polyglot", "DSH 的模型切换器：指向任意 OpenAI 兼容端点，内置精选免费/低价 DeepSeek 服务商预设，免费额度限流时自动回退。", "ai", 3, "model"),
        E("dsh-sub2api", "dsh-sub2api", "将 sub2api 网关接入 DeepSeek Harness：用一个 base URL 统一管理 OpenAI / Claude / Grok / Gemini 等多供应商路由，支持按 key 发现模型、用量查询与全局视觉/图像生成工具。", "image", 3, "model"),
        E("dsh-subagent-model-config", "dsh-subagent-model-config", "为 DSH 原生 Team 编队队员可视化配置专属模型与推理档位，运行时包装注入，不改官方任何文件。", "fileops", 3, "model"),
        E("dsh-swarm-router", "dsh-swarm-router", "子智能体矩阵蜂群：把异质任务路由到最合适的模型（OpenRouter 类网关 + cfgpu.com/llm/square），通过进程内子智能体或直接 LLM 调用下放，并按模型统计 token 消耗、用真实反馈驱动排名。", "sysinfo", 3, "model"),
        E("dsh-unlimited-retry", "dsh-unlimited-retry", "对没有其它恢复层接手的模型请求做重试，默认不设次数上限、退避有上限，且永不重试取消；策略可在设置面板中编辑。", "ai", 3, "model"),
        E("dsh-workbuddy-connect-1", "dsh-workbuddy-connect", "把已登录的 WorkBuddy 桌面 App 里可用的模型接进模型选择器，复用 App 的登录与积分；国内版与国际版各成一组。corrinehu/dsh-workbuddy-connect（仓库已删除）的续作；注册相同的 workbuddy / workbuddy-ai provider id，不能", "git", 3, "model"),
        E("dsh-workbuddy-connect-community", "dsh-workbuddy-connect-community", "复用本机桌面登录的 WorkBuddy 与 WorkBuddy AI 模型提供器社区分叉，提供模型发现和额度显示。正式版 0.1.11 支持按模型选择上下文窗口及 DSH 0.2.1-rc.2、rc.3 和 rc.5，CN 兼容层与 functy23 的分叉不同。派生自 corrinehu/dsh-", "session", 3, "model"),
        E("dsh-workmate", "dsh-workbuddy-harness", "把 WorkBuddy 国内版和国际版的免费/付费模型接进 DSH，无需桌面端；以 @bushizhanghan/dsh-workmate 发布。本包是 Faide-cyber/dsh-workbuddy 的维护分支（上游条目已在目录内）；请勿与上游同装，二者共用 provider id「workb", "git", 3, "model"),
        E("freecodego", "bundle-latest", "面向 DeepSeek Harness 的 FreeCodeGo：DeepSeek、Codex、Claude 三套引擎共用同一条会话与工具链，并为以下模型提供 0 token 免费使用渠道：deepseek-v4.1-flash、deepseek-v4-pro、deepseek-v4-flash-f", "session", 3, "model"),
        E("thu-tok-auto", "thu-tok-auto", "获取清华 MadModel 的 API token，按每 20 分钟在无窗口浏览器里用已保存的 SSO 会话续期，写入 DSH 凭据 MADMODEL_API_KEY 并创建或复用 madmodel 模型 Provider；手动点一次 Get 就通过校内登录窗口捕获该会话。", "session", 3, "model"),
        E("dsh-codevault", "dsh-codevault", "读开源代码后记一笔的档案：快记或深读笔记按 仓库/文件/符号 归并成一张卡，追加式落盘为可放进 Obsidian 的 Markdown 笔记；可检索历史、回看最近阅读，也能搜你自己 Obsidian 里的笔记、把相关笔记挂到阅读记录上。共 9 个工具、/codevault 命令与 code-read", "git", 3, "memory"),
