        E("dsh-get-memory", "dsh-get-memory", "对话开始时自动拉取 GitHub 仓库内容注入上下文，对话结束时提取长期记忆按文件写回并提交；文件权限中心、原生设置页、回合写回指示与全局变动提示。", "git", 3, "memory"),
        E("dsh-harnmem", "dsh-harnmem", "DSH 跨 harness 全局记忆：DSH、pi 适配器与 harnmem CLI 共享同一份本地纯文件记忆库，在一个 harness 写入的记忆在另一个 harness 可用；以字节稳定的热索引注入系统提示，提供五个 harnmem_* 工具、会话结束记忆提取与只读记忆浏览面板。", "fileops", 3, "memory"),
        E("dsh-hindsight-local-optimize", "dsh-hindsight-local-optimize", "为 DSH 桌面端官方 Hindsight 插件补齐本地记忆生命周期：一键启停 hindsight-embed 守护进程、开机自启、退出随停、隐藏 uv.exe 黑框，并支持把档案柜与模型装到其它盘。", "sysinfo", 3, "memory"),
        E("dsh-hybrid-memory", "dsh-hybrid-memory", "DSH 本地混合记忆插件：L1 快照（MEMORY.md/USER.md，由 memory_* 工具按需读取）+ L2 可检索知识库（facts + SQLite FTS5，滑窗分词支持中文检索）+ L3 从 Hermes/Claude Code/Codex/WorkBuddy 以及 Agent H", "data", 3, "memory"),
        E("dsh-living-memoir", "dsh-living-memoir", "把跨会话记忆写成一份简短可读的 Markdown 活文档，每轮对话结束后整个重写；模型工具、页面手写与自动改写都写进同一批文件。", "pdfdoc", 3, "memory"),
        E("dsh-living-memory", "dsh-living-memory", "单文件本地 SQLite 的自整理活记忆——夜巡引擎自动去重、合并、衰减、建链，七信号 RRF 混合检索（FTS5+jieba 中文优先分词、可选向量 KNN、图谱 PPR），带类型知识图谱，冲突检测标记矛盾而非静默覆写，Web 遥测面板。", "data", 3, "memory"),
        E("dsh-local-vector-memory", "dsh-local-vector-memory", "DSH 全本地向量记忆:本地 embedding、SQLite 存储、自动召回注入、去重与冲突检测、软删除回收站、在线备份,可选 LLM 提取。", "data", 3, "memory"),
        E("dsh-mem0-2", "dsh-mem0", "自托管 mem0 记忆读写插件：agent 直接读写自有 mem0 服务（增删查改、搜索、历史、重置、状态），并带设置面板配置卡片。", "search", 3, "memory"),
        E("dsh-memoria", "dsh-memoria", "向量+图记忆后端：observe/remember/search/recall 四个工具对接本地 memoria 服务，HNSW 语义召回 + FTS5 关键词 + 知识图谱信号经 RRF 融合排序，回合结束自动写入，按 Agent 命名空间隔离。", "text", 3, "memory"),
        E("dsh-memory-layers", "dsh-memory-layers", "给 DeepSeek Harness 的分层长期记忆：热层约 600 字、超限自动腾挪，冷层按月归档、可按关键词跨月召回并按使用度排序，日/周/月三级抽取式摘要控制注入体量。", "archive", 3, "memory"),
        E("dsh-memory-plugin", "dsh-memory-plugin", "纯本地长期记忆：跨对话、跨项目，数据只存本机一个 JSON 文件，不联网、不调大模型、不需要 API key。提供 memory_save / memory_search / memory_list / memory_forget / memory_review 五个工具；每轮按关键词与标签检索并注", "data", 3, "memory"),
        E("dsh-memu-memory", "dsh-memu-memory", "面向长篇 RP 与陪伴对话的记忆插件：三层记忆、逐轮召回、来源标注、角色与世界线边界、关系图、图片附件与独立 WebUI。", "image", 3, "memory"),
        E("dsh-mnemosyne-1", "dsh-mnemosyne", "给 DeepSeek Harness 的分层长期记忆：每轮只注入「人设框架 + 相关记忆索引」，原文留在磁盘按需展开，不把整个库塞进上下文。事实层按槽位做冲突消解，改口后旧值自动失效；人设框架由模型从记忆里自行归纳，带三道防污染闸门（拒收开发流水、拦截自身注入的回流、同一件事按共享实词归并）。记忆周", "sysinfo", 3, "memory"),
