        E("dsh-commercial-ui-ux", "dsh-commercial-ui-ux", "注册 commercial-ui-ux 技能：以任务为中心的商业界面 UI/UX/GUI 设计、审查、修复与实现（SaaS、仪表盘、后台、表单、表格、设计系统），带参考文档体系与质量门禁。", "data", 3, "skill"),
