        E("dsh-tool-visual-primitives", "dsh-tool-visual-primitives", "通过模式化提示分析对话图片（描述、UI、文档、定位、拓扑等），将含坐标原语（框、点、引用）的结构化证据以文本注入上下文，会话级缓存跨回放与压缩复用。", "image", 3, "vision"),
        E("dsh-vision-bridge-1", "dsh-vision-bridge", "将图片交给所选的视觉模型处理（自动改写、显式工具或混合模式），使纯文本聊天模型也能处理包含图片的对话。", "image", 3, "vision"),
        E("dsh-vision-mix", "dsh-vision-mix", "把文本、识图和生图 API 组合成一个 Mix 模型并按对话内容自动路由：纯文本走聊天模型，用户图片和 Agent 截图走识图模型，后续可继续追问同一张图；还支持图片生成与编辑及会话级调用记录。", "image", 3, "vision"),
        E("dsh-vision-tools", "dsh-vision-tools", "DeepSeek Harness 视觉能力全家桶：vision_understand 工具（OpenAI 兼容视觉 API，默认免费智谱 GLM-4V-Flash）+ 粘贴/拖拽/按钮三入口识图。", "misc", 3, "vision"),
        E("dsh-course-assistant", "dsh-course-assistant", "把课程文件（PPTX、PDF、DOCX、Markdown）解析成目录、带原文引证的分章要点、B 站网课推荐与考纲覆盖检查，并可导出 Anki 卡片和 JSON。", "pdfdoc", 3, "docs"),
        E("dsh-markdown-preview", "dsh-markdown-preview", "产物文件聊天内预览：点击产物 chip 直接在对话中渲染 Markdown（宿主侧 markdown-it + highlight.js 代码高亮）、图片或纯文本，系统应用打开与在文件夹中显示仍一键可达。", "pdfdoc", 3, "docs"),
        E("dsh-mcp-context7", "dsh-mcp-context7", "接入 Context7 托管 MCP 服务，为 agent 提供随版本更新的库文档查询；默认免密钥可用。", "search", 3, "docs"),
        E("dsh-md-annotator", "dsh-md-annotator", "面向 dsh-better-sidebar 扩展的 Markdown 侧边栏预览与源码编辑器，支持块级和文本选区批注，并可将批注作为结构化修改请求发送到对话框。", "pdfdoc", 3, "docs"),
        E("dsh-paperforge", "dsh-paperforge", "论文阅读工作台：论文库、PDF 与 Markdown 笔记并排、每篇论文一个专属 AI 会话。高亮与框选截图自动写入笔记；划词 Ask AI 附带页码与选段；笔记可原地编辑、自动保存；多个会话可汇总成 Summary。", "pdfdoc", 3, "docs"),
        E("dsh-pdf-edit", "dsh-pdf-edit", "面向 PDF 文档的编辑插件,精确编辑PDF文字", "pdfdoc", 3, "docs"),
        E("dsh-zju-lecture-note", "dsh-zju-lecture-note", "把浙大智云课堂（classroom.zju.edu.cn）回放整理成 Markdown 复习讲义，并在本地用 Typst 排成同名 PDF。字幕公开免登录；投影截图需在插件设置中开启，且需浙大登录态。抓取内核来自 nzw806/zju-lecture-summerizer-；可选填空笔记用 MIT", "pdfdoc", 3, "docs"),
        E("obsidian-workbench", "obsidian-workbench", "DSH 内的 Obsidian 风格 Markdown 工作台：浏览、编辑、预览、创建、移动和删除所选本地仓库中的笔记。", "git", 3, "docs"),
        E("office-ppt", "office-ppt", "通过 UNO 驱动本机安装的 LibreOffice 做 PPT，而不是用 JavaScript 写 OOXML：`lo_build` 用结构化幻灯片真开一份 Impress 文档，再由 LibreOffice 导出可编辑的 PPTX/ODP、PDF 与逐页 PNG；`lo_render` 重新渲染", "pdfdoc", 3, "docs"),
        E("ultra-documents", "ultra-documents", "侧边栏里的 Artifacts 式文档：AI 生成独立的 HTML 文档，你可以对任意位置批注、一键交给 AI 改出新版本，也可以自己直接修改文字和格式。每次修改都是新版本，内容只存在本地。基于 tdoc（https://github.com/tornado-doc/tdoc）改造的本地化 DSH", "misc", 3, "docs"),
        E("deepseek-cost-meter", "DeepSeek Cost Meter（每轮费用）", "展示每轮及会话费用、渠道/模型明细和套餐用量，并在侧栏显示已登录的 DeepSeek 账号余额。", "session", 3, "usage"),
        E("dsh-activity-heatmap", "dsh-activity-heatmap", "侧边栏里的活动热力图，一格一天，支持近 30、90、365 天，统计 token 用量与按模型估算的费用，单价可自行修改。", "text", 3, "usage"),
        E("dsh-billing-1", "DeepSeek-Harness-chat-billing", "会话头部徽标显示 DeepSeek 账户余额、本轮对话花费与今日全部会话总花费；每轮消息操作行前置本轮花费，详情面板含按模型计价与今日会话消费排行。官方峰谷定价，余额取自 /user/balance API。", "session", 3, "usage"),
        E("dsh-billing-balance", "dsh-billing-balance", "在设置页、输入框下方读数条与可拖动悬浮按钮三处显示 DeepSeek 官方 API 余额与火山方舟 Coding/Agent Plan 套餐额度（5小时/周/月窗口及重置倒计时）。", "time", 3, "usage"),
        E("dsh-bottom-cost", "dsh-bottom-cost", "输入框下方统计栏里的会话费用胶囊：逐轮列出每轮花费与所用模型，并把总额拆成缓存命中与未命中两笔（CNY）；价目表按需从官方定价页刷新。", "text", 3, "usage"),
        E("dsh-commandcode-quota", "dsh-commandcode-quota", "Command Code 余额与额度面板：在输入框下方显示可用余额，以及 5 小时、每周、每月三个额度窗口。", "misc", 3, "usage"),
        E("dsh-dual-checkin", "dsh-dual-checkin", "从本机登录文件完成 Trae 与 WorkBuddy 每日签到，侧边栏展示状态与积分。", "fileops", 3, "usage"),
        E("dsh-minato", "dsh-minato", "可选的只读桥接插件：把 dsh 的会话与 token 实时统计写成一份 JSON 快照，供独立的 dsh-minato 工具箱读取.", "data", 3, "usage"),
        E("dsh-opencode-usage-1", "dsh-opencode-usage", "OpenCode Go 套餐用量显示：输入框下方常驻徽章显示滚动 / 每周 / 每月用量百分比与重置倒计时，点击展开进度卡片；Agent 可经 `opencode_go_usage` 工具随时查询余额。", "codec", 3, "usage"),
        E("dsh-plugin-llm-balance", "dsh-plugin-llm-balance", "DSH 余额与配额悬浮卡片：常驻显示最近使用的最多 3 个 provider，支持 DeepSeek、Moonshot、Kimi For Coding、OpenAI Codex 和 OpenCode Go；自动发现配置，展示配额窗口与重置时间，并支持分档着色、拖动和自动刷新。", "codec", 3, "usage"),
        E("dsh-plugin-opencode-usage", "dsh-plugin-opencode-usage", "在会话窗口左下角的悬浮面板中显示 OpenCode Go 订阅用量（滚动/每周/每月的已用与剩余百分比及重置时间）。", "codec", 3, "usage"),
        E("dsh-prompt-lab", "dsh-prompt-lab", "DeepSeek Harness 的 Agent 结构化提示词优化：将输入栏草稿改写为角色/任务/上下文/约束/格式，支持普通/精简/扩写，弹窗含评分与继续优化，引擎可选本地、hybrid、DSH 或云端 API。", "session", 3, "usage"),
        E("dsh-subusage", "dsh-subusage", "在 DeepSeek Harness 模型选择器旁显示 28 条提供商入口的订阅额度与账户余额，附统一设置页和只读额度查询工具。", "ai", 3, "usage"),
        E("dsh-tide-badge-1", "dsh-tide-badge", "DSH 输入框下方的计费时段与余额药丸：常显账户余额与本次对话花费，并显示峰价/谷价档位与距下次切换的倒计时。峰谷判定含中国法定节假日与周末；本次对话花费按余额差值记账，采样点是插件自带的「对话停止满一分钟后刷新余额」。", "time", 3, "usage"),
        E("dsh-token-usage-dashboard", "dsh-token-usage-dashboard", "根据 DSH 会话日志展示 Token 用量统计、每日与每周热力图、活跃情况和模型排名，并在本地持久保存汇总数据。", "text", 3, "usage"),
        E("dsh-token-usage-sidebar", "dsh-token-usage-sidebar", "为 DSH Web 提供自动发现历史记录的本地持久化 Token 用量统计与紧凑的供应商/模型明细。", "text", 3, "usage"),
        E("dsh-usage-dash", "dsh-usage-dash", "会话用量统计面板：天/小时/分钟三粒度 token 与请求统计、活跃热力图、会话底栏信息接管与回合费用芯片、多条件分时段定价费用估算；复刻自 HaoyueQin/dsh-usage-statistics-panel 并扩展。", "text", 3, "usage"),
        E("dsh-usage-dashboard-plus", "dsh-usage-dashboard-plus", "显示 DeepSeek 余额与今日花费估算，合并外部视觉调用 JSONL 记录，并提供含模型统计、TTFT、缓存率、调用日志、费用估算、筛选与 CSV 导出的会话看板。", "data", 3, "usage"),
        E("dsh-usage-lite", "dsh-usage-lite", "侧边栏面板展示账户余额与本地 Token 用量，包含供应商/模型明细和 27 周每日热力图。", "ai", 3, "usage"),
        E("dsh-usage-meter-harness", "dsh-usage-meter-harness", "DeepSeek Harness 实时用量、费用与余额计量：官方 API 实时查询余额、计费误差 0.02 元内，分本轮/本次会话/整个模型三级费用台账，实时分色档位 Token 速度，输入框旁弹窗即点即看。", "session", 3, "usage"),
        E("dsh-usage-monitor-1", "dsh-usage-monitor", "设置页用量仪表盘：从会话日志汇总 token、请求、输出 token 与缓存命中率，含堆叠图，并按供应商、模型或工作区分组列表。", "session", 3, "usage"),
        E("dsh-usage-panel-2", "dsh-usage-panel", "多平台 LLM 账号余额与额度面板：配置 DeepSeek、OpenRouter、Kimi、智谱、MiniMax、NewApi 或自定义端点，定时自动查询并绘制趋势图，余额/额度阈值与窗口重置经多通道推送通知。", "time", 3, "usage"),
        E("dsh-usage-stats-2", "dsh-usage-stats", "在 DSH 桌面端看清每一次请求的 Token、费用与速度，按模型和供应商汇总花费，统一同一模型的不同名称，核对余额并比较模型实际表现。", "ai", 3, "usage"),
        E("dsh-usage-wallet", "dsh-usage-wallet", "dougen/dsh-deepseek-usage 的非官方分支（基线 v0.16.0）：侧边栏余额与配额卡片，显示当前模型提供商的账户读数：DeepSeek、Moonshot、Z.ai、OpenRouter、Kimi、MiniMax、OpenCode；并为 qwen-token-plan 读取阿里", "git", 3, "usage"),
        E("dsh-wakatime", "dsh-wakatime", "在 WakaTime 中记录 DSH 读取文件、查看图片和编辑代码的活动，并准确统计 AI 新增和删除的代码行数。DSH 回复期间持续记录活动，多个文件的记录批量上报，并在并行运行的 DSH 进程间统一控制各项目的上报频率。自动安装和更新 wakatime-cli。", "image", 3, "usage"),
        E("chengxiao", "CHENGXIAO", "用一次性配对码把两台 DeepSeek Harness 机器连起来——局域网直连，或跨网络经端到端加密中继（默认自带官方中继，零配置）——让一边的 agent 在另一边执行任务、交换文件，各自文件都留在本机。", "codec", 3, "remote"),
        E("dsh-auto-trust-all", "dsh-auto-trust-all", "动态信任所有实际到达的 Host 并把 web 默认绑定翻转为 0.0.0.0：泛域名等无法枚举的入口免改启动命令，认证层不动，超出容量的 Host 按 LRU 淘汰。", "misc", 3, "remote"),
        E("dsh-cherry-bridge", "dsh-cherry-bridge", "把 DeepSeek Harness 会话桥接到局域网内的 Cherry Studio 桌面端——二维码配对、14 个 cherry_* 工具（agent/会话/历史/交互）与设置页（设备管理、按工作区的工具启用范围）。", "codec", 3, "remote"),
        E("dsh-hardssh", "dsh-hardssh", "为 DeepSeek Harness 提供 SSH 工作区与运维：把服务器目录绑定为工作区，fs/命令经 cordis seam 替换透明路由到远端主机，并带 Web 终端、文件传输、隧道、集群执行与主机管理。", "fileops", 3, "remote"),
        E("dsh-lark-claw", "dsh-lark-claw", "DeepSeek Harness 的飞书/Lark 网关：按话题持久化会话、实时执行卡片、图片与文件输入、聊天内审批和提问、来源白名单，以及用自然语言创建可持久化的一次性或周期 Agent 任务。", "image", 3, "remote"),
        E("dsh-mobile-1", "dsh-mobile", "在手机浏览器里用 DSH。点会话顶栏的手机按钮（或插件设置卡）打开手机访问、扫二维码，手机就打开电脑上 DSH 进程提供的官方网页界面，会话相同、实时同步，人不在电脑前也能跟进正在跑的任务、回消息、点批准。DSH 里内置一个网关（端口 18765）转发网页界面，并替手机处理桌面端登录。一个二维码在", "codec", 3, "remote"),
        E("dsh-mobile-pwa", "dsh-mobile-pwa", "基于 dsh-mobile-gate 的完整移动端 PWA：安全远程访问网关 + 可安装到主屏（manifest + service worker）+ 离线可用 + 触屏手势（下拉刷新/边缘返弹/捏合缩放字体）+ agent 完成推送 + 触屏优先布局，桌面零影响。", "ai", 3, "remote"),
        E("dsh-mobile-xc", "dsh-mobile-xc", "DSH 移动端 UI 适配插件 - Overlay 抽屉导航、玻璃卡片设计、Safe Area 全覆盖、PWA 支持。", "misc", 3, "remote"),
        E("dsh-plugins-20", "dsh-lan-gateway", "完整的 Web GUI 局域网/远程访问方案：0.0.0.0 绑定、crypto.randomUUID polyfill、令牌门卫（401 登录页 + WebSocket 拦截，回环豁免）、特权围栏与设置持久化放行，附带幂等安装器与升级恢复。", "codec", 3, "remote"),
        E("dsh-reach", "dsh-reach", "把 DSH 的审批卡与提问卡推送到 IM 渠道（先支持微信），可在聊天里直接作答，带会话控制台、逐渠道安全与开放推送服务。", "session", 3, "remote"),
        E("dsh-remote-access-web", "remote-access-web", "DSH Web GUI 反向隧道：通过 frp 把 `dsh --profile web` 发布到公网地址，目录选择器改用应用内浏览器，手机或远程机器可直接打开并管理工作区。", "fileops", 3, "remote"),
        E("dsh-remote-control", "dsh-remote-control", "用手机浏览器继续电脑上的会话：扫码并在电脑上确认设备后，在移动端界面里对话、处理审批、浏览工作区文件、管理设置；支持同一 Wi-Fi 直连或经 Cloudflare Quick Tunnel 连接。", "fileops", 3, "remote"),
        E("dsh-remote-tunnel-easy", "dsh-remote-tunnel-easy", "在设置中扫描二维码，通过 cloudflared 快速隧道在手机上于当前会话中打开 DeepSeek Harness 网页端。", "codec", 3, "remote"),
        E("dsh-rw", "dsh-rw", "Remote-SSH 风格工作区：把 SSH 主机上的远程目录变成原生 DSH 工作区，agent 通过 12 个 rw_* 工具（SFTP/exec）直接操作远程文件，路径限定在工作区内并校验 known_hosts。", "fileops", 3, "remote"),
        E("dsh-telegram-bridge-1", "dsh-telegram-bridge", "DeepSeek Harness 双向 Telegram 远程控制台：实时进度卡片、截图识图、Git 差异对比、Shell 执行与工具审批。未配置 chatId 前首个发送者即被认领为主人；语音转文字需本地 ffmpeg 与 BeeRouter 服务前置支持。", "git", 3, "remote"),
        E("dsh-agent-loop-guard", "dsh-agent-loop-guard", "为 DeepSeek Harness 提供故障关闭式运行时工具调用循环防护。", "misc", 3, "security"),
        E("dsh-auto-approve", "dsh-auto-approve", "自动审批 / 自动审核需要审批的工具调用：先用关键词分桶做零上下文红线匹配，再交由审核模型判类别与风险等级， 按命中行与等级那一格决定自动允许、自动拒绝或转人工；判定没跑成固定转人工，自动拒绝会把原因回传给模型。", "session", 3, "security"),
        E("dsh-pdr-plugin", "DSH-PDR-Plugin", "运行时插件防火墙，仅覆盖经其启动器启动的会话（DSH Desktop 桌面应用注入不进去，不在覆盖范围）：插件发起的文件、网络、子进程调用会归属到发起它的插件，并用该插件自己声明的需求去衡量——本职范围内的行为零打扰，越出声明才被记录。归因是尽力而为，不是保证：覆盖不到的调用退回 host，不会被记", "sysinfo", 3, "security"),
        E("dsh-plugin-vet", "dsh-plugin-vet", "DSH 插件信任流水线：确定性静态扫描判定、可选运行时守卫与蜜罐诱饵、agent 审查协议技能与浏览器盾牌状态灯，只报警不执法。", "ai", 3, "security"),
        E("dsh-rule-engine", "dsh-rule-engine", "dsh 规则执行引擎：解析 AGENTS.md、硬拦违反规则的工具调用、文本纠察与审计、/guard 命令、版本化文件守卫、自由区域支持（引擎跳过自由区内容）。", "fileops", 3, "security"),
        E("dsh-secret-scrub", "dsh-secret-scrub", "不可逆密钥脱敏守护：在访问密钥、Bearer 令牌、私钥块进入会话日志和模型请求之前，将其改写为 `[REDACTED:<category>]` 占位符。", "session", 3, "security"),
        E("dsh-skip-browser-auth", "dsh-skip-browser-auth", "替换 DSH Web 的连接提供方以整体跳过 BrowserAuth，打开 Web 地址即可直接使用、无需抄写启动 URL 中的随机 token；按九个已验证的 DSH 版本对严格成对门控，遇到未知或混用版本自动休眠，卸载即完全恢复官方行为，仅限 Web profile。", "fileops", 3, "security"),
        E("dsh-workspace-api-key", "dsh-workspace-api-key", "为每个工作区或单个会话单独绑定一把 DeepSeek API key，生效 key 失效或服务商不匹配时提醒，且绝不自动替换 key。", "text", 3, "security"),
        E("dsh-yolo-mode", "dsh-yolo-mode", "沙箱升权申请的 LLM 自动审批：内置预设，fail-closed 兜底。", "ai", 3, "security"),
        E("qiushi-dsh-evidence-audit", "qiushi-dsh-evidence-audit", "把工具结果与会话事件的 receipt 写入本地哈希链 JSONL，不保存提示词、工具参数、结果正文或原始会话 ID。", "codec", 3, "security"),
