        E("dsh-repo-setup", "dsh-repo-setup", "只读仓库体检引导工具（repo_setup_scan）：识别技术栈/测试/文档/git/数据库线索，给出插件、MCP 与卫生文件的安装建议。", "git", 2, "tools"),
        E("dsh-routed-subagent", "dsh-routed-subagent", "新增 subagent_routed 工具：从任意会话发起一次性子 Agent，并完整挂载到任意 agent preset 上运行，支持按次覆盖模型/提供方，并在调用前预检模型可用性。", "session", 2, "tools"),
