        E("dsh-venv", "dsh-venv", "为每个 DSH 工作区/项目提供独立的运行时环境：自动接管或创建项目本地 Python venv（.venv_local/python），并自动识别项目所用运行时（python venv / node / go）接入其工具链与环境变量——python / pip 永远走项目环境，绝不静默落到系统 P", "misc", 2, "tools"),
        E("dsh-vm-tester", "vm-blackbox", "面向 DeepSeek Harness 的黑盒 GUI 测试：AI 测试员只靠截图与键鼠操作真实 Windows 虚拟机，判定必须由像素支撑，而不是读日志或源码。包含 dsh-vm-tester 插件的十二个 vm_* 工具（状态、UI 元素树、截图、点击、输入、凭据注入、按键、普通键、等待、快照、", "image", 2, "tools"),
        E("dsh-wakatime-plugin", "dsh-wakatime-plugin", "将DSH的每一次Agent交互量化为可视化表现指标并自动同步至WakaTime,用数据展示你与Agent协作的生产力", "ai", 2, "tools"),
        E("dsh-webui-launcher", "dsh-webui-launcher", "跨平台 Web UI 启动器：提供 webui_start/stop/status/open 模型工具、/webui start|stop|status|open 斜杠命令、设置页启动卡片，以及可选的桌面快捷方式——隐藏控制台启动 Web UI，完全就绪后自动打开浏览器，默认使用 dsh 官方图标。", "archive", 2, "tools"),
        E("dsh-windows-c-cleanup", "dsh-windows-c-cleanup", "DSH 的 Windows 系统盘（C 盘）清理能力：按规则库扫描、五级安全分级、带台账可回滚的暂存区、UAC 提权与迁移到其他盘 —— 既有模型工具，也有 Web 面板。", "git", 2, "tools"),
        E("dsh-workbuddy-websearch", "DSH-Workbuddy-WebSearch", "把 WorkBuddy 桌面 App 的网络搜索作为 dsh 的 web_search 提供方，复用 App 已有的登录状态，无需额外配置。", "search", 2, "tools"),
        E("dsh-wx-archive", "dsh-wx-archive", "wx_archive 工具：把公众号文章链接经 2100laike 存档服务转成永久 Markdown 快照——图片转存不裂链、删文后仍可读、重复提交去重秒回不耗额度、content_kind 区分图文与贴图（图片消息）、带 PAT 可 refresh 强制重抓。依赖第三方 2100laike 存档", "git", 2, "tools"),
        E("feishu-dsh-plugin", "feishu-dsh-plugin", "飞书（Lark）集成：25 个工具，覆盖群消息与聊天记录、云文档（含知识库页面、自动生成的图表与图片）、多维表格记录、电子表格区间读写与文档授权，基于企业自建应用。", "image", 2, "tools"),
        E("huixuan-assistant", "huixuan-assistant", "购物助手：在 DSH 对话里搜索、对比、挑选并推荐商品，支持比价与选购建议，覆盖电商购物场景，数据来自拼多多开放平台官方 API，含价格、销量、服务标签、商品图与推广链接。", "search", 2, "tools"),
        E("hwfee-dsh-1", "git-bash", "Windows 上的 Git Bash 默认 shell。从 git --exec-path 定位 bash.exe（不用 WSL 的 bash），提供 run_shell 工具；找不到 Git Bash 时明确降级，而不是让插件消失。", "git", 2, "tools"),
        E("insta360-ai-content-studio", "insta360-ai-content-studio", "Insta360 GO 3S 自动每日内容管线：BLE/WiFi 遥控拍摄鱼缸素材、无线取回、ffmpeg 质量评估与决策记录、自动剪辑（选段/旁白/配乐/字幕）、biliup 投稿（默认 dry-run）。", "media", 2, "tools"),
        E("linkdigest-mcp", "linkdigest-mcp", "把小红书、抖音、TikTok、YouTube 或 X 链接转成文本：带时间戳的转写、屏幕文字、逐图描述与 OCR、正文与元数据。通过 streamable HTTP 挂载托管的 MCP 服务。", "image", 2, "tools"),
        E("mackorn-cone-crusher", "MACKORN-hydraulic-cone-crusher", "MACKORN NH/NS 单缸液压圆锥破碎机的选型与破碎筛分生产线设计：需求表录入、设备选型、整线配置、方案书生成、产品粒度仿真与实测标定。21 个工具、6 个技能、一个 MCP 服务器，零运行时依赖。", "devops", 2, "tools"),
        E("portfolio-os", "dsh-portfolio-os", "DSH 内的自包含个人资产与投研工作台：支持本地注册、资产导入与配置视图、市场和新闻跟踪、研究库及用户自行配置的 AI 简报；内置 Windows Runtime，数据保存在本机。", "misc", 2, "tools"),
        E("semantic-search", "semantic-search", "面向 DeepSeek Harness 的本地语义代码搜索：片段级符号感知索引、离线词法 embedding（或 OpenAI 兼容端点）、向量+BM25 混合检索并以 RRF 融合——三个 dsh 工具外加 sema CLI。", "search", 2, "tools"),
        E("weread-export", "weread-export", "微信读书多目标导出：通过官方 Skills API Key 查看书架、导出划线/想法到 flomo、本地 Markdown 或 Notion，可选按自定义 LLM prompt 整理后再导出。", "pdfdoc", 2, "tools"),
        E("what-sub-agents-doing-now", "what-sub-agents-doing-now", "注册一个只读工具，让父代理读到每个子代理实际在做什么，而不只是它有没有在跑：子代理自己写下的进度旁白，时间早的在前，按序号向前翻页，给出距上次查看已过去多少步，并在连续五步以上没有新旁白时给出沉默计数。", "net", 2, "tools"),
        E("win-pilot", "win-pilot", "面向 AI Agent 的 Windows 电脑操控与 computer use 插件，支持可复用窗口目标、UIA 无障碍定位、窗口绑定截图、后台优先的验证输入、隔离 Chromium 自动化、MCP、CLI 和可安装 Skill。", "image", 2, "tools"),
        E("xander-zaozao-xiaban", "xander-zaozao-xiaban", "Xander 早早下班亚马逊运营工具包：提供 33 个原生 xander_* 工具和 7 个技能，涵盖竞品、关键词、Listing、广告、补货与利润；亚马逊改动须准备精确提案、取得明确批准并回读核验。", "misc", 2, "tools"),
        E("dsh-anchor", "dsh-anchor", "DSH 会话指令定锚：新会话的第一个 step 把自由组合的指令块作为插件来源消息注入，之后在完成压缩、跨过设定轮数、或计量到的上下文压力越过阈值时重锚。`/anchor` 命令可按需定锚且不触发模型调用；设置页管理分页预设库、注入顺序、重锚来源与字数上限。", "archive", 2, "session"),
        E("dsh-archive-sessions", "dsh-archive-sessions", "归档会话管理：在设置页新增“归档会话”，列出所有已归档会话，支持恢复与二次确认后的永久删除。", "archive", 2, "session"),
        E("dsh-assembly-resume", "dsh-assembly.resume", "将本地 Codex CLI/Desktop、Claude Code CLI 和 Claude Desktop 会话导入 DSH：按项目分组，保留语义历史和工具活动，可绑定原工作区或新工作区，并由 DSH Agent 继续对话。", "session", 2, "session"),
        E("dsh-attention-health", "dsh-attention-health", "内容退化检测（思考打转、输出复读）+ 继续/交接成本裁决 + 零模型交接文档。", "ai", 2, "session"),
        E("dsh-autorestart", "dsh-autorestart", "重启不丢工作：等所有对话空闲后自动重启，重启后接着干、不中断；已有守护的机器交给守护重启，绝不双开。 还顺手治一个常见毛病：反复启动攒下的过期登录 cookie 会把请求头撑爆、让 DSH 起不来，插件在每次重启前先清掉它们。 每次重启前自动备份配置和已装插件，默认留 2 份、最多 10 份，旧的和", "session", 2, "session"),
        E("dsh-belief-merge", "belief-merge", "把其他会话的上下文合并进当前回合：按证据裁决冲突、前提被撤回时同步撤回结论、用信任格抵抗跨会话提示注入，并在 token 预算内打包。附带评测基准。", "archive", 2, "session"),
        E("dsh-branch-inbox-guard", "dsh-branch-inbox-guard", "清除 DSH 分支会话从 fork 父会话继承来的排队提问，让分支的第一轮执行你在分支里输入的问题，而不是父会话的下一句。", "git", 2, "session"),
        E("dsh-btw-1", "dsh-btw", "每条已完成回答操作行上的侧问抽屉：追问在独立且自动归档的会话中进行，携带此前的已完成对话文本（只读，上限 48000 字符）作为参考，主会话零写入；模型默认继承主会话并可在抽屉内切换，附上下文占用圈。", "archive", 2, "session"),
        E("dsh-bulletin-dispatch", "dsh-bulletin-dispatch", "同一台电脑上会话之间的「单子」：会话用标题里的编号前缀表明自己属于哪张桌；单子投给某张桌，由那张桌最先开始干活的那个会话取走 —— 桌是地址，路过的会话不会收到它。", "session", 2, "session"),
        E("dsh-compact-threshold", "dsh-compact-threshold", "输入框旁的上下文自动压缩阈值控制器：20%-80% 滑条按 step 重写运行中 BasicCompactionEngine 的配置，显示当前用量、上下文窗口与实际触发线；阈值降到当前用量以下且 Agent 空闲时立即压缩。", "archive", 2, "session"),
        E("dsh-context-console", "dsh-context-console", "上下文控制台：通过轨迹墙与库存视图检查并模拟 DSH 上下文消费，并由内置消息锻造台创建、注入、导入或安全修复会话消息。", "session", 2, "session"),
        E("dsh-context-guard", "dsh-context-guard", "长会话越跑越贵，平台到点还会把上下文压掉。这个插件做三件事：在会话标题旁显示当前上下文占了多少，鼠标停上去能看到这个数是怎么来的；过 45% 时往工作目录的 HANDOVER.md 写一份交接草稿，记下改过哪些文件、花了多少钱、最近几轮在聊什么；到 60% 提醒你一次该收尾了。平台压缩发生时，它把压", "archive", 2, "session"),
        E("dsh-context-guardian", "context-guardian", "为 compaction-basic 提供压缩兜底：当 LLM 摘要抛错、返回空内容或放不进上下文窗口时，改为确定性编译该区段，每行带 seq 指针（内置 dsh-compaction-instant 编译器）。提供 recall、search 工具与 /recall、/context 命令，占用超", "archive", 2, "session"),
        E("dsh-context-reclaim", "dsh-context-reclaim", "上下文治理：折叠超大工具结果、收拢工具面、稳住提示词缓存命中，长会话不再越聊越贵。", "session", 2, "session"),
        E("dsh-continue-on-limit", "dsh-continue-on-limit", "dsh 网页端输出上限自动继续：本地模型输出到上限出现提示时，自动发送「继续」让回复接上；双源截断检测、防死循环保护，完全无 UI。", "ai", 2, "session"),
        E("dsh-conversation-archive", "dsh-conversation-archive", "在 Windows 上管理 DSH 已归档会话，支持搜索、批量取消归档与删除、AI 辅助文件保留，以及经过校验的本地或网络目录备份。", "archive", 2, "session"),
        E("dsh-conversation-share", "dsh-conversation-share", "分享任意段落的对话。", "session", 2, "session"),
        E("dsh-dsml-guard", "dsh-dsml-guard", "抹掉漏进助手正文的 DSML 标记；只在确实毫无产出的轮次补一条继续——整段调用写进正文且没有发出任何工具调用，或只剩闭合标签且正文近乎为空。上游抖动类错误会续跑，额度、限流、鉴权与上下文超限一律不续。适用 DSH 0.2.1-rc.2 起、0.3.0 以下，Node 20 起。", "session", 2, "session"),
        E("dsh-fork-relink", "dsh-fork-relink", "DSH 的 fork 伴随插件:官方 fork 发生后,把原会话的直接子 agent 复制到 fork 出的新对话下(递归复制整棵子树,副本经官方 agent API 创建),每个副本留在磁盘上成为可被官方恢复路径唤醒的冷会话——新对话保留子代理面板,并能继续给这些子代理发消息;原件仍留在旧分支。", "git", 2, "session"),
        E("dsh-message-forward", "dsh-message-forward", "DSH 会话间消息转发：把单条模型回复、用户消息或多选合并的消息与图片从上游会话提取出来投递到另一个会话，支持静默发送、填入草稿、发送并跳转三种投递方式，并可套用提示词模板。", "image", 2, "session"),
        E("dsh-pause-resume", "dsh-pause-resume", "会话头一个按钮停掉回合、目标和后台任务，写盘；重启后同一个按钮把工作接回来。", "session", 2, "session"),
        E("dsh-power-switch", "dsh-power-switch", "会话头部的电源按钮，两个动作，都需再点一次确认。重启结束的是 Electron 主进程本身（taskkill /F 不带 /T），因此不会出现崩溃弹窗；宿主在 IPC 断开后自行优雅退出，分离的 helper 等单实例锁释放后重放同一可执行文件，并以真实窗口句柄确认新实例已启动。关闭同理但不重新拉起", "sysinfo", 2, "session"),
        E("dsh-preset-switcher-fork", "dsh-preset-switcher-fork", "随时切换当前会话的代理预设（模式），对话开始后也能切：会话头下拉菜单，由受限的 POST /preset-switch/api 路由支撑；该路由还会修复记录中预设已被删除的会话。jeffcwj/dsh-preset-switcher 的分支，已适配 DSH 0.2.1。", "git", 2, "session"),
        E("dsh-projectless-session", "dsh-projectless-session", "在 DSH 工作区选择器中添加无工作区会话入口，创建按日期整理的独立目录，并让已开始的会话在未分组区域保持可恢复。", "time", 2, "session"),
        E("dsh-prompt-lib", "dsh-prompt-lib", "提示词库存放在插件配置中，含 Settings 页面与输入框选择器：勾中的提示词注入该会话的每一步模型调用，subagent 继承其最近祖先会话的选择。", "session", 2, "session"),
        E("dsh-prompt-stash", "dsh-prompt-stash", "本地、按会话隔离的 LIFO 输入暂存：临时收起未完成的输入，之后安全恢复并继续编辑。", "git", 2, "session"),
        E("dsh-prompt-studio", "dsh-prompt-studio", "带实时预览的用户/内置 system prompt 分节编辑器。", "ai", 2, "session"),
        E("dsh-recent-sessions-1", "dsh-recent-sessions", "一块面板列出所有工作目录里的最近会话：时间分组、两种排序、内容检索、在文件管理器中显示目录，以及只存在本机、回到那个会话时提示填入草稿的想法。", "time", 2, "session"),
        E("dsh-redo", "dsh-redo", "给你发出的每条消息加上「重新生成」和「编辑重发」：重新生成一键用同样的文字重新回答，不经过输入框；编辑重发就地撤回这条消息及其之后的内容——从时间线和模型上下文里一起消失，不新建会话也不开新分支——再把文字和图片放回输入框，改完发送就从那一条重写对话。带文件（非图片）的消息两个操作置灰。", "git", 2, "session"),
        E("dsh-reference-session-collector", "dsh-reference-session-collector", "DSH 会话原文只读投影同步器（drsc）：只读扫描 ~/.dsh/sessions/** 会话日志，经内置 leaf 解码器解 zstd/分段帧日志后投影进插件自有 SQLite（node:sqlite，segments/replaces + FTS5），由单条 fenced HTTP 路由提供", "codec", 2, "session"),
        E("dsh-save-chat", "dsh-save-chat", "把整轮问答（问题 + 完整回答）存成工作区里的纯 Markdown；把值得留的提升进跨项目个人知识库，模型可按需检索。无数据库、零运行时依赖。", "pdfdoc", 2, "session"),
        E("dsh-session-drafts", "dsh-session-drafts", "Cursor 风格的新会话：每次点击都新建一个空白草稿会话（首条消息前即持久化），不再复用工作区唯一的空会话；侧栏新增草稿切换器，可同时保留多个空会话。", "session", 2, "session"),
        E("dsh-session-eater", "dsh-session-eater", "DSH 侧边栏的会话清理：把会话行拖到余额挂件的小胖鱼嘴边，它张嘴吃掉 —— 会话目录移入回收站，不是 rm。删除前只问一句「消耗了多少 token，真的给我吃吗？」（可在设置里关掉）；撤销走常驻回执或设置里 12 条持久台账。点侧栏那条小鱼直达插件设置：换形象、拖拽校准嘴位、改写全部 17 段界面", "fileops", 2, "session"),
        E("dsh-session-insights", "dsh-session-insights", "回头看看你是怎么使用 AI 的：`/session-insights` 会整理一段时间内的 DSH 会话，找出哪些做法有效、哪些问题总在重复、最终真正留下了哪些成果，并生成一份保存在本机的复盘报告。", "time", 2, "session"),
        E("dsh-session-lens", "Session Lens", "DeepSeek Harness 的会话洞察，并可一键导出为可分享的 HTML 回放。", "session", 2, "session"),
        E("dsh-session-manager-2", "dsh-session-manager", "设置 → 插件 下的会话管理面板：列出全部会话的标题、工作目录、agent 预设、更新时间、轮次与步数，展开可查看消息历史，删除非运行中的会话，并经浏览器 Blob URL 导出为 JSON 或 Markdown。", "pdfdoc", 2, "session"),
        E("dsh-session-manager-5", "dsh-session-manager", "会话行右键菜单与侧边栏会话管理：置顶、重命名、归档、分叉、导出、复制工作目录/会话 ID/深链，在资源管理器或新窗口打开。", "archive", 2, "session"),
        E("dsh-session-messaging", "dsh-session-messaging", "跨会话与跨工作区通信：session_list 按最近活跃或标题查找顶层会话，session_send_message 投递带来源标注的消息（支持 steer/queue，按需冷恢复已存储会话），session_create 新开带标题的顶层会话交代任务，前端渲染器把转发消息显示为标注发送方会话标题", "session", 2, "session"),
        E("dsh-session-mover", "dsh-session-mover", "在侧边栏把会话直接拖到其他工作区的标题行即可移动：目标工作区生成携带完整历史的新会话，原会话归档。", "archive", 2, "session"),
        E("dsh-session-organizer", "dsh-session-organizer", "两级侧边栏组织器：工作区分组 + 工作区内嵌套会话文件夹，支持拖拽、会话状态点、待处理会话概览与手动未处理标记。", "fileops", 2, "session"),
        E("dsh-session-plugin", "dsh-session-plugin", "在输入框内按 ↑/↓ 回填历史消息，并支持右键归档（隐藏）工作区会话。", "archive", 2, "session"),
        E("dsh-session-plus", "dsh-session-plus", "DSH Web 侧栏归档目录：将会话恢复到原工作区槽位、删除会话日志，或从用户消息修改并分支为新会话。", "git", 2, "session"),
        E("dsh-session-port", "dsh-session-port", "把会话连同附件导出为压缩包，或把这样的压缩包导入为当前工作区里的新会话。", "archive", 2, "session"),
        E("dsh-session-purge", "dsh-session-purge", "在侧栏「已归档」会话的菜单里加一行彻底删除，一次清掉会话日志、投影缓存与工作区登记。", "archive", 2, "session"),
        E("dsh-session-recycle-bin", "dsh-session-recycle-bin", "DeepSeek Harness 会话回收站：从会话行菜单删除（或从侧栏标题栏批量移入）后，会话进入回收站，默认保留 15 天（设置里可选 7 / 15 / 30 天），到期条目自动清除；回收站表格显示每条还剩几天，可还原回原工作区，也可单条彻底删除或清空。", "data", 2, "session"),
        E("dsh-session-remover", "dsh-session-remover", "在侧栏会话行菜单中增加「删除对话」与「批量删除」；删除的对话及其子代理会话移入 Windows 回收站，可从回收站还原。", "net", 2, "session"),
        E("dsh-session-save", "dsh-session-save", "把整个 DSH 会话存成单个 .dsproj 工程文件，并能再打开回来。会话标题栏上多了打开、保存、另存为三个按钮和自动保存开关，空会话页面另有自己的打开入口。第一次保存会问存到哪里，之后一键覆盖；打开 .dsproj 会导入该会话并切过去，按需可以把包里的工作区记忆合并回本机。", "fileops", 2, "session"),
        E("dsh-session-search-1", "dsh-session-search", "在所有或指定工作区、会话中搜索已存储的 DSH 对话文本，支持精确、正则表达式、拼写容错及词内子序列匹配。", "text", 2, "session"),
        E("dsh-session-status", "dsh-session-status", "为每个会话设置项目状态标签（内置进行中/已结项/搁置中+自定义标签，颜色可调），在侧栏、对话头部与悬停卡片中显示。", "session", 2, "session"),
        E("dsh-session-task-tags", "dsh-session-task-tags", "为每个会话标记长期任务或短期任务、记录创建时的 Agent 模式，并在你设定的归档时间窗结束后自动归档。", "archive", 2, "session"),
        E("dsh-session-title-pattern", "dsh-session-title-pattern", "把 dsh 会话标题统一成「日期｜类型｜主题」（类型与主题由模型对整段对话总结），并支持可逆的会话隐藏：暂时不用的会话从侧边栏收起，不删除、随时一键显示回来。", "time", 2, "session"),
        E("dsh-session-xc", "dsh-session-xc", "DSH 会话管理增强插件 - 工作区会话数展示、归档会话面板（支持恢复/删除）、拖拽移动会话到其他工作区。", "archive", 2, "session"),
        E("dsh-set-workspace", "dsh-set-workspace", "给 Windows 文件管理器加右键项：把文件夹设为 DSH 工作区并切换到它，DSH 未运行会自动拉起。", "fileops", 2, "session"),
        E("dsh-share-1", "dsh-share", "将当前会话以只读、token 保护的 HTML 快照分享到局域网，附带会话统计与 Markdown 渲染。", "pdfdoc", 2, "session"),
        E("dsh-side-chat-plus-plus", "dsh-side-chat-plus-plus", "DeepSeek Harness 多标签侧聊增强：可引用整条消息，也可在回复生成中选中文本追问（无需等待回复完成）；右侧停靠面板随 better-sidebar 开关在覆盖与让位间自动切换。", "session", 2, "session"),
        E("dsh-snapcompact", "dsh-snapcompact", "DSH 的位图帧上下文压缩插件：把被丢弃的对话历史渲染成像素字体 PNG 帧，交给支持视觉的模型直接读回；整个过程本地、确定，不调用任何辅助模型。", "image", 2, "session"),
        E("dsh-takeover", "dsh-takeover", "会话接管：只读拉取九家外部 agent（Claude Code / Codex / OpenCode / ZCode / Pi / WorkBuddy / Cursor / Grok / Gemini CLI）的本地会话，蒸馏成六段交接卡，输入框「接力」按钮一键接管；/handoff 把当前会话寄存", "codec", 2, "session"),
        E("dsh-task-relay", "dsh-task-relay", "跨会话任务队列与交接摘要：会话与子 agent 在共享的文件队列上投递、认领、完成、取消任务，并留下交接摘要供后续会话查看。", "fileops", 2, "session"),
        E("dsh-tool-result-trimmer", "dsh-tool-result-trimmer", "即时、尾部加权、行吸附的工具输出修剪插件：挂载于执行流水线即时截断超大命令输出，内置语义提纯器与 ANSI 剥离。", "misc", 2, "session"),
        E("dsh-tool-session-delete", "dsh-tool-session-delete", "在侧栏上下文菜单中添加删除会话操作，删除前通过模态框实时展示日志大小与活跃状态，并完整清理日志文件、投影缓存与内存注册表杜绝复活。", "sysinfo", 2, "session"),
        E("dsh-toolong-warning", "dsh-toolong-warning", "统计每段对话成功完成的压缩次数并常驻悬浮窗，只有反复压缩过、且此后又烧掉大量 token 或上下文占用过高时才提醒；三个阈值都可在设置页调整。", "archive", 2, "session"),
        E("dsh-turn-delete", "dsh-turn-delete", "从 DSH 会话中删除一个已结束的轮次而不删除会话本身——最后一条助手回复旁的垃圾桶按钮会把该轮的提问、这条回复与工具记录从对话界面和模型上下文中移除，而 Session id、标题、之后的轮次与只追加日志保持不变；删除以持久 tombstone 记录，刷新后依然生效。", "session", 2, "session"),
        E("dsh-whale-post-bus", "bus", "DeepSeek Harness 会话之间的文件信箱：每封信都用 HMAC 与正文摘要封好，收件人通过名单接口解析，默认离线投递——投不出去的信留在信箱里等人来收，不会丢。", "fileops", 2, "session"),
        E("dsh-win-minimal", "dsh-win-minimal", "Windows 极简模式 preset：单句 persona、三工具、无运行时上下文。", "session", 2, "session"),
        E("dsh-workspace-migrate", "dsh-workspace-migrate", "按工作区迁移 DSH：把一个项目的会话、文件与附件打包，在新机器上还原到指定根目录并重写历史绝对路径，之后只增量同步改动的文件。", "archive", 2, "session"),
        E("organize-workspace-sessions", "organize-workspace-sessions", "整理 DeepSeek Harness 工作区会话，按 类别｜主题 重命名并给出归档、改名与待判断建议。", "archive", 2, "session"),
        E("agnes-ai-for-dsh", "agnes-ai-for-dsh", "为 llm-pi-ai 预声明 Agnes AI 供应商：4 个多模态对话模型，以及图像与视频生成工具。", "image", 2, "model"),
        E("deepseek-harness-acp", "deepseek-harness-acp", "把 Codex、Claude Code、Gemini CLI 等外部 ACP（Agent Client Protocol）Agent 注册为 DSH 模型提供方：Agent 的 thought_level 选项映射为推理等级菜单，Agent 声明 promptCapabilities.image 时", "ai", 2, "model"),
        E("dsh-ai-gateway-provider", "dsh-ai-gateway-provider", "同时接入多台 OpenAI 兼容网关：每台在模型选择器里各成一组、可单独隐藏且配置保留、按地址即可获取自身公开信息，并逐网关管理模型、跑模型测试、按需显示额度。", "ai", 2, "model"),
        E("dsh-antigravity-2", "dsh-antigravity", "Google Antigravity 与 Cloud Code Assist 模型提供方插件，支持 Gemini 3.8 Flash、沙箱端点容灾与多账号配额管理。", "ai", 2, "model"),
        E("dsh-api-thinking", "dsh-ThirdApi-ThinkingMode", "读取每个第三方端点自己的模型列表，同步 llm-pi-ai 的逐模型 reasoningEfforts，让输入框提供模型真实支持的思考等级。", "ai", 2, "model"),
        E("dsh-auto-rerun", "dsh-auto-rerun", "自动重试断连类模型失败（传输中断、超时、限流、5xx、流中断），在同一次智能体回合内接管重试而不是让任务直接断掉。所有选项都能在插件配置或右侧栏面板里调整：重试次数、初始与最大延迟、退避系数与抖动、限流延迟窗口、一直重试的时间上限、换路线的触发条件与次数上限、死路黑名单时长、日志文件。限流按指数退避", "time", 2, "model"),
        E("dsh-chatgpt-subscription", "dsh-chatgpt-subscription", "为 Windows 上的 DSH Desktop 0.2.0-rc.2 提供原生 Codex OAuth 登录、主 Agent 默认模型选择及直连或本地代理设置。", "net", 2, "model"),
        E("dsh-codex-oauth", "dsh-codex-oauth", "在 DSH 设置页添加 Codex 登录入口，调用 llm-pi-ai 内置 OAuth 流程完成浏览器或设备码登录并展示脱敏账号状态，不另建模型适配器或凭证库。", "ai", 2, "model"),
        E("dsh-codex-subscription-pool", "DSH-CODEX-SUBSCRIPTION-POOL", "在 DSH 中使用你的 ChatGPT/Codex 订阅，并支持图像生成和 Web 搜索。", "image", 2, "model"),
        E("dsh-codex-use", "dsh-codex-appserver", "通过本机 Codex App Server，将 OpenAI Codex（ChatGPT）作为可选 DSH Provider。", "misc", 2, "model"),
        E("dsh-connect-agnes-token-plan", "dsh-connect-agnes-token-plan", "一键接入 Agnes 的语言、生图、视频模型到 DSH（默认关），自动填入图片识别与思考强度；登录 Agnes 控制台后（重登需 AGNES_PASSWORD），可看额度窗口（5 小时请求、每周请求、每日图片、视频）、账号累计用量，以及输入框旁的用量胶囊；也支持接入 AgnesCode 桌面端模型（", "image", 2, "model"),
        E("dsh-connect-modelscope-token-plan", "dsh-connect-modelscope-token-plan", "一键接入魔搭社区的语言、生图模型到 DSH（默认关），自动填入图片识别与上下文窗口；还可查看免费魔粒余额、跳转到模型信息页，记录本地调用计数、趋势、限流事件，输入框旁另有用量胶囊显示余额与今日本地调用次数。上述功能仅需填入 API key，不需要登录账号。", "image", 2, "model"),
        E("dsh-connect-workbuddy-1", "dsh-connect-workbuddy", "在本机运行 OpenAI 兼容网关，让 DSH 使用已登录的腾讯 CodeBuddy（WorkBuddy）账号额度：一键安装脚本（含 SHA256 校验）、登录自启计划任务（带防重复启动）、manage.ps1 统一管理（status/start/stop/restart/logs/update/u", "codec", 2, "model"),
        E("dsh-copilot-auth", "dsh-copilot-auth", "为 DSH 内置的 GitHub Copilot 通道补充网页设备码登录与注销入口，预置开箱即用的 Copilot 提供方路由，凭据存入内置凭据库，模型目录仅在首次登录兜底填充一次、永不覆盖已定制的模型条目。", "fileops", 2, "model"),
        E("dsh-deepseek-web", "dsh-deepseek-web", "把 chat.deepseek.com 网页版接成 deepseek-web provider：纯 HTTP 无浏览器，多账号轮换/冷却/自动切换，插件内登录（浏览器，或邮箱+密码+验证码），带 token 用量统计。", "text", 2, "model"),
        E("dsh-delegate-router", "dsh-delegate-router", "给 DeepSeek Harness 的子代理调用做 Flash/Pro 自动分派：轻任务自动用便宜模型、重任务留在强模型，支持手动覆盖与 /delegate 会话模式。", "net", 2, "model"),
        E("dsh-glm-web", "dsh-glm-web", "非官方的智谱清言（chatglm.cn）网页版 provider——用网页版登录态与积分驱动 DSH，支持流式输出与提示词桥工具调用。", "ai", 2, "model"),
        E("dsh-grok-provider", "dsh-grok-provider", "Grok Build 模型接入插件：使用官方 CLI 浏览器登录，动态发现账号可见模型，支持流式推理、工具调用、额度与模型能力设置页。", "ai", 2, "model"),
        E("dsh-llm-openai-completions", "dsh-llm-openai-completions", "面向自定义网关（vLLM / LM Studio / 自托管代理）的 OpenAI-completions 兼容适配器：始终 role:\"system\"、按模型配置驱动思考、Qwen 式 response 切分，并支持视觉模型图片输入（单图 / 多图）。", "image", 2, "model"),
        E("dsh-llm-subscription", "dsh-llm-subscription", "在 DSH 原生模型选择器里加入 Claude、Gemini 与本地 Ollama 模型，复用你已有的 Claude Code / Antigravity CLI 登录态而不是按量计费的 API Key，并为 Claude 提供可用的推理强度选择。", "ai", 2, "model"),
        E("dsh-magpie", "dsh-magpie", "在 DSH 中管理 Magpie 模型清单并写入 Magpie 模型分组：从 /v1/models 全量同步、手动添加，逐模型编辑上下文、输出限额、图片输入与思考档位，支持排序与拖动调整顺序。Windows x64/ARM64 上还可从 yetone/magpie-releases 下载、升级 Ma", "image", 2, "model"),
        E("dsh-model-auto-enricher", "dsh-model-auto-enricher", "DSH 模型补齐助手：解决添加新渠道后还要把几十个模型一个个手动点开调百万上下文、调最大输出、勾多模态发图（\\[text, image]）、配思考强度档位（{low, high, max}）的繁琐痛点，支持设置页添加模型保存后自动补齐与可视化一键补齐。", "session", 2, "model"),
        E("dsh-model-lock", "dsh-default-model-lock", "锁定共享的默认模型：在聊天里切换模型不再改写全局默认值，也不会再被那次切换连带降档推理强度。", "ai", 2, "model"),
        E("dsh-model-memory", "dsh-model-memory", "为自定义 API 模型提供推理强度分级管理与跨会话偏好记忆：在「设置 → 模型」中内联切换 low/medium/high/max，配置写入为原子操作。", "session", 2, "model"),
        E("dsh-model-pricing", "dsh-model-pricing", "DSH 设置页中的模型价格表：约 7,250 个模型 / 213 个提供商（叠加本地路由目录），诚实的最低标价比较、按实际路由计价的会话成本、缓存泄漏归因，以及经验证的促销信息源。", "fileops", 2, "model"),
        E("dsh-model-proxy", "dsh-model-proxy", "把 DeepSeek Harness 的模型 API 请求送进系统代理、自定义代理或 SOCKS 代理，清单之外的请求一律直连。", "net", 2, "model"),
        E("dsh-model-router-4", "dsh-model-router", "统一模型路由：一个逻辑 ModelID 汇聚多家供应商，首 token 前失败自动切换并冷却、健康度择优、按 purpose 三档分级（tier1/2/3）、每候选思考级别，设置面板自动保存即时生效。", "ai", 2, "model"),
        E("dsh-model-switch", "dsh-model-switch", "显式路由 Main、Subagent、web_search 与图像生成，并提供由模型目录驱动的 Composer/Plan Review Picker，支持 Model、Effort、Context、Fast 与 Thinking 变体。", "image", 2, "model"),
        E("dsh-model-sync-2", "dsh-model-sync", "一键同步 / 自动同步供应商模型列表，与 /v1/models 保持一致。", "ai", 2, "model"),
        E("dsh-modellix", "dsh-modellix", "将 Modellix 接入 DSH：使用一个 API Key 在分栏 Design 工作区中提供基于 Schema 的图片、视频与音频生成、实时 LLM 模型目录，以及原生网页搜索与抓取 Provider。", "image", 2, "model"),
        E("dsh-modeltester", "ModelTester", "在 dsh 网页端挂载模型归属面板，用纯本地、零联网的结构指纹匹配（模板特殊 token 泄漏、glitch 金丝雀、tokenizer usage 向量比对）判断当前会话的回答最像 29 家 AI 厂商中的哪一家，每个结论附带可展开的证据账本，另附 12 探针主动取证电池。", "sysinfo", 2, "model"),
        E("dsh-newapi-video", "dsh-newapi-video", "在对话中用 @ 引用素材调用 new-api 中转站的视频大模型生成视频，支持 Seedance 2.0 与快乐马的文生视频和图生视频，覆盖四种中转协议。", "media", 2, "model"),
        E("dsh-nl-model-switch", "dsh-nl-model-switch", "用一句自然语言切换当前 DSH 会话模型，可在 Web、TUI 及 IM 桥接的微信、飞书等对话框中使用，无需操作面板。", "session", 2, "model"),
        E("dsh-oauth-login", "dsh-oauth-login", "通过 Pi 适配器接入订阅 OAuth 和厂商 Plan API Key 登录，使用独立的 DSH 凭据存储。", "misc", 2, "model"),
        E("dsh-opencode-zen", "dsh-opencode-zen", "把 OpenCode Zen 免费模型接入 DSH：8 个实时发现的免费模型，零配置无需 API key；内置持久化额度检测器，自动追踪 429 限流并显示重置倒计时。", "codec", 2, "model"),
        E("dsh-opencode-zen-free", "dsh-opencode-zen-free", "为 DeepSeek Harness 接入 OpenCode Zen 免费模型：默认免 key 走公共额度，内置回环 OpenAI 兼容 shim，并把网关要求的 bash/read 注册为真实可执行工具。", "codec", 2, "model"),
        E("dsh-opencode2api", "dsh-opencode2api", "随 DSH 启动独立的 opencode2api 后端（jasonxu114514/opencode2api，Windows x64/ARM64，无需 Docker 或 OpenCode CLI），退出时只停自己拉起的进程；设置卡片可从经校验和验证的 GitHub Release 安装、更新或回滚后", "codec", 2, "model"),
        E("dsh-provider-proxy-1", "dsh-provider-proxy", "在设置里为每个已启用的 provider 单独配置正向代理（HTTP/HTTPS/SOCKS5），未配置的 provider 与其它流量保持直连。", "net", 2, "model"),
        E("dsh-provider-veark", "dsh-provider-veark", "火山方舟 Coding Plan 的 DeepSeek Harness LLM provider：provider 级 PDF 与图片输入，支持 Responses API 流式。", "pdfdoc", 2, "model"),
        E("dsh-radeon-cloud-patcher", "dsh-radeon-cloud-patcher", "把 AMD Radeon Cloud 接入 DeepSeek Harness 的模型选择器，思考档位按模型逐个声明。provider 定义随插件自带的补丁层交付，而不是写进 profile。", "fileops", 2, "model"),
        E("dsh-reasoning-effort-new", "dsh-reasoning-effort-new", "dsh-reasoning-effort 的分支：输入框里的两级模型选择器（Provider 列表 + 右侧滑出的模型栏）、搜索与紧凑行，并保留推理强度滑块与最高档特效。", "git", 2, "model"),
        E("dsh-request-params", "dsh-request-params", "给 dsh 发出的模型请求加上自己的参数：OpenRouter 供应商路由和备用模型、思考强度、采样参数与自定义请求体字段、请求头，OpenRouter 和其他网关都能用。参数按 dsh 已配置的渠道管理；实时预览显示每个请求会多出什么，请求记录显示实际发出了什么、网关回了什么。", "data", 2, "model"),
        E("dsh-response-id-reuse", "dsh-response-id-reuse", "复用 Responses 存储 ID 续传，隔离重试与分支，并核对历史回放。", "git", 2, "model"),
        E("dsh-subagent-route-pin", "dsh-subagent-route-pin", "注册一个包装 provider，让被委派的子代理走自己的 LLM 路由——单发子代理经 provider.start，Agent Teams 成员经 startActivation 上的钩子——主 agent 仍用自己的模型。附带设置页选择路由、按专家覆盖的配置文件、报告钩子挂在哪条缝上的能力标志，", "archive", 2, "model"),
        E("dsh-tri-model", "dsh-tri-model", "DSH 多模型分层协同插件：强模型规划、快模型执行、第三方模型审查，审查 FAIL 自动带问题清单返工；端点、协议、模型、层级全部在设置面板里配。", "ai", 2, "model"),
        E("dsh-workbuddy-connect", "dsh-workbuddy-connect", "已 404 的 corrinehu/dsh-workbuddy-connect 的原地接管版，沿用原来的包名、配置行 id 与 provider id，已装用户可直接升级。同时修复 400/11128 渠道校验（归一化 DSH 身份句并清除 system 消息中的产品名），并改为读取真实的 Wind", "session", 2, "model"),
        E("dsh-workbuddy2api-panel", "dsh-workbuddy2api-panel", "读取运行中的 workbuddy2api-panel 的 HTTP 接口，把面板模型连同倍率、国内/国际分区与逐模型思考档位同步进 DSH 的模型选择器，并在设置页与侧边栏徽标中显示剩余额度与用量。", "ai", 2, "model"),
        E("dsh-zcode-plan-bridge", "dsh-zcode-plan-bridge", "需已安装并登录 ZCode CLI。把 ZCode CLI agent 接入 DeepSeek Harness 作为模型提供方。常驻 app-server 会话逐回合流式转发，模型清单从 CLI 实时读取，因此上下文窗口、图片支持与 provider 路由都跟随已安装的 CLI 和账号。稳定版 0.", "image", 2, "model"),
        E("dsh-zed-provider", "dsh-zed-provider", "在 DSH 中使用 Zed AI 托管模型。", "ai", 2, "model"),
        E("keyringseam", "keyringseam", "macOS Keychain 凭据提供器：替换本地文件提供器，并使用已签名、公证的通用二进制辅助程序。", "fileops", 2, "model"),
        E("llm-adaptive", "llm-adaptive", "自适应模型路由：请求级复杂度分类，按配置链自动选择后端 provider。", "ai", 2, "model"),
        E("model-failover-manager", "model-failover-manager", "模型选择弹窗＋路由分组：模型失败后自动换到组内下一个可用模型并继续本轮；另含数据看板与免费渠道页签。页签一键安装六个渠道插件 —— Our Free Model（唯一不登录、不填 API Key 也能用的）、CodeArts、WorkBuddy、Trae、Qoder、Providers Hub，覆盖", "ai", 2, "model"),
        E("trae2api-dsh", "Trae2api-dsh", "将 TRAE 账号的模型额度接入 dsh，支持多账号管理、自动签到、账号轮询、用量统计、思考强度选择和模型显示管理。 需要 Python 3.10+，首次使用需联网安装 Python 依赖。", "text", 2, "model"),
        E("agent-feedback-loop-dsh", "agent-feedback-loop-dsh", "把 dsh 的每一轮 prompt 送入本地 agent-feedback-loop 反馈记忆管线——捕获用户不满、离线评审沉淀为反思，并把编译好的复发规则上下文附着回当前轮次，从不阻塞 prompt。需要先安装 agent-feedback-loop 运行时；安装后执行 agent-feedbac", "session", 2, "memory"),
        E("companion-memory", "companion-memory", "《AI记忆》角色扮演伴侣记忆：每个对话独立的人格文档（每条设定可配 1~100 权重，默认允许 AI 小步润色角色性格与例句）、多人对话按说话人分开记录的好感度与羁绊、带 AI 打分的活跃记忆、每轮实时更新的九种情绪表、AI 自我演化的性格/喜好/习惯、最近 48 小时对话检索、伴侣式上下文压缩、按", "archive", 2, "memory"),
        E("context-razor", "context-razor", "上下文剃刀：把当前会话上下文逐条列出（角色/预览/≈token 估算），超阈值标红，勾选后不经 LLM 精确裁剪，删了什么一目了然。", "session", 2, "memory"),
        E("deepseek-harness-forge-plugins", "forge-memory", "基于 BM25 关键词检索的记忆召回。", "session", 2, "memory"),
        E("dsh-cipher", "dsh-cipher", "把 cipher 记忆平台原生带进 DSH：四类记忆每轮沉淀、跨会话确定性检索经 systemPrompt.context 注入、洞察复核只进沉淀、会话级 UNNI/LOOP 模式（记忆驱动自动续轮）、记忆检索/写入两个工具，以及设置页（SOUL 编辑器）与 AgentPool 面板。", "session", 2, "memory"),
        E("dsh-cognition-engine", "dsh-cognition-engine", "让 AI 记住你跨会话说过的事，并且分得清哪些已经过期。", "session", 2, "memory"),
        E("dsh-compound-memory", "dsh-compound-memory", "通过 uvx 启动本地 compound-memory MCP server，并在每个会话注入一次简短的使用提醒。", "session", 2, "memory"),
        E("dsh-error-atlas", "dsh-error-atlas", "把 DSH 的运行错误与编程任务复盘渲染成可交互的 GPU 图谱，并把记录下来的教训送回模型上下文。", "session", 2, "memory"),
        E("dsh-file-memory", "dsh-memory", "DeepSeek Harness 分层文件记忆，提供工作区隔离的 USER/MEMORY 笔记、后台沉淀与混合会话召回。", "fileops", 2, "memory"),
        E("dsh-handoff-compaction", "dsh-handoff-compaction", "面向小上下文模型的 DSH 上下文压缩插件：压缩大小可视化配置，默认 8k 交接摘要 + 16k 最近上下文，完整历史仍可查询。", "archive", 2, "memory"),
        E("dsh-hierarchical-fishmemory", "dsh-hierarchical-fishmemory", "面向 DeepSeek Harness 的分层长期记忆，合并自 AirPineApplea/feiyu-memory 4.0.2、dsh-soul-md 与 dsh-shallow-memory（请勿与这几个插件同时安装）：从结束的对话自动蒸馏的共度时光日记、手写的情感日记、带版本历史的人设卡、每轮", "session", 2, "memory"),
        E("dsh-hindsight-gui", "dsh-hindsight-gui", "在 DSH 侧边栏提供 Hindsight 配置与状态面板，管理连接、模型、向量和记忆库设置，支持健康检查及经归属核验的本机服务控制；记忆工具由独立的官方集成提供。Hindsight 服务需另行安装，本插件不负责部署。", "session", 2, "memory"),
        E("dsh-inbox", "dsh-inbox", "dsh 的个人收件箱：输入框的 /inbox 或侧栏面板把链接、图片、文本与账密收进本地仓库，先按本地规则、再由有每日上限的模型分类，可在面板里筛选、搜索与编辑；对话里让助手按需检索取回，账密正文加密落盘，可选 WebDAV 或 S3 远端同步记录与附件字节。目前只在 Windows 实测。", "git", 2, "memory"),
        E("dsh-journal-calendar", "dsh-journal-calendar", "助手替你维护的每日日志：journal_record 工具把带时间的待办与记事（可选详情与标签）追加到 DSH home 下一天一个的 JSON 文件；右侧栏把这些文件画成月历，单元格按「有待办未完成 / 待办已完成 / 只有记事」标记，下方是可勾选的待办与所选日期的条目；它加入系统提示词的那句职责", "data", 2, "memory"),
        E("dsh-kb-sieve", "dsh-kb-sieve", "从 md/txt/docx/pdf 构建可审计知识库包（SQLite FTS5），确定性检索与原文阅读。", "pdfdoc", 2, "memory"),
        E("dsh-knj-obsidian", "dsh-knj-obsidian", "DSH 内置版 Obsidian 知识库：agent 把对话、文档与网页蒸馏为结构化 .wiki 知识图，支持检索、图谱导出、笔记编辑、增量构建与多库管理。", "session", 2, "memory"),
        E("dsh-lan-memory", "dsh-lan-memory", "澜·轻量本地记忆与人格系统：四层文件记忆（pinned / memory / facts / experience）、可编辑 SOUL/MOOD 人格、零 LLM 捕获、BM25 检索与状态池卡片；无独立管理面板，不依赖 Python 服务、向量库或 API Key。", "fileops", 2, "memory"),
        E("dsh-ledger-memory", "dsh-ledger-memory", "项目级记忆，核心是台账：台账的结构由 AI 按项目类型自行决定，插件只负责检测、注入、回写、归档与 Git 配合。记忆按语义分开放 —— 活跃台账是当前状态、回合流水只追加、关键决策/目标树/经验教训各是一卡一文件（另有卡片目录的多维索引表），根本原则只有用户本人能改。压缩方式只有一种（分流后压缩）", "git", 2, "memory"),
        E("dsh-linghun-memory", "dsh-linghun-memory", "DeepSeek Harness 的记忆子系统：记忆完全本体化（event/fact/rule 三本体）+ 目标系统（goal.js）——belief 价值观写侧收录 + Bridge 触发词，读侧重匹配公式（0.25 域命中 + 0.35 触发词 + 0.40 相似度）补上 goal/value", "pdfdoc", 2, "memory"),
        E("dsh-lite-memory-1", "dsh-lite-memory", "SQLite 条目化记忆、日历到点提醒，以及 cron 驱动的定时 agent 任务；13 个模型工具，中英双语界面。", "data", 2, "memory"),
        E("dsh-memj", "dsh-memj", "以项目为主线的 DSH 记忆插件。开放知识书写，以及插件提示词编辑，让用户不改一行代码就能重新设计记忆库结构与模型被驱动的方式。默认的记忆库核心设计在于，项目以一份你自己设计的项目文档（默认是一份交接文档）作为实体，插件自动识别会话所属项目、把沉淀的知识与项目绑定，并把可复用的部分升级进主题与全局层", "session", 2, "memory"),
        E("dsh-memories", "dsh-memories", "双账本跨会话记忆：自动把对话中的长期事实提取进 MEMORY.md，并维护项目进度账本 PROGRESS.md，每个新会话自动召回两本账。", "session", 2, "memory"),
        E("dsh-memory-11", "dsh-memory", "dsh 网页端项目级+全局长期记忆：分拆 POST /items 路由避免路径冲突，多轮工具调用上下文压缩后存入记忆项，去重与会话级持久化。", "archive", 2, "memory"),
        E("dsh-memory-2", "dsh-memory", "DSH 的工作区长期记忆。会话开始只注入「一行一条」的记忆索引，正文由 memory 工具按需取——同样字数预算约装三倍条目；一轮结束时用当轮最后一条用户消息做纯本地检索，命中的记忆下一轮随简报召回，不花模型 token。可选自动提炼把一段对话归纳成结构化记忆，captureMode=draft 时", "text", 2, "memory"),
        E("dsh-memory-calendar", "dsh-memory-calendar", "本地优先的 DSH 长期记忆插件：文本包、按需检索、可回原始事件、多大脑与工作区边界。", "session", 2, "memory"),
        E("dsh-memory-delta", "dsh-memory-delta", "分层跨会话记忆，只推变化的部分：首轮注入全部有效条目，之后只推新增 / 已更新 / 已失效，没有任何变化时一个字都不注入；与条目 id 重复的 key 不再写进正文，基线体积因此小约 26%。事实与决策带语义键（一个 key 只有一个有效结论），模型只能写收件箱、由人确认后才成为常驻事实；条目可以带", "session", 2, "memory"),
        E("dsh-memory-gate", "dsh-memory-gate", "有界本地记忆 + CBDC 权威门控：SQLite + FTS5 claims，作用域召回并给出可解释的采用/核验/忽略决策与完整审计轨迹，/memory 命令，每次注入 ≤3 条/1200 字符，不增加额外模型调用。", "data", 2, "memory"),
        E("dsh-memory-lite", "dsh-memory-lite", "给 DeepSeek Harness 的按需记忆库：会话日志提炼成分层 markdown（总览、索引与分主题明细），mem_query 只回命中条目而非整份索引。不每轮注入、零依赖，每条记忆都保留指回原对话的溯源标记。", "pdfdoc", 2, "memory"),
        E("dsh-memory-protocol", "dsh-memory-protocol", "记忆强制协议插件：桥接 opencode-memory MCP 服务器，工具调用前强制 memory_weave、每轮自动存档、自动注入记忆上下文。", "codec", 2, "memory"),
        E("dsh-memory-spaces", "dsh-memory-spaces", "用户治理的跨会话记忆空间，提供独立的来源与使用关系、来源追踪、版本管理和发送前注入检查。", "session", 2, "memory"),
        E("dsh-memory-tiers", "core", "dsh 的六层本地记忆插件：捕获对话轮次，经 L2 巩固、由分流模型沉淀为 DL3 摘要，每轮注入稳定记忆块并以占位符替代聊天历史。附五个记忆工具与配置页。", "session", 2, "memory"),
        E("dsh-native-memory", "dsh-native-memory", "基于 DSH 原生接缝的按工作区记忆：事实与有界常驻档案落在 storage-domain 的 JSON 单元上，写入经人工审批并带 `(sessionId, seq)` 引证，确定性召回 + session-query 全文检索历史会话——无外部服务器、无自建 SQLite。", "data", 2, "memory"),
        E("dsh-observational-memory", "dsh-observational-memory", "在后台将会话工作提炼为观察和反思，以便在上下文压缩后保留会话上下文。", "archive", 2, "memory"),
        E("dsh-openclaw-memory", "dsh-openclaw-memory", "把现有 OpenClaw Markdown workspace 作为有界的人格与记忆上下文共享给 DeepSeek Harness，并提供 Sidebar 浏览与编辑。", "pdfdoc", 2, "memory"),
        E("dsh-persona-gateway", "dsh-persona-gateway", "把 DSH 变成本机的 OpenAI / Anthropic 兼容网关端点，给指向它的客户端统一套上同一套人格与长期记忆；需自备 DeepSeek API Key（DSH 的登录凭证在上游会被拒）。", "session", 2, "memory"),
        E("dsh-plugin-context-manager", "dsh-plugin-context-manager", "DeepSeek Harness 上下文管理：每轮对话自动总结为记录并按优先级排序注入，⭐ 置顶记录跨会话继承，自定义文本每轮注入；真实对话任意范围折叠成摘要真省 token，全状态持久化重启不丢。注意：非标准一键安装——需手动将三个包目录复制到 profiles/node_modules、粘贴 c", "fileops", 2, "memory"),
        E("dsh-plugin-sodamem", "dsh-plugin-sodamem", "基于 SodaMem 守护进程的双时间轴记忆：每轮组装提示词时注入检索结果，回合结束后自动写回，读路径不经工具调用也不额外调用模型；每条召回的事实都标注来源回合并带有效期，失效的事实不再被检索到。", "time", 2, "memory"),
        E("dsh-plugin-thread", "dsh-plugin-thread", "带血缘的决策与目标记忆：显式命令与模型工具确定性记录决策，状态卡跨压缩重锚定，无损事件流 + BM25 分词检索兜底，场景级保真回归集作发布门禁。", "archive", 2, "memory"),
        E("dsh-qrcode", "dsh-qrcode", "DeepSeek Harness 离线二维码（SVG/PNG/ASCII）与条码（Code128/EAN-13）生成器，无网络、无 shell。", "image", 2, "memory"),
        E("dsh-scribe", "dsh-scribe", "跨会话记忆与工作区知识库合一。记忆默认是 ~/.dsh/memory 下的纯 JSONL，会话开始把相关记忆放进系统提示，会话结束回写一条；每个工作区的 kb/ 目录加一份全局目录构成只读知识库，检索结果能引用到文件行号。十一个工具统一带 scribe_ 前缀（七个 scribe_memory_*、", "data", 2, "memory"),
        E("dsh-skillradar", "dsh-skillradar", "扫描当前会话可见的技能，按与最近对话的相关性排序推荐。", "text", 2, "memory"),
        E("dsh-trilogy", "dsh-trilogy", "DeepSeek Harness 的项目记忆插件。每个工作区三份 Markdown 文件（PROJECT.md / DECISIONS.md / SESSIONS.md）：会话首个步骤自动创建、内容变了才重新注入（被上下文压缩挤掉也会重注入），并按分类经 memory_checkpoint 工具写回", "pdfdoc", 2, "memory"),
        E("dsh-workspace-memory-1", "dsh-workspace-memory", "显式、按项目隔离的记忆交接：新开会话时，经你确认后只调用一次模型，把同一项目里之前的对话整理成有长度上限的摘要，注入到新会话的第一步；不会在后台偷偷调用模型。“记忆”面板可以查看摘要、编辑笔记。", "fileops", 2, "memory"),
        E("harness-desktop", "plugins/harness-memory", "跨会话记忆插件：用官方 ctx.storage 存储域持久化记忆，注册 system-prompt section（memory:recall）把记忆注入模型上下文，提供 memory_save / memory_forget 工具让 agent 自行存取记忆（maxMemories 可配置）。", "session", 2, "memory"),
        E("interest-memory", "interest-memory", "由本地 Go 服务支撑的跨会话长期记忆（约 50MB 内存，SQLite-vec + 经验证增强的论断）：每条用户消息零延迟注入召回、会话结束时摄入对话记录，提供 memory_search / memory_logs / memory_ingest 工具。安装：`dsh plugin --prof", "data", 2, "memory"),
        E("mylife", "mylife", "本地优先的个人状态档案与决策引擎：逐字保留你的原始输入并精确到行地溯源，给出结论前先生成\"证伪项\"反驳自己，为每个事实单独设置有效期，并指出这个决定正建立在哪些空白之上。", "misc", 2, "memory"),
        E("ofttold-memory", "ofttold-memory", "让 AI 自己写、自己维护的一份记忆——日记、索引、自我描述、此刻的情绪；插件每个会话把她写的那几段摆回她眼前。只读你点名的几段，不自动总结、不替她写正文，只补缺的起始文件、给没有日期的锚点补上起算日；除此之外不改动已有文件。怎么写做成 skill 随包发。", "time", 2, "memory"),
        E("xiaoman-memory", "xiaoman-memory", "纯文本记忆：一条事一节、六个字段，靠元素联想而不是向量检索，每轮最多交两条旧事；不调模型、不联网，写库留给人——库能直接打开、能 grep、能改、能整份拷走。", "data", 2, "memory"),
        E("ai-eight-honors-eight-shames", "ai-eight-honors-eight-shames", "注册 ai-eight-honors-eight-shames skill 的 DSH 插件：面向编码代理的八条可核对工作准则（先查证再调用、有歧义先确认、业务规则给出处、先复用再新造、先测试再声称完成、按既有约定写、区分事实与推断、改动可回滚），外加第 9 条——用户每次提出需求或问题，都在工作区", "codec", 2, "skill"),
        E("bigseedskill", "BigSeedSkill", "闪念记录与人生拼图技能：捕捉生活点滴，构建画像并生成小说、剧本或自传。", "misc", 2, "skill"),
        E("cot-lint", "cot-lint", "思维链泄漏检测：零依赖 CLI 扫描 AI 留在文档与注释里的会话残留（死设计引用、PR 视角、变更叙述、评审编排），内置 cot-trim 语义修复技能包。", "session", 2, "skill"),
        E("dao-zang-skill", "dao-zang-skill", "道藏知识库离线检索与原文提取：对 28.5 万段经文进行关键词或语义检索，精确提取原文（带行号与命中标记），可从 Godners/DaoZang 数据集一键搭建工作区。", "misc", 2, "skill"),
        E("ds-pstack", "ds-pstack", "面向 DeepSeek Harness 的 pstack：58 个 agent 工作流技能，外加确定性路由器，按任务意图从你勾选的子 agent 模型池里选型。", "ai", 2, "skill"),
        E("dsh-any-skills", "dsh-any-skills", "从 Codex / Claude Code / OpenCode / GitHub / npm 导入并安装技能到 ~/.dsh/skills，模型自动读取、/技能名 立即可用；对话框旁 ⚡ 一键插入调用，设置页支持按来源/单技能导入、路径与数量展示、卸载与一键恢复。", "codec", 2, "skill"),
        E("dsh-at-skill", "dsh-at-skill", "通过 @名称 标记调用用户可用的 Skill，并在对话输入框中显示匹配的 Skill 候选项。", "session", 2, "skill"),
        E("dsh-creative-studio", "dsh-creative-studio", "面向 DeepSeek Harness 的美工与视频剪辑工具包——可分档抠图、局部重绘改图、标题与 logo 合成、平台规格批量导出与图片体检；视频侧含 AI 抠像换背景（RVM ONNX，另有绿幕色键路径）、淡入/滑入/打字机/卡拉OK 动效文字、53 种转场与风格化变体、光效与调色预设（支持 L", "image", 2, "skill"),
        E("dsh-ctf-solve-teach", "ctf-solve-teach", "教学式 CTF 解题技能：每步讲清套路、工具选型与底层原理，收尾在 solves/<题目名>/ 生成可复现 Writeup，并用九章质量门校验。", "misc", 2, "skill"),
        E("dsh-gsap", "dsh-gsap", "把 GSAP 官方的 8 个 AI 技能注册进 DeepSeek Harness；技能正文随包分发，装完重启即可使用，无需配置、账号或密钥。", "misc", 2, "skill"),
        E("dsh-i-have-adhd", "dsh-i-have-adhd", "常驻的 ADHD 友好输出塑形：一个系统提示词区段让回复行动先行、步骤编号、时间估算具体；adhd_on / adhd_off / adhd_status 三个工具让模式跨重启保持。", "time", 2, "skill"),
        E("dsh-life-decision-guide", "dsh-life-decision-guide", "按《高性价比人生指南》765 条正文回答人生决策：先查条目，按成本与收益排序，每条注明第几节第几条。", "text", 2, "skill"),
        E("dsh-ls125-uv-probe", "dsh-ls125-uv-probe", "为林上 LS125 紫外辐照计与 UVALED-X3 探头提供技能：逆向出的 9600 8N1 链路（28 字节帧、CRC-16/MODBUS、轮询与清零命令）、抓取解码工具链，以及已验证的 STM32F103 主机固件，可在脱离原装表的情况下读取探头。全部代码与文档均由 AI agent（Deep", "codec", 2, "skill"),
        E("dsh-mastery-loop", "dsh-mastery-loop", "从课程材料建一份 Markdown 知识库，然后出题刷到每个知识点都达到目标正确率；每题都必须写出思维链。", "pdfdoc", 2, "skill"),
        E("dsh-plugin-coaligne", "dsh-plugin-coaligne", "安装 CoAligne 团队协作的 coaligne-workflow skill；MCP 连接由登录后的 CoAligne Desktop 提供，不安装 Desktop 则无法使用。", "misc", 2, "skill"),
        E("dsh-plugin-skill-autoroute", "dsh-plugin-skill-autoroute", "对每条用户指令自动做一次确定性的技能路由，让技能目录在模型作答之前就被查阅，而不是等它自己想起来。宿主侧只依据指令关键词与目录元数据打分，不调用 LLM 也不做向量检索，然后向该步追加恰好一条带生产者标签的消息：默认是候选排名简报，分数过线时改注入冠军技能的 SKILL.md 正文，也可以只注入一句", "fileops", 2, "skill"),
        E("dsh-plugin-upgrade", "dsh-plugin-upgrade", "面向 DeepSeek Harness 插件作者的升级技能：一个包只放一份走廊索引，自动识别调用方的 peer 区间并路由到对应已封版的升级卡片（0.1.3-alpha.1 至 0.1.5-rc.1 为 A+B 两条腿，0.1.5-rc.2 至 0.1.6-alpha.2 为 C 腿），并附带以 b", "misc", 2, "skill"),
        E("dsh-plugin-zerone", "dsh-plugin-zerone", "会进化的项目级 Agent：以 SDD 规格驱动掌舵全流程，内置 16 个技能覆盖澄清、PRD、issue、编码、定位、验收、审查；会记忆、会沉淀，越用越懂你的项目。", "codec", 2, "skill"),
        E("dsh-plugins-learn", "dsh-learn", "dsh 自我学习闭环：记录经验、生成并发布技能，定期审查修正、合并与退役技能。", "misc", 2, "skill"),
        E("dsh-project-based-learning", "dsh-project-based-learning", "项目制教学教练：学科无关的教学引擎 + 可替换领域包（随包提供 Unity/C#），同时以 DSH 技能与可安装组合包分发。技能协议强制\"先做后教\"与分级提示；零依赖校验器会拒绝证据不支撑的能力结论，并在存在未解决阻塞项时阻止阶段通过。", "text", 2, "skill"),
        E("dsh-scholar-suite", "dsh-scholar-suite", "八个学术技能一次装齐——学术图表（按真实数据设计+视觉审核）、去 AI 味改写、论文润色与改写、PubMed 引文核验（DOI/PMID 逐条对账）、中文著作引用核验、公众号医学文章结构化。三项纯本地运行，五项按功能访问外部服务（NCBI、DOI 解析、发布平台）并逐技能如实声明；零遥测、无安装期脚", "misc", 2, "skill"),
        E("dsh-skill-center-1", "dsh-skill-center", "当前会话的技能中心面板：列出可见技能及其提供方与来源根目录，阅读 SKILL.md，开关模型/用户调用，并可创建、软删除技能；随包附带 skill-authoring 技能与 skill_create 工具。", "fileops", 2, "skill"),
        E("dsh-skill-manage", "dsh-skill-manage", "代理自管的程序性记忆：skill_manage 工具可创建、修补、禁用、删除 agent 自己的技能（用户级/项目级双作用域），带删除守卫（agent 创建标记、pin、路径限制）与触发纪律提示。", "net", 2, "skill"),
        E("dsh-skill-router-2", "dsh-skill-router", "DeepSeek Harness 的按需技能工具：注册 skill_search / skill_load / skill_ref 三个工具，让模型先从分层的技能库里检索、再按需加载正文，库里的技能因而不必进入常驻目录、不占每轮上下文；并在对话视图栏加一个「技能」标签页，回读整个会话、列出本次真正加", "fileops", 2, "skill"),
        E("dsh-skill-scope", "dsh-skill-scope", "给你的 Agent 减负：Skill 与 MCP 一键启停，让上下文只装这一轮真正要用的能力。关掉的 skill / MCP 不再进入模型上下文，更干净，更省 token。", "session", 2, "skill"),
        E("dsh-skill-starter", "dsh-skill-starter", "DSH 技能管理器，带技能包机制。技能以带版本的包安装，升级时绝不覆盖你改过的文件，只跳过并如实报告。另自带 6 个基础技能、按「你遇到的问题」分组的面板，以及让模型在对话里直接读写技能库的工具。", "fileops", 2, "skill"),
        E("dsh-skill-trace", "dsh-skill-intelligence", "面向 DeepSeek Harness 的只读 Skill 检视器。它显示一次对话实际加载过哪些 Skill（只凭观测到的加载证据）、当前环境又能发现哪些 Skill，并为每个 Skill 提供一页详情：左列在框架、证据、验收、评测、步骤证据、本次运行逻辑、有修改事务时的本次修改前后对比、定义事实与", "session", 2, "skill"),
        E("dsh-skills-console", "dsh-skills-console", "汇总共享技能目录里的技能并标注来源与版本，可从 GitHub 仓库安装与更新，删除时先进保留 7 天的回收站，并控制每个技能对各 Agent 的可见性与模型可调用性。", "git", 2, "skill"),
        E("dsh-video-skills", "dsh-video-skills", "在 DSH 设置里浏览 awesome-claude-video-skills 目录（373 条），把选中的技能装进 ~/.claude/skills 和/或 ~/.dsh/skills：下载该仓库的 GitHub 归档并复制技能目录，不执行仓库里的任何代码。安装以后台任务运行、显示实时进度（已下载", "git", 2, "skill"),
        E("dsh-we-wallpaper-sync", "dsh-we-wallpaper-sync", "可复用技能：批量浏览、搜索、下载 Wallpaper Engine（小红车，Steam 431960）创意工坊壁纸并接入 DSH 皮肤中心；含绕过 Steam HTTP 封锁与异地登录拦截（经出口 IP 与账号一致的 SOCKS 代理）。", "net", 2, "skill"),
        E("dsh-webnovel-writer", "dsh-webnovel-writer", "为现有 Agent 添加基于文件记忆的中文网文策划、逐章写作、一致性审校、回滚与文风画像技能。", "fileops", 2, "skill"),
        E("human-writing-skills", "human-writing-skills", "多语言润色、长文分块协作与上下文一致性审查，按需检查 DSH 智能体委派能力。需要 PATH 上有 Python 3.9+。", "session", 2, "skill"),
        E("listform", "ListForm", "智能表单技能：支出账单、台账与日志的结构化记录，自动归类并生成周期报表。", "devops", 2, "skill"),
        E("spec-driven", "spec-driven", "规格驱动开发纪律技能包（keel）：五个技能（锚定/立规/探针/建造/审计）、三个审查工具与六个规格模板，强制先规格后代码、假设先行验证并约束范围蔓延。", "misc", 2, "skill"),
        E("word-docx-writer", "word-docx-writer", "用简单标记稿生成并排版中文 Word（.docx）文档，使用内置标题样式、宋体与 Times New Roman 字体，图表题注按章自动编号。", "pdfdoc", 2, "skill"),
        E("dseyesopen", "dseyesopen", "视觉桥：纯文本 DeepSeek 也能收图（单独发、图文混发均可），快速小识图模型后台描述，对话框里图还在、模型只见文字；纯插件，卸载即复原。", "session", 2, "vision"),
        E("dsh-capture", "dsh-capture", "DSH 双引擎截图：思灵桌面壳内，全局快捷键/托盘打开全屏框选浮层（多显示器、逐屏像素级抓帧），选区定格后工具条就地画红框，一次确认送进输入框；纯 DSH（浏览器）下由输入框相机按钮经 getDisplayMedia 捕获屏幕，复用同一套单阶段框选+标注遮罩。均走官方附件通道。", "image", 2, "vision"),
        E("dsh-computer-use-vision", "computer-use-vision", "Windows 桌面识图+模拟操作能力：截图→vision模型→模拟鼠标键盘，内置自进化应用技巧库。支持插件工具模式和纯skill模式双形态。", "image", 2, "vision"),
        E("dsh-deepseek-vision", "dsh-deepseek-vision", "复用 DeepSeek 网页端识图模式给纯文本模型补上看图能力：deepseek_vision 工具调用本地 deepseek-vision-cli 浏览器自动化（手动登录助手、自动开启深度思考、用后自动关窗），把图片描述以文字返回给模型。", "image", 2, "vision"),
        E("dsh-dseyes", "DSH-dseyes", "为纯文本 DeepSeek 提供原生图片上传体验：在 Web GUI 粘贴/拖入图片即以缩略图附件进入会话，发送前由 host 用免费智谱 GLM-4V-Flash 视觉 API（glm-4v-flash 降级链）读取并替换为文字描述，DeepSeek 据此回答，原图保留在聊天历史中。", "image", 2, "vision"),
        E("dsh-gpt-image-1", "dsh-gpt-image", "控制已登录的网页版 ChatGPT 生成图片并下载到本地。", "image", 2, "vision"),
        E("dsh-image-gen-1", "dsh-image-gen", "图像生成：侧边栏画廊页面和三个 Agent 工具（paint_image、paint_images、edit_painting）；预置 ModelScope、Google Gemini、OpenAI、硅基流动、火山方舟 Seedream、阿里云百炼、xAI、智谱等服务商，也可接入任意 OpenAI", "image", 2, "vision"),
        E("dsh-image-lite", "dsh-image-lite", "DSH 生图插件，双模式：对话中由模型调用 image_generate_lite 工具出图，或在右侧栏「生图工作台」手动生图；最多 5 张参考图、支持 OpenAI images 接口格式，密钥存于 DSH 凭据服务。", "session", 2, "vision"),
        E("dsh-image-vision-1", "dsh-image-vision", "纯文本 DeepSeek 的聊天识图插件：view_image 工具转发任意 OpenAI 兼容 VLM（本地 Ollama 或云端），对话框粘贴/拖拽的图片自动改写为 view_image 路径标记供模型查看。", "image", 2, "vision"),
        E("dsh-imagegen-1", "dsh-imagegen", "DSH文生图/图生图插件：兼容OpenAI风格生图接口，默认适配多米API；标准OpenAI需调整协议、图生图模式和尺寸；文生图和URL参考图无需COS，本地参考图可压缩后存COS；支持自定义提示词后缀。", "archive", 2, "vision"),
        E("dsh-labnana", "dsh-labnana", "为 DeepSeek Harness 接入 Labnana 图片生成：文生图 / 图生图 / 精准编辑，含积分预估、余额查询与网页设置界面。", "image", 2, "vision"),
        E("dsh-open-eyes", "dsh-open-eyes", "为纯文本 DeepSeek 路由提供视觉桥接：通过可配置的 OpenAI Responses、Chat Completions 或 Anthropic Messages 端点分析附件与本地图片，同时保持支持图片的路由走原生路径。", "image", 2, "vision"),
        E("dsh-vidlens", "dsh-vidlens", "按人看片的顺序取样，而不是下载整片：先元数据与章节，再按时间码抽帧看画面、字幕优先转录（平台没有字幕才走本地 ASR）、AudioSet 527 类声音事件标签与高赞评论——21 个工具共用一个磁盘缓存，并带跨进程锁。需要 Python 3.10+、ffmpeg 与 vidlens 包（pip in", "media", 2, "vision"),
        E("dsh-visibridge", "dsh-visibridge", "结构化视觉证据（OCR/版面/语义）+ USB 摄像头拍摄工具，支持\"拍-看-改\"调试闭环；后端支持 Ollama、DeepSeek、小米。", "image", 2, "vision"),
        E("dsh-vision-1", "dsh-vision", "极简的原生视觉能力增强，支持免费的智谱模型或本地千问视觉模型。", "ai", 2, "vision"),
        E("dsh-vision-bridge-3", "dsh-vision-bridge", "输入框贴图自动识别：由 OpenAI 兼容视觉模型转成文字描述后，再交给纯文本 DeepSeek 模型处理。", "ai", 2, "vision"),
        E("dsh-vision-free-eyes", "vision-tool", "给 DeepSeek Harness 的纯文本模型补上免费识图：`vision` 工具直连智谱 GLM 视觉 API 描述/OCR 图片文件（glm-4v-flash 降级链），无需任何外部 CLI。", "image", 2, "vision"),
        E("dsh-vision-plugin", "dsh-vision-plugin", "为纯文本 DSH 模型增加可配置识图能力：在 DSH 0.1.7-rc.2 中，上传图片会完整通过适配链路，由 OpenAI 兼容视觉模型转写为文字后交给主模型；支持 OpenAI / Anthropic / Gemini / Azure 风格密钥鉴权，缺少 API Key 时会在发起请求前明确提示", "image", 2, "vision"),
        E("dsh-vision-proxy-route", "vision-route", "注册 `deepseek-vision` 路由：Web GUI 直接粘贴图片，由免费智谱 GLM 视觉模型转译为文字后，再交给 DeepSeek 适配器作答。", "image", 2, "vision"),
        E("dsh-vision-recognizer", "dsh-vision-recognizer", "视觉模型路由：把附加图片经可配置模型（15+ OpenAI 兼容与 Anthropic 供应商）转译为文字，对话仍由 DeepSeek 作答。", "image", 2, "vision"),
        E("dsh-youreyes", "dsh-youreyes", "纯文本 DeepSeek 的识图工具包：模型可主动调用的 `vision` 工具、deepseek/opencode-go 包装适配器（v4 flash/pro）、反重力额度（默认，flash/pro）/ 任意 OpenAI 兼容 VLM / Gemini / 本地 Ollama 通道、证据记忆与会", "codec", 2, "vision"),
        E("imgpost", "imgpost", "让 DSH 助手把本地、网页和 AI 生成的图片直接发到聊天里给用户看，并为文本模型提供识图能力；Windows 下经 PowerShell 运行。", "image", 2, "vision"),
        E("phone-lens", "phone-lens", "手机变 dsh 会话的全功能摄像头（需配合开源的 Android 手机 App——安装插件后扫插件提供的二维码即可下载 APK）：1. 局域网或 USB 直连实时取景，画面可直接注入对话框或保存到指定位置；2. 提供可调用工具，dsh 模型可在流式对话中按需主动拍照/变焦/切换镜头，便于全自动开发中", "codec", 2, "vision"),
        E("taxue-dsh-artisan", "taxue-dsh-artisan", "DSH 一体化视觉创作工具链：提示词反推与审计优化，多供应商生图，支持异步后台出图。", "ai", 2, "vision"),
        E("visionforge", "visionforge", "为 DeepSeek Harness 提供读图与生图/编辑能力（Qwen/OpenAI/Anthropic/Gemini 读图，Qwen-Image 生图与编辑）。基于 liustack/modlens（MIT）改造；请先卸载 @liustack/modlens——两者会注册同一批 vision p", "misc", 2, "vision"),
