        E("dsh-workspace-hub", "dsh-workspace-hub", "DSH 工作区中枢：侧边栏将工作区按彩色分组管理（分组/工作区/会话三级拖拽排序、内联编辑、一键展开折叠、标题+消息双通道搜索），基于真实会话日志统计每工作区与每会话的 Token 与花费（任意 deepseek 模型自动按官方峰谷价计费、三种时段口径、悬停明细卡、总览面板），另含 OpenCode", "codec", 2, "usage"),
        E("headroom-stats-plugin", "headroom-stats-plugin", "在 DSH 内实时展示 Headroom 压缩代理的 token 与费用节省：设置页仪表盘 + 输入区常驻统计行。", "archive", 2, "usage"),
        E("hwfee-dsh", "usage-stats", "空白会话首页的用量面板：会话数、消息数、总 token、活跃天数、高峰时段、常用模型与热力图，范围可选全部、30 天或 7 天。", "session", 2, "usage"),
        E("llmtrim-stats-plugin", "llmtrim-stats-plugin", "在 DSH 内实时展示 llmtrim 节省统计：设置页金额卡片（已支付、未压缩应付、今日与本周节省）与按模型明细，输入区可配置轮播或静态统计条。", "archive", 2, "usage"),
        E("luxueliu-usage-command", "luxueliu-usage-command", "本地 LLM 网关当日花费价目卡：/usage 读取 gateway_usage.jsonl，按模型×分小时列出消费，覆盖官方直连、OpenRouter 中转与套餐内计费池。", "data", 2, "usage"),
        E("minimax-usage", "trusted-plugin", "在 DSH 设置页「用量」section 展示 MiniMax Token Plan 的 5 小时 / 周窗口用量（带重置倒计时）、单模型明细与视频赠送额度；通过 trusted plugin 调 `/v1/token_plan/remains` 拿 key，未配置 key 时整段 section", "media", 2, "usage"),
        E("mmx-quota-tool", "mmx-quota-tool", "DSH 网页 MiniMax 配额悬浮卡：会话输入区显示水滴形 5h 已用百分比，点击展开详情面板，列出每个模型的 5h/周用量与重置倒计时，当前默认模型非 MiniMax 时自动隐藏。", "time", 2, "usage"),
        E("suanzhang-dsh", "suanzhang-dsh", "交易终端风格的 DeepSeek Harness 计费插件：侧边栏余额与今日消费、按步骤人民币费用表、官方价自动同步（含峰谷）、跨会话与按天汇总、工具级费用归属与成本预测。", "session", 2, "usage"),
        E("dsh-cindy-host", "dsh-cindy-host", "Host 侧插件：将 Cindy 手机客户端接入 DSH，提供会话、消息、审批、todo、goal 的手机通道，以及配套的设置卡片。", "session", 2, "remote"),
        E("dsh-feishu-bot-1", "dsh-feishu-bot", "通过 WebSocket 长连接把飞书机器人绑到 DeepSeek Harness：收到的消息跑在 agent 会话里并流式回传，/attach 等聊天命令管理活动会话，模型可调用 feishu_* 工具推送消息。", "session", 2, "remote"),
        E("dsh-gateway-agent", "dsh-gateway-agent", "客户机接入插件：以单条出站 WebSocket 连接网关，把本机 dsh web 界面经隧道转发给门户，配对接入码 + HMAC 认证；无需入站端口、端口映射或公网 IP。", "net", 2, "remote"),
        E("dsh-gb", "dsh-gb", "把手机变成 DSH 的外设遥控台：发送消息（打字或用手机输入法语音转文字）、应答 yes/no 审批与选择题、浏览消息与切换会话，Game Boy 风格屏幕；局域网扫码或内置 Cloudflare 隧道连接。", "media", 2, "remote"),
        E("dsh-local-link", "dsh-local-link", "以浏览器为核心、仅限局域网访问当前 DeepSeek Harness Web UI，支持一次性二维码配对、设备撤销、事件驱动诊断和保留插槽的移动端布局；无需配套应用、云中继或远程隧道。", "codec", 2, "remote"),
        E("dsh-mobile-css", "dsh-mobile-css", "DSH Web UI 移动端适配：紧凑排版、全宽输入卡（含光标修复）、抽屉式侧边栏（点击遮罩关闭）、两页式设置流程、响应式表格与统计、安全触控目标。", "data", 2, "remote"),
        E("dsh-mobile-harness", "dsh-mobile-harness", "DSH 的远程访问网关：用浏览器或可选的 Android App 扫一个码，接入电脑上正在运行的同一个会话。一次性二维码票据（10 分钟、扫一次失效）、6 位配对码两端核对、四条网络入口（SakuraFrp / Cloudflare 快速隧道 / 局域网 / Tailscale）、逐台设备准入（在线", "codec", 2, "remote"),
        E("dsh-network", "dsh-network", "为 DSH Host 提供经认证的局域网、Tailnet 与公网 HTTPS 接入，支持持久主机身份、配对和二维码配置。", "codec", 2, "remote"),
        E("dsh-on-phone", "dsh-on-phone", "让手机浏览器直接使用电脑上的 DSH 网页界面，远程通道建立在 Tailscale Serve 之上。两边除了 Tailscale 不用再装任何东西：没有专用 App、没有二维码、没有登录页，插件不设账号，也不中转你的内容。电脑端支持 macOS、Windows 与 Linux。", "codec", 2, "remote"),
        E("dsh-plugin-qr-connect", "dsh-plugin-qr-connect", "「设置」按钮上方的一键二维码，让手机通过带鉴权的反向代理连接 Web 界面。", "codec", 2, "remote"),
        E("dsh-remote-4", "dsh-remote", "随时随地用手机操作 DSH：自托管中继 + 桌面 host 插件组成令牌认证隧道（保序 HTTP 反向代理 + WebSocket 桥接），扫码配对、管理台可管理设备与令牌，并自动注入移动适配层（聊天全宽、设置弹窗全屏、侧栏抽屉化）。", "net", 2, "remote"),
        E("dsh-remote-control-1", "plugin", "用 HarmonyOS 手机遥控 DeepSeek Harness：浏览/切换/新建会话；发送提示词（手机跟随宿主的繁忙行为，排队或插话）；流式接收正文、思考与工具步骤；应答审批请求与提问；查看会话图片（缩略图内联 + 大图按需拉取）；切换模型与思考强度；取消运行中的任务；接收推送通知。流量端到端加", "image", 2, "remote"),
        E("dsh-remote-file-system", "dsh-remote-file-system", "模型可直接调用的 ssh 远程文件三件套：read_remote 按行号分页读远端 UTF-8 文本，write_remote 只新建文件、目标已存在即拒绝且没有覆写分支，edit_remote 做唯一匹配的字面替换，三者共用取自 ~/.ssh/config 的「别名:路径」一个 file_path", "git", 2, "remote"),
        E("dsh-remote-workspace-1", "dsh-remote-workspace", "支持冲突感知镜像同步、端口转发和原生 Web UI 的 SSH/SFTP 远程工作区。", "net", 2, "remote"),
        E("dsh-ssh-workspace", "dsh-ssh-workspace", "为 Windows DeepSeek Harness Desktop 0.2 提供 SSH 工作区：发现 OpenSSH 主机、添加或浏览远端项目目录，按工作区路由文件、搜索与 Bash 操作，DSH 运行时仍在本地。基于 Yan-Zero/dsh-remote-ssh 的 Desktop 兼容分支", "git", 2, "remote"),
        E("dsh-uniterminal", "dsh-uniterminal", "在 DSH 右侧栏里提供 SSH 终端、SFTP 文件管理与端口转发（-L/-R/-D），支持跳板链，记住的密码交给操作系统密码箱保管。", "net", 2, "remote"),
        E("dsh-weave", "dsh-weave", "基于 Iroh 的可信 DSH 主机网状网络：提供加密的节点发现、远程会话投递与连通状态。", "codec", 2, "remote"),
        E("dsh-winrm", "dsh-winrm", "通过 WinRM 管理 Windows 主机，提供 PowerShell 执行、服务与进程管理、SMB/分块文件传输（SHA-256 校验）、集群并发，以及 GUI 面板和七个 agent 工具。", "sysinfo", 2, "remote"),
        E("onebox-dsh-bridge", "onebox-dsh-bridge", "DeepSeek Harness 的 Android 客户端实现:扫码配对 + 端到端加密云端中继,把本机 dsh web 桥接到万宝盒 App。", "codec", 2, "remote"),
        E("w2m-dsh-plugin", "dsh-windows2macos", "一条指令同时下发给所有在线的 Windows 与 macOS 机器，可跨网络跨区域：零依赖中继只通过出站连接与各机通信（Tailscale 内网、公网 VPS + TLS、或隧道），各机在各自的项目副本上执行，结果连同 commit、工作区指纹与命令哈希一并回传，因此\"环境不一致\"会被判为 unve", "git", 2, "remote"),
        E("agent-web-sandbox", "agent-web-sandbox", "在内容进入模型之前净化抓取的网页：剥离隐藏文本、站外图片与内联数据，其余内容用带金丝雀的不可信分隔符包裹，并标记提示注入。", "image", 2, "security"),
        E("dsh-action-outbox", "dsh-action-outbox", "暂存精确的 DSH 工具调用而不执行，在持久化批量审查收件箱中展示完整规范参数；编辑或重启后审批失效，仅允许携带匹配 SHA-256 摘要与一次性 nonce 的批次通过 DSH 正常工具管线提交。", "git", 2, "security"),
        E("dsh-allow", "dsh-allow", "按路径与能力（read / write / create / delete / execute）授予 shell 调用的文件权限，而不是按命令名判断。命令行的文件效果由解析得出，缺哪个能力就出审批卡片而不是一律拒绝，同一套规则还会编译成进程、它的子进程、以及命令行根本没露出来的代码共同运行其下的 m", "sysinfo", 2, "security"),
        E("dsh-approval-explain", "dsh-approval-explain", "在审批卡片上加一个「解释」按钮：一次模型调用返回固定三行解读——做什么、读写改了什么、是否安全（风险等级加一句理由）。同时补上 `write`/`edit` 类调用详情区留白的问题——官方渲染器只读 `command` 字段，那两类调用没有该字段。", "data", 2, "security"),
        E("dsh-cloudflare-access", "dsh-cloudflare-access", "在 DSH Origin 校验 Cloudflare Access JWT，使 Settings、凭据、Agent Preset 管理与模型发现可在远程主机名下使用。", "codec", 2, "security"),
        E("dsh-code-security", "dsh-code-security", "确定性代码安全审查：40+ 规则、密钥熵检测、staged diff 审查、SARIF 导出、基线接受、SBOM-lite 依赖清单与健康自检。面板内置 4 步首次使用引导，看一次后不再出现。", "text", 2, "security"),
        E("dsh-cve-audit", "dsh-cve-audit", "面向你自己项目依赖（npm/pip/go）的实时 CVE/供应链审计，基于 OSV.dev，提供 `cve_audit` 工具，并支持在 lockfile 变化时自动重新扫描。", "fileops", 2, "security"),
        E("dsh-file-integrity-check", "dsh-file-integrity-check", "扫描并修复 Windows 上 DSH 工作区中的 Low 完整性标签、非继承 S-1-4-* 沙箱授权 ACE 及关联的 Everyone 拒绝项。按 DSH 实时工作区映射，默认只读，确认后修复并复扫校验；每个工作区保留一条可替换的 ACL 回滚记录。", "text", 2, "security"),
        E("dsh-file-shield", "dsh-file-shield", "屏蔽 agent 对指定文件或目录的读取、搜索、写入与编辑，使其内容不进入对话——含敏感词的文件也在其中，避免它们的文字让之后的 provider 请求以 400 失败。规则在插件页面上点选。", "fileops", 2, "security"),
        E("dsh-full-with-approval", "dsh-full-with-approval", "dsh 第四个权限预设：进程全权限（GPU 可用），同时工作区外与受保护文件（.git/**、.env*）的写入逐次向用户审批；纯插件实现，零核心改动。", "sysinfo", 2, "security"),
        E("dsh-guardrail", "dsh-guardrail", "对 agent 工具调用输入参数做字符串匹配，命中危险行为则拦截（deny）或放行但注入警告（warn），附规则管理面板。", "ai", 2, "security"),
        E("dsh-guardwall", "dsh-guardwall", "在安装前体检本地、npm 与 GitHub 插件源码，运行时拦截命中配置阈值的高风险工具调用，审计输出中的密钥模式，并写入 HMAC 链式本地审计日志。", "devops", 2, "security"),
        E("dsh-hawkeye-scan", "npm", "AI 驱动的源代码安全扫描工作台：5 个模型工具（start/finding/status/report/list）、/hawkeye Web UI 和 JSON/Markdown/HTML 漏洞报告；零依赖 Cordis 插件，可作 agent preset 或 npm 包安装。", "pdfdoc", 2, "security"),
        E("dsh-medical-anonymizer", "dsh-medical-anonymizer", "在 DeepSeek Harness 中批量匿名化病历文本、CSV、JSON 与 XLSX：先跑确定性标识符规则，可选 OpenAI 兼容模型做发现与复核；按精确区间替换以保持文件结构，同一值保持同一假名，并输出审计报告与映射库。DICOM 影像按 PS3.15 附录 E 只处理头部元数据，像素数据", "image", 2, "security"),
        E("dsh-plugin-guard-1", "dsh-plugin-guard", "DSH 插件的静态安全闸门与诊所：安装前静态审计、安装后哈希与能力锁定、本机指纹库与 GitHub dsh-plugin 主题的同类搜索、机械式剥离清理；永不执行目标插件。", "codec", 2, "security"),
        E("dsh-prompt-antivirus", "dsh-prompt-antivirus", "全局提示注入 / 上下文病毒防御：扫描工具参数、工具结果、进模型前消息与出站流；隔离/阻断/监控三模式、金丝雀陷阱、可演进磁盘签名库（学习/导入/导出）。", "sysinfo", 2, "security"),
        E("dsh-repeat-stop", "dsh-repeat-stop", "在可配置次数后硬拦截连续相同的工具调用，避免 Agent 原地空转。", "ai", 2, "security"),
        E("dsh-rule-guard", "dsh-rule-guard", "在写文件、跑非只读命令、联网、派子代理等有副作用的动作执行前，按项目规则与当前目标复核，超出范围即拒绝（失败即拒，无可配置豁免开关）。", "net", 2, "security"),
        E("dsh-security-guard", "dsh-security-guard", "dsh 安全守卫插件：基于规则的静态扫描覆盖恶意代码、提示词注入与令牌浪费，运行时拦截危险工具调用，提供 /scan 命令、plugin_scan 工具、Web 面板与白名单。", "ai", 2, "security"),
        E("dsh-sonarqube", "dsh-sonarqube", "面向 SonarQube Community Build 的只读工具：实例状态、分支或 PR 的项目质量阈、议题与安全热点搜索、单个热点详情，以及覆盖率、重复率或调用方指定的度量项。议题与热点结果附带标准化的位置信息，包含组件 key、文件路径、行号与文本范围。", "git", 2, "security"),
        E("dsh-telemetry-redactor", "dsh-telemetry-redactor", "在已配置遥测后端接收前，对 `session-telemetry/record` 导出副本中的已支持秘密模式进行脱敏。", "misc", 2, "security"),
        E("dsh-trust-check", "dsh-trust-check", "DSH 插件静态能力披露：设置页与 CLI 列出已装插件的权限能力、字面量去向、安装脚本与注入形态（prompt 注册、自带 skill 文本、bundle patch），每条附文件:行号证据。代码判定、可复现、零 token。只做披露，不做安全承诺，不判定恶意。", "fileops", 2, "security"),
        E("dsh-vaultwarden", "dsh-vaultwarden", "让任意会话直接读写自建的 Bitwarden/Vaultwarden 保险库：十一个 bitwarden_* 工具、WebSocket 实时同步（不可用时降级轮询）、readonly/ask/auto 三档写权限设置面板，以及可开启的本地脱敏——开启后密码默认以稳定占位符出现，需要时按条目+字段单次", "data", 2, "security"),
        E("dsh-web-auth", "dsh-web-auth", "DeepSeek Harness Web GUI 的传输层认证门禁，提供服务端会话、HttpOnly Cookie、基于 IP 的登录限流及 scrypt 口令 CLI。", "codec", 2, "security"),
        E("dsh-whale-post-verify", "verify", "校验其他 agent 写来的信：规范字段顺序、摘要与 HMAC 校验。默认关闭；开启后，缺字段或未登记字段不放行，任何一项不过就拒收。", "data", 2, "security"),
        E("euthyna", "euthyna", "面向 AI 编码代理的确定性安全审计事实与结论门禁：euthyna history 把每行被删代码归因到提交并标记安全修复类删除（--origins 追到最初引入者），euthyna coverage 报告哪些改动符号从未被测试调用，euthyna gate 用六道门禁逐条校验结论，拿不出证据的一律", "git", 2, "security"),
        E("sandbox-nono", "sandbox-nono", "nono 沙盒支持。", "misc", 2, "security"),
        E("dsh-browser-playwright-codex", "dsh-browser-playwright-codex", "浏览器自动化：让 AI 用你已经登录的账号，在真实网页上填表、抓取列表、多标签查后台。它跑在你桌面上的一个可见窗口里 —— 最小化它就不抢焦点、安静干活；遇到登录、验证码和原生弹窗会停下来等你，绝不替你点「确定」。登录一次一直记得（独立 profile + session cookie 回注）。23", "net", 2, "browser"),
        E("dsh-browser-use-2", "dsh-browser-use", "DeepSeek Harness 浏览器插件：把网页任务交给它——打开页面、点击、输入、填表、读取页面内容——它会驱动真实浏览器一步步完成，每步只看到“当前页面能做什么”的索引表，而不是原始 HTML 或截图。每步由内置 Jev 引擎决策一次，而非大模型整轮推理（仓库基准中每步决策中位 1.1 秒，", "git", 2, "browser"),
        E("dsh-cdp-browser", "dsh-cdp-browser", "通过 CDP 连接已运行的 Chrome/Edge：为 DSH 提供截图、像素断言、DOM/CSS 检查与页面 JS 执行，全程 HTTP + WebSocket、零子进程、零 npm 依赖、无需逐次授权。", "image", 2, "browser"),
        E("dsh-free-search", "dsh-free-search", "可切换引擎的联网搜索 provider，其中多个引擎无需 API key（Bing、DuckDuckGo、SearXNG 等），可设置回退顺序；另提供 multi_search、platform_search、带对话内图片墙的 image_search、page_images 和 save_imag", "image", 2, "browser"),
        E("dsh-image-search", "dsh-image-search", "多引擎反向识图聚合：Google Lens、百度、Yandex、TinEye、SauceNAO、IQDB、Ascii2d。", "misc", 2, "browser"),
        E("dsh-insight", "dsh-insight", "Chrome/Edge 浏览器伴侣扩展：在网页上选中文字后点浮标，dsh 的解读会以 Markdown 显示在侧栏或页面浮窗，并支持多轮追问；宿主侧工具让智能体读取当前页面、抓取 HTTP 流量、操作浏览器。stuarthu/dsh-chrome（MIT）的 fork：桥接、浏览器工具与页面注入来自", "pdfdoc", 2, "browser"),
        E("dsh-plugin-web-annotate", "dsh-plugin-web-annotate", "在内置浏览器里点选页面元素写批注，攒够后一次性发给会话，让模型直接定位并修改对应源码。", "session", 2, "browser"),
        E("dsh-s1", "dsh-s1", "Search1API（s1）原生联网检索工具：网页搜索、新闻、页面抓取、站点地图与趋势榜，以 `s1_*` 一等工具形式提供，并附带 s1 技能。", "net", 2, "browser"),
        E("dsh-sxs-anti-bot-http", "dsh-sxs-anti-bot-http", "反爬 HTTP 工具：UA 池轮换、指数退避重试、反爬墙检测（验证码/安全验证）与自适应限流，提炼自 SXS 生产采集体系（每日数百万请求）——工具：`sxs_fetch` / `sxs_fetch_json` / `sxs_rate_status`。", "data", 2, "browser"),
        E("dsh-tavily-search", "dsh-tavily-search", "为内置网页搜索提供 Tavily 后端：在 DSH 进程内提供 127.0.0.1:8787/v1 接口，把搜索请求转成 Tavily 检索；最多 10 个 API Key 存在 DSH 凭据库，按请求轮换，遇鉴权、限流或额度错误自动换下一个；设置卡片可管理密钥、测试搜索并一键接入网页搜索。", "sysinfo", 2, "browser"),
        E("dsh-verify", "dsh-verify", "Agent 交付物的独立浏览器验收测试：JSON 规格进，真实 Chromium 结论出。", "data", 2, "browser"),
        E("dsh-web-fetch-fakeip-1", "dsh-web-fetch-fakeip-plugin", "让内置 web_fetch 在 Clash / mihomo 以 TUN + fake-ip 模式运行时正常工作：只放行 fake-ip 地址段（198.18.0.0/15、fdfe:dcba:9876::/64、2001:2::/48）通过公网地址校验，回环、内网与链路本地地址仍照旧拦截。无需设置", "misc", 2, "browser"),
        E("dsh-web-search-1", "dsh-web-search", "为 DeepSeek Harness 提供可配置联网搜索，支持 SearXNG、Wikipedia、Tavily、Brave 与 Gemini，并支持客户端引擎选择和受控重试。", "search", 2, "browser"),
        E("dsh-web-search-bing", "dsh-web-search-bing", "为内置 web_search 工具提供 Bing 搜索源：优先解析 Bing 的 RSS 输出，以 cn.bing.com 公开 HTML 结果页作为兜底，无需 API Key，国内可直连，搜索不再消耗模型自带的搜索额度。端点、结果数量与结果语言可配置；适配 DSH 0.2.x（0.1.7+ 亦可用", "search", 2, "browser"),
        E("dsh-web-search-doubao", "dsh-web-search-doubao", "为 DeepSeek Harness 提供豆包搜索（火山引擎）网络搜索提供方——把 web_search 的后端切换为独立的豆包搜索 API，密钥与计费独立（每月 500 次免费），并内置专用设置卡片，经凭据服务保存密钥。", "search", 2, "browser"),
        E("dsh-web-search-ext", "dsh-web-search-ext", "面向内置 web_search 工具的多后端搜索提供方（Exa + Firecrawl）：自动故障切换、按后端 429 冷却、无密钥匿名可用。", "search", 2, "browser"),
        E("dsh-web-search-fetch", "dsh-web-search-fetch", "聚合型 web_search 与 web_fetch 提供方，接在 DSH 原生工具背后。搜索把一次查询并发分发给 AnySearch、智谱、知乎三路，URL 去重后用 RRF 融合排名，可选经硅基流动重排。抓取按 URL 感知分流：静态页走内置 HTTP 抓取，动态页并发 Firecrawl 与", "net", 2, "browser"),
        E("dsh-web-search-microsoft-webiq", "dsh-web-search-microsoft-webiq", "基于 Microsoft Web IQ 的网页搜索提供方，接入内置 web_search 工具，并提供 API Key、端点、语言、地区、摘要长度与 SafeSearch 的设置卡片。", "search", 2, "browser"),
        E("dsh-web-search-openrouter", "dsh-web-search-openrouter", "内置 web_search 每次搜索都要在 DeepSeek 自己的端点上消耗一整轮模型调用；本插件改为在 OpenRouter 兼容网关上执行搜索，与对话走同一个账户，模型和价格都由你决定。", "search", 2, "browser"),
        E("dsh-webstack", "dsh-webstack", "为 DeepSeek Harness (ctx.web) 提供 SearXNG 搜索与 Scrapling 多级抓取 Provider，支持 SSRF 防护与 Markdown 格式转换。", "pdfdoc", 2, "browser"),
        E("agents-gitflow-guard", "AgentsGitFlowController", "AI 编码智能体分支角色守卫：可配置集成/预览/生产/归档角色，拦截对受保护分支的直接推送、强推与删除，以及智能体对生产/归档分支的合并。", "git", 2, "git"),
        E("dsh-backstory", "dsh-backstory", "/backstory 命令与工具：为每一行标注最后改动它的 git 提交，以及写下它的 agent 轮次与提示词；数据取自按行持久化的账本（以内容哈希防漂移）、DSH-* 提交尾注或实时会话日志。", "git", 2, "git"),
        E("dsh-code-review-2", "dsh-code-review", "把对话里的 git diff 一键打开为独立标签页的双列代码评审页：行号、增删配色、字符级高亮、hunk 感知的多文件分段、文件导航侧栏与统计条，行内评论可提交回 DSH 对话框，界面跟随 DSH 语言（中英）。", "git", 2, "git"),
        E("dsh-command-code-review", "dsh-command-code-review", "注册 /code-review 斜杠命令，五个并行审查视角、逐发现置信度打分，同时支持拉取请求与本地代码审查。", "git", 2, "git"),
        E("dsh-dev-git-graph", "dsh-dev-git-graph", "DSH Web 的 vscode-git-graph 1.30.0 忠实移植：入驻 dsh-better-sidebar 右侧栏的原生 Git Graph 提交图 tab（前置依赖），自动绑定会话工作区，host 直跑全套 git 操作（checkout/merge/rebase/push/tag/", "git", 2, "git"),
        E("dsh-git-hygiene", "dsh-git-hygiene", "Git 卫生巡检：只读扫描已合并/过期分支、大文件、未跟踪文件与未提交修改，输出体检报告与清理建议，不自动删除任何东西。", "git", 2, "git"),
        E("dsh-git-push", "dsh-git-push", "DSH 的 git 提交推送自动化：提交前审计、规则质量评分、SSH 密钥生成与三选项卡设置侧边栏。", "git", 2, "git"),
        E("dsh-git-tools", "dsh-git-tools", "为 DeepSeek Harness 提供四个零依赖本地 git 工具（status、diff、log、commit），作用于会话工作区。", "git", 2, "git"),
        E("dsh-github-mcp-hint", "dsh-github-mcp-hint", "GitHub MCP 辅助面板：在「设置 → 插件 → GitHub MCP」展示可复制的示例提示（30 条示例池随机 4 条）、可视化公开仓库的星/fork/语言，并提供 gh_repo_stats / gh_current_user 模型工具。", "git", 2, "git"),
        E("dsh-github-push", "dsh-github-push", "一键上传项目到 GitHub：自动初始化 git、生成或完善 README、设置仓库 topics，并推送本地项目。", "git", 2, "git"),
        E("dsh-gitnexus-plus", "gitnexus-plus", "在 DSH 侧栏读取 GitNexus 索引，报告被跳过的文件、索引新鲜度与语言覆盖，支持符号搜索和最近的 Git 活动审查。", "git", 2, "git"),
        E("dsh-plugin-git-1", "dsh-plugin-git", "在 DSH 会话标题栏与浮层工作台中管理已有本地仓库，支持查看改动、提交、获取、拉取、推送以及浏览分支和历史。", "git", 2, "git"),
        E("dsh-plugin-git-workflow", "dsh-plugin-git-workflow", "一等公民的 Git 工具：status / diff / log / commit / branch，参数与路径校验、零 shell 调用，杜绝注入。", "git", 2, "git"),
        E("dsh-pr-board", "dsh-pr-board", "DSH 侧边栏的维护者 + 开发者 PR 看板：五状态评审队列（等我 / 等作者 / 可合并 / 已合并 / 待分诊）、三列 issue 看板、跨仓库跟踪自己 PR 的 mine 视图（我的回合 / 等别人 / 已合并），附 CI 汇总徽章与不活跃过滤，点卡片一键打开或新建对应的评审会话。", "git", 2, "git"),
        E("dsh-revdiff", "dsh-revdiff", "DeepSeek Harness 原生交互式 Git diff 审查，支持结构化批注并回传当前 Agent 会话。", "git", 2, "git"),
        E("dsh-sidebar-git-graph", "dsh-sidebar-git-graph", "DSH 右侧边栏页：把当前会话的仓库画成 VS Code 风格的分支/合并提交图谱（彩色泳道、ref 徽章、提交详情），上方带工作区 Changes 区（staged/unstaged 分节、行内 diff），覆盖仓库的每个工作树；只读，装不装 dsh-better-sidebar 都能用，装了 d", "git", 2, "git"),
        E("dsh-simple-worktree", "dsh-worktree", "极简 worktree 管理方案，只有一个按钮和一个弹窗。", "git", 2, "git"),
        E("dsh-task-worktree", "dsh-task-worktree", "任务级 git worktree：per-repo manifest 持久保存；Worktree 模式在首条消息注入创建指引并统一 worktree/ 分支前缀，头部徽标替代工作区注册，支持带回主目录或强制删除收尾。", "git", 2, "git"),
        E("dsh-update", "dsh-update", "一键更新本地 DeepSeek Harness：侧边栏按钮对比版本、拉取重建并自动重启，还可选择回退到任一历史版本，全程实时进度。", "misc", 2, "git"),
        E("gord-dsh-worktree", "gord-dsh-worktree", "为 DeepSeek Harness 管理 git worktree —— 让并行工作各自隔离在自己的目录与分支里。自带快速模式（Fast mode）。", "git", 2, "git"),
        E("worktree-mgr", "worktree-mgr", "按任务隔离的 git worktree 工作区，覆盖创建/同步/收尾全生命周期：任务名自动派生分支、合并目标双重校验、内置批量清理——全程零手工 git 操作。", "git", 2, "git"),
        E("agent-native-trade", "dsh-plugin", "为模型原生交易提供目录检索、交易方联络、合同签名、结算协调、人工任务交接和签名评价回执工具。", "fileops", 1, "tools"),
        E("anno", "dsh-native", "面向编码代理的本地优先 HTML 审阅与标注工作区：在浏览器编辑器中打开文件的隔离副本，收集文本修改、格式调整与元素/区域评注，并把持久的交接（handoff）交还给代理认领和落实。", "codec", 1, "tools"),
        E("beav-creator-dsh", "beav-deepseek-harness", "将 DSH 连接到本机 Beav，面向小红书（RED/RedNote）、社交媒体运营和自媒体 AI 创作，覆盖选题研究、知识库、文案、图片、音频与短视频工作流，并保留审批和产物追踪。", "image", 1, "tools"),
        E("cad-tool", "dsh-cad-studio", "为 DSH 添加参数化 CAD 建模、几何验证、预览、设计历史和 STEP/STL 导出能力。", "misc", 1, "tools"),
        E("cn-intel-mcp-dsh", "cn-intel-mcp-dsh", "中国硬科技供应链情报：33 条信号看板、中报验证追踪、命中率记录与问答，通过远程 MCP 接入（mcp__cn_intel__*）。", "misc", 1, "tools"),
        E("cn-linebreak", "cn-linebreak", "中文网页文案断行静态审查与修复工具：检查显式 <br> 孤字行、keep-all 覆盖、标点禁则、保护词被拆等问题，并在自然停顿处自动插入 <wbr>；提供 cn_linebreak_audit 工具供代理调用。", "net", 1, "tools"),
        E("computer-user-vision", "computer-user-vision", "computer-user 分叉的 Windows 电脑操作插件：13 个 computer_* 工具，读取屏幕并驱动鼠标键盘。模型支持图像输入时截图直接作为图片返回，附精确的图像→屏幕映射，无需外接 OCR；控件以 UI Automation 引用返回，点击落在精确矩形上；Ctrl+Alt+Esc", "image", 1, "tools"),
        E("deepseek-harness-community-plugins", "dsh-agent-mail", "DeepSeek Harness 中的 AI 协作邮箱，让 AI 工具互发消息、交接任务并查看收发回执。一个包包含 MCP 集成与邮箱界面；0.2.2 需要 DSH 0.2.0-rc.2，需要独立安装 Agent Mail 1.0.0-alpha.7；不提供自动唤醒模型或持续在线状态。", "session", 1, "tools"),
        E("deepseek-harness-community-plugins-1", "dsh-ai-asset-hub", "将 DeepSeek Harness 连接到部署方管理的 AI Asset Hub MCP 服务，并提供八个经过审查的只读资产工具。", "devops", 1, "tools"),
        E("deepseeklauncher", "DeepSeekLauncher", "macOS 桌面启动器与安装 skill：启动或复用本地 DeepSeek Harness Web 服务，固定使用 Google Chrome 打开，并提供透明人物与对话框图标。", "session", 1, "tools"),
        E("dm-recovery", "DM-recovery", "只读评估达梦 DM8 数据库的可恢复能力：16 类恢复场景下能恢复到哪一点（LSN/时间）、要丢什么，并生成 HTML 报告。需 Java 8+，并自备达梦 DmJdbcDriver8.jar。", "time", 1, "tools"),
        E("docindex", "docindex", "工作区文档的本地语义索引（MD/PDF/DOCX/TXT）：FTS5 BM25 与本地嵌入混合检索、带行号命中引用、增量更新。", "pdfdoc", 1, "tools"),
        E("dscomputer-control", "dscomputer-control", "为 dsh 提供 Windows 桌面自动化：14 个工具，可枚举应用与窗口、抓取被遮挡也能截的窗口截图、读取无障碍树，并执行真实输入——点击、输入文字（含中文）、按组合键、滚动与拖拽。加载机器上已安装的官方电脑控制运行时（@oai/sky），按厂商目录枚举发现，引擎升级换目录也不会失效。", "image", 1, "tools"),
        E("dsh-123pan", "dsh-123pan", "123 云盘客户端：支持手机号或邮箱密码登录，也支持粘贴 token；侧栏面板可浏览、拖拽上传与下载，并能对工作区做保留目录结构的增量备份；同时提供 15 个工具供 agent 列目录、上传、下载、重命名、移动和删除文件。网络请求、MD5、16MB 分片上传与 token 加密都由随包的静态链接 C", "codec", 1, "tools"),
        E("dsh-9router-web-search", "dsh-9router-web-search", "9router 网页搜索与网页抓取 provider，为 DeepSeek Harness 提供搜索和抓取能力。", "net", 1, "tools"),
        E("dsh-agent-dispatch", "dsh-agent-dispatch", "自定义 Agent + 自动路由 + 小队编排：六个模型工具（agent_dispatch / agent_followup / agent_list / agent_squad / agent_import_skill / agent_upsert），无内置 Agent，原生右 tab 主面板（总", "ai", 1, "tools"),
        E("dsh-agent-project-sync", "dsh-agent-project-sync", "发现 Codex 和 Claude 使用过的项目目录，并将其注册为共享的 DeepSeek Harness 工作区。", "fileops", 1, "tools"),
        E("dsh-agent-settings", "dsh-agent-settings", "智能体设置：在侧边栏管理可复用的子智能体档案，为每个档案写明适用场景与所用提供方/模型，任务中由智能体按场景自动拉起对应的子智能体。", "ai", 1, "tools"),
        E("dsh-agnes-tools", "dsh-agnes-tools", "把 Agnes AI 的生图 / 生视频接成 DSH 原生工具，长视频任务可稍后续查。需设置 Agnes API Key（AGNES_API_KEY）。", "media", 1, "tools"),
        E("dsh-android-pane", "dsh-android-pane", "在 DSH 对话旁打开 Android 设备实时画面：scrcpy H.264 串流，agent 可点按操作并用截图与控件树自证，截图 / 录屏 / 调试证据统一存进你指定的电脑目录；调试会话自带分段视频、全量 logcat 与逐动作前后帧。模拟器与 USB 真机通吃，人机共屏，仅限本机回环。", "image", 1, "tools"),
        E("dsh-android-phone", "dsh-android-phone", "在 DSH 侧栏实时显示 USB 连接的安卓手机，并通过 scrcpy 控制协议直接操作手机：12 个 agent 工具（点按/滑动/输入/按键）、多帧滚动拼接的长截图，以及「默认交给 agent、人一碰手机就立刻交出控制权」的控制权模型。自带 adb 与 scrcpy-server。仅 Windo", "image", 1, "tools"),
        E("dsh-api-client", "dsh-api-client", "DeepSeek Harness 的 Agent 原生 API Client：Postman 级调试 UI（右键菜单与完整键盘导航的请求树、可调宽侧栏、自动生成 Header 分层预览——逐项可停用、敏感值恒脱敏），六个 api_client_* Agent 工具与 Human UI 共用同一请求核", "ai", 1, "tools"),
        E("dsh-app-updater", "dsh-app-updater", "检测本机已安装应用里哪些有可用新版本，并一键从各软件官网下载完整安装包静默更新；Windows 走 winget、macOS 走 Homebrew cask，并按本机 ARM64 / x64 架构挑选对应安装包。", "net", 1, "tools"),
        E("dsh-ark9canvas", "dsh-ark9canvas", "DSH 生图工作台与 Agent 生图工具：一个工具（ark9_generate_image）走任意 OpenAI 兼容图片 API 文生图/图生图。渠道完全由用户自行添加——默认零预置，自带 baseURL、Key 与模型名即可（支持手动输入任意模型名）。Agent 发起的生图默认需用户审批：请求", "image", 1, "tools"),
        E("dsh-at-file-everything", "dsh-at-file-everything", "用 es.exe 从 Everything 索引回答 @file 补全，而不是遍历工作区，并以工作区根目录作为排序范围。仅限 Windows；需先安装 Everything 与 es.exe 并加入 PATH。", "fileops", 1, "tools"),
        E("dsh-atlassian-plugin", "atlassian", "把 Jira 与 Confluence 接进 DeepSeek Harness：提供 Atlassian 远程 MCP 服务器的工具、问题与页面的结果卡片，以及问题面板。", "devops", 1, "tools"),
        E("dsh-auto-open-web", "dsh-auto-open-web", "deepseek harness自动打开浏览器插件，内置WebView2程序实现轻量级桌面化。", "misc", 1, "tools"),
        E("dsh-autocad-bridge", "bundle-autocad-ui", "通过 COM 驱动本机安装的 AutoCAD，把它暴露成 18 个 mcp__autocad__ 工具：连接与状态、取消当前命令、列出本机注册的 ProgID、列出或新建文档、保存、新建与列出图层、绘制直线/圆/矩形/多段线/圆弧/文字、列出图元、缩放到范围，以及透传任意 AutoCAD 原生命令。", "misc", 1, "tools"),
        E("dsh-bash-windows", "dsh-bash-windows", "Windows 上的一键 Git Bash 开关，替换四种内置模式的 PowerShell，极简模式保留持久终端。", "git", 1, "tools"),
        E("dsh-bid-health-check", "dsh-bid-health-check", "按招标要求逐条检查投标文件的响应位置，报告哪些要求看起来有应答、哪些匹配较弱、哪些未能定位。只报告差异，不判断是否实质满足。", "fileops", 1, "tools"),
        E("dsh-bili-see", "dsh-bili-see", "本地模型刷 B 站：由 Ollama 小模型按题材配额挑片，读字幕、热评与关键帧，判断要不要评论，再经五档安全闸写出并发布。节奏由 dsh-schedule 触发；未开启写权限时不注册写工具。v1.1 收紧写路径：撤权改为运行时状态（每次发送前检查）、发布原子化、风控错误会持久化为暂停、发前复核人设", "media", 1, "tools"),
        E("dsh-bili-video-summary", "dsh-bili-video-summary", "仅 Windows。B 站视频一键总结：下载音轨并用 faster-whisper 本地转写（需 Python 与 faster-whisper，首次运行下载约 725 MB 模型），随后生成解析 md 与一页「一图读懂」PNG。", "image", 1, "tools"),
        E("dsh-bookkeeping", "bookkeeping", "dsh 的对话式记账插件:聊天即可记账(严格金额校验、自然语言日期、自动分类),并支持查询、报表、CSV/HTML 导出和月度预算,数据存于本地 SQLite 账本。", "data", 1, "tools"),
        E("dsh-brave-search", "dsh-brave-search", "把 Brave 注册为 web_search 的搜索提供方，API Key 依次从 DSH 凭证库、$DSH_HOME/.credentials.yaml 或环境变量读取。无设置卡片、无备用引擎：每次搜索向 Brave Web Search API 发起一次请求。", "data", 1, "tools"),
        E("dsh-browser-use", "dsh-browser-use", "Browser Use 云端桥接：通过 Browser Use API 让 dsh agent 执行真实网页任务，包括打开页面、点击、输入、填表和提取数据。", "ai", 1, "tools"),
        E("dsh-ca-ref", "dsh-ca-ref", "DSH 的 Clean Architecture 参考库:8 个钉版参考仓(Go / Java / C# / Python)索引进本地 FTS5,提供断言规则、审查台账与只读观察窗面板。", "misc", 1, "tools"),
        E("dsh-cad-plugin", "dsh-cad", "只读 CAD 工具：查看、提取 DWG/DXF 图纸，导出 SVG/PNG 预览或转换 DXF。", "image", 1, "tools"),
        E("dsh-cap-manager", "dsh-cap-manager", "一个面板统一管理全局 / Profile / 项目三个作用域的 MCP 服务与技能：实时状态与工具数、导入导出、回收站与备份，并可安装/更新/卸载 Anthropic 官方 claude-plugins-official 市场的 Claude Code 插件。", "fileops", 1, "tools"),
        E("dsh-capability-optimizer", "dsh-capability-optimizer", "以 advisor / reviewer / designer 角色无头调用 Claude Code，回复作为参考答案。", "misc", 1, "tools"),
        E("dsh-chat-digest", "dsh-chat-digest", "把微信与 QQ 聊天记录里「必须做的、可以报名的、值得知道的」摘成一张面板：由一个常驻会话按计划或在你点 Fetch 时重读聊天记录并改写条目，每条可直链到原始文件或图片。", "image", 1, "tools"),
        E("dsh-clock-context", "dsh-clock-context", "每一轮把当前日期时间注入运行上下文，让 agent 能读到准确时间而不是靠推算。", "time", 1, "tools"),
        E("dsh-clock-tools", "dsh-clock-tools", "给 DSH Agent 的任务计时工具：task_clock 用宿主单调时钟测实际耗时，DSH 或系统重启后可续算并标注空档为估算，桥接不了时返回 unknown 而不是编造数字；不覆盖任何 preset。", "time", 1, "tools"),
        E("dsh-codegraph-project", "dsh-codegraph-project", "将本机已安装的 CodeGraph CLI 接入各会话的已索引项目，同项目共享一个 MCP 进程，并在工作目录或索引变化时更新会话级工具。", "sysinfo", 1, "tools"),
        E("dsh-codex-computer-use", "dsh-codex-computer-use", "让 DSH 当前模型通过已安装的 Codex Computer Use 运行时读取和操作 Windows 应用，并保留每个会话的应用授权。", "session", 1, "tools"),
        E("dsh-codex-consult", "dsh-codex-consult", "需先安装 Codex CLI 并完成 `codex login`。为 DeepSeek Harness 增加三个按需咨询 OpenAI Codex CLI 的工具：codex_consult 在只读沙箱中运行 Codex、自动内联证据文件、从 Codex rollout 记录校验实际模型与推理档位、", "fileops", 1, "tools"),
        E("dsh-codex-subscription-en", "dsh-codex-subscription", "在 DeepSeek Harness 中直接使用 ChatGPT / Codex 订阅：OAuth 免密、额度续航预测、安全重置、联网搜索、生图与高速模式。", "search", 1, "tools"),
        E("dsh-context-toolkit", "dsh-context-toolkit", "让大块输出不进对话：ctk_execute、ctk_execute_file 与 ctk_batch_execute 在子进程里跑代码只回结论，ctk_index 与 ctk_search 把长材料存进基于 node:sqlite 的本地 FTS5 知识库，路由门禁在执行前拦下 curl 与 wge", "data", 1, "tools"),
        E("dsh-conversation-nav-dots", "dsh-conversation-nav-dots", "DSH 网页端对话导航点 — 快速跳转用户消息。", "session", 1, "tools"),
        E("dsh-cookie-cleaner", "dsh-cookie-cleaner", "桌面客户端的赛博端粒不老药：解决启动报 `desktop welcome: Web authentication failed`（HTTP 431）的现象——Electron 随机端口启动，`dsh-auth-*` 登录 cookie 随端口越积越多（70 余条、单条约 229 B），启动请求头撑爆", "net", 1, "tools"),
        E("dsh-custom-env", "dsh-custom-env", "在设置中管理 $DSH_HOME/.env，并同步到 Host 与 Windows/macOS 用户环境。", "misc", 1, "tools"),
        E("dsh-custom-headers", "dsh-custom-headers", "添加可配置的 HTTP 请求头配置档，并支持按模型选择。", "net", 1, "tools"),
        E("dsh-darksouls-guide", "dsh-darkSoulGuide", "读你自己的《黑暗之魂3》Windows 存档（默认 `%APPDATA%\\DarkSoulsIII\\*\\DS30000.sl2`）回答问题：等级与属性、当前区域、按家族统计的篝火/戒指/法术/誓约完成度、24 个 Boss 的击杀状态，装有 Steam 时还包括 Steam 成就；以模型工具提供，另", "text", 1, "tools"),
        E("dsh-data-insight", "dsh-data-insight", "数据分析工具包：CSV/TSV/JSON 数据画像、IQR 与 z-score 异常检测、带质量问题提示的结构化摘要、以及无需写代码的筛选/分组/聚合查询。", "data", 1, "tools"),
        E("dsh-deai-audit", "dsh-deai-audit", "中文文案去 AI 味审计：0–100 六维评分、逐句打标并给出改法，文体权重可在对话里查看和修改。", "session", 1, "tools"),
        E("dsh-deepsearch", "dsh-deepsearch", "DSH 右侧栏里的多轮深度搜索：每轮把子问题派给多个子代理并行查，再在上一轮基础上继续深挖，最后产出带引用的调研报告。", "net", 1, "tools"),
        E("dsh-design", "dsh-design", "在渲染后的页面上测量设计规则，而非解析 CSS——字号种类、与真实合成背景比对的 WCAG AA 对比度、间距栅格偏移、配色规模、点击区尺寸，以及「机器味指纹」（如按色相角度判定的紫色渐变）；内置 design-system 技能。", "misc", 1, "tools"),
        E("dsh-desktop-sidecar", "dsh-desktop-sidecar", "原生 Windows 桌面控制，共 21 个工具：UIA 控件树 + 离线 OCR 看屏幕、按控件名字点击、不占剪贴板地打中文，微信 / Office / 浏览器 / 网课都能操作。不抢你的鼠标键盘（你在用它会等）、从不改你的窗口大小，侧边栏「指挥台」可随时打字纠正，每步操作后都会回头核对屏幕并如实", "image", 1, "tools"),
        E("dsh-desktop-tools", "dsh-desktop-tools", "dsh 环境管理插件：自动获取 Rust/Tauri 桌面宿主（按系统从 dsh-desktop-host 下载，无 Release 时源码构建），运行时一键更新、Windows 平台兼容自动适配、DeepSeek 官方计费，并内置工作区代码编辑器。", "net", 1, "tools"),
        E("dsh-disk-manager", "dsh-disk-manager", "扫描整 C 盘,把每个大空间按 A/B/C/D/E/P 分类(无忧缓存/官方可改址/可junction搬/冷废弃软件/配置记忆红线/个人文件),再按需删缓存/junction搬走/引导改址,带强红线保护、dry-run 预览与 undo。未知软件由 LLM 兜底 + 人工确认,动手前先预览、做完可回", "fileops", 1, "tools"),
        E("dsh-docker-1", "dsh-docker", "类型安全、带护栏的容器控制：ps/logs/inspect/exec/start/stop 与 compose up/down，JSON 输出、项目感知定位、破坏性操作需审批。", "data", 1, "tools"),
        E("dsh-dota2bp", "dsh-dota2bp", "Dota 2 天梯无 Ban 2-2-1 征召助手，支持分段与职业数据口径、灵活分路成员池、参战勾选和 BP 后预测胜率。", "misc", 1, "tools"),
        E("dsh-douyin-publish", "dsh-douyin-publish", "把本地视频送到抖音投稿页的「待发布」状态：打开投稿页、真实点上传、递文件（回读校验）、填标题、设可见性，然后默认停手——可见性默认仅自己可见、不点发布。", "media", 1, "tools"),
        E("dsh-draft-polish-1", "dsh-draft-polish", "DSH 输入框一键润色草稿：把口语化表达改写成专业措辞；只发送草稿快照、绝不夹带会话上下文；LLM 不可用时优雅降级，不阻塞发送。", "session", 1, "tools"),
        E("dsh-dual-auto", "dsh-dual-auto", "双模型 Auto 路由插件：低成本模型直返 / 高成本模型升级 + 逃逸学习闭环（直返答错自动学习指纹，同指纹下次强制升级），状态持久化并与 Python ModelRouter 互通。", "ai", 1, "tools"),
        E("dsh-emailreader", "DSH-EmailReader", "面向密码认证被禁用邮箱的 OAuth2 IMAP 读取插件：微软 2024 年起停用个人 Outlook 的 IMAP 基本认证，本插件改用 refresh-token OAuth2（XOAUTH2）自动续期，Gmail 走应用密码并可选本地 HTTP/SOCKS 代理；工具注册为 ol_email", "net", 1, "tools"),
        E("dsh-encoding", "dsh-encoding", "编码正确的命令执行与乱码还原：encoding_run 自动识别 UTF-8/UTF-16LE/GBK 并正确解码子进程输出，encoding_decode 把乱码文本还原为正确 Unicode。", "image", 1, "tools"),
        E("dsh-enter-plan-mode", "dsh-enter-plan-mode", "进入计划模式工具：给模型一个可调用的 `dsh_enter_plan_mode_enter_plan_mode`，把当前会话切进计划模式，与内置的 `exit_plan_mode` 配对，形成“先规划、后评审”的闭环。", "session", 1, "tools"),
        E("dsh-environment-context", "dsh-environment-context", "将实时的时间、天气、地点、电量和设备信息注入 DSH 系统提示，并提供双语设置页面。", "time", 1, "tools"),
        E("dsh-figma-plugin", "dsh-figma-plugin", "给 agent 用的 Figma 设计上下文：读取画板的节点树、自动布局、填充与字体，解析节点绑定的设计变量，并渲染截图用于对照代码 —— 另附四个设计转代码技能。点一个按钮即跳转 Figma 官方授权页完成连接；插件自带 OAuth 应用、自动续期令牌，全程不索取也不展示任何 Token。", "image", 1, "tools"),
        E("dsh-file-share", "dsh-file-share", "会话工作区文件管理：在对话区加「文件」tab，浏览当前会话工作区的目录树并就地管理（上传/下载/新建文件夹/改名/删除/搜索），文件可 @ 进对话框给 agent 处理。", "net", 1, "tools"),
        E("dsh-geoserver", "dsh-geoserver", "在 dsh web GUI 中读取 GeoServer WMS 服务并渲染地图图像，带服务器地址、用户名和密码设置卡片。", "image", 1, "tools"),
        E("dsh-gitbash-1", "dsh-gitbash-new", "DeepSeek Harness 的 Windows bash 工具：用 Git for Windows 或 MSYS2（UCRT64/MINGW64/CLANG64…）的 bash 替换预设里的 pwsh，保留官方终端契约（workdir、后台任务与超时转后台、结果标记、终端卡片），并提供一个可自", "git", 1, "tools"),
        E("dsh-github-trending", "dsh-github-trending", "Harness Web UI 里的 GitHub 趋势雷达：抓取日榜/周榜/月榜（可按编程语言筛选），把每个仓库分析成简介、star 增量、技术栈、亮点与风险，渲染为可筛选、可分页的卡片面板，并注册 github_trending 工具与 /github-trending 命令。", "git", 1, "tools"),
        E("dsh-gongwen-word-check", "dsh-gongwen-word-check", "依据公开的党政机关公文格式标准，核对公文的文种与发文字号——包括年份所用的括号形式与编号格式。只报告与格式不符之处，不评价公文内容。", "misc", 1, "tools"),
        E("dsh-guard-ui", "plugin", "会话头部的「护航」面板：启停本机 dsh-guard 守护，显示扫描开关、守护心跳与上次扫描时间；做监控的 Python 守护需单独部署，插件通过 DSH_GUARD_ROOT 环境变量定位它的目录。守护默认路径是 Windows 上的 D:\\AI\\Projects\\dsh-guard，可用 DSH", "time", 1, "tools"),
        E("dsh-guardian", "dsh-guardian", "dsh-guardian 守护程序面板：在 dsh WebUI 中启动、停止并查看两个 macOS LaunchAgent 的状态、日志尾行与明确的失败提示。", "ai", 1, "tools"),
        E("dsh-hashline-edittool", "dsh-hashline-edittool", "把 DeepSeek Harness 的文件工具换成哈希锚定版本：read、edit、write、grep 被替换为按变长内容锚点定位每一行（而不是行号）的实现，插件同时注册 delete、rename、undo_last_edit、ast_grep、ast_edit、lsp 与 format 七个", "codec", 1, "tools"),
        E("dsh-human-task", "dsh-human-task", "人工协作工具（`human_task` / `human_task_ready_check`）：让 Agent 暂停等待用户完成现实操作或返回观察结果（GUI 操作、游戏测试、视觉验证、硬件检查等），内置会话同意与 AFK 在场两级门控，通过 Web 任务窗返回结构化 JSON 结果。", "data", 1, "tools"),
        E("dsh-icloud-calendar", "dsh-icloud-calendar", "通过 CalDAV 读写苹果 iCloud 日历，提供五个工具：列出日历、按时间窗读取并展开重复日程、创建事件，以及先干跑、按对象数确认后再删除。凭据保存在 DPAPI／钥匙串／libsecret 或环境变量中。", "time", 1, "tools"),
        E("dsh-image-create", "dsh-image-create", "在 DSH 内直接文生图/图生图：对接 OpenAI 兼容图像接口，提供 Agent 生图工具、多供应商自动降级，以及带生成历史的侧栏工作台。", "image", 1, "tools"),
        E("dsh-inimerse", "tools/dsh-inimerse", "五个工具，用于构建、测试与运行 Inimerse 引擎，并通过服务端行协议驱动其 Verse 层。需要本机有 Inimerse 源码检出并用 CMake 构建；在 bundle 配置中把 repoRoot 指向它（默认值是作者本机路径）。", "fileops", 1, "tools"),
        E("dsh-intellisense", "dsh-intellisense", "一个用于管理工具集的命名空间管理工具，支持自动发现与集成，用于节省token的消耗还会在受限 Node 运行时执行 TypeScript 与 JavaScript，按需通过命名空间调用工具。", "ai", 1, "tools"),
        E("dsh-ip-info", "dsh-ip-info", "DeepSeek Harness 的 IP/域名情报：ip_lookup、dns_lookup、whois_lookup 工具，走免费免 key API(ipwho.is、Google DoH、RDAP)。", "net", 1, "tools"),
        E("dsh-jev", "dsh-jev", "基于 TypeSafe Jev 的 DeepSeek Harness 语义工具路由、技能发现与类型化 System One 决策插件。", "misc", 1, "tools"),
        E("dsh-jev-verify", "dsh-jev-verify", "0.8.6 修复了一个会让宿主起不来的依赖问题（宿主运行时包改为 optional peer，永不被安装）。为 DeepSeek Harness 端到端接入 TypeSafe Jev（System One 决策模型）0.8.6。共七个工具：jev_decision（一次并行完成 1-25 个原子判定", "ai", 1, "tools"),
        E("dsh-lan-share", "dsh-lan-share", "通过浏览器把 DSH 工作区分享到局域网：手机、平板、其它电脑可浏览、下载、上传文件，无需 DSH 登录。带令牌门卫、路径边界、只读模式与速率限制，零依赖(node:http)。", "net", 1, "tools"),
        E("dsh-language-control", "dsh-language-control", "让 Agent 的思考过程也自动使用中文。在每步推理前向 System Prompt 最顶部注入语言约束，强制思维链、规划、工具调用推理全部使用中文，防止工具返回英文内容后发生语言漂移。支持在设置面板中实时编辑约束文本。", "ai", 1, "tools"),
        E("dsh-latex", "dsh-latex", "用本机已装的 TeX Live 真编译 LaTeX：`latex` 工具把一个公式排成 SVG、PNG 或 PDF，把整份文档排成 PDF（正文含中文时自动切 xelatex + ctexart），产物写进工作区并返回可直接引用的 Markdown 链接。同时注入系统提示词段落，让模型用 `$...", "pdfdoc", 1, "tools"),
        E("dsh-launcher", "dsh-launcher", "DSH Web 服务的 macOS 菜单栏应用，以及它所读取的 Host 插件：插件把运行中服务的端口、PID 与带 token 的 URL 写入 ~/.config/dsh-launcher/runtime.json，并在停止时删除，因此即使服务器是从终端启动的，也能在状态栏完成启动、打开、重启与", "data", 1, "tools"),
        E("dsh-lazy-mcp", "dsh-lazy-mcp", "dsh 的按需 MCP 网关：每个 server 首次使用时才连接、空闲后自动断开，工具列表缓存在磁盘，可导入现有的 mcpServers 配置，并对子进程环境变量做脱敏。", "sysinfo", 1, "tools"),
        E("dsh-lexiforge", "dsh-lexiforge", "改写模型回复的语言包框架：A 为独立 LLM 改写，B 将 FTS5 术语检索注入改写请求，C 执行本地字典与正则规则，composite 按 B→A→C 等管线组合。附 GitHub 语言包市场、带路径/体积/文件类型校验的 ZIP 安装器，以及强制风险免责闸门。", "archive", 1, "tools"),
        E("dsh-light-tool", "DLT", "一个 DSH 插件里的六个可独立开关的模块：每轮对话的人民币成本、DeepSeek 账户余额、PDF/Word/Excel/CSV 直接读写工具与右栏预览、编译/运行环境表，以及按环境名执行程序或编译 MSBuild 工程的 run/build 工具。工具链路径在运行时解析（扫描 Visual St", "pdfdoc", 1, "tools"),
        E("dsh-link-collect", "dsh-link-collect", "把收藏的链接存成你指定文件夹里的 Markdown 文件，带侧栏页面管理收藏夹与链接、全库搜索、自动抓取图标，以及三个 agent 工具。", "pdfdoc", 1, "tools"),
        E("dsh-lit-fetch", "dsh-lit-fetch", "按 DOI 或关键词获取学术文献：Crossref 与 OpenAlex 检索，经 8 个 Sci-Hub 镜像批量下载 PDF 并以 Unpaywall 开放获取兜底，含 PDF 魔数校验与并发控制，并为未下载到的文献生成可点击的批量获取清单 HTML。", "pdfdoc", 1, "tools"),
        E("dsh-literature-search", "dsh-literature-search", "面向 DeepSeek Harness 的文献检索：pubmed_search、pubmed_paper、pubmed_related 走官方 NCBI E-utilities（含 elink 相关文献排序），scholar_search、scholar_cite 走 Google Scholar（", "text", 1, "tools"),
        E("dsh-local-3d-studio", "dsh-local-3d-studio", "本地三维工作室编排：每次调用都现场探测 Blender、COLMAP 与 ComfyUI 并按其支持情况选路线；另带 Three.js 兜底通道，可按图元描述生成模型、修改或缩放 GLB、生成离线预览页并在没有 Blender 时渲染多视角 PNG。", "image", 1, "tools"),
        E("dsh-ma-plugins-1", "dsh-oracle", "强制只读、会脱敏的第二意见子代理。", "net", 1, "tools"),
        E("dsh-mail", "dsh-mail", "通过 IMAP/SMTP 列出、读取、搜索、回复、发送和移动邮件的工具集，内置 QQ／163／126／Gmail／Outlook／iCloud 与自定义服务器预设，支持附件上传下载，并提供侧栏账号配置页。", "net", 1, "tools"),
        E("dsh-malong-bridge", "bundle", "将 LiuHe MCP 代码工具集（44 个工具）桥接进 dsh web：repo_map、符号搜索、带容错匹配的 edit_batch、带撤销日志的事务性编辑，以及确定性质量门禁——由崩溃隔离的 Rust tree-sitter 解析守护进程和 SQLite 索引支撑。", "data", 1, "tools"),
        E("dsh-markdownize", "dsh-markdownize", "将 PDF、Word、PowerPoint、Excel、HTML、CSV、JSON、ZIP 等文档转换为 Markdown 供模型读取，内置 JavaScript 引擎，也可使用 Microsoft MarkItDown。", "pdfdoc", 1, "tools"),
        E("dsh-mcp-autoload", "dsh-mcp-autoload", "自动加载项目级 MCP 服务器：项目在 `.agents/mcp.json` 中声明服务器（路径与根目录标记可配置），在项目内工作的每个会话各自的作用域里挂载——支持 stdio 与 Streamable HTTP，工具名为 `mcp__<server>__<tool>`——会话结束时断开连接。We", "data", 1, "tools"),
        E("dsh-mcp-client-manager", "dsh-mcp-client-manager", "DSH 插件：一块设置面板管理 @deepseek-ai/dsh-mcp-client 的 MCP 行——列出、新增、改写、启停，不必再手写 cordis.patch.yml；零构建、零运行依赖。", "misc", 1, "tools"),
        E("dsh-mcp-console", "dsh-mcp-console", "插件页 MCP 服务器控制台：运行时管理官方 @deepseek-ai/dsh-mcp-client——新增/编辑/删除服务器、启停/重连、工具级开关、SSE 实时状态与工具列表、mcpServers JSON 导入、自动迁移 profile YAML 里的 MCP 条目；卸载后留下原生 fallb", "data", 1, "tools"),
        E("dsh-mcp-link", "dsh-mcp-link", "扫描 Cursor、Claude Code、Codex CLI、Gemini CLI、VS Code 等 13 种客户端和项目工作区的 MCP 配置，把选中服务接入当前 DSH profile，并提供连接测试、原地重连、JSON 导入和图形化新增、编辑和移除。", "data", 1, "tools"),
        E("dsh-mcp-manager", "dsh-mcp-manager", "面向 DSH 的 MCP 服务器管理器：在面板中增删改、启用或停用 Model Context Protocol 服务器，支持 stdio 与 streamable-HTTP 两种传输、按服务器设置工具调用超时、实时查看连接状态与工具数量，并持久化到项目级或主目录的 mcp.json。@wingsk", "data", 1, "tools"),
        E("dsh-mcp-manager-2", "dsh-mcp-manager", "一个设置页管理本机所有 MCP 服务器。它读取另外 17 种 AI 工具的真实配置文件（Claude Desktop、Claude Code、Cursor、VS Code、Windsurf、OpenCode、Trae、Trae CN、Qoder、Gemini CLI、Qwen、Zed、Roo Cod", "codec", 1, "tools"),
        E("dsh-mcp-rea", "dsh-mcp-rea", "把 REA（逆向一切）的 MCP 服务收成两个网关工具，而不是每次请求都注册它的 200 多个工具 schema：rea_list 按名字/描述搜索工具目录、或取单个工具的完整 input schema，rea_call 按原始工具名调用，每次调用启动一个短命 rea mcp 子进程，每步请求的工具", "data", 1, "tools"),
        E("dsh-minimax-multimodal", "dsh-minimax-multimodal", "为 DeepSeek Harness 添加 MiniMax 识图、文生图、语音合成和语音转写工具。", "media", 1, "tools"),
        E("dsh-model-failover-1", "dsh-model-failover", "模型接力路由器：将已接入 DSH 的全部模型排成优先级队列，失败时自动重试「继续」，不行则切换下一模型，并将故障模型隔离至次日。", "ai", 1, "tools"),
        E("dsh-mojibake-interceptor", "dsh-mojibake-interceptor", "DSH 乱码拦截器 bundle：写入前特征值/编码回环检测乱码并复查放行（原样重试即通过），pwsh 写入编码执行前审计（ANSI/GBK/UTF-16/默认编码），Windows 与中文场景优先。", "codec", 1, "tools"),
        E("dsh-motion", "dsh-motion", "面向 DSH 的代码生成数学/科普动画：六个工具覆盖环境预检与依赖自愈、把 Manim/manimgx 场景渲染为 storyboard 帧或 MP4、对成片抽帧拼图检查黑帧与过曝、用 SymPy 判断公式恒等；另带三个技能（题材路由、设计规范、交付自检）、含时间轴与旁白的项目脚手架、渲染前的需求确", "pdfdoc", 1, "tools"),
        E("dsh-multi-workspace", "dsh-multi-workspace", "多工作区沙箱：自动赋予所有已注册工作区的文件写入权限——添加工作区后即可直接写入，无需配置或提权。", "fileops", 1, "tools"),
        E("dsh-netcafe", "dsh-netcafe", "托管工具服务器（MCP）：发票与银行流水提取并做代码内算术校验、按整数分对账、PDF 与表格转换、SQL 方言转写，以及从中国移动骨干网实测大陆可达性。", "pdfdoc", 1, "tools"),
        E("dsh-novel-studio", "dsh-novel-studio", "小说创作工作区：一本书一个文件夹、YAML/Markdown 分区、关系图自动连边、一致性校验、四个 AI 任务与四种导出格式。", "pdfdoc", 1, "tools"),
        E("dsh-nx", "dsh-nx", "从 DeepSeek Harness 驱动 Siemens NX 2406 与 2506，也支持 NX 12：一个按日志而非退出码判定 journal 成败的执行器（NX 对吞掉异常的 journal 返回 0，干净结束时返回 0xC0000409）、常驻批处理 NX 上的 16 个类型化工具，以及", "devops", 1, "tools"),
        E("dsh-omicos", "dsh-omicos", "在持久 Python 内核里跑 OmicVerse/OmicOS 生信分析，附能力目录检索、内核变量查看与账号订阅页签。", "image", 1, "tools"),
        E("dsh-onebot-channel", "dsh-onebot-channel", "经 OneBot 11 把 QQ 私聊和群聊接进 DSH，提供 qq_send 等工具，让 agent 能回消息、发表情、等待对方接话。", "session", 1, "tools"),
        E("dsh-pace-calc", "dsh-pace-calc", "跑步配速计算：根据距离与时间换算配速（分/公里）与速度（公里/小时）。", "time", 1, "tools"),
        E("dsh-patch-apply", "apply-patch", "将结构化 unified diff（git 格式）应用到真实文件系统：多文件/多 hunk 解析、带行号偏移修正的模糊定位、全有或全无的应用与类型化冲突报告、反向补丁撤销日记及 dry-run——4 个 patch_* dsh 工具外加一个 CLI。", "git", 1, "tools"),
        E("dsh-pdf-translate", "dsh-pdf-translate", "用 DeepSeek 或兼容 API 翻译文本型 PDF，保留版式、字体、图片与链接，输出可编辑 PDF。", "pdfdoc", 1, "tools"),
        E("dsh-phocinae", "dsh-phocinae", "本地非生成式决策层：phocinae_ask 与 phocinae_gate 由小型决策模型返回带校准置信度的类型化裁决，并对无法回答的情况 fail-closed 升级。需在本机 8155 端口运行 phocinae-server（pip 安装）并加载 Phocinae-Largha-150M-v", "net", 1, "tools"),
        E("dsh-pi-compatible", "dsh-pi-compatible", "在 DeepSeek Harness 中复刻 Pi 工具组：安装小写 read/write/edit/bash/find/grep/ls 核心工具，并保留 DSH-backed 网页、任务、计划、todo、think 与 slash 扩展。", "misc", 1, "tools"),
        E("dsh-plan-mode-plus", "dsh-plan-mode-plus", "dsh 计划模式的 ZCode 式增强：模型可主动调用 enter_plan_mode 进入计划模式，计划期间写类工具在分发前被硬拦截，并注入「探索 → 设计 → 评审 → 退出」四阶段工作流提示词；复用官方 plan/mode 状态机与退出评审流，只做增量。", "ai", 1, "tools"),
        E("dsh-plugin-8", "dsh-plugin", "DeepSeek Harness 的参考素材检索插件：refkit_search 在 24 个开放来源中检索图片、视频、音频和文本参考素材，为每条结果标注规范化的许可证和针对用途的可用性判定；refkit_rights 针对另一种用途复核单条许可证。来源 key 与检索参数在设置页配置。24 个来源", "image", 1, "tools"),
        E("dsh-plugin-agnes-image", "dsh-plugin-agnes-image", "提供 agnes_image 工具，调用 Agnes Image Flash 系列模型（2.5 / 2.1 / 2.0）完成文生图、图生图与多图合成，并带一个设置页控制台管理当前模型、默认档位与画幅、输出目录、API Key 与生成历史。", "fileops", 1, "tools"),
        E("dsh-plugin-baiguangda-style", "dsh-plugin-baiguangda-style", "把机核网编辑白广大的中文文风做成可执行的判据：注册一份 40 KB 风格技能，并提供 style_lint / style_audit / style_rules 三个工具——4 条硬错误 + 27 条警告（空转转折、金句通胀、冗余量词、段落过于均匀、孤证数字、AI 口头禅等），阈值按 444 篇", "misc", 1, "tools"),
        E("dsh-plugin-corpus", "plugin", "DeepSeek Harness 的本地知识库与文档检索插件：全文搜索、PDF/Word/PPT/Excel/Markdown 导入与按行读取、扫描件 OCR、ACL 和 Web 面板。", "pdfdoc", 1, "tools"),
        E("dsh-plugin-deepsearch", "dsh-plugin-deepsearch", "给 DSH 内置 web_search 加一个开关：在 DeepSeek Search API（/v1/tools/search）与默认账号搜索之间切换，失败自动回退，并带设置页与侧栏开关。", "search", 1, "tools"),
        E("dsh-plugin-device-info", "dsh-plugin-device-info", "只读的 Windows 设备信息工具：每个 Win32 设备类别一个 agent 工具（时间、系统、CPU、内存、磁盘、GPU、网络、电池、进程、USB、音频、打印机），基于 WMI/CIM 与 Node os 采集。", "media", 1, "tools"),
        E("dsh-plugin-everything", "dsh-plugin-everything", "Windows 全盘文件搜索：按文件名、路径、扩展名、大小或修改时间检索，毫秒级从本机 voidtools Everything 索引返回匹配的文件与文件夹（完整路径、大小、修改时间）；另一张卡片显示 Everything 是否可达与索引条目数。内置官方 Everything SDK，不需要 es.", "time", 1, "tools"),
        E("dsh-plugin-project-management", "dsh-plugin-project-management", "一个 DeepSeek Harness 插件，通过与用户进行项目需求访谈，生成项目时间线 / 甘特图，并导出为 Word 或 Excel 格式。", "time", 1, "tools"),
        E("dsh-plugin-qcc", "dsh-plugin-qcc", "企查查企业数据源动态 Cordis 插件：5 个 agent 工具（扫码登录认证、企业快搜、知识库检索、工具发现、取数执行），覆盖工商/股东/司法/知识产权等 100+ 数据维度，附设置页账号管理；网络与文件 IO 经 DSH subprocess 拉起 node -e 完成，凭证与本地 BizOw", "sysinfo", 1, "tools"),
        E("dsh-plugin-sirchmunk", "dsh-plugin-sirchmunk", "在 DSH 设置中管理本地 Sirchmunk 知识库：图谱导出、聚类管理、审计历史、运行指标与隐私控制。", "misc", 1, "tools"),
        E("dsh-plugin-tempguard", "dsh-plugin-tempguard", "为本地 tempguard 温度守护提供两个 DSH 工具：读取温度与 alertd 健康状态，以及通过 alertd 发送告警。需另行在本机运行 tempguard Python 看门狗及其 alertd 服务，并在 profile patch 里配置 projectDir 与 alertdTok", "sysinfo", 1, "tools"),
        E("dsh-plugin-translation", "dsh-plugin-translation", "为 DSH agent 提供翻译工具包：句子分块、术语与术语表提取、译文质检（数字、单位、括号）、语气指南与工作区持久化翻译记忆。", "session", 1, "tools"),
        E("dsh-plugin-undermind", "dsh-plugin-undermind", "把 Undermind 的文献检索接进 DeepSeek Harness。插件自己维护远端 MCP 服务要求的 OAuth 授权码 + PKCE 登录，在到期前刷新并轮换 refresh token、在服务端丢弃会话时重新初始化，并把 Undermind tools/list 返回的每个工具注册成", "session", 1, "tools"),
        E("dsh-plugins-12", "dsh-mcp-client-v2", "MCP 客户端增强：分页工具发现、非阻塞启动、mcp_tool_search 搜索，自研 stdio/streamable-http 传输。", "search", 1, "tools"),
        E("dsh-plugins-loulan-1", "dsh-loulan-mcp", "读取 .dsh 根目录与 agent 工作区里的 .mcp.json，把其中的 MCP server 挂载进 DSH；Web 界面增加「MCP」标签页，可查看、添加与卸载服务。", "data", 1, "tools"),
        E("dsh-problem-bank", "dsh-problem-bank", "面向 DeepSeek Harness 的结构化数学题库：多解法、分层知识图谱、六维难度与技巧驱动的变式出题。", "misc", 1, "tools"),
        E("dsh-profile-settings", "dsh-profile-settings", "为 DeepSeek Harness 提供按 profile 分层的设置覆盖：全局 settings.yaml 仍为基线，每个 profile 可用自己的 profiles/<name>/settings.patch.yml 覆盖任意设置命名空间——对象段递归合并，数组与标量整体替换，!unset", "data", 1, "tools"),
        E("dsh-progress", "dsh-progress", "「进度」实验/项目进度管理：16 个 progress_* agent 工具（安排增删改查、画板页、每日记录、全局搜索、概览、甘特、留言、导入导出），并在 better-sidebar 注册「进度」侧边栏 tab 托管原版界面；数据存会话项目 .progress/progress.json，随项目目", "data", 1, "tools"),
        E("dsh-project-mcp", "dsh-project-mcp", "按项目挂载 MCP 服务器：项目在自己的文档里声明服务器（默认 `.dsh/mcp.json`，本地与全局文件列表均为配置项），只对在该项目中工作的会话挂载——会话首个 turn 时挂载，空闲后释放。右侧栏标签页与设置页列出每个有活动会话的项目、各服务器状态以及持有挂载的会话，并提供 `Sync`", "data", 1, "tools"),
        E("dsh-prompt-lint", "dsh-prompt-lint", "读你的历史会话，找出反复踩的提问坑（缺路径与版本、没定输出格式、漏说前置条件导致工具失败），每条给一段可直接粘贴的改写；输入框右侧一键把草稿改成更短的带约束版本。", "fileops", 1, "tools"),
        E("dsh-public-apis", "dsh-public-apis", "把 public-apis 目录接入 DeepSeek Harness：按关键词、分类、auth、https、cors 搜索 1716 个免费公共 API 并直接调用。", "fileops", 1, "tools"),
        E("dsh-qixin-insight-mcp-oauth", "dsh-qixin-insight-mcp-oauth", "通过 OAuth 2.1 + PKCE 授权接入启信慧眼 MCP 服务，以单条插件条目把它的工具挂载为 mcp__qixin_insight__*，token 到期前自动刷新，断开时吊销。", "ai", 1, "tools"),
        E("dsh-qq-zone", "DSH QQ Zone", "通过 SnowLuma 的 OneBot qzone_* 动作发/看/删/赞/评论 QQ 空间说说（需 SnowLuma 2.2+ 且已登录 QQ），并让机器人用本地视觉模型（OpenAI 兼容网关）或 Windows OCR 看懂图片。", "image", 1, "tools"),
        E("dsh-qqbot", "dsh-QQbot", "DSH QQ机器人桥接插件，将DeepSeek Harness对接QQ机器人。", "misc", 1, "tools"),
        E("dsh-qzone", "dsh_qzone_sticker", "QQ 空间发说说插件：手机 QQ 扫一次码登录，之后由模型按心情挑表情包发说说，支持每天条数上限，静默 Chrome 不占屏。", "ai", 1, "tools"),
        E("dsh-reckoner", "dsh-reckoner", "面向 DeepSeek Harness 的确定性计算引擎，附带一个预设：引导 LLM 通过引擎而非文本生成来完成计算。", "ai", 1, "tools"),
        E("dsh-restart-planner", "dsh-restart-planner", "让 agent 自己安排宿主重启：工具立刻返回，等这一轮回复送达、会话日志落盘安静后再停+拉，并留下报告；自带 dry-run、体检与「什么时候可以眨一下眼」的确认。", "session", 1, "tools"),
        E("dsh-rich-questions", "dsh-rich-questions", "网页端分支问卷：ask_survey 工具，按选项路由后续问题，悬停洞察、Mermaid 流程图、一键快速模板，答案可暂存续答。", "git", 1, "tools"),
        E("dsh-rss-digest", "rss-digest", "dsh 的 RSS/Atom 摘要插件:订阅源管理、定时抓取、精确与近似去重,并由 LLM 生成每日 Markdown 简报投递到会话和/或文件(同时提供独立 CLI)。", "pdfdoc", 1, "tools"),
        E("dsh-scan-mcp", "dsh-scan-mcp", "扫描 Claude Code / Codex / CodeBuddy 配置中的 MCP，通过 stdio 与 streamable-http initialize 握手检测真实连通性，支持启停开关与 /mcp 控制面板。", "misc", 1, "tools"),
        E("dsh-script-manager", "dsh-script-manager", "DSH 自定义操作脚本管理器，将验证过的操作流程固化为可复用的脚本，用 /script 直接运行或注册为 Agent 工具，支持参数化脚本、执行预期声明、执行历史记录。", "ai", 1, "tools"),
        E("dsh-self-trigger", "DSH Self Trigger", "宿主空闲时由 Agent 自己决定要不要往指定会话注入一轮：每日上限、活跃时段、按权重抽动作、单次预算，策略文件每次判定现读。默认关闭，不发任何网络请求。", "fileops", 1, "tools"),
        E("dsh-semantic-drift", "dsh-semantic-drift", "一份按项目维护的业务概念词表、只读命名漂移扫描，以及注入每个 Agent 提示的同一套命名规则。", "ai", 1, "tools"),
        E("dsh-semble", "dsh-semble", "面向 DeepSeek Harness 的语义代码搜索：注册 semble_search（按行为描述检索代码，返回按相关度排序的 file:line 命中）与 semble_find_related（查找已知位置的相邻代码）两个原生工具，检索由 uvx 启动的 Semble CLI 完成，并附一个随", "fileops", 1, "tools"),
        E("dsh-serper-search", "dsh-serper-search", "互补式网页搜索 provider：每次 web_search 由 DeepSeek 官方 Search API（主）与 serper.dev 的 Google 结果（补）按固定 2:1 交错合并。两路均为直连检索、无辅助模型调用；来源按 URL 去重，官方长摘要截断注入，单路超时自动降级到另一路。", "text", 1, "tools"),
        E("dsh-sheet-diff", "dsh-sheet-diff", "按业务主键对齐 CSV/XLSX 改动，离线记录审阅结论与批注，核对源文件后生成反馈交接包。", "data", 1, "tools"),
        E("dsh-shell-switch", "dsh-shell-switch", "让 bash 工具在本机设置里选定的 shell（Niubash、Git Bash、MSYS2、Cygwin 或 PATH 上的 bash.exe）中执行命令，不再改写为 PowerShell，并在 Windows 下隐藏 pwsh 工具。", "git", 1, "tools"),
        E("dsh-shop-assistant", "dsh-shop-assistant", "电商店主工作台：CSV 批量预览（多平台列适配）、可复算利润与六维评分、公开商品页快照、中文 skills、可替换售后政策知识库。", "data", 1, "tools"),
        E("dsh-shortcut-creator", "dsh-shortcut-creator", "在设置页一键创建 Windows 桌面快捷方式：为 DeepSeek Harness 或任意本地服务生成 .cmd 启动器与桌面图标，自动打开浏览器、可固定任务栏。", "misc", 1, "tools"),
        E("dsh-smswebhook", "DSH-SmsWebhook", "DSH 短信转发 webhook：手机端转发 App（短信转发器/Tasker 等）把短信 POST 到本地 HTTP 端点，插件落盘 JSONL 并暴露 sms_recent / sms_search 工具，让 agent 在任务中直接读取短信验证码；自动提取 4–8 位 OTP，支持关键词过滤，", "data", 1, "tools"),
        E("dsh-snippets", "dsh-snippets", "DSH 极简片段/命令工具箱：5 个工具，一个可手工编辑的 JSONL 文件，零 UI、零数据库、零网络，只有明确说存才存。", "data", 1, "tools"),
        E("dsh-solidworks", "dsh-solidworks", "通过 MCP 服务器把 DeepSeek Harness 接入本机 SolidWorks，默认只读模式，高风险操作逐次确认。仅 Windows 10/11 x64；需 Python 3.10+ 并装好 mcp、pydantic、jsonschema（Windows 上还需 pywin32、comty", "data", 1, "tools"),
        E("dsh-stage-gate", "dsh-stage-gate", "阶段门治理工具：模型可直接调用的 gate_open / gate_check / gate_list / gate_close，为多阶段工作提供内存态、按会话隔离的验收核对与通过/阻塞结论。", "sysinfo", 1, "tools"),
        E("dsh-stash", "dsh-stash", "把外部数据库与文献语料登记成模型可调用的取数工具；每条库声明取数边界，钥匙台账只记引用名不存值，取数台账只留指纹与内容哈希而不留响应体。", "codec", 1, "tools"),
        E("dsh-stock-research", "dsh-stock-research", "基于数据快照提供 A 股与美股的单股研究和问答。", "misc", 1, "tools"),
        E("dsh-su", "dsh-su", "SketchUp Pro 2023 桥接插件：让 Agent 检查实时模型、执行 Ruby 任务脚本、保存 .skp 并截取视口 PNG。", "image", 1, "tools"),
        E("dsh-subagent-antigravity-2", "dsh-subagent-antigravity", "把 Google 官方 Antigravity CLI（agy）作为一次性编码子智能体接入 DeepSeek Harness，提供 subagent_antigravity 委派工具，可直接使用 Gemini 4 Argon 等 Antigravity 订阅模型。需安装并登录 Antigravity", "codec", 1, "tools"),
        E("dsh-subagent-claude-code-wrapper", "dsh-subagent-claude-code-wrapper", "子代理委派提供方：通过可配置的 executablePath 字段，运行任意 Claude 兼容 CLI 二进制。", "data", 1, "tools"),
        E("dsh-sxs-news-collector", "dsh-sxs-news-collector", "时事热点采集：一次调用聚合百度热搜 / 头条热榜 / 抖音热点 / 微博热搜（微博可选 cookie），返回标题+热度值，供内容创作借势——工具：`sxs_news_hot`。", "misc", 1, "tools"),
        E("dsh-sync", "dsh-sync", "把 DSH 配置档案（插件、设置、技能、界面偏好与可选的 MCP 连接器或 API Key）加密定时备份到 S3 兼容存储、WebDAV 或本地目录，恢复时自动重装缺失的插件。", "codec", 1, "tools"),
        E("dsh-system-monitor-plugin", "dsh-system-monitor-plugin", "监控dsh进程及其派生子进程的资源占用,并以面板图表报告整机与各会话的CPU与内存占用", "sysinfo", 1, "tools"),
        E("dsh-system-net", "dsh-system-net", "让 DSH 跟随系统网络设置：走系统代理并信任系统证书库，无需环境变量、无需重启。", "net", 1, "tools"),
        E("dsh-table-attach", "dsh-table-attach", "把表格与文档（xlsx、csv、pdf、zip…）粘贴或拖拽进 DSH 输入框即可附加：文件会保存到会话工作区并插入 @引用。", "pdfdoc", 1, "tools"),
        E("dsh-talebook-plugin", "dsh-talebook-plugin", "在自托管 Talebook 书库上搜索、下载、上传和管理书籍与有声书，管理 Legado 书源及管理员操作；写入操作需经批准。", "net", 1, "tools"),
        E("dsh-testhud", "dsh-testhud", "把自动测试的进展画在被测界面之上的浮层：每步的期待与实际，以及等待的人现在能不能动鼠标键盘。包内附带通用预编译二进制（arm64 + x86_64），无需 Xcode 命令行工具；浮层面板自身要求 macOS 14 及以上。", "misc", 1, "tools"),
        E("dsh-tool-bandit-search", "dsh-tool-bandit-search", "使用上下文赌博机算法（Thompson 采样）学习何时使用快速搜索、何时使用深度搜索的 `search` 工具。", "search", 1, "tools"),
        E("dsh-tool-comfyui", "dsh-tool-comfyui", "在对话里直接调用本机或局域网的 ComfyUI 机队出图，支持工作流模板、机队健康检查与队列控制。", "session", 1, "tools"),
        E("dsh-tool-gzh-publisher", "dsh-tool-gzh-publisher", "公众号发布管线：先按发布闸门校验草稿，再推送到草稿箱。", "misc", 1, "tools"),
        E("dsh-tool-imagegen-1", "dsh-tool-imagegen", "通过 OpenRouter 统一 Image API 的文生图与图生图：以别名配置模型，参数按实时模型能力列表校验，支持参考图输入、设置卡片与对话内联展示结果。", "session", 1, "tools"),
        E("dsh-tool-router", "DSH-Tool-Router", "通过决策模型 API 把工具 schema 从模型 prefill 中隐藏，每次按需揭示一个工具。需运行决策模型 API 端点，且 PATH 中有 pnpm。", "data", 1, "tools"),
        E("dsh-tool-search-2", "dsh-tool-search", "按 agent 的按需工具发现与渐进式 schema 披露。", "data", 1, "tools"),
        E("dsh-tool-weather", "dsh-tool-weather", "面向模型的天气工具，基于公开 Open-Meteo API 查询当前天气与 7 天预报，无需 API Key。", "ai", 1, "tools"),
        E("dsh-tools", "dsh-tools", "面向 dsh web profile 的个人工具箱，各功能可单独开关：任务完成桌面通知、一键重启、会话删除、插件启停、更新检查，以及若干界面小工具。", "fileops", 1, "tools"),
        E("dsh-tuanjie-plugin", "dsh-tuanjie-plugin", "从 DeepSeek Harness 驱动团结引擎编辑器：连接已运行编辑器的 Codely 桥，创建与修改 GameObject、改组件属性、执行编辑器命令，并在编辑器进程里跑 C#。改自 opdsh/unity-plugin，适配团结引擎的 Codely 桥。", "sysinfo", 1, "tools"),
        E("dsh-unified-desktop", "dsh-unified-desktop", "把两个需自行安装的 Windows 桌面自动化后端（dsh-computer-use-win 插件 + 用 uv 装的 windows-mcp，Python 3.14）合成一个 MCP 工具面：装完还要跑一次随包的 scripts/patch-backend.mjs 改写本机 windows-mcp", "misc", 1, "tools"),
        E("dsh-universe-api", "dsh-universe-api", "面向 DeepSeek Harness 的离线确定性公共 API 目录检索，支持中英文查询，以及认证、HTTPS、CORS、状态、来源层级与分类的精确筛选。", "fileops", 1, "tools"),
        E("dsh-unreal-agentlink", "dsh-unreal-agentlink", "UnrealAgentLink 编辑器插件的桥接端：Unreal 编辑器拨入 127.0.0.1:17860 的 WebSocket 桥，agent 由此用 12 个工具驱动全部 170 个已编目命令（Actor、关卡、蓝图、材质、PCG、截图、日志、撤销）。", "image", 1, "tools"),
        E("dsh-video-remix", "dsh-video-remix", "把文案变成带配音的讲解视频：默认用文字卡片（快且准确，适合教程），也可逐段调用 AI 生成真实画面（需 AGNES_API_KEY）；内置 14 个在线中文神经音色和 3 个离线 Windows 音色，一条命令即可生成全部音色的试听包。前置需要 ffmpeg，并把仓库内的 video-remix s", "git", 1, "tools"),
        E("dsh-video-tools", "dsh-video-tools", "基于 FFmpeg.wasm 的浏览器端音视频工具集，支持抽帧、截图、图片压缩与视频转 GIF。", "image", 1, "tools"),
        E("dsh-waste-market", "dsh-waste-market", "DeepSeek Harness A 股行情面板：实时大盘指数、技术选股（13 项信号 + 多策略交叉）、7×24 多源快讯聚合、自选股分组管理、市场情绪温度计（连板梯队/涨跌家数）、K 线图（MA/EXPMA/BOLL 叠加）、板块榜/涨停池/龙虎榜。", "sysinfo", 1, "tools"),
        E("dsh-web-search-litellm", "dsh-web-search-litellm", "ctx.web 搜索提供方：通过 LiteLLM 代理走 OpenAI Responses API 调用 DeepSeek 原生服务端 web_search，复用 LITELLM_API_KEY，无需新密钥。", "net", 1, "tools"),
        E("dsh-web-search-zai", "dsh-web-search-zai", "DeepSeek Harness 的 Z.ai / 智谱网页搜索插件，支持 Coding Plan MCP 套餐额度和 REST API 余额两种计费模式，提供原生中英文设置卡片，可复用现有 ZAI_API_KEY。", "search", 1, "tools"),
        E("dsh-webdav-server", "dsh-webdav-server", "WebDAV 服务器：把一个共享目录变成 Windows/macOS/Linux 都能挂载成本地磁盘的 WebDAV 服务，令牌认证、可选只读、目录/端口/令牌全可配，设置页自带三平台挂载指南。", "net", 1, "tools"),
        E("dsh-word-vault", "dsh-word-vault", "一个或多个孩子的英语生词库，面向 DSH 0.2 及以上（0.2.0-rc.1 / 0.2.0-rc.2 实测通过，含桌面版 GUI；0.1.7 ~ 0.2.x 均可使用）。1.10 新增语音发音：记忆卡与在线答题页里，每个单词、每句例句旁都有一个 🔊，点了用 Windows 自带语音朗读——离线、", "media", 1, "tools"),
        E("dsh-your-balance", "dsh-your-balance", "新增余额查询工具，在每轮对话中注入 DeepSeek 账户余额快照与低余额省电/严重不足停机策略，并提供阈值和汇率联动换算设置页。需要已登录的 DeepSeek 账号才能读取余额，仅配置 API key 的 profile 会返回无法读取。", "fileops", 1, "tools"),
        E("dsh-zhihu", "dsh-zhihu", "为 DeepSeek Harness 提供知乎能力：包装本机 pyzhihu-cli 为 18 个 zhihu_* 工具——14 个只读（搜索/热榜/问题/回答/用户/推荐流/话题/通知/收藏夹）与 4 个发布类工具（readOnly 关闭前不注册）——并在侧栏提供 Web 面板做登录、配置与查询。", "search", 1, "tools"),
        E("dsh-zhihu-dashboard", "dsh-zhihu-dashboard", "知乎面板：热榜（带趋势标记）、关注动态（收藏/创作/关注的人）、帖子追踪（问题/关键词/关注的人，支持自动创意简报），并提供 5 个对话工具（zhihu_search / hot / answer / global_search / followees）。", "search", 1, "tools"),
        E("dsh-zspace", "dsh-zspace", "把极空间（ZSpace）NAS 变成 agent 的原生工具：列目录、查属性、按名检索、读取、下载、上传、写入、建目录、重命名、移动、复制、删除 NAS 文件。跨网络走桌面客户端中转——不需要同一局域网、不用 WebDAV、不用 SSH；同一网络时自动改走更快的 WebDAV 直连。删除需显式传 c", "net", 1, "tools"),
        E("dwg-reader", "dwg-reader-plugin-20261029", "DSH 插件：直接读取 DWG/DXF 图纸、PDF 与图片，无需安装 AutoCAD 或 Tesseract；DXF 需本机安装 Python 3 与 ezdxf。", "pdfdoc", 1, "tools"),
        E("figcraft", "figcraft", "论文图即代码：Agent 创建版本化 Figure IR，经语义化 Patch 增量修改（单节点粒度——未指定的对象绝不动），确定性导出可编辑的 SVG / PDF / PPTX 真矢量图。七个 papercanvas_* 工具覆盖创建、读取、修改、布局、Lint（FC001–FC008 质量检查）", "pdfdoc", 1, "tools"),
        E("fitmeet-dsh-plugin", "fitmeet-dsh-plugin", "通过每位用户独立的 OAuth 授权将 DeepSeek Harness 接入 FitMeet，提供找人、组局查询、提醒、个人事项、连接反馈、大厅发布与私聊的 17 个工具，写入操作保留预览与确认步骤。", "misc", 1, "tools"),
        E("isingq-dsh-plugin", "dsh-plugin", "IsingQ 原生插件：引导式 QUBO 建模与本地校验，用户确认后提交远端求解。", "git", 1, "tools"),
        E("jieyatool", "jieyaTool", "批量递归解压：魔数识别真实格式（伪装后缀/无后缀/乱序后缀）、嵌套压缩包自动解到底、多密码池+层内动态发现（\"第二层密码:xxx\"）、SFX/分卷自动配对、工具运行库目录防误递归。", "archive", 1, "tools"),
        E("kaipu-dsh-plugin-release", "plugin-wisdom", "山海·开铺 智囊团插件：配套侧边面板，展示内置谋士团队与席位状态。需与 kaipu-platform 一起安装——灯位数据由开铺插件经网关提供，单独安装会如实显示「通道未就绪」。可摘除：卸掉它，开铺仍完整可用。", "misc", 1, "tools"),
        E("kaleidosphere-dsh-plugin", "kaleidosphere-dsh-plugin", "KaleidoSphere 数据库分析插件：六个原生工具（状态/发现/分析/计划/预览/回读），针对只读的 Microsoft SQL Server 与 Oracle，默认走内置确定性 fixture，运行时随包分发、无需外部服务。", "data", 1, "tools"),
        E("market-watch", "market-watch", "dsh 的金融行情监控插件:实时报价、本地自选列表、带冷却的阈值提醒、定时轮询,以及在会话内用 ASCII/mermaid 渲染 A 股与加密货币图表(数据源腾讯 + CoinGecko)。", "codec", 1, "tools"),
        E("math-rigor", "math-rigor", "给 DeepSeek Harness 的可审计数学证明:本地 stdio MCP 服务器(23 个机器校验工具)+ 工作流技能 + /prove、/audit-proof 命令。proven / refuted / inconclusive 绝不混淆,未证明的步骤如实报告而非隐藏。需 Python", "devops", 1, "tools"),
        E("model-catalog", "model-catalog", "从 OpenAI 兼容 API 主机自动发现模型列表、定价与能力，归一化后生成 dsh 可直接使用的模型配置。", "ai", 1, "tools"),
        E("motor-hospital-plugins", "motor-case-kb", "按故障描述、功率与品牌检索历史电机维修案例，支持将新诊断沉淀回写供后续检索。", "misc", 1, "tools"),
        E("motor-hospital-plugins-1", "motor-cost-quote", "组合历史供应商报价与工时，生成现场抢修/返厂大修/绿色再制造/整机更换等维修方案，并按综合持有成本给出决策建议。", "misc", 1, "tools"),
        E("motor-hospital-plugins-2", "motor-decision-report", "将案例依据、诊断结论、维修工序、配件清单与方案对比汇总为带数据溯源的 Markdown 维修建议书。", "pdfdoc", 1, "tools"),
        E("motor-hospital-plugins-3", "motor-fault-diagnosis", "结合故障知识库症状-原因规则与相似历史案例，输出电机候选诊断排序、证据词与建议补测项。", "text", 1, "tools"),
        E("motor-hospital-plugins-4", "motor-parts-selector", "按故障类型与电机功率生成替换配件 BOM，输出库存、交期与国产/进口替代选项。", "text", 1, "tools"),
        E("nau-dsh-plugin", "dsh", "把 NewAgentUniverseByDeepSeek 节点接入 DSH：五个只读工具，覆盖版本与上游出处、数据目录恢复状态与账本审计、一致性向量、精确十进制换算，以及节点可达性探测。刻意不暴露启动/停止守护进程、存款、发总线消息这类在本项目里受审计的特权操作。", "sysinfo", 1, "tools"),
        E("net-debug", "net-debug", "为 DeepSeek Harness 打造的网络调试工具集：带 SSRF/私网防护的通用 HTTP 客户端、会话内请求历史与重放、响应检查与 HAR 导出——三个 dsh 工具外加零依赖 CLI。", "session", 1, "tools"),
        E("primesync-ai-studio", "primesync-ai-studio", "PrimeSync AI Studio 托管策略研究 MCP 服务的实验性配置包，使用官方 MCP 客户端和 mcp-remote OAuth 桥接，需具备 Studio 使用权限。OAuth 授权与工具调用尚未完成端到端验证；启动 Harness 前须在同一电脑上通过命令行手动登录，否则工具可能无", "misc", 1, "tools"),
        E("wincu", "wincu", "给 DeepSeek Harness 用的 Windows 计算机操作插件：常驻 PowerShell UIA 后端，对外只有 16 个合并入口（读取/点击/输入/观测/验证）；带加固的策略层（红线拒绝、显式审批、观测绑定、落点归属与前台焦点守卫）与一轮性能优化（后端预热、缓存、像素哈希稳定探测）。", "codec", 1, "tools"),
        E("bites-the-dsh", "bites-the-dsh", "为 DSH 原生会话加入完全只读、可脚本控制的历史回放，支持模拟用户输入、正放与倒放、逐事件移动、变速、空闲间隔压缩，以及按事件、轮次或记录时间直接跳转。", "archive", 1, "session"),
        E("ctx-handoff-sentinel", "dsh-plugin", "面向 DeepSeek Harness 的上下文交接哨兵：每次压缩后或手动 /guard check 时运行三项行为自检（约束 / 已改文件 / 下一步+验证命令），用会话日志做证据核对，给出 🟢🟡🔴 判定并可生成交接单。", "archive", 1, "session"),
        E("dhs-plugins", "dsh-session-monitor", "侧边栏徽标与面板，跨工作区聚合各会话的待处理、运行中、已完成状态，点击即可打开对应会话。", "session", 1, "session"),
        E("dsh-afk", "dsh-afk", "面向 ask_user_question 的 AFK 离开模式：当前 profile 全局或会话级设置，自定义自动应答或禁用新提问调用，基于会话日志的提问记录与已读状态；不批准权限或计划。仅支持 DSH 0.2.1-rc.2 与 0.2.1-rc.3。", "fileops", 1, "session"),
        E("dsh-agent-clean", "dsh-agent-clean", "在 DSH 完全退出后清理会话日志里的子代理条目与孤儿投影缓存，默认先试演并整份备份。", "net", 1, "session"),
        E("dsh-agent-sidecar", "plugin", "跨 agent 看板监控本机 AI agent 会话（cursor-ide、claude、codex、copilot、kimi 及 dsh 自身），提供会话时间线，并可经默认关闭的两阶段确认门注入消息。", "time", 1, "session"),
        E("dsh-ai-session-title", "dsh-ai-session-title", "用会话自己的模型从对话内容生成会话标题，可走 /ai-title 命令，也可点重命名弹窗里的按钮。提供四种标题结构（主题、动作、主题 + 结论、自定义提示词）和可选的「月-日」前缀，均可在插件设置页调整。", "fileops", 1, "session"),
        E("dsh-air", "dsh-AIR", "DSH Web 输入框增强：跨会话召回已发送提示词、用 Ctrl+R 搜索并还原富草稿，以及提供停靠式 /btw 或 /side 旁路会话。", "search", 1, "session"),
        E("dsh-archive-favorites-forge", "dsh-archive-favorites-forge", "在侧栏「…」菜单或行内星标收藏任意对话；一键复制会话 ID 与转录文件绝对路径；单条永久删除（二次确认，删完侧栏立即移除该行）。设置页新增一张卡：按可配置的小时阈值批量归档闲置会话并支持一键撤回，把候选导出为制表符分隔的 txt（含对话名称、ID、所属工作区、闲置时长、最后活动时间），以及批量删除归", "archive", 1, "session"),
        E("dsh-archive-manager-3", "dsh-archive-manager", "双 Tab 归档面板（已归档 / 活跃），每行的归档或取消归档与彻底删除并排；显示绑定的工作目录且可直接点击打开，删除后的归档记录进入待清理队列，避免已删会话重新出现在活跃列表。", "archive", 1, "session"),
        E("dsh-archived-sessions", "dsh-archived-sessions", "管理并删除已归档的 DSH 对话：设置里新增「归档会话」页，列出所有归档会话，支持单条与批量删除；侧边栏会话「…」菜单在「取消归档」旁新增红色的「删除归档会话」。删除是真正的删除（会话日志、投影缓存与两套索引一起清理），不只是取消归档。", "archive", 1, "session"),
        E("dsh-attachment-library", "dsh-attachment-library", "只读附件库：列出本机保存的所有图片和文件附件及其占用空间，以及哪些对话（包括会话回收站中的）仍在使用它们，并可在访达中显示或用预览打开。", "image", 1, "session"),
        E("dsh-auto-archive-1", "dsh-auto-archive", "按闲置天数自动归档冷会话（带运行中、驻留会话安全护栏），并提供归档会话管理面板：查看、释放、安全删除与内容预览。", "archive", 1, "session"),
        E("dsh-auto-compaction", "dsh-auto-compaction", "对本地模型友好的会话自动压缩插件：压缩时不会触发本地模型重读历史，节省大量时间；压缩触发点与压缩会话的保存内容可由用户自定义。安装后需把 Agent 预设的 compaction-basic 槽位指向 dsh-auto-compaction-engine（或在设置页保存一次切换）；在此之前仍走原生压", "archive", 1, "session"),
        E("dsh-auto-continue-1", "dsh-auto-continue", "回答因达到单次输出 token 上限被截断时自动发送\"继续\"续写，无需手动操作；面向自部署 Ollama 等小输出上限场景。", "ai", 1, "session"),
        E("dsh-branch-review", "dsh-branch-review", "为相关 DSH 会话分支记录人工决策：保留、淘汰或待跟进，并保存理由、标签与外部链接。", "git", 1, "session"),
        E("dsh-branch-tree", "dsh-branch-tree", "把会话变成左侧栏里的文件夹：可分叉出独立分支（完整复制 / 压缩记忆 / 只继承开头），并以树状浏览。", "git", 1, "session"),
        E("dsh-brief-session-title", "dsh-brief-session-title", "把 DSH 会话标题从一句话精简为不含动词的短语，目标五个词以内。", "session", 1, "session"),
        E("dsh-btw", "dsh-btw", "使用当前会话上下文进行侧边提问，支持独立流式回复与取消。", "session", 1, "session"),
        E("dsh-butler-archive", "dsh-butler-archive", "DSH 网页插件：浏览、预览、还原与删除已从会话目录搬出的归档会话。", "archive", 1, "session"),
        E("dsh-channel-view", "dsh-channel-view", "侧边栏注入的按渠道分组会话视图——工作区/Channels 双标签、运行中绿点、归档折叠与孤儿工作区标注，完全基于官方扩展面实现，兼作 RFC-0001（discussion #3897）的参考实现。", "archive", 1, "session"),
        E("dsh-chat-search", "dsh-chat-search", "DSH 对话搜索插件：支持全局跨会话与当前对话内精准搜索，高亮定位并快速跳转。", "search", 1, "session"),
        E("dsh-chat-settings", "dsh-chat-settings", "为单个对话设置系统提示词、按轮数折叠上下文、采样参数，并提供低 token 的纯聊天模式。", "session", 1, "session"),
        E("dsh-client-ui-session-mention", "dsh-client-ui-session-mention", "输入 @ 引用另一个对话：选择历史会话，将其压缩总结注入当前提示词。", "archive", 1, "session"),
        E("dsh-codex-pins", "dsh-codex-pins", "把 DeepSeek Harness 侧边栏分成可独立滚动的置顶栏和最近栏，置顶过的会话不再出现在最近列表里。", "session", 1, "session"),
        E("dsh-codex-ui-classic", "dsh-codex-ui-classic", "把 Codex UI 1.1.49 的侧边栏内置进插件，上游更新换不掉界面；提供 remote.workspaceRegistry.deleteSession 让会话菜单出现「删除会话」，放出被样式隐藏的「...」按钮，永久删除会话日志、工程记录与投影缓存，子智能体与派生对话可在家族树里逐项勾选。内", "session", 1, "session"),
        E("dsh-compact-agents", "dsh-compact-agents", "模型可调用的 compact_agents 工具：强制压缩进程内所有活会话的上下文（主会话、普通子代理、AgentTeams 成员一视同仁），忙的目标自动排队、本轮结束立即补压，逐目标回报被遮蔽的节点数与估算 token 数；浏览器侧在设置里自成一页，提供触发阈值、保留比例、受控阶段输出预算、自动续", "archive", 1, "session"),
        E("dsh-compact-manager", "dsh-compact-manager", "接管上下文压缩：手动与自动压缩都可选用模型压缩（支持备用模型兜底或直接使用备用模型），或选用机械折页——在本地把旧历史整理成摘要卡，不调用模型、不消耗 token；折页走官方压缩事务，被替换的原始事件仍以原序号留在只追加的会话日志里。代码改编自 dsh-compact-saviour、折页算法取自", "archive", 1, "session"),
        E("dsh-compact-selected-model", "dsh-compact-selected-model", "/compact 与自动压缩使用会话中当前选中的模型来生成摘要，而不是用跑完上一轮的那个模型。", "archive", 1, "session"),
        E("dsh-connection-card-host", "dsh-connection-card-host", "把两个 DSH 会话之间的「连接」做成一等对象：从输入框锚点或会话行拖拽建连，两个方向各自设权限，并可在连接上装载卡片。两端各获得五个宿主工具，用于按指定紧急度传话、读取对端工作状态、共用公约盒；感知为拉取式，空闲连接不占上下文。", "session", 1, "session"),
        E("dsh-context-compressor", "dsh-context-compressor", "dsh 网页端一键上下文压缩：会话标题栏「压缩」按钮把整段对话总结成几句话，新建同工作区会话以摘要为第一条消息并自动切换，原会话原样保留。", "archive", 1, "session"),
        E("dsh-context-maid", "dsh-context-maid", "自动上下文策展：tool 输出内容感知瘦身、无效日志清理、用户要求与进行中工作钉扎保护、先归档后压缩，全程审计留痕。", "archive", 1, "session"),
        E("dsh-context-ops", "dsh-context-ops", "新增交接、上下文决策、上下文诊断三个技能，自带 context_pressure/context_history 工具（峰值 token、压缩复盘），支持按线路实测窗口 realWindows（含 windowSource 证据）、routeKey 直出与 handoffAt 强制交接线，附斜杠命令", "archive", 1, "session"),
        E("dsh-context-proxy", "dsh-context-proxy", "按需取回薄层：context_query / context_slice / context_grep 三个工具读取已持久化的历史，引用可回放。", "misc", 1, "session"),
        E("dsh-continue-guard", "dsh-continue-guard", "在输入框停靠区加一个「继续」按钮，并在某一轮被断网或上游输出超限截断时自动续跑。常驻的链路监测每 10 秒问一次网络是否回来（链路恢复本身不发任何事件），而一个正常跑完的回合会被当作链路可用的证据。点击走宿主真实的提交链路（beginSubmission + session.prompt），消息带的", "git", 1, "session"),
        E("dsh-conversation-exporter", "dsh-conversation-exporter", "将当前 DSH 对话或选定轮次导出为干净、易读的 Markdown。", "pdfdoc", 1, "session"),
        E("dsh-conversation-recycle-bin", "dsh-conversation-recycle-bin", "在会话列表菜单或会话页头部删除对话，可勾选一并删除该对话关联的记忆节点（确认框先显示命中条数）；删除进入插件回收站可恢复，每次操作写入审计日志，批量删除有限流与逐会话回滚。", "session", 1, "session"),
        E("dsh-cross-session-agent-pre", "dsh-cross-session-agent-pre", "支持 DSH 跨工作区消息与发送方导航、同工作区受限上下文，以及可选的本机 Claude Code 双向通信。", "session", 1, "session"),
        E("dsh-darwin-sentinel", "sentinel", "会话体检：基于官方 session-query 接缝，机械挖掘会话日志为结构化问题工单（重试环/工具错误簇/中断回合/Token 浪费）；可独立安装使用。", "session", 1, "session"),
        E("dsh-deephub-share", "dsh-deephub-share", "将一条 dsh 会话提炼为脱敏后的思路，端到端加密投递给 DeepHub 上的朋友；收到的思路落为一条新会话。", "codec", 1, "session"),
        E("dsh-drag-graft", "dsh-drag-graft", "Codex 同款拖拽引用对话：把侧栏的会话行拖到对话区，它就变成输入框里一枚原生会话引用 chip，可以继续打字再发送。拖侧栏的工作区（文件夹）行，则把那个文件夹的路径插进草稿，整个目录一起交给模型。候选按 session id 匹配而不是按标题，标题重名或为空都不会插错对话。引用条数由宿主决定（原", "fileops", 1, "session"),
        E("dsh-faster-compress", "dsh-faster-compress", "在后台准备上下文摘要并于安全步骤应用，保留原生压缩回退，并提供摘要内容、应用状态、耗时与用量的会话压缩历史。", "archive", 1, "session"),
        E("dsh-file-history", "dsh-file-history", "按轮次给整个工作区留检查点：每轮结束存一份快照，本轮改了哪些文件直接列在聊天里那一条下方，任意一轮都能还原——只还原文件、只还原对话，或者全部还原。捕获靠扫描整棵树，而不是挂钩 write/edit 工具，所以 shell 命令、外部编辑器、git 操作改出来的东西同样留痕。还原对话是从那一轮分叉出", "git", 1, "session"),
        E("dsh-forget-session", "dsh-forget-session", "在会话行菜单加入「遗忘会话」（菜单内二次点击确认），把会话从侧栏与磁盘彻底移除：先停掉正在运行的工作，经官方通道解除工作区、归档与置顶记录，删除日志目录与投影缓存条目，并由复活守卫在一个窗口内补删迟到写入或句柄残留重建的文件；灵枢记忆、附件与其他会话不受影响。", "archive", 1, "session"),
        E("dsh-fork-diff", "dsh-fork-diff", "只读并排比较相关 DeepSeek Harness 会话历史，展示消息、工具调用、回答、耗时和 usage 差异。", "text", 1, "session"),
        E("dsh-fork-graph", "dsh-fork-graph", "会话标题栏内联的 Git 风格 fork 血缘图：用彩色轨道与分叉曲线显示会话从何处分支，并可点击跳转。", "git", 1, "session"),
        E("dsh-graft", "dsh-graft", "移植、转发与分叉 DSH 会话:读取会话日志切片并导出,在回合边界分叉会话,或将选中部分作为独立 graft 消息转发到另一会话(可为全新会话)。", "session", 1, "session"),
        E("dsh-hermes-session", "dsh-hermes-session", "只读读取本机 Hermes Agent 的会话库，把会话导入当前会话作为有界、不可信的背景上下文：输入框按钮可搜索全部 profile 的会话，另有 hermes_sessions_list 与 hermes_session_import 两个工具。", "fileops", 1, "session"),
        E("dsh-highlightpin", "dsh-highlightpin", "把已定稿的用户或助手消息里划选的一段原文钉住，让它在上下文压缩后仍留在模型输入中：每枚钉子默认按需补回，也可改为 resident（中性常驻系统提示词）或 highlight（强调常驻）。选区会以 source-exact、source-normalized 或 rendered 三级保真对回源文本", "archive", 1, "session"),
        E("dsh-if", "dsh-if", "为 DSH 增加 /if 斜杠命令：第一行是条件，其余行是指令。由继承当前会话工具、system prompt 与消息历史的 fork 子代理判断条件并回答 YES 或 NO，只有 YES 才把指令作为一条普通用户消息发给主 agent，NO 则什么都不发送；条件、判断用的 prompt 与判断结果", "net", 1, "session"),
        E("dsh-input-rewriter", "dsh-input-rewriter", "你只管正常打字，停下约两秒，它就把你刚写的话改写成更清晰、以第一人称表达的版本，更容易得到好答案；贴进来的代码、网址、长文原样不动，缺的信息用占位符标出而不乱猜，一次问几件事也一件不漏、排好顺序。", "misc", 1, "session"),
        E("dsh-intercom", "dsh-intercom", "给已经开着的窗口装内线电话，不建团队、不生新会话，只让平级窗口互相递话（带跳数上限防环）。", "session", 1, "session"),
        E("dsh-lang-zh", "dsh-lang-zh", "向系统提示注入固定语言指令，让 Agent 始终用简体中文回复（含工具调用之间的叙述文字），除非你明确要求其他语言；对所有会话与预设生效，且不覆盖 persona。", "session", 1, "session"),
        E("dsh-loop-recover", "dsh-loop-recover", "模型死循环防护：自动检测并拦截重复输出，停止循环后恢复任务继续执行，无需重启或手动拉起；支持配置故障中断策略与救援参数。", "ai", 1, "session"),
        E("dsh-ma-plugins", "dsh-handoff", "脱敏会话交接，支持审阅、立即启动和仅生成简报。", "session", 1, "session"),
        E("dsh-manage-session", "dsh-manage-session", "DSH 会话管理台（原名会话管家）：一屏管理活跃与归档会话——按工作区分组、检索域与标题筛选、收藏，批量归档 / 取消归档 / 清理归档文件（不可逆需二次确认），外加四门会话体检（日志完整性 / 投影缓存 / 无损 JSON / 冷读），给出可逆、先备份的处方。搜索与索引在 dsh-search-i", "data", 1, "session"),
        E("dsh-manage-sessions", "dsh-manage-sessions", "侧栏原生增强的会话管理：批量归档/恢复/永久删除，卡死会话两段式强停（自动复活/离线），工作区行一键复制绝对路径。", "archive", 1, "session"),
        E("dsh-message-branch", "dsh-message-branch", "原位编辑纯文本用户提问，并在新的 DSH 会话分支中重新发送。", "git", 1, "session"),
        E("dsh-minimal-first-turn", "dsh-minimal-first-turn", "Web 根会话的首轮精简：先使用持久 bash 与 str_replace_editor，移除自动工作区和技能上下文；首次工具调用或回复后恢复所选预设，带持久 composer 开关。", "session", 1, "session"),
        E("dsh-minimal-session-delete", "dsh-minimal-session-delete", "从侧边栏永久删除会话：等待正在运行的回合停下，并级联删除其子代理会话。", "net", 1, "session"),
        E("dsh-multi-session", "dsh-multi-session", "多会话一体：在一个会话内按工作区总览全部会话的实时状态，钉住最多三个并排看对话正文，可直接发消息或打断，不用来回切换。", "session", 1, "session"),
        E("dsh-nightwatch", "dsh-nightwatch", "把这个会话一直续跑到指定钟点：输入框里一颗按钮选 22:30、+90m 或明天 07:00，之后每轮答完插件补一句继续，让你去睡觉时它接着干；到点之后不再发任何消息。另有三道提前收手的闸——轮次上限 400、连续 3 轮出错、连续 4 轮一个工具都没调；随时可以手动停。快到点时切成收尾语气，窗口最多", "session", 1, "session"),
        E("dsh-nutstore-backup", "dsh-nutstore-backup", "把 DeepSeek Harness 的会话记录、插件配置与工作区记忆通过 WebDAV 增量备份到坚果云，支持连接测试与在新机器上一键恢复。", "session", 1, "session"),
        E("dsh-parallel-sessions", "dsh-parallel-sessions", "DeepSeek Harness 并行会话协调：列出并行会话、在会话之间转发带发起方归属的消息，并在任务阶段冲突时暂停或恢复另一个会话。", "session", 1, "session"),
        E("dsh-per-session-folder", "dsh-per-session-folder", "为默认工作区中的每个新会话创建独立文件夹，并根据会话标题重命名。", "fileops", 1, "session"),
        E("dsh-pin-sessions", "dsh-pin-sessions", "把会话置顶到 Web 侧边栏顶部：独立置顶面板、归档区、原生三点菜单集成。", "archive", 1, "session"),
        E("dsh-pinned-sessions", "dsh-pinned-sessions", "把运行中、跑完未点开和当前打开的会话固定在 DSH Web 侧栏工作区分组上方，并可从任意会话/工作区的「...」菜单里全局置顶。", "session", 1, "session"),
        E("dsh-plugin-background-compaction", "dsh-plugin-background-compaction", "作为会话压缩引擎注册，后台预计算压缩摘要，压力压缩触发时直接提交已持有的结果，省去前台模型往返。锁定已摘要的区间以保证提交时载荷指纹仍然匹配，提交前先裁剪工具结果；载荷漂移或上下文溢出时回退到原生前台路径。", "git", 1, "session"),
        E("dsh-plugin-canvas", "dsh-plugin-canvas", "无限会话画布，区域绑定工作区与智能体预设，可钉住会话卡片、放置便签，带对齐参考线。", "session", 1, "session"),
        E("dsh-plugin-session-delete-1", "DSH-Plugin-Session-Delete", "在 DeepSeek Harness 界面里彻底删除会话：会话头部垃圾桶按钮与侧栏「…」菜单项（带风险确认弹窗），另提供 workbench_session_delete agent 工具。从 lsz-asd/dsh-plugin-session-delete 派生并自 v0.4.0 起独立维护；请", "session", 1, "session"),
        E("dsh-plugin-session-purge", "plugin", "永久删除 DSH 会话（而非仅归档），级联清理它的日志目录、投影缓存、工作区记账与子会话（子代理）。提供设置页面板：按工作区分组，显示体积、时间与「打开中 / 已归档 / 子会话 N / 无工作区」标记，支持筛选与批量删除，每条删除都在行下方内联二次确认。", "archive", 1, "session"),
        E("dsh-plugin-session-purge-1", "dsh-plugin-session-purge", "两步删除会话：会话菜单先把会话移入回收站（不删任何内容、可随时恢复），面板可恢复、可逐条立刻删除、也可整体清空，下次启动 DSH 时才真正清掉日志、投影缓存、spill 文件与工作区登记。", "fileops", 1, "session"),
        E("dsh-plugin-session-trash", "dsh-plugin-session-trash", "会话回收站：移入回收站、恢复或永久删除会话。", "session", 1, "session"),
        E("dsh-plugin-sessiongraph", "dsh-plugin-sessiongraph", "本机全部会话的全文检索：sessiongraph 跨工作区查找对话，中文两字词也能命中，sessiongraph_index 负责建索引。", "session", 1, "session"),
        E("dsh-plugin-sessivra", "dsh-sessivra", "Sessivra：DSH 会话通信与任务协作，支持共享问题和裁决、自动回传结果、关联回复、验收后放行、上下文引用与会话树。npm 包名 dsh-plugin-sessivra。", "session", 1, "session"),
        E("dsh-plugins-loulan", "dsh-loulan-rules", "在首次 agent pre-step 读取 $DSH_HOME/rules 与 <cwd>/.dsh/rules 下的规则文件并注入会话，被 compaction 遮蔽后自动补回。", "fileops", 1, "session"),
        E("dsh-prompt-bar", "dsh-prompt-bar", "把当前会话的第一条提问常驻在对话区上方，滚动也不消失：一键复制，面板列出本会话发过的全部提问（点某一行直接跳到那条消息，够不着会自动往前翻页），另有十套外观可在面板里即选即换（含四套亮色）。", "session", 1, "session"),
        E("dsh-prompt-booster", "dsh-prompt-booster", "输入框提示词提升。左键点击输入框按钮，草稿被轻度润色后直接替换（可撤销、不弹窗）；右键打开模式菜单：8 个内置模式加自定义模式，每个模式的模板可编辑、可新增（保存在宿主端），并可从 dsh 当前可用的模型列表中选择改写所用的模型；其他模式先显示前后对比预览。基于 rongxingda/dsh-pro", "text", 1, "session"),
        E("dsh-query-jump", "dsh-query-jump", "DSH WebUI 会话提问导航：对话区右缘淡色短横线，悬停列出真实用户提问，点击跳回对应气泡。", "session", 1, "session"),
        E("dsh-recall-sessions", "dsh-recall-sessions", "轻量级解压并读取历史会话，让新会话读取之前会话的内容，单次操作毫秒级。`/recall` 列出当前项目的历史会话（标题、最后活动时间、轮次、首问）；`/recall <序号>` 读回该会话的轮次内容；`/recall all` 覆盖所有项目；也可用自然语言让模型调用 `recall_sessions", "archive", 1, "session"),
        E("dsh-recovery-resume", "dsh-recovery-resume", "DSH 重启后自动续跑被中断的回合：在会话激活后读取崩溃修复写入的 turn/end，投出要求先核对真实状态（不假定外部操作成功或失败）的续跑消息；永久性失败（认证、配额、上下文超限）直接跳过，并有跨重启次数预算、自适应退避与最小上下文注入。", "session", 1, "session"),
        E("dsh-reedit", "dsh-reedit", "双击自己发送的消息即可修改，并从该处开一条新分支继续。", "git", 1, "session"),
        E("dsh-resend-editor", "dsh-resend-editor", "在消息位置编辑已发消息并以 fork 出的新聊天重发，原聊天保留：改文字、删图、调整图片顺序、补图片或文件，发送前按会话图片限制校验（第一条消息在同一工作区新开聊天）。另外支持输入 @ 按文件名引用待发送图片、拖动调整输入框附件顺序、复制消息时连图片一起复制，以及对话图片的复制、下载和拖进输入框。", "image", 1, "session"),
        E("dsh-resume-on-restart", "dsh-resume-on-restart", "检测 DSH 服务重启后自动唤醒主 agent：对比上次运行时间、人性化播报中断时长，并把提示消息投递回来让中断的工作自动恢复。仅依赖 cordis ctx 服务，兼容 DSH Desktop 打包环境。", "archive", 1, "session"),
        E("dsh-revert", "dsh-revert", "现代化对话回退与重试插件：纯 UI 图形化交互、原地 Prompt 微调、支持工作区与外部文件双引擎安全快照同步，完美解决分支重放断代问题。", "git", 1, "session"),
        E("dsh-revive", "dsh-revive", "DSH 会话回放视图：按轮重放一次会话，用户输入与助手正文保持阅读速度，思考与工具输出高速掠过且每段最多 3.5 秒，每条输入后停顿一秒；可一键把原始请求复刻到一个新会话，也可边回放边录制，把回放录屏导出成 WebM 视频（画布 1280×720，无需系统录屏权限）。", "media", 1, "session"),
        E("dsh-rice-on-a-stick", "dsh-rice-on-a-stick", "白饭钓竿：把控制 DeepSeek Harness（dsh）的能力通过 MCP（Streamable HTTP）与 dsh 原生工具暴露出去， 可配置允许使用的模型清单。可通过带审计的通用桥调用宿主长尾端点。默认只监听 127.0.0.1，可选访问令牌。", "ai", 1, "session"),
        E("dsh-role-prompts", "dsh-role-prompts", "在 DSH 输入框里用岗位角色约束整个会话：在输入框开头键入 - 选一个角色，它会以引用 chip 的形式落在草稿里，随后作为 system prompt 的一部分在这一会话的每一轮注入，指令持续生效且不会出现在对话记录中。角色在设置页新增和编辑，保存在 ~/.dsh/dsh-role-prompt", "session", 1, "session"),
        E("dsh-rolehub-bridge", "dsh-rolehub-bridge", "发现并校验可移植的 RoleHub 角色，固定其精确 bundle，再将提示词和随角色打包的 Skills 加载到独立、可续聊的 DSH Session，以 Host 批准的工具绑定限制能力，并可选接入 Agent Team Room。", "archive", 1, "session"),
        E("dsh-session-archive-delete", "dsh-session-archive-delete", "给 DSH 会话「···」菜单加「备份删除」与「彻底删除」两个入口：这是一个安全的会话删除工具（session-delete），删除会话前先把会话目录、投影缓存和元数据快照复制到本地归档文件夹并逐文件校验，通过后再删除原件以释放磁盘空间；派生的子代理会话一并处理，每个备份文件夹都带 RESTORE.", "archive", 1, "session"),
        E("dsh-session-board", "dsh-session-board", "会话看板：悬浮球一览所有工作区会话，实时显示思考与工具进展、任务耗时、上下文用量，支持近 12h/30 天用量统计，点击直达会话。", "text", 1, "session"),
        E("dsh-session-bridge", "dsh-session-bridge", "在 agent 里枚举、读取、发送并实时跟随本机 DeepSeek Harness 会话：四个工具（session_list、session_read、session_send、session_chat）加同功能 Python CLI，走桌面 App 本地 RPC，离线也能读转录。需要 Python", "session", 1, "session"),
        E("dsh-session-categories-1", "dsh-session-categories", "工作区内会话分类，支持拖拽排序、分组折叠、任务状态提示及路径添加工作区。", "fileops", 1, "session"),
        E("dsh-session-chat-share", "dsh-session-chat-share", "将选中的聊天片段分享为 Markdown、HTML、TXT 或 PNG；提供 Session Header 弹窗（范围或多选、脱敏、工具调用、子代理对话）与 /share 命令。", "pdfdoc", 1, "session"),
        E("dsh-session-clock", "dsh-session-clock", "给指定会话授时，并给出「距上次对话过去多久」。补上宿主时间上下文只算「距上一条消息」、无法按会话开关的缺口。", "time", 1, "session"),
        E("dsh-session-conductor", "dsh-session-conductor", "DSH 会话管理增强：归档/恢复、批量与条件删除、AI 自动重命名、中断自动续跑、按工作区分组、撤回最后一条消息、三类损坏日志修复（seq-gap/EIO/双格式）、价值分析与全文搜索——另含方案/收尾模板注入（系统提示词 + 上下文）。", "archive", 1, "session"),
        E("dsh-session-control", "dsh-session-control", "DSH 侧边栏会话管理：固定对话、搜索内容、读取归档记录并隐藏噪音。", "archive", 1, "session"),
        E("dsh-session-copy", "dsh-session-copy", "在会话标题栏添加一个复制按钮，可复制会话深度链接、整段对话 Markdown、勾选的部分消息（QQ/微信式多选）或工作目录。", "pdfdoc", 1, "session"),
        E("dsh-session-delete-10", "dsh-session-delete", "在会话列表菜单里加删除与批量删除：会话移入 Windows 回收站而不是永久删除，删除前先列出该会话产出过哪些文件，由你决定是否一并清理。", "fileops", 1, "session"),
        E("dsh-session-delete-13", "dsh-session-delete", "在原生会话操作菜单中加入「删除」，并提供支持搜索、排序、工作区分组、消息预览、批量恢复与按工作区彻底清除的会话回收站；活跃会话受到保护。", "text", 1, "session"),
        E("dsh-session-delete-14", "dsh-session-delete", "在 DSH 侧栏会话菜单中加入一键「删除会话」：把会话日志与该对话的 .dsh-sessions 产出目录移入 Windows 回收站，没有确认弹窗。", "fileops", 1, "session"),
        E("dsh-session-delete-4", "dsh-session-delete", "给侧边栏每个会话的\"…\"菜单加上\"删除会话\"（官方只有归档/置顶/重命名/分叉，无持久 删除）。一键「强制删除」：逐出宿主内存态会话、停止后台工作后，彻底清除会话日志、 投影缓存与注册表记账，已连接的桌面 Web 端即时清行、不留幽灵。会话生成的工作区文件 保留，对话记录永久删除；第三方云端镜像（如", "archive", 1, "session"),
        E("dsh-session-delete-9", "dsh-session-delete", "DSH 会话管理：可归档或删除单个会话，工作区行可归档全部、恢复已归档或删除全部会话，设置页可查看/恢复/删除已归档会话；归档时备份工作区信息，恢复时自动恢复原工作区，原工作区被删除时自动重建。", "archive", 1, "session"),
        E("dsh-session-finder", "dsh-session-finder", "跨会话搜索 DSH 聊天记录并直接跳到命中的那条消息：多关键词同时匹配，可限定当前会话、全部会话或某个项目，工具命中按 callId 精确定位，浮层可拖拽并支持上一处、下一处。", "search", 1, "session"),
        E("dsh-session-fork-tree", "dsh-session-fork-tree", "DSH 会话分叉树排列功能：分叉会话缩进排在父会话下方并绘制圆角连接线，有分叉的会话名字右侧带绿色“+”，默认收起、逐层展开，悬停子会话时祖先链高亮。", "session", 1, "session"),
        E("dsh-session-handoff-1", "dsh-session-handoff", "会话工作移交：会话行菜单一键移交，新会话按八节交接包复刻老会话的记忆、任务与铁律，原始上下文经按需回读保持轻量。", "session", 1, "session"),
        E("dsh-session-manager-6", "dsh-session-manager", "在设置页管理已归档会话：恢复或彻底删除（直接物理删除，无备份层）。会话菜单新增红色彻底删除项，附三个 agent 工具。已打开的会话也能立即删除，残留内存副本以归档墓碑隐藏、重启后自动清理。", "archive", 1, "session"),
        E("dsh-session-md-export", "dsh-session-md-export", "把当前会话导出为可读的 Markdown 文件，只保留对话正文：用户消息、助手文本与 ask_user_question 问答，通过会话标题栏按钮或 /md 命令触发。", "pdfdoc", 1, "session"),
        E("dsh-session-mirror", "dsh-session-mirror", "按会话逐个备份 DSH 对话：增量镜像、模糊匹配恢复（先预览再确认）、按规则清理并先进回收站留 7 天。", "session", 1, "session"),
        E("dsh-session-recovery", "dsh-session-recovery", "从原始磁盘恢复被删除或损坏的 dsh 会话（session.jsonl.zstd）与记忆库（memory.db），并通过 web 界面中的 /session-repair 命令修复重建后无法续接的会话。", "data", 1, "session"),
        E("dsh-session-recycler-1", "dsh-session-recycler", "面向 Windows 的 DSH 会话两段式删除：对话移入回收站、可恢复回侧栏原位置；两段确认式删除，防止误删文件，连带整条子代理树、侧栏账本、投影缓存、日志与专属附件。同时能扫出一条对话真正写过的文件，增加文件查询功能，点击后将路径信息粘贴到对话中，通过Agent来判断哪些文件可以删除；在资源管理", "net", 1, "session"),
        E("dsh-session-rescue", "dsh-session-rescue", "回合异常收尾时的自动补救：瞬时失败后续跑、输出截断后继续、待办未完成时重跑，另有一层请求级 429 兜底，以及带「改后重发 / 手动重试 / 停止并重问」的客户端停靠栏。", "misc", 1, "session"),
        E("dsh-session-resume", "session-resume", "为进程退出或重启导致中断的任务提供继续按钮。", "sysinfo", 1, "session"),
        E("dsh-session-rewind", "dsh-session-rewind", "就地回退已完成的回合：点你自己消息旁的按钮即可把这条消息及之后的内容从模型上下文中撤回，原文回到输入框可直接改完重发，并可一并恢复该回合经 DSH 文件系统服务改动过的文件。", "fileops", 1, "session"),
        E("dsh-session-search-bar", "dsh-session-search-bar", "对话页顶部常驻搜索栏：按关键词搜索历史会话的消息正文，点击结果直接打开会话并定位到命中的那段文字。", "search", 1, "session"),
        E("dsh-session-shield", "dsh-session-shield", "让会话日志永远不会因为一次畸形 tool call 而打不开：坏调用自动修复，正常调用原样通过，历史永远可加载。", "session", 1, "session"),
        E("dsh-session-tags", "dsh-session-tags", "为会话添加标签，并在 Web 设置面板中按标签搜索会话。", "search", 1, "session"),
        E("dsh-session-telecom", "dsh-session-telecom", "复制会话 ID、向在线或已保存的会话发送消息，并查看会话 token 用量。", "session", 1, "session"),
        E("dsh-session-title-live", "dsh-session-title-live", "DSH 会话标题实时生成器：每条用户消息后重新生成标题，在字节预算内概括最近几条消息。", "session", 1, "session"),
        E("dsh-session-title-regen", "dsh-session-title-regen", "根据会话最近 10 轮用户 prompt，用该会话最近一次使用的模型重新生成标题，预览确认后写回。", "session", 1, "session"),
        E("dsh-session-title-stamp", "dsh-session-title-stamp", "把 DSH 会话标题固定为「日期 | 分类 | 名称」，支持回答后自动重算、设置页，以及悬停查看耗时/估算成本/token。", "time", 1, "session"),
        E("dsh-session-toolkit-1", "dsh-session-toolkit", "在会话头部添加按钮，可把已开始的会话迁移到另一个工作区，或切换已开始会话的 Agent 预设。", "session", 1, "session"),
        E("dsh-session-trash-1", "dsh-session-trash", "会话回收站：把对话移到回收站而不是直接删除，可以恢复，或再次确认后永久删除；本次启动中打开过的会话先隐藏，下次启动时再移入。", "session", 1, "session"),
        E("dsh-session-unarchive", "dsh-session-unarchive", "从 Web GUI 侧栏查看已归档会话，并一键恢复到原工作区。", "archive", 1, "session"),
        E("dsh-side-session", "dsh-side-session", "主会话进行中也能一键新开独立的可续聊旁会话：从输入框 ＋ 命令菜单选 side-chat 即开即用，主会话不受影响。", "session", 1, "session"),
        E("dsh-sideband", "dsh-sideband", "无需等待或打断正在工作的 Agent：即时冻结有界 Session 快照，由隔离且无工具的 LLM 异步总结，再将带来源信息的上下文胶囊投递到另一 Session 或已授权 Room；对 Session 默认 quiet，也可显式 wakeup。", "session", 1, "session"),
        E("dsh-smart-namer", "dsh-smart-namer", "会话与工作区的智能命名：点一下让模型基于条目自身内容给出短名候选，选中即改名。", "session", 1, "session"),
        E("dsh-sqy-rewind", "dsh-sqy-rewind", "在你自己的消息下方、与「复制」并排的回退按钮，把会话退回该轮发起之前——模型可见历史就地遮蔽，界面同步隐藏被回退的轮次，不改 DSH 本体源码、不删原始日志。", "session", 1, "session"),
        E("dsh-talk-map", "dsh-talk-map", "会话地图：每个对话都是白板上的一张卡片——工作区是会自动折叠溢出的框，点开是抽屉；卡片位置摆好就不会被打乱；卡片之间的连线承载上下文（拉一条就能带摘要分叉），每张卡还有运行中 / 等你回复 / 待查看 / 已中断的状态灯。", "session", 1, "session"),
        E("dsh-task-shelf", "dsh-task-shelf", "整理任务资料，支持跨工作区的会话交接。", "fileops", 1, "session"),
        E("dsh-temptask", "dsh-temptask", "DeepSeek Harness 的临时任务模式：一键创建一次性的时间戳工作区并开会话，直接成为侧边栏原生工作区节点。", "time", 1, "session"),
        E("dsh-time-context", "dsh-time-context", "为每次请求注入精确的本地当前时间，以及上一条用户消息的时间、日期关系与间隔；并提供 /time 命令查看注入内容。", "time", 1, "session"),
        E("dsh-todo-continuity", "dsh-todo-continuity", "让没做完的任务清单跨回合保留。DSH 在每个回合开始时清空 todos 投影，指望模型重写整份清单，于是回合一旦被中断，计划虽然durable 地留在会话日志里，界面上却永久消失——而 todo_write 只写不读，用户和模型都拿不回来。本插件只注册一个普通的 session/event 监听器，", "session", 1, "session"),
        E("dsh-tool-call-guard", "dsh-tool-call-guard", "在 wire 层中性化 arguments 为非法 JSON 的 tool call，避免一次模型畸形输出让 session 在严格 OpenAI 兼容服务端上永久 400。", "data", 1, "session"),
