        E("dsh-turnscope", "dsh-turnscope", "逐轮次文件变更与逐文件差异、确定性安全结论，外加 preview-first 安全回退：预览不写盘，确认后才应用，工作区在预览后发生漂移则直接拒绝。", "fileops", 1, "session"),
        E("dsh-undo-plugin-1", "dsh-undo-plugin", "回退会话回合和文件检查点，并在同一历史截点恢复任务与证据。", "fileops", 1, "session"),
        E("dsh-web-search-session", "dsh-web-search-session", "让 DSH 网页搜索改走当前会话模型加自建检索后端。", "search", 1, "session"),
        E("dsh-web-share", "dsh-web-share", "只读取回 chat.deepseek.com 的对话并交给新会话：生成交接包（所选轮次逐字保留、更早轮次每轮压缩为一行），预填进输入框但不自动发送。发布包仅支持 Windows（package.json os=win32）；需要本机 Edge 或 Chrome，并先在插件里登录一次 chat.dee", "data", 1, "session"),
        E("dsh-whale-companion", "dsh-whale-companion", "接近上下文上限时自动创建新 Web 会话并只转移最后一个完整回合，同时提供可编辑的追加式鲸鱼娘人格与按需重读工具。", "session", 1, "session"),
        E("dsh-whats-up", "dsh-whats-up", "What's up · 在忙啥——零维护的会话动态看板:host 端扫描全部会话,为每个会话提取「目标 + 一句话现状」(多 provider LLM、按指纹缓存),自动发现做到一半、问了没回、近期在推进的事,点卡片一键跳回会话。", "session", 1, "session"),
        E("dsh-wm-toolkit", "dsh-wm-toolkit", "一个插件做会话与消息手术：撤回或编辑指令/回复（连思考过程一起改）、用原提问重新生成、按模型上下文级删除任意一条，以及会话归档、删除、跨工作区移动与工作区迁移。面向 DSH 0.1.5 / 0.2.x，已在 0.2.1-rc.3 实测。由三个 MIT 插件分叉合并而成（Jipcon/DSH-plug", "archive", 1, "session"),
        E("dsh-workspace-cleaner", "dsh-workspace-cleaner", "在设置页列出所有工作区及其对话，勾选后按勾选内容删除对话或整个工作区，并一并清理对应的会话日志、投影缓存与工作区注册。", "session", 1, "session"),
        E("dsh-workspace-drag", "dsh-workspace-drag", "把侧边栏中的对话拖到任意工作区分组，即可在 DSH 工作区之间迁移该对话，同步更新其 cwd、磁盘位置与工作区注册表归属。", "sysinfo", 1, "session"),
        E("dsh-workspace-heal", "dsh-workspace-heal", "有会话绑定的工作区目录被删时自动重建；并把失去归属的会话折叠成摘要，供新会话导入。", "fileops", 1, "session"),
        E("dsh-workspace-settings", "workspace-settings", "按工作区保存 DeepSeek Harness 的会话默认值：模式、权限预设、模型、推理强度、Chat 工作步骤展示与收起时机；在该工作区新建或复用的空白会话自动应用这些值。", "session", 1, "session"),
        E("dsh-workspace-tree", "dsh-workspace-tree", "DSH 侧边栏虚拟会话分类树、点击式移动菜单与任务状态胶囊。", "session", 1, "session"),
        E("keep-reminder", "keep-reminder", "把会话工作目录下 .keep-reminder 文件的内容作为 system-reminder 注入，支持三种模式：每会话一次、每轮第一步、每次请求。", "fileops", 1, "session"),
        E("lazynoobscockloft", "dsh-session-notes", "会话备注 0.3.1：一个会话挂多条备注（1 2 3 按创建顺序编号），会话级颜色+置顶（弹窗标题行一键操作），复制挑选器（多条备注点哪条复制哪条），🗑 会话备注批量清理，兼容 DSH Desktop 0.8.2。", "session", 1, "session"),
        E("llmagentchatroom", "LLMAgentChatRoom", "自托管聊天室：主人与编码 agent 共用一个房间。插件在服务未运行时启动本地 Node 服务（SQLite、REST、SSE），侧边栏入口在面板中打开房间界面，五个工具（room_join、room_send、room_read、room_status、room_leave）把收到的消息以标注发送", "codec", 1, "session"),
        E("oil-dsh-title", "oil-dsh-title", "在用户消息后为 DeepSeek Harness 维护稳定的 emoji 会话标题，不向原会话追加命名消息。", "session", 1, "session"),
