        E("session-reader", "session-reader", "通过 1session 命令行或 DSH Web 历史浏览器搜索和读取 Claude Code、Codex、Antigravity、Grok 与 DSH 的本地编程会话。", "search", 1, "session"),
        E("smart-compaction", "smart-compaction", "让模型自己挑安全时机触发压缩：提供 compact_now 工具（回合进行中也能用），另有 context_status 工具，按会话真实的上下文窗口报告 token 占用。", "archive", 1, "session"),
        E("deepseek-harness-trae", "deepseek-harness-trae", "仅凭一个个人访问令牌（PAT）把 Trae 企业版模型接入 DeepSeek Harness，直连 llm_raw_chat，不需要 trae2api 或 traecli 进程；启动时从上游拉取模型目录，并显示个人额度包与企业席位的剩余额度。", "sysinfo", 1, "model"),
        E("dsh-advisor-group", "dsh-advisor-group", "主模型在专业/长尾/高风险或不确定问题上召集多个专家顾问模型，以复古 CRT 聊天组卡片展示：一次 ask_advisors 自动跑满自动深挖流水线（驱动模型追问、顾问接力、综合结论），真流式 SSE、26 个供应商预设、可配置每日配额、停止/继续，以及可选的顾问工具调用。", "ai", 1, "model"),
        E("dsh-agent-lang", "dsh-agent-lang", "模型产出文本的三个语言通道——工具调用描述（所有工具调用卡片标题，含 PTC 类预设的 run_code）、思考与回复——各自可跟随网页界面语言、强制指定语言或关闭（默认仅描述通道跟随界面语言）。host 侧注入一条全局 runtime-context 提示指示，client 半上报界面语言，设置里", "ai", 1, "model"),
        E("dsh-apply-model-all", "dsh-apply-model-all", "在输入框模型位旁边加一个控件，一键把当前会话的模型应用到其余所有会话。", "session", 1, "model"),
        E("dsh-auto-model-routing", "dsh-auto-model-routing", "通过 Jev 调整主会话推理投入而不换模型，为 fresh 子任务独立选择并应用能力与投入，展示决策分布并收集逐回复资源分配反馈。", "session", 1, "model"),
        E("dsh-autotier", "dsh-autotier", "自动模型档位路由：一条用户指令进入、一个档位决策出来——复杂意图由强档规划、廉价档执行，简单意图全程廉价档，确定性护栏 + TTL 升级回退。", "ai", 1, "model"),
        E("dsh-bifenggang", "dsh-bifenggang", "按时间做模型路由：在设置页定义工作日峰谷时段与各时段使用的 Provider/模型（候选来自 harness 已注册的 API 与订阅账号），打开开关后由该策略决定每次请求的模型与思考档。开关按会话独立，会话列表每行带指示灯显示各自状态，设置页顶部写明此刻生效的模型与原因。无任何时段命中的日子（周末", "time", 1, "model"),
