        E("dsh-token-heatmap", "dsh-token-heatmap", "新建会话页的 GitHub 风格每日 Token 用量热力图：可选日历年度视图、绿/蓝配色与显示开关，并附今日/本月/累计总量。", "time", 1, "usage"),
