        E("dsh-turn-trace", "dsh-turn-trace", "DeepSeek Harness 的逐轮、逐步成本账本：在 Chat 与 Trajectory 旁新增 Turns 页签，显示 token、估算费用、缓存节省，以及工具参数、原始返回与来源检查器。纯客户端，价格按已记录的模型用量估算。", "ai", 1, "usage"),
        E("dsh-usage-guard-1", "dsh-usage-guard", "Web GUI 与桌面端的用量统计面板：静默按模型采集 token、活跃热力图、趋势图、费用估算与每日超限守卫。", "text", 1, "usage"),
        E("dsh-usage-heatmap", "dsh-usage-heatmap", "DSH 设置页的 Token 用量看板：九宫指标卡（累计/今日/昨日/峰值日/最长会话/连续活跃/活跃天数/会话/子代理 Token）、GitHub 风格每日/每周/累计热力图与活动洞察，全部从本地会话日志与投影缓存聚合，会话被删后历史 token 仍然保留。", "net", 1, "usage"),
        E("dsh-usage-insights", "dsh-usage-insights", "在 DSH 设置里加一页「用量查询」：把每次模型调用记进本地账本，按天、接口、模型汇总请求数、Token 与费用估算，支持单价修改与 CSV 导出。", "data", 1, "usage"),
        E("dsh-usage-ledger", "dsh-usage-ledger", "本地用量账本：从本机会话日志统计每日、每模型、每工作区的 token 消耗、缓存命中率、工具请求占比与估算费用，并提供按模型编辑单价的设置面板。", "text", 1, "usage"),
        E("dsh-usage-orb", "dsh-usage-orb", "DeepSeek Harness 跨会话用量面板：常驻用量圆环 + 可拖动面板，从本地会话日志聚合 token 用量、缓存命中率、成本与余额，支持工具级成本归因、iOS 式磁贴布局编辑与可选表情伴侣；数据只在本机读取，不联网。", "session", 1, "usage"),
        E("dsh-usage-state", "Balance & Quota · 余额与额度", "在输入框上方查看当前模型供应商的账户余额或套餐额度，显示已用比例和重置倒计时。", "time", 1, "usage"),
        E("dsh-usage-suite", "dsh-usage-suite", "输入框下方显示本轮花费；侧栏显示今日 token、消费与高峰/空闲时段；对话区顶部钉住最新提问，点击可跳回。", "session", 1, "usage"),
        E("dsh-usage-vendor-stats", "dsh-usage-vendor-stats", "按厂商（订阅/官方API）统计用量看板：按供应商/模型拆分 Token、缓存、输出等 KPI，53 周热力图，趋势折线图（今天按小时），模型钻取，费用估算，CSV 导出，以及健康度卡片（TTFT、生成速度、峰值 Context、错误率）。", "data", 1, "usage"),
        E("dsh-volcengine-usage", "dsh-volcengine-usage", "一个使用本地控制台登录态、可拖动的 DeepSeek Harness Web 火山引擎 Coding Plan 用量卡片。", "misc", 1, "usage"),
        E("dsh-where-did-my-tokens-go", "dsh-where-did-my-tokens-go", "在聊天页“深度思考”指示旁实时显示 token 计数，支持输入/输出合并或分列展示、逐步骤操作计数与 K/M/G/T 自适应单位。", "ai", 1, "usage"),
        E("dsh-zhijiang-connector", "dsh-zhijiang-connector", "在 DSH 侧边栏显示 New API 中转站的余额、日均消耗与剩余可用天数，并提供充值入口。", "misc", 1, "usage"),
        E("llmdshplugin-token-usage", "LLMDSHPlugin_token-usage", "仅本地、只读、不上传的 DSH Token 面板：按 provider 实际 usage 统计，所有后端统一汇总；含历史总量、365 天热力图、输入+输出与缓存读写明细、轮次/步骤、平均 tok/s，归档后仍保留历史。", "archive", 1, "usage"),
        E("zcode-usage-stats", "zcode-usage-stats", "DeepSeek Harness 的 Token 用量统计面板：用量趋势、模型用量与活跃热力图，手写 SVG，零图表库依赖。", "image", 1, "usage"),
        E("agent", "agent", "把本地 dsh 网页通过带登录门禁的中继转发到公网 *.ds.hn 子域名(也可自托管到自己的域名),支持可选的端到端加密(PBKDF2 到 AES-256-GCM)。", "codec", 1, "remote"),
        E("at-terminal-dsh", "at-terminal-dsh", "DeepSeek Harness 原生 SSH 终端与 SFTP 远程工作区，支持 Agent 直连运维与三级安全沙盒。", "ai", 1, "remote"),
        E("devctl-dsh", "devctl-dsh", "从另一台设备驱动 DSH：Host 插件开一个 token 鉴权的 TCP 端口，单文件 Python CLI 负责列会话、建会话、发带图消息、看流式回复，以及切模型、权限与工作区。", "net", 1, "remote"),
        E("dsh-3301", "dsh-3301", "将DSH Web GUI代理到3301端口供局域网访问。口令可选，无明文保存，初始3080端口保存回环不暴露。", "net", 1, "remote"),
        E("dsh-clash-proxy", "dsh-clash-proxy", "让 DeepSeek Harness 的出网流量走本地 Clash 代理，代理关闭时自动回落直连。", "net", 1, "remote"),
        E("dsh-coding-remote-kit", "dsh-coding-remote-kit", "DeepSeek Harness 移动配对远程插件：双平面白名单 RPC 上的端到端加密 Companion（局域网、Tailscale，可选 Cloudflare Quick Tunnel 或自建 rendezvous）。", "codec", 1, "remote"),
        E("dsh-desktop-automation", "dsh-desktop-automation", "macOS 桌面控制插件：agent 像人一样操作非浏览器应用（剪映/PS/WPS/原生客户端）——14 个工具覆盖鼠标/键盘/滚动/应用/窗口/截图，并整合视觉闭环（desktop_see 识图 + desktop_locate UI 定位坐标，复用 dsh 既有视觉凭据）。服务 GUI 会话按需", "image", 1, "remote"),
        E("dsh-dispatch", "plugin", "面向手机的指挥台而非 Web UI 镜像：从 PWA 把任务派发进隔离的 git worktree，工具审批推送通知支持手机/桌面「谁先答谁算」（绝不自动批准），多机会话看板，以及可自建的端到端加密零知识中继。", "git", 1, "remote"),
        E("dsh-enhancement", "dsh-enhancement", "DSH 增强套件：为 Web GUI 提供独立的密码访问网关（可选 HTTPS，适合局域网/远程访问），整合 PWA 安装与图标、桌面通知与 Web Push，并可把当前会话的 session id 注入第三方 API 请求头，在设置页统一配置。", "session", 1, "remote"),
        E("dsh-feishu-bot", "dsh-feishu-bot", "通过 WebSocket 将飞书聊天连接到 DeepSeek Harness 的项目、对话、回复和限定范围的工具审批。", "session", 1, "remote"),
        E("dsh-feishu-channel-1", "dsh-feishu-channel", "在飞书聊天里驱动 DeepSeek Harness agent：流式富卡片实时展示思考与工具步骤，按 DeepSeek 峰谷牌价计量每轮费用，一键审批、按模型能力透传图片，扫码即用、无需公网。", "image", 1, "remote"),
        E("dsh-feishu-cui", "dsh-feishu-cui", "免运维的远程 DSH——拿飞书私聊当界面，机器人出站长连接、不需要公网入口，工作区、会话（切换与改名）、模型、推理深度、权限预设、余额都用卡片操作，工具审批与 agent 反问也在同一个聊天里回。", "session", 1, "remote"),
        E("dsh-fleet", "dsh-fleet", "DeepSeek Harness 多机指挥台：用一个本地 dsh 页面管理多台远程 dsh——实时查看远程忙闲、免切标签页原地切换与使用、远程页面保活秒开、跨设备读取历史会话、一键刷新/重启，并支持控制端/被控端角色。", "session", 1, "remote"),
        E("dsh-lan-pair", "dsh-lan-pair", "仅内网的远程访问：手机或另一台电脑通过扫码或令牌接入同一份 DSH Web 界面，并可选内网免密钥直连。", "misc", 1, "remote"),
        E("dsh-mobile-access", "dsh-mobile-access", "用 iPhone 或 iPad 的 Safari 打开 Mac 或 Windows 上的 DeepSeek Harness Web：8 位配对码、回环监听的局域网网关、可选 Tailscale Serve，以及仅 iOS 生效的 Safari 输入与触摸补丁。可用 dsh plugin add 安装", "misc", 1, "remote"),
        E("dsh-mobile-access-1", "dsh-mobile-access", "受 PIN 保护的 DeepSeek Harness 移动端对话界面，在独立端口上通过局域网或自备隧道访问。", "net", 1, "remote"),
        E("dsh-mobile-access-2", "dsh-mobile-access", "移动端访问网关：独立子进程反向代理 + 首次访问 PC 审批（管理 token 认证、DNS rebinding 防护）+ 局域网/VPN/公网自动识别与网络模式切换 + 扫码访问 + WebSocket 实时转发 + 窄屏 UI 适配（输入区重排、第三方插件弹窗适配、crypto.randomUU", "codec", 1, "remote"),
        E("dsh-mobile-use", "dsh-mobile-use", "手机装进 DSH 右栏：读一次界面 120 ms、200-1300 token，截图那套要 0.5-3.2 s、1.5-2k 图片 token；点一下就是点真机（61 ms），圈一处带圈图和控件回到会话。不截图也能说清屏上有什么、刚才那下点中了没有。需要宿主上的 adb 与 ffmpeg；OCR 兜", "image", 1, "remote"),
        E("dsh-model-endpoint", "dsh-model-endpoint", "把当前在聊天或「模型」设置页选中的模型发布成 OpenAI 兼容 HTTP 端点：/v1/models、/v1/chat/completions（SSE 流式与非流式）、/health。请求可指定本 profile 能路由的任意模型；省略 model 时使用聊天中当前选中的模型，因此在聊天里换模型就", "fileops", 1, "remote"),
        E("dsh-multi-end", "dsh-multi-end", "DSH 多端管理：通过 SSH 远程连接多台机器，在同一原生侧栏管理工作区与会话，任务在所属机器运行。", "session", 1, "remote"),
        E("dsh-netshell", "dsh-netshell", "DeepSeek Harness Web 的本地与远程 SSH 终端：提供三级权限，危险 AI 命令需真人确认，凭据加密存储。", "codec", 1, "remote"),
        E("dsh-palm", "dsh-palm", "dsh 的独立手机端界面：扫码配对设备信任、实时 SSE 同步、三通道完成通知（应用内 / Web Push / Server酱·Bark·Telegram）、离线发件箱、审批与提问面板、多提供方用量卡、PWA；从零为窄屏设计的原生手机 UI。", "mail", 1, "remote"),
        E("dsh-peerbar", "dsh-peerbar", "把本机与多台远端 DeepSeek Harness 聚合进官方侧栏：远端工作区/会话作为原生行出现、由官方中栏打开，执行始终留在远端，经 HTTP/TLS 直连。远端无需安装插件，界面不使用 iframe。", "session", 1, "remote"),
        E("dsh-phone-access", "dsh-phone-access", "在 DSH 界面里加一个开关，经由内嵌的 loopback 反向代理与 Cloudflare 快速隧道把当前会话开放给手机浏览器，并把每次的新隧道地址推送到微信。", "net", 1, "remote"),
        E("dsh-plugin-login-gate", "dsh-plugin-login-gate", "密码登录的 HTTPS 闸门，让局域网设备安全地通过网络访问 DeepSeek Harness 的 Web 界面。", "misc", 1, "remote"),
        E("dsh-plugin-mobile-bridge", "dsh-plugin-mobile-bri", "带令牌鉴权的 REST 与 SSE 接口，扫码配对后可在手机 App 上看会话、发消息、批准工具调用。", "session", 1, "remote"),
        E("dsh-plugin-ssh", "dsh-plugin-ssh", "在 DeepSeek Harness 内使用 SSH 终端、SFTP 文件传输与文本编辑，并通过宿主模型排查服务器问题。", "fileops", 1, "remote"),
        E("dsh-pocket", "dsh-pocket", "为 DSH 单独做的窄屏移动端 Web 服务，不是把桌面 GUI 缩放塞进手机：自带会话列表与聊天流，随机访问令牌保护，可走局域网、cloudflared / localtunnel / localhost.run 隧道或自有服务器 SSH 反向转发。手机上流式看助手文本、思考、工具调用与结果，能发", "session", 1, "remote"),
        E("dsh-presence", "dsh-presence", "像操作本地一样使用 ssh config 中的任意远程机器：持久连接、原生文件编辑、搜索、命令执行与终端，远端无需安装任何东西。", "fileops", 1, "remote"),
        E("dsh-produced-file-paths", "dsh-produced-file-paths", "在远程 Web 中显示并复制 DSH 每轮产出文件的绝对路径。", "fileops", 1, "remote"),
        E("dsh-remote-3", "dsh-remote", "扫码即可用手机远程控制 DeepSeek Harness：查看会话、发送消息、上传图片，支持局域网、IPv6 与 Cloudflare 隧道。", "image", 1, "remote"),
        E("dsh-remote-bridge", "dsh-remote-bridge", "把 DSH 内核的私有 remote 协议翻译成版本化 REST 接口（聊天、会话、文件、设备），供 Android 客户端 dsh-companion 等受信任客户端使用；桌面端在 DSH 设置里提供「手机设置」面板：主列表五张卡（远程访问 / 外网隧道 / 设备 / 回收站 / App 下载），", "net", 1, "remote"),
        E("dsh-remote-console", "dsh-remote-console", "DSH 右侧栏的 SSH 远程终端：你和 agent 共用一个 PTY，16 个 agent 工具，传输上限可调，终端按会话隔离，配置页支持一键热更新。", "session", 1, "remote"),
        E("dsh-remote-dock", "dsh-remote-dock", "将 SSH 主机与 WSL 发行版接入远程 DSH 工作区，支持环境安装、模型配置移植与本地内嵌远程界面。", "ai", 1, "remote"),
        E("dsh-remote-ssh-tools", "dsh-remote-ssh-tools", "DeepSeek Harness 的 SSH 会话管理：连接档案、Agent 远程执行、交互终端与 SFTP；秘密仅存于 DSH 凭据中心。", "session", 1, "remote"),
        E("dsh-remote-workspaces", "dsh-remote-workspaces", "通过 SSH 把远程主机目录作为 Harness 工作区打开：read/write/edit/grep/glob 与 shell 命令经 SFTP、ripgrep、ssh2 exec 直接在远程主机执行，不做本地镜像；多主机注册表加密存储，本地沙箱策略依然生效。", "codec", 1, "remote"),
        E("dsh-roam", "dsh-roam", "远程连接正在运行的 DeepSeek Harness 会话：手机浏览器扫码即可继续对话、处理审批、新建任务，支持同一 Wi-Fi 或临时隧道。", "session", 1, "remote"),
        E("dsh-service-portal", "dsh-service-portal", "把一个口令登录的内网地址与公网 cloudflared 快速隧道域名提供给本机任意服务，每条路由的开放/屏蔽闸门在插件设置页里管理。需本机有 Python 3 与 cloudflared，缺失或路径填错会在启动前的设置页里提示；内网与本机访问默认免密，公网隧道需要口令。", "fileops", 1, "remote"),
        E("dsh-solo-agent", "agent", "DSH-SOLO 手机远程协作的电脑端插件，搭配 App 扫码连接，查看会话、发送任务、切换模型、传递附件并确认操作审批；支持端到端加密，已配置官方云转发服务，无需自行部署服务器。App 安装包下载：https://github.com/wudidiandian/dsh-solo/releases/", "codec", 1, "remote"),
        E("dsh-ssh-logs", "dsh-ssh-logs", "从白名单 SSH 服务器和日志根目录读取或搜索有界日志内容，不开放任意远程命令。", "fileops", 1, "remote"),
        E("dsh-ssh-mac", "dsh-ssh-mac", "基于 @linxin666/dsh-ssh 的二次开发（两者不能同时启用）：建链前先按网卡 MAC 把主机解析成当前 IP，DHCP 换号不用改配置。", "devops", 1, "remote"),
        E("dsh-ssh-pro", "dsh-ssh-pro", "SSH 增强运维：连接测试、远程目录、ssh-config 导入、指纹检查与多主机批量执行。", "fileops", 1, "remote"),
        E("dsh-ssh-remote", "dsh-ssh-remote", "SSH 远程执行插件集：把会话工作区指向 ssh:// 目录，文件读写、命令与 shell 全部在远程主机上执行。", "fileops", 1, "remote"),
        E("dsh-ssh-shell", "dsh-ssh-shell", "用密码直连远程主机的 SSH 终端：ssh_remote 工具提供 connect/exec/close/status 四个动作，底层是 ControlMaster 常驻会话；另带浏览器浮动终端面板，跑真实 PTY。", "session", 1, "remote"),
        E("dsh-switchboard", "dsh-switchboard", "在 Telegram 和飞书中指挥 DeepSeek Harness：每轮一条实时进度消息，按钮审批与提问，收发文件和语音，断线和重启不丢消息，飞书扫码接入，按人设置权限。", "media", 1, "remote"),
        E("dsh-tailscale-console", "dsh-tailscale-console", "Tailscale 远程访问运维面板：健康检查、HTTPS 入口（tailscale serve）开关、macOS 代理绕过、中继服务器运维与 ACL 片段生成。", "net", 1, "remote"),
        E("dsh-telegram-bridge", "dsh-telegram-bridge", "通过 Telegram 遥控 dsh Agent：对话、技能调用、工作目录浏览与文件传输。", "fileops", 1, "remote"),
        E("dsh-telegram-channel-ru", "dsh-telegram-channel-ru", "DeepSeek Harness 的 Telegram 遥控器：在手机上接续正在运行的 Web 会话并回答问题，界面为俄语。hi-wenw/dsh-telegram-channel 的俄语分支（MIT）。", "git", 1, "remote"),
        E("dsh-wechat-channel", "dsh-wechat-channel", "微信公众号通道：微信消息触发 DSH 会话，回答经客服消息接口推回微信，回调带签名校验与 openid 白名单。", "session", 1, "remote"),
        E("dsh-ws-deflate", "dsh-ws-deflate", "在不修改 DSH 安装目录的前提下，为 DSH 的 WebSocket 传输启用 permessage-deflate。", "fileops", 1, "remote"),
        E("huahua-dsh-chatroom", "huahua-dsh-chatroom", "跨机 DSH 群聊适配修复包：安装期自动对 dsh-weave rc.14 打四合一补丁（注入崩溃、随机端口、4KB ack 帧上限），并附带 dsh-chat x dsh-weave x dsh-bridge 聊天室的部署、机制与运维文档。", "net", 1, "remote"),
        E("kizuna", "kizuna", "Kizuna Agent 信箱：四个工具让 Agent 读自己的信箱（信箱状态、待处理信件、读一封信全文），并以 completed / failed / input-required / working 状态回信。Kizuna 是带可靠投递的 Agent 通讯录：同一台机器上的 kizuna-bo", "ai", 1, "remote"),
        E("open-whale", "dsh-openwhale", "把手机变成你这台电脑上 DeepSeek Harness 的个人助理——扫一次码即可远程聊天、收发图片与文件、看回复流式输出，多台手机还能在同一会话里协作；连接方式可选局域网 / Tailscale / 公网隧道。附带安卓安装包、iOS 构建流水线，以及鸿蒙和 iOS 浏览器可直接用的网页版客户端。", "image", 1, "remote"),
        E("quicktui-dsh", "quicktui-dsh", "在 dsh 插件页配置 QuickTUI：在 macOS 与 Linux 上安装 QuickTUI server，扫码配对手机 App，并接入 dsh 会话，让 App 能查看会话、回应审批与提问、发送提示词、中断回合。", "session", 1, "remote"),
        E("dm-security", "DM-security", "只读安全评估达梦 DM8 数据库：60 项检查，附等保 2.0 控制点对照，生成 HTML 报告。需 Java 8+ 并自备达梦 DmJdbcDriver jar。", "misc", 1, "security"),
        E("dsh-airbag", "dsh-airbag", "拦截粘贴进输入框或被工具写入的 API 密钥，记录泄露事件，并扫描工作区中暴露的密钥。", "misc", 1, "security"),
        E("dsh-almost-full-access", "dsh-Almost_Full_Access", "介于 workspace-write 与 Full access 之间的权限模式：命令先经规则与子代理审查，不可逆或系统级操作需人工批准。", "net", 1, "security"),
        E("dsh-alpha-guard", "dsh-alpha-guard", "在工具调用真正执行之前做判定的策略层护栏：读取白名单、敏感路径拒绝（凭据、浏览器配置、聊天记录、其他用户目录）、危险命令拦截、子代理隔离，以及对可执行文件的静态扫描与隔离区。每次拒绝都写进审计日志。它是文本与路径过滤，不是沙箱也不是杀软：动态拼接的路径、编码载荷、加壳程序都可能绕过，也不能替代系统自", "codec", 1, "security"),
        E("dsh-approval-gate", "dsh-approval-gate", "dsh-approval-gate 的维护中 fork。判定器不可用时，确认次数已达阈值的中立操作直接自动放行，不再重复弹人工审批；审批说明由真实的沙箱模式、命令与路径生成中文。另含凭据外泄与系统路径销毁的确定性硬拒、判定输入脱敏、判定模型候选链、带操作指纹的放行规则，以及可查看 unified d", "fileops", 1, "security"),
        E("dsh-auto-classifier", "dsh-auto-classifier", "auto（自主模式）权限分类器：工具作用域的放行/拒绝规则、LLM 语义裁判与 git 快照，面向无人值守会话。", "git", 1, "security"),
        E("dsh-auto-preset", "dsh-auto-preset", "重新打开会话时恢复该会话上次设置的权限预设；首次打开不干预。需排在 dsh-experimental-auto-review 之后加载才能恢复 auto 预设。", "session", 1, "security"),
        E("dsh-auto-review-1", "dsh-auto-review", "沙箱越权审批的 LLM 应答器：先过确定性正则过滤，再交给干净上下文的审核模型；拿不准才转人工。需要随附的核心补丁。", "text", 1, "security"),
        E("dsh-auto-review-jev", "dsh-auto-review-jev", "DeepSeek Harness 审批守护者：权限请求先由审查模型裁决，支持 System One 决策 API 后端（TypeSafe Jev／硅基流动／自部署 Laya）、可配置的低置信度策略与免审白名单。", "ai", 1, "security"),
        E("dsh-auto-reviewer", "dsh-auto-reviewer", "Codex 风格自动审查权限模式：新增 auto-review 权限档，自动放行安全沙箱提权，危险或模糊操作转人工确认，未确认的致命操作直接拒绝。", "misc", 1, "security"),
        E("dsh-bash-guard", "dsh-bash-guard", "DSH 权限守卫：原生权限菜单里的四范围读写执行权限位，bash 命令可选 Jev 语义分类层。", "misc", 1, "security"),
        E("dsh-computer-use-guard", "dsh-computer-use-guard", "给 computer-use（cua-driver）工具族加三档「禁止 / 询问 / 自动授权」闸门：每个工具类别在设置里各占一个分段控件，另可用放行名单或拒绝名单按工具名覆盖档位。", "misc", 1, "security"),
        E("dsh-cookie-guard-2", "dsh-cookie-guard", "把 DSH 桌面端 dsh-auth-* 会话 cookie 的寿命压到 7 天，避免它们越积越多撑爆请求头、导致启动时报 HTTP 431。", "session", 1, "security"),
        E("dsh-credential-manager", "dsh-credential-manager", "具名凭据按引用使用：秘密值在「设置 → 凭据」页录入，按次注入 shell 执行环境的 DSH_CM_* 变量而不打印进对话，credential_read 是文档化的最后手段。", "session", 1, "security"),
        E("dsh-egress-guard", "dsh-egress-guard", "工具管线上的运行时安全网关：拦截出站白名单之外的主机调用，在 canonical value（而非仅渲染内容）层面脱敏结果中的凭据，每个决策写入 JSONL 审计日志；默认仅监控不拦截。", "data", 1, "security"),
        E("dsh-feishu-channel", "dsh-feishu-channel", "面向安全的 DeepSeek Harness 飞书通道：提供白名单远程 Agent 访问、工作区路径与符号链接边界校验、风险分级审批、会话隔离、日志脱敏和有界消息队列。", "fileops", 1, "security"),
        E("dsh-fileguard", "dsh-fileguard", "文件守卫：拦截危险的文件删除/写入命令，需用户提供 token 才放行。", "fileops", 1, "security"),
        E("dsh-fleet-audit", "dsh-fleet-audit", "只读的 agent 机群凭据卫生审计：检查凭据文件权限、git remote 内嵌凭据（输出脱敏）与 provider token 字面量计数；零依赖、确定性。", "git", 1, "security"),
        E("dsh-fofatoto", "dsh-fofatoto", "在对话里做 FOFA 网络空间测绘：查看账号额度、执行查询语句，并把全量结果按时间游标深翻页导出为 CSV／JSON／TXT 落到会话工作区；被时间预算或上游报错中断的 CSV／TXT 导出可凭游标续写同一文件，已拉取的行不丢。结果以对话卡片展示（语句、命中数、文件路径），API Key 在插件页保", "data", 1, "security"),
        E("dsh-fs-allowlist", "dsh-fs-allowlist", "白名单目录写入免审批——write/edit 文件工具直通白名单栅栏，命中白名单的 bash 沙箱升权自动放行，设置页可视化管理目录与开关。", "fileops", 1, "security"),
        E("dsh-full-access-switch", "dsh-full-access-switch", "给 DeepSeek Harness 加 Full access 一次性开关：新工作区与新对话默认 danger-full-access 并跳过逐个确认；可作为 dsh bundle 安装，也可用脚本打补丁。", "session", 1, "security"),
        E("dsh-guardian-2", "dsh-guardian", "增加危险操作策略检查、输出脱敏和安全审查工作流。", "misc", 1, "security"),
        E("dsh-hard-gate", "dsh-hard-gate", "内置沙箱之上的独立权限闸门：在 danger-full-access 下依然拦截工作区外与受保护路径的写入，未完整读到文件末尾就整文件覆盖时拒绝，破坏性操作前生成 ZIP 还原点与回收站副本。", "archive", 1, "security"),
        E("dsh-hooks", "dsh-hooks", "文件声明的命令钩子，覆盖会话、提问、工具、审批、Stop 与压缩后等事件，配套只读审批界面：未经批准的命令不执行，批准绑定精确定义、实际执行目录与 watchFiles 固定内容。命令以 DSH 系统用户身份运行且无独立沙箱，因此信任记录是显式的。", "archive", 1, "security"),
        E("dsh-jev-guard", "dsh-jev-guard", "DSH 执行前安全阀门，用 TypeSafe Jev 模型做判定：挂载 tools/pre-execute，对每条 bash/pwsh 调用先过离线静态规则，再向 Jev 模型（TypeSafe 的 System One 模型，返回结构化判定而非散文）提一个是非问句——「这条命令会不可逆地删除或覆盖", "ai", 1, "security"),
        E("dsh-key-panel", "dsh-key-panel", "为 DSH Desktop 提供密钥库，集中保管 API 密钥并以 $DSH_* 变量注入助手的 shell 中。", "misc", 1, "security"),
        E("dsh-kiss-law", "KISS_Law-DSH", "唯稳律（KISS's Law）英文版：业界首个且唯一的领域无关白箱因果裁决中间件。与领域特定的因果推断工具（统计/经济/机器学习）或「需提供因果证据」的代理防火墙不同，它在执行前对*每个*工具调用沿确定性结构因果链（R->S->D->H->M）裁决——适用任意领域，无需训练或按领域调参。拦截破坏性与", "net", 1, "security"),
        E("dsh-kubectl-guard", "dsh-kubectl-guard", "按 kubeconfig context 管控 kubectl 调用的策略插件：本地集群外硬拒绝不可逆操作，其余写操作请求人工确认。", "misc", 1, "security"),
        E("dsh-llm-approve-for-me", "dsh-llm-approve-for-me", "使用隔离的 LLM 审查来批准或拒绝 DSH 沙箱权限请求。", "ai", 1, "security"),
        E("dsh-mcpguard", "dsh-mcpguard", "扫描 skill 与 MCP 配置中的提示注入、同形字、Unicode 隐形字符、危险 shell 与凭据泄露。", "image", 1, "security"),
        E("dsh-perm-guard", "dsh-perm-guard", "自动审批权限守卫：介于 workspace-write 与 danger-full-access 之间的中间档——信任目录内安全操作自动放行，危险操作一律人工确认；11 个分类开关可调，自带审计记录。", "fileops", 1, "security"),
        E("dsh-permission-matrix", "dsh-permission-matrix", "把 DSH 权限拆成 9 个可选预设（3 种沙箱 × 4 种审批），规则 + LLM 双通道四档风险分级，高风险操作需输入批准密码才放行，附 JSONL 审计日志。", "data", 1, "security"),
        E("dsh-plugin-gate", "dsh-plugin-gate", "DSH 插件的安装安全闸门：在 \"dsh plugin add\" 前对本地目录或 npm 包做\"杀毒\"式扫描（安装脚本、权限、密钥、网络回连），给出 BLOCK/WARN/PASS 判定。", "fileops", 1, "security"),
        E("dsh-plugin-precheck", "dsh-plugin-precheck", "DSH 插件安装前兼容性门控：锁定解析版本、校验 peer/engines 声明、在隔离 DSH_HOME 中试装并限时试启动，任一失败即阻止；正式安装失败自动还原 profile。可选拦截 dsh-market 的安装/更新点击，兼容 DeepSeek Harness 0.2.x。", "fileops", 1, "security"),
        E("dsh-plugin-sentinel", "dsh-plugin-sentinel", "插件安装前静态安全审计：生命周期脚本、动态执行、凭据外传组合特征与 patch 层风险；零依赖，tar 包全程内存解析不落盘。", "archive", 1, "security"),
        E("dsh-plugin-sql-security-validate", "dsh-plugin-sql-security-validate", "拒绝智能体生成的越权 SQL：读取的表或字段不在黑白名单策略内时直接拒绝，返回结构化权限原因，不改写查询。", "data", 1, "security"),
        E("dsh-plugin-trustlens", "dsh-plugin-trustlens", "只读 DSH 插件审查器：静态扫描、当前会话模型审查和启用前确认。", "session", 1, "security"),
        E("dsh-plugins-17", "dsh-approve-for-me", "自动化审批审核：只读工具自动放行、危险命令自动拒绝，策略引擎 fail-closed。", "misc", 1, "security"),
        E("dsh-plugins-18", "dsh-secret-redactor", "工具结果敏感信息自动脱敏：模型看到前掩码 API key / token / JWT / 私钥与配置密钥。", "codec", 1, "security"),
        E("dsh-poison-guard", "dsh-poison-guard", "DSH 插件安装前投毒扫描：AST（JS-X-Ray）+ 去混淆解码 + 正则启发式，发现即非零退出，可作 CI 门禁。", "codec", 1, "security"),
        E("dsh-provenance", "dsh-provenance", "为 DeepSeek Harness 插件做安装前供应链校验：在代码运行前核对即将安装的包是否与你读到的源码一致。", "misc", 1, "security"),
        E("dsh-semgrep-sast", "semgrep-sast", "面向 DeepSeek Harness 的工作区内 Semgrep SAST 工具，提供托管 Windows x64 运行时、结构化有界结果、取消与超时控制，以及经用户批准的沙箱权限升级。npm 包名为 @aaub-software/dsh-semgrep-sast。", "misc", 1, "security"),
        E("dsh-session-lock-1", "dsh-session-lock", "DeepSeek Harness 侧边栏的会话锁：每个对话行尾多一个锁按钮，锁定后只把对话区挡住并弹出密码框，侧边栏照常可用。窗口失焦、切到后台、页面隐藏或换了对话都会立刻重新锁定；锁定只是界面层，正在跑的回合继续执行，遮罩上会提示后台任务仍在运行。密码摘要、锁清单和偏好存放在 <DSH_HOME>", "session", 1, "security"),
        E("dsh-time-machine", "dsh-time-machine", "为 DeepSeek Harness 提供智能检查点、工作区安全防护和即时回滚。", "misc", 1, "security"),
        E("dsh-tool-approval", "dsh-tool-approval", "手动审批模式（Manual/Ask Mode）。", "misc", 1, "security"),
        E("dsh-tool-budget", "dsh-tool-budget", "在达到可配置的会话级工具调用次数上限后，硬拦截后续工具调用。", "session", 1, "security"),
        E("dsh-turn-approval", "dsh-turn-approval", "DSH「允许本次任务」临时授权：仅在当前任务内自动放行同类 `danger-full-access` 请求，任务结束自动失效。", "misc", 1, "security"),
        E("dsh-weiwen-law", "weiwen-law-dsh", "唯稳律白箱因果闸门：每个工具调用执行前沿确定性因果逻辑链裁决——拦截破坏性与凭据文件操作、对反复越界升级止损、故障环节切断至修复验证、不可审计执行给出风险判定；纯本地运行、零 API 成本，附带 6 个白箱自查工具。", "fileops", 1, "security"),
        E("dsh-write-gate", "dsh-write-gate", "承诺写入闸门：由运营者编写的规则在工具调用执行前生效——先是一层确定性守卫，再是一层 LLM 裁判，默认失败即拒绝，每一次拦截都写进矛盾日志。", "ai", 1, "security"),
