        E("dsh-chrome-cdp", "dsh-chrome-cdp", "Chrome DevTools Protocol 插件 for DeepSeek Harness。通过 chromremote-interface 以 CDP 连接并操控 Chrome。连接带有图形界面。", "misc", 1, "browser"),
        E("dsh-chrome-use", "dsh-chrome-use", "操纵你正在使用的 Chrome 浏览器：新建或复用已登录的标签页，让模型读取页面、点击、填写、拖拽页面元素、滚动、截图，新建标签页并分组、关闭本会话打开的标签页，并查看控制台与网络日志，调试浏览器等。需要 Chrome 120 或更新版本；扩展从 Chrome 应用商店安装，用 8 位配对码连接。", "image", 1, "browser"),
        E("dsh-dschat", "dsh-dschat", "在 DSH 桌面版主面板里通过 Electron webview 嵌入 DeepSeek 网页版聊天（chat.deepseek.com），带后退/前进/刷新工具栏，并把登录相关的 localStorage 快照存在本地、下次打开时回填。", "misc", 1, "browser"),
        E("dsh-inapp-browser", "dsh-inapp-browser", "通过 Better Sidebar 为 DeepSeek Harness 提供共享浏览器面板，支持本地 Chromium、人和 AI 的鼠标键盘操作、页面快照、截图及按聊天持久保存的浏览器资料。", "image", 1, "browser"),
        E("dsh-inner-browser-use", "dsh-inner-browser-use", "不另开窗口：用右栏内置浏览器，同一份 cookie、同一处登录，指针走到哪点到哪。", "misc", 1, "browser"),
        E("dsh-keyless-search", "dsh-keyless-search", "为内置 web_search 工具注册免密钥搜索提供方：无需 API Key 即可使用，在 Tavily 与 Firecrawl 官方免密钥通道之间自动降级；若设置了 TAVILY_API_KEY 或 FIRECRAWL_API_KEY 会自动采用。另含两个 Bing 抓取后端，默认关闭。", "net", 1, "browser"),
        E("dsh-moli-browser", "dsh-moli-browser", "为 DSH 挂出完整的浏览器工具面（33 个 browser_* 工具）：把 ctx.browser 接缝接到自管的 moli 无头浏览器（经 127.0.0.1 单例 CDP 守护进程，带 Bearer token 鉴权、请求路径白名单与 WebSocket 地址改写，不需要 root / GUI", "sysinfo", 1, "browser"),
        E("dsh-plugin-nuaa-search", "dsh-plugin-nuaa-search", "免 key 的 web_search 后端：按降级链抓取 Bing 中文站、360 与 SearXNG，返回真实 URL、摘要与发布日期；不需要任何 API key，也没有设置卡片。面向校园网等拿不到官方 key 的环境。SearXNG 仅在配置自有实例地址后才会启用；安装后 web_search", "net", 1, "browser"),
        E("dsh-scrapling", "dsh-scrapling", "把 Scrapling Python 库包成最多十九个模型工具，按探测到的能力注册：为纯 JavaScript 页面上真实浏览器渲染、用 CSS/XPath 取出结构化数据而不是 Markdown、选择器自愈、可复用的登录态会话、XHR 抓取、页面截图、受部署门禁的浏览器动作，以及在官方作业后端上跑", "pdfdoc", 1, "browser"),
        E("dsh-search-hub", "dsh-search-hub", "可配置的原生 web_search 后端：在 DeepSeek 官方原生搜索与智谱 GLM web_search 之间切换当前生效入口，并在设置页管理搜索入口与凭证引用。", "search", 1, "browser"),
        E("dsh-sidebar-mobile-browser", "dsh-sidebar-mobile-browser", "右侧边栏的移动端视口预览标签页：九种预设尺寸（手机、平板、笔记本）及自定义宽高，一键复制当前地址，并可通过 @ 按钮或 /url 指令把页面地址插入输入框。", "misc", 1, "browser"),
        E("dsh-use-browser", "use-browser", "通用浏览器自动化：browser_open、browser_click、browser_type、browser_extract、browser_screenshot、browser_eval 六个工具，@e 元素引用，Playwright 无头与 CDP（连接本机 Chrome）双后端。", "misc", 1, "browser"),
        E("dsh-web-kimi", "dsh-web-kimi", "为 DeepSeek Harness 提供 Kimi Coding 的网页搜索与网页抓取双提供方——一把 coding 计划密钥同时接入 ctx.web 的两条链路（/v1/search 与 /v1/fetch），设置卡片经凭据服务保存密钥，并回退读取 Kimi CLI 配置，安装即用。", "net", 1, "browser"),
        E("dsh-web-search-2", "dsh-web-search", "同时兼容 DSH 与 Pi 的搜索与抓取提供方：Exa、Tavily、Parallel、Firecrawl、TinyFish 匿名优先路由，计费需显式授权，带额度预检与有界取消。", "net", 1, "browser"),
        E("dsh-web-search-glm", "dsh-web-search-glm", "智谱 GLM 联网搜索 provider：以 glm 注册到 ctx.web 缝，经 GLM 的 Anthropic 兼容 API 执行原生 web_search 服务端工具（走 Coding Plan 计费）。", "search", 1, "browser"),
        E("dsh-web-search-tavily", "dsh-web-search-tavily", "为原生 web_search 提供 Tavily 搜索后端，并在设置 → 插件中提供 API Key 管理与是否替换 DeepSeek 的开关。", "text", 1, "browser"),
        E("dsh-web-search-zhipu", "dsh-web-search-zhipu", "GLM(智谱)网页搜索 provider——把 web_search 后端切到智谱 Anthropic 兼容端点的服务端搜索工具,直接复用你现有的 GLM 额度或 Coding Plan,替代 DeepSeek 官方搜索通道,并内置智谱私有响应格式的翻译层。", "search", 1, "browser"),
        E("dsh-web-window-companion", "dsh-web-window-companion", "在独立浏览器 profile 的 Edge/Chrome 应用模式窗口中打开 dsh web 界面，关闭窗口即优雅停止服务。", "fileops", 1, "browser"),
        E("dsh-webmcp", "dsh-webmcp", "WebMCP 桥接器：让 agent 通过内置无头 Chromium，发现并调用网站按 W3C WebMCP 协议暴露的站点工具。", "ai", 1, "browser"),
        E("dsh-webview", "dsh-webview", "在 DSH 桌面端里打开 chat.deepseek.com：入口有两个——会话视图标签栏里的「网页端」（与「对话｜轨迹｜上下文」并列， 随当前会话走），以及左上角面板列的地球图标；两者共用同一个内嵌页面，切换入口不会重新加载。登录态可跨重启保留 （在页面自身脚本执行前回放 localStorage", "session", 1, "browser"),
        E("kimi-webbridge-dsh", "kimi-webbridge-dsh", "自动安装并启动 kimi-webbridge 桥接守护进程（含 SHA-256 校验），注册一套 25 个动作的技能，通过本地桥接驱动用户的真实浏览器。", "sysinfo", 1, "browser"),
        E("dsh-ci-co-pilot", "dsh-ci-co-pilot", "让 DeepSeek Harness Agent 化身 GitHub 副驾：PR 审查、CI 失败修复、Issue 分类与自动发版说明。", "ai", 1, "git"),
        E("dsh-code-smell", "dsh-code-smell", "代码气味雷达：静态扫描 TODO/FIXME 债务、未实现桩、超长行、大文件与重复代码块，按严重度输出修复建议，全程只读。", "fileops", 1, "git"),
        E("dsh-file-review-tab", "dsh-file-review-tab", "侧边栏「文件审查」标签页：按轮次列出本会话改动文件、展开行级 diff 并支持撤销，对话尾部同步显示同款审查卡片。需另装 dsh-better-sidebar。是 Lzh3070/dsh-file-review-tab 的 DSH 0.2.x 移植版，不要与原版同装。", "fileops", 1, "git"),
        E("dsh-git-branch-manage", "dsh-git-branch", "DeepSeek Harness 的 git 分支与 worktree 管理：工作区工具栏显示当前分支并可原地切换；支持 IDEA 风格分支选择器、远程分支检出、右键操作菜单（新建/重命名/删除/复制）、推送与更新当前分支，以及把分支隔离到独立 worktree 工作区并管理其创建与删除。", "git", 1, "git"),
        E("dsh-git-connector", "dsh-git-connector", "DeepSeek Harness 的 Git 仓库连接：按档案名操作仓库（clone/fetch/pull/push/commit）、Gitea/Forgejo/GitHub API、密钥存 DSH 凭据中心，并按仓库单独授权忽略证书/允许覆盖/force push 等危险开关。", "git", 1, "git"),
        E("dsh-git-graph-sidebar", "dsh-git-graph-sidebar", "DSH 的 Git 图谱插件：better-sidebar 里看多仓库提交图（泳道、合并菱形、短槽、导出），七套内置规范（可自建、可隐藏）注入每个模型步骤并体检最近 20 条提交。与上游同占 /git 前缀，二选一。", "git", 1, "git"),
        E("dsh-git-manager", "dsh-git-manager", "为 DeepSeek Harness 提供 GitHub 联动的可视化 Git 管理：引导式 GitHub Flow 步骤、带 PR/CI 徽章的提交图谱、一键 GitHub 登录、PR 与 issue 管理，以及面向 Agent 的结构化 Git 工具。2.0.0 起由 gitcompass 改名", "git", 1, "git"),
        E("dsh-git-manager-1", "dsh-git-manager", "DeepSeek Harness 的 Git 工作区管理：输入框「模式」选择器旁的仓库感知入口，打开与设置同规格的面板，覆盖 diff/commit、分支、冲突、worktree 管理与带分支线的提交历史。", "git", 1, "git"),
        E("dsh-git-server", "dsh-git-server", "Git 服务器：内嵌 ts-gogs（Gogs 的 TypeScript 平替），独立端口跑完整 Git 服务（HTTP clone/push、网页端、issue/PR/wiki），可复用 user-management 的用户名密码，设置页一键启停。", "git", 1, "git"),
        E("dsh-git-statusline", "dsh-git-statusline", "DSH Web 的紧凑 Git 状态行：显示当前分支、已暂存与未暂存的行数改动、相对 upstream 的领先/落后提交数以及工作区干净标记；可放在侧边栏底部、会话标题栏或输入框上方/下方，位置在设置页切换。", "git", 1, "git"),
        E("dsh-git-vcs", "dsh-git-vcs", "右侧栏的 IDEA 风格 Git 面板：本地变更与按文件勾选提交、提交树与提交详情、分支 / 远程 / 贮藏管理、带凭据兜底的推送，以及 git 命令流水，全部通过原生 git CLI 执行。", "git", 1, "git"),
        E("dsh-git-workbench-1", "dsh-git-workbench", "DSH 的 JetBrains 风格 Git 工作台：按块与按行暂存、带词级高亮的并排 diff、提交图与分支操作、三方冲突合并，还能用宿主模型起草提交信息。", "git", 1, "git"),
        E("dsh-git-workflow-1", "dsh-git-workflow", "规范提交（Conventional Commits）、自动 changelog、PR 描述生成与分支推送，纯 git CLI 实现。", "git", 1, "git"),
        E("dsh-git4idea", "dsh-git4idea", "DSH 里的 IDEA 风格 Git 工具窗口：带 ahead/behind 角标的分支树、可按文本/分支/作者/日期/路径筛选的提交图谱、已暂存与未暂存变更和提交框、提交详情与逐文件行级 diff、贮藏与工作树管理、git 控制台日志，以及 AI 撰写提交信息。KannaKuron/dsh-ide", "git", 1, "git"),
        E("dsh-gitee-chat", "dsh-gitee-chat", "在对话里管理 Gitee 企业版项目：issue、Pull Request、看板与 Gitee MCP 工具链。", "git", 1, "git"),
        E("dsh-gitflow", "dsh-gitflow", "增加需要审批的 Git 状态、diff、日志、提交、分支和可选检查点工具。", "git", 1, "git"),
        E("dsh-github", "dsh-github", "Web GUI 的 GitHub 账号与本地 Git 工作流插件，支持 clone、快进 pull、status、commit、push，推送默认关闭并有宿主侧开关保护。", "git", 1, "git"),
        E("dsh-gitlab-plugin", "gitlab", "在侧栏面板里通过 GitLab REST API 与个人访问令牌查看合并请求、评审讨论串与流水线作业日志，并可评论、回复、解决讨论与批准；写操作均需二次确认（读需 read_api，写需 api）。", "devops", 1, "git"),
        E("dsh-gitmate", "dsh-gitmate", "右侧栏的 Git 面板与十五个 Agent 工具：编辑器式的差异、覆盖全部分支的提交图、暂存与提交、分支与贮藏与远程操作，以及由模型协助的提交说明、提交前审阅和拆分提交方案。", "git", 1, "git"),
        E("dsh-home-sync", "dsh-home-sync", "通过一个 git 远端同步 DSH 主目录与 Mnemon 记忆数据：拉取、推送、按间隔自动同步、跨设备迁移、初始化备份，遇冲突在推送前停下并保留本地提交；面板记录最近 100 次操作各自的备份路径。", "git", 1, "git"),
        E("dsh-jj-panel", "dsh-jj-panel", "DSH Web GUI 里的 Jujutsu（jj）版本控制面板：「Jujutsu」标签页把 jj log 渲染成 change 图，含 change 详情、改动文件与文件差异、revset 输入框，以及 jj 原生历史改写（拖拽 rebase、按文件拆分、修改描述、压缩、放弃、撤销、推送）；直接读", "git", 1, "git"),
        E("dsh-ma-plugins-2", "dsh-librarian", "带行号证据和内存缓存的 GitHub 只读调研子代理。", "archive", 1, "git"),
        E("dsh-next-git", "dsh-next-git", "DSH Web 右侧边栏的 Git tab，跟随当前会话的仓库：下拉切换本地/远程分支（带 ahead/behind），按 staged/unstaged/untracked/conflicted 分组暂存，提交、fetch、pull、push（无 upstream 时自动建跟踪分支），用默认模型按", "git", 1, "git"),
        E("dsh-open-code-review-1", "dsh-open-code-review", "将阿里 Open Code Review 接入 DSH：通过原生文件筛选、规则工具和审查技能复用当前会话模型，并提供可选的 OCR 独立审查模式。", "git", 1, "git"),
        E("dsh-plugin-git", "dsh-plugin-git", "Git 服务 + 右侧边栏 UI：Changes 页（暂存/取消暂存、逐文件 diff、提交/修补、推送与 rebase 同步、二次确认的丢弃）、分页 canvas 提交图谱页、Worktrees 页（列出/进入/新建工作树）、输入框旁分支选择器，以及可选的 LLM 提交信息生成。", "git", 1, "git"),
        E("dsh-plugin-git-workbench", "dsh-plugin-git-workbench", "面向 DSH 的本地 Git 工作台：分支搜索与切换、hunk 级暂存、提交图谱、文件历史与 blame、储藏与工作树管理、冲突处理，以及 8 个供 agent 使用的 Git 工具。", "git", 1, "git"),
        E("dsh-plugin-repopanel", "dsh-plugin-repopanel", "浏览工作区 origin 远端对应的 GitHub issue 与 pull request，筛选、评论、关闭或重开，并可转成任务写到 dsh-plugin-taskboard 的看板上等 agent 领取。", "git", 1, "git"),
        E("dsh-review-3", "dsh-review", "把同一个 diff 同时交给多个评审者——已安装的 CLI 编程智能体（codex、claude 等）或 DSH 子智能体——各自成节，合并为一份报告；评审者与命名评审模式在设置界面里配置。", "text", 1, "git"),
        E("dsh-review-loop", "dsh-review-loop", "增量代码审查插件：批准一批改动后只审查检查点之后的新改动，提供 Web 审查面板与 `/review` 命令，并把审查意见注入回 agent。", "git", 1, "git"),
        E("dsh-review-squad", "dsh-review-squad", "通过 /review 命令或 code_review 工具并行派出只读评审员子代理小队（安全、正确性、测试、风格，各自可指定不同模型），并汇总为按严重度分组的结构化评审报告。", "net", 1, "git"),
        E("dsh-skill-7d-git-commit", "dsh-skill-7d-git-commit", "提交前按 7DGroup 规范校验 git commit message（中文类型标签、长度与标点规则），作为 GitLab pre-receive 钩子的客户端前置校验。", "git", 1, "git"),
        E("dsh-tool-github", "dsh-tool-github", "GitHub REST API 工具 + 浏览器侧边栏面板：仓库/搜索/Issue/PR/评论、账号绑定（凭据库）与一键克隆为工作区。", "git", 1, "git"),
        E("dsh-wending-git-workbench", "dsh-wending-git-workbench", "Codex 风格 Git 工作台：工作区级更改、diff、暂存、提交、受守卫的分支操作、提交图谱、fetch、pull --ff-only 与经官方插件 API 的上游推送。", "git", 1, "git"),
        E("dsh-workspace-snapshot", "dsh-workspace-snapshot", "以结构化数据返回有界、相对仓库根的 Git 状态，不暂存、不提交，也不切换分支。", "git", 1, "git"),
        E("dsh-worktree-studio", "dsh-worktree-studio", "面向 DeepSeek Harness 的人工 Git worktree 任务工作台，将验证结果绑定到合并交付。", "git", 1, "git"),
        E("harness-github", "harness-github", "DSH GitHub 连接器:检查 PR、分诊 issue、调试 CI、准备代码变更(18 个工具,gh 优先 + REST 回退,写操作人工审批)。", "misc", 1, "git"),
        E("5530", "dsh-video-notes", "把 B 站视频下载、本地 whisper.cpp 转写、再用 DSH 自身 LLM 生成结构化 Markdown 笔记（可打印为 PDF）的 agent 工具。仅支持 Windows：缺依赖时自动下载到数据目录——yt-dlp.exe 与 ffmpeg.exe（GitHub、gyan.dev）、wh", "pdfdoc", 0, "tools"),
        E("ai-residue-cleaner", "ai-residue-cleaner", "把 AI 会话留下的草稿、备份、日志、缓存收进可逆回收站；项目结项时归类成品、归档可引用结果并生成结项清理清单，未结项期间一切保留。清运引擎是 Python 脚本，需 PATH 上有 Python 3（自动探测 python3 / python / py；缺了它清运跑不起来，会明确提示）。", "archive", 0, "tools"),
        E("artifact-center", "artifact-center", "跨会话产物中心：agent 产出重要文件时用工具登记（默认复制一份到统一目录），侧边栏面板按分类、后缀或关键词即时筛选。", "fileops", 0, "tools"),
        E("axiom-dre-dsh", "axiom-dre-dsh", "为 dsh 提供确定性推理引擎（DRE）：dre__* 工具覆盖知识验证（三段甄别）、确定性认知闭环、约束求解、心智模型与突触记忆，强化信息确定能力。", "session", 0, "tools"),
        E("axiom-kb-dsh", "axiom-kb-dsh", "为 dsh 提供知识库（Vault 记忆 + 知识图谱）：kb__* 工具覆盖确定性记忆检索/写入、知识图谱节点/边/子图/遍历、文档入图谱与跨存储统一查询（KAL），不含联网检索工具。", "session", 0, "tools"),
        E("bilimemory", "BiliMemory", "把本地 BiliMemory 接入 DSH，支持 B站搜索、视频采集、任务状态、登录管理、A-Memorix 共用记忆状态检查，以及 QQ 链接监听状态、QQ 白名单和监听重启。仓库提供 Windows 一键部署器，可在 A-Memorix 缺失时自动安装或修复，并配置 local-bge-smal", "git", 0, "tools"),
        E("calendar", "calendar", "dsh 的日历集成 bundle：CalDAV + iCalendar + RRULE 日程管理，内置农历/节假日等中文场景支持、冲突检测与提醒工具。", "time", 0, "tools"),
        E("caopazi", "caopazi", "南京林业大学 ACM AI Hub 每日签到与该校图书馆座位预约（两个站点地址写死），带设置页与完成度角标；面向 Android 上的 DeepSeek Harness Mobile。", "misc", 0, "tools"),
        E("ccreach-dsh-web-search", "ccreach-dsh-web-search", "让 DeepSeek Harness 的 Agent 检索 CCReach 能力目录（数据源、工具、API、MCP、技能与工作流）。", "fileops", 0, "tools"),
        E("cua-computer-use", "cua-computer-use", "把 Cua Driver 的 MCP 服务器接入 DSH：缺失时自动安装 cua-driver，经内置 MCP 客户端以 stdio 启动，注册其 60 个无障碍优先的窗口、输入、菜单与浏览器工具，并附带工作流技能与一次性的 macOS 权限引导。", "devops", 0, "tools"),
        E("deepclean-mydisk", "deepclean-mydisk-plugin", "电脑清理工具：磁盘清理、空间清理、Mac清理、Windows清理；缓存、残留与相似照片，扫描只读，清理先移入废纸篓或隔离区并可撤销。", "image", 0, "tools"),
        E("dragonfly-chatbot", "dragonfly_chatbot", "面向 DSH 0.2.1-rc.2（engines.dsh 精确钉版）。基于 Dragonfly 3D World 2027.1 帮助文档和本机安装源码的只读检索提供技术支持，未发现安装时明确提示仅帮助文档模式。", "misc", 0, "tools"),
        E("dsh-2", "pricewin-dsh", "通过远程 PriceWin MCP 服务器（无需账号或 API key）实时比较 Booking.com、Agoda、Trip.com、Traveloka 等预订网站的酒店与机票价格，并附带旅行搜索 skill。在 Web 界面中结果以卡片呈现：酒店照片、评分、整段住宿总价及各网站带链接的价格；航班", "image", 0, "tools"),
        E("dsh-3d-director-desk", "dsh-3d-director-desk", "DSH 右侧栏 3D 导演台插件：摆角色、运镜、时间轴预演与导出，AI Agent 经 MCP 工具实时编排场景。", "time", 0, "tools"),
        E("dsh-a11y-scan", "dsh-a11y-scan", "原生 WCAG 无障碍扫描工具：对本地 HTML / 构建产物 / URL 运行 axe-core，输出规则 id、impact、WCAG 2.1 映射、元素定位与修复建议（Markdown/HTML/JSON），只读可进 CI。", "pdfdoc", 0, "tools"),
        E("dsh-adaptive", "dsh-adaptive", "DSH 版本自适应：自检当前运行时版本，按 DSH 自己的规则（engines.dsh 优先，否则检查 @deepseek-ai/dsh* peer；预发布参与比较；精确版本例外）逐条判定已装插件，并用官方 release notes 摘出的规则标出源码里仍在使用 v0.1.6 起已改名/弃用接口的", "misc", 0, "tools"),
        E("dsh-aesthete-agent", "dsh-aesthete-agent", "前端美学引擎的 17 个原生工具：118 块实证色板按语域选板、跨语域整页方向对比、四道机械检查（对比度、色盲、AI 味、评分）带指纹绑定，另有设计令牌表、页面审计、图表色板、中文字阶、渲染对账与量化叙事。全部本地运行，零联网。需 Python 3.8+。", "misc", 0, "tools"),
        E("dsh-agent-frugality", "dsh-agent-frugality", "多智能体防内耗防御插件：读取台账去重度量、免疫压缩规则区、完成机械门禁、低成本审查 lane。", "archive", 0, "tools"),
        E("dsh-agent-import", "agent-import", "把 Codex 与 Claude Code 已声明的 MCP 服务器接入 dsh 的 mcp-client，把 22 个已知 Agent 技能目录的技能以符号链接（不复制文件）导入 ~/.dsh/skills，并提供设置页：列出本次实际挂载的服务器与技能、逐项启停技能、重名时改选来源。", "fileops", 0, "tools"),
        E("dsh-agent-picker", "cwk", "DSH 的 Agent 模式选择器：在输入框旁边直接选定一个外部 Agent CLI（Claude Code、Codex、 Qwen Code、Gemini CLI、Aider、Goose、Hermes…）作为当前会话的默认执行体，不必去改配置文件。 Agent 名册是数据驱动的，已安装的 CLI", "fileops", 0, "tools"),
        E("dsh-agents-visualization", "dsh-agents-visualization", "在 DSH 设置页查看、创建与编辑 AGENTS.md 等 AI 规则文件：项目级跟随工作区从项目根到 cwd 的目录链，全局级覆盖 ~/.dsh 与 ~/.agents，另含 25 个第三方 AI 工具的用户级规则文件。预览以渲染态展示并自动剥离 .mdc 的 frontmatter，就地编辑并带", "fileops", 0, "tools"),
        E("dsh-ai-armor", "dsh-ai-armor", "五个生产级 DSH 工具合一的 bundle（共 8 个 tool slot）：git 回归定位（引入者反查、最近改动、二分定位、blame 年龄）、带本地代码上下文的堆栈解码器、YAML/ENV/properties 配置校验器（带近似键名提示）、跨平台 shell 转义（POSIX/PowerS", "git", 0, "tools"),
        E("dsh-ai-courses", "package", "把学习诉求和手头资料变成结构化、纯本地的 AI 课程，含大纲、知识点内容、图表与学习进度。", "misc", 0, "tools"),
        E("dsh-ai-jobs", "dsh-ai-jobs", "索引海外 AI 公司的公开招聘看板（Greenhouse、Ashby、Lever、Workable、SmartRecruiters），按 AI 相关性给岗位打分，从职位描述里提取招聘要求，并按计划每天生成 Markdown 摘要。", "pdfdoc", 0, "tools"),
        E("dsh-ai-research", "dsh-ai-research", "DSH 的 AI 研究工具箱：模型发布雷达、单模型跑分与口碑体检（13 路结构化榜单 + 中英文社区讨论）、覆盖 46 个 Feed 与 22 个官方 X 账号的 AI 新闻雷达；注册 4 个工具 + 3 个技能，报告统一渲染为带目录的 Markdown。", "pdfdoc", 0, "tools"),
        E("dsh-aiyting-image-video", "dsh-aiyting-image-video", "把 DeepSeek Harness 接到 AIyting 的生图 MCP 端点，注册四个工具：aiyting_image_catalog（模型、线路与规格）、aiyting_image_settings（读取、报价与保存参数）、aiyting_image_generate（先返回报价，只有显式给出", "ai", 0, "tools"),
        E("dsh-algo-trainer", "dsh-algo-trainer", "算法学习工具：同步 Codeforces 与 AtCoder 提交记录，分析弱项画像， AI 生成训练计划，间隔复习排期，覆盖 114 课算法模板库。", "git", 0, "tools"),
        E("dsh-alist", "dsh-Alist-", "AList v3 文件管理插件：浏览、搜索、上传（本地文件流式与 multipart）、离线下载、压缩包查看、任务轮询与控制，以及存储、用户、角色、元数据、站点设置、搜索索引、分享、标签等管理端操作，共 75 个工具；全部写操作强制走审批，密码与 Token 只写不读。", "archive", 0, "tools"),
        E("dsh-anlayzer", "dsh-anlayzer", "此插件定位DeepSeek Harness代理会话失败的根本原因，并生成可共享的诊断报告。", "net", 0, "tools"),
        E("dsh-anysearch", "dsh-anysearch", "给 agent 用的 AnySearch 搜索工具：通用与垂直域搜索、并行批量查询、垂直域目录发现、网页转 Markdown，并在设置中提供 API Key 面板。它注册独立工具而非 web_search provider，不能与 @anysearch/anysearch-dsh 同时安装。", "pdfdoc", 0, "tools"),
        E("dsh-aoci-bind", "dsh-aoci-bind", "DSH Host 侧 AOCI 接入工具：发现带 AOCI 索引的工作区、诊断与修复 MCP 绑定、初始化未接入仓库，并提供状态与体检工具。", "git", 0, "tools"),
        E("dsh-api-contract", "dsh-api-contract", "DeepSeek Harness 的 API 契约工作室：开工前先定七件事、写/审 OpenAPI、按「客户端具体坏在哪」分类破坏性变更，再定错误结构、版本与弃用——六本手册加一个路由。", "misc", 0, "tools"),
        E("dsh-apis-plugin", "dsh-apis-plugin", "把任意一套 HTTP 接口注册成 agent 可用的文档查询与请求双工具。", "ai", 0, "tools"),
        E("dsh-app-updater-1", "dsh-app-updater", "侧边栏按钮：启动时自动检查DSH更新并显示红点提示，支持忽略特定版本、预览更新日志，带实时下载进度、国内镜像加速和下载安全校验。", "net", 0, "tools"),
        E("dsh-appdata-scanner", "dsh-appdata-scanner", "只读的 Windows AppData 分析插件：点侧边栏图标后以资源管理器式逐层下钻，每行显示目录的递归体积、文件数与最后修改时间，并说明由哪个软件生成、作何用途，按「知识库 → 混合目录拆分 → 启发式 → 标注为推测」的顺序给出可删建议；只统计目录、不读取文件内容，也不提供任何删除操作，未知目", "time", 0, "tools"),
        E("dsh-applauncher", "dsh-applauncher", "扫描本机已安装的 Windows 应用，在侧边栏设置图标上方提供一键启动。", "misc", 0, "tools"),
        E("dsh-aqua-input-check", "dsh-aqua-input-check", "水产养殖投入品记录完整性与休药期日期核对：按规则 ID 输出确定性发现。", "time", 0, "tools"),
        E("dsh-artifacts", "dsh-artifacts", "把 Markdown + JSON 渲染成自包含 HTML 文档/卡片/仪表盘/画廊（CLI + 内置 artifact_render 工具）。", "pdfdoc", 0, "tools"),
        E("dsh-as-mcp", "dsh-as-mcp", "把正在运行的 DeepSeek Harness 暴露为 MCP server（Streamable HTTP，或附带的 stdio 桥），外部 agent 可创建 workspace 与会话，发起 prompt、fork、重命名、切换模型，读写文件，运行前台与后台 shell 命令，按名调用该实例自", "fileops", 0, "tools"),
        E("dsh-asciinema", "dsh-asciinema", "把终端/工具输出录制为 asciinema v2（.cast）文件，离线内嵌播放器回放并导出 HTML。", "fileops", 0, "tools"),
        E("dsh-asimovbox", "dsh-asimovbox", "通过 API 密钥认证的工具将 DeepSeek Harness 连接到 AsimovBox，用于创建、更新、渲染和完成视频。", "media", 0, "tools"),
        E("dsh-babel", "dsh-babel", "读取 Claude Code 和 Codex 插件配置，发现并预检 MCP 服务器与斜杠命令，支持在 DeepSeek Harness 中按需启用注册。", "devops", 0, "tools"),
        E("dsh-baidu-netdisk", "dsh-baidu-netdisk", "百度网盘 MCP 插件，支持在 DeepSeek Harness 中搜索网盘文件、查看文件信息和查询容量。安装后需授权百度账号。", "fileops", 0, "tools"),
        E("dsh-balance-inquiry", "dsh-balance-inquiry", "余额看板，可以添加多个按量计费/Token plan，同时查询余额。", "ai", 0, "tools"),
        E("dsh-bangumi", "dsh-bangumi", "DSH 追番订阅管理器：Bangumi 查番、nyaa/dmhy 搜种、qBittorrent 自动下载（RSS 判新轮询）、本地媒体库查重，附日历/进度侧边栏 GUI 与 11 个 LLM 工具（bangumi_lookup / bangumi_search / bangumi_subscribe", "net", 0, "tools"),
        E("dsh-basemind-plugin", "dsh-basemind-plugin", "按会话工作区启动 BaseMind MCP server，并注册其对外提供的代码智能工具，无需配置 MCP 行。需先安装 BaseMind 并在 PATH 上（basemind serve）；否则不会注册任何工具。", "session", 0, "tools"),
        E("dsh-bash-terminal-ts", "dsh-bash-terminal-ts", "一个 shell 工具：Windows 上支持 PowerShell / Git Bash / WSL / MSYS2 四种后端，外加交互式 PTY 终端；MSYS2 后端以 bash.exe -lc 启动，让 /etc/profile 把 /usr/bin 与 /mingw64/bin 带进 PA", "git", 0, "tools"),
        E("dsh-bili-whale-safever-by-jediliu", "dsh-bili-whale-safever-by-jediliu", "DSH 的 B 站养鱼插件（Alterssss/dsh-bili-whale 的 MIT 分叉；不要与上游 dsh-bili-whale 同装——两者注册同一套 `/dsh-bili/` 设置路由并共用 `~/.dsh/bili-whale.config.json`）：按作息自己醒来，靠字幕、弹幕、", "data", 0, "tools"),
        E("dsh-blender-1", "dsh-blender", "在 DeepSeek Harness 里以 headless 方式跑 Blender：执行 bpy 脚本、渲染场景、导出 glTF 资产，并附带建模技法库、5.x 踩坑清单与资产管线手册（技能包），让 agent 在交付前自检几何。", "ai", 0, "tools"),
        E("dsh-blender-mc", "dsh-blender-mc", "把 Minecraft Java 存档变成 Blender 封面或动画：在 .mca 区域文件里找大片平地，导出地形为 OBJ，无头驱动 Blender（MCprep 材质、BPS 角色骨架、三点布光）。每次渲染后用 OpenCV 检查朝向、接地、曝光、布光和构图，不合格就调整参数重渲。需 Blen", "media", 0, "tools"),
        E("dsh-blender-mcp-bridge", "dsh-blender-mcp-bridge", "此项目旨在桥接 Blender MCP Add-on，使 DSH 上的模型可便捷对接接入当前用户工作的 Blender 以辅助创作，且满足基础安全需要。", "ai", 0, "tools"),
        E("dsh-booth-search", "dsh-booth-search", "在会话旁的 BOOTH 独立页或两个只读工具里搜 VRChat 素材（衣服、着色器、素体、配饰、贴图、动画、小物）；中文关键词在宿主侧转日文再检索，界面不出现日文词。", "session", 0, "tools"),
        E("dsh-bowmark", "dsh-bowmark", "接入 Bowmark 托管的 MCP 服务器并注册它公布的工具，让智能体搜索并调用面向实时网站的类型化函数库。API Key 从 BOWMARK_API_KEY 凭据读取，不写入插件配置。", "search", 0, "tools"),
        E("dsh-brake", "dsh-brake", "DSH 会话死循环刹车器：检测重复的相同工具调用、循环的调用序列与重复文本，提醒 agent 或在执行前拒绝调用。", "session", 0, "tools"),
        E("dsh-calculator-1", "dsh-calculator", "为 agent 提供 calculate 工具，内置零依赖表达式解析器（不用 eval），支持批量求值与金额精确小数模式。", "data", 0, "tools"),
        E("dsh-canteen-retention-check", "dsh-canteen-retention-check", "核对食堂留样台账的四个记录要素、125 克下限、48 小时冷藏窗口，以及单元格中残留的模板占位符。", "misc", 0, "tools"),
        E("dsh-capability-composer", "dsh-capability-composer", "能力组合：把工具、技能与 MCP 编成可切换的组合，按需缩小常驻工具面与系统提示。", "misc", 0, "tools"),
        E("dsh-capability-gateway", "dsh-capability-gateway", "把选定代管的第三方技能与 MCP 服务器从原生工具目录收起，改由单个 capability 工具统一提供：按意图搜索、读 schema 或技能说明，再调用。本地日志只记录元数据，不记录查询文本与参数。", "data", 0, "tools"),
        E("dsh-ccf", "dsh-ccf", "用 ccf_deadlines、ccf_venue、ccf_update 三个工具、/ccf 命令和可导出日历的桌面面板查 CCF 会议截稿：日期靠实时同步（CCFDDL 为主、另一个源交叉比对，差 36 小时以上标「来源冲突」），插件本身不内置任何日期，首次使用需先同步一次；未来 30 天的截稿会", "time", 0, "tools"),
        E("dsh-checkin-workbuddy", "dsh-checkin-workbuddy", "常驻输入框工具行的 WorkBuddy 每日签到按钮，一键调用 dsh-connect-workbuddy 的签到路由为当前选中账号签到，并在按钮旁显示结果：已签到、签到成功加分或连签天数。已签状态通过本地日期戳跨会话保留，加载时与上游状态对账，跨天后自动复位。", "time", 0, "tools"),
        E("dsh-claude-code-sdk", "dsh-claude-code-sdk", "需本机已安装并登录 Claude Code。通过 Claude Agent SDK 把编码任务委派给本机 Claude Code，报告改动文件、支持一键回退，并在输入框旁提供「Claude 模式」开关。", "codec", 0, "tools"),
        E("dsh-claude-codex-mode", "dsh-claude-codex-mode", "讨论阶段只读，改仓库代码一律交给 Codex CLI（插件自带 MCP server）；在插件表单里可在 DSH 主模型与 Claude Code CLI 之间切换，带前置检查，并用写文件 guard 拦截对仓库文件的结构化写入。", "git", 0, "tools"),
        E("dsh-claude-delegate", "dsh-claude-delegate", "把自包含的编码子任务委派给本机 Claude Code（官方 Agent SDK 驱动），结果回传主会话：19 个参数可按次控制模型、思考强度、权限模式、允许工具、轮次与预算上限；后台作业立即返回 jobId 并支持增量读取；结果附会话句柄，传回 resume 即可在同一会话续跑；预计超过 20 秒", "codec", 0, "tools"),
        E("dsh-claude-desktop", "dsh-claude-desktop", "用桌面端自己的 claude:// 深链把活派过去：开新 Claude Code 会话（带 prompt、目录）、带文件开 Cowork 任务、把 CLI 会话 id 交回应用；再代按 Ctrl+Enter 发送，并从本机 Claude Code 的 transcript（~/.claude/pro", "fileops", 0, "tools"),
        E("dsh-claude-pilot", "dsh-claude-pilot", "把本机 Claude Code CLI 接成 DSH 的三个工具（claude_run / claude_resume / claude_probe），解析 --output-format json 并返回可续接的 session id，另带独立回环桥。", "data", 0, "tools"),
        E("dsh-clickhouse", "dsh-clickhouse", "DSH 的 ClickHouse 数据问答工具：七个工具负责列库表字段、抽样、按字段名反查、看 EXPLAIN 计划，以及执行带客户端只读护栏的单条 SQL（拒绝写操作、多语句、跨表查询与外部表函数）。默认单表查询：用户给什么参数就用什么参数，不内置任何多步业务流程。零运行时依赖；遇到老版本服务器会", "data", 0, "tools"),
        E("dsh-clipfile", "dsh-clipfile", "在输入框附加文件和文件夹：剪贴板粘贴、原生文件/文件夹选择器、@-mention 路径搜索；文件夹转分页 Markdown 供智能体逐页读取。仅支持 macOS（剪贴板读取与选择器依赖 osascript）。", "pdfdoc", 0, "tools"),
        E("dsh-code-intel", "dsh-code-intel", "用 Tree-sitter 建立工作区符号索引，提供词法或可选 embedding 辅助的代码检索。", "ai", 0, "tools"),
        E("dsh-code-navigator", "code-navigator", "为 DeepSeek Harness 提供持久化的 C/C++、Python 和 TypeScript 定义跳转及独立工作区界面。", "misc", 0, "tools"),
        E("dsh-codebase-memory", "dsh-codebase-memory", "codebase-memory-mcp 的代码知识图谱桥：语义符号搜索（BM25）、源码片段、Leiden 社区架构总览、调用/数据流/跨服务追踪、图增强 grep。", "search", 0, "tools"),
        E("dsh-codegraph-2", "dsh-codegraph", "将当前工作区索引为关系图，向 agent 暴露一个工具 codegraph_explore（可达性、调用者、影响面），并在 Web 右侧栏提供图形面板。", "ai", 0, "tools"),
        E("dsh-codegraph-plugin", "dsh-codegraph-plugin", "将 Codegraph CLI 封装为 DSH 的八个代码智能工具：符号搜索、调用者/被调用者、影响分析、代码库探索、符号/文件读取、索引状态与同步。", "fileops", 0, "tools"),
        E("dsh-coderag", "dsh-coderag", "以 MCP 服务器形态提供的代码库检索引擎：四个工具（code_search、code_outline、code_index、index_status），底层是 SQLite FTS5 索引 + BM25 排序 + 中文 bigram 索引，tree-sitter 按声明边界分块、增量重建索引，并带", "data", 0, "tools"),
        E("dsh-codex-pilot", "dsh-codex-pilot", "把本机 Codex CLI 接成 DSH 的四个工具（codex_run / codex_resume / codex_queue / codex_probe），另带独立的回环桥：HTTP 接口 + 文件信箱。", "fileops", 0, "tools"),
        E("dsh-comfyui", "dsh-comfyui", "ComfyUI 在 DeepSeek Harness 里的生产包：向本地或远程服务提交 API 格式工作流、批量出图并取回产物，附实测参数区间与崩图排查决策树（黑图、主体重复、彩边、显存不足）。", "git", 0, "tools"),
        E("dsh-comfyui-control", "dsh-comfyUI-control", "新增「绘图模式」Agent 预设，含 19 个 comfyui_* 工具：Anima/Krea2 出图、LoRA 检索与下载、Danbooru 角色 tag、PNG 元数据、上游复刻自检、小番茄解混淆。", "image", 0, "tools"),
        E("dsh-computer-use-2", "dsh-computer-use", "Linux X11 电脑控制插件：9 个工具（截图、鼠标移动/点击/拖拽/滚轮、输入、快捷键），由零依赖 Python XTest 助手驱动——原生像素坐标、每次操作返回坐标校验、可选自动截图。", "image", 0, "tools"),
        E("dsh-computer-use-4", "dsh-computer-use", "为 DeepSeek Harness 提供 computer use：js 与 js_reset 工具通过本机安装的 ChatGPT 应用读取窗口、点击、输入与截屏（macOS）。仅 Apple Silicon macOS，需已装 ChatGPT 桌面版。", "image", 0, "tools"),
        E("dsh-computer-use-en", "dsh-computer-use-en", "Windows 电脑控制插件（英文版）：提供 10 个桌面控制工具（截图、鼠标、键盘、UIA 界面元素读取、剪贴板、窗口管理、应用技能与按应用授权），全英文设置面板与右下角迷你进度卡片浮层，支持按 Esc 暂停或继续，并适配 DSH 0.2.1 的 koffi.node 自动发现。Fork 自 co", "image", 0, "tools"),
        E("dsh-computer-use-next", "dsh-computer-use-next", "基于 CuaDriver 的 macOS 跨应用桌面工具，默认隐藏虚拟光标，支持后台窗口选择和操作后界面回读。", "misc", 0, "tools"),
        E("dsh-computer-use-windows-1", "dsh-computer-use-windows", "Windows 桌面操作插件，提供绑定窗口的截图与无障碍状态、文本回读、DSH 审批和操作提示层。", "image", 0, "tools"),
        E("dsh-config-sync", "dsh-config-sync", "基于私有 Git 仓库的 DSH 多端配置同步——把设置、插件清单、锁文件与技能纳管到私有仓库，设置页一键捕获、应用、拉取与回滚，并按 pnpm-lock 确定性重建插件依赖。", "git", 0, "tools"),
        E("dsh-connect-atomcode", "dsh-connect-atomcode", "用你本机已登录的 AtomGit 免费额度，请 AtomCode 给代码做一次独立代码审查：模型通过`atomcode_ask` 工具自主调用审查；你也可以使用`/atomcode-review`命令，一键评审未提交改动 / 分支 / PR。本插件不读取 API key；输入框下方有用量胶囊显示 C", "git", 0, "tools"),
        E("dsh-connectors-1", "desktop-connector", "Windows 桌面控制连接器：通过 10 个工具截屏（含被遮挡与半出屏窗口）、枚举与置顶窗口、移动/点击/拖拽/滚轮鼠标、发送组合键与任意中文文字。基于 koffi FFI：无需编译器、不每次起子进程，自带 GDI 截图与 PNG 编码。", "image", 0, "tools"),
        E("dsh-console", "dsh-console", "dsh 控制台命令：/web 启动/停止/重启/状态、/tunnel SSH 隧道管理、/ask 一次性问答、/console 启动控制台 TUI。", "devops", 0, "tools"),
        E("dsh-console-sentinel", "dsh-console-sentinel", "监控 Windows 控制台窗口，自动隐藏或关闭「空壳」控制台——解释器进程除 conhost / openconsole 外没有任何业务子进程、且长期 CPU 接近 0 的窗口。同时识别传统控制台与 Windows Terminal（CASCADIA）中只挂着裸 cmd / powershell", "sysinfo", 0, "tools"),
        E("dsh-construction-doc-check", "dsh-construction-doc-check", "按项目资料归档要求检查缺失的必需资料类型、过期版本与空文件；只读文件夹与文件名，不读文档内容。", "archive", 0, "tools"),
        E("dsh-context-archive", "dsh-context-archive", "模型驱动的工具结果归档插件。超过阈值的结果会带一个短内联编号（\\[#a1b2c3d4]），模型把不再需要的 结果归档进会话自己的 archives/ 目录，上下文里只留一个可回捞的小存根（含文件路径）。原文同时保留在 只增的会话日志中，不会丢失。附带设置面板：按大小分桶的回收统计、改完立即生效的阈值", "archive", 0, "tools"),
        E("dsh-context-extract", "dsh-context-extract", "为 DeepSeek Harness 注册一个 `context_extract` 工具：把长篇原始文件（财报底稿、合同、台账）压成高密度结构化 Markdown + JSON——关键指标、表格、条款切分、实体与勾稽 alert，让下游流程直接基于压缩结果工作，而不是重读原文。财报 / 合同 / 台", "pdfdoc", 0, "tools"),
        E("dsh-cool-terminal", "dsh-cool-terminal", "终端插件 — 真 shell、工作区同步、状态常驻、常用命令管理、命令补全。", "misc", 0, "tools"),
        E("dsh-copy-tool", "dsh-copy-tool", "提供按行复制工具，可替换或插入文件片段，并支持缩进控制和 diff 预览。", "fileops", 0, "tools"),
        E("dsh-cost-ledger", "dsh-cost-ledger", "可核对的 token 成本账：包住 llm/stream waterfall，逐次记录 provider、model、输入/输出/缓存命中/缓存写入 token、用量来源，以及按显式价目表算出的整数 nano-CNY 费用；按小时/日/会话聚合，支持 JSON/CSV 导出与不落盘的 dry-run", "data", 0, "tools"),
        E("dsh-countdown-days", "dsh-countdown-days", "记录倒数日和重复日期，并可设置提醒。", "time", 0, "tools"),
        E("dsh-cpa", "dsh-cpa", "在 DeepSeek Harness 内直连 ChatGPT Codex，管理授权、模型同步和额度显示，无需本地代理进程。", "net", 0, "tools"),
        E("dsh-cpp-probe", "dsh-cpp-probe", "Windows + CDB 下的 C++ 运行时信息探针：cpp_trace 一次会话多断点打印变量（替换手打 print），cpp_probe 条件断点输出调用栈。安装：dsh plugin --profile web add dsh-cpp-probe。", "fileops", 0, "tools"),
        E("dsh-cua-drive", "dsh-cuadrive-mac", "通过插件独立管理的 Cua Driver 运行时提供 macOS 电脑操作工具。", "misc", 0, "tools"),
        E("dsh-cua-driver-indicator", "dsh-cua-driver-indicator", "给官方内置 Cua Driver 电脑控制通道加一层可见提示：顶部横幅显示是哪个会话、基于什么目标在控制电脑，按 Esc 真正停止。", "session", 0, "tools"),
        E("dsh-cubox", "dsh-cubox", "Cubox 收藏同步：定时同步收藏，按你的 prompt 用 LLM 生成今日收藏简报直接写入 Obsidian，可导出每张收藏为 Markdown。", "pdfdoc", 0, "tools"),
        E("dsh-cuda", "dsh-cuda", "在 DeepSeek Harness 里直接跑本地 NVIDIA CUDA GPU 的 Python 任务：设备状态、前台/后台作业、持久日志、每次运行实测的峰值显存。", "devops", 0, "tools"),
        E("dsh-cursor-toolkit", "cursor-cli", "把编码任务交给本机 Cursor CLI 代理在工作目录中执行，并可按 chat id 续跑。", "codec", 0, "tools"),
        E("dsh-custom-tool-studio", "dsh-custom-tool-studio", "用 Python 在网页、对话或 dsh-go 手机 App 的原生面板里编写自定义工具，保存后免重启注册成 DSH 工具；危险工具每次执行都走内置审批，工具可分组成包，还可选「解锁模式」按对话逐步放出。需 PATH 中有 Python 3。", "session", 0, "tools"),
        E("dsh-customs-doc-check", "dsh-customs-doc-check", "报关单证一致性检查：按规则 ID 输出字段级发现。", "data", 0, "tools"),
        E("dsh-cyber-amber", "dsh-cyber-amber", "在 Windows x64 上下载视频，或将链接及本地片段制作为可指定体积上限的 GIF。", "image", 0, "tools"),
        E("dsh-d1", "dsh-d1", "Cloudflare D1 数据库工具：d1_list/query/exec/schema/stats/health，通过 D1 HTTP API 访问，默认只读（SQLite 语义的词法级只读保护）、LIMIT 行数上限、CSV/JSON 查询输出与写审批门。", "data", 0, "tools"),
        E("dsh-daoyi-yijing", "dsh-daoyi-yijing", "道一-易经推演：通用决策评审 DSH 插件（决策辅助，非迷信）。六层加权聚合引擎（384爻→64卦→8宫→四象→三才→两仪→太极），强关联一票否决，内置电机设计/股票趋势/商业成功率剧本，纯 JS 零求解器依赖。免费档每日限 9 次推演，激活码可提升；stock-trend 剧本会按请求里的股票代码", "misc", 0, "tools"),
        E("dsh-data-agent-1", "dsh-data-agent", "DeepSeek Harness 的数据库连接与 SQL 插件：注册数据源，浏览并注释表结构，通过 AST 校验执行 SQL（每个数据源可单独切换只读），并渲染柱状图、折线图和饼图，可在对话或设置页中使用。", "data", 0, "tools"),
        E("dsh-data-curation", "dsh-data-curation", "用于数据核对与清洗的 dsh 插件：原始材料保持只读，一格数据只有在多个独立校验一致后才被接受，每个接受值都保留来源与审计痕迹。", "text", 0, "tools"),
        E("dsh-database", "dsh-database", "DeepSeek Harness Web 数据库插件：统一管理 MySQL、MariaDB、PostgreSQL、SQL Server、Oracle 和 MongoDB 连接，让 Agent 按会话授权探索数据结构、执行只读查询并辅助数据分析。", "data", 0, "tools"),
        E("dsh-database-preview", "dsh-database-preview", "在右侧边栏只读预览 SQLite 文件与 MySQL / MariaDB / PostgreSQL / SQL Server 连接：表、分页数据、列、索引，列宽可拖动，从不写库。", "data", 0, "tools"),
        E("dsh-db", "dsh-db", "MySQL/PostgreSQL 数据库连接管理，带库表字段树、表名搜索、SQL 补全控制台，以及列出连接、搜索表、查看结构和执行 SQL 的四个 Agent 工具。", "data", 0, "tools"),
        E("dsh-db-connect", "dsh-db-connect", "管理 Oracle、PostgreSQL、MySQL、MariaDB、SQL Server 与 SQLite 连接，提供驱动诊断、字段默认值/注释和需显式授权的智能体元数据浏览；需另建 Python 3 环境并安装对应驱动（SQLite 仅需标准库）。", "data", 0, "tools"),
        E("dsh-decisiontools", "dsh-decisiontools", "可选 Decision API 工具预发现与搜索来源预读，支持会话开关和普通按需发现回退。", "search", 0, "tools"),
        E("dsh-deepseek-billing-period", "dsh-deepseek-billing-period", "在输入框下方显示 DeepSeek API 当前计费时段（高峰/空闲）与距下次切换的倒计时，点击可展开高峰/空闲时段规则；高峰时段发送消息前会先拦截并弹出确认。", "time", 0, "tools"),
        E("dsh-deepseek-model-router", "dsh-deepseek-model-router", "自动切换 DeepSeek 模型：含图片时走视觉模型，复杂任务走 pro，常规任务走 fast；提供 switch_model 工具手动固定。", "image", 0, "tools"),
        E("dsh-delivery-receipt", "dsh-delivery-receipt", "项目收尾用的交付回执面板。触发一次即汇总分支与 commit、测试与构建结果、截图的宽高与 sha256、密钥扫描结论，然后只按证据把每一条分进三区：已验证、仅本地、未验证。落在未验证区的声明只保留标签，正文位置显式留空而不是把声明印出来——措辞自信而背后什么都没有的句子，正是回执要防的东西。测试失", "git", 0, "tools"),
        E("dsh-dep-vuln-scan", "dsh-dep-vuln-scan", "扫描项目锁文件（npm/pnpm/yarn/pip/go/cargo/maven/gradle…）并对免费 OSV API 批量查询漏洞，输出「包 / 当前版本 / 漏洞 ID / 摘要 / CVSS / 修复版本」表格与修复命令。", "data", 0, "tools"),
        E("dsh-deskresume", "dsh-deskresume", "重启或断电后恢复 Windows 桌面：快照已打开的程序、文档、文件夹与窗口位置，可一键重开。仅支持 Windows 10 及以上；关机前自动抓取需先用 collector/install-tasks.ps1 注册两个计划任务。", "net", 0, "tools"),
        E("dsh-desktop-hand", "dsh-desktop-hand", "DSH 的 Windows 桌面控制插件，六个工具：列出窗口、抓取被遮挡窗口、聚焦窗口、按坐标点击、注入 Unicode 键盘输入与诊断桌面桥接。", "image", 0, "tools"),
        E("dsh-desktop-organizer", "dsh-desktop-organizer", "Windows 桌面整理：归类桌面快捷方式、发现未建快捷方式的程序、检测失效链接（1 个模型工具 desktop_organize）。", "fileops", 0, "tools"),
        E("dsh-desktop-uia", "dsh-desktop-uia", "通过 UI Automation 控制 Windows 桌面：九个工具读取窗口控件树、按 id 走控件自身的 UIA 模式操作，每次写入都受审批策略、动作日志与设置面板约束。", "devops", 0, "tools"),
        E("dsh-desktop-yida", "dsh-desktop-yida", "通过 OpenYida CLI 给 Agent 14 个创建、修改钉钉宜搭应用（应用、表单、页面、Schema、数据）的工具，并在右侧栏工作台里用内置浏览器打开查看。", "data", 0, "tools"),
        E("dsh-diagram-design", "dsh-diagram-design", "将 diagram-design 图表导出为 SVG/PNG，提取 draw.io/Mermaid/Excalidraw 结构，校验输出，并浏览 45 种图表类型。基于 cathrynlavery/diagram-design（MIT），需 python3，导出 PNG 还需 Playwright。", "image", 0, "tools"),
        E("dsh-disk-browser", "dsh-disk-browser", "DeepSeek Harness 侧边栏磁盘文件浏览插件：浏览服务器任意目录（含隐藏文件夹），支持文本预览、流式下载与上传（多选/拖拽、同名确认覆盖），桌面与移动端响应式适配。", "net", 0, "tools"),
        E("dsh-dotclaude", "dsh-dotclaude", "在 DeepSeek Harness 里运行 Claude Code 项目的 .claude/ 斜杠命令与 permissions.deny 规则。命令正文会把 $ARGUMENTS、位置参数与 @文件引用展开进模型的下一轮；命中的工具调用在执行前被拒绝。所有宿主服务都做探测：缺命令注册表、工作目录", "fileops", 0, "tools"),
        E("dsh-douyinxiaoqi", "dsh-douyinxiaoqi", "抖音运营插件：用本机真实 Chrome 看推荐、读评论、回私信，把本地视频传进创作者中心；写动作过权限闸，发布永远要你点头。", "media", 0, "tools"),
        E("dsh-draw-mode", "dsh-draw-mode", "把 ComfyUI 接给 agent：五个 draw_* 工具（状态、工作流、模型、生图、反推）与侧栏面板。插件本身不带任何工作流、也不假设你用什么模型：放进工作流目录的每个 API 格式 JSON 都会被自动检查，找出 prompt / 负向提示词 / 宽高 / steps / cfg / 种子", "data", 0, "tools"),
        E("dsh-drawai-vectorizer", "dsh-drawai-vectorizer", "fork 自 fourzkw/dsh-drawai，保留 .drawio 可编辑画布与两个模型工具，并在原版描边之外新增第二套矢量化引擎：分层颜色聚类 + 贝塞尔样条拟合 + 每通道色彩精度，绘制任务可选三档保真度（同一 1920×1080 帧实测约 18 / 38 / 46 dB PSNR（上游引", "ai", 0, "tools"),
        E("dsh-drive-backup", "dsh-drive-backup", "基于 rclone 的备份工具，含四个工具：目标清单、本地/远端状态、rclone check 校验，以及带预演与审计行的审批式 copy/sync 传输。需已安装 rclone 并用 `rclone config` 配好远端；插件不读取 rclone 配置或凭据。", "misc", 0, "tools"),
        E("dsh-drive-manager", "dsh-drive-manager", "Windows 多盘磁盘分工面板：用绿/黄/红标出可清理、需确认、系统占用，核对下载目录，并给出多盘分工与迁移建议。", "net", 0, "tools"),
        E("dsh-eco-indicator", "dsh-eco-indicator", "世界银行开放数据经济指标查询：GDP、通胀、贸易、人口等，无需 API 密钥。", "misc", 0, "tools"),
        E("dsh-enet-review", "dsh-enet-review", "校对嘉立创 EDA 导出的 .enet 网表，检查断链式网络标签、单脚悬空网络、电源轨孤立、引脚名与所连网络极性矛盾、全差分运放反馈接法。", "misc", 0, "tools"),
        E("dsh-engineer-tools", "dsh-engineer-tools", "面向软件工程师的 DeepSeek Harness 插件：注册两个模型可直接调用的 Host Tool——受工作区约束的 `git` 运行器，以及按 lockfile 自动识别 npm/pnpm/yarn/bun 并选择正确动词的包管理器运行器（`dev`）。两者都经 dsh 沙箱 shell 执行", "fileops", 0, "tools"),
        E("dsh-environment-packer", "dsh-environment-packer", "为 Windows DSH 创建包含插件配置、Session、Workspace、已识别外部记忆和 Skills 的私人冷备份；v0.6.0 独立恢复助手规划跨版本迁移到全新目标，检查依赖与数据格式，并在启动验证后提交。", "git", 0, "tools"),
        E("dsh-evidence-check", "dsh-evidence-check", "证据清单齐备性核对：把待证事实映射到证据并输出缺口与规则 ID。", "misc", 0, "tools"),
        E("dsh-excel-reconcile", "dsh-excel-reconcile", "按声明的主键连接两张表，按声明字段与容差比对，输出 Markdown 报告、JSON 结果与差异工作簿。只报告差异，不裁决对错。", "pdfdoc", 0, "tools"),
        E("dsh-exit-code-lens", "dsh-exit-code-lens", "为 exit code 1 表示结果而非错误的 bash 输出（grep 无匹配、diff 有差异、test 为假）补充说明，避免 agent 反复排查。", "text", 0, "tools"),
        E("dsh-feishu", "dsh-feishu", "通过十个工具创建与编辑飞书 / Lark 云内容——多维表格及其记录、把 Markdown 转成原生块的文档、电子表格、知识库、云空间文件与消息，并提供 Base V3 的仪表盘图表与服务端聚合查询。", "pdfdoc", 0, "tools"),
        E("dsh-fengniao-company-search", "dsh-fengniao-company-search", "在对话里直接查中国企业：说出公司名就能拿到工商基本信息、股东、高管、对外投资、工商变更，以及被执行、失信、限制高消费、经营异常、严重违法、行政处罚等司法与经营风险（共 11 类维度）；结果以对话卡片呈现，展开可看字段与原始数据，API Key 在插件页保存到 Harness 凭据库。", "data", 0, "tools"),
        E("dsh-feyagate", "dsh-feyagate", "在 DSH 中安装、守护并自动升级本机 miloco-mcp-server 后台服务，把它的 MCP 工具接入 DSH，并提供服务、账号与授权设置界面。", "misc", 0, "tools"),
        E("dsh-fft-paper-trading", "dsh-fft-paper-trading", "在 DSH 中进行模拟交易，支持 A 股和商品期货，本地账本，内置 FTShare 数据源与 K 线，无需购买 API Key 也可使用日K收盘价练习", "misc", 0, "tools"),
        E("dsh-file-bookmark", "dsh-file-bookmark", "在 DeepSeek Harness 中管理常用的文件书签，支持保存、列出与跳转，并且可以创建常用的项目，包括管理类项目、代码类项目等。", "fileops", 0, "tools"),
        E("dsh-file-convert", "dsh-file-convert", "通过 Agent 工具和拖拽界面在本地转换图片、PDF、数据、音视频及 Office 文件；v1.0.x 适配 DSH Desktop 0.2.1-rc.5，部分转换需要外部工具。", "pdfdoc", 0, "tools"),
        E("dsh-file-handover", "dsh-file-handover", "把本地文件交给任何程序的「打开文件」对话框：等对话框出现、走剪贴板填路径、读回来逐字核对、再点确认。目标必须显式给，每一步都留证据——文件上传、微信发文件、PS 打开都能用它代劳。仅 Windows（依赖 EnumWindows / UI Automation）。", "fileops", 0, "tools"),
        E("dsh-file-upload-local", "dsh-file-upload-local", "本地文件上传：回形针按钮与拖拽上传、按会话隔离存储到 .dsh-uploads，并提供 read_document 工具分页读文本、对图片 OCR。", "image", 0, "tools"),
        E("dsh-firecrawl", "dsh-firecrawl", "通过 Firecrawl Cloud API 把 URL 抓成 LLM 可用 Markdown，或搜索网页并返回结果内容。", "pdfdoc", 0, "tools"),
        E("dsh-fish-notes", "dsh-fish-notes", "把智能体浏览、干活时的碎碎念随手记下来，并在侧栏面板里按时间列出。", "time", 0, "tools"),
        E("dsh-fmea-table-check", "dsh-fmea-table-check", "参照公开的 FMEA 方法标准，核对 FMEA 分析表的要素齐备性，以及严重度、发生度、探测度与风险顺序数之间的算术一致性。只报告不一致之处，不评价各项评分数值是否恰当。", "misc", 0, "tools"),
        E("dsh-folder-timemachine", "dsh-folder-timemachine", "给任意文件夹留下历史时间点并一键回到过去：像 Git 一样有版本历史，但不需要懂 Git，任何文件夹都能用（游戏存档、软件配置目录、散落文档都行）。快照按内容寻址去重，只存真正变化的文件，未变文件不重算哈希；自动存档分两档——实时（fs.watch，最后一次改动静默约 8 秒后存一版，编辑器一次保存", "git", 0, "tools"),
        E("dsh-frecency", "dsh-frecency", "为 DeepSeek Harness 提供常驻索引 grep，以同名遮蔽内置 grep/glob 工具：重复内容检索命中按访问/修改 frecency 排序的内存索引，glob 在可用时对齐内置 ripgrep 语义、不可用时回退索引。", "sysinfo", 0, "tools"),
        E("dsh-freeweb", "dsh-freeweb", "Keyless web-search provider for DeepSeek Harness: Startpage, DuckDuckGo, Exa, and more behind a consensus fan-out.", "archive", 0, "tools"),
        E("dsh-fs-reobserve", "dsh-fs-reobserve", "在 agent 自己的 bash/shell 命令结束后，重新观察该会话此前观察过的文件：自己改文件不再触发 FS_STALE_VERSION，但其他人写入仍会触发。", "fileops", 0, "tools"),
        E("dsh-gemini-tool-schema", "dsh-gemini-tool-schema", "把发给模型的工具 schema 统一归一化成 Gemini function declaration 能接受的 OpenAPI 3.0 子集：每个节点补 type、数组补 items、剔除空 enum 项、内联 $ref，让\"任何一个 MCP 或内置工具不合规\"不再把整包请求打成 HTTP 400。", "data", 0, "tools"),
        E("dsh-genbox-plugin", "dsh-genbox-plugin", "通过本地 GenBox 服务生图、改图、生视频，并用 ffmpeg 本地剪辑；自带零成本测试台。", "media", 0, "tools"),
        E("dsh-genspark", "dsh-genspark", "将 Genspark 能力接入 DeepSeek Harness：网页搜索、抓取、图片/视频/音频生成、媒体理解、X/Instagram/Reddit 搜索与模型列表，提供 17 个工具和 18 个 /genspark-* 命令。需安装并登录 @genspark/cli（gsk login），或设置", "image", 0, "tools"),
        E("dsh-geo", "dsh-geo", "通过工作区权限受限的 MCP Key 连接已有本地 BeatGEO，操作品牌、AI 可见度证据和草稿；附带连接诊断与同品牌 SEO 页面操作 Skill。", "ai", 0, "tools"),
        E("dsh-geo-toolkit", "dsh-geo-toolkit", "面向规划/测绘的 GIS/CAD 分析工具：读 DXF、DWG 转 DXF、按图层/文字查实体、出带版式的分析图（SVG/PNG/JPG/PDF，PSD 仅 Windows x64），并对 SHP/GeoJSON/KML 做按类汇总、缓冲与叠加——解析用纯 JS，不依赖 GDAL。", "pdfdoc", 0, "tools"),
        E("dsh-git-proxy", "dsh-git-proxy", "Web UI 按需 GitHub 代理：一键开关 git/SSH 代理并测试连通性。", "net", 0, "tools"),
        E("dsh-github-link", "dsh-github-link", "把 DSH 中当前 DeepSeek 账号与本机 GitHub 身份关联，支持本机 GitHub CLI、Personal Access Token 和 OAuth 设备授权，并提供受控的 github 工具用于列出仓库、读取或创建 Issue、发表评论。", "git", 0, "tools"),
        E("dsh-gopeed-downloader", "dsh-gopeed-downloader", "把本机 Gopeed 下载器接进 DSH 的 agent 工具：新建、查看、暂停、继续、删除下载任务，诊断或启动 Gopeed 进程，并通过 DSH 后台任务接收下载完成事件（空闲的 agent 会被唤醒）。进程诊断与启动仅支持 Windows，下载相关工具跨平台可用。", "net", 0, "tools"),
        E("dsh-gowin", "dsh-gowin", "把高云 Gowin 1.9 FPGA 工具链交给 dsh：15 个工具覆盖环境与 License 探针、.gprj/.cst 工程与约束审计（对着真实 GW1N 板引脚表）、gw_sh 批量综合与布局布线、pnr 资源与时序报告解析、programmer_cli 扫描与烧录、任意 gw_sh Tcl", "misc", 0, "tools"),
        E("dsh-graphify", "dsh-graphify", "为 DeepSeek Harness 提供代码库知识图谱：7 个 graphify_* Agent 工具、/graphify 命令与 Graphify 页面，用本地 AST 解析构建并查询项目图谱（无需 API Key），支持路径 / 解释 / 枢纽节点查询与 wiki、HTML、SVG、Graph", "image", 0, "tools"),
        E("dsh-guard-degen", "dsh-guard-degen", "在模型输出边界检测并拦截退化符号流，并提供修复被污染工件与会话的工具。", "session", 0, "tools"),
        E("dsh-guard-labs-evidence-check", "mindforge-guard-labs-dsh-evidence-check", "面向 DeepSeek Harness 的合成智能体主张证据审阅插件，通过确定性规则输出有限判定、理由与证据引用。", "ai", 0, "tools"),
        E("dsh-gui-guard", "dsh-gui-guard", "Windows 窗口操作的可靠性层：先体检目标窗口是否最小化、是否在前台、有没有 DPI 缩放，再点击与输入——坐标口径和激活顺序由它处理。零依赖、纯本地、不联网。", "misc", 0, "tools"),
        E("dsh-har-triage", "dsh-har-triage", "离线分析 HAR，以端点别名、原始条目索引和最小 HTML/JSON 证据定位请求问题；不录制或重放请求。", "data", 0, "tools"),
        E("dsh-harmony", "dsh-harmony", "面向 Windows x64 上的 DSH NEXT 桌面版（在 DSH NEXT 2.0.21-next + Better Sidebar 0.28.2 上验证）的鸿蒙设备工作台；悬浮投屏复用 DSH 的 Electron，没有时首次打开会下载约 140 MB 的 Electron。", "net", 0, "tools"),
        E("dsh-harness-zh", "dsh-harness-zh", "把 DeepSeek Harness 发给模型的提示词——系统提示词各段、运行时上下文、工具描述与参数说明——翻译成简体中文。Cordis API 词典派生自 zjl1989-li/dsh-harness-zh-cn（MIT），后者同样在运行时翻译同一批提示词层；不要同时启用两者。", "session", 0, "tools"),
        E("dsh-hazchem-check", "dsh-hazchem-check", "核对危险化学品台账的内部自洽性：每种物质是否载明危险性类别、储存量能否解析、是否记录临界量、重大危险源判定与该储存量相对台账自述临界量的关系是否一致、是否载明安全技术说明书编号、CAS 号是否重复。只列出差异供人复核，不判定某单元是否构成重大危险源。", "text", 0, "tools"),
        E("dsh-health", "dsh-health", "把声明式的健康读数（来源、判据、结论）合成为一个只读的总判定；读不到的来源报 `unknown`，绝不报成健康。", "misc", 0, "tools"),
        E("dsh-host-fs", "dsh-host-fs", "在 DSH 宿主进程里执行 fs_remove 与 fs_move，因此能删除沙箱 shell 删不掉的路径；带会话白名单与路径白/黑名单，默认拒绝。", "sysinfo", 0, "tools"),
        E("dsh-hot-search", "dsh-hot-search", "活在宿主进程里的常驻检索索引：hot_find（文件名与路径模糊匹配，带 frecency 与 git 状态）、hot_fuzzy（内容检索，中文错字也能命中）、hot_grep（字面与正则内容检索）、hot_plan（按文件聚合命中，便于排批量阅读顺序）与 hot_stats。一份内存行索引只建一", "git", 0, "tools"),
        E("dsh-http-probe", "dsh-http-probe", "为 agent 增加 http_probe 工具：探测 HTTP(S) 端点的状态码、延迟与关键响应头，HEAD 被拒时自动降级 GET，不下载响应体。", "net", 0, "tools"),
        E("dsh-icd-rule-check", "dsh-icd-rule-check", "依据 GB/T 14396-2016 与公开的 ICD 使用说明，提示需要编码员关注的 ICD 编码配对——剑号与星号组合、合并编码。只报告发现的配对，不代为判定，编码结论仍由编码员作出。", "codec", 0, "tools"),
        E("dsh-image-hunt", "dsh-image-hunt", "多图源搜图并下载（14 个图源 + 7 个别名，覆盖百度/必应/360/堆糖/花瓣/Iconify/DuckDuckGo/Yandex/Openverse/维基共享/Pixiv/Wallhaven/Konachan/Safebooru），落盘进会话工作区并逐张写 meta.json，图片直接在对话里", "image", 0, "tools"),
        E("dsh-import-newapi", "dsh-import-newapi", "一键从new api站点导入复制的连接信息。", "misc", 0, "tools"),
        E("dsh-infinite-canvas", "dsh-infinite-canvas", "无限画布右侧栏插件——在画布上编排文本、图片、视频、音频节点，用 AI 生成媒体内容，Agent 经 MCP 工具直接操作画布；自带本地桥服务，安装后离线可用。", "image", 0, "tools"),
        E("dsh-insurance-advisor", "dsh-insurance-advisor", "个险代理人的展业工作流：P1-P5 产品分级与客户风险等级匹配、按回执签收日推算犹豫期的保单台账、双录五环节校验，含 10 个工具与 5 个技能。", "net", 0, "tools"),
        E("dsh-invoice-ledger", "dsh-invoice-ledger", "核对发票台账：按代码与号码识别重复、核对算式一致性、付款方不一致、日期异常与模板占位符，输出异常清单与工作簿。", "time", 0, "tools"),
        E("dsh-jev-plugin-1", "dsh-jev-plugin", "为 DSH 增加 `jev` 工具：就同一段文本向 Jev（TypeSafe System One）提出是/否、选择和评分问题，返回概率与置信度；provider 与 API key 在设置中按用户配置，并带判定账本、花费统计以及每日调用与 token 上限。", "text", 0, "tools"),
        E("dsh-juzpost", "dsh-juzpost", "通过 MCP 将智能体连接到 JuzPost（社交媒体排程工具）：列出已连接账号、检查各平台限制、上传媒体，并向 YouTube、Instagram、Facebook、TikTok、X、LinkedIn、Pinterest、Bluesky、Threads、Tumblr 和 WordPress 起草、", "ai", 0, "tools"),
        E("dsh-keep-awake", "dsh-keep-awake", "在任务运行期间通过原生电源断言保持 DSH 主机亮屏与唤醒，并在任务结束后释放。", "misc", 0, "tools"),
        E("dsh-kiwix-wiki", "kiwix-wiki", "通过你自己运行的 kiwix-serve 离线查询维基百科等 ZIM 数据包：wiki_search / wiki_read / wiki_books 三个工具分别做带摘要片段的全文搜索、按精确标题读取全文、列出本地 ZIM 书库。", "search", 0, "tools"),
        E("dsh-lang-guard", "dsh-lang-guard", "把「用中文思考和回答」钉进系统提示词，并每步注入一条运行时提醒，避免工具返回英文后语言漂移。零运行时依赖、单文件，带能力探测与降级注册，宿主 API 变更时仅记日志、不抛错。", "fileops", 0, "tools"),
        E("dsh-lawcorpus", "dsh-lawcorpus", "法学论文框架语料库：内置 2024–2026 四本 CLSCI 期刊 850 篇题录（标题、作者、摘要、关键词、目录骨架），支持 BM25 检索、框架卡、期刊画像、投稿对标自查与导出。", "fileops", 0, "tools"),
        E("dsh-libtv", "dsh-libtv", "把 LibTV 的画布与媒体生成能力接进 DeepSeek Harness，随包附带三个导演技能，首次使用微信扫码授权一次即可。", "misc", 0, "tools"),
        E("dsh-lighthouse", "dsh-lighthouse", "一屏看清每个作品的现状：本地版本与文件数、GitHub star 与最后推送、市场是否已收录及下载量、收录 PR 等待时长对比上游中位数；全部只读、数字都来自 API，不经模型生成。", "archive", 0, "tools"),
        E("dsh-linear", "dsh-linear", "DeepSeek Harness 的 Linear 工具：26 个基于 Linear GraphQL API 的模型工具（议题、评论、关联、团队、状态、标签、项目、周期、用户），外加 linear_graphql 逃生口。需自备 Linear 个人 API token。", "ai", 0, "tools"),
        E("dsh-lingua-atlas", "dsh-lingua-atlas", "离线汉英/英汉词典：含汉语释义、英英释义、分组相关词与声律分析，并向 Agent 提供可检索的公有领域中英文文学语料库。", "ai", 0, "tools"),
        E("dsh-link-parse", "dsh-link-parse", "把聊天里的分享链接解析成标题、作者、正文、封面与视频直链：B站、抖音、小黑盒、GitHub 走结构化解析，微信、知乎等其它页面退回 OpenGraph 摘要（标题、简介、封面）；可把媒体下载到本地后发回聊天。", "media", 0, "tools"),
        E("dsh-lit-library", "dsh-lit-library", "可治理的文献库：导入论文、抽取全文，每条文献只保留一行索引，并逐字核验摘录能在原文中查到。", "misc", 0, "tools"),
        E("dsh-literature-skills", "dsh-literature-skills", "三个文献调研技能打包成一个 DSH 插件：academic-web-research（轻量代理检索）、academic-literature-research（Scholar/IEEE/知网/万方/Sci-Hub 全流程）、off-campus-literature（校园 WebVPN/CARSI", "archive", 0, "tools"),
        E("dsh-loadout", "dsh-loadout", "给每个对话选一套工具（套装），只把用得上的工具投给模型：三档底座（全部 / 仅内置 / 我的套装）、一次性加挂、token 账本估算省下的开销，并可在设置里指定新对话的默认套装。", "session", 0, "tools"),
        E("dsh-loadout-1", "dsh-loadout", "DSH 的按需工具装配：MCP 工具按 server 自动分组、宿主插件工具按手工前缀分组，进组的默认隐藏、一句话激活，没被规则认领的始终可见。另带写代码/写材料/运维/只读审阅内置模式、新工具观察区用多了自动转正、敏感组激活要用户点头、读网页当轮切断外发组防提示注入，以及长尾工具的内置搜索和代理调", "net", 0, "tools"),
        E("dsh-local-library", "dsh-local-library", "本地资料库（仅 Windows，需用随包的 PowerShell 脚本安装）：文件传一次，之后每个对话都能用四个工具（library_list / library_search / library_read / library_save）检索、读取；上传、下载与打包下载在设置页完成。文件只保存在本机", "archive", 0, "tools"),
        E("dsh-localsend", "dsh-localsend", "在 DSH 对话中通过 LocalSend v2 协议把文件/文件夹发到局域网内其它机器，或生成一次性浏览器下载链接（接收方无需安装任何软件）。零配置开箱即用，兼容 dsh 0.1.1-rc.2 与 0.1.3-alpha.1。", "net", 0, "tools"),
        E("dsh-longpress-shot", "dsh-longpress-shot", "给 DSH 加区域截图，不用记快捷键（仅 Windows；截图走 PowerShell + GDI）。按住左键 550 毫秒，页面变暗进入十字框选，拖出范围松手即得 PNG，落到 ~/.dsh/longpress-shots 并同时写进剪贴板；预览卡可以把同一份字节直接送进输入框（按钮 / Ctrl", "image", 0, "tools"),
        E("dsh-loop-breaker", "dsh-loop-breaker", "失控回合硬止损：拦截同一工具+同一参数的重复调用，单轮步数或时长超预算即结束本轮。", "misc", 0, "tools"),
        E("dsh-lost-and-found", "dsh-lost-and-found", "本地文件记忆索引：把指定的文件夹记进本机一个 SQLite 库，忘了东西放哪问一句就能找回，不必翻硬盘；缓存、版本库与程序目录整棵跳过。每个目录各有独立增量锚点，后加入的目录首扫回填全部历史。只读，绝不修改、移动或删除你的文件。 支持 DSH 0.1.7 ~ 0.2.x,已在 0.2.0-rc.1", "data", 0, "tools"),
        E("dsh-mac-cua", "dsh-mac-cua", "macOS 桌面应用 Computer Use 插件：以文本读取任意应用的无障碍树与元素索引，并据此点击、输入、粘贴、滚动、拖拽、选择文本与赋值，截图可回传为图片。由常驻 JavaScript REPL 驱动——智能体只拿到两个工具（`js`、`js_reset`），在其中调用 `sky` API，", "image", 0, "tools"),
        E("dsh-maend", "dsh-maend", "通过本机 MaaEnd（MXU）的 loopback HTTP API 驱动它：10 个 maend_* agent 工具、一个侧边栏看板面板，以及任务链里的启动静音与「全部成功后才关游戏」收尾。需先在本机安装 MaaEnd 并开启 MXU 服务。", "ai", 0, "tools"),
        E("dsh-mail-2", "dsh-mail", "DSH 的邮件客户端：接入 IMAP、POP3、SMTP 与 OAuth2 账号，提供侧栏阅读标签页、API 发信、定时与 CSV 批量发信（含退订处理），以及 mail_* agent 工具。阅读标签页需配合 dsh-better-sidebar，未装时 agent 工具仍可用。", "data", 0, "tools"),
        E("dsh-masterduel", "dsh-masterduel", "面向 DSH 的 Master Duel 工具面板：带禁限筛选和 AI 智能查卡的查卡、相关卡片、稀有度徽章、收藏与构建拖放、可收放收藏栏、规则引擎先手实测与 hand_odds 起手概率、卡组类型排行、卡组检查。卡图与卡文在运行时从第三方来源获取，插件不打包卡牌数据；需要单独安装 master-d", "archive", 0, "tools"),
        E("dsh-math-plugin", "dsh-math", "SymPy 驱动的考研数学一精确计算与独立验证：14 个工具、214 个算子，默认返回精确符号解，并由独立机制复核每个结果（需本机 Python 3.10+ 及 sympy、mpmath）。", "misc", 0, "tools"),
        E("dsh-mcd-mcp", "dsh-mcd-mcp", "把麦当劳中国官方 MCP(mcp.mcd.cn)接入 DSH。粘贴自己在官网生成的 Token 后，插件会握手并调用 tools/list，把远端全部工具自动注册成 DSH 原生工具(mcd_ 前缀)，官方增删工具无需改代码，重启即同步。另附 mcd_status、mcd_test、mcd_tool", "ai", 0, "tools"),
        E("dsh-mcp-control", "dsh-mcp-control", "面向 @deepseek-ai/dsh-mcp-client 注册的 MCP 服务器的面板：逐个开关服务器（即时生效），显示各服务器的已注册工具数与预估上下文 token 开销，并将选择持久化到主目录 cordis.patch.yml，每次写入前保留带时间戳的备份。面板本身可以放在设置里作为一节，也", "time", 0, "tools"),
        E("dsh-mcp-host", "dsh-mcp-bridge", "把 stdio MCP 服务器变成 DeepSeek Harness 原生工具。默认接微软官方 Playwright MCP，agent 直接操作你已打开、已登录的 Edge 或 Chrome；也可换成任意 stdio MCP 命令。宿主侧插件，不带客户端包，无 npm 依赖。要接管你自己的浏览器，", "ai", 0, "tools"),
        E("dsh-mcp-manager-1", "dsh-mcp-manager", "DSH 的 MCP 服务器管理器：九个 mcp_manager_* 工具、命令行与网页面板，可列出、校验、探测、新增、编辑、启停、移除 ~/.dsh/cordis.patch.yml 中的服务器，从官方 MCP Registry 搜索并安装服务器，以及定位或轮换已存凭据。", "search", 0, "tools"),
        E("dsh-mcp-summon", "dsh-mcp-summon", "休眠式 MCP：只注册一个 mcp_summon 工具，召唤后该服务器的工具在本次会话内以原生 mcp__<server>__<tool> 名称注册，释放即注销并停止进程。", "sysinfo", 0, "tools"),
        E("dsh-mcp-tunnel", "dsh-mcp-tunnel", "把本机 MCP Server 通过出站-only 隧道栈（mcp-proxy + cloudflared Quick Tunnel）暴露给远程 Agent，并把公网 URL 注册进 dsh-mcp-client 的 streamable-http 配置。", "ai", 0, "tools"),
        E("dsh-mcp-workbench", "dsh-mcp-workbench", "DeepSeek Harness 的 MCP 管理控制台：左侧栏独立页面列出全部 MCP 服务器，可就地试用工具；传输断开或工具未同步时可单独重启某一行，并探测连通性。基于 PerryLink/dsh-mcp-panel 的分支；不能与上游插件同装——两者都注册 /mcp 命令。", "git", 0, "tools"),
        E("dsh-mcpserver-manager", "dsh-mcpserver-manager", "管理 DeepSeek Harness profile 的 MCP 服务：列出每个服务的连接状态与它注册的工具；保存前预检配置（可执行文件缺失、把包名当命令、变量未展开、URL 缺少路径）；粘贴 dsh 配置片段或 Claude Code 的 mcpServers 块即可新增，并自动转换为 dsh", "fileops", 0, "tools"),
        E("dsh-media-card", "dsh-media-card", "在 DSH 对话卡片内显示本地图片与短视频并提供原文件一键下载，也可为任意其他本地文件提供下载；本机与远程连接均可用，媒体本身不进入模型的视觉上下文。", "image", 0, "tools"),
        E("dsh-media-studio", "dsh-media-studio", "在对话里直接生成图片和视频并发送到会话：generate_image / generate_video / send_media 三个工具，内置 Agnes 免费额度与任意 OpenAI 兼容后端，长耗时生成走后台任务完成后自动推送，内联画廊与视频卡片支持下载、灯箱查看和系统默认应用打开。", "image", 0, "tools"),
        E("dsh-medrec-qc", "dsh-medrec-qc", "依据国卫办医发〔2016〕24号等公开文件，核对病案首页各字段的齐备性与字段间的逻辑矛盾。列出缺失或不一致之处供人复核，不评价临床正确性。", "data", 0, "tools"),
        E("dsh-memoryleak", "dsh-memoryleak", "把随手记和待办写进工作区的 Markdown 文件里：/ml 加一句话就记进当天日志；待办分三种——截止日、睡到某天自动唤醒、随时；/ml view 打几个字母就能模糊打开任意文件。全程零 token，不经过大模型；笔记就是普通的本地文件，git 和任何编辑器都能直接用。", "git", 0, "tools"),
        E("dsh-modpack", "dsh-modpack", "PCL 式 DSH 整合包：勾选已安装插件导出小体积 .dshpack.zip 与安装命令串，导入时先预览、确认后再按版本重新安装。", "archive", 0, "tools"),
        E("dsh-moss-draw", "plugin", "给 Agent 增加 7 个 art_* 工具和一个右侧栏绘图工作台（系列、页、修订、区域、相机体块），把工作流提交到你自建的 ComfyUI：MOSS/K2 文生图、局部重绘、角色参考、区域编辑与 Qwen 图像编辑，单次请求可叠加最多 4 个自备 LoRA。需要本机仓库执行一次适配：市场安装后运", "git", 0, "tools"),
        E("dsh-moss-image", "dsh-moss-image", "DSH 的 Moss 文生图插件——在对话里说一句要画什么，就出一张图；需自备 platform.moss.cn 的 Moss API Key，生成费用由自己的账号承担。", "session", 0, "tools"),
        E("dsh-motor-ai", "dsh-motor-ai", "电机电磁设计 AI 插件完整版：在 L0 毫秒级广筛之上补齐 L1（Ansys RMxprt）与 L2（Motor-CAD）精算层，形成 需求解析 → 参数识别 → 候选矩阵 → L0 预筛 → L1/L2 精算校核 的端到端设计链；与 dsh-motor-ai-l0 互斥，安装前请先卸载 l0，共", "misc", 0, "tools"),
        E("dsh-motor-ai-l0", "dsh-motor-ai-l0", "电机 AI 辅助设计插件：需求解析 → 参数识别 → 候选矩阵 → Top10 校验。L0 纯 JS、零求解器依赖，毫秒级广筛候选并给出交给 L1/L2 精算工具的载荷；可作为本地 agent 预设与 Cordis 插件使用。L1（RMxprt）与 L2（Motor-CAD）在本版本中仅预留接口，层", "ai", 0, "tools"),
        E("dsh-mp-catalog-guard", "dsh-mp-catalog-guard", "微信小程序内容目录守卫：校验 catalog.json，保证每条活动金额都是整数 amountFen、页面价格统一走 money()，必填字段 / 重复文案 / 图片路径逐项检查，输出问题清单与可直接 patch -p1 的 unified diff。29 条规则分五组（目录结构、必填与唯一性、金额", "image", 0, "tools"),
        E("dsh-msszsd-toolkit", "dsh-msszsd-toolkit", "用 QQ 远程驾驶已有的 DSH 会话（需本机另跑 OneBot 11 实现，如 NapCat）：跨会话提问（带上下文守卫）、分享槽与团队槽（一令牌一目录，带监管）、界面暂停按钮、在 Windows 上重启 DSH 并自动续跑（依赖 install-restart.ps1 创建的计划任务）、贵时段纪", "archive", 0, "tools"),
        E("dsh-mt-download", "dsh-mt-download", "新增 download_file 工具，用 16 路 aria2c 并发下载，aria2 不可用时自动退回单线程流式下载。需自行安装 aria2c；aria2 通道不校验 TLS 证书。", "net", 0, "tools"),
        E("dsh-multicad", "dsh-multicad", "通过 MCP 把 AutoCAD、中望、浩辰、BricsCAD 接入 DeepSeek Harness，内置 CAD 服务端，首次运行自动搭建私有 Python 环境。需要 Windows、本机已安装上述任一款 CAD、PATH 上有 Python 3.10+，且 CAD 与 DSH 以同一 Win", "devops", 0, "tools"),
        E("dsh-napcat-keeper", "dsh-napcat-keeper", "让 NapCat 这个 QQ 后端跟着 DSH 一起活着：启动时探测 OneBot 11 的 HTTP 端口，连不上就拉起 NapCat，之后每 45 秒复查、清掉重复的进程链、隐藏控制台窗口、可在填写任务名后创建登录计划任务，并提供设置页以及 napcat_status、napcat_restar", "archive", 0, "tools"),
        E("dsh-nuphus-mcp", "dsh-nuphus-mcp", "桌面 + 浏览器自动化桥（36 个工具）：窗口/屏幕/鼠标/键盘控制配 PaddleOCR 元素感知，Chrome CDP 浏览配无障碍快照。", "image", 0, "tools"),
        E("dsh-nurse-record-check", "dsh-nurse-record-check", "依据《病历书写基本规范》等公开文件，核对护理记录的书写时限、签名，以及评估表的完整性。列出缺失或次序不符之处供人复核。", "fileops", 0, "tools"),
        E("dsh-nx-1", "dsh-nx", "把 Siemens NX 接进 dsh（仅 Windows，需本机已装 Siemens NX，且只在 NX 2512 上验证；有限元工具另需 Simulation / Nastran 许可）：71 个工具覆盖实体建模、曲面闭环、同步建模、孔型与管路、Nastran 静力与模态、装配 BOM 与逐对间", "misc", 0, "tools"),
        E("dsh-obsidian-1", "dsh-obsidian", "把本机项目接入 Obsidian：有界的 manifest 扫描、确定性的依赖/技术栈/主题边，通过 Local REST API 或 vault 文件系统把带 wiki 链接的笔记写入托管的 graph/ 命名空间。", "fileops", 0, "tools"),
        E("dsh-office-audit", "dsh-office-audit", "为 DeepSeek Harness 注册一个 `office_audit` 工具：用内置 LibreOffice Kit 重算公式后审计计算结果——公式错误、断链引用、公式一致性、硬编码、数字格式与单位不符、三表勾稽、留存收益滚动、现金 tie-out、现金流量表加总、比率表口径与数据清洗问题。问", "pdfdoc", 0, "tools"),
        E("dsh-onedev", "dsh-onedev", "OneDev 集成插件：MCP 服务器将 OneDev REST API 暴露为 61 个工具——57 个管理工具（用户、组、角色、项目、授权、构建代理与令牌、构建及流式构建日志、全局设置、访问令牌）、3 个独立的官方文档查询工具（docs.onedev.io）以及带按调用多环境路由的环境发现；另提", "net", 0, "tools"),
        E("dsh-open-with", "dsh-open-with", "讓 DSH 擁有自己的「副檔名 → 開啟 app」規則：卡片、側邊預覽與變更審查用你指定的 app 開啟， 而 macOS 的 Finder 雙擊預設不受影響。規則在設定頁編輯、存於 ~/.dsh/open-with.json； 「顯示文件位置」仍走 Finder。", "data", 0, "tools"),
        E("dsh-opencode-live", "dsh-opencode-live", "通过 ACP 把 OpenCode 作为 DSH 子智能体运行，并在右侧边栏实时展示它的 agent 与模型、工具调用和它自己派生的子 agent；权限请求会变成 DSH 问题卡片，可选允许一次、始终允许或拒绝。", "codec", 0, "tools"),
        E("dsh-operator", "dsh-operator", "装一次、所有 DSH 会话可用的 Computer Use 插件：截屏、鼠标键盘、启动应用、计划与技能回放、审计日志、危险动作守卫、后台代码代理，以及面向无障碍树缺失应用的 OCR 工作流（文字与坐标）。仅 macOS 已验证：Windows 只有未验证的基础 GUI 后端，Linux 没有桌面后端", "image", 0, "tools"),
        E("dsh-outcomes", "dsh-outcomes", "DSH 成果登记：agent 把一次任务的最终成果（报告、网页、文档、表格、图片、数据表）登记进设置页与管理页的同一份清单，只记路径、不搬文件，删除可撤销；独立 CLI（add/list/stats/check/remove/restore）在应用外也能查同一份清单，并核对登记的文件是否还在。", "image", 0, "tools"),
        E("dsh-payroll-audit", "dsh-payroll-audit", "按公开的社保、公积金与个人所得税参数核对工资表，结果分为 pass、pass_with_gaps、review、fail 四档；参数本身带复核日期。", "time", 0, "tools"),
        E("dsh-pen-dev", "dsh-pen-dev", "把 pen.dev 桌面应用的 MCP 服务器挂进 DSH 会话，模型即可通过 get_app_state、read_skill、execute、get_style、browser 读取并修改 Pen 中打开的 .pen 文档；服务器二进制按常见安装路径探测定位，另附一个 pen-dev 技能，以及", "fileops", 0, "tools"),
        E("dsh-phone", "dsh-phone", "dsh-better-sidebar 里的 Phone 标签页：通过 Twilio 与经 Asterisk 桥接的 SIP 线路收发短信和通话，通话音频走你的服务器，提供 Live、Voicemail、勿扰模式与实时语音信箱转写，并可挂一个 Telegram 账号（聊天、语音消息、通话），以及 ph", "media", 0, "tools"),
        E("dsh-phone-butler", "dsh-phone-butler", "用 adb 查看并打理一台真实的 Android 手机：存储体检、未 root 也能读到的逐应用数据大小（来自 dumpsys diskstats）、只清缓存不动数据的清理、目录统计与截图——共五个工具；读取永不改动任何东西，写入必须显式确认。", "image", 0, "tools"),
        E("dsh-phone-drop", "dsh-phone-drop", "局域网手机直传：电脑屏幕上出一个二维码，手机扫开就能拍照或扫描，文件直接落进电脑文件夹，全程局域网直连，不经过隧道也不经过云端。文档模式在手机浏览器里本地做自适应二值化、去噪、裁边，把普通照片变成黑白扫描件。插件会在 DSH 侧边栏底部加一个「手机直传」入口，点开就是二维码页；另有 phone_dr", "image", 0, "tools"),
        E("dsh-phonephoto-ezinput", "dsh-phonephoto-ezinput", "通过一个简单的局域网服务，把手机中的照片发送到 DeepSeek Harness 的对话中。", "image", 0, "tools"),
        E("dsh-picture-text-reader", "dsh-picture-text-reader", "需 Python 3.12+；小红书需 xiaohongshu-mcp 后端并扫码登录（OCR/ffmpeg 可选）。批量抓取小红书笔记与微信公众号文章：逐篇取正文、图片文字（本地 OCR）、视频抽帧文字与评论样本，输出结构化 JSON/Markdown，每条结果带原文链接。只读，不发布、不点赞、不", "pdfdoc", 0, "tools"),
        E("dsh-plc-decode", "dsh-plc-decode", "在 DSH 里读 PLC 工程——把 CoDeSys `.project`、台达 `.dvp`（两者需本机 PATH 里有 Python 3.9+）与西门子 S7-200 SMART `.smart/.smartlib` 解码成可读报告与结构化数据，另带新旧对比、地址体检、元素级读写判定与连线还原。", "codec", 0, "tools"),
        E("dsh-plugin-adwhispr", "dsh-plugin-adwhispr", "通过 mcp-remote 加浏览器 OAuth 登录，把 DeepSeek Harness 接到 AdWhispr 的远程 MCP 服务：竞品广告调研、广告创意克隆，以及 Meta／Google／TikTok 广告的投放与管理。需要 AdWhispr 账号。", "misc", 0, "tools"),
        E("dsh-plugin-animegarden", "dsh", "Anime Garden 的 DSH 插件：在 DSH 内搜索来自動漫花園、蜜柑计划、萌番组和 ANi 的动画 BT 资源——支持对话搜索、按字幕组和类型筛选的侧边栏面板、新番周历，以及站内浮窗播放。", "media", 0, "tools"),
        E("dsh-plugin-baizhi-agent-toolkit", "dsh-plugin-baizhi-agent-toolkit", "复用 DSH 现有 MCP 客户端连接百智云托管工具包的可选配置包，通过用户提供的 BAIZHI_API_KEY 生成 Bearer 请求头；工具调用可能计费。", "misc", 0, "tools"),
        E("dsh-plugin-call-trace", "dsh-plugin-call-trace", "持久化模型工具调用轨迹记录器：每次工具调用落盘为 JSONL（重启不丢），提供结构化 call_trace 查询工具与 callTraceHistory 服务，支持文件大小轮转，附可选浮层画布 UI。", "data", 0, "tools"),
        E("dsh-plugin-comfyui", "dsh-plugin-comfyui", "让 DeepSeek Harness 用本机 ComfyUI 真正生图——自动查找或启动本地服务，在对话里完成文生图并附图。", "session", 0, "tools"),
        E("dsh-plugin-dm-ops", "dsh-plugin-dm-ops", "需 JDK 11+、达梦 JDBC 驱动与目标实例的 SSH 访问。巡检达梦数据库实例、评估安全与恢复条件，生成支持筛选和共享证据的报告。", "devops", 0, "tools"),
        E("dsh-plugin-dxpdf", "dsh-plugin-dxpdf", "不依赖 Microsoft Office、LibreOffice 或网络的 DOCX 转 PDF:用 dxpdf(Rust/Skia)引擎转换 Word 文档,自动修复 WPS Office 写出的非法 OOXML,并补齐 Word 在奇偶页节分界处插入的空白页。需 PATH 上有 Python 3", "pdfdoc", 0, "tools"),
        E("dsh-plugin-education", "dsh-plugin-education", "为 DSH agent 提供教育工具包：按学段的教案骨架、测验题与答案校验、分析式评分量规、Anki/markdown 闪卡与可读性分级。", "pdfdoc", 0, "tools"),
        E("dsh-plugin-local-life", "dsh-plugin-local-life", "为 DSH agent 提供本地生活工具包：预算规划、账单分摊、单价与折扣计算、常用单位换算（斤/里/尺、摄氏/华氏、升/加仑）与出行清单。", "ai", 0, "tools"),
        E("dsh-plugin-mail-triage", "dsh-plugin-mail-triage", "IMAP 邮件分拣与清理：增量只读扫描，先过硬保护规则层、再走可选的本地模型分类，产出报告与带哈希的清单，人工批准后才移动到回收站——全程不 expunge。", "codec", 0, "tools"),
        E("dsh-plugin-mermaid-gb-svg", "dsh-plugin-mermaid-gb-svg", "把 Mermaid 流程图转成符合 GB/T 1526-1989（等同 ISO 5807）图形符号的 SVG，可选用 A4/A3 幅面自动分页。", "image", 0, "tools"),
        E("dsh-plugin-nexterm", "dsh-plugin-nexterm", "在 DSH 会话中运维 Nexterm 托管的 SSH 机群：6 个 agent 工具（密码/TOTP/设备授权码登录认证、机群清单、单机执行、批量并行执行、预设健康检查、CPU/内存/磁盘监控），全走 Nexterm REST API，附极简设置页；DSH 机器上无需任何 SSH 私钥。", "sysinfo", 0, "tools"),
        E("dsh-plugin-onenote", "dsh-plugin-onenote", "只读取你允许的 Microsoft OneNote 笔记本：设备码登录、设置页的笔记本白名单，以及状态、页面列表、搜索、页面内容四个只读工具。", "search", 0, "tools"),
        E("dsh-plugin-optimize-ai-reply", "dsh-plugin-optimize-ai-reply", "把大模型生成的文本改成读起来像人写的：本地密度扫描 + 事实/强度/安全确定性校验，改写不达标自动回退原文。", "ai", 0, "tools"),
        E("dsh-plugin-porter", "dsh-plugin-porter", "把 DSH 插件搬到另一台机器或另一个 profile：导出迁移包（本地插件带源码、远程插件按版本重装），用包自带的 restore.mjs 在别处恢复，一键复制到其他 profile，或把配置/记忆/会话/附件/插件源码打成带校验分卷并附恢复脚本。", "fileops", 0, "tools"),
        E("dsh-plugin-recommender", "dsh-plugin-recommender", "按职业/角色推荐 DSH 插件：询问用户是做什么的（程序员、设计师、写作、研究、运维、学生…），推荐适合的插件，并对每个插件做本地静态安全审计（危险代码模式 + 0-100 风险分）与口碑检查（npm 下载量 / GitHub 星数）。", "net", 0, "tools"),
        E("dsh-plugin-tlsearch", "tlsearch", "低 Token 联网搜索：只把结果裁成 {title, url, snippet} 三个字段返回，厂商附带的 answer / score / raw_content 等一律不进上下文。后端可在 Tavily、Brave、SearXNG、Google CSE、Exa 五种之间配置，主后端失败时按 f", "data", 0, "tools"),
        E("dsh-plugin-update-checker", "dsh-plugin-update-checker", "在内置插件设置里新增「检查更新」标签页：每个已安装插件一行，显示 npm 最新版本并提供更新按钮。每行还会报告 DSH 运行时兼容性。注册表按 .npmrc 逐级读取（环境变量 → profile → 用户级，取第一个命中），未配置时并发探测镜像与公共源，内部源不会与公共源竞速。版本从哪个注册表读到", "fileops", 0, "tools"),
        E("dsh-plugin-updater", "dsh-plugin-updater", "通过简单的可用性 UI 帮助跟踪从 github 添加的插件的更新。", "misc", 0, "tools"),
        E("dsh-plugin-updates", "dsh-plugin-updates", "面向 DSH profile 内插件的只提醒更新检查器：按依赖写法（specifier）分类，只列出当前 DSH 内核能加载的版本；提供 plugin_updates 工具和 Updates 侧栏页（侧栏页需装 dsh-better-sidebar，不装时工具与设置仍可用）。", "time", 0, "tools"),
        E("dsh-plugin-veriscope", "dsh-plugin-veriscope", "AI 回答质量的发布门禁。两条通道：用原 Python 门禁重放 VeriScope 归档，或仅用 Node 对 Ragas 逐条导出做阈值判定，后者不需要 VeriScope、Python 或 pandas。返回通过／失败／待复核，附出处与可复验回执；支持逐条阈值与精确十进制比较。不重新评测、不调", "archive", 0, "tools"),
        E("dsh-plugin-virtuoso-layout", "dsh-plugin-virtuoso-layou", "从宿主机驱动 Cadence Virtuoso 画版图：虚拟机生命周期、经 bridge 执行 SKILL、窗口截图、Calibre DRC 解析，以及写入确认闸门，共 12 个宿主侧工具。", "image", 0, "tools"),
        E("dsh-plugin-writer", "dsh-plugin-writer", "写作工作台：引入多模型针对同一命题独立盲写，追加主审裁判交叉评审与去糟取精，支持 AI 命题扩写、视觉总览配图与 Markdown 文件预览导出。", "pdfdoc", 0, "tools"),
        E("dsh-plugin-xparse", "dsh-plugin-xparse", "为 DeepSeek Harness 提供结构化的 TextIn xParse 工具与文档解析 Skill，支持文档解析、缓存内容导航和持久化多文档任务，并集成 AppKey 或 Device OAuth 认证、付费操作审批及跨平台内嵌 CLI。", "pdfdoc", 0, "tools"),
        E("dsh-plugin-yuantoutao", "dsh-plugin-yuantoutao", "电商插件——一个 MCP 给你的 AI 加上商品搜索、比价与购买能力，覆盖淘宝/京东/拼多多，商品目录由源头淘 MCP 服务提供。", "fileops", 0, "tools"),
        E("dsh-plugins-10", "dsh-hiddify", "不打开 Hiddify 桌面版也能用它：七个工具起停内核、切换分流模式（重建配置并重启内核）（外网走代理／国内与内网直连）、经 Clash 控制面轮换出口节点，并经代理做多引擎检索与网页抓取。仅 Windows。", "net", 0, "tools"),
        E("dsh-plugins-11", "dsh-scholar", "DSH 学术检索工具：四个模型可用工具 paper_search / paper_get / paper_citations / book_search，覆盖 OpenAlex、arXiv、Crossref、Semantic Scholar、PubMed 五个库，并用 Unpaywall 解析开放获", "search", 0, "tools"),
        E("dsh-plugins-13", "dsh-mcp-davinci-resolve", "把 DaVinci Resolve 21.1+ 内置的 MCP 服务器注册进 DSH，让 agent 能通过 Resolve 的脚本 API 操作达芬奇。", "ai", 0, "tools"),
        E("dsh-plugins-14", "dsh-mcp-flapi", "把 FilmLight 官方的 FLAPI MCP（flapi-dev-mcp）注册成 DSH 里的 MCP 服务器，让 agent 能编写并运行 Baselight / Daylight 的 FLAPI 脚本。", "ai", 0, "tools"),
        E("dsh-port-map", "dsh-port-map", "只读的 Linux 端口、服务与 Caddy 路由地图：监听套接字及其所属 unit 或容器、反向服务视图，以及 reverse_proxy 存活检查。需要 iproute2（ss），docker 与 Caddyfile 可选。", "net", 0, "tools"),
        E("dsh-postel", "dsh-postel", "Connects DeepSeek Harness to Postel over MCP: search a library of X posts that went viral by topic, write posts and X threads in the user's saved voic", "archive", 0, "tools"),
        E("dsh-postman", "dsh-postman", "用 9 个工具在 dsh 里管理 Postman 云端集合——列出、浏览、新增（单个或批量）、修改、删除接口，导出或整体覆盖集合。", "misc", 0, "tools"),
        E("dsh-power-ticket-check", "dsh-power-ticket-check", "依据现行电力安全工作规程，核对电力工作票应载明的要素，以及签发与许可的先后顺序。只报告发现的差异，不判定作业是否安全、许可是否有效。", "text", 0, "tools"),
        E("dsh-pptx-builder", "dsh-pptx-builder", "面向 DeepSeek Harness 的 PowerPoint 演示文稿生成器：柔和色板、十种幻灯片模板、网络图片、Python 绘制的图表、高亮代码卡片、无需安装 TeX 的 LaTeX 公式（矩阵、积分、带上下限的求和）以及 Presentations 智能体模式。", "pdfdoc", 0, "tools"),
        E("dsh-pr-description", "dsh-pr-description", "分析当前分支 diff，生成符合 Conventional Commits 的 PR 标题与动机/方案/影响/测试/风险描述和自审清单，输出 PR_DESCRIPTION.md，可选直接调用 gh 提 PR。", "git", 0, "tools"),
        E("dsh-preset-categorizer", "dsh-preset-categorizer", "读取已安装的插件、MCP 服务器与技能，按能力分组，报告每项能力应属于哪个预设；可按需为每个类别注册一个预设。", "devops", 0, "tools"),
        E("dsh-preset-inspector", "dsh-preset-inspector", "面向 Web GUI 的 agent 预设只读清单：以矩阵展示每个预设包含哪些工具、MCP 服务器与技能，并提供在预设间迁移插件的命令行工具。", "ai", 0, "tools"),
        E("dsh-principles-audit", "dsh-principles-audit", "为 DeepSeek Harness 注册一个 `principles_audit` 工具：审查原则库的 ID 冲突与旧版 ID、因果句/适用边界/反例/证据缺失、同名与近重复原则、状态与置信度不一致、长期未复核与维度覆盖缺口。问题按严重度分级，并用硬门禁给出 pass / warn / fail—", "misc", 0, "tools"),
        E("dsh-prompt-enhance-2", "dsh-prompt-enhance", "增强提示词：点击发送框的星形按钮，用当前模型把草稿改写得更清晰，可一键切回原文；模板可编辑。", "ai", 0, "tools"),
        E("dsh-prompt-refine", "dsh-prompt-refine", "发送按钮左侧的 ✨ 按钮：读取草稿与最近若干轮对话，向已配置的模型要三条建议（每条都是「问题 + 改法」），可逐条勾选并实时预览合并后的提示词，结果写回输入框但不发送。", "session", 0, "tools"),
        E("dsh-prompt-system", "dsh-prompt-system", "输入框内的提示词优化器：结合对话历史、工作区文件与会话选定模型，把草稿改写为十一节分析式提示词，支持一键撤销。", "fileops", 0, "tools"),
        E("dsh-prompt-translation", "dsh-prompt-translation", "通过翻译 API 或 DSH 已配置的模型，在发送前翻译用户提示词，并将模型思考文本和回答译回用户语言，提供独立内容开关和输入框快捷菜单。", "ai", 0, "tools"),
        E("dsh-proteus-bridge", "dsh-proteus-bridge", "让 Agent 通过 11 个 proteus_* 工具控制 Proteus 8/9 交互仿真：连接、仿真启停与状态、探针读数、会校验文件哈希与 mtime 确已变化的工程保存、纯本地计算的布局建议；本机注册了 Labcenter.InteractiveSimulation COM 服务器时还可按白", "codec", 0, "tools"),
        E("dsh-proxy-2", "dsh-proxy", "按域名分流的 DSH 代理插件：列入「强制走代理」的域名（含子域名）永远走代理，其余域名先直连、1 秒内不通再换代理，先答上的通道在本会话定格，连接复用 120 秒，每次尝试都记录；可让插件安装用的 pnpm/git 子进程也走代理。", "git", 0, "tools"),
        E("dsh-proxy-control", "dsh-proxy-control", "启动前与运行时的 HTTP 代理控制：把代理写入 DSH 用户级 .env，让启动器和任何插件加载前的请求也走代理，并在「插件」页用开关同步该文件。", "net", 0, "tools"),
        E("dsh-proxy-on-demand", "dsh-proxy-on-demand", "按需拉起 mihomo 内核，空闲后自动关闭：不常占端口、不留后台进程、不改 Windows 系统代理设置。已有代理在跑时直接借道它的出口。需要自备 Clash/mihomo 配置（订阅、导入 FlClash 配置或手动粘贴）；首次运行会自动下载约 61 MB 的 mihomo 内核到插件目录。", "net", 0, "tools"),
        E("dsh-proxy-router", "dsh-proxy-router", "导入代理订阅并监督本地 mihomo 内核（proxy-provider + url-test 组），取回时直连优先、失败自动切代理并按主机记忆路由；对外只有一个 proxy_router 工具（status/start/stop/test/fetch/routes/forget）。", "archive", 0, "tools"),
        E("dsh-proxy-switcher", "dsh-proxy-switcher", "在 dsh 运行过程中热切换出站代理（直连/系统/自定义），无需重启即可生效", "net", 0, "tools"),
        E("dsh-ptc-router", "dsh-ptc-router", "按任务自动选择 PTC 或标准工具呈现，并支持模型或用户在任务中随时切换。", "ai", 0, "tools"),
        E("dsh-qbittorrent", "dsh-qbittorrent", "基于 qBittorrent WebAPI v2 的九个模型侧工具，写操作需显式 confirm，并提供孤儿种子诊断。", "ai", 0, "tools"),
        E("dsh-qboson-ising-solver", "dsh-qboson-ising-solver", "将 QBoson Kaiwu 的 Ising 矩阵求解能力作为 solve_ising Agent Tool 接入 DeepSeek Harness。", "ai", 0, "tools"),
        E("dsh-qianyuan", "dsh-qianyuan", "把乾元 MCP 服务器挂进 DeepSeek Harness：一个纯配置层 bundle 带来 15 个 agent 记录工具（坑库、成果缓存、身份、任务板），注册为 mcp__qianyuan__*。不含运行时代码；读匿名，写用 ed25519 签名。", "ai", 0, "tools"),
        E("dsh-qianyuan-1", "dsh-qianyuan", "把 DeepSeek Harness 接入乾元 MCP 服务器——其中存着其他 Agent 已经踩过的坑与已经跑出的结果，并提供能力检索。共暴露 13 个工具，名为 mcp__qianyuan__*。读取开放，无需密钥。", "ai", 0, "tools"),
        E("dsh-qq-email", "dsh-qq-email", "用已授权的 agently-cli 账号发送 QQ 邮件：注册 send_qq_email 工具（发送前需用户确认），并对外提供 ctx.qqEmail 服务供其他 DSH 插件调用。", "ai", 0, "tools"),
        E("dsh-qqnt-chat-export", "dsh-qqnt-chat-export", "读取 Windows / Linux 本机 NTQQ（QQ 9.9.x）消息库，把群聊与私聊的聊天记录导出成 txt、csv、json、md、html 或 sqlite。包含十六个模型工具：qqnt_status 与 qqnt_doctor（环境体检与排障）、qqnt_extract_key、qqn", "data", 0, "tools"),
        E("dsh-quality-lens", "dsh-quality-lens", "为每条回答给出五维质量分与话题覆盖度，附证据，并把最弱的一项转成可直接复制的提示词改写。只观测不改写；默认本地评分，可选 Jev 精评。", "ai", 0, "tools"),
        E("dsh-question-bridge", "dsh-question-bridge", "让 DSH agent 提问而不阻塞回合：ask_interactive_question 工具立刻返回待答批次号，答案稍后以普通用户消息送回会话，待答批次显示在浏览器内的待答面板，可选系统通知。", "session", 0, "tools"),
        E("dsh-quick-translate", "dsh-quick-translate", "不离开 DSH 就能中英互译：复用已配置的模型，免填 API Key；译文边生成边显示，提示词可自定义，历史自动存在本地，可随时回看重译。", "ai", 0, "tools"),
        E("dsh-rea-dispatcher", "dsh-rea-dispatcher", "把 REA 的 207 个逆向工具（Ghidra / Hopper / IDA 后端）折叠成 3 条命令加 6 个只读域入口，常驻约 5 KB。不代装引擎，需自行安装 rea-agents、Ghidra 12.1.x 与 JDK 21。", "ai", 0, "tools"),
        E("dsh-rea-gateway", "dsh-rea-gateway", "派生自 kirkchinese/dsh-capability-catalog 0.1.4（不能与上游能力目录 / @kirkchinese/dsh-rea 同装）：为 REA 提供按需 MCP 网关，通过三个固定的检索、参数查看与调用入口访问缓存工具定义，支持会话开关并复用 DSH 原生结果处理。需", "fileops", 0, "tools"),
        E("dsh-rea-mcp-toggle", "dsh-rea-mcp-toggle", "在 DSH Web UI 会话标题栏或通过 rea_mcp_toggle 工具开关 rea-mcp 服务器：不用逆向时，170 个 mcp__rea__* 工具 schema 不再随每次请求发送（tools payload 由约 722 KB 降到约 95 KB），REA 子进程同时退出；选择存入", "data", 0, "tools"),
        E("dsh-rea-toggle", "dsh-rea-toggle", "一个开关，实时把某个 MCP 服务器的工具 schema 与说明块从每个 agent 的模型上下文中移除或放回，无需重启——针对 REA 在任何任务下都会注入的 207 个工具 schema 而做。输入框下方胶囊、/rea on|off|status|toggle 与 GET/POST /rea-t", "data", 0, "tools"),
        E("dsh-read-book", "dsh-read-book", "一个窗口同时搜四家免费图书馆：Project Gutenberg 走 OPDS 目录，书格走 WordPress 检索再取每本书页面上的 s.shuge.org 下载短链，国家哲学社会科学文献中心走它的 Solr 检索接口。中国哲学书电子化计划刻意只给链接——它明令禁止程序化抓取。两个工具：read", "net", 0, "tools"),
        E("dsh-realtimeavatar", "dsh-realtimeavatar", "Realtime Avatar（realtimeavatar.ai）实时数字人工具：开发者 API key 由 harness 凭据存储保管，公开文档打包为五个按需加载的技能，rta_* 工具封装公开 REST API（余额、数字人、动作片段、会话、用量），消耗额度的操作需审批，/rta 命令引导开", "archive", 0, "tools"),
        E("dsh-receipts", "dsh-receipts", "从本地 DSH 会话日志（JSONL）挖掘「使用与影响」报告：Markdown 日/周/月报 + 自包含 HTML receipt，交叉本机 git log；零联网、隐私优先。", "git", 0, "tools"),
        E("dsh-recued", "dsh-recued", "把你自己搭建的 Recued 服务器接成 MCP 服务，让 agent 读取你的笔记、任务与物品，并提交需要你在 Recued 里确认的修改。", "git", 0, "tools"),
        E("dsh-redstone-music", "dsh-redstone-music", "Minecraft 红石音乐：rm_render 从 SoundFont 渲染乐器采样并把起音对齐到 3ms 内，rm_build 把谱面与轨表编译成分片 mcfunction 数据包（可选经 RCON 部署开建）。", "devops", 0, "tools"),
        E("dsh-refkeeper", "dsh-refkeeper", "收集对话里引用过的文献，逐条到 Crossref、OpenAlex、arXiv、DataCite 核对，通过核对的导出为 BibTeX 或 RIS。", "pdfdoc", 0, "tools"),
        E("dsh-remote-workspace", "dsh-remote-workspace", "SSH/SFTP 远程站点与远程工作区：像本地工作区一样管理远程连接与目录。", "fileops", 0, "tools"),
        E("dsh-resume-screening", "dsh-resume-screening", "面向 HR 的简历筛选插件:把 Word/PDF/Excel 简历统一收进简历库建档(技能/粗分类/入库时间),新简历自动入库、重复自动去重;用大白话下指令即可筛选,硬性条件靠库内规则精准过滤,入围的少数人再由 LLM 精判适配度,结果可导出、可追溯。 支持 DSH 0.1.7 ~ 0.2.x,已在", "pdfdoc", 0, "tools"),
        E("dsh-retry-guard", "dsh-retry-guard", "监视连续相同的工具失败，可在下一个模型步之前选择暂停；保留原始结果与成功的重复调用，并在 DSH Web 里出一份会话内报告。", "session", 0, "tools"),
        E("dsh-rf-toolkit", "dsh-rf-toolkit", "六个射频计算工具：电平换算、链路预算与最大距离、级联噪声系数、香农容量、阻抗匹配。", "misc", 0, "tools"),
        E("dsh-rich-tracking", "dsh-rich-tracking", "todo 胶囊下方的进度记分板：百分比行必须带工件证据，检查点由宿主抓取 git 状态，pursue/align/dismiss 直接送达 agent 下一步。", "git", 0, "tools"),
        E("dsh-roam-planner", "dsh-roam-planner", "面向 DeepSeek Harness 的行程工作台：地图页按天展示站点，roam_* 工具负责起草、审阅与采用行程，可选接入火车票和小红书笔记的 MCP 数据源。", "misc", 0, "tools"),
        E("dsh-rollback-1", "dsh-rollback", "文件变更回滚：捕获 write/edit 工具调用的改前映像（git blob 或快照），通过面向模型的 rollback_files 工具或 /rollback 命令还原。", "git", 0, "tools"),
        E("dsh-rss-2", "dsh-rss", "RSS/Atom 阅读器——分组订阅与未读/总数双计数、FreshRSS 账号同步（Google Reader API，已读/收藏双向写回）、图片本地代理、自带 Key 的 AI 摘要/翻译/单篇问答、播客音频与全文抓取。", "image", 0, "tools"),
        E("dsh-safety-ledger-check", "dsh-safety-ledger-check", "核对施工安全资格台账的培训学时、四个记录要素，以及特种作业证书有效期与作业时间的匹配。", "net", 0, "tools"),
        E("dsh-scratch-vault", "dsh-scratch-vault", "把操作腳本的寫入導出工作區、改放各 session 的暫存根，並把每一支收進工作區外的可檢視收納庫，讓工作區只留下真正的交付物。", "misc", 0, "tools"),
        E("dsh-search-1", "dsh-search", "通过 DeepSeek 官方 Search/Fetch 接口做网页搜索、单页抓取与一键调研；需要一个 DeepSeek API key。", "net", 0, "tools"),
        E("dsh-sensitive-replace", "dsh-sensitive-replace", "在模型读取内容之前，按用户维护的 YAML 屏蔽表（全局 / 按 Provider ID / 按模型）替换消息与工具结果中的敏感字符，出网前再清洗一次请求，避免 DeepSeek 官方 API 的 Content Exists Risk 400。", "data", 0, "tools"),
        E("dsh-session-to-doc", "dsh-session-to-doc", "把 DSH 当前会话的对话记录重组成带大纲、章节层级和目录的结构化 Markdown 文档，而不是按时间顺序原样导出。三种入口：模型工具 session_to_doc、输入框按钮、仅回环的 Web 接口。", "pdfdoc", 0, "tools"),
        E("dsh-shared-kb", "dsh-shared-kb", "团队共享知识库：一个人在自己电脑跑零依赖 Hub，其他人装插件后粘一个邀请码即可加入。上传素材按十类归档，带摘要、置信度与要点；15 个 agent 工具支持上传、检索、聚合回顾、评论与阅读。标为重要的资料必须手写推荐语，并置顶到每位成员读过为止；每个账号还各有本地私有库、收藏夹、每周简报与版本对比", "archive", 0, "tools"),
        E("dsh-ship-receipt", "dsh-ship-receipt", "项目收尾时生成一张可公开的交付回执。`ship_receipt` 工具自己测量能测的、记录被告知的，再把每一条硬性分进三区：已验证（本次采集到、且能在别处复现的证据——真跑过的命令与退出码、已入版本库文件的哈希、确实扫到文件的扫描、本地记录的远端里存在的 git 引用）、仅本地（只在这台机器上成立—", "git", 0, "tools"),
        E("dsh-site-log-check", "dsh-site-log-check", "依据 GB/T 50319-2013 等公开文件，核对监理日志的跨日连续性，以及旁站监理的覆盖情况。列出缺漏与覆盖差异供人复核。", "fileops", 0, "tools"),
        E("dsh-siyuan-archive", "dsh-siyuan-archive", "把 DSH 对话产出归档到思源笔记：一次 siyuan_archive 调用按「<归档路径>/<年-月>/<类型>/<日期>_<时间>_<主题>_<内容>」写入并附元数据表，自动维护笔记本根的「索引与规范」索引文档；6 个 siyuan_* 宿主工具（列笔记本、全文检索、读文档、归档、删块、删文档）", "archive", 0, "tools"),
        E("dsh-slipway", "dsh-slipway", "一条命令把本地 DSH 插件工程发到 GitHub 并开市场收录 PR：逐文件上传带字节校验、市场条目 PR，最后把线上文件逐个拉回来比 sha256。", "codec", 0, "tools"),
        E("dsh-social", "dsh-social", "提供社媒能力发现、价格预览、确认后读取、历史结果取回及来源表格；付费读取需要 BeatAPI key。", "data", 0, "tools"),
        E("dsh-squeeze", "dsh-squeeze", "新增 squeeze 工具：Agent 把长网页、多个网页、文本文件或含文本层的 PDF（借助 pdftotext）连同一个问题交给辅助模型阅读，只把答案带回对话，原文不进入上下文。设置页可从 DSH 模型列表选择最多三个辅助模型，各配昵称、固定思考强度与“何时使用”说明，支持可选的回退，并按各模型", "pdfdoc", 0, "tools"),
        E("dsh-stitch-mcp", "dsh-stitch-mcp", "把 Google Stitch 的 MCP 端点接成 16 个原生 `mcp__stitch__*` 工具，覆盖项目、界面与设计系统，并附一张面板内的 API Key / OAuth 令牌凭据卡片。", "misc", 0, "tools"),
        E("dsh-subagent-antigravity", "dsh-subagent-antigravity", "将 DeepSeek Harness 原生 subagent_fork 子智能体会话路由至 Google AI Pro (Antigravity) 订阅（支持 Gemini 3.8 Flash、Claude Sonnet 5.5、Claude Opus 5.5、GPT-OSS 120B）：零 API", "session", 0, "tools"),
        E("dsh-subagent-antigravity-1", "dsh-subagent-antigravity", "内置 Google 官方 Antigravity ACP 运行时的 Windows x64 完整包，委派一次性文本任务，支持选择认证方式、模型和思考强度；复用宿主依赖，支持 Harness >=0.2.1-rc.3 <0.2.2-0，包含后续 0.2.1 RC 和 0.2.1 正式版。", "ai", 0, "tools"),
        E("dsh-subagent-dispatcher", "dsh-subagent-dispatcher", "注册 `dispatch_task` 工具，把局部或例行任务交给隔离子 Agent 执行，等待其完成后检查预期文件并运行可选的验证命令，只向主会话返回一份简短报告。", "fileops", 0, "tools"),
        E("dsh-svg-motion", "dsh-svg-motion", "在 DSH 里把任意 SVG logo 变成动效视频：`animate_svg` 工具渲染透明背景 30fps 组装动画（零件飞入或整体落位），并用 ffmpeg 合成 MP4。", "image", 0, "tools"),
        E("dsh-system1", "dsh-system1", "用同一接口接入多种决策提供商与模型：在线可选 TypeSafe 提供的 Jev、Cloudflare 提供的 Clef、Nace 提供的 Drex、meraGPT 提供的 Decider 1；本地可连接 Laya，也支持兼容的自定义 provider。Agent 和插件可用它进行内容分类、候选筛选、", "ai", 0, "tools"),
        E("dsh-tab-complete", "dsh-tab-complete", "输入框会预测你接下来要打的字：幽灵文本贴在你的光标后面，字体、行高、字间距都照抄编辑器，按 Tab 变成真正的文字，按 Esc 忽略。预测是走当前会话自己的模型路由的一次短调用，喂进你的草稿和最近几轮对话，所以空输入框时还会预测你的「下一句」，用用户自己的口吻；只是复述助手原话的建议会被丢弃。宿主半", "session", 0, "tools"),
        E("dsh-table-ingest", "dsh-table-ingest", "把 .docx、.xlsx、.xlsm、.csv、.tsv 中的表格转换成规则核查器可读的 table JSON；识别不了时明确报告，不做猜测。", "pdfdoc", 0, "tools"),
        E("dsh-task-runner", "dsh-task-runner", "DSH 项目/任务双模式工作区：任务不绑定工作区，每次新对话在 D:\\dsh_working\\<名称>-<时间戳> 自动创建独立临时目录（类 Codex）；侧边栏\"任务\"分组常驻显示所有无工作区会话并带空状态提示，新建会话的工作区选择器增加\"无工作区（任务）\"选项。", "time", 0, "tools"),
        E("dsh-tavily-mcp", "dsh-tavily-mcp", "接入 Tavily 托管的 MCP 服务器并注册它公布的工具。API Key 从 TAVILY_API_KEY 凭据读取，不写入插件配置。", "devops", 0, "tools"),
        E("dsh-tender-matrix", "dsh-tender-matrix", "核对评标因素评分矩阵的内部算术自洽性：各因素分值上限、所记分值与合计之间是否互相一致。只报告发现的差异，不评价评标本身是否正确或公正。", "text", 0, "tools"),
        E("dsh-tender-requirements", "dsh-tender-requirements", "从招标文件提取截止时间、保证金、有效期、最高限价、投标文件组成与正副本份数；未找到的项也逐条报告，不省略。", "time", 0, "tools"),
        E("dsh-tianjige", "dsh-tianjige", "图形/动画/物理/AI 算法的可查询天书——219 条术法，带取舍说明与现成实现链接，提供 10 个 agent 工具与侧栏页面。AI 工具需 DEEPSEEK_API_KEY。", "ai", 0, "tools"),
        E("dsh-time-reminder", "dsh-time-reminder", "为 agent 提供它自己的时钟：按会话注入时间读数且精度可由 agent 运行时调整，并附带累计计时器与跨宿主重启可靠的一次性倒计时。", "time", 0, "tools"),
        E("dsh-tingdong", "dsh-tingdong", "把英文有声读物（MP3）和英文文档（PDF / Word / EPUB / 网页 / TXT）变成听力课：用 DSH 语音输入已下载的模型在本机识别每一句（缺失时首次使用自动下载约 241 MB；需 ffmpeg）、用你选的大模型逐句校对翻译讲解，再以精听、间隔复习、磨耳朵练到一听就懂；支持中文配音", "pdfdoc", 0, "tools"),
        E("dsh-tmp-cleaner", "dsh-tmp-cleaner", "保证 /tmp 清理守护进程常驻：被 Android 杀掉后约 2 分钟内由 dsh 进程内看门狗复活，守护进程持续不在时由 dsh 自己兜底清理；设置页可看状态、改配置、立即清理或演练。清理工具随包自带（bin/tmp-clean，Python 3），装好即用。", "sysinfo", 0, "tools"),
        E("dsh-tool-archive", "dsh-tool-archive", "把目录打成确定性 tar、不解包就列出内容、解包时逐个成员拒绝任何能写到目标目录之外的名字、并用 SHA-256 核对「解出来的东西 == 打进去的东西」。零外部依赖 —— tar 格式在这个插件里自己写、自己读。读比写更宽容是刻意的：读方的职责是如实报告归档说了什么，写方则绝不能写出自己读不回来的", "archive", 0, "tools"),
        E("dsh-tool-browser", "dsh-tool-browser", "打开页面、按页面真正需要的方式等待、抽出可读正文、截图。Playwright 是可选依赖：没装时退回静态抓取并在结果里明确说明，因为「JavaScript 从未执行」的页面意味着的东西和渲染过的不同。正文靠给候选子树打正文密度分来选，而不是相信标签名，所以容器不会因为「包含的文档更多」而赢过它里面的", "image", 0, "tools"),
        E("dsh-tool-epub", "dsh-tool-epub", "读、造、拆 EPUB 3 电子书，零外部依赖 —— ZIP 读写器与 XML 扫描器均为自建。可体检元数据/阅读顺序/目录并点出结构问题，从章节拼出一本合规的书，或把已有的书拆回逐章 HTML。", "pdfdoc", 0, "tools"),
        E("dsh-tool-error-hints", "dsh-tool-error-hints", "给失败的工具结果追加可执行提示（如路径不存在时给出最近的已存在目录）。", "fileops", 0, "tools"),
        E("dsh-tool-folder", "dsh-tool-folder", "装了大量 MCP 时折叠工具定义提示面：KV 缓存稳定的静态目录 + BM25/bge-m3 混合 tools_search + tools_schema 批量展开，几百个工具仍可检索，但不必每轮都付完整 schema 的 token。", "data", 0, "tools"),
        E("dsh-tool-gate", "dsh-tool-gate", "把整包工具从会话的工具面上摘掉，要用时一条命令挂回来。工具表从 99,789 字符降到 48,144（51.8%），不用卸载插件、不用重启，按组可逆、按 agent 独立。", "session", 0, "tools"),
        E("dsh-tool-invoice", "dsh-tool-invoice", "从文本中提取发票号码、日期、购销方、税号与金额/税额/合计，并验算「金额 + 税额 = 价税合计」是否成立，对不上就报出来。", "time", 0, "tools"),
        E("dsh-tool-media", "dsh-tool-media", "把本机 ffmpeg 包成六个结构化工具：探流、转码裁剪、均匀抽帧、扒音轨，以及按目标体积做两遍编码压缩。", "codec", 0, "tools"),
        E("dsh-tool-mining", "dsh-tool-mining", "把 GitHub 仓库的原始计数变成一句能站住的判断 —— 贡献者集中度与 bus factor（附单作者文件）、合并时长中位数与均值并列（让离群值可见而不是被隐藏）、以及排掉 PR 与 draft 之后的 issue backlog。只用公开 REST API、不装 SDK，分页被截断时明确说明而", "git", 0, "tools"),
        E("dsh-tool-nanobot", "dsh-nanobot-subagent-link", "通过 nanobot_run 工具把本机 nanobot CLI agent 当作 DSH 子代理运行：每次只交给它一个自包含任务并仅返回最终答案，可按次启动进程，也可走常驻的 OpenAI 兼容服务。", "net", 0, "tools"),
        E("dsh-tool-notion", "dsh-tool-notion", "Notion 区块与 Markdown 双向转换，不带 API 客户端、无外部依赖。Notion 的段落是一组富文本 run，而 Markdown 只有一个字符串 —— 所以两个方向分别是「切分」与「合并」，并不是一对互逆操作：一个方向在每个注解边界切开 run，另一个方向把相邻同注解的 run 重", "pdfdoc", 0, "tools"),
        E("dsh-tool-ocr", "dsh-tool-ocr", "从图片或 PDF 中抽取文字，电子版直接读文字层，扫描件自动转交已配置的 OCR 引擎。", "pdfdoc", 0, "tools"),
        E("dsh-tool-picker", "dsh-tool-picker", "按会话开关 DSH 工具，并提供让文件操作只落在工作区、同时关闭 shell 与子代理的访客模式。", "net", 0, "tools"),
        E("dsh-tool-podcast", "dsh-tool-podcast", "用本机 ffmpeg 把一期录音做成可发布的播客 —— 从静音里检出章节断点、按断点切段、两遍算法把响度归一化到广播目标，并写出 iTunes 兼容的 RSS（enclosure 字节长度实测自磁盘，避免客户端静默丢弃）。", "media", 0, "tools"),
        E("dsh-tool-protobuf", "dsh-tool-protobuf", "无需安装 protoc 即可阅读、审查和对比 Protocol Buffer 定义：零依赖 .proto 解析器，提供六个工具（status / outline / describe / diff / audit / next_number）。diff 会把每处改动分级为 breaking、risk", "data", 0, "tools"),
        E("dsh-tool-qrcode", "dsh-tool-qrcode", "内置从零实现的 ISO/IEC 18004 编码器，无需任何外部程序即可出码；出图前先算清楚版本与纠错余量，也能把已有二维码读回文本。", "codec", 0, "tools"),
        E("dsh-tool-reading-map", "dsh-tool-reading-map", "让 agent 在动一个陌生仓库之前，先拿到一份按优先级排序、覆盖率老实的仓库地图。", "git", 0, "tools"),
        E("dsh-tool-search-1", "dsh-tool-search", "内置工具、插件工具与 MCP 工具的原生发现与按 agent 加载，支持 BM25 检索，可选 Ollama 或 OpenAI 兼容的向量检索。", "search", 0, "tools"),
        E("dsh-tool-subagent-batch", "dsh-tool-subagent-batch", "DeepSeek Harness 子智能体的滚动窗口批量调度器：一次 subagent_batch 调用携带一队互相独立的子任务和由用户掌握的并发窗口，任一子智能体一结束就立刻补位，结束时把每个子智能体的最终回答、停止原因与子会话 id 作为一份验收报告一并返回。async 模式让整个池子在后台运行", "session", 0, "tools"),
        E("dsh-tool-subtitle", "dsh-tool-subtitle", "读写互转 SRT/WebVTT/ASS 三种字幕并校正时间轴，出片前体检过长或读不过来的 cue，还能用已配置的识别引擎把音视频转成字幕。", "media", 0, "tools"),
        E("dsh-toolkit-3", "dsh-at-file", "DSH 的 @ 文件引用工具：注册 at_file_read 工具，把工作区内文件内容注入会话，含目录穿越防护与 50KB 截断（MIT）。", "fileops", 0, "tools"),
        E("dsh-tools-manager", "dsh-tools-manager", "按 Agent 预设（模式）管理的工具黑名单，只做禁用：在设置页勾掉一个工具，它就从该模式的工具 schema 里消失、调用也会被拒；不设白名单、不负责启用，没被点名的工具一概不碰。每行可展开看工具自己的描述，规则存在 profile 之外的单个 JSON 文件里。", "data", 0, "tools"),
        E("dsh-toutiao-reader", "dsh-toutiao-reader", "读网页/头条文章全文的 webfetch 工具：三级策略（直连 → Edge 常驻无头浏览器 CDP → dump-dom 兜底），自动识别头条反爬质询页，附 toutiao-reader 实战经验技能。", "misc", 0, "tools"),
        E("dsh-translator-pro", "dsh-translator", "DSH 输入框悬浮快捷翻译挂件：支持当前会话模型、智谱 GLM 与自定义端点，提供预览/替换/追加、连通性测试及最近历史找回。", "text", 0, "tools"),
        E("dsh-tsm-agent", "dsh-tsm-agent", "把 tsm-core-dlr 语义服务（LanceDB 向量 + 图）挂为 MCP 工具，并携带与场景无关的 DLR/TSM 建模技能、服务状态浮层与 agent 规则；该服务是硬依赖，须先运行、bundle 才能激活。", "ai", 0, "tools"),
        E("dsh-tutorloop", "dsh-tutorloop", "面向自选资料的学习陪练，使用当前 DSH 会话模型，提供引导练习、证据反馈、Leitner 间隔复习、18 个教师工具与中英双语学生面板；要求 DSH >=0.2.1-rc.2 <0.3.0-0、Python 3.11+ 及 Python 运行时依赖。", "session", 0, "tools"),
        E("dsh-undo", "dsh-undo", "按轮次回退工具写入/编辑造成的文件改动：落盘前先快照，模型（undo 工具）、人（/undo 命令）或助手消息动作行里的按钮都能一次退回一整轮改动过的所有文件。快照在进程内写入、不 fork shell，因此在 workspace-write 这类受限会话里无需额外权限放宽。", "sysinfo", 0, "tools"),
        E("dsh-unitverse", "dsh-unitverse", "单位换算：提供 convert 工具，覆盖长度/面积/体积/时间/角度/速度/温度/压力/热量/功率十大类共 82 个单位，支持中英文单位名与温差（Δ）换算，并在 DSH Web 会话视图中提供按类别分模块、跟随中英文界面语言的「单位换算」标签页。", "time", 0, "tools"),
        E("dsh-unity-mcp-bridge", "dsh-unity-mcp-bridge", "Unity-MCP 桥接：开机即休眠，/unity-mcp-tools 才连接 Unity 编辑器的 MCP 服务端（com.ivanmurzak.unity.mcp）并注册 Unity 侧当前已开启的工具；随包发布按插件版本生成的命令目录与 /unity-mcp-install、/unity-mc", "fileops", 0, "tools"),
        E("dsh-upload-origin", "dsh-upload-origin", "通过文件名、大小和 sha256 反查上传到 .dsh-uploads 的文件在本地原始位置的绝对路径。", "codec", 0, "tools"),
        E("dsh-va-studio", "dsh-va-studio", "接入 VA Studio：10 个工具，生成短剧、图片、视频、小说与剧本，并从图片或视频反推提示词。需运行中的 VA Studio 后端。", "image", 0, "tools"),
        E("dsh-valuation-service", "dsh-valuation-service", "注册一个 `valuation_service` 工具：读取 01/02/04 JSON 底稿树，输出统一 schema——六大类比率、预测比率、带 missing 标记的 DCF 输入槽、可比 PS/PE 与 IRR。确定性、本机运行：缺 WACC/增长率/资本开支/折旧摊销/营运资本时留空而不猜", "data", 0, "tools"),
        E("dsh-vault", "dsh-vault", "把 DSH 的配置、会话、插件、工作区与 Hindsight 记忆加密分卷打包：AES-256-GCM 卷可用口令、恢复码或本机 DPAPI 免密槽解开，包内自带自包含还原器；GFS 四档滚动保留（最近 / 每日 / 每周 / 每月，另有总体积上限与回收站），支持网络路径与 WebDAV 目标。零外", "codec", 0, "tools"),
        E("dsh-vba-bridge", "dsh-vba-bridge", "通过真实 Excel COM 读写、导出并校验 Excel VBA 工程：模块、窗体代码、过程清单与 .frm/.frx 导出。仅 Windows：需安装桌面版 Excel、Python 3.10+（含 pywin32），并设置 AccessVBOM=1。", "misc", 0, "tools"),
        E("dsh-vercel", "dsh-vercel", "通过 OAuth 把 DeepSeek Harness 连接到 Vercel 官方 MCP 服务，支持按 Agent 按需加载工具、精简工具 schema、长结果分页，并附带 34 个 Vercel 技能。", "data", 0, "tools"),
        E("dsh-video-studio", "dsh-video-studio", "本地视频调色工作台，支持 DJI Log LUT 匹配还原、高光与暗部独立调节、可选肤色与局部颜色控制、逐帧预览和 10-bit HEVC 导出。此处列出的通用包不带运行时：首次启动点「配置独立环境」会经 HTTPS 下载固定版本的平台运行时（Python 3.12 + FFmpeg 9，约 100", "media", 0, "tools"),
        E("dsh-video-to-knowledge", "dsh-video-to-knowledge", "把视频链接编译成带时间戳、可回跳原片时刻的 Markdown 知识卡。需自备 Python 3.10+ 与 yt-dlp（无字幕视频另需 ffmpeg + faster-whisper，B 站会员字幕需登录 cookie）。", "pdfdoc", 0, "tools"),
        E("dsh-vision-click", "dsh-vision-click", "让 Agent 看着屏幕操作 Windows：用 Windows OCR 把界面文字变成可点目标，再执行点击、拖动、滚轮、键入与按键，每步都用逐像素差分和文字增删复核；F6+F7 由独立进程急停。", "image", 0, "tools"),
        E("dsh-vps-ops", "dsh-vps-ops", "先读后写的 VPS 运维工具：systemd 状态与操作、磁盘占用、Docker 状态、日志尾部、可配置备份与静默时段计划。", "sysinfo", 0, "tools"),
        E("dsh-wall-mcp-manager", "dsh-wall-mcp-manager", "在DeepSeek Harness内管理MCP服务的插件。", "misc", 0, "tools"),
        E("dsh-wash-calendar", "dsh-wash-calendar", "基于纯日期数学的周期习惯排程：下次发生日、区间排程与逾期提醒。", "time", 0, "tools"),
        E("dsh-wayland-use", "dsh-wayland-use", "GNOME/Mutter 下的 Wayland 桌面控制：截图、带坐标的 OCR、按文字点击，以及批量输入动作。后端为 Python 进程，需 python3-gi 与 GStreamer；OCR 需 Tesseract。", "image", 0, "tools"),
        E("dsh-wb", "dsh-wb", "把 DSH 与本机 WorkBuddy 桌面端接起来，分四块：读写与搜索 WorkBuddy 的记忆、技能、计划和日志；经本机 CodeBuddy CLI 跑任务，带四档权限；通过 CDP 驱动正在运行的 WorkBuddy 窗口（打开会话、以清洗后的富文本读取回复、代打字并发送、切换按账号计费的模", "text", 0, "tools"),
        E("dsh-wb-archive", "dsh-wb-archive", "wb_archive 工具：把微博单条链接（m.weibo.cn/status/…）经 2100laike 存档服务转成永久 Markdown 快照——长文取全文、图片转存不裂链、删博后仍可读、重复提交去重秒回不耗额度。依赖第三方 2100laike 存档服务；匿名使用每个插件实例每天限 8 次，注", "git", 0, "tools"),
        E("dsh-web-search-9router", "dsh-web-search-9router", "为 DeepSeek Harness 提供 9router 网页搜索与抓取。启用插件包后自动接管原生 web_search/web_fetch，停用后恢复其余配置层的提供方选择。", "net", 0, "tools"),
        E("dsh-web-search-free", "dsh-web-search-free", "多后端自动降级的 WebSearchProvider：依次尝试 Exa、Bing HTML、DuckDuckGo HTML，都失败后才动用有额度的 SerpAPI，日常搜索由免费档承担。", "search", 0, "tools"),
        E("dsh-web-search-session-follow", "dsh-web-search-session-follow", "替换内置 web_search 的 provider：按会话当前路由的模型选择端点与凭据，运行时可编辑的优先级链支持 Anthropic web search、OpenRouter online、智谱 bigmodel 三种方言，设置 UI 面板可视化编辑，本地 JSONL 调用审计，链全失败回退内", "data", 0, "tools"),
        E("dsh-wechat-mp", "dsh-wechat-mp", "把 markdown 变成排好版的微信公众号草稿：样式逐条内联到元素上（编辑器会丢弃 `<style>` 块和 class 名），每张本地图片走微信自己的上传接口以免被过滤，然后创建草稿；不做群发。", "pdfdoc", 0, "tools"),
        E("dsh-weknora-archive", "dsh-weknora-archive", "把 DeepSeek Harness 会话归档进自建 WeKnora 知识库，含提取、总结与增量去重。", "archive", 0, "tools"),
        E("dsh-wenan", "dsh-wenan", "提取抖音、B站、快手与 YouTube 短视频的文案与字幕，并带标题、作者、话题与互动数据；抽取器以 Python 随包提供。", "media", 0, "tools"),
