        E("dsh-yeelight-smart-home", "dsh-yeelight-smart-home", "控制、组织、诊断、设计、个性化 Yeelight 智能家居，解答产品知识问题，由本地 yeelight-home 运行时驱动。", "misc", 0, "tools"),
