        E("mcptender-plugins", "mcptender-plugins", "使用个人服务 API 密钥，将 DeepSeek Harness 连接到 MCPTender 的俄罗斯公开采购记录、来源文件及已公布合同供应商。", "fileops", 0, "tools"),
        E("miran-fann-dsh", "miran-fann-dsh", "通过 MCP 调用 Miran Fann 引擎，在 dsh 会话里做动态图形，附带 Miran 设置页与动效设计技能。需单独安装 Miran Fann 引擎（npx miran-fann setup）并登录。", "session", 0, "tools"),
        E("mouse-keyboard-plugin", "Mouse-Keyboard-Plugin", "面向 DeepSeek Harness 的 Windows x64 桌面工具，可恢复并前置已有窗口、观察截图与 UI Automation 元素、左键点击、输入文字或支持的按键，支持反复开启和交还控制，并可按物理 Esc 停止。", "image", 0, "tools"),
        E("msds-chain-mcp", "dsh", "通过托管的 MSDS Chain MCP 端点接入化学品安全数据：23 个工具覆盖相容性与投料顺序、GHS 危害、PPE、储存、废弃处置、职业接触限值、运输分类、多法域合规、SDS 查询与版本比对、签名审计报告；每条回答都标注其依据的供应商 SDS 与版本日期。", "time", 0, "tools"),
        E("multisim-toolkit", "multisim-toolkit", "在 Windows 上把本机的 NI Multisim 14.3 变成可编程对象：九个 msim_* 工具可开关 .ms14 设计、读写元件值与电路参数、跑直流工作点/交流扫频/单频交流/瞬态分析、导出原理图与 BOM/网表；Win32 通道驱动可见窗口操作分析对话框并截取 Multisim 自己的", "session", 0, "tools"),
        E("my", "my", "Windows NapCat部署指南与本机端口只读检查，附用户手动运行的管理员启动入口。", "net", 0, "tools"),
        E("opencode-tokenrhythm-image-mcp", "opencode-tokenrhythm-image-mcp", "用 TokenRhythm 生成图片:把无 npm 依赖的 Python stdio MCP 服务器挂成 mcp__tokenrhythm_image__generate_image,用 qwen-image-2.0 或 wan2.7-image 生成并存到你指定的目录。需 PATH 上有 Pyth", "image", 0, "tools"),
        E("reaudit-ai-plugin", "dsh-reaudit", "通过内置的 @deepseek-ai/dsh-mcp-client 桥接挂载托管的 Reaudit MCP 服务（https://mcp.reaudit.io/mcp），用 REAUDIT_API_KEY 做 bearer 鉴权：238 个 mcp__reaudit__* 工具，覆盖品牌在 AI 回", "misc", 0, "tools"),
        E("seo", "callai-seo-mcp", "连接 CallAI SEO MCP 服务，提供 10 个 SEO 数据工具和 1 个 DataForSEO 通用请求工具：Google/Bing 搜索结果（含 AI Overview 引用来源）、关键词搜索量与难度、长尾词、竞品关键词差距、外链和页面审计。附带 callai-seo 技能。需要 Ca", "search", 0, "tools"),
        E("shangshi-dsh", "shangshi-dsh", "在 DeepSeek Harness 中本地完成奇门排盘、商务评分、未来择时和方位建议。", "misc", 0, "tools"),
        E("sleep-not-permitted", "sleep-not-permitted", "禁止 Agent 前台等待：sleep / wait / tail -f / watch / ping 等等待型命令、wait_agent 与 job_output(wait) 等阻塞等待工具，用反复 check 代替等待的轮询（同一条命令在窗口内重复出现），以及需要人输入/确认的命令（sudo 不", "net", 0, "tools"),
        E("transproof", "transproof-plugin", "译校助手 TransProof 的 DSH 插件：完整网页界面 + 不联网的「跑本地体检」Agent 工具。", "ai", 0, "tools"),
        E("video-reader", "dsh-video-reader", "复用现有的 Video Reader 本地安装，为 DSH 接入带时间戳的视频阅读、通用队列/历史与 Scroll 的个人 B 站工作流。仅支持 Windows x64：需先安装核心并设置 VIDEO_READER_ROOT 再启动 DSH；本包不安装 Python、FFmpeg、模型或 B 站凭据", "media", 0, "tools"),
        E("yuezhiye-dsh-closet", "dsh-closet", "按工作区管理临时脚本与其运行日志的收纳间，数据放在每个项目内的 .dsh-fix 目录。可登记脚本（语言与用途）、扫描项目中遗留的临时脚本/备份/日志、带超时执行已登记脚本并把每次运行写进带时间戳的日志、把选中的文件清运进可整批还原的回收站。扫描只列清单永不删除；清运只做移动不做删除；已被 git", "git", 0, "tools"),
        E("zuad-deepseek", "Zuad-deepseek", "通过 DeepSeek Harness 管理 Zuad 数字标牌节目、素材、播放排程和设备。需要已有 Zuad 信发系统后台及可用账号，在插件设置里登录，密码只保存在本地。", "misc", 0, "tools"),
        E("dsbot-session-create", "dsbot-session-create", "给会话加四个工具：create_session 在指定工作区或任意一个已存在的文件夹里开一个新会话，并把一段提示词投进去；session_message 给一个还在跑的会话再追加一条消息——请宿主立刻把它插进正在跑的那一轮，不再排队到本轮结束；已经闲下来的会话会被拒投，并指向 create_sess", "fileops", 0, "session"),
        E("dsh-abba-secret-chat", "dsh-abba-secret-chat", "装进 DeepSeek Harness 右侧栏的一次性双人密码聊天：端到端加密（服务器只见密文），支持图片与截屏，结束即彻底清理，关掉 DSH 即消失。", "image", 0, "session"),
        E("dsh-agent-bridge", "dsh-agent-bridge", "在 DSH 工作区侧边栏列出 Claude Code 与 Codex 会话，可打开、继续对话、置顶、重命名和归档，并附带终端、文件和 Git 标签页。", "git", 0, "session"),
        E("dsh-agent-context-hub", "dsh-agent-context-hub", "把本机所有 agent 的会话历史合并成一份按项目分组的只读索引，并附一块只追加的共享上下文板，让换 agent 时不丢结论。", "session", 0, "session"),
        E("dsh-agent-sync", "dsh-agent-sync", "把本机其他 AI 编程助手的会话实时镜像成 DeepSeek Harness 的任务，每个应用一个工作区。", "session", 0, "session"),
        E("dsh-ai-exporter", "dsh-ai-exporter", "通过 Windows 原生保存窗口，将当前或历史 DSH 会话及选定轮次导出为 TXT、Markdown 和可搜索 PDF。", "pdfdoc", 0, "session"),
        E("dsh-always-there", "dsh-always-there", "心跳与日志标记两种触发只负责叫醒会话，说不说由 agent 自己决定；沉默也是一种回答。默认关闭：需在 profile 里填 sessionId 并启用；若把回复转发到聊天软件，发送层需拦掉 SILENT 标记。", "fileops", 0, "session"),
        E("dsh-antigravity-bridge", "dsh-antigravity-bridge", "在 DeepSeek Harness 里读取 Google Antigravity 的 SQLite 会话并导入为原生侧栏会话，提供 list／read／import 工具与斜杠命令。", "data", 0, "session"),
        E("dsh-archive-delete", "dsh-archive-delete", "在 DSH 中批量将归档会话移入回收站、恢复或永久清除，并查看 DSH 和工作区的存储占用、文件类型与大文件。", "archive", 0, "session"),
        E("dsh-archive-delete-1", "dsh-archive-delete", "归档会话管理，支持单条与批量删除、原生工作区登记同步，以及宿主持有会话资源时的延迟文件清理。", "archive", 0, "session"),
        E("dsh-archive-purge", "dsh-archive-purge", "在已归档会话的行菜单里加入「删除会话」：永久移除会话日志目录、它启动的子代理会话日志、工作区归属、归档标记、投影缓存记录与 spill 溢出目录；宿主仍持有的会话先登记，下次启动或点「完成待删除清理」时完成。另外会清扫被放弃的空白占位、遗留的孤儿子代理与失效的投影缓存记录，并让空白占位不再出现在 @", "archive", 0, "session"),
        E("dsh-archive-purge-1", "dsh-archive-purge", "无论侧栏「归档显示」如何设置都强制隐藏已归档会话，并提供管理面板：取消归档，或彻底删除会话日志目录、归档与置顶登记及投影缓存。", "archive", 0, "session"),
        E("dsh-archive-viewer-1", "dsh-archive-viewer", "已归档 DSH 会话的只读查看器：按工作区筛选、按标题/ID 搜索，不取消归档即可阅读从完整日志折出的对话——包括上下文压缩前的原文与工具调用。", "archive", 0, "session"),
        E("dsh-archived-chats-1", "dsh-archived-chats", "在设置里按工作区分组浏览已归档会话，可筛选、搜索、一键恢复，或把会话日志从磁盘彻底删除。", "archive", 0, "session"),
        E("dsh-archived-conversations", "dsh-archived-conversations", "侧边栏底部的已归档对话列表，可只读预览最近消息；针对产品刻意隐藏且无法重新打开的归档会话。", "archive", 0, "session"),
        E("dsh-archived-session-delete", "dsh-archived-session-delete", "在 Web 侧栏已归档会话的“...”菜单中新增带二次确认的「删除会话」；Host 永久删除本地 JSONL 日志（含隐藏的子代理后代）、工作区记账与归档/置顶集合，并刷新已打开的页面。", "data", 0, "session"),
        E("dsh-asc", "dsh-asc", "由模型主导的 DeepSeek Harness 上下文压缩：由 agent 决定何时压缩、压缩什么，以持久化会话日志替换提交，并提供可逆的工具结果压缩与逐字节哈希取回。", "git", 0, "session"),
        E("dsh-auto-archive", "dsh-auto-archive", "按可配置天数自动归档闲置的 DSH 会话，并清理已归档会话的投影缓存，不删除会话记录或附件。", "archive", 0, "session"),
        E("dsh-auto-continue", "dsh-auto-continue", "避免轮次停在「话没说完」或「只写了下一步计划」上关闭：把静默截断的流转成同一步内可重试的失败，并要求模型在每轮结束时声明收尾方式。", "ai", 0, "session"),
        E("dsh-auto-goal-resume", "dsh-auto-goal-resume", "DSH 重启后自动续跑有活跃目标的会话,无需人工说「继续」。", "session", 0, "session"),
        E("dsh-auto-handoff", "dsh-auto-handoff", "DSH 插件：通过 /handoff 或会话累计 Token 阈值把长会话交接给同工作区的新会话，并继承 preset、模型、权限与 Plan 模式；交接简报由会话自身的模型撰写，切换在 Step 边界发生，不中断正在执行的步骤。", "session", 0, "session"),
        E("dsh-auto-rename", "dsh-auto-rename", "用首条消息为会话命名，并在重命名弹窗里流式给出 AI 标题建议。", "fileops", 0, "session"),
        E("dsh-auto-sync", "dsh-auto-sync", "把 DeepSeek Harness 的 home 自动、带版本地备份到自己的私有 git 仓库：会话记录、记忆文件、设置与 profile 插件树都会按计划提交并推送，失败一定会在 DSH 日志里报告。", "git", 0, "session"),
        E("dsh-auto-title", "dsh-auto-title", "给 DSH 会话自动起名：首轮问答结束后用「项目｜具体任务」命名，而不是把提问截断。通过 bundle patch 顶替内置标题 provider，在会话行「…」菜单里加「AI 重命名」（先预览再应用），设置页可改 provider/model、命名规则并查看诊断日志。49 个单元测试。", "fileops", 0, "session"),
        E("dsh-auto-workspace", "dsh-auto-workspace", "为 dsh 提供无项目聊天：不选工作区创建的会话会获得自己的目录（~/Documents/DSH/<日期>/chat-NN），重新打开会话时复用，并留在「未分组」而不会变成侧栏项目；新建会话的 Hero 上新增悬浮清除徽标与「不在工作区中工作」一行，另有一个仅存在于浏览器端的哨兵工作区，让该 Her", "time", 0, "session"),
        E("dsh-autocompress", "dsh-autocompress", "在 DeepSeek Harness 上按固定时间压缩所有空闲会话的上下文：默认每天 08:30 自动执行，错过时间点在下次启动时补做，也可用 /compact-all 命令随时手动压缩，并逐会话报告结果。", "archive", 0, "session"),
        E("dsh-autonomous-restart", "dsh-autonomous-restart", "由 agent 自己发起的重启，不是按钮。agent 调一个工具，之后由插件接管：等这台机器上所有 agent 与后台任务都空闲，走完十秒可见倒计时（点一下鼠标、滚一下滚轮、按任意键都会取消），再重启 DSH，并唤醒原会话让 agent 接着说下去。没有按钮、没有手动入口——工具是唯一入口。官方桌面", "time", 0, "session"),
        E("dsh-background-compaction", "dsh-background-compaction", "接管内置压缩 provider：默认在上下文达到阈值的 85%（比例可配）时，起一个游离任务把截至上一轮的历史总结成摘要；摘要就绪后的下一个回合边界直接把它提交为 checkpoint，这一步 0 次模型调用、耗时毫秒级。/bcompact \\[消息] 按需发起同样的生成，随后照常发送你的消息。设置", "git", 0, "session"),
        E("dsh-baize-session", "dsh-baize-session", "把选中的消息从一个对话迁移到另一个对话，并管理工作区的对话——支持归档、还原、删除和跨工作区迁移。", "archive", 0, "session"),
        E("dsh-big-compact", "dsh-big-compact", "超大会话分块压缩：仅在实测上下文超过模型窗口 85%（或请求超过 4 MB）时接管，把历史按 1.5 MB 分块摘要再合并；小会话仍走 dsh 自带压缩。", "archive", 0, "session"),
        E("dsh-boot-resume", "dsh-boot-resume", "宿主启动时读取已存会话，找到被重启打断的最后一轮并补发一句「继续」，让中断的工作接着跑。", "session", 0, "session"),
        E("dsh-branch-discussion", "dsh-branch-discussion", "把自包含的子问题软分支到子会话，只把一页以内的结构化摘要带回主上下文。", "git", 0, "session"),
        E("dsh-breather", "dsh-breather", "零成本“会话暂停”键：不会发出新请求，当前步骤做完后直接挂起，方便添加提示词；继续时不会花费token重发请求；只有点击继续或发新提示词才会继续，子代理结算与定时提醒唤不醒；侧栏加入暂停图标，计时器与动画共同冻结，不计暂停时段，恢复后从冻结前时间继续走；状态区分「暂停中」与「已暂停」；暂停只会作用于", "net", 0, "session"),
        E("dsh-brutal-delete", "brutal-monkey", "dsh暴力删除：永久删除 DSH 会话的磁盘数据——单条删除或跨工作区批量删除，支持 Ctrl+A 全选与 Delete 快捷删除，彻底清理对话记录、投影缓存、工作区归属、附件与子会话，不可恢复。", "sysinfo", 0, "session"),
        E("dsh-bz", "dsh-bz", "三级规则注入器：长对话里反复重发规则，带熔断、内容指纹去重、会话持久化与设置面板编辑器。", "text", 0, "session"),
        E("dsh-chat-source-tracer", "dsh-chat-source-tracer", "选中 AI 回答中的一句话，反查此前对话与工具记录中的候选依据，区分直接依据、推论和未找到依据，并跳回原文核对。", "session", 0, "session"),
        E("dsh-checklists", "dsh-checklists", "会话级清单：每个会话一棵任务树、按预算注入提示词的摘要，以及可改条目标题的右侧栏面板。", "session", 0, "session"),
        E("dsh-claw-identity", "dsh-claw-identity", "把 SOUL、IDENTITY、AGENTS、TOOLS 注入 Claw 会话提示词。硬依赖（需同装，否则单装会崩）：dsh-claw-permissions。", "session", 0, "session"),
        E("dsh-claw-registry", "dsh-claw-registry", "登记具名 Claw Agent，与官方工作区侧栏隔离，并提供设置页和全局新建模板。硬依赖（需同装，否则单装会崩）：dsh-claw-policy、dsh-claw-observability、dsh-claw-permissions。", "ai", 0, "session"),
        E("dsh-cleaner", "plugin", "为 DeepSeek Harness 补上会话删除：侧边栏菜单项、按工作区分组的批量清理面板、默认 dry-run 的 session_delete 工具。删除会话日志、投影缓存、工作区注册表引用与派生搜索索引，并级联删除全部子代理会话。", "net", 0, "session"),
        E("dsh-codex-bridge-1", "dsh-codex-bridge", "在 DSH 输入框下方列出可接续的 Codex 聊天，按每个聊天所属的具体项目分组，把机械提取的恢复上下文插入草稿、不自动发送。项目归属取自 Codex 的项目注册表并做路径边界匹配，同时标注这个判断有多可靠：有记录的会话归属、登记目录、元数据不可读、或同一目录登记给多个项目（后者标为未知而不是猜一", "fileops", 0, "session"),
        E("dsh-compact-control", "dsh-compact-control", "调整 DSH 原生自动上下文压缩的触发阈值：在插件管理器的插件页面用滑块设置上下文占满模型窗口多少百分比时压缩（1%–100%，默认 80%，方向键可 1% 微调）；阈值调低时保留的最近历史预算会随之缩小，以免提前压缩被抵消，压缩本身仍由原生引擎执行。", "archive", 0, "session"),
        E("dsh-compact-queue", "dsh_compact_queue", "注册 /compact_queue：会话忙时也不丢弃请求的压缩命令——空闲就立刻压缩，忙时把请求排进本会话队列，等这个会话下一次空闲自动补跑；agent 状态事件之外再挂一条 2 秒兜底 tick，避免漏触发，排队最长等 30 分钟，排队中或执行中都可以用 /compact_queue cancel", "archive", 0, "session"),
        E("dsh-compact-saviour", "dsh-compact-saviour", "使用专用模型处理上下文压缩恢复，并在原生上下文弹窗提供手动压缩。", "archive", 0, "session"),
        E("dsh-compaction-route", "dsh-compaction-route", "在 Web 设置页里为会话压缩指定摘要模型，并在主模型出错时改用配置的兜底模型重试。", "archive", 0, "session"),
        E("dsh-compaction-selector", "dsh-compaction-selector", "按供应商浏览、搜索并选择 DSH 标准模式的独立摘要模型，或用 Auto 跟随对话路由；保存自动压力压缩额外次数，手动压缩只尝试一次有用压缩。提供中英文主题适配设置，安装后新建标准模式会话以应用配置。", "archive", 0, "session"),
        E("dsh-compat-val", "dsh-compat-val", "一个设置项把压缩阈值铺到所有 Agent 模式：注册 <模式>-compact-<阈值> 预设副本并改写 compaction-basic.thresholdRatio，阈值或勾选变化时重新注册，还可把副本设为默认模式（标准 > 创造 > 极简 > ptc）。", "archive", 0, "session"),
        E("dsh-composer-enter", "dsh-composer-enter", "让 DSH 0.1.5 Web 输入框使用 Enter 换行，同时保留 Cmd/Ctrl+Enter 提交消息。", "git", 0, "session"),
        E("dsh-context-1", "agent-embodiment", "为 DeepSeek Harness 提供上下文可观测性与控制：跨会话 token 分析、会话级预算/提示词/工具控制，以及可选的 Agent 脚手架。复用官方 tokenMeter、compaction、systemPrompt、tools.restrict seam；监控只读。", "sysinfo", 0, "session"),
        E("dsh-context-continuum", "dsh-context-continuum", "把上下文压缩从滚动重写的叙事摘要改为只追加的会话索引：早期事实逐字保留，被压缩掉的原文可按锚点取回。", "archive", 0, "session"),
        E("dsh-context-diet", "dsh-context-diet", "在提示缓存转冷后，把陈旧、过大的纯文本工具结果替换为带末尾行与错误行预览的 stub，并在输入框下方显示每请求与累计节省量。", "text", 0, "session"),
        E("dsh-context-drawer", "dsh-Context-Drawer", "会话上下文超过阈值时，先把较早的消息追加到按会话归档的文件夹，再把最早的已完成轮次移出模型可见上下文；聊天记录与会话日志保持原样。", "archive", 0, "session"),
        E("dsh-context-handoff", "dsh-context-handoff", "输入框下方实时显示上下文占用；接近上限时让当前模型写一份交接摘要，开新会话继续干活并自动切过去，长任务不用怕撞上窗口上限。", "session", 0, "session"),
        E("dsh-context-keeper", "dsh-context-keeper", "看护 DeepSeek Harness 会话的上下文预算：每轮回复底部一个颜色点（绿<50%、黄50-65%、橙65-80%、红≥80%，读官方 contextPressure 投影），橙/红档在输入框下方出现提醒与「一键开新会话」交接按钮，另有 /context-watch 与 /handoff", "session", 0, "session"),
        E("dsh-context-rescue", "dsh-context-rescue", "抢救已经被上下文窗口拒掉的会话：补上宿主分类器漏判的网关文案，从失败信息里拿到真实窗口， 不调用模型就把最旧的一段历史折成一个检查点（工具结果裁剪、借宿主压缩引擎、或纯机械摘要折叠）， 然后重试失败的那一步；context_rescue 工具与 /rescue、/rescue-status 可手动走", "archive", 0, "session"),
        E("dsh-continuechat", "dsh-continuechat", "从断点继续对话：/continue 命令与消息操作行按钮让模型接着被打断的回答往下写，覆盖手动停止、模型请求失败、输出 token 上限截断与崩溃恢复四种情形，续写提示在被回答后从对话框中回收。", "session", 0, "session"),
        E("dsh-conversation-find", "dsh-conversation-find", "当前会话内的关键词搜索：先把会话历史翻回最早一页再匹配，命中处高亮并滚动定位到所选项。", "search", 0, "session"),
        E("dsh-conversation-folders", "dsh-conversation-folders", "每个会话一个专属文件夹：自动存档对话记录，会话空闲 10 分钟后把调研产出的表格、图表等文件按类别归档并自动命名，会话菜单中提供删除入口，删除会话时连同文件夹一起彻底删除。", "data", 0, "session"),
        E("dsh-conversation-purge", "dsh-conversation-purge", "在侧栏会话菜单里彻底删除单个对话（含已归档），同时清理会话日志、投影缓存、归档状态与提醒。", "archive", 0, "session"),
        E("dsh-cross-session-ref", "dsh-cross-session-ref", "跨会话引用卡片：把任意会话里的问答卡片拖到另一个会话并保留下来；在目标会话提问时，被拖入卡片的提问、当时的回答与附件会作为「本会话更早的对话记录」注入 Prompt，模型可直接引用。", "session", 0, "session"),
        E("dsh-curate", "dsh-curate", "面向 DSH 会话的人工上下文整理工作台：可为整轮或单条消息标记「重要（原文保留）／一般／次要」，不调用模型即可改写用户、助手、工具结果与注入上下文消息，再按标记区间用模型生成的摘要压缩，或调用官方 /compact（范围由官方压缩器决定）；每次写入前都会生成一份本地 JSON 备份。", "data", 0, "session"),
        E("dsh-deep-purge", "dsh-deep-purge", "真正删除 DSH 会话，而不是只归档（仅限 Windows）。一次清掉六处本地存储：会话日志、标题缓存、billion-context SQLite 索引（含 VACUUM）、侧栏注册表、成本台账、桥接日志。带预演、自动备份、逐字节回滚，以及「退出→删除→重启」全自动流程。", "data", 0, "session"),
        E("dsh-deepworker", "dsh-deepworker", "DSH 会话工作台：轮次操作、引用出处、本地笔记与摘要、会话内查找、专注锁和多工作区命令按钮。", "session", 0, "session"),
        E("dsh-default-workspace", "dsh-default-workspace", "把默认工作区从系统盘挪走（DSH 把新会话一律开在 <文档>/deepseek-harness/default-workspace 且从不迁移），同时让已存会话继续可用：无需重启即可改写工作区记录，同一套动作也有图形面板可点，连同 header cwd 把已存会话日志一起搬走，并重帧化首帧不是恰好一", "session", 0, "session"),
        E("dsh-delete", "dsh-delete", "DSH 会话与图片管理：侧边栏多选面板在 DSH 归档后把选中的会话连同磁盘文件一起删除，支持子 agent / 团队成员 / 整族级联与逐个大小统计；右侧栏页签统计会话图片张数并多选摘除，可另行删除磁盘上的源文件与附件对象。", "image", 0, "session"),
        E("dsh-delete-chat", "dsh-delete-chat", "给 DSH 补上真正的会话删除：「⋯」里的 Delete chat 把会话目录移进 ~/.dsh/session-trash，侧栏回收站页面负责筛选、恢复与永久删除，另有 CLI 用同样的动词、不用开 GUI。", "fileops", 0, "session"),
        E("dsh-delete-session", "dsh-delete-session", "在侧边栏会话行菜单中加入「删除会话」项，确认方式可配置（再次点击、对话框确认或直接删除），正在执行任务的会话会被拒绝删除。", "session", 0, "session"),
        E("dsh-delete-sessions", "dsh-delete-sessions", "在侧边栏会话菜单中添加“删除会话”选项，从磁盘上永久删除该会话。", "sysinfo", 0, "session"),
        E("dsh-easy2restart", "dsh-easy2restart", "归档 DeepSeek Harness 会话前先确认，归档后把副本自动备份到你指定目录：每个会话一个文件夹（会话日志、附件、元数据），另附清单、还原说明与 Markdown 台账。并提供右侧栏的已归档会话浏览器与双击重启按钮（仅 Windows；会话运行中时按钮禁用）。", "pdfdoc", 0, "session"),
        E("dsh-edit-question", "dsh-edit-question", "在每条用户提问旁加「编辑提问」入口：改完从该提问重新开始，原图一并重发（还可粘贴补充图），原会话可选保留或归档。", "archive", 0, "session"),
        E("dsh-edit-regen", "dsh-edit-regen", "编辑重发：在用户消息气泡上多一个「编辑」，改完从那条消息重新生成，图片与文件随行重传，模型继承原会话。", "image", 0, "session"),
        E("dsh-global-context", "dsh-global-context", "全局提示词配置：在对话视图新增一个标签页，写进去的内容会加在每个会话系统提示词的最前面，保存后下一条消息即生效。", "session", 0, "session"),
        E("dsh-gui-last-session", "dsh-gui-last-session", "重启 DeepSeek Harness 后自动回到最近一次对话；实现方式是在 DSH 数据目录里保存一个指针文件，不修改引擎文件。", "fileops", 0, "session"),
        E("dsh-handoff-button", "dsh-handoff-button", "为每条 AI 回复添加 Handoff 按钮，点击后由 LLM 将当前会话总结为交接文档，写入该会话工作区的 handoff/ 目录。", "fileops", 0, "session"),
        E("dsh-handoff-session", "dsh-handoff-session", "为 DeepSeek Harness 提供会话交接：上下文压力到阈值时写交接文档与可搜索转录，并在新会话里自动继续。", "search", 0, "session"),
        E("dsh-healthcheck", "dsh-healthcheck", "面向 DSH 的会话健康体检（只读）：全库扫描（总量、最大会话、体积 / 事件数超限告警）与单会话深检（尾部闭合检查、工具调用 / 结果配对、事件类型分布）。", "session", 0, "session"),
        E("dsh-hold", "dsh-hold", "暂缓发送一条消息，直到主智能体空闲、没有子智能体在运行、也没有后台任务，然后再发出。每条暂缓可以设置发送时间，并选择排队、等待空闲或立即插话，消息与附件都保存在宿主端，重启也不会丢失。", "time", 0, "session"),
        E("dsh-huiyou", "dsh-huiyou", "把 DSH 会话删除到可搜索的回收站，再从侧栏恢复或彻底删除。仅限 DSH Desktop：需装进 Desktop profile，且只支持 Desktop 的 Web GUI。", "fileops", 0, "session"),
        E("dsh-idle-compact", "dsh-idle-compact", "会话上下文超过可配置的 token 阈值、且用户空闲达到可配置时长后，在模型 KV 缓存过期前自动压缩会话；两项设置都在插件管理器的插件页面中修改。", "archive", 0, "session"),
        E("dsh-image-once", "dsh-image-once", "同一张图片只在它第一次出现的那一次请求里以 base64 内联；之后的每次请求都携带被标记为 offloaded 的同一个块，由 DSH 自带的图片 offload 投影渲染成带本地只读路径的占位文字。记账键是会话 id、消息 id、内容树路径与 attachment id 的组合，且请求产生第一个", "image", 0, "session"),
        E("dsh-intent-debt-radar", "dsh-intent-debt-radar", "把聊天里被顺口搁置的“回头再说”记成一份带利息的账本：每句承诺是一张卡，搁得越久排名越靠前，点一下回到当初那句话所在的会话。", "session", 0, "session"),
        E("dsh-interject", "dsh-interject", "把排队中的消息提前到下一个 step 边界送达，而不是等整个 turn 结束；默认不打断已经在跑的模型调用，打断是显式开启的模式。", "session", 0, "session"),
        E("dsh-interrupted-resume", "dsh-interrupted-resume", "轻量级的 dsh 崩溃恢复：重启后识别上一轮被强杀中断的会话，注入一条「先核实现状再动手」的续跑指令，避免盲目重做已有副作用的操作。只认真正的崩溃信号（turn/end 的 reason 为 interrupted，由 session repair 冷读时合成），因此不会把用户主动取消、限流或模型报", "session", 0, "session"),
        E("dsh-knj-session-management", "dsh-knj-session-management", "DSH 会话管理：归档、恢复、删除持久化会话，按工作区限制会话数量上限，并提供体积治理面板。", "archive", 0, "session"),
        E("dsh-lark-session-monitor-plugin", "dsh-lark-session-monitor-plugin", "以用户本人身份监听飞书会话，把新消息作为 prompt 投递到指定的 DeepSeek Harness 会话：每个监听支持发送者过滤、@机器人提及与关键词黑白名单，可自动创建并固定目标会话，游标式轮询在投递失败后会重读消息。", "session", 0, "session"),
        E("dsh-linked-folders", "dsh-linked-folders", "多文件夹工作区：全局链接文件夹列表 + 会话内临时挂载（link_folder/unlink_folder），侧边栏管理并支持系统选目录。", "fileops", 0, "session"),
        E("dsh-local-share", "dsh-local-share", "把完整 Web Session 导出为本地 Markdown 或自包含 HTML，提供稳定的 Markdown 渲染预览、默认脱敏和可选的有界工具调用详情。", "pdfdoc", 0, "session"),
        E("dsh-lorebooklike-prompt-tool", "dsh-lorebooklike-prompt-tool", "类世界书的 DSH 提示词规则：分层系统提示锚点、蓝绿灯条目、可复现概率门与正则替换。", "text", 0, "session"),
        E("dsh-material-library", "dsh-material-library", "dsh 材料库：把对话里产出的目录、文件或笔记收进真实文件夹并打标签，按 Finder 方式浏览，点一下跳回原始会话。内置 materials_archive 工具与自动归档规则：手动收过一次某任务的成品，之后每次定时任务跑完都会自动把新成品收进同一个文件夹。", "archive", 0, "session"),
        E("dsh-md-export", "dsh-md-export", "在会话标题栏加入「导出 MD」按钮，经系统原生保存窗口把当前会话导出为干净的 Markdown，并提供共用同一渲染核心的命令行与 HTTP 路由；直接读取会话日志（支持 v0、v3、v4 格式），且不声明任何 @deepseek-ai peer 依赖。", "pdfdoc", 0, "session"),
        E("dsh-message-actions", "dsh-message-actions", "为对话消息添加撤回、删除、删至末尾、多选分享与导出，并提供每条回答的用量统计与 DeepSeek 余额费用统计。", "text", 0, "session"),
        E("dsh-one-click-session-delete", "dsh-one-click-session-delete", "为 DeepSeek Harness 工作区侧栏增加会话一键永久删除：行悬停垃圾桶按钮、菜单项、确认框、运行中保护、派生会话级联，并清理会话日志目录、投影缓存与工作区记账。", "fileops", 0, "session"),
        E("dsh-period-report", "dsh-period-report", "自由周期会话报告：任意日期区间的 AI 叙事日报/周报/月报，支持每隔 N 天定时提醒并弹系统通知（macOS / Linux）。", "time", 0, "session"),
        E("dsh-phone-inbox", "dsh-phone-inbox", "列出当前会话通过微信桥实际收到的附件，并按需将其中一个采纳到工作区。", "session", 0, "session"),
        E("dsh-plugin-agent-groups", "dsh-plugin-agent-groups", "把多个已打开的 DSH 会话组织成一个协作群，只转达每轮最终输出，并按共享时间线合并投递。", "time", 0, "session"),
        E("dsh-plugin-archived-conversations", "dsh-plugin-archived-conversations", "在设置界面管理已归档对话：一键取消归档，或经确认后永久删除。", "archive", 0, "session"),
        E("dsh-plugin-btw", "dsh-plugin-btw", "新增 /btw 与 /side 斜杠命令，在隔离的分叉子会话中回答临时旁问，不污染主会话上下文。", "session", 0, "session"),
        E("dsh-plugin-conversation-purge", "dsh-plugin-conversation-purge", "彻底删除对话，可选择同时删除该对话创建的文档与附件。", "session", 0, "session"),
        E("dsh-plugin-goal-map", "dsh-plugin-goal-map", "目标进展图以只读流程图展示目标到计划的进展路线、会话思维导图与步骤列表，按已报告计划计算进度，不启动任务或模型调用。Beta.2 支持 DSH Web 0.2.0-rc.2 或 0.2.1-rc.2、Node.js >=24。", "session", 0, "session"),
        E("dsh-plugin-mark-unread", "dsh-plugin-mark-unread", "给工作区会话行补一个手动「标记为未读」；官方支持同能力后自动退休。", "session", 0, "session"),
        E("dsh-plugin-multi-chat-windows", "dsh-plugin-multi-chat-windows", "话分两头：把 AI 对话从「切来切去」变成「并排开火」——每个会话一枚原生小窗，贴着主对话随开随用；一键平铺所有窗口（顶对齐·同高·紧贴），最小化到带实时状态灯的底部停靠条（转圈=工作中·绿色=刚完成·黄色=待审批·灰色=空闲），真浏览器里还能把会话弹出成独立浏览器窗口。", "session", 0, "session"),
        E("dsh-plugin-projectless", "dsh-plugin-projectless", "无需选择项目文件夹即可开始对话，为每次聊天分配持久工作目录，并沿用 Harness 原生会话存储。", "fileops", 0, "session"),
        E("dsh-plugin-session-colors", "dsh-plugin-session-colors", "给 DeepSeek Harness 的每个会话标颜色：悬停侧栏会话行即可选色（12 色），被标色行显示同色竖条，宿主侧持久化。", "session", 0, "session"),
        E("dsh-plugin-workspace-archive", "dsh-plugin-workspace-archive", "工作区文件夹被删除或移走、或工作区登记被移除时，自动归档其会话；目录或登记回归时恢复：只取消归档本插件归档过的会话，把台账记过的全部成员挂回分组（含你手动归档的会话，且不改其归档状态），并把「无项目」里工作目录正是该工作区路径的会话归位。", "archive", 0, "session"),
        E("dsh-plugins-7", "dsh-session-ops", "给侧栏会话行菜单补上三项操作：打开工作区位置、移动到其它工作区、删除会话（进回收站，可撤销）。", "session", 0, "session"),
        E("dsh-plus", "dsh-codex-import", "把 Codex / Claude Code 历史会话一键导入 DeepSeek Harness：同路径项目自动归并进现有工作区，支持交接书摘要或全量转录，导入历史可回滚。", "fileops", 0, "session"),
        E("dsh-prompt-assembler", "dsh-prompt-assembler", "独立提示词装配插件，提供来源注册、自定义文本、策略编辑与预览，通过 DSH 公开钩子按会话应用策略快照。", "session", 0, "session"),
        E("dsh-prompt-enhance-1", "dsh-prompt-enhance", "dsh-prompt-enhance 的维护分支，已适配 DSH 0.1.7——此前的版本在当前宿主上甚至无法加载（InputState.imageIds 已更名为 attachmentIds，输入框按钮会让整个输入区崩溃；settings.get() 已被移除；/enhance 读取了 agent", "git", 0, "session"),
        E("dsh-qq-voice", "dsh-qq-voice", "给 QQ 那一条线单独装一张嘴：把口径文件挂成那段会话的系统提示段，只挂 QQ，别的线一个字不动；改 md 就生效，不必重装插件。须把 home 指向放有口径文件（默认 QQ线口径.md）的目录才生效；应挂进 QQ 的 preset，而非全局插件列表。", "fileops", 0, "session"),
        E("dsh-quickly-clear", "DSH-Quickly-clear", "只给已归档对话的菜单加一项删除，确认后把会话日志目录、投影缓存、归档与置顶标记、工作区记账一起清掉。", "archive", 0, "session"),
        E("dsh-quilt-compact", "dsh-quilt-compact", "压缩后端，替代默认的 compaction-basic：用可配置的低成本模型池压缩对话内容，按所选模型的上下文窗口切块，并将所有摘要一次归并，支持逐路由冷却与会话模型兜底。", "archive", 0, "session"),
        E("dsh-rebuild", "dsh-rebuild", "DSH 环境一站式整合包：根目录是可从市场一键安装/更新的工作区美化插件，pack/ 子目录是任务列表、编码兼容、LSP/审查、视觉与白皮书的完整安装器。", "codec", 0, "session"),
        E("dsh-recap", "dsh-recap", "通过 /recap 或闲置触发回顾当前 DeepSeek Harness 会话，支持配置模型、中英文输出，并在对话内展示可展开的摘要。", "session", 0, "session"),
        E("dsh-recent-sessions", "dsh-recent-sessions", "在 DSH Web 侧栏底部加一块可折叠的「最近」列表：跨工作区按最后活动时间排序，过滤空白、已归档与 subagent 会话，复用宿主状态点，首屏 10 条、每次点击再多 10 条。", "archive", 0, "session"),
        E("dsh-recent-sessions-2", "dsh-recent-sessions", "跨所有工作目录的扁平会话列表：显示最后一句提问、按时间分组、全文搜索，并让随手记下的想法在重开会话时提醒。是 huangxp12/dsh-recent-sessions 的重写分支，界面按原生样式重做；两者注册同一个 recent-sessions 面板 id，不要与原版同装。", "git", 0, "session"),
        E("dsh-recycle-bin", "dsh-recycle-bin", "把 DSH 会话删入可恢复的回收站——子会话随其父会话作为一棵树处理，支持批量归档、恢复与彻底删除，只有彻底清除才会真正销毁数据。", "archive", 0, "session"),
        E("dsh-restart-autoresume", "dsh-restart-autoresume", "通过现有兼容的 dsh-restart Host 提供方，为符合条件的顶层会话增加确认式 DSH 重启与持久自动续作。", "archive", 0, "session"),
        E("dsh-restart-task", "dsh-restart-task", "修复被打断的 DSH 回合：放大产品自带的重试预算并把等待渲染成同一步内的实时倒计时，输出被截断时在同一轮内续写，回合已结束时可选地新开一轮继续；输入框为空时把「继续」交给发送键。", "time", 0, "session"),
        E("dsh-rich-indexing", "dsh-rich-indexing", "分级压缩中枢：把单一的 80% 压缩阈值换成可配置的阶梯（默认 30/50/70/90），逐级加强压缩力度；每次检查点都折叠入确定性关键词索引，让事实跨周期累积；摘要走模型链——主模型加最多 3 个回退，各自独立推理档位。附带 Compaction 模块子标签页与设置卡片；关闭插件始终恢复原版压缩。", "archive", 0, "session"),
        E("dsh-rollover", "dsh-rollover", "上下文滚段：窗口快满时自动存档接续前情，换段后自动注入一次。两个工具 + 设置面板。", "session", 0, "session"),
        E("dsh-seesion-copy-enhance", "dsh-seesion-copy-enhance", "复制用户消息时连同图片与文件一起捕获，粘贴到任意会话：文字进入输入框，每个附件经官方 createDrafts/addAttachments 通道重建为真实草稿，可正常上传并发送。", "image", 0, "session"),
        E("dsh-self-restart", "dsh-self-restart", "把「重启宿主」变成一次中断、多个会话共用：若干会话可以排进同一次重启（默认上限 8 个、可配置，任意时刻都能加入，等待途中也行），宿主只关一次、只拉起一次，随后按名单逐个唤醒，每个会话拿回自己写下的理由并各自开工，互不等待。每个会话独立决定要不要续接，某一条投递失败不影响其余，某个会话也能只摘掉自己", "session", 0, "session"),
        E("dsh-send-debounce", "dsh-send-debounce", "把聊天框里连发的几条短消息缓冲合并成一轮再唤醒模型：停手若干秒后才回复一次；长消息和附件不延迟。", "session", 0, "session"),
        E("dsh-send-timestamp", "dsh-send-timestamp", "在输入框工具栏加一个「时间戳」开关：开启后，你提交的每条消息后面会跟一条隐藏的上下文消息，携带发送时刻的本地时间，模型因此知道你是什么时候发的；开关按会话分别记住。", "git", 0, "session"),
        E("dsh-sensenzi-conversation-search", "dsh-conversation-search", "0.2.0-beta.2 仅支持 DSH 0.2.1-rc.2，面向宿主所有者使用。在当前会话或同目录工作区搜索用户与助手原文，查看来源坐标和上下文；不支持非所有者身份的会话级授权。", "fileops", 0, "session"),
        E("dsh-session-artifacts", "dsh-session-artifacts", "右栏标签页：把各个 DSH 会话产出过的文件列成一列，当前会话置顶并默认展开；单击复制文件完整路径，双击在侧栏预览，文件可以单独置顶到本会话或全局置顶。", "fileops", 0, "session"),
        E("dsh-session-attachment-repair", "dsh-session-attachment-repair", "在设置页列出历史引用了本地附件库中已丢失对象的会话，先备份日志、再把悬空引用替换成文本占位，使这些会话能重新发送消息。修复脚本需要 Node 22.15 及以上；设置卡片目前仅在 Windows 上验证过。", "text", 0, "session"),
        E("dsh-session-autarchive", "dsh-session-autarchive", "把长期没动过的会话自动归档（默认 5 天，已归档、置顶、标记「不自动归档」的跳过）——会话右键菜单可标记单条会话，行首显示盾牌，通用设置里改天数。", "archive", 0, "session"),
        E("dsh-session-auto-rename", "dsh-session-auto-rename", "在每个会话的侧栏菜单里新增「自动重命名」：模型读取会话日志，按时间衰减给用户消息加权（τ = 3 天，越新权重越高），写出不超过 10 个汉字的标题并写入会话名。同时支持右键会话呼出该菜单，并把同一操作暴露为 session_auto_rename 智能体工具。需要 DSH 0.2.1-rc.5 或", "time", 0, "session"),
        E("dsh-session-autotitle", "Automatic-session-renaming-for-dsh", "DSH 会话自动重命名（session rename）：基于全部会话消息的 LLM 总结标题，首条提示词与 /handoff 后自动命名，会话头按钮或 /autotitle 手动触发，标题语言与最大字节数可设置。", "fileops", 0, "session"),
        E("dsh-session-bar", "dsh-session-bar", "侧栏会话状态条：会话跑起来时整行变成绿色卡片，底部一条带流动小点的进度条按估算时长推进，行首直接显示完成百分比，超时后改显示精确到秒的已用时长；跑完后整行转橙并一直亮着，直到你点开那条对话才熄灭。不用切过去看，瞄一眼侧栏就知道每条会话在干嘛。", "session", 0, "session"),
        E("dsh-session-bin", "dsh-session-bin", "按工作区管理原生归档，支持搜索、取消归档、单项和固定范围批量永久删除。", "archive", 0, "session"),
        E("dsh-session-chains", "dsh-session-chains", "把互相交接的對話自動聚成一條鏈：從交接提示詞自動判定、場次編號、就地改名、搜尋、拖拉／多選歸鏈、把鏈置頂、把鏈封存進面板裡的封存庫（側欄不再顯示，有新場次也留在封存庫）、本場上下文與請求數讀數，以及可調的交接門檻（達到可自動交接：寫提示詞→開新對話→貼上→切換）。", "session", 0, "session"),
        E("dsh-session-clean-delete", "dsh-session-clean-delete", "在侧栏会话菜单中增加「永久删除会话」的操作，并附带确认对话框：对话框会说明会话日志大小，以及与该会话绑定的进行中轮次、子代理、后台任务和提醒；删除后 id 会从 live、归档与工作区登记中一并释放，因此刷新列表时该行不会复活。", "archive", 0, "session"),
        E("dsh-session-cleaner-host", "dsh-session-cleaner-host", "从侧栏会话菜单删除整个会话；聊天里划词右键弹出「复制 / 引用 / 提问」：引用把 Markdown 引用块插入输入框，提问把选区与问题交给同一个复用的可继续子智能体（label `ask`，宿主重启后经子智能体目录找回），回答在右侧栏流式显示。", "pdfdoc", 0, "session"),
        E("dsh-session-cleanup", "dsh-session-cleanup", "按工作区批量清理会话：查看归档状态，把会话日志、投影缓存和工作区记录一起彻底删除。", "archive", 0, "session"),
        E("dsh-session-colors", "dsh-session-colors", "给任意会话加上颜色标记：在侧栏显示色条、从会话头部选择颜色；标记保存在宿主上，一台设备选的颜色在其他设备上同样可见。", "session", 0, "session"),
        E("dsh-session-concurrency", "dsh-session-concurrency", "按根会话设置 1–10 路推理并发；设为 1 时排队原生子任务派发、按分支串行执行，并让父 Agent 等待结果。", "git", 0, "session"),
        E("dsh-session-delete", "dsh-session-delete", "在侧栏会话菜单里删除会话：日志与投影缓存移入回收站（Windows；其它平台移到本地回收目录）；正在使用的会话排队到下次启动时删除。", "fileops", 0, "session"),
        E("dsh-session-delete-2", "dsh-session-delete", "DSH 会话管理：列出全部会话并显示各自的磁盘占用，可按标题、会话 ID、类型标签、工作区或 agent preset 搜索，并按时间或工作区分组。支持单个或批量永久删除——同时清除日志文件、工作区账目与搜索索引，删除前两步确认、删除后复验；可按需显示子代理会话，侧边对话线程始终隐藏，本次启动中活动", "net", 0, "session"),
        E("dsh-session-delete-3", "dsh-session-delete", "在侧栏会话“…”菜单的“归档会话”下方新增红色“删除会话”行，永久删除该会话的日志与工作区账目（走 workspace registry 自己的持久化写）。第二次点击确认后该行立即从列表消失；当次启动使用过的会话会先从内存停用再删（不会复活）；正在跑任务的会话会再显示一次警告，点下去先停止任务再删除", "archive", 0, "session"),
        E("dsh-session-delete-5", "dsh-session-delete", "在会话行菜单中永久删除会话：先归档、再删除日志目录并立即移除该行，带 Delete 快捷键；只使用官方扩展点，仅打开过、未在运行的会话依然可以删除。", "archive", 0, "session"),
        E("dsh-session-delete-6", "dsh-session-delete", "在侧边栏会话菜单里二次确认后删除会话：移除会话日志目录、投影缓存记录与工作区/置顶/归档记账；所有注册表调用带超时保护，工作区注册表卡住也能完成删除。", "archive", 0, "session"),
        E("dsh-session-delete-8", "dsh-session-delete", "在侧边栏会话菜单添加「删除」项，经二次确认后硬删除该会话。", "session", 0, "session"),
        E("dsh-session-delete-next", "dsh-session-delete-next", "在侧栏会话菜单中加入「删除会话」，永久删除该会话的本地记录；正在运行的会话会被拒绝。", "session", 0, "session"),
        E("dsh-session-dm", "dsh-session-dm", "跨会话投递：往同工作区的另一个会话发消息，并可新建顶层会话。", "session", 0, "session"),
        E("dsh-session-eval", "dsh-session-eval", "回溯式会话评估：从持久化日志生成确定性成绩卡与跨会话回归对比——不跑基准、不用 LLM 裁判。", "session", 0, "session"),
        E("dsh-session-export-1", "dsh-session-export", "会话证据报告：/transcript 从权威日志生成 HTML/Markdown/JSON 报告，/stats 输出终端统计卡，/archive 打包单会话 ZIP。", "pdfdoc", 0, "session"),
        E("dsh-session-focus", "dsh-session-focus", "从会话行、悬浮卡或会话头一点即可标记「进行中／挂起」；侧边栏底部和折叠的工作区名旁始终显示还有几条。面板把标记过的会话与侧边栏本就跟踪的状态（等待回复、在跑、已完成未查看）列在一起，底部读数则直接跳到最该处理的那一条。", "session", 0, "session"),
        E("dsh-session-fulltext-search", "dsh-session-fulltext-search", "开启 dsh 内置但默认关闭的会话全文搜索后端（session-query-sqlite，SQLite FTS5），侧边栏放大镜即可搜索消息正文并附摘要，而不只是标题。", "data", 0, "session"),
        E("dsh-session-guard-1", "dsh-session-guard", "预防并发写导致的会话损坏：在会话开始及每一步获取按会话的咨询锁，第二个 dsh 进程会明确报错而非写出重复 seq 断层；死进程持有的锁自动接管。", "sysinfo", 0, "session"),
        E("dsh-session-history-search", "dsh-session-history-search", "侧栏全局搜索历史对话：字面子串匹配（中文可用），结果按会话分组并高亮命中片段，点一下跳回那个会话。", "search", 0, "session"),
        E("dsh-session-id-copy", "dsh-session-id-copy", "在 DSH Web 界面的对话标题旁显示 6 位 session id 徽标，点击即复制完整 session id 并给出短暂提示。", "session", 0, "session"),
        E("dsh-session-id-for-desktop", "dsh-session-id-for-desktop", "在会话行的「⋯」菜单里补上复制会话 ID，以及永久删除会话（日志、投影缓存与工作区引用），删除前有二次确认。", "session", 0, "session"),
        E("dsh-session-inherit", "dsh-session-inherit", "会话菜单新增「继承」：把长会话里的具体锚点（任务原文、最近的用户指令、改过的文件、最近的失败、命令、待办）机械提取成交接单，在干净的新会话里接着干——预设默认一并继承，不复制历史，也不调用模型。", "fileops", 0, "session"),
        E("dsh-session-intent-title", "dsh-session-intent-title", "零 UI 侵入的 DeepSeek Harness 会话意图自动分类命名插件，新会话自动生成前缀图标与主题（优化、修复、功能、探索等 8 类意图）。", "session", 0, "session"),
        E("dsh-session-janitor", "dsh-session-janitor", "在侧边栏页面里列出 DSH 的会话记录与归档缓存，删除先移入可恢复的回收站，最近 10 分钟仍在写入的会话会被拒绝。", "archive", 0, "session"),
        E("dsh-session-keeper", "dsh-session-keeper", "DeepSeek Harness 侧栏的会话管理插件：按工作区划分的分类树，支持拖拽排序；置顶会话可抬到分类上方，也可按开关留在所属分类内；另有归档分区，以及删除回收站——删掉的会话日志留存，可恢复或批量彻底清除。宿主半边掌管分类与回收站数据，网页半边负责渲染，两者作为一个插件一起发布。本插件是 h", "archive", 0, "session"),
        E("dsh-session-keepwarm", "dsh-session-keepwarm", "让浏览器最近用过的会话保持常驻：切走再切回来直接复用已加载的历史、不再重新读取；常驻数量可配置，并可整体关闭。", "session", 0, "session"),
        E("dsh-session-lazy-view", "dsh-session-lazy-view", "只读会话惰性查看器：仅 stat 列出会话，再只解压尾部 Zstandard 帧查看最近事件；独立 /lazyview 面板支持搜索、统计和导出。需 Node.js 24+。", "archive", 0, "session"),
        E("dsh-session-leftover-purge", "dsh-session-leftover-purge", "在 DeepSeek Harness 中删除会话后，清理 billion-context 快照；cost-meter 账本记录的清理默认关闭，可在设置里打开。", "session", 0, "session"),
        E("dsh-session-lock", "dsh-session-lock", "侧栏每个会话行上的锁按钮：锁定的会话经客户端 workspaces.archiveSession 归档时（⋮ 菜单，或其它插件调用的同一方法）会被拦下并提示；锁清单持久化在宿主侧，另有批量归档不活跃会话的宿主路由，永远跳过已锁定的会话。直接打到宿主注册表的调用不在拦截范围内。", "archive", 0, "session"),
        E("dsh-session-mail", "dsh-session-mail", "同一宿主内 DSH 会话之间的代理传话。`send_session_message` 可等对方回合结束再送达、也可插进正在跑的回合；发信方 id 由插件自己写，伪造的 From 抬头会被拒；每条消息带 id —— 回信可用 replyTo 引用、thread 防止同一件事排队两次、supersede", "net", 0, "session"),
        E("dsh-session-manager-3", "dsh-session-manager", "彻底删除 DSH 会话，并在一个控制台里集中管理：单条删除、可筛选的批量清理与维护清扫。", "session", 0, "session"),
        E("dsh-session-manager-8", "dsh-session-manager", "DSH Web 会话管理插件：在设置页查看全部与已归档会话，支持恢复（取消归档）、二次确认删除与对话内容预览。", "archive", 0, "session"),
        E("dsh-session-map", "dsh-session-map", "会话图谱：把 DSH 会话画成一张 fork 树画布，另在设置里加了一个「从 Git 克隆」页——填仓库地址、选存放目录（会记住上次选择、带原生目录选择器），按需打开浅克隆，克隆完自动添加为工作区。画布可从会话头部开关和右侧栏两个标签页打开，对话标签页默认关闭；默认只铺开当前会话所在的那棵树、自上而", "git", 0, "session"),
        E("dsh-session-menu-delete", "dsh-session-menu-delete", "在侧边栏会话三点菜单的「归档会话」下面加一项「删除会话」：先把会话从内存里摘掉，再删磁盘记录与投影缓存，并立刻移除左侧那一行。永久删除，没有回收站。", "archive", 0, "session"),
        E("dsh-session-migrate", "dsh-session-migrate", "DSH 会话跨版本迁移：扫描旧版会话目录（v0 明文、.zstd 与 .zip 导出包），改写 header cwd 绑定目标工作区并落盘，打开会话时由持久化层自动完成版本升级；设置侧边栏（环境 / 导入 / 列表 / 转换）加 CLI（check / fix / import）。", "archive", 0, "session"),
        E("dsh-session-mindmap", "dsh-session-mindmap", "把 DSH 会话整理成一张自包含的交互式 HTML 脑图（主题、结论、决策、待办、未决问题），并给出与上一次生成相比的变更。", "fileops", 0, "session"),
        E("dsh-session-mng", "dsh-session-mng", "在设置里管理全部 DeepSeek Harness 会话：按工作区分组浏览活跃与已归档会话，为活跃或已归档会话按整段对话生成标题，归档/恢复，把冷会话移动到其他工作区，并在确认后彻底删除已归档会话（含其子代理会话）。", "archive", 0, "session"),
        E("dsh-session-monitor", "dsh-session-monitor", "只读的本机 DSH 会话监视器：实时任务看板、会话事件尾随、阻塞等待回复、Markdown 导出，可选配合 dsh-im 推送 IM。需要 Python 3 与 zstandard 库；IM 推送需另装 dsh-im。", "pdfdoc", 0, "session"),
        E("dsh-session-move", "dsh-session-move", "在 Web UI 中把会话移动到其他文件夹、永久删除，或进行 AI 重命名——支持把会话行拖到文件夹标题上，也可从会话菜单操作。移动会重写会话头的 cwd、迁移持久化日志并更新工作区账目，历史随会话一起走；删除会先停止运行中的 agent，再移除日志、投影缓存行与工作区账目。同样提供三个 agent", "fileops", 0, "session"),
        E("dsh-session-move-1", "dsh-session-move", "在工作区之间安全移动会话：移动前校验运行中/子代理/离线状态，每次移动自动备份到 ~/.dsh/session-move-backups/。", "net", 0, "session"),
        E("dsh-session-nav-1", "dsh-session-nav", "对话旁的悬浮按钮，打开当前会话全部提问的可搜索列表并快速跳转；悬浮弹出/移出平滑关闭。", "search", 0, "session"),
        E("dsh-session-path", "dsh-session-path", "复制会话日志路径（或可直接粘贴的接续块），并把多帧 zstd 会话日志转成可读文件，供另一个会话读取接续。", "fileops", 0, "session"),
        E("dsh-session-radar", "dsh-session-radar", "DSH Web 侧边栏的未读、待办与状态读数中枢：铃铛按顺序定位未读会话，快捷键依次走到正在等你输入的会话，⌘⇧, / ⌘⇧. 在访问过的对话之间前后切换；另有总览把未读与待决策会话分两区铺开；底部一行六项会话状态读数，每个图标都能点，点了跳到下一个同类会话；账本落在 host 半边，重启也不丢——", "session", 0, "session"),
        E("dsh-session-rail", "dsh-session-rail", "DSH 右侧栏的进度页：会话每一轮的状态与长任务上报的进度集中在一个 tab 里，和对话并排看。", "session", 0, "session"),
        E("dsh-session-recall", "dsh-session-recall", "确定性跨会话检索：`recall` 工具带显式范围控制地搜索历史会话日志。", "search", 0, "session"),
        E("dsh-session-recycler", "dsh-session-recycler", "在 DeepSeek Harness 网页界面里真正删除会话记录：带可恢复、可彻底清除的回收站。本插件与 zhezhi33/dsh-session-recycler 安装后的包名同为 dsh-session-recycler，请只装其中一个。", "session", 0, "session"),
        E("dsh-session-rename", "dsh-session-rename", "给模型一个 rename_session 工具，让 agent 在对话中直接重命名会话。", "fileops", 0, "session"),
        E("dsh-session-rename-1", "dsh-session-rename", "新增 session_rename 工具，让 AI 能重命名自己所在的 DSH 会话。", "fileops", 0, "session"),
        E("dsh-session-resilience", "dsh-session-resilience", "为 DSH 增加重启和停止控制、基于令牌的重连，以及用于恢复中断 Web 会话的策略。", "session", 0, "session"),
        E("dsh-session-rotate-on-compact", "dsh-session-rotate-on-compact", "在每次 DSH 成功 Compact 后轮换对外 LLM 会话 ID，而不创建新的 DSH 会话。", "session", 0, "session"),
        E("dsh-session-search", "dsh-session-search", "跨会话全文搜索：对持久化 DSH 会话日志建立增量消息级索引，返回 sessionId、seq 与摘录；提供 agent 工具和独立面板。需 Node.js 23.5+。", "search", 0, "session"),
        E("dsh-session-snapshot", "dsh-session-snapshot", "在每个回合边界为会话滚动保留校验过的备份：提升快照前先确认日志仍可加载，回合结束时若已损坏则绝不覆盖上一份好副本，dsh 启动不了时也能一条命令恢复。", "session", 0, "session"),
        E("dsh-session-sweeper", "dsh-session-sweeper", "会话清道夫：在 DSH 设置中扫描、查看并安全清理本机 AI 终端会话历史（Claude Code、Codex CLI、WorkBuddy、DSH），隔离优先、带 SHA-256 清单与一键整批恢复，彻底删除需输入确认短语。", "session", 0, "session"),
        E("dsh-session-sync", "DSH-Session-Sync", "双向同步网页版与 DSH Desktop 桌面版之间的会话、工作区、设置与插件。", "session", 0, "session"),
        E("dsh-session-tidy", "dsh-session-tidy", "删除整个 DSH 会话，或只删除会话中某一轮已完成的对话：带二次确认、运行中 Agent 安全停止、路径与身份校验、改写前备份，后续轮次自动顺延。", "fileops", 0, "session"),
