        E("dsh-surrogate-guard", "dsh-surrogate-guard", "在工具输出写入会话日志前中和落单的 UTF-16 代理字符，避免会话永久 400 无法继续。", "net", 0, "session"),
        E("dsh-task-groups", "dsh-task-groups", "给侧边栏加上自定义任务分组和活动铃铛：把会话拖进拖出分组、手动排序、折叠分组，并在一处集中查看运行中、待确认和未读的会话。", "text", 0, "session"),
        E("dsh-temp-chat", "dsh-temp-chat", "用 /single-turn 与 /multi-turn 在独立子代理中作答，结果只留在当前对话，不进入主模型上下文。", "net", 0, "session"),
