        E("dsh-claude-memory", "dsh-claude-memory", "只读桥接 Claude Code 已有项目记忆到 DSH：按 git 仓库根解析、注入前脱敏、按需检索工具，零依赖。", "git", 0, "memory"),
        E("dsh-codex-memory", "dsh-codex-memory", "Codex V2 记忆流水线到 DeepSeek Harness 的移植：后台 agent 逐个抽取空闲会话，整合阶段在 git baseline diff 之后把它们合成一份 memory_summary.md，新会话注入这份摘要，被引用的记忆回流成使用计数。设置页可选模型、两个阶段的思考强度，以", "git", 0, "memory"),
        E("dsh-cognition", "dsh-cognition", "给 DSH agent 的项目记忆:历史相似编辑作为先例出现、越界修改被 scope 锁拦下、认知跨会话持续积累(47 次上游验收修复、去 gold 化 20/20)。", "session", 0, "memory"),
        E("dsh-compaction", "dsh-compaction", "压缩后端：用确定性语义提取器替换 LLM 摘要（保留代码/路径/命令，剔除闲聊），附带 28.4x KV 压缩记账。", "archive", 0, "memory"),
        E("dsh-company-kb", "dsh-company-kb", "DSH 本地文件夹知识库：把 Office、文本、PDF 与扫描件建成 SQLite FTS5 索引，提供 kb_search / kb_read / kb_list / kb_status / kb_session 五个工具与 Web 面板；仅在用户点名时检索，仅在手动触发时同步。", "pdfdoc", 0, "memory"),
        E("dsh-context-budget-2", "dsh-context-budget", "长对话裁剪工具：trim_context / estimate_context_tokens 保留系统人设与最后一条消息，按轮丢弃最旧的用户/助手对话以压到轮数或 token 预算内，并回报裁剪前后的估算；不调用工具就不会自动裁剪。", "session", 0, "memory"),
        E("dsh-decay-memory", "dsh-decay-memory", "带遗忘曲线的代理记忆：被提起就变牢、不提就变短，📌 的永不淡忘。六个工具 + 设置面板。", "net", 0, "memory"),
        E("dsh-derive-watcher", "dsh-derive-watcher", "DSH 语义上下文观察器，维护旅程台账并做闪存摘要与 MinHash 新颖度检测，支持里程碑折叠、长期上下文注入与三级停滞响应；注入与 stall-2/3 响应默认关闭。", "codec", 0, "memory"),
        E("dsh-dev-progress-memory", "dsh-dev-progress-memory", "逐轮开发进度记忆：每轮完成后分类写入 doc/progress/ 下按日期索引的 Markdown 文件并维护 INDEX.md，系统级问题记入跨项目 SYSTEM_MEMORY.md 并在出现报错关键词时重新注入，progress_read 工具可按需读取完整文档。", "pdfdoc", 0, "memory"),
        E("dsh-dream", "DSH-DREAM", "面向 LLM Agent 的持久化 RAG 增强长期记忆层，支持全息记忆、状态槽位冲突检测与时间线检索。需要 Python 3.10+，并先在仓库里建 venv 执行 pip install -e \".\\[dev]\" 装好 Python 依赖后再启用插件；仓库自带安装脚本为 PowerShell（W", "git", 0, "memory"),
        E("dsh-engramory-recall", "dsh-engramory-recall", "给 Engramory 记忆库加本地 BM25 自动召回、写入闸门、静态体检与记忆面板。不联网、不起进程，默认不调模型；召回质量由仓库里的可复算基准量化。", "git", 0, "memory"),
        E("dsh-evolver", "evolver-dsh-plugin", "越用越聪明的 harness，告别金鱼记忆。每条 prompt 前，Evolver 从本地经验和 EvoMap 网络召回一条验证过的策略；回合结束后，它凭测试结果、改动是否被保留、你的下一句反馈给策略打分，再回报网络按证据加权。每一次成功都变成下一次的捷径，每一次失败都变成下一次的避坑指南。", "session", 0, "memory"),
        E("dsh-expmem", "dsh-expmem", "个人经验记忆：把真实解决过的问题存为带来源、可纠正、有适用条件的案例，新任务中自动召回复用，纠正与删除会级联影响后续召回。", "session", 0, "memory"),
        E("dsh-file-memory-1", "dsh-file-memory", "文件型工作记忆：memorize/recall 把关键前提逐字保存在会话笔记文件，无损挺过上下文压缩。", "archive", 0, "memory"),
        E("dsh-flavor-memory", "dsh-flavor-memory", "角色聊天记忆层：人格、语气、关系与摘要分开保存，原文全量归档并按需检索，附带 SillyTavern 角色卡导入和 OpenAI 兼容网关。", "archive", 0, "memory"),
        E("dsh-flomo", "dsh-flomo", "配置一次 flomo API URL / API Key，Agent 即可用 flomo_send 把笔记、摘要、待办写进 flomo（浮墨笔记）。", "ai", 0, "memory"),
