        E("dsh-greatarrow", "dsh-greatarrow", "通过 Streamable HTTP 将 dsh 连接到 GreatArrow.ai MCP 服务器，让智能体检索和保存与你其他 AI 客户端共享的工作区记忆、任务与决策；纯配置包，从 dsh 主目录的 great-arrow.token 读取令牌，从不读取环境变量。", "archive", 0, "memory"),
        E("dsh-headroom-plugin", "plugin", "在 DeepSeek Harness 内以 MCP 方式运行上游 Headroom 压缩工具集（headroom-ai，Apache-2.0）：headroom_compress、headroom_retrieve、headroom_stats 以 mcp__headroom__* 工具暴露，后端是", "archive", 0, "memory"),
        E("dsh-heartprint", "dsh-heartprint", "记忆类插件。可设置名字、性格与人格；只淡忘琐事，重要的会保留，特殊的会被记住。", "session", 0, "memory"),
        E("dsh-hindsight-memory-1", "dsh-hindsight-memory", "把 DeepSeek Harness 接入 Hindsight 记忆服务，沿用与 omp 相同的约定：单一共享 bank、自动打项目标签、项目层与全局层同时召回，并提供精神模型、重复检测与失败后台任务重试工具。需要本机已运行 Hindsight 服务（默认 http://127.0.0.1:8888", "session", 0, "memory"),
        E("dsh-hippo", "dsh-hippo", "海马体：把工作区文件、DSH 记忆和历史会话画成一张可旋转的神经元网络，挂在侧栏随时翻；条目名自动整理成中文短句，每次启动自动重新索引。", "fileops", 0, "memory"),
        E("dsh-inject-scheduler", "dsh-inject-scheduler", "DSH 注入调度器：跨插件注入段的注册/排序/记账落在官方 storageDomain，含冲突检测与每会话预算汇总（B10 面板数据源）。", "text", 0, "memory"),
        E("dsh-inkvault", "dsh-inkvault", "把本地 Markdown 库拆成两个由用户在设置页选择的文件夹：知识库由 DSH 在对话中写入笔记，记忆库作为 agent 的长期记忆，按回合召回、回合结束沉淀候选。纯 Markdown 加 frontmatter、BM25 检索、可逆归档，并用路径隔离拒绝穿越、绝对路径与符号链接逃逸。", "pdfdoc", 0, "memory"),
        E("dsh-inner-life", "dsh-inner-life", "给 agent 的私人日记本：八个零依赖工具负责写、改、翻、导出，正文按日期哈希散落在看似随机的目录里，索引不记路径（需要时由 inner_find 按日给出路径）。", "codec", 0, "memory"),
        E("dsh-knowledge", "dsh-knowledge", "全局知识库桥：kb_add/kb_search/kb_show/kb_timeline 读写与 Codex 共享的 D:\\knowledge（格式逐字节兼容）。", "search", 0, "memory"),
        E("dsh-knowledge-base", "dsh-knowledge-base", "DeepSeek Harness 本地知识库：导入 Word/PPT/Excel/PDF（文字版或扫描版）、EPUB、MOBI/AZW3，生成带页码锚点、OCR 质量/置信度与 PDF 双栏阅读顺序的 Markdown 分块；并提供 LLM 维护的编译层（schema.md 维护规范、自动 inde", "pdfdoc", 0, "memory"),
        E("dsh-lattice", "dsh-lattice", "DeepSeek Harness 的本地记忆插件：写下的内容按主题归档、与相关条目连边，召回按向量相似度排序（没装模型时退回词面匹配），数据存在本地 SQLite 库里。", "data", 0, "memory"),
        E("dsh-layers-hippocampus", "dsh-Layers-Hippocampus", "为 DeepSeek Harness 提供的分层长期记忆：追加式事件日志、可重建标签索引、按天日记、语义层、趋势隔离，以及离线知识图谱面板。", "session", 0, "memory"),
        E("dsh-lesson-loop", "dsh-lesson-loop", "把拦截拒绝、门禁失败与人工差评沉淀为项目教训，只把人工确认过的规则注入该项目之后的新会话；它不注册模型工具，通过设置卡评审规则。", "session", 0, "memory"),
        E("dsh-life-hair", "dsh-life-hair", "上下文压缩时把 checkpoint 原文抄进便签归档，并叫醒会话补写丢掉的内容。", "archive", 0, "memory"),
        E("dsh-limit-break", "dsh-limit-break", "跨会话持久记忆，加一条绕开主机名级封锁的取数阶梯：四个工具——memory_recall / memory_save / memory_stats 读写 $DSH_HOME/memory/facts.json 里的纯 JSON，resilient_fetch 依次尝试直连 fetch → 同服务别名", "data", 0, "memory"),
        E("dsh-local-memory", "dsh-local-memory", "给 DeepSeek Harness 的跨项目长期记忆：每个项目各存各的库，另有一次性看遍全部的查询视图；还能不打开会话就直接从项目的 git 历史播种记忆。", "git", 0, "memory"),
