        E("dsh-memory-1", "dsh-memory", "为 DeepSeek Harness 打造的本地优先、基于文件的记忆插件：支持 Markdown 记忆存储、可验证的信任机制、逐轮次回忆，以及可选的 SQLite FTS5 全文检索。", "pdfdoc", 0, "memory"),
