        E("dsh-memory-director", "dsh-memory-director", "LLM 驱动的记忆记/忘插件：每轮对话后由模型决定记住什么/忘记什么（MemoryDirector），请求前注入相关记忆，自动去重，跨会话持久化。", "text", 0, "memory"),
        E("dsh-memory-eternal-fork", "dsh-memory-eternal-fork", "dsh-memory-eternal 的维护版 fork：对话结束自动沉淀知识卡到本地 Markdown 记忆库并按需召回，修复 DSH 0.2.0-rc.x 兼容性。原项目由 EternalNight996 创建并维护（https://github.com/EternalNight996/dsh-", "pdfdoc", 0, "memory"),
        E("dsh-memory-file", "dsh-memory-file", "文件型长期记忆：每个会话开始注入你自己的 Markdown 记忆文件，提供带备份与撤销的读写工具，并能查出 DSH_HOME 漂移。默认不读对话；可选开启 autoScan 后，才从本机会话日志里提取你自己的发言交给 agent 归档。不联网。", "pdfdoc", 0, "memory"),
        E("dsh-memory-hub", "dsh-memory-hub", "本地优先、文件原生的 DSH 长期记忆，提供每回合预检、紧凑上下文注入、引用、人工批准写入、手动汇总、夜间只读维护，以及一个知识视图只读、可编辑工作区配置的 Web 面板。", "fileops", 0, "memory"),
        E("dsh-memory-keeper", "dsh-memory-keeper", "跨会话记忆：会话自动导出成能读的 Markdown（带出处），维护一份长期 MEMORY.md，新窗口醒来先看摘要。", "pdfdoc", 0, "memory"),
        E("dsh-memory-kit", "dsh-memory-kit", "给 DSH 机器人装五层持久记忆（人设、说话规则、日记、会话存档、未了结的约定），全部存成磁盘上的纯 Markdown；文件改动一分钟内自动重建注入段落，配 memory_read / memory_write / memory_search 三个工具，另带一个从旧记忆目录迁移的导入器。", "pdfdoc", 0, "memory"),
        E("dsh-memory-library", "dsh-memory-library", "按工作区隔离的记忆库，支持按对话手动开启、可编辑规则、三种共用模式和连续遗忘；记忆卡仍是可读的 Markdown。", "pdfdoc", 0, "memory"),
        E("dsh-memory-lite-1", "dsh-memory-lite", "面向「纯文件（markdown 卡片 + git）长期记忆库」的只读增强插件：memory_find 检索工具、一小段受预算约束的记忆库摘要注入，以及带概览/健康/开关的设置页。", "pdfdoc", 0, "memory"),
        E("dsh-memory-observer", "dsh-memory-observer", "在后台把长会话提炼为观察与反思并注入系统提示，压缩时直接用预备记忆渲染摘要；提供设置页与可回溯原文的 memory_recall。", "archive", 0, "memory"),
        E("dsh-memory-palace", "dsh-memory-palace", "DSH 会话的本地长期记忆：上下文压力升高时归档较早轮次，提供四板块分级热记忆、项目档案、记忆家族与根转移（家族名可独立修改，转移保留项目热记忆）、摘要关键词定位与段级候选翻页、手动注入、20K 分段读取和 tag 关联检索；包含分级回忆 cue 与安装后版本校验。数据都保存在工作区。", "archive", 0, "memory"),
        E("dsh-memory-recall", "dsh-memory-recall", "Hermes Agent 风格的 dsh 持久记忆：一个 memory 工具维护用户档案与模型自己的笔记，并在每段对话的开头、记忆变更后、压缩之后各投递一条带记录的消息；session_search 工具只在用户同意后才会读取更早的会话；另有 Memory 面板可查看和编辑已保存的内容。", "archive", 0, "memory"),
        E("dsh-memory-shield", "dsh-memory-shield", "在指定 DSH preset 里挡掉其他记忆插件的上下文段与工具，让该会话拿到干净上下文。bundle 形态、默认关闭，带只读诊断工具。", "session", 0, "memory"),
        E("dsh-memory-snapshot", "dsh-memory-snapshot", "把本地已有的 markdown 文档（笔记、规则、知识库）按路径清单注入 dsh 每个会话的系统提示词，当只读记忆——无数据库、无服务、无写入通道；支持目录收集、UTF-8 字节预算截断、front-matter 剥离与新鲜度时间戳。", "pdfdoc", 0, "memory"),
        E("dsh-memory-studio", "dsh-memory-studio", "DeepSeek Harness 的本地记忆插件：记忆、目录、画像、关系、待审五个分区；规则式自动沉淀，明确区分该记与不该记；父子分块的 BM25 + 向量混合检索；12 个工具读写同一份本地数据。", "fileops", 0, "memory"),
        E("dsh-memory-tide", "dsh-memory-tide", "按工作空间保存日记与长期要点的冷热归档记忆：热档常驻、冷档下沉，每层各有一份索引，每天自动归纳一次；读写走七个 memory_* 工具，另有设置页可按工作空间调参数。", "archive", 0, "memory"),
        E("dsh-memory-triage", "dsh-memory-triage", "DeepSeek Harness 记忆分诊插件：每轮对话结束自动判断条目保留或归档，把项目条目迁入 project 桶、全局条目留在总体记忆，合并近义重复条目，规则拿不准时用 LLM 兜底；自动动作只做可恢复的归档，永不直接删除。", "archive", 0, "memory"),
        E("dsh-memory-unlocked", "dsh-memory-unlocked", "发送“大记忆恢复术”来让 AI 回想起忘记的对话。", "session", 0, "memory"),
        E("dsh-memory-vault-1", "dsh-memory-vault", "DeepSeek Harness 的 SQLite 长期记忆插件：按分类与标签增删改查、搜索、归档记忆，自动记录对话并分层压缩，带项目维度——检索默认收窄到当前工作区加全局事实。", "data", 0, "memory"),
        E("dsh-missher-brain", "dsh-missher-brain", "协调兼容的记忆与学习提供方进行有界项目召回，提供共享设置和提供方生命周期管理。", "session", 0, "memory"),
        E("dsh-missher-memory", "dsh-missher-memory", "按项目隔离的本地记忆，支持审核后检索、来源追溯、可回滚整理与通用 Cordis 服务；Harness 适配提供搜索和设置页，可选接入 Brain。", "fileops", 0, "memory"),
        E("dsh-mnemo", "dsh-mnemo", "给 DeepSeek Harness 的跨会话长期记忆：规则和坑每轮注入，其余按 IDF 加权关键词召回；事实键去重、明文 JSON、设置页可增删改。", "data", 0, "memory"),
        E("dsh-mnemosyne-memory", "dsh-mnemosyne-memory", "DSH 永久记忆插件，支持向量搜索、LLM 反思和知识页面生成。", "search", 0, "memory"),
        E("dsh-natural-dialogue", "dsh-natural-dialogue", "为 DeepSeek Harness 提供可配置人格、独立回复生成，以及支持审核和修正的可追溯记忆。", "session", 0, "memory"),
        E("dsh-nexus-memory", "dsh-nexus-memory", "基于本地 SQLite 的长期记忆：新会话自动注入项目相关记忆（噪声过滤），支持轻量规则或模型辅助提取，写入去重与反馈加权排序。Python 桥默认使用 $NEXUS_PYTHON 或 <DSH home>/dsh-runtimes/dsh-primary-runtime/dependencies/", "data", 0, "memory"),
        E("dsh-note-keeper", "dsh-note-keeper", "DSH 侧栏里的 Obsidian 兼容 Markdown 笔记：搜索、标签、反向链接、图谱、带转写的语音笔记、画布、OCR（需 tesseract）、客户端加密与 notes_* agent 工具；release tarball 与 npm 包自带预构建的 Linux x64 daemon，其他平", "pdfdoc", 0, "memory"),
        E("dsh-notes", "dsh-notes", "把笔记存成你选定根目录下按分组组织的本地 Markdown 文件，带侧栏页面，并把 AGENTS 等规则 md 作为写作上下文，另有六个 agent 工具。", "pdfdoc", 0, "memory"),
        E("dsh-obsidian-memory", "dsh-obsidian-memory", "把 agent 的长期记忆存成 Obsidian vault 里的普通 Markdown 笔记——每条记忆是一个带 YAML frontmatter 的 .md 文件，Obsidian 原生索引，可以直接读、改、链接和备份，不锁在数据库里。提供左侧栏面板（按标签筛选、按时间或重要度排序、就地编辑）、", "pdfdoc", 0, "memory"),
        E("dsh-pitfall-memory", "dsh-pitfall-memory", "面向 DeepSeek Harness 的失败记忆插件。运行中捕获工具失败，用 16 条内置规则归并成「症状 + 正确做法」的经验，附带会话/天/周三级总结，并通过 systemPrompt context 把简报注入后续会话。提供 5 个 pitfall_ 工具与 Web 设置页。", "session", 0, "memory"),
        E("dsh-plugin-3", "dsh-plugin", "PLUR 记忆在每次组装时渲染进系统提示词，而非以工具调用形式暴露，因此记忆块是被替换而不是追加，整段会话的上下文长度保持不变。全本地混合检索（BM25 + BGE，RRF 融合）、可直接编辑的纯 YAML 存储、按工作区划分 scope，并提供 /plur-memory 浏览器界面。", "data", 0, "memory"),
        E("dsh-plugin-asmemory", "dsh-plugin-asmemory", "动作-状态时序记忆：记录类型化的状态与动作，做趋势、异常与因果关联分析。", "session", 0, "memory"),
        E("dsh-plugin-memory-2", "dsh-plugin-memory", "DeepSeek Harness 的长期持久记忆：以 JSON 保存事实／偏好／实体／规则／经历等分类条目，注册为 memory_remember 与 memory_recall 两个 agent 工具；召回按关键词重叠、重要度与访问频次排序。", "data", 0, "memory"),
        E("dsh-plugin-tlmemory", "tlmemory", "跨会话、跨工程的长期记忆：turn/end 时非阻塞派发无感静默沉淀，写入本机 SQLite（FTS5 trigram 全文索引，含增删改同步触发器）供后续回合召回；记忆按项目作用域与全局树分层存储，并自带内嵌 Web 看板（插件自身起 HTTP 服务，非独立进程）用于浏览、图谱与受控删除。", "data", 0, "memory"),
        E("dsh-plugins-9", "dsh-notes-context", "为 DeepSeek Harness 提供笔记式上下文压缩：用模型维护的持久笔记本取代 LLM 摘要式压缩，并保留可恢复的原始历史，窗口边界本身不产生模型调用。", "archive", 0, "memory"),
        E("dsh-powercontext", "dsh-powercontext", "DeepSeek Harness 的 PowerContext 常驻插件：模型每步前自动召回有界上下文，19 个 pc_* 工具覆盖记忆、工作移交、经验与技能，附带 Windows Server 看门狗实现常驻自启与崩溃自动拉起。", "session", 0, "memory"),
        E("dsh-premise-guard", "dsh-premise-guard", "压缩后前提漂移守卫：摘要丢失关键字面锚点时注入一次性提醒。", "archive", 0, "memory"),
        E("dsh-project", "dsh-project", "把多个文件夹与会话收纳为「项目」，共享 PROJECT.md 记忆与 AGENTS.md 指令并注入每个会话，附带项目树侧边栏。", "fileops", 0, "memory"),
        E("dsh-puppet-memory", "dsh-puppet-memory", "面向 DeepSeek Harness 的跨会话记忆：三层存储（行为笔记／深层细节／会话阵列）打底，加一张每步注入的 600 字核心卡、工作·陪伴·学习三线状态、多人多群记录与可见性分区、会话级记忆片段屏蔽与删除、可路由到独立模型的摘要与事实候选，以及备份与自检工具；数据全部是家目录下的纯文本文件，", "fileops", 0, "memory"),
        E("dsh-qzone-echo", "dsh-qzone-echo", "把你本人发过的 QQ 空间说说收进本地库，自动分成「思考/感想」「梦记」「介绍/推荐」三栏，三栏都能人工纠正 —— 逐条改，一条只动它自己那一栏，撤销也不会连累另外两栏。配一个可用口令锁住的私人网页查看器，会把被上游接口截到前 500 字左右的长说明确补回全文，按年月统计字数，并把配图备份到本地离线", "text", 0, "memory"),
        E("dsh-reflect", "dsh-reflect", "把对模型的纠正变成永久规则：remember: 显式触发与自动检测的纠正经确认条确认后写入 AGENTS.md 的标记段（全局或项目作用域，可编辑、可跳过），当前会话立即生效，新会话由 dsh 原生指令加载器读取；规则去重、版本守卫写入、疑似密钥拒绝落盘。", "text", 0, "memory"),
        E("dsh-relationship", "dsh-relationship", "本地关系记忆工作台，一切 AI 写入先过确认闸门：AI 提取的记忆与新建的联系人都先进入待确认队列，由用户在界面拍板收录；素材逐字存档，AI 提取时逐条校验原话摘录溯源；已确认记忆聚合为联系人时间线、礼赠时机与往来视图。内置「关系记忆」agent preset 支持对话录入；默认 JSON 存储、可", "data", 0, "memory"),
        E("dsh-rules", "dsh-rules", "DSH 统一准则/规则层：把 agent 的所有准则收进一份本地规则库，区分默认（常驻）与局部（按任务域）适用面，把生效规则同步进 AGENTS.md 托管段；并提供语义路由、分类树、管理页/右栏面板、面板内助手（读取规则、校准待复核、个性化分类、按归属汇报问题台账），以及规则副本（右键移动/复制、", "ai", 0, "memory"),
        E("dsh-self-evolution", "dsh-self-evolution", "有界自管的长期记忆（Hermes 式 MEMORY.md / USER.md，硬字符上限 + 写入前安全扫描）；每轮结束后自动复盘，用大白话写笔记、或把新知识合并进已有技能而不堆出雷同技能；curator 找出会被加载器静默丢弃的技能并外科式修复；跨会话搜索历史消息；输入框上方的学习卡片只在有新闻时", "search", 0, "memory"),
        E("dsh-self-memory", "dsh-self-memory", "DSH 四层记忆插件（记忆设计移植自 NoMindSama/qq-dsh-bridge，MIT，去掉了 QQ 通道）：只增不改的原文库、带权重衰减与单向归档的长期事实库、智能体自己写的自我认知、原文库上的中文 bigram 检索，以及增量 AES-256-GCM 加密同步到只存密文的私有 git 仓", "git", 0, "memory"),
        E("dsh-selfmem", "dsh-selfmem", "给会断片的模型三本账，各解决一件事：自我笔记（我变成什么样了——上限 40 条，挤掉最旧的一条之前必须留一句折痕，记下删的是哪条、为什么）、判断账本（记下自己做的判断和验证方法，到期回头核，错了进错册，防止一直觉得自己是对的）、交接条（这一轮停在哪、下一轮先看什么——是接力棒不是记忆）。三个工具各带", "session", 0, "memory"),
        E("dsh-session-notebook", "dsh-session-notebook", "从 DSH 会话里记笔记：可收藏整条回复或选中片段，划线会持久重绘回原文位置，可为其补写可编辑的 Markdown 笔记、打标签，按工作区或会话筛选，并导出 Markdown 或完整 JSON 备份；数据以本机 JSON 文件存储。", "pdfdoc", 0, "memory"),
        E("dsh-shared-memory", "dsh-shared-memory", "所有会话共用一份 Markdown 记忆，含人设、要求、指正、教训、方法、请求、会话、方法库与导入文档九个分区；双硬盘镜像、历史快照、跨进程写锁，条目按命中频率与重复强调在主文件与可检索归档之间双向流动，检索为关键词共现加 BM25 排序。另含自有技能库（SKILL.md 操作手册，可选带护栏的 r", "pdfdoc", 0, "memory"),
        E("dsh-snail-memory", "dsh-snail-memory", "为 DeepSeek Harness 提供分层的全局与工作区记忆：Web 面板中查看、控制条目并调整记忆整理与整合设置；索引常驻上下文、详情按需加载，每个对话手动选择要加载的记忆层。", "fileops", 0, "memory"),
        E("dsh-supermemory", "dsh-supermemory", "基于 Supermemory 的跨会话长期记忆：在 pre-step 按需执行语义与历史对话片段召回（同会话去重、首轮附带静态画像），回合结束后防抖上传脱敏对话并由后台模型提炼增删改事实（字面二元组与向量语义双层查重），提供 memory_search、memory_save、memory_forg", "text", 0, "memory"),
        E("dsh-trilium", "dsh-trilium", "通过 ETAPI 把 Trilium 笔记库接入 agent，提供 20 个工具：记忆读写（remember/recall + 自动注入索引）、笔记管理（CRUD/克隆/属性/修订）、全文搜索、周报工作流、附件、日历笔记、备份导入，独立设置卡片，配置 0600 落盘。", "time", 0, "memory"),
        E("dsh-user-mirror", "dsh-mirror", "让模型主动记下你的判断依据（原则/红线/工作方式），跨会话复用 —— 有容量上限、会遗忘、每条都说得出为什么记。0.7.0 重构为画像式速写，带证据追溯与红线硬约束，告别冷冰冰的数据库列表。", "session", 0, "memory"),
        E("dsh-whale-journal", "dsh-whale-journal", "给陪伴型 agent 的日记 / 叙事记忆：按天、按 scope 写「自己视角」的话，每条尽量能回指到当天的消息；附带只读日记页（简笔画 / 照片跟着句子走）与接地审计。", "image", 0, "memory"),
        E("dsh-wife-memory", "dsh-wife-memory", "只记关于主人的长期记忆：每轮抽出作息、喜好、雷点、情绪触发、在忙什么、约定与说话方式，把很短的摘要注入每轮提示；会按点主动开口或在回复里顺口关心一句，从短句里学作息，记忆攒多了自动整合——带有插件来源与对外发送动作识别、未核实记忆降权与一键撤回。", "session", 0, "memory"),
        E("dsh-worklog", "dsh-worklog", "给 agent 的跨会话开发日志：worklog_add 往当天文件追加一行（可带 tag），worklog_list 按天回读或列出有记录的日期。条目是 $DSH_HOME/worklog 下的纯 JSON，下一次会话能接上上一次停在哪。", "data", 0, "memory"),
        E("dsh-workspace-memory", "dsh-workspace-memory", "为 DSH 提供工作区隔离的持久化记忆，让每个工作区拥有可检索、可审计、可纠错和可删除的独立记忆，并支持受控的全局记忆。", "session", 0, "memory"),
        E("dsh-xia-plugins", "packages/gameassist-memory", "单文件持久陪伴记忆：把兴趣、偏好、任务与过往作品摘要注入系统提示词，提供读取与更新工具。", "fileops", 0, "memory"),
