        E("dsh-skill-manager-3", "dsh-skill-manager", "dsh 技能管理页：列出全部技能，按全局、本项目、本会话三级开关，取消勾选的技能不进模型目录，并可按自建分类整理。", "fileops", 0, "skill"),
        E("dsh-skill-map", "dsh-skill-map", "在右侧栏用一个或多个「工作区」给已加载的 skill 分类：每个工作区有自己的分类表和每个 skill 的归属，分类可就地新建、改名、排序、删除，skill 可拖动或用选择器改归位；首次使用可以让这个 profile 的模型从零分一版，也可以先自己建分类再让模型按分类分配。点击行复制 /skill-", "fileops", 0, "skill"),
        E("dsh-skill-mimo", "dsh-skill-mimo", "实时技能提供器：把小米 MiMo（MiMo Desktop / MiMoCode）的全部 skill 读进 DSH 会话技能目录——engine-config 下的引擎内置技能（该目录缺失时从 app.asar 解包）、MiMoCode 全局与项目根、extensions.json 里扩展贡献的技能", "data", 0, "skill"),
        E("dsh-skill-recursive", "dsh-skill-recursive", "把标准 DSH 技能根目录下嵌套子文件夹中的 SKILL.md 技能包加入目录，并可在设置中调整深度、监听和额外根目录。", "fileops", 0, "skill"),
        E("dsh-skill-router", "dsh-skill-router", "用关键词匹配替代完整技能目录，支持逐个技能的启停开关与系统提示词段落开关。被停用的技能会被 skill 工具拒绝，其斜杠调用也会在请求前被拦截。", "fileops", 0, "skill"),
        E("dsh-skill-router-1", "dsh-skill-router", "DeepSeek Harness 的 skill 路由插件：用本地模型为 skill 和用户任务生成向量，按基于分差的规则保留明确相关的 skill，并自动把它们的完整正文注入提示词。", "ai", 0, "skill"),
        E("dsh-skill-slash-fuzzy", "dsh-skill-slash-fuzzy", "用唯一 kebab 片段解析斜杠 skill，例如 /oneshot 可加载 game-package-oneshot。", "misc", 0, "skill"),
        E("dsh-skill-status", "dsh-skill-status", "在会话标题栏显示已确认加载的技能数量，点击「技能」打开右侧面板，查看完整正文是否仍在当前主助手上下文中，以及各次加载的正文版本与来源。", "session", 0, "skill"),
        E("dsh-skill-studio", "dsh-skill-studio-codex", "带左侧栏页面的 Codex 兼容技能工作室：浏览、创建、编辑、启停并调用 SKILL.md 技能；把 ~/.codex/skills 与项目 .codex/skills 接入 DSH，并支持在对话中用 $技能名 调用。", "session", 0, "skill"),
        E("dsh-skill-suite", "dsh-skill-suite", "Agent技能：在管理页里浏览、开关、编辑技能，也能让 Agent 自己写新技能。", "ai", 0, "skill"),
        E("dsh-skill-tag", "dsh-skill-manager-tags", "按标签筛选技能：给 DSH 技能打标签，再用布尔表达式为每个工作区或对话选出下发给模型的子集（例如 `pdf + docx` 或 `aegis * plugin`）。命中以外的技能会被 deny-shadow 真正从模型目录里移走，而不只是在设置页隐藏；表达式之外的技能可手动添加或强制禁用，另附带", "pdfdoc", 0, "skill"),
        E("dsh-skill-toggles", "dsh-skill-toggles", "按分组开关 DSH 暴露的技能：生效集合是所有启用中分组的并集；含成员由当前目录判定的自带技能分组、输入框上的面板，以及给智能体的 skill_toggles_* 工具。", "fileops", 0, "skill"),
        E("dsh-skill-triage", "dsh-skill-triage", "触发词命中后先检索本机已安装的 skill，要求对每个候选登记使用或弃用的理由，并拦住其它工具直到选定的 skill 全部加载。", "misc", 0, "skill"),
        E("dsh-skill-zemingxingxiao-brand-diagnosis", "zemingxingxiao-brand-diagnosis", "注册择命行效五行品牌诊断技能及五个伴随参考技能（理论、诊断手册、二百四十案案例库、可视化模板、术语表），带提示词路由与强制 HTML 报告模板、13 张理论配图。", "ai", 0, "skill"),
        E("dsh-skills", "dsh-skills", "技能提供者：将整个 @dennisrongo/skills 目录作为一个 npm 依赖安装，无需克隆仓库或链接目录即可完成技能的安装与更新。", "git", 0, "skill"),
        E("dsh-skills-hub-1", "dsh-skills-hub", "显示每个已安装 skill 在模型上下文中占多少，并能在不删除文件的前提下把它从目录里摘掉。按 DSH 的渲染规则给出模型实际看到的那一行（介绍归一化并按目录上限截断）、正文体积与 token 估算；可逐字预览模型将收到的目录消息，与会话里已发布的那份比对，并列出来自磁盘却进不了目录的 skill（", "sysinfo", 0, "skill"),
        E("dsh-skills-input", "dsh-skills-input", "DSH composer 界面：搜索当前会话可手动调用的 Skill，并将宿主可识别的斜杠命令写入草稿，不自动发送。", "search", 0, "skill"),
        E("dsh-skills-symlink", "dsh-skills-symlink", "按项目分配技能根目录，支持多级分类发现。", "fileops", 0, "skill"),
        E("dsh-spring-admin-kit", "dsh-spring-admin-kit", "Spring Boot 后台开发套件：EasyExcel 批量导入导出代码生成与 Thymeleaf + LayUI 模板安全守卫。", "misc", 0, "skill"),
        E("dsh-starter-zh", "dsh-starter-zh", "DSH 新手入门包：欢迎语、从 0 到 1 学习路径、按场景推荐插件与新手自查清单，联动 dsh-handbook-zh 中文教程仓库。", "git", 0, "skill"),
        E("dsh-superpowers", "dsh-superpowers", "向 dsh 提供 obra/superpowers 技能目录，并将其 using-superpowers 引导作为持久、压缩安全的系统提示区块注入。", "archive", 0, "skill"),
        E("dsh-superpowers-1", "dsh-superpowers", "把 Superpowers 作为 Agent 预设运行，并在设置表里为每个技能单独指定子代理模型，测试、系统调试与收尾验证不再全部沿用父会话的模型。", "net", 0, "skill"),
        E("dsh-superpowers-2", "dsh_superpowers", "把 obra/superpowers 的 14 个技能按已记录的上游 tag（v6.3.0）打包进 dsh，并可用带差异报告的命令重新同步；任务匹配时自动触发。", "archive", 0, "skill"),
        E("dsh-teamai-panel", "dsh-teamai-panel", "DeepSeek Harness 侧边栏面板，用于团队技能、MCP 和提示词管理与同步。", "ai", 0, "skill"),
        E("dsh-token-handoff", "dsh-token-handoff", "DeepSeek Harness 的会话上下文交接——不再每会话重读/重建上下文。单个 skill(layer ①),让下一会话暖启动。", "session", 0, "skill"),
        E("dsh-token-headroom", "dsh-token-headroom", "DeepSeek Harness 的上下文压缩/headroom——压缩在线上下文让 prompt 保持小，又不丢关键状态(layer 3)。", "archive", 0, "skill"),
        E("dsh-token-rtk", "dsh-token-rtk", "DeepSeek Harness 的输入冗余剪枝——送进模型前剪掉重复/冗余 token(layer ②)。", "ai", 0, "skill"),
        E("dsh-useof-skill-panel", "dsh-useof-skill-panel", "显示每轮对话实际调用了哪些技能，并可在应用内安装、更新与删除技能。", "session", 0, "skill"),
        E("dsh-vehicle-dynamics", "dsh-vehicle-dynamics", "把 Gillespie《车辆动力学基础》整本书做成工程检查单：十章 164 张卡，单一入口两级路由。每张卡给出所需输入、执行步骤、方法失效的边界条件，以及回查用的页码——原理讲解仍在原书里。不复制原书任何连续段落；卡内记录了 44 条原文缺陷（错印、OCR 损坏、前后矛盾），每条带审查清单编号。本包", "image", 0, "skill"),
        E("dsh-verify-cheap", "dsh-verify-cheap", "携带一份技能：用仍然能给出确定结论的最便宜手段验证改动——L0–L3 成本阶梯（静态检查到单个测试套件）、用条件轮询加超时替代固定延时、断言必须能失败、耗时必须实测而不是凭印象。包里还带着这份技能调用的两个零依赖 Node 工具：wait-until.mjs（轮询命令 / 文件 / 端口直到就绪）与", "net", 0, "skill"),
        E("dsh-vivado", "dsh-vivado-preset", "为 dsh 增加一个 Vivado 会话预设：FPGA 工程纪律 persona（全局串行、纯 ASCII 路径、结论必须带证据、长构建脱离进程树），并从包内挂载 8 个 AMD/FPGA 技能；安装预设本身不要求装 Vivado 或 vivado-mcp。", "sysinfo", 0, "skill"),
        E("dsh-youtube-study-notes", "dsh-youtube-study-notes", "把 YouTube 链接变成学习笔记：先取视频自带字幕，可选让视觉模型读画面，再问你自己的笔记，最后合并成一份文档。需 PATH 上有 python3、ffmpeg 与 yt-dlp（缺失时技能会停下来并给出安装提示）。", "media", 0, "skill"),
        E("harness-review", "dsh-harness-review", "技能：回看最近两周的编程助手会话记录（仅 Claude Code 与 Codex，不支持 DSH 自身会话），报告哪些技能、钩子和规则有效、需要关注或从未使用。需要 Python 3。", "session", 0, "skill"),
        E("law-thesis-review", "law-thesis-review", "DeepSeek Harness 技能插件：批改法学论文（国际经济法等）。读取学生 Word 论文，对照打包的常见问题清单逐项检查；可直接确定的错漏以 Word 修订模式修改，对部分整体问题、缺依据/缺澄清之处写 Word 批注；并输出简短、客观、以宏观点评为主的总体评语与待修改清单。", "archive", 0, "skill"),
        E("lelogin-skill", "lelogin-skill", "提供 LeLogin 技能，用于凭据注入和已登录业务系统调用，避免向模型暴露明文秘密。", "ai", 0, "skill"),
        E("lit-report-ppt", "lit-report-ppt", "把一篇期刊论文做成中文组会文献汇报 PPT（南阳师范学院物理模板），并附一份配套的 Word 讲稿。需本机 Python 3 及 python-pptx、python-docx、Pillow、pymupdf（pypdf 兜底）依赖，可用 pip install -r requirements.txt", "pdfdoc", 0, "skill"),
        E("local-solution-first", "local-solution-first", "给 DeepSeek Harness 的「先找本地现成方案、再用证据验证」技能：动手实现、移植、选依赖、排查工具之前，先在项目与本机分层检索已有方案，用可核对的证据判断能否复用，必要条件或风险不满足时明确拒绝复用，并写清哪些结论无法核实。以 DSH 组合包（dsh.bundle）注册到 ctx.sk", "misc", 0, "skill"),
        E("mattpocock-skills-dsh-2", "mattpocock-skills-dsh", "把 mattpocock/skills v1.3.2 的 27 个精选技能（TDD、代码审查、grilling、规格与工单流程、领域建模等）打包为 DSH 插件；技能正文与上游逐字节一致，并保留上游调用策略；附带上游同步脚本与离线契约校验。", "git", 0, "skill"),
        E("paper-format-check", "paper-format-check", "论文 / 实验报告格式体检：对照 JSON 规则预设核验正文字号、首行缩进、行距、中文字体、页眉学号姓名、页边距、图题表题编号，逐条给出段落定位与具体修法。只读、零依赖（纯 Python 标准库），实际执行的检查项为 0 时拒绝判通过。需要 PATH 中有 Python 3.8 或更高版本。", "data", 0, "skill"),
        E("plan-guardian-skill", "plan-guardian-skill", "每个请求都必须走完 7 步计划,每步都有可判定的验收标准,执行交给 worker 子代理,完成情况由无记忆的独立 verifier 子代理带证据判定 PASS / FAIL。", "net", 0, "skill"),
        E("project-cross-migration", "project-cross-migration", "为 DSH 注册 project-cross-migration 技能：对话/记忆/人格/工具/环境五层迁移，含入口校验、JSONL 完整性检查与可读还原。三平台 1418 条消息真实迁移实测；纯 Python 标准库，MIT。", "data", 0, "skill"),
        E("publish-size-check", "publish-size-check", "发布尺寸检查技能：发布前对照目标平台的几何规格核验交付物——像素尺寸、宽高比、dpi、体积、格式、物理印刷宽度、色彩模式。只查几何参数，不做内容合规审查（二维码、文字占比、版权、违规内容均不在范围内）。纯 Python 标准库实现，不装任何第三方包，原件全程只读。需 Python 3.8+。覆盖 1", "codec", 0, "skill"),
        E("react-monitor-agent", "react-monitor-agent", "安装壳技能：安装、跑起并排障 React-Monitor-Agent 人机协作操作板——agent 把工作过程写成由录屏、截图、diff、文本节点组成的结构化回放时间线，人在方案/阶段/风险/完工四类检查点上拍板，决策改变时间线走向，被否定/改向的旧分支灰掉保留以供审计。技能引导克隆主仓，启动零依赖", "git", 0, "skill"),
        E("readable-diagrams", "readable-diagrams", "让读者一眼看懂的图表：一份 JSON 规格出九种图，标题、阅读动线、图例、对比度与连线都经机器校验。渲染与校验脚本需要 Python 3.9+。", "data", 0, "skill"),
        E("scenes-skill-creator", "scenes-skill-creator", "Web 界面上的技能创建面板：拉取官方 creator 技能，把需求交给华为云 / 通用 / REST API 三个 creator 之一执行创建，随后按 10 分制评测产物，未达 8.5 分就把逐项扣分交回 creator 修改直到通过。", "misc", 0, "skill"),
        E("search-school-sci-skill", "search-school-sci-skill", "统计某一所大学某个学院（二级单位）的科研产出：按作者单位串匹配学院的各种英文写法（并检测其他高校的同名院系），对只写到校名一级的论文用教师作者 ID 反查补全，再按期刊层级分类（中科院分区含 Top 标记、JCR 分区、CCF、经知网导出合并的中文核心），区分教师与学生一作，输出含看板页、可筛选论文", "text", 0, "skill"),
        E("shared-handoff-dsh", "dsh-shared-handoff", "共享交接套件的 dsh 版:handoff 与 task-id-bootstrap 技能 + host 侧自动化——基线状态注入、每轮快照与 Auto Log 轨迹、task=<id> 路由、续接关键词重注入、达阈值报警的压缩守护、子代理只读保护;与 Codex、Claude、pi 版写同一份 .a", "archive", 0, "skill"),
        E("simple-plan", "simple-plan", "给每个任务加上严格验证:把任务拆成 2-7 步,用 worker 子代理执行,每个交付物都由无记忆的独立 verifier 子代理验证,最多修 3 轮后如实汇报。", "net", 0, "skill"),
        E("superpower-dsh", "SuperPower-dsh", "为 DeepSeek Harness 提供 15 个 Superpowers 技能，覆盖测试驱动开发、调试、规划与代码评审。", "misc", 0, "skill"),
        E("superpowers-for-dsh", "superpowers-for-dsh", "将 obra/superpowers 的 14 个工程技能打包为 DeepSeek Harness bundle，附原生 Agent 预设、自动会话引导和 Windows 沙箱兼容。", "archive", 0, "skill"),
        E("taptap-maker-builder", "taptap-maker-builder", "把一份游戏策划案在 TapTap 制造（UrhoX 引擎 + Lua）上落成可玩、可发布的项目：先用浏览器工作区还是本地 MCP、拆解策划案五要素、写最小可玩的首轮需求、按官方顺序迭代、核对预览与发布物料，并守住积分、凭证与不可逆动作的红线。含 8 篇参考（产品、积分、主题与素材、排行榜、需求拆解、", "misc", 0, "skill"),
        E("team-skill-hub", "internal-skill-workshop-plugin", "团队 Skill 中心：连接 Skill Base，浏览团队共享的公开或私有技能，并一键安装到 DSH Web。", "misc", 0, "skill"),
        E("voicetranser", "VoiceTranser", "macOS 本地按住说话语音输入：按住全局热键说话、松开即转写粘贴到光标处。纯本地 STT（默认 Qwen3-ASR 0.6B 4bit 走 MLX/Metal，SenseVoice / mlx-whisper 双 fallback），零外部 API，launchd 自愈常驻 + 8 项自检。内置技", "media", 0, "skill"),
        E("xiaobai-reasearch", "Xiaobai-Reasearch", "中文行业与技术调研报告生成技能，内置离线 Word (.docx) 编译流水线（build_docx.py）。规范九章总分总结构、2.1 节白话演进时间线、五维技术瓶颈判据与自研成本/外部采购成对博弈论证，提供双主线启发式自检工具（check_research_report_threads）与带原生", "pdfdoc", 0, "skill"),
        E("dsh-auto-sight", "dsh-auto-vision", "主模型不能识别图片时，自动改用同一 API 下可识别图片的模型读取图片，再把描述反馈给主模型。", "image", 0, "vision"),
        E("dsh-auto-vision", "dsh-auto-vision", "按需自动把 DeepSeek 路由切到视觉模型：flash 主会话直接切（A），pro 保持深推理并交给视觉子代理读图（B），子代理恒切，含失败回退，无需手动切模型。", "net", 0, "vision"),
        E("dsh-autovision", "dsh-autovision", "纯文本 dsh 模型的识图插件：粘贴图片自动由你配置的多模态模型转成文字——透明孪生路由、模型可自主调用识图工具、无内置密钥与中转。", "image", 0, "vision"),
        E("dsh-cloudflare-media", "dsh-cloudflare-media", "把 Cloudflare Workers AI 的多媒体模型接进 dsh：生图、TTS、语音转写都有；每个模型标注价格档位，带原生设置页，复用已有的 Cloudflare 账号，输出文件带模型名。", "media", 0, "vision"),
        E("dsh-design-1", "dsh-design", "启动已发布的本地 BeatDesign 0.2.5 工作台，接入项目、画布、素材和时间线的 30 个 MCP 工具，附带共享项目与远程生成确认流程。需 Node.js 22.12+ 且 3020 端口空闲；抽帧与时间线渲染另需 PATH 上的 ffmpeg/ffprobe（浏览器导出不需要）。", "media", 0, "vision"),
        E("dsh-easyvision", "dsh-easyvision", "让纯文本模型拥有视觉：describe_image 工具调用 dsh 模型列表中的视觉模型描述图片，走 harness 自身的 LLM 运行时。", "image", 0, "vision"),
        E("dsh-free-image", "dsh-free-image", "无需 API 密钥的图片生成，含两个工具：generate_image（无需密钥、串行调用、有限次限流重试）与 list_image_models。", "image", 0, "vision"),
        E("dsh-image-compare", "dsh-image-compare", "在右栏新增一个面板，用来并排对比用户自己从工作区挑选的一组图片——每页 1/2/3/4/6 张、每张独立缩放与平移、可把某一张的缩放与显示位置同步到整组、缩略图可拖动排序。图片由浏览器直接加载，不进入模型。", "image", 0, "vision"),
        E("dsh-image-conatiner", "dsh-image-conatiner", "以对话内画廊和灯箱展示生成的图片。", "image", 0, "vision"),
        E("dsh-image-designer", "dsh-image-designer", "神火设计师：连接神火 AI 完成图片设计，支持个人账号 OAuth、素材上传、需求匹配、设计提案、积分报价确认与作品下载。", "image", 0, "vision"),
        E("dsh-image-editor", "dsh-image-editor", "神火图层编辑器：通过神火 MCP 上传并分离图片，确认积分后生成可编辑图层，在默认浏览器编辑，按需导出并下载 PSD。", "image", 0, "vision"),
        E("dsh-image-gen-2", "dsh-image-gen", "带提示词自动增强、可切换多个 API 配置，并在 Turn 尾展示不被折叠的图片卡片的生图工具。需自行配置图像 API 地址与密钥，插件不内置。", "image", 0, "vision"),
        E("dsh-image-generation", "tool-image-generation", "面向模型的图像生成工具，提供可配置通道和标准化图像参数。", "image", 0, "vision"),
        E("dsh-image-generation-1", "dsh-image-generation", "在设置中配置多个生图供应商，对话通过 image_generate 调用当前选中的模型；图片保存到工作区 generate/image，并在对话中内联显示。", "image", 0, "vision"),
        E("dsh-image-guard", "dsh-image-guard", "发送前把请求中的历史图片裁剪至保留张数，并从上游 400 错误解析单次图片上限、按更少张数降级重试，保证含图会话不被图片数量限制打断。", "image", 0, "vision"),
        E("dsh-image-insight", "dsh-image-insight", "结构化图像识别：本地 sharp 感知 + 云端视觉模型，一次调用拿到描述、带坐标的 OCR、 目标定位与细粒度属性；图片指纹缓存让重复图片毫秒返回且不消耗模型额度。", "image", 0, "vision"),
        E("dsh-image-router", "dsh-image-router", "在准入前把提示词里的图片换成视觉模型的文字分析，因此任何模型（包括纯文本模型）都能读图且会话不切换模型；另提供 describe_image 工具处理图片路径。", "image", 0, "vision"),
        E("dsh-image-tiler", "dsh-image-tiler", "让超大图片以可读分辨率进入模型视野，而不是被压成一张缩图：准入前按附件存储允许的上限把大图切成多张切片（8000x8000 的截图会变成 20 张 2000x1600），小字得以保留。以替换本地附件存储的方式实现，不新增任何配置项。", "image", 0, "vision"),
        E("dsh-koboldcpp-hands", "dsh-koboldcpp-hands", "给在线模型装上本地双手：koboldcpp_run 与 koboldcpp_vision 工具把重复的文本与视觉（OCR、图像分析、对比）劳动交给本地 KoboldCpp（llama.cpp）服务器，并按需拉起与管理服务器生命周期。", "image", 0, "vision"),
        E("dsh-longshot", "dsh-longshot", "超长截图在发送前自动切成 DSH 可接受的切片，而不是被直接拒收：纵向切片带重叠，不会把一行字劈成两半；纯 JS 编解码，无原生依赖，且只是包住现有附件服务、不顶替它。", "image", 0, "vision"),
        E("dsh-look", "dsh-look", "macOS 场景感知探针：拉模型零轮询的 look 工具，读取最前非自身窗口（应用信息、AX 标题/选中文本、按需本地 OCR），支持召唤热键按下瞬间抓取快照注入对话。", "image", 0, "vision"),
        E("dsh-maclens", "dsh-maclens", "苹果设备端 Vision 工具：本地 OCR（含中文）、图像分类、人脸检测、文档版面分析与综合描述，100% 离线、无需 API key，支持长截图切片。", "image", 0, "vision"),
        E("dsh-mask-pixel-lock", "dsh-mask-pixel-lock", "证明一次局部改图没有动蒙版外的像素。输入原图、生成图和蒙版三张 PNG，输出可 grep 的 `MASK_PIXEL_LOCK=PASS|FAIL|EMPTY` 结论、差异热力图、逐通道统计、差异包围盒与最大差异像素，并生成自包含 HTML 报告和 `report.json`；后者包含文件 SHA-", "image", 0, "vision"),
        E("dsh-media", "dsh-media", "提供图片视频模型发现、接口检查、价格预览、确认后生成及原任务续查，通过 BeatAPI 执行。", "image", 0, "vision"),
        E("dsh-model-vision", "dsh-model-vision", "补上 DSH「获取可用模型」漏记的视觉能力，让能看图的模型不再被当成纯文本，并在模型名后标出「可看图」。", "ai", 0, "vision"),
        E("dsh-ocr", "dsh-ocr", "为 DeepSeek Harness 注册两个工具：`doc_ocr` 把扫描件 PDF 与图片转成结构化文本（逐页文本、带资产负债表平衡勾稽的财务报表行、合同条款命中），可用本机 RapidOCR 或智谱 GLM-OCR 云端引擎；`doc_preprocess` 用 7 阶段管线把一批原始文件整", "pdfdoc", 0, "vision"),
        E("dsh-ocr-free", "dsh-ocr-free", "在 macOS 上使用 Apple Vision 的本地 OCR：从截图、照片和扫描件中读取文字，无需安装、无需联网、无需 API 密钥。", "image", 0, "vision"),
        E("dsh-omni-modal", "dsh-omni-modal", "为 DeepSeek Harness 增加「全模态设置」分区：可把生图 / 生视频指向任意 OpenAI 兼容端点，多套配置档案可随时切换，图片与视频各自独立的接口地址、API Key、模型、路径与尺寸，支持自由填写额外请求参数、不消耗额度的连通性测试，并注册 generate_image / ge", "image", 0, "vision"),
        E("dsh-omni-vision", "dsh-omni-vision", "为纯文本模型装上本地眼睛：eyes_render 在 Web 界面画布上绘制文字/图形/Mermaid，eyes_paste 接收用户粘贴的图片，eyes_ocr 用 Windows 自带 OCR 离线读文字，eyes_analyze 把像素解析成结构化数据，全程无需视觉模型。", "image", 0, "vision"),
        E("dsh-plugin-image-input", "dsh-plugin-image-input", "图片转文字输入插件：粘贴/拖拽图片自动转为结构化文字描述发送，给纯文本 LLM 提供图片输入接管（OpenAI 兼容视觉 API）。", "image", 0, "vision"),
        E("dsh-quicksight", "dsh-quicksight", "纯文本模型双层识图：优先本地快速 OCR（RapidOCR，离线），不足时回落视觉模型（modlens）。", "image", 0, "vision"),
        E("dsh-screenshot-tool", "dsh-screenshot-tool", "在输入框加相机按钮（预览、下载、复制截图），并提供一个截图工具，把 Windows 桌面截成 PNG 交给模型读取。", "image", 0, "vision"),
        E("dsh-see-now", "dsh-see-now", "让只有文字的智能体「看」实时屏幕或摄像头：每帧按画面变化量打分，只把真正变了的帧拼成一张带编号、带音轨条的宫格图——看视频、看演示、看游戏都行，token 只花在变了的地方。", "media", 0, "vision"),
        E("dsh-sticker-dict", "dsh-sticker-dict", "维护一本按内容哈希索引的本地表情包字典，看过的图直接复用描述而不再重复识图；同时把 GIF 均匀抽帧拼成一张联系表，让视觉模型看清整段动作。", "image", 0, "vision"),
        E("dsh-subagent-vision", "dsh-subagent-vision", "让纯文本 DeepSeek 代理在同一会话内读图：委派给视觉子代理，发送时自动把图片转为文件路径。", "image", 0, "vision"),
        E("dsh-unsloth-hands", "dsh-unsloth-hands", "把重复的文本与视觉（OCR、图像分析、对比）劳动交给本地运行的 Unsloth Desktop（Unsloth Studio）服务器：unsloth_run 与 unsloth_vision 两个工具，纯 HTTP 客户端，不拉起也不持有任何进程。", "image", 0, "vision"),
        E("dsh-video-android", "dsh-video-android", "安卓上的 DSH 视频工作台：分镜编辑、多供应商图像/视频生成与自动切换、FFmpeg 合成 MP4、提示词优化、手机窄屏工作台。", "image", 0, "vision"),
        E("dsh-video-eyes", "dsh-video-eyes", "让模型真的「看见」视频：本地 ffmpeg 按时间抽静帧、faster-whisper 转写音轨，模型逐帧读真实像素，而不是只读一段文字摘要。全程本地、不上传画面；音轨没有语音时如实报告而不是硬编。仅限 Windows；需已装 Python 3.10+ 与 ffmpeg，首次运行 video_eye", "media", 0, "vision"),
        E("dsh-video-eyes-1", "dsh-video-eyes", "让纯文本模型看懂视频：需本机装好 ffmpeg；按 0.1–10 秒的可调间隔抽帧拼成总览图，每格烧录该帧的真实时间码；提取音轨后上传到听脑（需配置 ITINGNAO_API_KEY）转写成带时间戳的台词；并自行调用宿主里的视觉模型逐页描述画面，因此不依赖任何其他视觉插件。输入框上方有抽帧间隔滑块，", "media", 0, "vision"),
        E("dsh-video-frames", "dsh-video-frames", "给纯文本 agent 补上视频理解：抽帧并返回带时间码的帧文件、只在场景切换时采样、导出 GIF 片段、探测元数据、并对关键帧做一次性分析。五个工具，通过 argv 数组调用本机 ffmpeg 而非拼接 shell 字符串。", "image", 0, "vision"),
        E("dsh-video-reader", "dsh-video-reader", "读取视频与音频文件的元数据、关键帧、字幕和带说话人标签的多语种转写；把实时桌面抓成帧序列或视频；首次使用时自动安装 ffmpeg / whisper.cpp / sherpa-onnx 并按文件校验 sha256，全部处理都在本机完成。自动安装工具链与桌面捕获目前仅支持 Windows x64，其他", "codec", 0, "vision"),
        E("dsh-vision-bridge", "dsh-vision-bridge", "通过已配置的 DSH Provider 或 OpenAI 兼容端点提供图片输入与识别。", "image", 0, "vision"),
        E("dsh-vision-diff", "dsh-vision-diff", "面向视觉回归的像素级截图比对。输入两张本地 PNG，第一行是可机器判定的结论（`PIXEL_CHANGED=true|false`，可以直接 grep 当断言），随后是差异比例、差异区域包围盒、最大通道差与平均绝对误差，并生成一份自包含的 HTML 对照页。可用绝对或比例坐标声明忽略区，排除时钟、光", "image", 0, "vision"),
        E("dsh-vision-guard", "dsh-vision-guard", "纯文本路由的透明图片护栏：贴图不再 400 卡死会话，附带 vision_analyze 工具（OCR/PDF/docx/pptx/视频）。", "pdfdoc", 0, "vision"),
        E("dsh-vision-plugin-1", "dsh-vision-plugin", "让纯文本模型也能看图：发图自动用视觉模型描述（默认提示词），描述不足时对话模型自动生成更具体的提示词重新解析；系统模型/自定义双模式 + GUI 可视化配置、Key 脱敏安全、针对 DSH 0.1.0-rc.6 的宿主小补丁（见仓库 README）。", "git", 0, "vision"),
        E("dsh-vision-pro-bridge", "dsh-vision-pro-bridge", "视觉桥：贴图先经 deepseek-v4-flash-vision-exp 转写为文字，再交给纯文本的 deepseek-v4-pro 回答，零第三方依赖。", "misc", 0, "vision"),
        E("dsh-vision-solution", "dsh-vision-solution", "为 DSH 纯文本模型补充视觉能力：识图技能（图片理解/OCR/文档解析，竞速池→自定义通道→本地）+ 幂等宿主补丁，让图片消息能送达模型侧。", "pdfdoc", 0, "vision"),
        E("dsh-vision-unlock", "dsh-vision-unlock", "移除拦截图片请求的多模态能力门禁：改写 llm.resolveModelInfo 的返回值与适配器模型表，为未声明 input 的路由补上 image 输入能力，使其可以发送和读取图片。不改 app.asar，也不改配置树。", "image", 0, "vision"),
        E("lumina-dsh", "lumina-dsh", "驱动本机 Adobe Photoshop 处理游戏截图与照片：分层 HDR、多区域颜色/人物蒙版、SUPIR/Real-ESRGAN 超分与原生 1:1 视觉检查。需要 Windows 10/11 与 Adobe Photoshop 2025；macOS 与更早的 Photoshop 版本无法运行调", "image", 0, "vision"),
        E("opencode-eyes", "opencode-eyes", "给不具备多模态能力的模型一双眼睛:把随插件分发的 stdio MCP 服务器挂成 mcp__opencode_eyes__describe_image,把图片交给 StepFun step-3.7-flash 并返回详细描述。", "image", 0, "vision"),
        E("opencode-eyes-nvidia", "opencode-eyes-nvidia", "走 NVIDIA NIM 的视觉能力:把随插件分发的 stdio MCP 服务器挂成 mcp__opencode_eyes_nvidia__describe_image,用 7 个托管视觉模型之一(默认 MiniMax-M3)描述图片,并支持多 Key 轮换。", "image", 0, "vision"),
        E("opencode-ppocr-mcp", "opencode-ppocr-mcp", "本地 OCR,不把文件发到云端:把 PP-OCRv6 Medium stdio MCP 服务器(PaddleOCR + ONNX Runtime CPU)挂成 mcp__ppocr__ocr_image 与 mcp__ppocr__ocr_pdf,识别图片和多页 PDF。", "pdfdoc", 0, "vision"),
        E("qiaomu-cover-design-dsh", "qiaomu-cover-design-dsh", "在画布中使用模板和排版控件制作封面，并导出 PNG 图片。", "image", 0, "vision"),
        E("wechat-ocr", "wechat-ocr", "DSH 的本地微信 OCR 工具：`wechat_ocr_recognize` 针对本地图片路径返回识别文本和引擎的结构化结果。", "image", 0, "vision"),
        E("win11-oneocr", "win11-oneocr", "DSH 的本地 Windows 11 OneOCR 工具：`oneocr_recognize` 返回 OCR 文本，以及包含行/词多边形、置信度、旋转角度和手写体样式的结构化结果。", "image", 0, "vision"),
        E("deepseek-reader", "reader-workspace", "Typocket 在 DSH 中阅读、编辑和整理本机文档，并预览工作区 Markdown。", "pdfdoc", 0, "docs"),
        E("docsuite", "docsuite", "文档工坊：把设备说明书与历史报告变成技术方案、调研报告和投标文件，支持导出 Markdown / Word / HTML / PDF / PPTX。Word / PPTX 导出与文档解析需要 Python 3 及 pypdf、python-docx、python-pptx（在设置页初始化），PDF", "pdfdoc", 0, "docs"),
        E("dsh-agent-outputs-reader", "dsh-agent-outputs-reader", "agent 产出文件的浮层阅读器：Markdown 渲染、PDF 面板预览、DOCX/XLSX/PPTX 文本提取与回复末尾文件 chips，支持搜索、大纲与位置记忆。", "pdfdoc", 0, "docs"),
        E("dsh-ai-notepad", "dsh-ai-notepad", "DSH 的 AI 原生文本编辑器：多标签、编码保留、选区/全文 AI 与 Diff 审阅、Markdown 预览及 Windows 文件关联。", "pdfdoc", 0, "docs"),
        E("dsh-asd-100", "dsh-ASD-100", "强制所有回复和文档按 ASD-STE100 简化技术英语输出。命令：/asd100 on、/asd100 off、/asd100。", "misc", 0, "docs"),
        E("dsh-auto-convert", "dsh-auto-convert", "在 read、read_image 与 vision_* 打开文件之前先处理：长边超 2048 像素或体积超 8 MB 的图降采样（同一轮可降到 1280 再试一次），BMP/TIFF 转 PNG，按字节纠正标错的上传类型，并把 docx/xlsx/pptx、有文字层的 PDF、csv/tsv 与", "pdfdoc", 0, "docs"),
        E("dsh-book-deconstruct", "dsh-book-deconstruct", "Host 插件：任意会话可用 /dsh-book-deconstruct 命令与 dsh-book-deconstruct 工具，输入书名与作者后讲透全书并给出一段深度思想。", "session", 0, "docs"),
        E("dsh-cite-lens", "dsh-cite-lens", "dsh 的 PDF 阅读：在文件选项卡里选中 PDF 中的文字，就能引用到当前对话或就它提问；把模型的引用变成链接，点开 PDF 并高亮被引用的那几句话；/cite-links 让一段对话为每条论断都附上引用。", "pdfdoc", 0, "docs"),
        E("dsh-code-highlight", "dsh-code-highlight", "报告代码高亮：一个 highlight_code 工具，68 种语言、15 套主题、11 种输出（内联 HTML、Word 可插 SVG/PNG、LaTeX 等），含 codeinword.com 同款 SyntaxHighlighter 经典主题。PNG 输出需 Python 3 与 Pillow", "pdfdoc", 0, "docs"),
        E("dsh-code-nav", "symbol-links", "让聊天里行内代码中的标识符可点击：按定义、包装函数、顺序出现三级回退解析，在右侧预览打开文件并定位到对应行。", "fileops", 0, "docs"),
        E("dsh-codegraph-3", "CodeGraph", "把代码流程变成可跳转源码的 Mermaid 图和交互式 CodeWalkthrough 讲解页。", "misc", 0, "docs"),
        E("dsh-consistency-guard", "dsh-consistency-guard", "长文创作一致性守卫：扫描会话正文，发现人物年龄、等级、境界、年份等设定跨章节矛盾，点击直接跳转到冲突原文位置。", "session", 0, "docs"),
        E("dsh-context-map", "dsh-context-map", "把对话上下文分层渲染成信息架构图：目标、决策、动作、产物、风险与待确认一次成图，可导出 SVG、交互式 HTML 与 Mermaid Markdown。", "pdfdoc", 0, "docs"),
        E("dsh-copyright-kit", "dsh-copyright-kit", "把代码仓库和软件名变成软件著作权登记材料：60 页源程序鉴别材料（每页 50 行自动分页）、带截图的软件说明书、以及申请表信息推导（源程序量、语言、完成日期、功能简介）。需 Python 3 与 python-docx，截图需 Google Chrome。", "git", 0, "docs"),
        E("dsh-delivery-kit", "dsh-delivery-kit", "把代码仓库与运行中的系统变成验收材料：数据库设计、概要设计、详细设计、带截图的使用说明书，以及测试报告、上线报告、验收报告。章节按 GB/T 8567-88 组织，无法核实的字段与结论一律留空，不编造。需 Python 3 与 python-docx 生成 .docx，自动截图需 Google Ch", "git", 0, "docs"),
        E("dsh-doc-reader", "dsh-doc-reader", "把 PDF、DOCX、XLSX、PPTX 和文本文件读取为智能体工具，并用 tesseract.js 在本地对扫描版 PDF 或图片做 OCR。提供 doc_read、pdf_read、xlsx_read、doc_meta、doc_ocr 五个工具。", "pdfdoc", 0, "docs"),
        E("dsh-doc-routing-guard", "dsh-doc-routing-guard", "加入全局文档路由提示，让 PDF、图片和 Office 文件自动走正确的读取工具。", "pdfdoc", 0, "docs"),
        E("dsh-docchain", "dsh-docchain", "知识库、文档转换与知识图谱插件：文档文件名、内容与元数据检索，按 doc_id/文档名称定位并读取正文，主题查询，文档批量上传，文档转 Markdown，图搜图，文档图片转文字（流程图/架构图这类结构图自动转成 PlantUML 草图，其它图写成文字描述，并写入旁路描述 md，主 md 不动；原图改", "pdfdoc", 0, "docs"),
        E("dsh-drender-plugin", "dsh-drender-plugin", "为 DeepSeek Harness 提供 md-report/1 报告的校验与渲染工具：把 Markdown 与声明的 SQLite/CSV 数据集生成单个离线可交互 HTML 报告或仪表盘，图表默认用 AntV G2、复杂图表回退 ECharts，并提供图表/数据/SQL 与数据表/数据/SQL", "pdfdoc", 0, "docs"),
        E("dsh-excalidraw", "dsh-excalidraw", "在 DSH 里渲染 Excalidraw 架构图：可无账号导入本地 .excalidraw/.json 或内联文档，也可通过 MCP 从 Excalidraw+ 刷新（刷新需在 mcpToken 或 EXCALIDRAW_MCP_TOKEN 里配置 Excalidraw+ 的 MCP 令牌）；支持平", "data", 0, "docs"),
        E("dsh-fullwidth-punctuation", "dsh-fullwidth-punctuation", "将 AI 回答中的半角标点转换为中文全角标点，让复制的回答可直接用于公文材料。", "misc", 0, "docs"),
        E("dsh-gh-pages-artifacts", "dsh-gh-pages-artifacts", "把 Agent 生成的 HTML 页面和 Markdown 文档发布到 GitHub Pages 并返回可分享链接，提供原地更新、列出、读回和删除的工具；附带侧边栏 Artifacts 面板和内置的页面设计技能。", "pdfdoc", 0, "docs"),
        E("dsh-github-notebook", "DSH Notebook · 私人笔记管理", "保存会话、管理图文笔记、导出文件，通过自己的 GitHub 私有仓库跨设备同步。", "git", 0, "docs"),
        E("dsh-hr-plugin", "dsh-hr-plugin", "面向 DeepSeek Harness 的结构化简历编辑器；每个会话独立保存草稿，对话与侧栏共用内容，并提供 A4 预览和 PDF 导出。", "pdfdoc", 0, "docs"),
        E("dsh-humanize", "dsh-humanize", "面向人类写入内容的行文审查。write 和 edit 调用需声明 human_facing，插件在后台按分层 PROSE.md 规则审查文本并暂存批注，再按全文核对已有批注，主会话照常推进；用 /humanize、/humanize-loop 或压缩后自动合并批注，/humanize-review", "git", 0, "docs"),
        E("dsh-hxc-blog", "blog-manage", "在 DSH 面板里管理 GitHub Pages 博客：按标签分组浏览 Markdown 文章，用表单填 front matter 并在分屏编辑器里修改，再通过 GitHub REST API 把改动作为一次 commit 发布。", "git", 0, "docs"),
        E("dsh-knowledge-base-2", "dsh-knowledge-base", "本地优先的 DSH 工作区侧边栏知识库：索引项目、文档和插件，自动归类，支持搜索、文件预览和可编辑笔记；数据保存在工作区。", "fileops", 0, "docs"),
        E("dsh-kp-notes", "dsh-kp-notes", "DeepSeek Harness 知识点笔记插件：把 Markdown 笔记目录变成卡片式学习画布，目录 = 章节、文件 = 小节、正文 = 知识点；题目可遮挡答案自测，支持 KaTeX 公式、Mermaid 流程图、思维导图与面板内编辑。", "pdfdoc", 0, "docs"),
        E("dsh-large-jsonl-viewer", "large-jsonl-viewer", "使用字节索引逐条浏览 JSONL 与 NDJSON，支持物理行跳转和超长记录流式预览的只读查看器。要求 DSH >=0.2.1-rc.2。", "data", 0, "docs"),
        E("dsh-latex-guard", "dsh-latex-guard", "为 DeepSeek Harness 提供的 LaTeX 与 BibTeX 检查工具：编译检查（自动识别 xelatex/lualatex），基于 Crossref 的 BibTeX 条目去重与字段补全，以及 \\cite 键与 .bib 文件的一致性审计。", "pdfdoc", 0, "docs"),
        E("dsh-latex-look", "latex-look", "让 Agent 真正看见编译后的页面：把任意一页渲染成图片，用 SyncTeX 把页面坐标或文字锚点解析成源码 file:line（并指出某条横线是宏包画的而不是正文画的——这正是朴素定位最容易出错的地方），把这一页与上一次构建做像素对比，逐页审计本次修改新引入的空洞，并检查图表编号是否仍然顺序正确", "pdfdoc", 0, "docs"),
        E("dsh-launch-card", "dsh-launch-card", "从本地仓库真实支持的产物生成发布素材：hero 图、特性网格与中英双语文案，由 `README.md`、`package.json` 和可选截图渲染成 SVG 与 HTML。事实全部从这些文件引用——项目名、版本、license、一句话简介、特性列表、安装片段——缺失的字段直接不渲染，不补占位文案。", "git", 0, "docs"),
        E("dsh-markdown-notes", "dsh-markdown-notes", "随手记、随时读：阅读、编辑、并排预览一键切换，附大纲与三套排版主题，支持公式与 Mermaid，多级文件夹管理，自动存为本地 .md 文件。", "pdfdoc", 0, "docs"),
        E("dsh-marktext", "dsh-marktext", "基于 MarkText 内核 muya 的右侧栏所见即所得 Markdown 编辑器：打开 .md 按渲染结果编辑，保存走 ctx.fs 并带版本守卫。", "pdfdoc", 0, "docs"),
        E("dsh-mermaid-2", "dsh-mermaid", "把会话里的 mermaid 代码块直接渲染成图表，源码一键可查。", "session", 0, "docs"),
        E("dsh-notebook-studio", "dsh-notebook-studio", "把最多 30 篇上传的 PDF 文献变成提示词驱动的文献综述、关键信息提取、研究思路与研究设计，并导出带页码引用的报告（DOCX/PDF）或演示文稿（PPTX/PDF）。", "pdfdoc", 0, "docs"),
        E("dsh-notes-2", "dsh-notes", "右侧栏的笔记工作区：笔记树 + 实时预览的 Markdown 编辑器（标签 / 分屏 / 大纲 / 回收站），笔记是普通 .md 文件，索引是按工作区的薄映射，Agent 侧只用一个 `knowledge` 工具整理；`embed` 围栏把可交互网页演示嵌进笔记（沙箱 iframe，脚本可跑、断网、", "pdfdoc", 0, "docs"),
        E("dsh-openwiki-visualize", "dsh-openwiki-visualize", "在 DSH Web 右侧边栏预览工作区的 OpenWiki：识别 wiki 目录，用官方 `openwiki visualize` 阅读器在本地回环端口提供服务并嵌入自有标签页，同时对照可配置的版本下限报告 openwiki 与 DSH 版本，并向 registry 检查自身更新。", "net", 0, "docs"),
        E("dsh-overleaf-sync", "dsh-overleaf-sync", "不走 Git 桥接，而是通过 Overleaf 自身的 Socket.IO + OT 通道在本地 LaTeX 文件夹与 Overleaf 项目之间双向同步：拉取后自动 git init、推送默认 dry-run、三方 diff、后台 watch，冲突永不覆盖而是另存副本。", "git", 0, "docs"),
        E("dsh-paper-deepread", "DSH-Paper-DeepRead", "把文献精读库与 paper-deepread-html 精读技能打包成 dsh 插件：侧边栏浏览交互式报告、上传 PDF 到托管书库、由 Agent 或可选接入的站点自动精读 worker 精读、管理或重建书库；提供 paper_deepread、paper_deepread_uploads、pap", "pdfdoc", 0, "docs"),
        E("dsh-paper-translate", "dsh-paper-translate", "DSH 的整篇 PDF 文献翻译：BabelDOC（Python CLI 及其 config.toml 里的 OpenAI 兼容 API Key）需自行安装配置；输出双语对照 PDF，跑之前先给 token 成本预估，按领域跨论文复用术语表，并关掉翻译环节服务端默认开启的 thinking 推理开销", "pdfdoc", 0, "docs"),
        E("dsh-pdf-jump", "dsh-pdf-jump", "一个包装两个 PDF 工具：按页码跳页、用本地渲染的页面和缩略图整本浏览，也可用 DSH 原生预览直接打开；另带一个 /pdf 命令。", "pdfdoc", 0, "docs"),
        E("dsh-plugin-doc-review", "dsh-plugin-doc-review", "在官方预览里审阅 Word、PowerPoint、PDF 与 HTML：框选问题、就地改字，再把批注交给 AI。PDF 与图片仅可批注；改字依赖 Harness 自带的 LibreOffice 与 Python。", "pdfdoc", 0, "docs"),
        E("dsh-plugin-readme-zh", "dsh-plugin-readme-zh", "把已安装插件的文档翻译成简体中文：README 按章节翻译并持久缓存；另有默认关闭的可选 metaSidecars 模式，会为每条插件列表行写入 locale/zh.json 侧文件，让列表原生渲染中文。", "data", 0, "docs"),
        E("dsh-plus-1", "dsh-code-wiki", "项目 Wiki 生成器：聚合 README 摘要、docs 树、技术栈、git 活跃度与语言构成，本地缓存并可导出 Markdown。", "git", 0, "docs"),
        E("dsh-pptx-anim", "dsh-pptx-anim", "给已生成的 .pptx 批量写入 PowerPoint 进入动画与幻灯片切换——直接构造 python-pptx 未实现的 OOXML timing 树，并附带结构校验器。需本机 Python 3 且已安装 python-pptx（插件会自动探测 python / python3 / py）。", "pdfdoc", 0, "docs"),
        E("dsh-preview-extra", "dsh-preview-extra", "在右侧栏文档预览中打开 STL、OBJ、PLY、glTF 与 GLB 模型，zip/tar/gzip 压缩包，音视频、字体、字幕，以及 TOML、Intel HEX、JCAMP-DX 谱图、VCD 波形、KiCad 原理图和电路板、DFU 固件。", "codec", 0, "docs"),
        E("dsh-quarto-book", "dsh-quarto-book", "把一份 Quarto Book 写成可读、可查、可发布的中文技术书：九步章节写作、结构/链接/图表检查、统一主题与渲染验收。仅在 type: book 仓库加载；需 Quarto CLI 与 Python 3。", "git", 0, "docs"),
        E("dsh-readme-reel", "dsh-readme-reel", "把插件仓库里已有的截图排成一条 6 秒无声循环首屏短片：VP9 webm（保留真 alpha）、压平垫底的 gif、封面帧，外加记录每幕停留与 sha256 的清单。时间轴按构造即精确（整数停留 + 转场之和等于 durationMs，最后一幕转场回第一幕，t=0 与 t=结束同一帧）。零运行时依赖", "git", 0, "docs"),
        E("dsh-reviso", "reviso-dsh", "把 Agent 产出发布到 Reviso 供人工评审，在侧边栏浏览已发布文档，并在产生这些文档的同一个 DSH 会话中再次找到它们。OAuth 由宿主中转：Reviso token 只保存在 DSH credentials 里，浏览器仅获得短时效的 embed 会话。需要 Reviso 账号或兼容的", "session", 0, "docs"),
        E("dsh-sacc-translator-cpu", "dsh-sacc-translator-cpu", "翻译 CPU：Windows x64 专属翻译界面，侧栏独立入口，支持工作台／聊天切换、原文与译文双栏、尽量保留原格式的文档翻译、屏幕框选翻译及最近记录，复用宿主模型、语音输入与预览。使用 CPU OCR，无需 NVIDIA 运行库。不要同时启用 CPU 与 CUDA 两个版本。", "image", 0, "docs"),
        E("dsh-sacc-translator-cuda", "dsh-sacc-translator-cuda", "翻译 CUDA：Windows x64 专属翻译界面，侧栏独立入口，支持工作台／聊天切换、原文与译文双栏、尽量保留原格式的文档翻译、屏幕框选翻译及最近记录，复用宿主模型、语音输入与预览。文档 OCR 支持 CUDA 加速，无兼容 GPU 时回退 CPU；屏幕 OCR 使用 CPU。不要同时启用 CP", "image", 0, "docs"),
        E("dsh-storyboard", "dsh-storyboard", "对话收尾可视化故事板：storyboard 工具把 JSON 规范渲染为自包含 HTML 卡片（内嵌 SVG 流程图、编号步骤、事实网格、时间线），写入 ~/.dsh/storyboard/<session>/ 并在侧边栏打开；系统提示词段落与 /storyboard 命令触发生成。纯服务端、零运行", "image", 0, "docs"),
        E("dsh-study-note", "dsh-study-note", "按对话开启学习笔记，自动整理问答，按分类保存并维护 Markdown 索引。", "pdfdoc", 0, "docs"),
        E("dsh-wps365-plugin", "dsh-wps365-plugin", "通过本机安装的 wps365-cli 读写 WPS 365 云文档（智能文档与 .docx/.xlsx/.pptx），写入前先做并发冲突比对；需要 WPS 365 企业版账号。", "pdfdoc", 0, "docs"),
        E("dsh-xia-plugins-2", "packages/gameassist-knowledge", "树状 Markdown 知识库：为 DSH Agent 提供 kb_list/kb_read/kb_write 工具、目录/正文 HTTP 接口，并配套浏览器面板。", "pdfdoc", 0, "docs"),
        E("dsh-yiyide-pdf", "dsh-yiyide-pdf", "在 DeepSeek Harness 里通过一译得连接器账号翻译 PDF：12 个工具覆盖授权、上传与页级预检、三页预览、报价、确认（冻结译点）、任务轮询、质量确认，以及把纯译文或双语对照 PDF 下载到本机。", "pdfdoc", 0, "docs"),
        E("ppt-assistant", "ppt-assistant", "DeepSeek Harness 的一条龙 PowerPoint 助手预设，支持可编辑演示文稿生成、保留模板的修改、渲染和结构质量检查。需 Python 3.10+ 并安装 requirements.txt；渲染另需 LibreOffice 与 pdftoppm，扫描件 OCR 需 Tesserac", "pdfdoc", 0, "docs"),
        E("qiaodoc-dsh", "qiaodoc-dsh", "基于 joeseesun/qiaomu-reader-dsh 二次开发（并非上游官方后续版本；两者都用 qiaomu-reader 插件 id，不要同装）：在 DSH 原生对话旁阅读文档、解释翻译选段，并通过文档历史返回原会话。当前为开发试用版，仅验证 Windows + DSH 0.2.1-rc.", "session", 0, "docs"),
        E("qiaomu-publish-dsh", "qiaomu-publish-dsh", "使用发布主题排版 Markdown，预览效果并导出 HTML 或长图。", "pdfdoc", 0, "docs"),
        E("qiaomu-reader-dsh", "qiaomu-reader-dsh", "在 Harness 中阅读 EPUB、PDF、TXT、Markdown 和 HTML，整理阅读笔记与生词，并使用原生 AI 伴读。", "pdfdoc", 0, "docs"),
        E("qiaomu-ui-learn-dsh", "qiaomu-ui-learn-dsh", "浏览界面设计参考和交互标本，练习设计测验，并导出 Markdown 学习笔记。", "pdfdoc", 0, "docs"),
        E("sendpage-mcp", "sendpage-mcp", "把 HTML 文档变成一键打开、在聊天里显示预览卡的分享链接;支持发布、更新,以及导出 PNG/PDF/Word。", "pdfdoc", 0, "docs"),
        E("deepseek-harness-wallet-patched", "deepseek-harness-wallet-patched", "feibi-mochi/deepseek-harness-control-center 的维护分支，上游自 2026-09-09 起未再更新。计价改为跟随官方模型池、而非硬编码模型前缀，因此 DeepSeek V4.1 Flash（`deepseek-flash`）能正常计价并显示峰谷时钟；官方价格", "git", 0, "usage"),
        E("deepseek-peak-indicator", "deepseek-peak-indicator", "显示当前 DeepSeek API 高峰或非高峰计费时段，以及距离下一次切换的倒计时。", "time", 0, "usage"),
        E("deepseek-time", "dsh", "在 DSH 会话界面显示 DeepSeek 当前高峰/空闲收费时段图标与下一时段倒计时，悬停图标可查询 API 余额。", "time", 0, "usage"),
        E("dsh-agent-token-stats", "dsh-agent-token-stats", "跨 Agent 的 token 用量看板:聚合 Claude Code、OpenCode、Cursor、DSH、OpenClaw、CodeWhale、Hermes 等本地对话日志,台账持久化(删除聊天记录后历史仍留存),提供缓存命中率、成本估算、环比对比与当日下钻分析的侧边栏面板。", "codec", 0, "usage"),
        E("dsh-api-balance-2", "dsh-api-balance", "在对话标题栏实时显示 DeepSeek API 余额与本会话 token 用量，详情面板展开余额拆分（充值／赠送）、请求次数、输入／输出／缓存命中 tokens 与上下文占用；API Key 每次查询现取，不缓存、不落盘、不返回浏览器。", "session", 0, "usage"),
        E("dsh-api-balance-plugin", "dsh-api-balance", "输入框下方常驻 DeepSeek API 余额胶囊，点开显示充值额度、赠送额度、更新时间与用量/充值链接，另有 /balance 命令与 api_balance 工具；凭据只留在 Host（已登录账户钱包或 DEEPSEEK_API_KEY），浏览器只拿到金额。", "time", 0, "usage"),
        E("dsh-api-ledger", "dsh-api-ledger", "按 API 路由与模型配置单价，统计 Token 用量与估算费用，支持可选账单分组、同步切换 CNY/USD，以及会话报告、输入框费用和可点击的侧边栏今日金额。", "text", 0, "usage"),
        E("dsh-ark-usage", "dsh-ark-usage", "火山方舟 Coding Plan 用量挂件：右下角一只可拖动的小鲸鱼，点开看 5 小时 / 周 / 月三档请求配额，再往下是本机 token 折算的今日、近 7 天、本月与累计花费。需要先安装并登录火山方舟 CLI：npm i -g @volcengine/ark-cli，然后 arkcli aut", "ai", 0, "usage"),
        E("dsh-balance", "dsh-balance", "DSH 侧边栏的账户余额胶囊，跟随当前模型的服务商显示余额，支持 DeepSeek、OpenRouter、Moonshot/Kimi、Zhipu/GLM 与 MiniMax，并显示 DeepSeek 高峰/空闲时段。", "ai", 0, "usage"),
        E("dsh-balance-1", "dsh-balance", "侧边栏底部「设置」旁常驻显示 DeepSeek API 余额——读取 DSH 已保存的密钥，悬停查看赠送/充值明细，余额低于 ¥2 变红告警，每 60 秒自动刷新或点击刷新。", "misc", 0, "usage"),
        E("dsh-balance-2", "dsh-balance", "显示 DeepSeek API 余额，并判断当前是否为高峰时段，实时倒计时到下次切换。", "time", 0, "usage"),
        E("dsh-balance-4", "dsh-balance", "会话标题栏实时显示 DeepSeek 账户余额：host 端 /api/balance 路由经凭据 seam 解析 API key（密钥绝不下发浏览器），60 秒自动轮询并支持手动刷新。", "session", 0, "usage"),
        E("dsh-balance-5", "dsh-balance", "侧栏名字行里的 DeepSeek 余额胶囊，显示余额、当前峰谷时段与下次切换倒计时，点一下刷新。", "time", 0, "usage"),
        E("dsh-balance-badge", "dsh-balance-badge", "在 DeepSeek Harness 主界面右下角常驻账户余额，60 秒自动刷新，点击即可立即查询。", "misc", 0, "usage"),
        E("dsh-balance-badge-1", "dsh-balance-badge", "标题栏余额徽章：余额、今日花费、本会话 tokens 一目了然，官方按峰谷时段计价展示，TokenBom 等自定义服务商按平价展示。", "session", 0, "usage"),
        E("dsh-balance-chip", "dsh-balance-chip", "侧边栏底部与右下角常驻胶囊实时显示 DeepSeek API 余额：状态点加金额，每 60 秒自动刷新，密钥从本机凭证库读取。", "misc", 0, "usage"),
        E("dsh-balance-panel", "dsh-balance-panel", "DSH Web 端的供应商额度与余额状态小组件，在输入框底部的停靠区展示剩余额度、用量与限流窗口。wenzetan/dsh-quota-panel 的本地分叉。", "misc", 0, "usage"),
        E("dsh-balance-plain", "dsh-balance-plain", "把 DeepSeek 余额、今日已用、峰谷倒计时与每轮消耗做成 DSH 侧栏 footer 里的一行纯文本，并在余额低于阈值时提醒。这是 dsh-whale-widget（MeteorNOX/DeepSeek-Balance-Whale-Widget）的纯文本衍生版，不能与上游同装：两者注册相同的", "time", 0, "usage"),
        E("dsh-balance-quota", "dsh-balance", "DSH Web 的供应商余额与额度状态栏，支持模型能力设置、外部 JSON 健康监测、可视化字段绑定和逐模型状态详情。", "data", 0, "usage"),
        E("dsh-balance-tasks", "dsh-balance-tasks", "右下角悬浮卡显示 DeepSeek 余额与峰谷档位倒计时，并基于历史平均单任务 Token 消耗与当前上下文估算剩余任务数。", "time", 0, "usage"),
        E("dsh-balance-usage", "dsh-balance-usage", "在侧边栏显示 DeepSeek 账户余额与当前峰谷时段，并按官方高峰/空闲价估算每个会话与每一轮的花费。", "session", 0, "usage"),
        E("dsh-balance-vision", "dsh-balance-vision", "输入框下方实时显示 DeepSeek 余额与本会话消耗，内置官方工作日谷峰计价（周一至周五 9-12/14-18 峰时、周末全天谷时）与 deepseek-v4-flash-vision-exp 视觉模型（按 flash 同价计费，图片按 token 计费，单图最多 384 tokens）。", "image", 0, "usage"),
        E("dsh-billing", "dsh-billing", "按官方模型价目表把 token 折算成费用，在聊天框底部上下文环旁常驻显示本会话与全局的本次已用金额，在左侧边栏显示账户余额，并在本次费用超过你自设的全局上限（超过余额会被夹到余额）或某个会话自己的上限（每个会话各自设、互不共用）时阻断该轮（可一次性或按会话放行）；每个角标右侧可重置计费起点（本次归", "session", 0, "usage"),
        E("dsh-billing-compass", "dsh-billing-compass", "输入框下方的计费面板：DeepSeek 账户余额、官网各模型用量与消费（含每亿 token 单价）、本次运行与整段对话的费用估算。点击弹出面板，面板与输入框同宽同位；余额走官方 /user/balance，用量与消费走 platform 的 usage 接口，整段用量由本地会话日志只读汇总。零依赖（", "session", 0, "usage"),
        E("dsh-cache-bricks", "dsh-cache-bricks", "在 DSH Web 中可视化提示词缓存命中率与模型请求活动，支持请求详情、请求对比和对话定位。", "session", 0, "usage"),
        E("dsh-cache-helper", "dsh-cache-helper", "展示缓存命中、发送前确认请求前缀风险，并按调用步骤定位缓存失效。", "misc", 0, "usage"),
        E("dsh-cache-hit-monitor", "dsh-cache-hit-monitor", "以寄存器阵列与反应堆芯历史盘面的形式，在 DSH 右侧栏实时显示当前会话的提示词缓存遥测。", "session", 0, "usage"),
        E("dsh-cache-saver", "dsh-cache-saver", "按 agent 收敛过大的 MCP 工具 JSON Schema（调度不变），并在设置页展示 token 用量、缓存命中与上下文构成。", "data", 0, "usage"),
        E("dsh-cacheback", "dsh-cacheback", "把 DeepSeek 前缀缓存省下的钱逐笔算清：回放本地 DSH 会话、按官方峰谷价计费，生成 HTML 账单与可分享卡片。", "session", 0, "usage"),
        E("dsh-ccswitch-usage", "dsh-ccswitch-usage", "把 DeepSeek Harness 每次模型调用的 token 用量写进 CC Switch 的用量统计，让 DSH 与 Claude Code、Codex 等 CLI 并列展示在同一个面板里。首启时会回填已有会话日志，并与 CC Switch 自带的 DSH 导入器共用去重台账，两者不会重复计数", "text", 0, "usage"),
        E("dsh-client-ui-balance", "dsh-client-ui-balance", "会话标题栏里的 DeepSeek 账户余额胶囊。由本包自带的 host 半注册同源路由，从凭据服务解析 API Key 后查询 api.deepseek.com/user/balance，Key 始终不进页面；胶囊每 60 秒轮询，可展开明细面板，显示分币种总额、赠送与充值部分、更新时间与手动刷新。", "time", 0, "usage"),
        E("dsh-codex-bridge", "dsh-codex-bridge", "读取本机 Codex CLI 的 ChatGPT 计划额度（5 小时与每周窗口），默认统一使用 gpt-6.1-sol + high 推理强度，任一窗口剩余不超过 10% 时回退 gpt-5.6-sol，并通过 codex exec 外派任务；昂贵的 gpt-6-astra 需要显式开启。需已登录的", "ai", 0, "usage"),
        E("dsh-codex-plus", "dsh-codex-plus", "在 DSH 里查看 ChatGPT / Codex 订阅的真实额度。读账号后端 /wham/usage：短周期（5h）与每周窗口、重置倒计时、额外用量余额、独立额度分组与代码审查额度；列出并使用服务端发放的额度重置卡（幂等键由 credit id 稳定派生，重试只结算一次）；支持多账号切换；读 /c", "git", 0, "usage"),
        E("dsh-composer-balance", "dsh-composer-balance", "输入框下方一枚芯片：显示账户余额与当前对话花费，花费按每轮发生时刻的峰谷档位逐段计价。点击展开 264px 卡片，沿用宿主自带面板的样式，带刷新与设置两个按钮。", "session", 0, "usage"),
        E("dsh-composer-tokens", "dsh-composer-tokens", "为 DSH 对话输入框实时估算 token 数，将当前上下文基线与草稿合并计算，并区分精确计数与启发式估算。", "session", 0, "usage"),
        E("dsh-connectors", "balance-widget", "DSH 会话标题栏右上角的账户余额读数：显示可用总额（充值余额与赠金余额合并），每两分钟刷新一次；未登录或查询失败时不显示任何内容。", "session", 0, "usage"),
        E("dsh-context-budget", "dsh-context-budget", "每步上下文账本：可选开启精简工具表、长结果外置、重复读回指针三个闸门。 作者 A/B 实测，开启工具表闸门后首步 prompt 少 16,110 token（-49.7%），长会话每步上下文约降 23%。", "session", 0, "usage"),
        E("dsh-context-radar", "dsh-context-radar", "估算上下文里谁在吃 token —— 逐文件、逐 skill、逐条工具结果列出占比，并给出膨胀判定与可执行建议。", "fileops", 0, "usage"),
        E("dsh-conversation-cost", "dsh-conversation-cost", "根据已记录的 Token 用量估算每轮回答和会话费用，支持自动更新模型价格及查看价格来源明细。", "session", 0, "usage"),
        E("dsh-convo-cost", "dsh-convo-cost", "当前对话实时费用统计：输入框下方一行显示运行中的 token 用量与 DeepSeek 官方价格估算（基础价与峰谷价）。", "text", 0, "usage"),
        E("dsh-cost-audit", "dsh-cost-audit", "以 harness 自己的统计形态显示每轮与会话的 token 与人民币花费，提供 1/7/30 天窗口的全账号账单与「单位工作量花费」趋势，并给出会在你采纳后重新测量效果的建议。", "text", 0, "usage"),
        E("dsh-cost-crystal", "dsh-cost-crystal", "Web UI 成本水晶球:余额卡片、实时 tok/s 速率、波峰/低峰计费倒计时、近 24h 消耗,以及 🔮 下一条消息消耗预测,全部时区感知。", "time", 0, "usage"),
        E("dsh-cost-meter", "dsh-cost-meter", "在 DeepSeek Harness 对话标题栏显示会话费用芯片：实时分桶 Token 用量、高峰/非高峰费率，以及到下次费率切换的倒计时。", "time", 0, "usage"),
        E("dsh-cost-pill-cny", "dsh-cost-pill", "把本次会话的估算费用直接写进输入框上方的 Token 用量胶囊，并在用量弹窗里为每个分项补上金额与预估合计，按 DeepSeek 官方高峰与空闲时段价（人民币）计算。", "session", 0, "usage"),
        E("dsh-cost-today", "dsh-cost-today", "在侧边栏底部、输入框下方与会话头部显示今日、本月与累计花费；金额由插件自记 —— 从会话用量事件按 DeepSeek 官方单价逐次累计（含 UTC 峰谷，周末与节假日按平时价），并按本地日汇总、换算币种。另提供 cost_today 工具与 /cost 命令。", "session", 0, "usage"),
        E("dsh-daily-read", "dsh-daily-read", "日报一键读：敲 /daily 就把「去读最新那篇刷B站日报」塞进当前会话——只给路径不给正文，让它自己读原文；侧栏面板发的是同一条命令。需 dsh-bili-scroll 已把日报写进 ~/.dsh/bili-duty/out，否则 /daily 找不到日报。", "fileops", 0, "usage"),
        E("dsh-deepseek-balance-1", "dsh-deepseek-balance", "dsh Web 界面的 DeepSeek 账户余额浮窗：按币种显示总余额、赠送余额与充值余额，每 60 秒刷新一次。可拖动、可折叠；API Key 按「卡片手动输入 → 凭据服务 → 环境变量 DEEPSEEK_API_KEY」顺序解析。", "misc", 0, "usage"),
        E("dsh-deepseek-balance-4", "dsh-deepseek-balance", "一个侧边栏挂件同时显示 DeepSeek API 账户余额与当前推理服务商的实时往返延迟，并可自定义余额告警阈值。读取余额需要在 DSH 凭据中配置 DEEPSEEK_API_KEY，未配置时挂件会提示缺少密钥。", "ai", 0, "usage"),
        E("dsh-deepseek-cost-live", "dsh-deepseek-cost-live", "DSH Web 实时显示 DeepSeek API 官方余额与今日花费(本机会话日志用量 x 分模型价格表的本地估算):输入框下方统计小条 + 右下角常驻悬浮徽标 + 设置页完整面板(近 7 日趋势、分模型花费、可编辑价格表/轮询、历史重扫)。API Key 不出宿主进程。", "sysinfo", 0, "usage"),
        E("dsh-deepseek-peak-badge", "dsh-deepseek-peak-badge", "输入框下方的徽标：显示 DeepSeek 是否处于高峰计费时段——高峰时为红色，高峰开始前 30 分钟内为黄色，空闲为绿色；非 DeepSeek 来源时隐藏。", "misc", 0, "usage"),
        E("dsh-deepseek-usage-1", "dsh-deepseek-usage", "在侧边栏脚部显示一行 DeepSeek 账户余额（带刷新按钮），点击打开弹层：余额卡、7/30 天每日 Token 与估算费用图表、按模型明细表，以及平台用量页外链。余额取自官方 /user/balance 接口；用量由本机 DSH 会话日志聚合，按官方峰谷单价以人民币估算，因此界面明确标注为估算值", "session", 0, "usage"),
        E("dsh-deepseek-usage-meter", "dsh-deepseek-usage-meter", "在输入栏统计行、官方 token 用量条旁加一枚费用与余额胶囊：本次会话的 DeepSeek 估算费用、峰谷时段指示灯与已登录账号的剩余额度，明细里按计费项列出各自金额；仅在检测到 DeepSeek 官方渠道时激活。", "text", 0, "usage"),
        E("dsh-deepseek-wallet", "dsh-deepseek-wallet", "在输入框工具栏实时显示 DeepSeek 账户余额，并在每轮完成对话的 token 用量旁显示按官方峰谷价计费的人民币金额：北京时间工作日上下午为高峰价，周末与法定节假日为空闲价。余额需要 DEEPSEEK_API_KEY 凭据，仅通过 DeepSeek OAuth 登录的账号不显示余额。", "time", 0, "usage"),
        E("dsh-desktop-linux-updater", "dsh-desktop-linux-updater", "桌面端 Linux 自建版一键更新：检查 fork release、下载 deb、替换应用目录并自动重启。", "net", 0, "usage"),
        E("dsh-dsbal", "dsh-dsbal", "在 DSH Web 侧边栏显示 DeepSeek API 账户余额：30 秒自动刷新、点击刷新、悬停查看明细、余额不足阈值告警。", "misc", 0, "usage"),
        E("dsh-entry-shaper", "dsh-entry-shaper", "代理 provider：每次出网前按类别跑 op 链重塑 payload 再转交上游，使 prompt 前缀在回合之间保持单调、未变的历史不必按全价重付；op 名只表示传输方式（exec / http / inline），可接入用户自定义算法。", "net", 0, "usage"),
        E("dsh-faremeter", "dsh-faremeter", "按 DeepSeek 官方价目显示每轮、每会话与每工作区的对话费用人民币金额，支持峰谷分时与 Search/Fetch 按次计费。", "search", 0, "usage"),
        E("dsh-float", "dsh-float", "DSH Web GUI 的 DeepSeek API 余额浮窗：角落胶囊显示余额，点击展开总额、赠金与充值明细，双击立即刷新且每 5 秒轮询一次；宿主侧代理 /user/balance，密钥不下发到浏览器。", "net", 0, "usage"),
        E("dsh-frame", "dsh-frame", "看清一场对话到底烧了多少：模型请求次数、system prompt 与工具表各占多少、累计 token、估算花费、离上下文自动压缩还有多远。只读本地会话日志，不调模型，不往 system prompt 加一个字。token 与花费均按字符数估算，不是 provider 用量。", "archive", 0, "usage"),
        E("dsh-free-egg-credits", "dsh-free-egg-credits", "在 DSH 侧边栏看 WorkBuddy / Qoder 账号积分、今日额度、签到状态与每轮消耗（WorkBuddy 已知单价时按输入 / 缓存 / 输出分类型折算）；配置 new-api 后可一键切换优先消耗平台。需本机运行 WorkBuddy2API 或 Qoder 网关。", "misc", 0, "usage"),
        E("dsh-genui-scope", "dsh-genui-scope", "按全局、工作区、会话三级裁剪 GenUI 卡片组件提示词；内置预设削减 24% 到 61% 的提示词。", "session", 0, "usage"),
        E("dsh-glm-balance", "dsh-glm-balance", "在输入框下方常驻显示智谱 GLM Coding Plan 余量，含 5 小时/每周额度、重置时间、MCP 调用量与今日用量，并附 glm_balance 查询工具。", "time", 0, "usage"),
        E("dsh-glm-quota-dock", "dsh-glm-quota-dock", "在输入框统计行常驻 GLM Coding Plan 额度 pill(含 5 小时窗口重置倒计时),点击展开双列卡片式详情面板:各窗口限额、重置时间、近 24 小时按模型 Token 用量与小时级 sparkline,支持插件一键自更新。", "time", 0, "usage"),
        E("dsh-gpt-niang-quota", "dsh-gpt-niang-quota", "Tokyo 的可拖动陪伴挂件，支持 Codex 额度监控、手动程序定位和可编辑回复。需安装 Codex CLI（codex app-server）并使用 ChatGPT 登录；API-key 登录不显示订阅额度。", "sysinfo", 0, "usage"),
        E("dsh-hann-usage-dashboard", "dsh-hann-usage-dashboard", "DeepSeek Harness 用量页签：展示 DeepSeek 账户余额、官方峰谷时段价格、动态倒计时、平台用量页入口和本地余额告警灯。", "time", 0, "usage"),
        E("dsh-herta-balance-card", "dsh-balance-card", "可拖动的余额与用量浮层卡片：点一下角色图片，卡片从图片左侧滑出，再点一下缩回；显示官方 DeepSeek 余额（赠金 / 充值拆分），并按缓存命中、未命中、输出三段计价，汇总本地会话日志的今日 / 近 7 天 / 本月 token 用量与人民币估算花费（按官方峰谷时段逐次计价）。", "image", 0, "usage"),
        E("dsh-hover-dict", "dsh-hover-dict", "点选或划选聊天回复里的英文单词，显示词性、中文释义与考纲标签；划选纯英文句子翻译成中文。词库离线内置：20,499 词条，8,960 个带双语例句，6,374 个带词根分析。", "misc", 0, "usage"),
        E("dsh-keep-running", "dsh-keep-running", "配额看门狗：遇到 429 或配额错误时建立循环调度，持续重发「继续任务」提示直到某一轮正常结束，长任务不必手动重开；/keep-running list 与 /keep-running cancel <id> 用于查看和取消。需先挂载 @deepseek-ai/dsh-schedule（调度由它注册", "misc", 0, "usage"),
        E("dsh-ledger-kitty", "dsh-ledger-kitty", "窗台上的白猫记账助手：显示每条回答与会话的 token 和花费、提示缓存省下的钱、上下文占模型窗口的比例、下一次峰谷换价时间与实时 DeepSeek 余额；可摸头打呼噜，随 agent 工作状态做出反应，所有音效均为合成。", "time", 0, "usage"),
