        E("dsh-team-reporter", "dsh-team-reporter", "把每台机器的 token 用量上报给你自己托管的团队服务器：一次性绑定码、离线落盘队列、幂等重放，管理员在一处看到全员用量与成本。", "ai", 0, "usage"),
