        E("dsh-tokstats", "dsh-tokstats", "可能有用的 DSH token 用量插件，跨会话统计 token 都花在哪儿了：用量总览四项指标、上下文长度分布、近 12 周热力图与按周趋势，工作区与模型排行；另附有发送前 token 预告和输入草稿优化功能。", "text", 0, "usage"),
        E("dsh-turn-cost", "dsh-turn-cost", "在 DSH Web 界面显示每轮与整个会话的预估费用：按 provider 上报的 token 用量（四桶）与内置官方 DeepSeek 人民币峰谷价目计价，高峰为北京时间周一至周五 9:00–12:00、14:00–18:00，周末与中国法定节假日全天按空闲价；可用本机费率表叠加其它或自部署模型的", "time", 0, "usage"),
        E("dsh-usage-badge", "dsh-usage-badge", "DeepSeek Harness 的侧边栏用量徽标：显示当天 token 总量与估算费用；弹窗里有 24 小时 / 近 7 日 / 近 30 日 / 近 12 个月与按年图表、活跃度热力图，按 DeepSeek 官方定价与中国法定节假日逐请求计算峰谷价，并可选 WebDAV 云同步合并多台机器的用量", "ai", 0, "usage"),
        E("dsh-usage-card", "dsh-usage-card", "侧栏常驻卡片：按 DeepSeek 官方价目（含峰谷与缓存差价）把本会话 token 折算成人民币，并按来源拆开上下文占比；逐轮计价，另附 Markdown/CSV 历史报告。", "pdfdoc", 0, "usage"),
        E("dsh-usage-dash-board", "dsh-usage-dash-board", "本机跨会话用量汇总：把 qfmodel 这类不透明路由键解析为真实模型名，含逐请求明细表与可编辑的四桶价格表（无公开单价的模型标为未计价而非猜测），趋势柱状图按日历日补齐、数值仅在悬浮或键盘聚焦时显示。", "time", 0, "usage"),
        E("dsh-usage-guard", "dsh-usage-guard", "规范化异常的 Token 用量样本，使损坏的会话历史仍可加载。", "session", 0, "usage"),
        E("dsh-usage-limits", "dsh-usage-limits", "在 DSH 中显示 OpenAI 与 Codex 的用量配额：Web 端用环形表与面板展示 5 小时 / 7 天窗口，dst 端在状态行显示同样的窗口。", "misc", 0, "usage"),
        E("dsh-usage-meter", "dsh-usage-meter", "设置页用量仪表盘：按服务商/模型汇总全部会话 token 用量，含今日/近 7 天/近 30 天趋势柱状图与缓存命中率。", "session", 0, "usage"),
        E("dsh-usage-mini", "dsh-usage-mini", "DSH Web 悬浮用量小窗，显示 Claude、Codex 订阅用量窗口与重置倒计时，以及 DeepSeek API 今日花费与余额；只展示，是 dsh-cost-meter 的伴侣。", "time", 0, "usage"),
        E("dsh-usage-panel", "dsh-usage-panel", "会话头部显示 DeepSeek 余额与本会话 Token 用量：三级余额预警、自定义阈值、一键充值入口、分段 Token 条与缓存命中率，并采用可见时才轮询的省流策略。", "session", 0, "usage"),
        E("dsh-usage-panel-1", "dsh-usage-panel", "用量统计设置页：全部基于本地会话日志计算（近 30 天条形图 / 模型表 / 会话表），按服务商感知计价（官方峰谷、内置 TokenBom 平价表），并跳过子代理会话继承的历史事件避免重复计费。", "net", 0, "usage"),
        E("dsh-usage-peak", "dsh-usage-peak", "DeepSeek Harness 用量峰谷仪表盘：侧栏胶囊常显峰谷、今日花费与 tokens，详情页提供 24 小时、近 14 天与按模型的用量拆分。", "ai", 0, "usage"),
        E("dsh-usage-stats", "packages/dsh-session-token-stats", "输入框里的当前会话 Token 胶囊：总量与未缓存输入、缓存读取、缓存写入、输出四个分桶，并显示缓存命中率；纯客户端消费会话 tokenUsage 投影，不注册宿主服务、不读写文件、不联网。", "fileops", 0, "usage"),
        E("dsh-usage-stats-1", "packages/dsh-usage-stats", "侧边栏里的全量会话 Token 用量仪表盘：累计/峰值 Token、连续使用天数、53 周活动热力图、7/30 天趋势、按模型用量与会话排行；在本地从 profile 的会话投影缓存汇总（旧会话格式的会话也能统计），不联网，只读汇总路由拒绝非本机请求。", "fileops", 0, "usage"),
        E("dsh-usage-stats-4", "usage-stats", "统计所有已存 DSH 会话的 token 用量：Host 端把持久化会话日志折叠进检查点，并经一条只读 HTTP 路由提供；「用量」设置页先立即绘出已保存的聚合结果，再在后台更新。当日视图按小时分桶（带日期选择器），旁边是近 7/30 天窗口，含分模型明细、请求数与联网搜索次数；不含费用/定价模型。", "time", 0, "usage"),
        E("dsh-usage-stats-plus", "dsh-usage-stats-plus", "DSH 用量与余额面板：官方余额实时拉取、逐事件官方峰谷计价、基于余额快照的全渠道消耗估算、Codex 风格 12 个月 Token 活动时间轴。Fork 自 Ychris12138/dsh-usage-stats。", "time", 0, "usage"),
        E("dsh-usage-wave", "dsh-usage-wave", "余额、剩余 tok 与用量面板：侧栏底部一张余额/剩余 token 卡片，点开是贴在对话栏左侧空白处的用量面板 —— 1h/6h/24h/7d 的 token/金额堆叠波形、实时 tok/s 曲线、逐指令消耗与花费；按最近 24h 实付均价折算「余额还能跑多少 tok」。", "session", 0, "usage"),
        E("dsh-wallet-pill", "dsh-wallet-pill", "DeepSeek Harness 的余额胶囊：在输入框下方显示 DEEPSEEK_API_KEY 对应账户的余额，点开可查看峰谷计费时段、切换倒计时与各模型价目表。", "time", 0, "usage"),
        E("dsh-web-search-insights", "dsh-web-search-insights", "联网搜索的「搜索洞察」：记下 Agent 查了什么、搜回哪些网页，并统计每轮与整个会话的搜索次数、返回网页数、被引用数与被打开读过的页数；这些数字在回答下方的引用入口和右侧栏面板里随时能回看。", "text", 0, "usage"),
        E("dsh-workspace-switch-cost", "dsh-workspace-switch-cost", "工作区切换成本量化：量每个工作区的冷启动开销（AGENTS.md + 技能目录 + 工具 schema + 运行时上下文）、稳态值、 几轮到达稳态，然后横向对比并归因。归因需要至少三个工作区，不到就明说数据不够而不是拿两个点编一个相关性； 在所有工作区之间没有差异的因素被标注为 profile 的属", "data", 0, "usage"),
        E("dsh-zhipu-plan", "dsh-zhipu-plan", "在 DeepSeek Harness 中登录智谱编程套餐，查看额度与用量并执行额度重置。", "misc", 0, "usage"),
        E("glm-coding-quota", "glm-coding-quota", "输入框下方实时显示 GLM Coding Plan 额度环 - 5 小时与每周额度窗口、等级、自动刷新与一键重试。需 GLM Coding Plan 订阅与 key，并配置 BigModel 的 organization 与 project ID（团队额度接口缺了它们会返回空）。", "misc", 0, "usage"),
        E("missher-dsh-usage-statistics", "Missher-DSH-Usage-Statistics", "汇总本地会话的 Token 用量、每日与小时活动，以及模型、工具和技能使用情况。", "session", 0, "usage"),
        E("sapi-budget", "sapi-budget", "AiSpot（sapi）中转站的费用显示插件：从供应商的公开价格端点动态爬取分组列表而非硬编码，在会话标题栏的下拉框里选择当前分组，在每轮对话结束处显示本轮费用，并在标题栏显示递归合计所有子代理子树的会话总额。切换分组会即时重算全部历史金额，因为宿主只发布 token 桶、由浏览器按实时价目表计价。", "codec", 0, "usage"),
        E("token-usage-statistic", "token-usage-statistic", "统计本机每次模型调用的 token 用量与预估费用，提供每日图表、会话/工作区名称、账户余额、预算与无凭据 CSV/JSON 导出。", "data", 0, "usage"),
        E("usage-widget", "usage-widget", "DSH 侧边栏账户余额快捷查看：显示余额、赠送额度、当前模型和官方高峰 / 空闲计费时段，按余额分四档显示质感，余额过低时提醒。", "ai", 0, "usage"),
        E("agentschat-mcp", "mcp-plugin", "通过 MCP 与 WebSocket 唤醒桥接将 DeepSeek Harness 接入 AgentsChat 共享房间，支持跨宿主多 Agent 通信、代码互审、提案投票与 OKR 协同。", "ai", 0, "remote"),
        E("bridge", "dsh-bridge-connector", "让 Obsidian 插件驱动 DSH 会话、并把库内笔记注入系统提示词的回环 HTTP/SSE 服务（按路径每轮重读磁盘，笔记改了下一轮就生效）；需要 Obsidian 内配套运行的插件。", "sysinfo", 0, "remote"),
        E("dimensional-portal-dsh", "dimensional-portal-dsh", "让 DSH 里的 Agent 直接操作安卓手机：看屏幕、点按滑动、打字、开应用。需要电脑侧 Python 3.10+ 并安装 aiohttp 与 mcp，手机侧运行 AutoX.js 脚本并授予屏幕录制与无障碍权限；手机主动长轮询本机，不开公网端口、不经中转。", "net", 0, "remote"),
        E("dot-dsh-management", "dot-dsh-management", "通过原生 Harness 工作台和本机网关，让 Dot 读取已保存项目与会话、派发原生任务、查看进度、继续或取消任务，并管理连接授权。", "session", 0, "remote"),
        E("dsh-a2a-1", "dsh-a2a", "Agent2Agent（A2A）协议桥：内置 A2A 服务端（agent card、message/send、message/stream SSE、任务 get/cancel/resubscribe、input-required 续答）；a2a_discover/a2a_send 等 4 个工具呼叫", "ai", 0, "remote"),
        E("dsh-anywhere", "dsh-anywhere", "专为 DSH iOS App 与移动端协同打造的远程连接插件，支持扫码配对、锁屏恢复与隧道管理。", "devops", 0, "remote"),
        E("dsh-community-web-ui", "dsh-community-web-ui", "DeepSeek Harness 独立远程 Web UI：适配手机视口、软键盘与触控热区，同时保持原生桌面端界面不变。", "misc", 0, "remote"),
        E("dsh-console-1", "dsh-plugin", "通过自建中继，用手机远程操作电脑上的 DSH：发消息/图片/文件、看流式回复、截取桌面、远程 Alt+Tab。", "image", 0, "remote"),
        E("dsh-deep-connect", "plugin", "同账号多台 DSH 的会话与任务互通：一台机器生成中继站，其它机器用邀请链接加入；逐帧端到端加密，中继只路由哈希频道、读不到内容。对端可读完整对话与任务板，向拥有该会话的那台机器正在跑的一轮插话，按发送方选定的目标工作区与模型强度下发命令，也可把一条会话复制成本机新会话并继续在这里干活。另带令牌手机", "codec", 0, "remote"),
        E("dsh-devops-plugin", "DSH-DevOps-Plugin", "DSH Web 远程运维插件：管理 SSH 服务器、采集硬件与进程指标、以只读 AI 巡检日志，并通过 SSH 部署 Git 仓库（git pull --ff-only 加健康检查）。凭据 AES-256-GCM 加密存储。支持 Linux 与 macOS，不支持 Windows。", "git", 0, "remote"),
        E("dsh-dfy-qq", "dsh-dfy-qq", "给 DeepSeek Harness 加一层 QQ 对话行为：人设文件注入每一轮、按 QQ 号认人的群友档案、带概率与大保底的表情包挑选、可选的主动接话、从群友原话蒸馏出的语气子人格，以及定时消息。开启内置 QQ 通道后，任何 QQ 用户私聊机器人、任何群里 @ 机器人都能驱动 Agent；没有发送", "time", 0, "remote"),
        E("dsh-docker-3", "dsh-docker", "dsh-docker 是 DeepSeek Harness Web 的 Docker 管理面板插件：支持本机 CLI 与 SSH 远端多目标一键切换，统一管理 Docker MCP（部署/移除/搜索官方 Catalog/启停重启 Gateway/自定义部署）与容器镜像（启停/删除/日志/详情/交互式", "search", 0, "remote"),
        E("dsh-feishu-assistant", "dsh-feishu-assistant", "给同事的运维请求通道——同事在飞书私聊里提的事先排进串行队列，由已配对的管理员在审批卡上放行后才进入那条共享的 DSH 会话（带注入的人设执行），回答回到提交人。", "git", 0, "remote"),
        E("dsh-feishu-bridge", "dsh-feishu-bridge", "把 DSH 接到飞书自建应用的长连接：接收聊天消息投进指定会话，再把回复发回同一会话。带去重、白名单、回执文案与试运行开关。自触发已拆到 dsh-self-trigger。", "text", 0, "remote"),
        E("dsh-herdr-site", "dsh-herdr-site", "让 Herdr 认识 DSH 面板：把 agent 的 working/idle/blocked 状态报给 Herdr（含 DSH 本身没有的 blocked 等待态），支持面板跳转与 --wait。（状态上报 / 状态显示 / 终端集成 / 面板跳转）", "ai", 0, "remote"),
        E("dsh-im-union", "dsh-im-union", "DSH 的 IM 联合桥：整合社区同类插件（xmanrui/dsh-im、MichengAI/dsh-im-connect）能力合集的独立实现——用 12 个平台的 15 个渠道适配器（含邮件；企微/钉钉/QQ 各含机器人与自建应用或推送两档）驱动宿主会话——微信（官方 iLink 扫码绑定）、飞书", "session", 0, "remote"),
        E("dsh-jand", "dsh-jand", "在 DeepSeek Harness 中进行加密文件交接与跨设备 Agent 协作，支持后台收件和受管任务执行。", "codec", 0, "remote"),
        E("dsh-lan-access-1", "dsh-lan-access", "可配置的 DSH Web GUI 局域网访问：设置页开启后绑定全部网卡，只信任你配置的访问地址，可调整浏览器会话有效期或去掉 token 登录，并修复非回环访问时的设置层。", "session", 0, "remote"),
        E("dsh-lan-gate", "plugin", "dsh-lan-gate 局域网网关的控制面：设置图标旁的一个按钮，显示网关是否在跑、有几台手机或平板在等批准；一次点击打开只认回环地址的批准页，省去手敲 URL；网关没在跑时先经计划任务把它拉起。在手机或平板界面上不渲染。", "misc", 0, "remote"),
        E("dsh-mobile-3", "dsh-mobile", "DSH 手机端 Web UI：带令牌认证的局域网服务，手机可浏览全部会话、通过 SSE 实时查看回复并继续对话；桌面 GUI 提供二维码入口，配合 dsh-whale-girl 0.3.0+ 现在还可以点桌宠鳍里的小手机打开面板。", "codec", 0, "remote"),
        E("dsh-mobile-pairing", "dsh-mobile-pairing", "DSH 手机远程配对：提供二维码 offer、回环 Host Gateway、加密 Relay 或 Quick Tunnel、同网 WebRTC Direct，以及可撤销的 Android Device Token。", "codec", 0, "remote"),
        E("dsh-my-phone", "dsh-my-phone", "让手机连上本机的 DeepSeek Harness 桌面版：局域网或 Cloudflare 隧道二维码配对，实时消息列表与授权提醒，桌面悬浮球。局域网与 Cloudflare 隧道两个入口默认都开启；每台手机用自己的配对令牌。", "codec", 0, "remote"),
        E("dsh-pair-quick", "dsh-pair-quick", "在 dsh 设置页直接铸造 remote-web-ui 远程访问配对链接并显示二维码。", "codec", 0, "remote"),
        E("dsh-phone-mirror", "dsh-phone-mirror", "在 DSH 右侧栏通过 adb 投屏并反控安卓手机/平板，视频、短视频和聊天留在电脑上，在工位上不必再拿手机；声音转发需 Android 11+，仅支持 Windows。", "media", 0, "remote"),
        E("dsh-phone-remote", "dsh-phone-remote", "DSH 手机远程访问的开箱即用修复套件：把 PWA manifest 的 start_url 改到 /pair-app，解决 iOS「添加到主屏幕」后打开停在 401 的问题；附常驻/守护脚本、自动登录与电源设置说明、中文排错手册。需安装 @linxin666/dsh-remote-web-ui（/", "archive", 0, "remote"),
        E("dsh-plugin-agent-bridge", "dsh-plugin-agent-bridge", "两台 DeepSeek Harness 主机之间的双向 agent 桥：任一侧可向对端 agent 提问并运行有界多轮对话，链路经 PSK 认证；两侧提供聊天页，默认只读工具姿态。两端需配置相同的共享密钥与 nodeId。", "session", 0, "remote"),
        E("dsh-plugin-android-vscreen", "dsh-plugin-android-vscreen", "在虚拟显示器上启动安卓应用，用读屏、点击与滑动驱动它们，主屏不受影响。", "misc", 0, "remote"),
        E("dsh-plugin-dshm", "bridge", "通过本地网络或 Tailscale，将 DSHM iPhone/iPad 配套应用连接到 DeepSeek Harness，支持设备配对、会话控制和文件传输；配套应用的公开 TestFlight 仍在等待 Apple 审核。", "fileops", 0, "remote"),
        E("dsh-plugin-feishu-im", "dsh-plugin-feishu-im", "飞书 IM 通道：扫码创建专属飞书机器人；每轮结束推一张卡片，在飞书里授权工具调用、回答结构化提问，并直接用聊天驱动会话（/sessions 列会话、/resume 切换绑定会话、任务进行中可插话引导），还能按对话设置权限模式（只读 / 工作区读写 / Auto Review / 完全权限）。消息以", "session", 0, "remote"),
        E("dsh-plugin-loopback-trust", "dsh-plugin-loopback-trust", "反向代理域名访问 dsh web 时恢复设置页的 Host 持久化：将页面连接标记为宿主可信，设置与模型页正常加载，不再报 \"settings are unavailable in this browser\"。适用于 dsh 0.1.7 – 0.2.x。", "net", 0, "remote"),
        E("dsh-plugin-qq-bridge", "dsh-plugin-qq-bridge", "把 QQ 官方机器人接到 DSH 进程内：QQ 里发消息直接开一轮真实会话（工作目录是已登记工作区时，桌面端左侧能看到、能续聊），结果以文本、图片或文件回传 QQ。需一个 QQ 官方机器人应用（AppID + AppSecret）。", "image", 0, "remote"),
        E("dsh-plugin-remote", "dsh-plugin-remote", "DSH Web 远程访问网关：登录鉴权 + 到本机服务的 HTTP/WebSocket 反向代理，无需 --trusted-host。", "net", 0, "remote"),
        E("dsh-plugins-19", "dsh-tether-ios", "面向 macOS Apple Silicon 上 DSH Desktop 0.2.0-rc.2 的 iOS 远程控制插件，支持配对、审批通知与设备撤销。", "image", 0, "remote"),
        E("dsh-plugins-21", "dsh-wx-remote", "用微信继续 PC 端未完成的 DSH 会话：轮询微信 iLink 消息，运行中的会话直接注入、已关闭的自动续接，回复原文发回微信；支持 /会话 列出与绑定会话、/新会话 解绑。需配置 wechat-acp 守护进程；仅处理发送者白名单内的微信用户，未配置白名单时拒绝所有人。", "sysinfo", 0, "remote"),
        E("dsh-pocket-glide", "dsh-pocket-glide", "把桌面 DSH 的电话面做成克制遥控器：白名单透传会话读写、发消息与权限审批，页面由宿主直接产出、无构建链，扫码配对，隧道地址变了自动推回手机。", "session", 0, "remote"),
        E("dsh-pocket-plus", "plugin", "dsh-pocket 的增强版：访问密码直接写进二维码，手机扫一次即可登录；新增只读接口 /dsh-pocket/entry.json，手机 App 在局域网时就能同步当前公网地址与密码；内网 / Tailscale / Cloudflare 三条链路按顺序探测、断线自动切换。这是 shaobeic", "codec", 0, "remote"),
        E("dsh-porthole", "dsh-porthole", "为 DeepSeek Harness 提供局域网访问门户，支持双密码认证和子路径反向代理。派生自 wenbin-wb/dsh-bridge v2.17.8（MIT，部分模块逐字沿用）；两者默认端口均为 3082，同开前需修改其中一个的端口。认证默认未开启：把端口暴露到局域网前，请先设置访客与管理员密", "net", 0, "remote"),
        E("dsh-pve-vm", "dsh-pve-vm", "在对话里控制 Proxmox VE 虚拟机：16 个工具，既能通过 VNC 操作 VM 控制台（截图、鼠标、键盘、批量动作、Unicode 文本与剪贴板），也能经 QEMU guest agent 执行命令、读写文件；全部走一条到节点的 ssh 连接，宿主无需 X11 或 Wayland。", "image", 0, "remote"),
        E("dsh-qq", "dsh-qq", "把 QQ 接成一条能进来的路：主人私聊一到就地开一个会话（读同一个家、同一份起床包），答完发回去；正文带一行 \\[SEND_FILE: 绝对路径] 能把文件送到手机上。需另行运行带正向 WebSocket 的 OneBot v11 实现（如 NapCat），并在配置里填 ownerId，否则所有消息", "fileops", 0, "remote"),
        E("dsh-qq-bridge", "dsh-qq-bridge", "把 QQ（NapCat）接入 DeepSeek Harness：私聊和群聊消息变成会话提示词，回复按行发回 QQ。", "session", 0, "remote"),
        E("dsh-qq-shell-commands", "dsh-qq-shell-commands", "目的是能远程运行 Shell 命令，而不是让 DSH 运行，适用于需要重复工作或托管行为但不能直接给权限到 DSH 的情况。原理是通过 NapCat 进程与 QQ 进行交互，当 QQ 发送特定消息，判断是否完全相等与哪个键的字符串，并执行对应的 Shell 命令。执行 Shell=\"执行 Shell", "sysinfo", 0, "remote"),
        E("dsh-remote-2", "dsh-remote", "为 DSH 会话提供 OpenAI 兼容的 HTTP 接口与手机面板：读会话、浏览文件、发送或排队消息，并在手机上处理审批与提问。", "fileops", 0, "remote"),
        E("dsh-remote-access-qr", "dsh-remote-access-qr", "远程接入插件：把本机 DSH 经 SSH 反向隧道映射到服务器并生成二维码，手机扫码直进本机 dsh。需自备可 root 登录的 Linux 服务器，并装好 nginx、openssl、qrencode；插件会改写该机 nginx 配置，二维码链接本身是一年有效的登录凭据，请当作密码保管。", "codec", 0, "remote"),
        E("dsh-remote-auth", "dsh-remote-auth", "DSH 远程授权页：以可点击链接或二维码呈现当前进程的浏览器会话 URL，可选主机/网段白名单与 PIN 门禁。", "codec", 0, "remote"),
        E("dsh-remote-bot-bridge", "dsh-remote-bot-bridge", "基于 ds-harness-remote 的跨机器 Bot 传话：五个工具让本地 Bot 列出对端 Bot、固定目标设备并给它发消息，不用切换本地窗口。", "session", 0, "remote"),
        E("dsh-remote-dsh", "dsh-remote-dsh", "在侧边栏顶部加一行，点击后整页切换成另一台 DSH 主机的 Web GUI（通过回环端口访问），并在该行显示那台主机的会话状态（运行中、有新活动、正等你回答）。", "net", 0, "remote"),
        E("dsh-remote-gateway", "dsh-remote-gateway", "带精确来源 IP 白名单的 HTTP/SSE/WebSocket 网关，让 DSH Web UI 在带认证反向代理后保持设置、插件与宿主机目录选择功能，并提供白名单健康检查。", "net", 0, "remote"),
        E("dsh-remote-gateway-1", "dsh-remote-gateway", "提供安全的反向代理，使DeepSeek Harness可以远程访问，随时随地和AI对话。", "net", 0, "remote"),
        E("dsh-remote-gpu", "dsh-remote-gpu", "在会话顶栏显示 dsh-remote 所连服务器还有几张空闲显卡，右侧边栏面板展示每张卡的利用率、显存、温度与占用用户，并提供返回同一快照的 remote_gpu 工具。", "sysinfo", 0, "remote"),
        E("dsh-remote-gui", "dsh-remote-gui", "通过 SSH 隧道把远端 DSH 的 GUI 嵌进本地 DSH 界面，列出远端会话，并在本地实例与任意远端主机之间切换。", "session", 0, "remote"),
        E("dsh-remote-server-manager", "dsh-remote-server-manager", "在 Harness Web UI 中管理远程 Linux 服务器：通过 SSH 浏览和编辑文件、查看主机状态、启动/停止/重启 Docker 容器、查看镜像、配置 Docker 镜像加速源、管理 firewalld/ufw 防火墙规则、切换 apt 软件源，并探测常见开发工具或通过 apt 一键安装", "fileops", 0, "remote"),
        E("dsh-remote-status", "dsh-remote-status", "侧边栏底部状态芯片：跟随当前显示的会话显示「本地」或「远程 · 机器名」，悬停显示诊断信息，绝不改动工作区标题。", "session", 0, "remote"),
        E("dsh-remote-workstation", "dsh-remote-workstation", "给 DeepSeek Harness 用的远程工作区：在侧栏选 SSH 主机，通过 SFTP 把服务器目录挂载成工作区，随后用普通文件工具直接读写远端文件；远端 watch 用轮询实现（文件树自动刷新），图片/二进制预览走字节区间读取，remote_exec / remote_search / re", "image", 0, "remote"),
        E("dsh-remote-x", "dsh-remote-x", "DeepSeek Harness 的远程控制与移动端覆盖层：局域网与公网（cloudflared）隧道 + 二维码接入、768px 以下的手机端界面，附局域网反向代理 CLI。", "codec", 0, "remote"),
        E("dsh-reverse-proxy-xc", "dsh-reverse-proxy-xc", "DSH 局域网反向代理插件 - 让手机/平板访问 DSH 获得完整功能，修复反代访问时设置面板无法打开的问题。", "net", 0, "remote"),
        E("dsh-rfiles", "dsh-rfiles", "为 DSH Web GUI 增加带进度与续传的分块上传，以及工作区文件与会话日志 ZIP 的原生下载；通过配对远程链接访问的会话同样可用。", "archive", 0, "remote"),
        E("dsh-sakurafrp", "dsh-sakurafrp", "在 DSH 界面里管理 SakuraFrp 手机与电脑互通的插件：链路状态、移动网关开关、一次性配对二维码、设备撤销与网关自愈。", "codec", 0, "remote"),
        E("dsh-server-box", "dsh-server-box", "DSH 服务器面板：每台主机展示在线状态、CPU/内存/磁盘/网速与趋势图，点卡片进入 xterm.js 终端并支持 SFTP 上传下载；提供 server_box_hosts、server_box_exec、server_box_upload、server_box_download 对话工具，可导", "net", 0, "remote"),
        E("dsh-share-webui", "dsh-share-webui", "把当前实例的 Web 界面固定在一个端口上共享，支持设备配对与 Cloudflare Access 校验。", "net", 0, "remote"),
        E("dsh-simple-remote", "dsh-simple-remote", "只用一个插件就可以手机访问 DSH——需本机与手机都装好并连上 Tailscale，没有额外设置。", "misc", 0, "remote"),
        E("dsh-ssh-agent-workspace", "dsh-ssh-agent-workspace", "基于常驻 Python RPC 代理的实时远程 SSH 工作区插件，支持远程执行命令与 Glob/Grep 搜索、SSH 端口转发、~/.ssh/config 一键导入、跳板机链及三方缓存同步。", "net", 0, "remote"),
        E("dsh-ssh-hub", "dsh-ssh-hub", "DSH Web GUI 多服务器 SSH 终端面板：浮动终端窗口支持标签页、并排组合、广播、宿主侧持久会话，以及密码/私钥/SSH Agent 认证。", "session", 0, "remote"),
        E("dsh-ssh-manage", "dsh-ssh-manage", "DSH 的 SSH 主机管理插件：浏览 ~/.ssh/config，保存 AES-256-GCM 加密密码，执行批量命令与 SFTP，并在可保持的侧边栏标签页中打开交互式 PTY 终端。", "codec", 0, "remote"),
        E("dsh-ssh-vault", "dsh-ssh-vault", "把 SSH 主机存进 AES-256-GCM 加密保险库，智能体按别名执行命令，口令经 SSH_ASKPASS 交给 ssh 而不进入命令行。仅支持 Windows。", "codec", 0, "remote"),
        E("dsh-ssh-workspace-2", "dsh-ssh-workspace", "面向 Linux/macOS 的 SSH 工作区，支持导入 SSH config、选择远端目录，文件工具、Bash 与持久远程终端沿用 DSH 原生会话权限。", "fileops", 0, "remote"),
        E("dsh-streaming-mcp-bridge", "dsh-streaming-mcp-bridge", "DeepSeek Harness 流式 MCP 桥接：将实时会话事件作为 MCP 进度输出，并提供 cc-connect/飞书 ACP 适配器。", "session", 0, "remote"),
        E("dsh-sync-1", "dsh-sync", "通过用户自行配置的私有 HTTPS Git 仓库或 SFTP 同步 DSH 会话、设置、附件及工程文件，支持安全范围在线应用、离线恢复计划和经确认的插件更新。需 Node.js 24+；SFTP 路径还需 OpenSSH（ssh/sftp）。", "git", 0, "remote"),
        E("dsh-tunnel-preview", "dsh-tunnel-preview", "通过 Cloudflare Tunnel 将本地监听端口暴露为公网 HTTPS 预览链接，支持自动管理 DNS 记录与一键模板创建 API Token。", "net", 0, "remote"),
        E("dsh-vscode-connect", "dsh-vscode-connect", "把 DSH 和 VS Code 连接起来，提供类似 Claude Code for VS Code 的使用体验，直接在 VS Code 中接续同一工作区与同一会话：下载 VS Code 扩展 DSH Coding Agent，插件在 Windows 同机会自动发现并连接，其他平台可复制连接地址后手动", "net", 0, "remote"),
        E("dsh-web-url-view", "dsh-web-url-view", "在设置页新增「查看 URL」：显示当前会话的临时访问地址，以及一个长期不变、局域网内其他设备也能直接打开的固定地址。", "session", 0, "remote"),
        E("dsh-wechat-share", "dsh-wechat-share", "把微信聊天记录转发进 DSH 会话：Windows 分享目标接收合并转发的 ZIP，GUI 浮层选择目标工作区与会话，ZIP 以文件附件用户消息到达，agent 解压并读取。按魔数纠正媒体扩展名（微信常把 PNG/HEIC 字节命名为 .jpg），投递失败时批次保留可重试。需 Windows 10/", "image", 0, "remote"),
        E("dsh-winrm-1", "dsh-winrm", "andyfan1094/dsh-winrm 的 Node.js 分支：同样的 WinRM 主机面板与七个 agent 工具，后端从 Python/pywinrm 移植到原生 Node WinRM 客户端，运行 dsh 的机器不再需要 Python。", "git", 0, "remote"),
        E("dshb", "dshb", "为 DSH 提供多节点执行路由，将文件系统、Shell、子进程和 PTY 操作分发到本地、SSH 与 Docker 执行节点，并包含节点注册表、认证门禁、移动端管理 UI，以及可注入新对话的工作区自定义项目指令。", "sysinfo", 0, "remote"),
        E("dshm-plugin", "dshm-plugin", "将 DSHM 安卓客户端连接到电脑上的 DeepSeek Harness 会话，支持远程续聊、模型切换、审批、设备配对与撤销。", "session", 0, "remote"),
        E("harness-mate-dsh", "harness-mate-dsh", "把跑在本机的 DeepSeek Harness 智能体接入 HarnessMate 平台：手机 / 浏览器即可对话、收发文件、审批工具调用。", "fileops", 0, "remote"),
        E("local-commander-plugins", "local-commander-plugins", "通过 mcp-remote 把 DeepSeek Harness 接到 localcmd.app 上托管的 Local Commander MCP 服务（浏览器登录），在你的 Windows 电脑上读文件、查 Git、执行你批准的检查并探测本地服务。需 Local Commander 账号，且配对的", "git", 0, "remote"),
        E("pocket-bridge", "pocket-bridge", "在 DSH 设置里为 Pocket Bridge 提供本机手机配对、网关控制与诊断面板。", "misc", 0, "remote"),
        E("remote-session-plugin", "remote-session-plugin", "在本机与远程 DSH 工作区和会话间切换，并支持插件同步；需要自备中继服务器。", "session", 0, "remote"),
        E("cloakpack", "dsh-cloak", "DeepSeek Harness 的上下文防火墙：成功的纯文本工具结果中的凭据在进入模型之前先变成不透明的 ⟦cloak:category:n⟧ 占位符，原值只保存在进程内存的 agent 级保险库中。36 类内置签名（与 cloakpack git pre-push 守卫共享同一引擎）、针对未知格", "git", 0, "security"),
        E("deep-seek-harness", "-deep-seek-harness", "中文进度规范与经用户确认的项目或全局记忆；遵循 DSH 完全权限，复用宿主自动审查，减少重复确认。", "session", 0, "security"),
        E("dsh-account-vault", "dsh-account-vault", "在浏览器本地加密保存账号凭据。", "codec", 0, "security"),
        E("dsh-agent-gate", "dsh-agent-gate", "DSH 工具调用的咨询式权限检查：风险分级、路径沙箱（allowed_roots 为空时一律拒绝）、每分钟调用限额与 JSONL 审计，通过 gate_check / gate_check_path / gate_policy 与 ctx.gate 提供——需由其他插件或提示主动调用，本身不拦截工具", "data", 0, "security"),
        E("dsh-agent-recycle-guard", "dsh-agent-recycle-guard", "把 Agent 提交的删除命令（PowerShell `Remove-Item` 及别名、Bash `rm`/`unlink`/`rmdir`、CMD `del`/`erase`/`rd`/`rmdir`）改写为 Windows、Linux、macOS 的系统回收站操作，执行脚本前尽力检查其中的同类", "git", 0, "security"),
        E("dsh-almazom-approve-escalate", "dsh-almazom-approve-escalate", "审批卡片上的「批准并升级」一键操作：既应答当前待批请求，又把当前会话切换到指定的权限预设。", "session", 0, "security"),
        E("dsh-approval-consult", "dsh-approval-consult", "审批等待期间，向执行 AI 提问，装了并启用 DSH 的自动审查插件时也可问自动审查 AI，问清风险与后果再决定；执行 AI 的回答会留在会话里。", "session", 0, "security"),
        E("dsh-approval-explainer", "dsh-approval-explainer", "为 DSH 的每一次提权审批弹窗加一份由模型生成的注释：这段代码做什么、模型想达成什么、风险多大以及原因、每个选项意味着什么；并提供 /dsh-approval/history 历史授权查询（可搜索、可筛选、记录当时选了什么）与 /dsh-approval/diag 诊断页。", "search", 0, "security"),
        E("dsh-approval-review", "dsh-approval-review", "新增「替我审批」访问模式：审批请求由独立的复核模型裁决而非人工，复核者可只读工作区，复核跑不起来时把请求交回人工，每次裁决的理由记录在「审批」页签中。", "ai", 0, "security"),
        E("dsh-attest-chain", "dsh-attest-chain", "会话签名监护链：被监视的工具结果逐条追加哈希链 ed25519 签名记录，commit 绑定进链——篡改任意行或截断尾部都会在确定性重放校验中失败。", "git", 0, "security"),
        E("dsh-audit", "dsh-audit", "审计 DeepSeek Harness 插件：安装前只读扫描并按 S–D 分级；装好后记录插件启停、敏感工具调用与每个插件的 token 估算，全部收在一个设置面板里。", "ai", 0, "security"),
        E("dsh-auto-approval-frame", "dsh-auto-approval-frame", "DSH 工具调用的审批框架：一张四档规则表（拒绝／问人／AI 评审／放行）按工具、命令、文件与网络作用面逐条匹配，之后是 AI 快评与深评、人工审批，并带哈希链审计台账和设置页。目标文件只查元数据、不打开文件正文；评审端看到的是命令、目标与裁剪后的写入内容，发出前先做敏感信息脱敏。", "codec", 0, "security"),
        E("dsh-auto-pass", "dsh-auto-pass", "延续 simon300000/dsh-auto 的 DSH WebUI 自动审批权限档位：每次审批只走一次单轮模型审查、不再起审查子代理，只自动放行审查通过的动作、其余全部转回人工审批；并会把用户确认过的决定记成项目级与全局级的允许/拒绝名单，右侧栏另有审批时间线。", "net", 0, "security"),
        E("dsh-auto-preset-guard", "dsh-auto-preset-guard", "让「自动审批」熬过重启：应用退出时，自动审查的卸载迁移不再把在用的自动审批会话改写成「完全权限」；集成缺席时，存留的自动审批会话也不会打不开。", "session", 0, "security"),
        E("dsh-auto-review", "dsh-auto-review", "为 DSH 工具调用提供 Auto-review 和 Approve for me 模式。", "misc", 0, "security"),
        E("dsh-auto-review-default", "dsh-auto-review-default", "让会话进入内置的 Auto review 权限预设：新建会话在创建时进入，已有的根会话在重新打开时切过去。", "session", 0, "security"),
        E("dsh-brain-kit", "dsh-brain-kit", "给 AI 编程戴上安全帽：L0 到 L2 分级拦截，把越权操作关进笼子——权限不够就不落盘，改给你一段可直接粘贴的替换稿；路径过两道闸，junction 逃逸也拦得住。", "fileops", 0, "security"),
        E("dsh-chatlock", "dsh-chatlock", "给 DeepSeek Harness 的会话加密码锁，并把目录整体加密成保险箱。", "codec", 0, "security"),
        E("dsh-code-runtime-container", "dsh-code-runtime-container", "`ctx.codeRuntime` seam 的容器隔离后端：每个 Code Mode 程序跑在全新容器里，无网络、根文件系统只读、丢弃全部 capability，内存/CPU/进程数上限由内核强制。", "sysinfo", 0, "security"),
        E("dsh-compaction-guard", "dsh-compaction-guard", "压缩监护：从被压缩范围提取指令行（never/must/必须 类标记），对照摘要做逐字或内容词覆盖存续校验；会话悄悄遗忘的约束会被响亮上报并写入 JSONL 台账；配置中的 pinned 约束每次压缩必验。", "data", 0, "security"),
        E("dsh-completion-guard", "dsh-completion-guard", "避免 DSH Agent 在长任务中忘记你的要求：它会把重要条件和完成依据保存在本机，在上下文压缩或恢复会话后重新带回，防止漏掉关键限制，或只做完一部分就说整个任务已经完成。", "archive", 0, "security"),
        E("dsh-credentials-vault", "dsh-credentials-vault", "凭证 seam 的 HashiCorp Vault 后端：支持 KV v2/v1、AppRole 机器认证、逐次操作读取（轮换无需重启）与 compare-and-swap 写入。", "image", 0, "security"),
        E("dsh-danger-guard", "dsh-danger-guard", "执行前拦截：`tools.guard` 谓词按当前权限档位，对危险 shell 命令（跳过 git 钩子、灾难性 `rm`、下载即执行、重写 git 历史）与「写凭据路径」「没读过目标文件的首次编辑」逐条给出放行 / 询问 / 拒绝，并把成因与可行替代写法交回模型。", "git", 0, "security"),
    ]

    private static let chunk9: [ExternalPlugin] = [
        E("dsh-edit-guardian", "dsh-edit-guardian", "文件修改 diff 栏与保留/撤销汇总，以及对 bash/pwsh 危险命令的审批与标红。", "fileops", 0, "security"),
        E("dsh-egress-gate", "dsh-egress-gate", "确定性网络出口门：网页抓取与搜索在 tools/pre-execute 按目的地白名单校验，越权即拒；shell 抓取动词默认观察，可选拦截。", "net", 0, "security"),
        E("dsh-freeze", "dsh-freeze", "密闭组合锁：对 profile 的依赖、组合顺序、锁文件与补丁层取指纹；组合漂移时启动告警，strict 模式直接失败（CI 的 --frozen 姿态）。", "fileops", 0, "security"),
        E("dsh-gov", "dsh-gov", "Agent 治理套件：基于策略的工具门禁（allow/deny/ask，支持通配符与优先级）、结构化 JSONL 审计日志、基于宿主 token 计量的按 agent 配额，状态存于 $DSH_HOME/gov。", "data", 0, "security"),
        E("dsh-honey-guard", "dsh-honey-guard", "在密钥离开本机前，将其确定性地替换为结构合法的蜜罐假值（OpenAI、AWS、GitHub、PEM、Bearer 模式）；支持手动标记检测器认不出的值、用户可见的显式还原、蜜罐跨会话出现时的金丝雀告警，以及可选的 JSONL 替换计数日志（只记来源与类别计数，绝不记录真实值）。", "data", 0, "security"),
        E("dsh-info-records", "dsh-info-records", "本机加密的 DeepSeek Harness 账密库：侧边栏管理记录，智能体登录前按站点取用；对话收录默认关闭，逐条可设仅手动；AES-256-GCM 加密，密钥由 Windows DPAPI / macOS 钥匙串 / Linux Secret Service 保护。", "codec", 0, "security"),
        E("dsh-jumpserver", "dsh-jumpserver", "通过对话查询与管理 JumpServer：资产、用户、账号、授权、会话、命令审计、命令过滤与 RBAC 角色，使用 AccessKeyID/AccessKeySecret（HTTP 签名）鉴权。", "session", 0, "security"),
        E("dsh-keychain-credentials", "dsh-keychain-credentials", "纯 JavaScript 实现的 macOS Keychain 凭据提供器，替换 DeepSeek Harness 的明文 .credentials.yaml 存储，完整支持 refs 和 records，无需原生构建、代码签名或 Xcode。", "data", 0, "security"),
        E("dsh-lan-pass", "dsh-lan-pass", "Web UI 局域网密码门禁：同网手机/平板输共享密钥登录，会话与电脑实时同步，内置 randomUUID polyfill。", "session", 0, "security"),
        E("dsh-leak-guard", "dsh-leak-guard", "发布前凭据审计：在你提交、发布或打包外发之前，遍历目录找出里面的 API key、令牌、私钥、数据库连接串和硬编码密码。零依赖、纯本地、不联网，发现结果脱敏到前 6 个字符。", "git", 0, "security"),
        E("dsh-lifecycle", "dsh-lifecycle", "锁屏、密码／OTP／Passkey、持久化登录与自定义壁纸，支持 Linux/macOS 的 Harness 电源管理（需安装随包提供的 systemd/launchd 服务）及 npm 更新；Windows 为实验支持，暂未实机验证。认证内核改编自 xbzbing/dsh-auth-gateway", "devops", 0, "security"),
        E("dsh-loose-review", "dsh-loose-review", "破坏性 shell 命令执行前由模型判断会不会造成不可逆破坏，判定会破坏时询问或拦下；命令运行中删除文件过多时中止。", "fileops", 0, "security"),
        E("dsh-mcp-test", "dsh-mcp-test", "工具面快照与漂移门：全量可见工具注册表（含 MCP 工具）基线化为可提交的 JSON，升级新增、移除或改动工具时响亮告警。", "git", 0, "security"),
        E("dsh-ollama-tool-guard", "dsh-ollama-tool-guard", "每次工具调用前由本机 Ollama 决策模型判定：可疑调用升级为确认提示，模型不可达时停止所有调用。需 DSH 0.2.x，并先装好本机 Ollama 0.35.1+、拉取默认约 6 GB 的 clef-flash 模型；否则所有工具调用都会被拒绝。", "ai", 0, "security"),
        E("dsh-pairing-gate", "dsh-pairing-gate", "DeepSeek Harness 的设备配对网关：默认只监听 127.0.0.1:3443（明文 HTTP）并把请求反代到本机 http://127.0.0.1:3080，本机安装无需证书即可使用。生产/跨机/App 配对必须配置 TLS 证书（自签即可）与 https 的 publicUrl；若在", "net", 0, "security"),
        E("dsh-phocinae-1", "dsh-phocinae", "DSH 本地决策层插件：失败关闭的命令审批门，以及由 144.3M 端侧模型支撑的 ask/gate 工具。需另装本地决策服务：`pip install phocinae-server` 后下载约 330MB 权重并常驻运行；服务不在时工具会返回 `PHOCINAE_SERVICE_UNAVAILA", "net", 0, "security"),
        E("dsh-plugin-content-policy", "dsh-plugin-content-policy", "工具结果的预防式内容策略：改写命中文本，并按字段路径整段丢弃或截断，让未经审查的载荷在结果被规范化/渲染/落盘之前就进不去。随包为真空操作，不含任何内置的类别或域名黑名单。", "data", 0, "security"),
        E("dsh-plugin-guard", "dsh-plugin-guard", "DSH Desktop 插件安全防护：崩溃后自我修复 + 8 项核心安全检查（另有 2 项可选：深度组合校验、业务冒烟），写完插件自动提示。非商业源可用。", "misc", 0, "security"),
        E("dsh-plugin-guard-tool", "dsh-guard-tool", "注册一个 agent 工具 plugin_guard，在安装前对 DSH 插件包做静态扫描，给出判定与原因：缺少或损坏的 dsh.bundle.patch、未声明 dsh.permissions、安装脚本、危险 API 与代码混淆、依赖风险，以及未索引、无法核验的源码。只读：不导入、不安装、不求值、", "ai", 0, "security"),
        E("dsh-plugin-judge", "dsh-plugin-judge", "插件价值裁判：装前审核（源码静态扫描 + LLM 裁判）与装后审计已装插件，模型切换时弹窗提醒复核；判断插件对当前模型是增强还是压制。", "ai", 0, "security"),
        E("dsh-plugin-notoken", "dsh-plugin-notoken", "！警告！这会移除认证步骤！警告！注册一个登录入口路由（默认 GET /__dsh_login），把进程里的登录 token 换成浏览器会话 cookie，让首次访问不用带 ?token=…。", "sysinfo", 0, "security"),
        E("dsh-plugin-redact", "dsh-plugin-redact", "会话日志的原地脱敏与按行回退：守住「每行 seq 必须等于它的行号」这一不变式（删中间行会让整份日志打不开）。任何写入前先把原文复制成隔离备份，并以读取端自身的语义作为写前闸门。", "session", 0, "security"),
        E("dsh-plugin-trust-audit", "dsh-plugin-trust-audit", "只读审计 DSH 插件的 HTTP 路由是否真的做了鉴权栅栏：读插件代码找出真正注册的路由，仅对回环地址发起探测。", "misc", 0, "security"),
        E("dsh-plugin-vajraclaw", "dsh-dros-vajraclaw", "DSH 本機工具調用防護外掛：攔截高風險 Shell 指令模式與敏感憑證讀取，具備持久化哈希鏈 JSONL 審計記錄，可選配外部 Gateway 集中治理。", "codec", 0, "security"),
        E("dsh-pr-gate", "dsh-pr-gate", "确定性写入门禁：范围策略在落盘前拒绝越权写入，残留规则扫描所写文本，每个决定落入带内容哈希的 JSONL 台账；可复用仓库的 agent-pr-gate.yaml 让 CI 与会话共用同一策略。", "git", 0, "security"),
        E("dsh-preclaim", "dsh-evidence", "提交前声明门：把“测试通过”等 commit/push/tag 声明与本次会话的真实执行证据核对后再写入。", "git", 0, "security"),
        E("dsh-privacy-gateway", "dsh-privacy-gateway", "在对话消息发给模型前，把个人信息替换为占位符（按上下文识别的中文姓名、大陆手机号与身份证号、邮箱、银行卡号，以及用户词库中的词），原文只在本机界面还原显示；并可生成 CSV/XLSX 的脱敏副本。", "data", 0, "security"),
        E("dsh-privacy-gateway-1", "dsh-privacy-gateway", "在宿主进程的 undici dispatcher 上拦截所有发往模型的请求：密钥、Cookie 与个人信息换成占位符，回复里再还原，一处拦截覆盖所有 provider（含插件自带的 adapter）；按 kind 可选 mask / warn / block、可换成同形的假 key，记录按天落盘并带", "sysinfo", 0, "security"),
        E("dsh-privacy-guard", "dsh-privacy-guard", "DeepSeek Harness 本地凭据脱敏网关的控制面板：网关与小模型健康状态、审计指标、泄密探测沙箱、豁免白名单、加密密钥管理、凭据保护模型入口与部署控制。", "codec", 0, "security"),
        E("dsh-privacy-shield", "dsh-privacy-shield", "请求离开本机前，把 system/developer/user/assistant/tool 五类消息的模型可见副本改写为稳定 HMAC 占位符；本地会话日志、对话记录与还原后的工具调用仍保留真值。", "session", 0, "security"),
        E("dsh-prompt-drift", "dsh-prompt-drift", "系统提示词面漂移门：任何插件或预设注入组装提示词的段落均哈希基线化，对模型被告知内容的静默改写将响亮报错。", "codec", 0, "security"),
        E("dsh-push-privacy-guard", "dsh-push-privacy-guard", "DSH 提交/推送前隐私检查：在 git commit、git push、gh repo sync 前只读扫描将要进入 git 的内容（本地路径、用户信息、API Key、私钥、连接串等），未授权内容不会上传；命中时通过 DSH 审批面板授权，授权项进入可管理的掩码白名单。支持原生 DSH Conf", "git", 0, "security"),
        E("dsh-re-workbench", "dsh-re-workbench", "逆向分析工作台：通过 @deepseek-ai/dsh-mcp-client 把本机 IDA Pro 桥接进 DSH，将 ida-pro-mcp 工具集（反编译、xref、重命名、注释）以 mcp__ida__* 注册给模型。自动选择 idalib 无头模式（进程内分析二进制，无需打开 IDA GU", "sysinfo", 0, "security"),
        E("dsh-read-guard", "dsh-read-guard", "确定性注入拦截：文件读取、仓库搜索与网络抓取的工具结果在进入模型上下文前被扫描；高危发现隔离包裹或阻断，凭证类文件按路径即隔离。", "git", 0, "security"),
        E("dsh-recycle-bin-1", "dsh-recycle-bin", "把删除的文件送进 Windows 回收站，可按 id 列出与还原，并拦截 shell 通道的永久删除。", "fileops", 0, "security"),
        E("dsh-redact", "dsh-redact", "把会话或文档里的密钥、本机路径、内网 IP、邮箱和手机号打码，再分享或提交。", "git", 0, "security"),
        E("dsh-rice-guard", "dsh-rice-guard", "同时监视一轮对话的思考流与正文流，模型开始复读时中断该轮。四条检测规则：逐字周期重复、每行只换数字的计数循环、被其他文字隔开的重复行，以及用户自填的短语清单。命中后在全球浮层弹出必须手动关闭的报警卡（可带提示音），「监控」标签页里有开关、阈值与命中历史。检测是本机字符串比对、不调用模型，零 toke", "sysinfo", 0, "security"),
        E("dsh-risk-gate", "dsh-risk-gate", "语义风险分级与渐进授权：把工具调用分为安全／有风险／红线三档，不可逆操作前先询问，只对「已批准且曾成功」的签名自动放行。", "misc", 0, "security"),
        E("dsh-risk-guard", "dsh-risk-guard", "零打扰审计与保险丝拦截：静默记录每次工具调用并做纯规则风险评分（含累积加分、风险等级分布、归档保留期清理），只拦不可逆灾难（受保护路径删除、磁盘擦除、force push 到受保护分支/引用、凭据外发），/risk-guard 输出脱敏操作账单并支持 --since 时间过滤。", "git", 0, "security"),
        E("dsh-route-fence-linter", "dsh-route-fence-linter", "审计 profile 内所有插件 HTTP 路由的浏览器信任围栏：插件路由在 Web 服务器的最长前缀匹配中优先，因此缺少围栏的路由会被静默暴露；逐条给出文件与行号级别的证据。", "fileops", 0, "security"),
        E("dsh-safe-delete", "dsh-safe-delete", "工具守卫将 agent 执行的 rm 目标移入 macOS 废纸篓而非直接删除，shell 感知词法器覆盖复合与伪装命令；设置页通用设置中可随时关闭。", "ai", 0, "security"),
        E("dsh-sandbox-arg-guard", "dsh-sandbox-arg-guard", "让「同级或更窄的 sandbox_permissions」不再让工具调用直接失败。会升级的工具（pwsh、bash、write、edit）都广告完整的 sandbox_permissions 枚举，但 DSH 只接受严格更宽于当前生效级别的请求——其源码自称这是「deliberately not a", "misc", 0, "security"),
        E("dsh-sandbox-noop-escalation", "dsh-sandbox-noop-escalation", "去掉那些不会让当前沙箱模式变宽的 sandbox_permissions / justification 参数，避免调用报错「sandbox escalation to \"workspace-write\" is not strictly wider than this call's current", "misc", 0, "security"),
        E("dsh-sandboxie-redirect", "dsh-sandboxie-redirect", "写时复制权限预设：shell 命令在工作区专属的 Sandboxie 沙盒内运行，工作区外的写入落进沙盒副本、真实磁盘不受影响（仅 Windows，需先安装 Sandboxie-Plus）。", "sysinfo", 0, "security"),
        E("dsh-secret-vault", "dsh-secret-vault", "把密钥和个人信息交给 agent，却不进入它的上下文；带校验位的字段抽取与掩码内容分类。", "data", 0, "security"),
        E("dsh-security-guard-1", "dsh-security-guard", "DSH 运行时安全守卫：配置加载导入约束、HTTP Host 头校验、附带 VM 沙箱逃逸源码补丁（4 个 CVE）。AI 辅助制作。", "misc", 0, "security"),
        E("dsh-security-guard-2", "dsh-security-guard", "DSH 插件安全卫士：28 条规则静态扫描、风险评分、白名单/黑名单、本地 Web 仪表盘与 DSH 内风险弹窗。", "misc", 0, "security"),
        E("dsh-security-judge", "dsh-security-judge", "代码安全防御规则评审判官：自动识别正在做代码的会话，按《代码安全防御架构规则》强制评审其安全防御措施与所采用的代码安全防御架构，推荐程序需要的架构（一种或多种）并检查架构之间是否冲突；连续不合格会进入教学模式要求重做；在面板授予评审权限后，未通过评审的代码任务不能算完成（未授权时只读观察）。", "session", 0, "security"),
        E("dsh-shadow-auditor", "dsh-shadow-auditor", "DeepSeek Harness 的后台安全审计器：扫描 Agent 输出中的秘密泄漏，在执行前检查命令安全性，并将发现记录到持久化审计日志中。", "ai", 0, "security"),
        E("dsh-sovereign", "dsh-sovereign", "宿主面主权条款与内容守卫：在系统提示词末节注入「用户裁定」条款，清洗工具结果里的凭据与隐蔽载体，按可逆性前置拦截不可逆操作。对全部 agent preset 生效。", "text", 0, "security"),
        E("dsh-staging-guard", "dsh-staging-guard", "pre-execute 钩子：拒绝写入受保护根下只读的成果区，其余路径放行。", "fileops", 0, "security"),
        E("dsh-stop-that-shit", "dsh-stop-that-shit", "用 `$stop-that-shit` 指令显式开启每会话范围契约并逐个工具调用审计；未开启时不干预。基于 lennney/stop-that-shit（MIT）的 DSH 封装。不要与上游 lennney/stop-that-shit 的 DSH bundle 同时安装。", "session", 0, "security"),
        E("dsh-system-guard", "dsh-system-guard", "系统守护（以 Windows 为主，保护类操作走 UAC/sudo）：分析并分类系统核心文件与运行时垃圾，把核心文件隐藏备份到剩余空间最大的硬盘、定期巡查完整性并从备份修复损坏文件；守护权限只用于保护系统。macOS/Linux 上只做分类与哈希（不删垃圾，修复仅给出人工步骤），且该路径未在真机验证", "codec", 0, "security"),
        E("dsh-taintguard", "dsh-taintguard", "当工具结果包含不可信内容时将代理标记为已污染，对随后的高权限调用进行拦截，并在所有模式下拒绝将凭据传递给可联网的工具。", "net", 0, "security"),
        E("dsh-tm-guard", "dsh-tm-guard", "macOS 上 DSH 智能体的零干预权限门 —— 安装即生效。可经本地 Git 或时间机器回滚的写操作自动放行并自动打快照，拦截网络、装包、进程 / 系统管理与敏感路径读取，并记录完整审计日志（可配置启用自动清理最旧审计记录）。", "git", 0, "security"),
        E("dsh-totp", "dsh-totp", "面向个人 DeepSeek Harness Web 实例的纯 TOTP 访问验证，支持设置内扫码绑定、一次性恢复码、动态启停保护和撤销所有页面授权。", "misc", 0, "security"),
        E("dsh-trust-panel", "dsh-trust-panel", "信任面板：把 dsh 信任插件族九个通道（注入拦截、写拒绝、出网拦截、custody 链校验、工具面/系统提示词漂移、残留扫描、压缩遗忘约束、profile 组成）聚合成右侧栏一块仪表盘——一个状态灯 + 事件卡片，把引擎术语翻译成非安全背景用户能看懂并知道要不要处理的句子；read/egress", "archive", 0, "security"),
        E("dsh-uriauth", "dsh-uriauth", "开启后，在可配置的公开 URI（默认 /trustme）上把当前进程的 launch token 换成浏览器会话 cookie，首次访问无需在 URL 里带 ?token=。", "sysinfo", 0, "security"),
        E("dsh-warden", "dsh-warden", "工具调用的对抗式审查门。它挂在 `tools/pre-execute` 上：先用本地正则零延迟筛破坏性命令（`rm -rf`、`git push --force`、`git reset --hard`、`DROP TABLE`、`format`、写盘）和敏感路径（`.env`、`id_rsa`、`.", "git", 0, "security"),
        E("dsh-whale-guard", "dsh-whale-guard", "防呆插件：safe_kill 工具（自动排除自身与全部祖先进程链），bash 命令预检（pkill 自匹配、sudo -S 抢 stdin、rm -rf / 等），以及可扩展规则库（block / warn / hint 三档）。", "sysinfo", 0, "security"),
        E("dsh-whitelist-auto-approval", "dsh-whitelist-auto-approval", "按命令生效的 bash 沙箱白名单：一条规则指定一个命令和它可用的可写根，命中的 lark-cli、gh 等在保留工作区的前提下于内核沙箱内直接执行。与「替你回答授权弹窗」或「对所有命令统一放宽可写范围」的做法不同，这里放行的只有命中的那条命令，工作区仍可写，其他命令行为完全不变。匹配依据是命令的「", "misc", 0, "security"),
        E("dsh-workspace-only-plugin", "dsh-workspace-only-plugin", "把任何沙箱模式（read-only / workspace-write / danger-full-access / auto）下代理的文件访问限制在会话工作区内，越界访问一律请用户裁决；每个会话还能用 composer 旁的档位选择框把越界门禁放宽为「工作区外只读」或「完全放开」。", "net", 0, "security"),
        E("dsh-workspace-tools", "dsh-workspace-tools", "按工作区规则为新建根会话自动应用 Agent 预设与权限预设（设置 - 工作区默认设置），仅使用官方扩展点。", "session", 0, "security"),
        E("faultseed", "dsh", "工具流水线上的诚实性护栏：阻止编码 agent 弱化测试、吞掉错误、用桩替换类型检查或通过 shell 删除测试——九个确定性 hook，每个都配有植入失败的测试，证明该护栏确实会触发。", "codec", 0, "security"),
        E("browser-automation", "browser-automation", "dsh 的真实浏览器自动化:基于 Playwright 的 MCP 服务,提供导航、点击、填写、输入、截图与带编号引用的无障碍快照操作,22 个 web_* 工具经 stdio 接入 Agent。", "image", 0, "browser"),
        E("dsh-academic-web-proxy", "dsh_academic_web_proxy", "按机构代理规则打开学术网站，可依据匹配的论文元数据重命名符合条件的新 PDF，并提供简体中文、繁体中文及美式英语设置界面。", "pdfdoc", 0, "browser"),
        E("dsh-bing-search", "dsh-bing-search", "godchen520/dsh-web-search-bing 的维护 fork，适配 DSH 0.1.5-rc.1：为内置 web_search 工具提供 Bing 搜索源，直接解析 cn.bing.com 公开 HTML 结果页，无需 API Key，国内可直连，不消耗模型自带搜索额度。端点与结果", "search", 0, "browser"),
        E("dsh-browser-1", "dsh-browser", "通过带命名空间的 MCP 工具和任务空间 Skill 接入已发布的 BeatBrowser；需要 Chrome 扩展，保留人工接管规则。", "ai", 0, "browser"),
        E("dsh-browser-4", "dsh-browser", "内置浏览器：给 Agent 一个真实的有头 Chromium，可打开网页并点击、输入、滚动，页面状态在多次调用之间保持。", "ai", 0, "browser"),
        E("dsh-browser-5", "dsh-browser", "DeepSeek Harness 的受控浏览器自动化：agent_browser 工具与 BrowserAutomationService 通过 agent-browser CLI 驱动真实 Chromium / Chrome 页面（或指定 CDP 端点），支持 allowedDomains 域名收", "ai", 0, "browser"),
        E("dsh-browser-bridge", "dsh-browser-bridge", "操控已经打开的 Edge 或 Chrome 窗口，不重启也不关闭它：一次选定窗口、已打开的网址直接复用标签页、读页面文本或 DOM 状态、按可访问名或可见文字点击、输入、滚动、等待内容、多步合批。22 个工具，基于 UI Automation、SendInput 与可选的篡改猴桥。仅 Windows", "misc", 0, "browser"),
        E("dsh-browser-mode", "dsh-browser-mode", "新增「浏览器操作」Agent 预设（基于 Playwright MCP 工具集的导航、填表、点击与截图规程），并加门禁：其他预设里的浏览器工具调用一律拒绝，直到用户通过内置的 browser_access 工具授权该会话。插件自带 Playwright MCP provider，插件页的设置页与 b", "image", 0, "browser"),
        E("dsh-browser-ops", "dsh-browser-ops", "DeepSeek Harness 真实浏览器自动化：agent 可直接驱动真实 Chrome（独立托管档案，或附加日常 Chrome/CDP），提供页面快照、点击、填表、读表与控制台/网络诊断工具；可将手动操作录制成流程并把输入标记为变量槽，按参数自动重放来批量造测试数据；附带 27 个 brows", "ai", 0, "browser"),
        E("dsh-browser-relay", "dsh-browser-relay", "DSH 与浏览器之间的通信桥：浏览器扩展发起的任务经 relay 在 DSH 创建会话执行，页面操作通过 browser_* 工具桥接回扩展，提供页面助手面板与免配置接入向导。", "session", 0, "browser"),
        E("dsh-browser-service", "dsh-browser-service", "为 DSH 挂出完整的浏览器工具面（33 个 browser_* 工具）：把 ctx.browser 接缝接到自管的 headless Chromium（经 127.0.0.1 单例 CDP 守护进程，带 Bearer token 鉴权、请求路径白名单与 WebSocket 地址改写，不需要 roo", "sysinfo", 0, "browser"),
        E("dsh-browser-tabs", "dsh-browser-tabs", "DSH 浏览器标签页管家：超过可配置上限时，按空白页、报错页、重复地址、最老页面的顺序关闭，正在用、刚打开和命中保留规则的页面不动；带设置页，可预演和手动清理。", "misc", 0, "browser"),
        E("dsh-browser-takeover", "dsh-browser-takeover", "浏览器网址接管：维护一份「要登录的网址」清单（只存网址与添加时间，不存账号密码），访问前先回答这条地址在不在清单里；按该站点的会话 cookie 名字判断调试浏览器此刻是否已登录（确定／可能／未登录，_gh_sess 这类匿名 cookie 不计），在带调试端口的浏览器里打开清单中的地址，并按可见文", "net", 0, "browser"),
        E("dsh-bug-gps", "dsh-bug-gps", "录制浏览器问题、固定预期，并通过独立原代码对照复核修复。", "misc", 0, "browser"),
        E("dsh-chrome-attach", "dsh-chrome-attach", "把当前 Chrome 标签页附到 DSH 草稿：一次点击截图（失败时降级为 macOS 窗口截图），同时把页面标题与地址写成一行放进输入框。", "image", 0, "browser"),
        E("dsh-codex-cua", "dsh-codex-cua", "安装 codex-cua 技能，让 DeepSeek Harness 使用 Codex computer use：通过 ChatGPT/Codex 桌面端自带的运行时操作 Chrome 与 macOS 原生应用，自带常驻会话客户端与 doctor 自检。需已装 ChatGPT/Codex 桌面端及", "session", 0, "browser"),
        E("dsh-connectors-2", "browser-connector", "浏览器自动化连接器：用 DevTools 协议直接驱动本机 Edge/Chrome，零运行时依赖——可启动无头的一次性 profile 浏览器，也可接管用 --remote-debugging-port 启动的浏览器；通过 11 个工具完成打开页面、读取正文与可交互元素、点击、填表与截图。", "image", 0, "browser"),
        E("dsh-deepseek-search-account", "dsh-deepseek-search-account", "为聊天模型走第三方订阅或网关（例如 OpenCode Go）的 DeepSeek Harness 会话提供基于已登录 DeepSeek 账号的网页搜索与抓取：注册 deepseek-account-search 和 deepseek-account-fetch 两个提供方，用账号 token 调用官", "codec", 0, "browser"),
        E("dsh-dots", "dsh-dots", "在 DSH 全幅页面使用 ChatGPT Dots，支持 Desktop 启动预加载与同次运行内的页面切换保留、中英文主题工具栏、刷新及外部浏览器回退，并提供需单独应用、适用于 Windows DSH 0.2.1-rc.3 的登录态持久化配套工具。升级至DSH 0.2.1-rc.5后，Dots内嵌页", "misc", 0, "browser"),
        E("dsh-dragon-control", "dsh-dragon-control", "仅支持 Windows x64，0.5.4 预览版：两个受控工具（dragon_browser 与 dragon_desktop），网页走 DOM/CDP、桌面走 Windows UI Automation，按网站来源和可执行文件分 read/control 权限，支持多步 batch、物理 Esc", "fileops", 0, "browser"),
        E("dsh-ego-webqa", "dsh-ego-webqa", "把 ego-webqa 的 MCP 审计服务接入 DSH，在移动端视口矩阵中检查已部署页面并返回结构化修复证据；前置需要在同一台机器上装好 uv/uvx 与 Playwright Chromium 无头运行时。", "devops", 0, "browser"),
        E("dsh-element-lens", "dsh-element-lens", "在右侧栏浏览器里拾取元素，把它的选择器、计算样式与 HTML 以可逐条删除的胶囊插入对话草稿。", "session", 0, "browser"),
        E("dsh-erp", "dsh-erp", "通过浏览器学习 ERP 并沉淀为私有本地知识；桌面端提供「ERP 助手」工作区（多站点会话、中对话+右浏览器、写入前审批）。", "session", 0, "browser"),
        E("dsh-exa", "dsh-exa", "基于 Exa 的 DSH 网页搜索与抓取插件：完全接管内置网络检索，并提供多源深度调研工具。", "net", 0, "browser"),
        E("dsh-free-search-lite", "dsh-free-search-lite", "两个原生工具，提供基于 360、Bing RSS 和 DuckDuckGo 的免 API Key 中英文搜索与静态网页正文读取，无需浏览器、Python 或 MCP 子进程。", "sysinfo", 0, "browser"),
        E("dsh-gui-auth-url", "dsh-gui-auth-url", "把当前 DSH Web GUI 的合法带 token 地址作为 agent 工具返回，浏览器自动化可直接打开 GUI，不再遇到 401。", "ai", 0, "browser"),
        E("dsh-html-inspector", "dsh-html-inspector", "HTML 选区模式：点选本机 demo 页面中的任意元素，定位信息（选择器、文本、HTML 片段）自动写入对话输入框，供 AI 精准修改。", "session", 0, "browser"),
        E("dsh-iab", "dsh-iab", "DSH 内置浏览器：独立 Chromium 配合持久化 profile，飞书或 SSO 登录一次跨重启有效，经 CDP 驱动，提供七个 Agent 工具（status、open、eval、read、feishu、screenshot、tabs），并把页面实时镜像到右侧栏面板——工具调用时面板会自动打", "fileops", 0, "browser"),
        E("dsh-inpage-translator", "dsh-inpage-translator", "给内置浏览器的每一张页面常驻一个「🈯 译」按钮：点一下，页面上每个可见文本节点原地换成译文；再点一下回到原文。长按可拖动，拖到左右边缘自动吸成贴边小把手；页面导航后自动重装。翻译走宿主模型服务 —— 插件不持有任何 API key。", "ai", 0, "browser"),
        E("dsh-jev-ultrafast", "dsh-jev-ultrafast", "给 DeepSeek Harness 一句话目标：决策服务从带编号的元素表里挑出下一步操作与目标元素，驱动真实浏览器把事办完，一趟多步任务只花一次工具调用。", "misc", 0, "browser"),
        E("dsh-keenable", "dsh-keenable", "为内置 web_search 与 web_fetch 工具提供 Keenable 网页搜索与网页读取，适用于任意模型，无需 API Key。", "search", 0, "browser"),
        E("dsh-opencli", "dsh-opencli", "把本机 OpenCLI daemon 当常驻服务直连的 DSH 浏览器工具，替代「每条命令起一次 opencli CLI」的冷启动：oc_status、oc_exec、oc_navigate、oc_snapshot、oc_tabs 五个工具，每个 session 一个常驻自动化标签页。需要本机运行", "misc", 0, "browser"),
        E("dsh-pilot-2", "dsh-pilot", "按无障碍 ref 操控浏览器：导航、把页面快照成 ref 树、操作元素、等待条件；域名策略跟随会话审批状态，并由请求拦截层强制执行。", "session", 0, "browser"),
        E("dsh-plugin-10", "dsh-plugin-specstream", "Registers the hosted SpecStream MCP server with the harness MCP manager and keeps the API key in the credential store. The server returns live web dat", "misc", 0, "browser"),
        E("dsh-plugin-browser", "dsh-plugin-browser", "DeepSeek Harness 原生无头及可视化 Chromium 浏览器自动化插件：支持 DOM 树提取、网页截图捕获及内置 SSRF 安全防护。", "image", 0, "browser"),
        E("dsh-plugin-prismsearch", "dsh", "打包 PrismSearch MCP 服务与配套 Agent Skill。网页搜索默认使用 Bing 和百度，无需账号或 API Key；设置 API Key 后可用 Google、Brave，在配置中启用后可用 DuckDuckGo、搜狗、360、Yandex；支持引擎自动回退与聚合模式。另提供图", "archive", 0, "browser"),
        E("dsh-plugins-15", "reference-library", "在原生 @ 引用菜单中提供 CodePen、Pinterest、Z-Library 与 GitHub 数据卡片，并支持 Pinterest 分页和 Z-Library 排序。", "archive", 0, "browser"),
        E("dsh-preview", "dsh-preview", "无头浏览器验证工具：让 agent 打开自己刚写的页面，读取渲染后的 DOM 与计算样式、检查控制台、截图留档；内置 frontend-verify 技能。", "image", 0, "browser"),
        E("dsh-proxy-failover", "dsh-proxy-failover", "把回环 HTTP 中继设为 DSH 的进程级代理路由，让 web_fetch 在 Mihomo/Clash TUN fake-ip 下正常出网；上游代理不可用时，同一请求内改走直连，1.5 秒探活发现代理恢复后自动切回。", "net", 0, "browser"),
