    private static func E(_ i: String, _ n: String, _ s: String,
                         _ k: String, _ st: Int, _ c: String) -> ExternalPlugin {
        ExternalPlugin(id: i, name: n, summary: s, capKey: k, stars: st, rawCategory: c)
    }

    // MARK: - 查询（2026-11-05：并入发现页后需要按分类计数与搜索）

    /// 某个分类下有多少条外部插件
    static func count(in c: PluginCategory) -> Int {
        all.reduce(0) { $0 + ($1.category == c ? 1 : 0) }
    }

    /// 按关键词 + 分类筛。kw 为空表示只看分类。
    ///
    /// 走的是简单 contains，没用正则或分词 —— 4687 条每敲一个字符跑一遍，
    /// 中文输入法连打时会卡。实测 contains 够快，够用。
    static func search(_ kw: String, category c: PluginCategory?) -> [ExternalPlugin] {
        let q = kw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return all.filter { e in
            if let c = c, e.category != c { return false }
            if q.isEmpty { return true }
            return e.name.lowercased().contains(q) || e.summary.lowercased().contains(q)
        }
    }
}
